/* =========================================================================
 * DS4 CUDA allocation tracer (diagnostic, env-gated by DS4_CUDA_ALLOC_TRACE)
 * =========================================================================
 *
 * Interrogating suspected consumers one at a time returned 0/5 on the ~3.2 GiB
 * of unattributed VRAM.  This wraps the allocator instead: every device,
 * managed, pinned-host and host-registered allocation in this translation unit
 * is routed through a tagged wrapper by the macros at the end of this block,
 * so no consumer can hide.  Whatever the wrappers do NOT see is, by
 * construction, not allocated by our code (driver context, module loads,
 * library-internal buffers) and is closed out against cudaMemGetInfo.
 *
 * Off by default: the wrappers forward directly and the accounting is skipped.
 */
enum {
    DS4_ALLOC_KIND_DEVICE = 0,      /* cudaMalloc            -> VRAM          */
    DS4_ALLOC_KIND_MANAGED = 1,     /* cudaMallocManaged     -> VRAM on WDDM  */
    DS4_ALLOC_KIND_HOST_PINNED = 2, /* cudaHostAlloc/Host    -> host RAM      */
    DS4_ALLOC_KIND_HOST_REG = 3,    /* cudaHostRegister      -> host RAM      */
    DS4_ALLOC_KIND_COUNT = 4
};

static const char *const g_alloc_kind_name[DS4_ALLOC_KIND_COUNT] = {
    "device", "managed", "hostpin", "hostreg"
};

/* VRAM-bearing kinds.  Managed memory counts: Windows/WDDM has no on-demand
 * migration, so a managed range is device-resident whenever a kernel runs. */
static int ds4_alloc_kind_is_vram(int kind) {
    return kind == DS4_ALLOC_KIND_DEVICE || kind == DS4_ALLOC_KIND_MANAGED;
}

/* =========================================================================
 * DS4 intra-token VRAM peak probe
 * (diagnostico, env-gated da DS4_CUDA_VRAM_PEAK_PROBE, default 0 = spento)
 * =========================================================================
 *
 * LA MISURA CHE MANCA.  La riga [vram-prio] campiona cudaMemGetInfo FRA un token
 * e l'altro e da' un valore costante (1083 MiB liberi, 0.00 MiB/token di deriva
 * su 15 campioni).  Eppure passare da 140 a 189 slot di cache esperti (+331 MiB)
 * fa collassare il decode da ~280 ms a ~2100 ms con ~1120 sfratti di backbone per
 * token.  Il costo non e' quindi un consumo che cresce fra i token: e' un PICCO di
 * occupazione DENTRO il singolo token che il campionamento inter-token non vede.
 *
 * PERCHE' IL PICCO ESISTE (letto dal codice, non ipotizzato).
 * cuda_model_stream_alloc() gira un ciclo: cudaMemGetInfo -> se
 * free >= aligned+reserve fa cudaMalloc; altrimenti cuda_stream_pool_reclaim()
 * (cudaFree di UN buffer parcheggiato); altrimenti sfratta una vittima con
 * cuda_model_range_evict_to_pool(), che NON libera VRAM ma PARCHEGGIA il buffer in
 * g_stream_pool.  L'occupazione oscilla quindi dentro il token (reclaim libera,
 * malloc riprende) e torna al punto di partenza a fine token: invisibile
 * dall'esterno, decisiva dall'interno.  g_stream_pool_bytes -- VRAM allocata e
 * parcheggiata, non usata da nessun range vivo -- e' la parte potenzialmente
 * comprimibile, e viene riportata nell'istante del minimo e come massimo del token.
 *
 * COME CAMPIONA -- scelta (a): agganciato ai punti di alloc/free GIA' esistenti.
 * Questa translation unit instrada OGNI cudaMalloc / cudaMallocManaged / cudaFree
 * attraverso i wrapper del tracciatore (macro in fondo al blocco successivo):
 * esiste gia' un unico collo di bottiglia per tutte le variazioni di occupazione.
 * Il probe si aggancia li':
 *   - subito DOPO una cudaMalloc/cudaMallocManaged riuscita (la VRAM libera e' al
 *     minimo locale esattamente dopo l'allocazione),
 *   - subito PRIMA di una cudaFree (la VRAM libera e' al minimo locale
 *     esattamente prima del rilascio).
 * Per costruzione questi due istanti sono gli estremi: fra un free e la malloc
 * successiva la VRAM libera non puo' scendere per opera di questo processo.
 * In piu' il ciclo di cuda_model_stream_alloc() chiama GIA' cudaMemGetInfo a ogni
 * iterazione: quel valore viene ingerito senza NESSUNA query aggiuntiva al driver,
 * ed e' proprio il ciclo caldo dello sfratto dove il picco si forma.
 * NON e' stato usato un thread di campionamento ad alta frequenza (opzione (b)):
 * sarebbe asincrono rispetto agli eventi da cogliere (un picco di poche decine di
 * microsecondi puo' cadere fra due campioni) e ruberebbe tempo CPU alla stessa
 * fase che sta misurando.
 *
 * COSTO.  Flag spento: una lettura di un int cachato per evento, nient'altro --
 * nessuna query al driver, nessun atomico toccato, nessuna riga emessa.
 * Flag acceso: una cudaMemGetInfo per alloc/free di device.  Il costo cumulato
 * NON e' stimato ma MISURATO (driver_queries / probe_ms nella riga di sintesi),
 * cosi' la regia puo' scontarlo dal tempo di decode.  DS4_CUDA_VRAM_PEAK_QUERY_EVERY
 * (default 1) permette di diradare le query al driver se il costo misurato
 * risultasse non trascurabile; i valori gia' noti dal ciclo di stream_alloc
 * restano ingeriti tutti, sempre, perche' non costano nulla.
 * ========================================================================= */

static double cuda_wall_sec(void);  /* definita piu' avanti in questo file */
static void ds4_transport_request_reset(void);

/* Contesto letto nell'istante del minimo.  g_stream_pool_bytes e
 * g_model_range_bytes sono definite molto piu' avanti del probe, quindi
 * l'accessore e' dichiarato qui e definito accanto a loro.  La lettura e'
 * volutamente non sincronizzata, come le altre righe di stato. */
static void ds4_vram_peak_read_context(uint64_t *pool_bytes,
                                       uint64_t *range_bytes);

static int ds4_vram_peak_probe_enabled(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_VRAM_PEAK_PROBE");
        cached = (env != NULL && env[0] != '\0' && env[0] != '0') ? 1 : 0;
    }
    return cached;
}

static uint64_t ds4_vram_peak_log_every_tokens(void) {
    static int resolved = 0;
    static uint64_t cached = 32ull;
    if (resolved) return cached;
    resolved = 1;
    const char *env = getenv("DS4_CUDA_VRAM_PEAK_LOG_EVERY_TOKENS");
    if (!env || !env[0]) return cached;
    char *end = NULL;
    errno = 0;
    const unsigned long long parsed = strtoull(env, &end, 10);
    if (errno == 0 && end && *end == '\0' && parsed <= 1000000ull) {
        cached = (uint64_t)parsed;
    } else {
        fprintf(stderr,
                "ds4: invalid DS4_CUDA_VRAM_PEAK_LOG_EVERY_TOKENS=%s "
                "-> using 32\n", env);
    }
    return cached;
}

/* 1 = interroga il driver a ogni evento di alloc/free (default, nessun estremo
 * perso).  N>1 = 1 evento su N, per limitare il costo se la misura dell'overhead
 * lo richiedesse; e' una perdita di risoluzione dichiarata, non silenziosa. */
static uint64_t ds4_vram_peak_query_every(void) {
    static int resolved = 0;
    static uint64_t cached = 1ull;
    if (resolved) return cached;
    resolved = 1;
    const char *env = getenv("DS4_CUDA_VRAM_PEAK_QUERY_EVERY");
    if (!env || !env[0]) return cached;
    char *end = NULL;
    errno = 0;
    const unsigned long long parsed = strtoull(env, &end, 10);
    if (errno == 0 && end && *end == '\0' && parsed >= 1ull &&
        parsed <= 1000000ull) {
        cached = (uint64_t)parsed;
    } else {
        fprintf(stderr,
                "ds4: invalid DS4_CUDA_VRAM_PEAK_QUERY_EVERY=%s -> using 1\n",
                env);
    }
    return cached;
}

/* Tutto atomico: gli stessi percorsi di allocazione girano sul thread di decode
 * E sul route worker.  Ordinamento rilassato: e' strumentazione, non un
 * protocollo di sincronizzazione. */
struct ds4_vram_peak_state {
    std::atomic<int> armed;                     /* 1 fra token-begin e token-end */
    std::atomic<uint64_t> token_index;
    std::atomic<uint64_t> free_at_token_start;
    /* finestra del token corrente */
    std::atomic<uint64_t> tok_free_min;         /* UINT64_MAX = nessun campione */
    std::atomic<uint64_t> tok_pool_at_min;
    std::atomic<uint64_t> tok_ranges_at_min;
    std::atomic<uint64_t> tok_bytes_at_min;
    std::atomic<uint64_t> tok_pool_hwm;         /* massimo di g_stream_pool_bytes */
    std::atomic<const char *> tok_what_at_min;
    std::atomic<const char *> tok_phase_at_min;
    std::atomic<int> tok_line_at_min;
    std::atomic<uint64_t> tok_allocs;
    std::atomic<uint64_t> tok_frees;
    std::atomic<uint64_t> tok_samples;
    /* minimo assoluto della richiesta */
    std::atomic<uint64_t> run_free_min;         /* 0 = nessun campione ancora */
    std::atomic<uint64_t> run_min_token;
    std::atomic<uint64_t> run_pool_at_min;
    std::atomic<uint64_t> run_ranges_at_min;
    std::atomic<uint64_t> run_bytes_at_min;
    std::atomic<uint64_t> run_pool_hwm;
    std::atomic<const char *> run_what_at_min;
    std::atomic<const char *> run_phase_at_min;
    std::atomic<int> run_line_at_min;
    std::atomic<uint64_t> run_allocs;
    std::atomic<uint64_t> run_frees;
    std::atomic<uint64_t> run_samples;
    std::atomic<uint64_t> run_driver_queries;
    std::atomic<uint64_t> run_probe_ns;         /* costo misurato del probe */
    std::atomic<uint64_t> query_tick;
    std::atomic<uint64_t> tokens_seen;
    std::atomic<uint64_t> next_log;
};
static ds4_vram_peak_state g_vram_peak;

/* Nome del tensore/range in corso di trasporto sul thread corrente: trasforma
 * "device/cuda_model_stream_alloc@7351" in "moe_gate_exp" / "attn_kv_b".
 * Scritto solo a flag acceso. */
static thread_local const char *g_vram_peak_what_hint;

static void ds4_vram_peak_set_what(const char *what) {
    if (!ds4_vram_peak_probe_enabled()) return;
    g_vram_peak_what_hint = what;
}

/* Ingestione di un campione.  free_bytes viene da cudaMemGetInfo, non e' stimato. */
static void ds4_vram_peak_record(uint64_t free_bytes,
                                 const char *what,
                                 const char *phase,
                                 int line,
                                 uint64_t bytes) {
    if (!g_vram_peak.armed.load(std::memory_order_acquire)) return;
    /* 0 = query fallita a monte: non e' un minimo, e' un dato mancante. */
    if (free_bytes == 0ull) return;
    const char *tag = g_vram_peak_what_hint ? g_vram_peak_what_hint : what;
    uint64_t pool_bytes = 0;
    uint64_t range_bytes = 0;
    ds4_vram_peak_read_context(&pool_bytes, &range_bytes);
    g_vram_peak.tok_samples.fetch_add(1u, std::memory_order_relaxed);
    g_vram_peak.run_samples.fetch_add(1u, std::memory_order_relaxed);

    /* Massimo della VRAM parcheggiata nel pool: e' la quota comprimibile. */
    uint64_t hwm = g_vram_peak.tok_pool_hwm.load(std::memory_order_relaxed);
    while (pool_bytes > hwm &&
           !g_vram_peak.tok_pool_hwm.compare_exchange_weak(
               hwm, pool_bytes, std::memory_order_relaxed)) {
    }
    hwm = g_vram_peak.run_pool_hwm.load(std::memory_order_relaxed);
    while (pool_bytes > hwm &&
           !g_vram_peak.run_pool_hwm.compare_exchange_weak(
               hwm, pool_bytes, std::memory_order_relaxed)) {
    }

    /* Minimo del token.  I descrittori sono scritti solo dal thread che vince la
     * CAS; LIMITE DICHIARATO: la tupla (minimo, descrittori) non e' atomica nel
     * suo insieme, quindi con due thread che abbassano il minimo nello stesso
     * istante i descrittori possono appartenere al campione immediatamente
     * successivo.  Il valore numerico del minimo resta esatto. */
    uint64_t prev = g_vram_peak.tok_free_min.load(std::memory_order_relaxed);
    while (free_bytes < prev) {
        if (g_vram_peak.tok_free_min.compare_exchange_weak(
                prev, free_bytes, std::memory_order_relaxed)) {
            g_vram_peak.tok_pool_at_min.store(pool_bytes,
                                              std::memory_order_relaxed);
            g_vram_peak.tok_ranges_at_min.store(range_bytes,
                                                std::memory_order_relaxed);
            g_vram_peak.tok_bytes_at_min.store(bytes,
                                               std::memory_order_relaxed);
            g_vram_peak.tok_what_at_min.store(tag, std::memory_order_relaxed);
            g_vram_peak.tok_phase_at_min.store(phase,
                                               std::memory_order_relaxed);
            g_vram_peak.tok_line_at_min.store(line, std::memory_order_relaxed);
            break;
        }
    }

    /* Minimo assoluto della richiesta (0 = mai campionato). */
    uint64_t rprev = g_vram_peak.run_free_min.load(std::memory_order_relaxed);
    for (;;) {
        const uint64_t effective = (rprev == 0ull) ? UINT64_MAX : rprev;
        if (free_bytes >= effective) break;
        if (g_vram_peak.run_free_min.compare_exchange_weak(
                rprev, free_bytes, std::memory_order_relaxed)) {
            g_vram_peak.run_min_token.store(
                g_vram_peak.token_index.load(std::memory_order_relaxed),
                std::memory_order_relaxed);
            g_vram_peak.run_pool_at_min.store(pool_bytes,
                                              std::memory_order_relaxed);
            g_vram_peak.run_ranges_at_min.store(range_bytes,
                                                std::memory_order_relaxed);
            g_vram_peak.run_bytes_at_min.store(bytes,
                                               std::memory_order_relaxed);
            g_vram_peak.run_what_at_min.store(tag, std::memory_order_relaxed);
            g_vram_peak.run_phase_at_min.store(phase,
                                               std::memory_order_relaxed);
            g_vram_peak.run_line_at_min.store(line, std::memory_order_relaxed);
            break;
        }
    }
}

/* Ingestione GRATUITA: il chiamante ha gia' un cudaMemGetInfo fresco in mano. */
static void ds4_vram_peak_note_known_free(uint64_t free_bytes,
                                          const char *what,
                                          const char *phase,
                                          uint64_t bytes) {
    if (!ds4_vram_peak_probe_enabled()) return;
    ds4_vram_peak_record(free_bytes, what, phase, 0, bytes);
}

/* Ingestione che interroga il driver, con il proprio costo misurato. */
static void ds4_vram_peak_sample(const char *what,
                                 const char *phase,
                                 int line,
                                 uint64_t bytes) {
    if (!ds4_vram_peak_probe_enabled()) return;
    if (!g_vram_peak.armed.load(std::memory_order_acquire)) return;
    const uint64_t every = ds4_vram_peak_query_every();
    if (every > 1ull) {
        const uint64_t tick =
            g_vram_peak.query_tick.fetch_add(1u, std::memory_order_relaxed);
        if ((tick % every) != 0ull) return;
    }
    const double t0 = cuda_wall_sec();
    size_t free_bytes = 0;
    size_t total_bytes = 0;
    const cudaError_t err = cudaMemGetInfo(&free_bytes, &total_bytes);
    const double t1 = cuda_wall_sec();
    g_vram_peak.run_driver_queries.fetch_add(1u, std::memory_order_relaxed);
    const double dt_ns = (t1 - t0) * 1.0e9;
    g_vram_peak.run_probe_ns.fetch_add(
        dt_ns > 0.0 ? (uint64_t)dt_ns : 0ull, std::memory_order_relaxed);
    if (err != cudaSuccess) {
        (void)cudaGetLastError();
        return;
    }
    ds4_vram_peak_record((uint64_t)free_bytes, what, phase, line, bytes);
}

static void ds4_vram_peak_count_alloc(void) {
    if (!ds4_vram_peak_probe_enabled()) return;
    if (!g_vram_peak.armed.load(std::memory_order_acquire)) return;
    g_vram_peak.tok_allocs.fetch_add(1u, std::memory_order_relaxed);
    g_vram_peak.run_allocs.fetch_add(1u, std::memory_order_relaxed);
}

static void ds4_vram_peak_count_free(void) {
    if (!ds4_vram_peak_probe_enabled()) return;
    if (!g_vram_peak.armed.load(std::memory_order_acquire)) return;
    g_vram_peak.tok_frees.fetch_add(1u, std::memory_order_relaxed);
    g_vram_peak.run_frees.fetch_add(1u, std::memory_order_relaxed);
}
/* ==================== fine DS4 intra-token VRAM peak probe ================ */

struct ds4_alloc_site {
    const char *fn;
    const char *label;
    int line;
    int kind;
    uint64_t calls;
    uint64_t fails;
    uint64_t cum_bytes;
    uint64_t live_bytes;
    uint64_t peak_bytes;
    uint64_t max_single_bytes;
};

struct ds4_alloc_record {
    int site;
    uint64_t bytes;
};

enum { DS4_ALLOC_SITE_CAP = 512 };

static ds4_alloc_site g_alloc_sites[DS4_ALLOC_SITE_CAP];
static int g_alloc_site_count;
static int g_alloc_site_overflow;
static std::mutex g_alloc_trace_mutex;
static std::unordered_map<const void *, ds4_alloc_record> g_alloc_live_map;
static uint64_t g_alloc_kind_live[DS4_ALLOC_KIND_COUNT];
static uint64_t g_alloc_kind_cum[DS4_ALLOC_KIND_COUNT];
static uint64_t g_alloc_kind_peak[DS4_ALLOC_KIND_COUNT];
static uint64_t g_alloc_untracked_frees;
static uint64_t g_alloc_trace_events;

/* Caller attribution for ds4.c tensor allocations: ds4_gpu.h turns every
 * ds4_gpu_tensor_alloc() call site into a label push followed by the real
 * call, so the single cudaMallocManaged inside the backend resolves to the
 * originating source line instead of collapsing into one bucket. */
static thread_local const char *g_alloc_pending_label;

static int ds4_alloc_trace_enabled(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_ALLOC_TRACE");
        cached = (env != NULL && env[0] != '\0' && env[0] != '0') ? 1 : 0;
    }
    return cached;
}

/* Per-event lines are noisy for small buffers; the summary always covers
 * every site regardless of this threshold. */
static uint64_t ds4_alloc_trace_min_bytes(void) {
    static int resolved = 0;
    static uint64_t cached = 0;
    if (!resolved) {
        const char *env = getenv("DS4_CUDA_ALLOC_TRACE_MIN_MIB");
        double mib = (env != NULL && env[0] != '\0') ? atof(env) : 16.0;
        if (mib < 0.0) mib = 0.0;
        cached = (uint64_t)(mib * 1048576.0);
        resolved = 1;
    }
    return cached;
}

/* Declared, not invented: the CUDA context/driver floor measured out of band
 * by a standalone probe on this machine is passed in so the balance line can
 * report the residual both before and after subtracting it. */
static double ds4_alloc_ctx_baseline_mib(void) {
    static int resolved = 0;
    static double cached = 0.0;
    if (!resolved) {
        const char *env = getenv("DS4_CUDA_CTX_BASELINE_MIB");
        cached = (env != NULL && env[0] != '\0') ? atof(env) : 0.0;
        resolved = 1;
    }
    return cached;
}

static const char *ds4_alloc_basename(const char *path) {
    if (!path) return "?";
    const char *out = path;
    for (const char *p = path; *p; ++p) {
        if (*p == '/' || *p == '\\') out = p + 1;
    }
    return out;
}

/* Composes the printable tag for one site.  Every field is a %-specifier over
 * a computed value; nothing here is a hard-coded literal number. */
static void ds4_alloc_site_tag(const ds4_alloc_site &site, char *out, size_t cap) {
    if (site.label) {
        snprintf(out, cap, "%s/%s", g_alloc_kind_name[site.kind],
                 ds4_alloc_basename(site.label));
    } else {
        snprintf(out, cap, "%s/%s@%d", g_alloc_kind_name[site.kind],
                 site.fn ? site.fn : "?", site.line);
    }
}

static void ds4_alloc_trace_note(const char *fn,
                                 int line,
                                 int kind,
                                 uint64_t bytes,
                                 const void *ptr,
                                 int ok) {
    if (!ds4_alloc_trace_enabled()) {
        g_alloc_pending_label = NULL;
        return;
    }
    const char *label = NULL;
    if (kind == DS4_ALLOC_KIND_MANAGED && g_alloc_pending_label) {
        label = g_alloc_pending_label;
    }
    g_alloc_pending_label = NULL;

    char tag[192];
    uint64_t cum_bytes = 0;
    {
        std::lock_guard<std::mutex> lock(g_alloc_trace_mutex);
        int index = -1;
        for (int i = 0; i < g_alloc_site_count; ++i) {
            const ds4_alloc_site &s = g_alloc_sites[i];
            if (s.kind != kind) continue;
            if (label) {
                if (s.label && (s.label == label || strcmp(s.label, label) == 0)) {
                    index = i;
                    break;
                }
                continue;
            }
            if (s.label) continue;
            if (s.line == line && s.fn == fn) {
                index = i;
                break;
            }
        }
        if (index < 0) {
            if (g_alloc_site_count >= DS4_ALLOC_SITE_CAP) {
                g_alloc_site_overflow++;
                return;
            }
            index = g_alloc_site_count++;
            memset(&g_alloc_sites[index], 0, sizeof(g_alloc_sites[index]));
            g_alloc_sites[index].fn = fn;
            g_alloc_sites[index].label = label;
            g_alloc_sites[index].line = line;
            g_alloc_sites[index].kind = kind;
        }
        ds4_alloc_site &site = g_alloc_sites[index];
        site.calls++;
        g_alloc_trace_events++;
        if (!ok) {
            site.fails++;
            return;
        }
        site.cum_bytes += bytes;
        site.live_bytes += bytes;
        if (site.live_bytes > site.peak_bytes) site.peak_bytes = site.live_bytes;
        if (bytes > site.max_single_bytes) site.max_single_bytes = bytes;
        g_alloc_kind_cum[kind] += bytes;
        g_alloc_kind_live[kind] += bytes;
        if (g_alloc_kind_live[kind] > g_alloc_kind_peak[kind]) {
            g_alloc_kind_peak[kind] = g_alloc_kind_live[kind];
        }
        cum_bytes = site.cum_bytes;
        if (ptr) {
            ds4_alloc_record record;
            record.site = index;
            record.bytes = bytes;
            g_alloc_live_map[ptr] = record;
        }
        ds4_alloc_site_tag(site, tag, sizeof(tag));
    }

    if (bytes < ds4_alloc_trace_min_bytes()) return;

    size_t free_bytes = 0;
    size_t total_bytes = 0;
    double free_after_mib = -1.0;
    if (cudaMemGetInfo(&free_bytes, &total_bytes) == cudaSuccess) {
        free_after_mib = (double)free_bytes / 1048576.0;
    }
    const double cum_mib = (double)cum_bytes / 1048576.0;
    const unsigned long long bytes_out = (unsigned long long)bytes;
    fprintf(stderr,
            "ds4: [cuda-alloc] tag=%s bytes=%llu ok=%d cum_mib=%.1f "
            "free_after_mib=%.1f\n",
            tag, bytes_out, ok, cum_mib, free_after_mib);
}

static void ds4_alloc_trace_release(const void *ptr) {
    if (!ds4_alloc_trace_enabled() || !ptr) return;
    std::lock_guard<std::mutex> lock(g_alloc_trace_mutex);
    std::unordered_map<const void *, ds4_alloc_record>::iterator it =
        g_alloc_live_map.find(ptr);
    if (it == g_alloc_live_map.end()) {
        g_alloc_untracked_frees++;
        return;
    }
    const uint64_t bytes = it->second.bytes;
    ds4_alloc_site &site = g_alloc_sites[it->second.site];
    site.live_bytes = site.live_bytes >= bytes ? site.live_bytes - bytes : 0;
    const int kind = site.kind;
    g_alloc_kind_live[kind] =
        g_alloc_kind_live[kind] >= bytes ? g_alloc_kind_live[kind] - bytes : 0;
    g_alloc_live_map.erase(it);
}

/* -------- tagged wrappers (templated to mirror the CUDA overloads) -------- */

/* I due wrapper di device sotto campionano il picco di VRAM SUBITO DOPO
 * l'allocazione riuscita: e' l'istante in cui la VRAM libera tocca il suo minimo
 * locale.  Il campionamento e' indipendente da DS4_CUDA_ALLOC_TRACE (i due
 * strumenti si accendono separatamente). */
template <typename T>
static cudaError_t ds4_trace_cuda_malloc(T **ptr, size_t bytes,
                                         const char *fn, int line) {
    const cudaError_t err = cudaMalloc((void **)ptr, bytes);
    ds4_alloc_trace_note(fn, line, DS4_ALLOC_KIND_DEVICE, (uint64_t)bytes,
                         err == cudaSuccess ? (const void *)*ptr : NULL,
                         err == cudaSuccess ? 1 : 0);
    if (err == cudaSuccess) {
        ds4_vram_peak_count_alloc();
        ds4_vram_peak_sample(fn, "post-malloc", line, (uint64_t)bytes);
    }
    return err;
}

template <typename T>
static cudaError_t ds4_trace_cuda_malloc_managed(T **ptr, size_t bytes,
                                                 const char *fn, int line) {
    const cudaError_t err =
        cudaMallocManaged((void **)ptr, bytes, cudaMemAttachGlobal);
    ds4_alloc_trace_note(fn, line, DS4_ALLOC_KIND_MANAGED, (uint64_t)bytes,
                         err == cudaSuccess ? (const void *)*ptr : NULL,
                         err == cudaSuccess ? 1 : 0);
    if (err == cudaSuccess) {
        ds4_vram_peak_count_alloc();
        ds4_vram_peak_sample(fn, "post-malloc-managed", line, (uint64_t)bytes);
    }
    return err;
}

template <typename T>
static cudaError_t ds4_trace_cuda_malloc_host(T **ptr, size_t bytes,
                                              const char *fn, int line) {
    const cudaError_t err = cudaMallocHost((void **)ptr, bytes);
    ds4_alloc_trace_note(fn, line, DS4_ALLOC_KIND_HOST_PINNED, (uint64_t)bytes,
                         err == cudaSuccess ? (const void *)*ptr : NULL,
                         err == cudaSuccess ? 1 : 0);
    return err;
}

template <typename T>
static cudaError_t ds4_trace_cuda_host_alloc(T **ptr, size_t bytes,
                                             unsigned int flags,
                                             const char *fn, int line) {
    const cudaError_t err = cudaHostAlloc((void **)ptr, bytes, flags);
    ds4_alloc_trace_note(fn, line, DS4_ALLOC_KIND_HOST_PINNED, (uint64_t)bytes,
                         err == cudaSuccess ? (const void *)*ptr : NULL,
                         err == cudaSuccess ? 1 : 0);
    return err;
}

static cudaError_t ds4_trace_cuda_host_register(void *ptr, size_t bytes,
                                                unsigned int flags,
                                                const char *fn, int line) {
    const cudaError_t err = cudaHostRegister(ptr, bytes, flags);
    ds4_alloc_trace_note(fn, line, DS4_ALLOC_KIND_HOST_REG, (uint64_t)bytes,
                         err == cudaSuccess ? (const void *)ptr : NULL,
                         err == cudaSuccess ? 1 : 0);
    return err;
}

/* Campiona PRIMA del rilascio: la VRAM libera e' al suo minimo locale
 * esattamente prima di una free.  fn/line arrivano dalla macro, cosi' il minimo
 * e' attribuibile alla riga sorgente anche sul lato free. */
static cudaError_t ds4_trace_cuda_free(void *ptr, const char *fn, int line) {
    if (ptr) {
        ds4_vram_peak_sample(fn, "pre-free", line, 0);
        ds4_vram_peak_count_free();
    }
    ds4_alloc_trace_release(ptr);
    return cudaFree(ptr);
}

static cudaError_t ds4_trace_cuda_free_host(void *ptr) {
    ds4_alloc_trace_release(ptr);
    return cudaFreeHost(ptr);
}

static cudaError_t ds4_trace_cuda_host_unregister(void *ptr) {
    ds4_alloc_trace_release(ptr);
    return cudaHostUnregister(ptr);
}

/* One VRAM snapshot with the tracked totals alongside, so the untracked delta
 * between two phases is readable directly off two consecutive lines. */
static void ds4_alloc_trace_mark_impl(const char *phase) {
    size_t free_bytes = 0;
    size_t total_bytes = 0;
    const cudaError_t err = cudaMemGetInfo(&free_bytes, &total_bytes);
    const double total_mib = (double)total_bytes / 1048576.0;
    const double free_mib = (double)free_bytes / 1048576.0;
    const double used_mib = total_mib - free_mib;
    uint64_t device_live = 0;
    uint64_t managed_live = 0;
    {
        std::lock_guard<std::mutex> lock(g_alloc_trace_mutex);
        device_live = g_alloc_kind_live[DS4_ALLOC_KIND_DEVICE];
        managed_live = g_alloc_kind_live[DS4_ALLOC_KIND_MANAGED];
    }
    const double tracked_mib =
        (double)(device_live + managed_live) / 1048576.0;
    const double untracked_mib = used_mib - tracked_mib;
    fprintf(stderr,
            "ds4: [cuda-vram-mark] phase=%s total_mib=%.1f free_mib=%.1f "
            "used_mib=%.1f tracked_vram_mib=%.1f untracked_mib=%.1f "
            "status=%s\n",
            phase ? phase : "?", total_mib, free_mib, used_mib, tracked_mib,
            untracked_mib, err == cudaSuccess ? "ok" : cudaGetErrorString(err));
}

extern "C" void ds4_gpu_alloc_trace_mark(const char *phase) {
    if (!ds4_alloc_trace_enabled()) return;
    ds4_alloc_trace_mark_impl(phase);
}

extern "C" void ds4_gpu_alloc_site_label(const char *site) {
    if (!ds4_alloc_trace_enabled()) return;
    g_alloc_pending_label = site;
}

static bool ds4_alloc_site_live_greater(const ds4_alloc_site &a,
                                        const ds4_alloc_site &b) {
    if (a.live_bytes != b.live_bytes) return a.live_bytes > b.live_bytes;
    return a.peak_bytes > b.peak_bytes;
}

extern "C" void ds4_gpu_alloc_trace_summary(const char *phase) {
    if (!ds4_alloc_trace_enabled()) return;

    std::vector<ds4_alloc_site> rows;
    uint64_t kind_live[DS4_ALLOC_KIND_COUNT];
    uint64_t kind_cum[DS4_ALLOC_KIND_COUNT];
    uint64_t kind_peak[DS4_ALLOC_KIND_COUNT];
    uint64_t untracked_frees = 0;
    uint64_t events = 0;
    int overflow = 0;
    {
        std::lock_guard<std::mutex> lock(g_alloc_trace_mutex);
        rows.assign(g_alloc_sites, g_alloc_sites + g_alloc_site_count);
        for (int k = 0; k < DS4_ALLOC_KIND_COUNT; ++k) {
            kind_live[k] = g_alloc_kind_live[k];
            kind_cum[k] = g_alloc_kind_cum[k];
            kind_peak[k] = g_alloc_kind_peak[k];
        }
        untracked_frees = g_alloc_untracked_frees;
        events = g_alloc_trace_events;
        overflow = g_alloc_site_overflow;
    }
    std::sort(rows.begin(), rows.end(), ds4_alloc_site_live_greater);

    const int row_count = (int)rows.size();
    fprintf(stderr,
            "ds4: [cuda-alloc-summary] phase=%s sites=%d events=%llu "
            "site_overflow=%d untracked_frees=%llu\n",
            phase ? phase : "?", row_count, (unsigned long long)events,
            overflow, (unsigned long long)untracked_frees);

    for (int i = 0; i < row_count; ++i) {
        const ds4_alloc_site &site = rows[i];
        if (site.calls == 0) continue;
        char tag[192];
        ds4_alloc_site_tag(site, tag, sizeof(tag));
        const int rank = i + 1;
        const double live_mib = (double)site.live_bytes / 1048576.0;
        const double peak_mib = (double)site.peak_bytes / 1048576.0;
        const double cum_mib = (double)site.cum_bytes / 1048576.0;
        const double max_single_mib = (double)site.max_single_bytes / 1048576.0;
        const unsigned long long calls = (unsigned long long)site.calls;
        const unsigned long long fails = (unsigned long long)site.fails;
        const int vram = ds4_alloc_kind_is_vram(site.kind);
        fprintf(stderr,
                "ds4: [cuda-alloc-row] rank=%d tag=%s vram=%d live_mib=%.2f "
                "peak_mib=%.2f cum_mib=%.2f max_single_mib=%.2f calls=%llu "
                "fails=%llu\n",
                rank, tag, vram, live_mib, peak_mib, cum_mib, max_single_mib,
                calls, fails);
    }

    for (int k = 0; k < DS4_ALLOC_KIND_COUNT; ++k) {
        const double live_mib = (double)kind_live[k] / 1048576.0;
        const double peak_mib = (double)kind_peak[k] / 1048576.0;
        const double cum_mib = (double)kind_cum[k] / 1048576.0;
        const int vram = ds4_alloc_kind_is_vram(k);
        fprintf(stderr,
                "ds4: [cuda-alloc-kind] kind=%s vram=%d live_mib=%.2f "
                "peak_mib=%.2f cum_mib=%.2f\n",
                g_alloc_kind_name[k], vram, live_mib, peak_mib, cum_mib);
    }

    size_t free_bytes = 0;
    size_t total_bytes = 0;
    const cudaError_t err = cudaMemGetInfo(&free_bytes, &total_bytes);
    const double total_mib = (double)total_bytes / 1048576.0;
    const double free_mib = (double)free_bytes / 1048576.0;
    const double used_mib = total_mib - free_mib;
    const double tracked_mib =
        (double)(kind_live[DS4_ALLOC_KIND_DEVICE] +
                 kind_live[DS4_ALLOC_KIND_MANAGED]) / 1048576.0;
    const double residual_mib = used_mib - tracked_mib;
    const double ctx_baseline_mib = ds4_alloc_ctx_baseline_mib();
    const double residual_after_ctx_mib = residual_mib - ctx_baseline_mib;
    fprintf(stderr,
            "ds4: [cuda-alloc-balance] phase=%s total_mib=%.1f free_mib=%.1f "
            "used_mib=%.1f tracked_vram_mib=%.1f residual_mib=%.1f "
            "ctx_baseline_mib=%.1f residual_after_ctx_mib=%.1f status=%s\n",
            phase ? phase : "?", total_mib, free_mib, used_mib, tracked_mib,
            residual_mib, ctx_baseline_mib, residual_after_ctx_mib,
            err == cudaSuccess ? "ok" : cudaGetErrorString(err));
}

/* -------- interception: every call site below is tagged automatically -------- */
#define cudaMalloc(p, n)          ds4_trace_cuda_malloc((p), (n), __FUNCTION__, __LINE__)
#define cudaMallocManaged(p, n)   ds4_trace_cuda_malloc_managed((p), (n), __FUNCTION__, __LINE__)
#define cudaMallocHost(p, n)      ds4_trace_cuda_malloc_host((p), (n), __FUNCTION__, __LINE__)
#define cudaHostAlloc(p, n, f)    ds4_trace_cuda_host_alloc((p), (n), (f), __FUNCTION__, __LINE__)
#define cudaHostRegister(p, n, f) ds4_trace_cuda_host_register((p), (n), (f), __FUNCTION__, __LINE__)
#define cudaFree(p)               ds4_trace_cuda_free((p), __FUNCTION__, __LINE__)
#define cudaFreeHost(p)           ds4_trace_cuda_free_host((p))
#define cudaHostUnregister(p)     ds4_trace_cuda_host_unregister((p))
/* ===================== end DS4 CUDA allocation tracer ===================== */

