static uint64_t cuda_page_size(void) {
#ifdef _WIN32
    SYSTEM_INFO si;
    GetSystemInfo(&si);
    return si.dwPageSize ? (uint64_t)si.dwPageSize : 4096u;
#else
    const long ps = sysconf(_SC_PAGESIZE);
    return ps > 0 ? (uint64_t)ps : 4096u;
#endif
}

static uint64_t cuda_host_register_budget_bytes(void) {
    /* Ceiling on cumulative host-pinned (cudaHostRegister) bytes. The 0050 knob
     * DS4_CUDA_STREAM_FROM_RAM_MASKED_BUDGET_GB wins on both platforms. Unset:
     * Linux stays unbounded (prior behavior); native Windows/WDDM caps at ~24 GiB
     * so the ~80 GiB image is never registered whole (the WDDM host-pin limit). */
    const char *env = getenv("DS4_CUDA_STREAM_FROM_RAM_MASKED_BUDGET_GB");
    if (env && env[0]) {
        const double v = atof(env);
        if (v > 0.0) return (uint64_t)(v * 1073741824.0);
    }
#ifdef _WIN32
    return 24ull * 1073741824ull;
#else
    return ~(uint64_t)0;
#endif
}

static void cuda_mtp_model_map_release(void) {
    if (g_mtp_model_registered_base) {
        (void)cudaHostUnregister(g_mtp_model_registered_base);
    }
    g_mtp_model_host_base = NULL;
    g_mtp_model_size = 0;
    g_mtp_model_map_offset = 0;
    g_mtp_model_map_bytes = 0;
    g_mtp_model_registered_base = NULL;
    g_mtp_model_registered_device_base = NULL;
    g_mtp_model_registered_bytes = 0;
}

static const char *cuda_mtp_model_range_ptr(
        const void *model_map,
        uint64_t offset,
        uint64_t bytes) {
    if (!model_map || model_map != g_mtp_model_host_base ||
        !g_mtp_model_registered_base ||
        !g_mtp_model_registered_device_base) {
        return NULL;
    }
    if (offset > g_mtp_model_size || bytes > g_mtp_model_size - offset ||
        offset < g_mtp_model_map_offset ||
        offset - g_mtp_model_map_offset > g_mtp_model_map_bytes ||
        bytes > g_mtp_model_map_bytes -
                    (offset - g_mtp_model_map_offset)) {
        return NULL;
    }

    const uintptr_t host_ptr =
        (uintptr_t)model_map + (uintptr_t)offset;
    const uintptr_t registered =
        (uintptr_t)g_mtp_model_registered_base;
    if (host_ptr < registered ||
        host_ptr - registered > g_mtp_model_registered_bytes ||
        bytes > g_mtp_model_registered_bytes - (host_ptr - registered)) {
        return NULL;
    }
    return g_mtp_model_registered_device_base + (host_ptr - registered);
}

static void *cuda_tmp_alloc(uint64_t bytes, const char *what) {
    if (bytes == 0) return NULL;
    if (g_cuda_tmp_bytes >= bytes) return g_cuda_tmp;
    if (g_cuda_tmp) {
        (void)cudaFree(g_cuda_tmp);
        g_cuda_tmp = NULL;
        g_cuda_tmp_bytes = 0;
    }
    void *ptr = NULL;
    cudaError_t err = cudaMalloc(&ptr, (size_t)bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA temp alloc failed for %s (%.2f MiB): %s\n",
                what ? what : "scratch", (double)bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return NULL;
    }
    g_cuda_tmp = ptr;
    g_cuda_tmp_bytes = bytes;
    return g_cuda_tmp;
}

static int cuda_attention_score_buffer_fits(uint32_t n_comp) {
    return n_comp <= DS4_CUDA_ATTENTION_SCORE_CAP - DS4_CUDA_ATTENTION_RAW_SCORE_CAP;
}

static const char *cuda_model_ptr(const void *model_map, uint64_t offset) {
    if (model_map == g_mtp_model_host_base) {
        return cuda_mtp_model_range_ptr(model_map, offset, 0);
    }
    if (model_map == g_model_host_base && g_model_device_base &&
        (g_model_window_bytes == 0 || offset < g_model_window_bytes))
        return g_model_device_base + offset;
    return (const char *)model_map + offset;
}

static void cuda_embed_row_stage_release(void) {
    if (g_embed_row_device) {
        (void)cudaFree(g_embed_row_device);
        g_embed_row_device = NULL;
    }
    if (g_embed_row_host) {
        (void)cudaFreeHost(g_embed_row_host);
        g_embed_row_host = NULL;
    }
    g_embed_row_capacity = 0;
    g_embed_row_notice_printed = 0;
}

static int cuda_embed_row_stage_alloc(uint64_t bytes) {
    if (bytes == 0) return 0;
    if (g_embed_row_capacity >= bytes && g_embed_row_host && g_embed_row_device) return 1;

    if (cudaDeviceSynchronize() != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA embedding row staging synchronization failed\n");
        (void)cudaGetLastError();
        return 0;
    }
    cuda_embed_row_stage_release();

    void *host = NULL;
    cudaError_t err = cudaHostAlloc(&host, (size_t)bytes, cudaHostAllocDefault);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: CUDA embedding row host staging allocation failed (%.2f MiB): %s\n",
                (double)bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    __half *device = NULL;
    err = cudaMalloc((void **)&device, (size_t)bytes);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: CUDA embedding row device staging allocation failed (%.2f MiB): %s\n",
                (double)bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaFreeHost(host);
        (void)cudaGetLastError();
        return 0;
    }
    g_embed_row_host = host;
    g_embed_row_device = device;
    g_embed_row_capacity = bytes;
    if (!g_embed_row_notice_printed) {
        fprintf(stderr,
                "ds4: CUDA embedding row staging ready (pinned host + device, %.2f MiB)\n",
                (double)bytes / 1048576.0);
        g_embed_row_notice_printed = 1;
    }
    return 1;
}

static cuda_model_range *cuda_model_range_find_override(
        const void *model_map,
        uint64_t offset,
        uint64_t bytes) {
    const uint64_t end = offset + bytes;
    if (end < offset) return NULL;
    auto exact = g_model_range_by_offset.find(offset);
    if (exact != g_model_range_by_offset.end()) {
        cuda_model_range &r = g_model_ranges[exact->second];
        if (r.persistent_override &&
            r.host_base == model_map &&
            bytes <= r.bytes) {
            return &r;
        }
    }
    for (cuda_model_range &r : g_model_ranges) {
        if (!r.persistent_override || r.host_base != model_map) continue;
        if (offset >= r.offset && end <= r.offset + r.bytes) return &r;
    }
    return NULL;
}

static const char *cuda_model_range_ptr(const void *model_map, uint64_t offset, uint64_t bytes, const char *what) {
    if (model_map == g_mtp_model_host_base) {
        const char *mtp_ptr =
            cuda_mtp_model_range_ptr(model_map, offset, bytes);
        if (!mtp_ptr) {
            fprintf(stderr,
                    "ds4: CUDA MTP secondary range is outside its registered "
                    "tensor window for %s (offset=%llu bytes=%llu)\n",
                    what ? what : "weights",
                    (unsigned long long)offset,
                    (unsigned long long)bytes);
        }
        return mtp_ptr;
    }
    if (bytes == 0) return cuda_model_ptr(model_map, offset);
    if (cuda_model_range *override_range = cuda_model_range_find_override(model_map, offset, bytes)) {
        return override_range->device_ptr + (offset - override_range->offset);
    }
    /* Zero-copy fast path: weight fully inside the registered contiguous host
     * window -> device pointer + offset (~24 GiB/s DMA, no VRAM). */
    if (g_model_window_bytes && model_map == g_model_host_base && g_model_device_base &&
        offset + bytes <= g_model_window_bytes) {
        return g_model_device_base + offset;
    }
    if (g_model_device_owned || g_model_registered) return cuda_model_ptr(model_map, offset);
    if (g_model_hmm_direct &&
        getenv("DS4_CUDA_WEIGHT_CACHE") == NULL &&
        getenv("DS4_CUDA_WEIGHT_PRELOAD") == NULL) {
        return cuda_model_ptr(model_map, offset);
    }
    const char *direct_env = getenv("DS4_CUDA_DIRECT_MODEL");
    if (direct_env && direct_env[0]) return cuda_model_ptr(model_map, offset);

    const uint64_t end = offset + bytes;
    auto exact = g_model_range_by_offset.find(offset);
    if (exact != g_model_range_by_offset.end()) {
        cuda_model_range &r = g_model_ranges[exact->second];
        if (r.host_base == model_map && end >= offset && bytes <= r.bytes) {
            if (r.streamed) r.last_used_tick = ++g_model_tick;
            return r.device_ptr;
        }
    }
    for (cuda_model_range &r : g_model_ranges) {
        if (r.host_base == model_map && offset >= r.offset && end >= offset && end <= r.offset + r.bytes) {
            if (r.streamed) r.last_used_tick = ++g_model_tick;
            return r.device_ptr + (offset - r.offset);
        }
        if (r.host_base == model_map && r.host_registered && r.registered_base && r.registered_device_base) {
            const uintptr_t h0 = (uintptr_t)((const char *)model_map + offset);
            const uintptr_t h1 = h0 + bytes;
            const uintptr_t r0 = (uintptr_t)r.registered_base;
            const uintptr_t r1 = r0 + r.registered_bytes;
            if (h1 >= h0 && h0 >= r0 && h1 <= r1) return r.registered_device_base + (h0 - r0);
        }
    }

    if (getenv("DS4_CUDA_NO_FD_CACHE") == NULL) {
        const char *fd_ptr = cuda_model_range_ptr_from_fd(model_map, offset, bytes, what);
        if (fd_ptr) return fd_ptr;
    }

    cudaError_t err = cudaSuccess;
    if (g_model_range_mapping_supported) {
        /* Register-mmap zero-copy: pin a page-aligned range of the view
         * (Win32 MapViewOfFile / POSIX mmap) and DMA weights straight to VRAM.
         * MISURA 2026-07-13: cudaHostRegister(Mapped|ReadOnly) succeeds on the
         * Windows section view at ~24.4 GiB/s (was previously hard-disabled here
         * on _WIN32 without ever being tried). Budget-gated so cumulative
         * registrations never exceed the WDDM ~24 GiB host-pin cap; over budget
         * falls through to the cudaMalloc copy path below. */
        const uint64_t page_sz = cuda_page_size();
        const uintptr_t host_addr = (uintptr_t)((const char *)model_map + offset);
        const uintptr_t reg_addr = host_addr & ~(uintptr_t)(page_sz - 1u);
        const uint64_t reg_delta = (uint64_t)(host_addr - reg_addr);
        const uint64_t reg_bytes = (reg_delta + bytes + page_sz - 1u) & ~(page_sz - 1u);
        if (g_model_registered_range_bytes + reg_bytes <= cuda_host_register_budget_bytes()) {
            void *reg_dev = NULL;
            err = cudaHostRegister((void *)reg_addr,
                                   (size_t)reg_bytes,
                                   cudaHostRegisterMapped | cudaHostRegisterReadOnly);
            if (err == cudaSuccess) {
                err = cudaHostGetDevicePointer(&reg_dev, (void *)reg_addr, 0);
                if (err == cudaSuccess && reg_dev) {
                    char *dev_ptr = (char *)reg_dev + reg_delta;
                    g_model_ranges.push_back({model_map, offset, bytes, dev_ptr, (void *)reg_addr, (char *)reg_dev, reg_bytes, 1, 0});
                    g_model_range_by_offset[offset] = g_model_ranges.size() - 1u;
                    g_model_registered_range_bytes += reg_bytes;
                    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                        fprintf(stderr, "ds4: CUDA mapped %s %.2f MiB [view=%p off=%llu reg_addr=%p reg_end=%p reg_bytes=%.2f MiB]\n",
                                what ? what : "weights", (double)bytes / 1048576.0,
                                model_map, (unsigned long long)offset, (void *)reg_addr,
                                (void *)(reg_addr + reg_bytes), (double)reg_bytes / 1048576.0);
                    }
                    return dev_ptr;
                }
                fprintf(stderr, "ds4: CUDA model range map pointer failed for %s: %s\n",
                        what ? what : "weights", cudaGetErrorString(err));
                (void)cudaHostUnregister((void *)reg_addr);
                (void)cudaGetLastError();
            } else {
                fprintf(stderr, "ds4: [regdiag] cudaHostRegister FAILED for %s: %s (addr=%p bytes=%.2f MiB cum=%.2f GiB budget=%.2f GiB)\n",
                        what ? what : "weights", cudaGetErrorString(err), (void *)reg_addr,
                        (double)reg_bytes / 1048576.0, (double)g_model_registered_range_bytes / 1073741824.0,
                        (double)cuda_host_register_budget_bytes() / 1073741824.0);
                if (err == cudaErrorNotSupported || err == cudaErrorInvalidValue) g_model_range_mapping_supported = 0;
                (void)cudaGetLastError();
            }
        } else if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
            fprintf(stderr, "ds4: [regdiag] %s SKIPPED register (budget): cum=%.2f GiB + %.2f MiB > budget %.2f GiB\n",
                    what ? what : "weights", (double)g_model_registered_range_bytes / 1073741824.0,
                    (double)reg_bytes / 1048576.0, (double)cuda_host_register_budget_bytes() / 1073741824.0);
        }
    }

    /* Standalone per-span VRAM copy (untracked/non-evictable). During pre-cache
     * (streaming not yet active) defer beyond-window spans to on-demand streaming
     * instead of burning the VRAM reserve here. At inference the fd-cache stream
     * path with eviction handles these, so this legacy fallback isn't reached. */
    if (!g_model_streaming_active) return NULL;

    void *dev = NULL;
    err = cudaMalloc(&dev, (size_t)bytes);
    if (err != cudaSuccess) {
        (void)cudaGetLastError();
        fprintf(stderr, "ds4: CUDA model range alloc failed for %s (%.2f MiB): %s\n",
                what ? what : "weights", (double)bytes / 1048576.0, cudaGetErrorString(err));
        return NULL;
    }

    const char *src = (const char *)model_map + offset;
    const uint64_t chunk = 64ull * 1024ull * 1024ull;
    for (uint64_t done = 0; done < bytes; done += chunk) {
        uint64_t n = bytes - done < chunk ? bytes - done : chunk;
        err = cudaMemcpy((char *)dev + done, src + done, (size_t)n, cudaMemcpyHostToDevice);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model range copy failed for %s at %.2f/%.2f MiB: %s\n",
                    what ? what : "weights",
                    (double)done / 1048576.0,
                    (double)bytes / 1048576.0,
                    cudaGetErrorString(err));
            (void)cudaFree(dev);
            (void)cudaGetLastError();
            return NULL;
        }
    }
    g_model_ranges.push_back({model_map, offset, bytes, (char *)dev, NULL, NULL, 0, 0, 0});
    g_model_range_by_offset[offset] = g_model_ranges.size() - 1u;
    g_model_range_bytes += bytes;
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA cached %s %.2f MiB (total %.2f GiB)\n",
                what ? what : "weights",
                (double)bytes / 1048576.0,
                (double)g_model_range_bytes / 1073741824.0);
    }
    return (const char *)dev;
}

static int cuda_model_range_is_cached(const void *model_map, uint64_t offset, uint64_t bytes) {
    if (bytes == 0) return 1;
    if (g_model_device_owned || g_model_registered) return 1;
    if (g_model_window_bytes && model_map == g_model_host_base && g_model_device_base &&
        offset + bytes <= g_model_window_bytes) return 1; /* served by the contiguous host window */

    const uint64_t end = offset + bytes;
    if (end < offset) return 0;
    for (const cuda_model_range &r : g_model_ranges) {
        if (r.host_base == model_map &&
            offset >= r.offset &&
            end <= r.offset + r.bytes) {
            return 1;
        }
        if (r.host_base == model_map &&
            r.host_registered &&
            r.registered_base &&
            r.registered_device_base) {
            const uintptr_t h0 = (uintptr_t)((const char *)model_map + offset);
            const uintptr_t h1 = h0 + bytes;
            const uintptr_t r0 = (uintptr_t)r.registered_base;
            const uintptr_t r1 = r0 + r.registered_bytes;
            if (h1 >= h0 && h0 >= r0 && h1 <= r1) return 1;
        }
    }
    return 0;
}

static void cuda_q8_f16_cache_release_all(void) {
    for (const cuda_q8_f16_range &r : g_q8_f16_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f16_ranges.clear();
    g_q8_f16_by_offset.clear();
    g_q8_f16_bytes = 0;
}

static uint64_t cuda_parse_mib_env(const char *name, int *present) {
    const char *env = getenv(name);
    if (present) *present = 0;
    if (!env || !env[0]) return 0;
    char *end = NULL;
    unsigned long long v = strtoull(env, &end, 10);
    if (end == env || *end != '\0') return 0;
    if (present) *present = 1;
    if (v > UINT64_MAX / 1048576ull) return UINT64_MAX;
    return (uint64_t)v * 1048576ull;
}

static uint64_t cuda_q8_f16_cache_limit_bytes(void) {
    int present = 0;
    const uint64_t limit = cuda_parse_mib_env("DS4_CUDA_Q8_F16_CACHE_MB", &present);
    return present ? limit : UINT64_MAX;
}

static uint64_t cuda_q8_f16_cache_reserve_bytes(uint64_t total_bytes) {
    int present = 0;
    const uint64_t reserve = cuda_parse_mib_env("DS4_CUDA_Q8_F16_CACHE_RESERVE_MB", &present);
    if (present) return reserve;

    /* The expanded Q8->F16 cache is only an acceleration path.  Keep enough
     * device memory free for cuBLAS workspaces, transient graph buffers, and
     * driver bookkeeping instead of letting optional cached weights consume the
     * last few GiB on 96 GiB cards. */
    const uint64_t min_reserve = 4096ull * 1048576ull;
    const uint64_t pct_reserve = total_bytes / 20u; /* 5% */
    return pct_reserve > min_reserve ? pct_reserve : min_reserve;
}

static void cuda_q8_f16_cache_budget_notice(
        const char *reason,
        uint64_t request_bytes,
        uint64_t free_bytes,
        uint64_t total_bytes,
        uint64_t reserve_bytes,
        uint64_t limit_bytes) {
    if (g_q8_f16_budget_notice_printed && getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE") == NULL) return;
    g_q8_f16_budget_notice_printed = 1;
    if (limit_bytes != UINT64_MAX && free_bytes == 0 && total_bytes == 0 && reserve_bytes == 0) {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache %s; using q8 kernels "
                "(request=%.2f MiB cached=%.2f GiB limit=%.2f GiB)\n",
                reason,
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0,
                (double)limit_bytes / 1073741824.0);
    } else if (limit_bytes == UINT64_MAX) {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache %s; using q8 kernels "
                "(request=%.2f MiB cached=%.2f GiB free=%.2f GiB reserve=%.2f GiB total=%.2f GiB)\n",
                reason,
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0,
                (double)free_bytes / 1073741824.0,
                (double)reserve_bytes / 1073741824.0,
                (double)total_bytes / 1073741824.0);
    } else {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache %s; using q8 kernels "
                "(request=%.2f MiB cached=%.2f GiB limit=%.2f GiB free=%.2f GiB reserve=%.2f GiB total=%.2f GiB)\n",
                reason,
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0,
                (double)limit_bytes / 1073741824.0,
                (double)free_bytes / 1073741824.0,
                (double)reserve_bytes / 1073741824.0,
                (double)total_bytes / 1073741824.0);
    }
}

static int cuda_q8_f16_cache_has_budget(uint64_t request_bytes, const char *label) {
    (void)label;
    const uint64_t limit = cuda_q8_f16_cache_limit_bytes();
    if (limit == 0) return 0;
    if (g_q8_f16_bytes > limit || request_bytes > limit - g_q8_f16_bytes) {
        cuda_q8_f16_cache_budget_notice("limit reached", request_bytes, 0, 0, 0, limit);
        return 0;
    }

    size_t free_b = 0;
    size_t total_b = 0;
    cudaError_t err = cudaMemGetInfo(&free_b, &total_b);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA q8 fp16 cache memory query failed: %s; using q8 kernels\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }

    const uint64_t free_bytes = (uint64_t)free_b;
    const uint64_t total_bytes = (uint64_t)total_b;
    const uint64_t reserve_bytes = cuda_q8_f16_cache_reserve_bytes(total_bytes);
    if (request_bytes > free_bytes ||
        free_bytes - request_bytes < reserve_bytes) {
        cuda_q8_f16_cache_budget_notice("budget exhausted", request_bytes,
                                        free_bytes, total_bytes,
                                        reserve_bytes, limit);
        return 0;
    }
    return 1;
}

static void cuda_q8_f16_cache_disable_after_failure(const char *what, uint64_t request_bytes) {
    if (!g_q8_f16_disabled_after_oom) {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache disabled after %s "
                "(request=%.2f MiB cached=%.2f GiB); using q8 kernels\n",
                what ? what : "allocation failure",
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0);
    }
    g_q8_f16_disabled_after_oom = 1;
    if (!g_q8_f16_ranges.empty()) {
        (void)cudaDeviceSynchronize();
        cuda_q8_f16_cache_release_all();
    }
    (void)cudaGetLastError();
}

static int cuda_q8_f16_cache_allowed(const char *label, uint64_t in_dim, uint64_t out_dim) {
    if (g_quality_mode) return 0;
    if (g_q8_f16_disabled_after_oom) return 0;
    if (getenv("DS4_CUDA_NO_Q8_F16_CACHE") != NULL) return 0;
    if (cuda_q8_f16_cache_limit_bytes() == 0) return 0;
    if (getenv("DS4_CUDA_Q8_F16_ALL") != NULL) return 1;
    if (!label) return 0;
    if (strstr(label, "attn_output_a") != NULL ||
        strstr(label, "attn_output_b") != NULL ||
        strstr(label, "attention_output_a") != NULL ||
        strstr(label, "attention_output_b") != NULL) {
        return getenv("DS4_CUDA_NO_ATTENTION_OUTPUT_F16_CACHE") == NULL;
    }
    if (strstr(label, "attn_q_b") != NULL) {
        return getenv("DS4_CUDA_NO_ATTN_Q_B_F16_CACHE") == NULL;
    }
    if (strstr(label, "ffn_gate_shexp") != NULL ||
        strstr(label, "ffn_up_shexp") != NULL ||
        strstr(label, "ffn_down_shexp") != NULL) {
        return 1;
    }
    return (in_dim == 4096u && out_dim == 2048u) ||
           (in_dim == 2048u && out_dim == 4096u) ||
           (in_dim == 4096u && out_dim == 1024u) ||
           (in_dim == 4096u && out_dim == 512u) ||
           (getenv("DS4_CUDA_NO_ATTN_Q_B_F16_CACHE") == NULL &&
            in_dim == 1024u && out_dim == 32768u);
}

static int cuda_q8_label_is_attention_output(const char *label) {
    return label &&
           (strstr(label, "attn_output_a") != NULL ||
            strstr(label, "attn_output_b") != NULL ||
            strstr(label, "attention_output_a") != NULL ||
            strstr(label, "attention_output_b") != NULL);
}

static int cuda_q8_use_dp4a(void) {
    return getenv("DS4_CUDA_NO_Q8_DP4A") == NULL;
}

static int cuda_q8_f16_preload_allowed(const char *label, uint64_t in_dim, uint64_t out_dim) {
    if (cuda_q8_label_is_attention_output(label) &&
        getenv("DS4_CUDA_ATTENTION_OUTPUT_PRELOAD") == NULL &&
        getenv("DS4_CUDA_Q8_F16_ALL") == NULL) {
        return 0;
    }
    return cuda_q8_f16_cache_allowed(label, in_dim, out_dim);
}

static int cuda_q8_f32_cache_allowed(const char *label, uint64_t in_dim, uint64_t out_dim) {
    if (getenv("DS4_CUDA_NO_Q8_F32_CACHE") != NULL) return 0;
    if (getenv("DS4_CUDA_Q8_F32_ALL") != NULL) return 1;
    if (label && strstr(label, "attn_q_b") != NULL) {
        return getenv("DS4_CUDA_ATTN_Q_B_F32_CACHE") != NULL;
    }
    return getenv("DS4_CUDA_Q8_F32_LARGE") != NULL &&
           in_dim == 1024u && out_dim == 32768u;
}

static const __half *cuda_q8_f16_ptr(
        const void *model_map,
        uint64_t offset,
        uint64_t weight_bytes,
        uint64_t in_dim,
        uint64_t out_dim,
        const char *label) {
    auto exact = g_q8_f16_by_offset.find(offset);
    if (exact != g_q8_f16_by_offset.end()) {
        const cuda_q8_f16_range &r = g_q8_f16_ranges[exact->second];
        if (r.host_base == model_map && r.weight_bytes == weight_bytes &&
            r.in_dim == in_dim && r.out_dim == out_dim) {
            return r.device_ptr;
        }
    }
    if (!cuda_q8_f16_cache_allowed(label, in_dim, out_dim)) return NULL;

    const char *q8 = cuda_model_range_ptr(model_map, offset, weight_bytes, "q8_0");
    if (!q8) return NULL;

    if (in_dim != 0 && out_dim > UINT64_MAX / in_dim / sizeof(__half)) return NULL;
    const uint64_t out_bytes = in_dim * out_dim * sizeof(__half);
    if (!cuda_q8_f16_cache_has_budget(out_bytes, label)) return NULL;

    __half *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)out_bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA q8 fp16 cache alloc failed (%.2f MiB): %s\n",
                (double)out_bytes / 1048576.0, cudaGetErrorString(err));
        cuda_q8_f16_cache_disable_after_failure("allocation failure", out_bytes);
        return NULL;
    }
    const uint64_t blocks = (in_dim + 31) / 32;
    const uint64_t n = in_dim * out_dim;
    dequant_q8_0_to_f16_kernel<<<(n + 255) / 256, 256>>>(dev,
                                                          (const unsigned char *)q8,
                                                          in_dim,
                                                          out_dim,
                                                          blocks);
    if (!cuda_ok(cudaGetLastError(), "q8 fp16 dequant launch")) {
        (void)cudaFree(dev);
        cuda_q8_f16_cache_disable_after_failure("dequant launch failure", out_bytes);
        return NULL;
    }
    g_q8_f16_ranges.push_back({model_map, offset, weight_bytes, in_dim, out_dim, dev});
    g_q8_f16_by_offset[offset] = g_q8_f16_ranges.size() - 1u;
    g_q8_f16_bytes += out_bytes;
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA cached q8 fp16 %.2f MiB (total %.2f GiB)\n",
                (double)out_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0);
    }
    return dev;
}

static float *cuda_q8_f32_ptr(
        const void *model_map,
        uint64_t offset,
        uint64_t weight_bytes,
        uint64_t in_dim,
        uint64_t out_dim,
        const char *label) {
    auto exact = g_q8_f32_by_offset.find(offset);
    if (exact != g_q8_f32_by_offset.end()) {
        const cuda_q8_f32_range &r = g_q8_f32_ranges[exact->second];
        if (r.host_base == model_map && r.weight_bytes == weight_bytes &&
            r.in_dim == in_dim && r.out_dim == out_dim) {
            return r.device_ptr;
        }
    }
    if (!cuda_q8_f32_cache_allowed(label, in_dim, out_dim)) return NULL;

    const char *q8 = cuda_model_range_ptr(model_map, offset, weight_bytes, label ? label : "q8_0");
    if (!q8) return NULL;

    const uint64_t out_bytes = in_dim * out_dim * sizeof(float);
    float *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)out_bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA q8 fp32 cache alloc failed (%.2f MiB): %s\n",
                (double)out_bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return NULL;
    }
    const uint64_t blocks = (in_dim + 31) / 32;
    const uint64_t n = in_dim * out_dim;
    dequant_q8_0_to_f32_kernel<<<(n + 255) / 256, 256>>>(dev,
                                                          (const unsigned char *)q8,
                                                          in_dim,
                                                          out_dim,
                                                          blocks);
    if (!cuda_ok(cudaGetLastError(), "q8 fp32 dequant launch")) {
        (void)cudaFree(dev);
        return NULL;
    }
    g_q8_f32_ranges.push_back({model_map, offset, weight_bytes, in_dim, out_dim, dev});
    g_q8_f32_by_offset[offset] = g_q8_f32_ranges.size() - 1u;
    g_q8_f32_bytes += out_bytes;
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA cached q8 fp32 %.2f MiB (total %.2f GiB)\n",
                (double)out_bytes / 1048576.0,
                (double)g_q8_f32_bytes / 1073741824.0);
    }
    return dev;
}

static int cuda_ok(cudaError_t err, const char *what) {
    if (err == cudaSuccess) return 1;
    fprintf(stderr, "ds4: CUDA %s failed: %s\n", what, cudaGetErrorString(err));
    return 0;
}

static double cuda_wall_sec(void) {
    return os_monotonic_sec();
}

/* =======================================================================
 * WORKER-PROF - scomposizione del tempo del route worker.
 *
 * Flag: DS4_CUDA_WORKER_PROFILE (default 0 = nessun timer letto, nessuna
 * riga, comportamento identico).  DS4_CUDA_WORKER_PROFILE_EVERY_TOKENS
 * (default 32) governa ogni quanti token esce la riga [worker-prof].
 *
 * PERCHE' QUI E NON ATTORNO.  worker_wait_ms (route_ready_wait_seconds) dice
 * QUANTO il thread di decode aspetta il route worker, non DOVE finisce quel
 * tempo.  Tutto cio' che era gia' strumentato - t_deliver_ms, t_orchestration_ms,
 * t_drain_ms, sfratti, byte - misura attorno al worker.  Questi contatori
 * spezzano l'attesa ai DUE capi dello stesso rendezvous:
 *
 *   wait = [pickup_lag] + [job] + [notice] + residuo
 *
 *   pickup_lag : dall'istante in cui il thread di decode entra nell'attesa
 *                (cuda_moe_gpu_resident_routes_finish, wait_started)
 *                all'istante in cui il worker vede la nuova sequence;
 *   job        : dal pickup del worker alla scrittura di route_ready_host,
 *                scomposto in lettura / fill nested / staging / consegna H2D /
 *                pubblicazione route_ptrs / handshake / drain / scelta slot;
 *   notice     : dalla pubblicazione di ready all'uscita dallo spin del
 *                thread di decode.
 *
 * Il residuo NON viene stimato: viene stampato, sia dentro il job
 * (job_residual_ms) sia sull'attesa completa (wait_residual_ms).  Se resta
 * grande e' li' che va cercato il tempo, ed e' l'informazione piu' preziosa
 * della riga.
 *
 * queue_ms non e' un addendo della quadratura: misura submit del kernel
 * resolver -> pickup, quindi include la latenza del resolver GPU.  E' li'
 * per dire se il lavoro ARRIVA tardi invece che essere PRESO tardi.
 *
 * Le attese che il worker non ha mai servito - i layer all-hit chiusi dalla
 * GPU stessa quando defer_all_hit_ready = 0, cioe' con G73 spento - finiscono
 * in wait_no_worker_ms.  E' tempo che il worker non puo' spiegare per
 * costruzione e va letto come tale, non sottratto di nascosto.
 *
 * COSTO.  A flag acceso: un QueryPerformanceCounter per evento aggregato e un
 * fetch_add relaxed; nessun log per evento, nessuna allocazione, nessun
 * campo per-job.  A flag spento: un int cachato e un ramo prevedibile.
 * ======================================================================= */
enum {
    WP_JOBS = 0,
    WP_JOB_NS,
    WP_QUEUE_NS,
    WP_IDLE_TOKEN_NS,
    WP_IDLE_FREE_NS,
    WP_IDLE_EDGE_NS,
    WP_READ_GATE_NS,
    WP_READ_UP_NS,
    WP_READ_DOWN_NS,
    WP_READ_QD_NS,
    WP_READ_OTHER_NS,
    WP_LOAD_RAM_NS,
    WP_NESTED_FILL_NS,
    WP_COPY_NS,
    WP_DELIVER_NS,
    WP_PUBLISH_NS,
    WP_SIGNAL_NS,
    WP_DRAIN_NS,
    WP_SLOTPICK_NS,
    WP_WRAP_POLL_NS,
    WP_READ_CALLS,
    WP_READ_BYTES,
    WP_FAULTS,
    WP_INFLIGHT_INTEGRAL_NS,
    WP_INFLIGHT_BUSY_NS,
    WP_WAITS,
    WP_WAIT_NS,
    WP_WAITS_NO_WORKER,
    WP_WAIT_NO_WORKER_NS,
    WP_PICKUP_LAG_NS,
    WP_PICKUP_EARLY,
    WP_NOTICE_NS,
    /* DRAIN3-STRUM (leva P.2, drain sovrapposto al compute).  Le prime due
     * voci sono quelle richieste per giudicare un eventuale braccio overlap:
     * oggi restano a zero PER COSTRUZIONE (il drain e' bloccante, niente si
     * sovrappone) e stampano la riga di base.  Le altre quattro sono i
     * discriminatori del fallimento 28/7 (abort transient-io-timeout con
     * worker idle_token 13,6 s/token): budget del guardiano residuo al primo
     * ingresso transiente e conteggio delle invalidazioni di cache.  Nessun
     * sito caldo le alimenta con DS4_CUDA_WORKER_PROFILE spento. */
    WP_DRAIN_OVERLAP_NS,
    WP_GPU_STALL_ON_DRAIN_NS,
    WP_DEADLINE_SLACK_NS,
    WP_DEADLINE_SLACK_EVENTS,
    WP_DEADLINE_EXHAUSTED,
    WP_CACHE_INVALIDATES,
    /* INVALIDATE-SCOPED: eventi di rollback mirato (per richiesta fallita) e
     * voci coinvolte, tenuti separati dal reset totale.  Le voci VALID
     * buttate da ogni reset totale rendono giudicabile il costo reale di
     * ciascun evento: un reset a cache vuota (avvio) pesa zero. */
    WP_CACHE_INVALIDATES_SCOPED,
    WP_CACHE_SCOPED_ENTRIES_DROPPED,
    WP_CACHE_FULL_VALID_DROPPED,
    WP_TOKENS,
    WP_COUNT
};

/* Zero-inizializzati per durata di memorizzazione statica, prima di ogni
 * inizializzazione dinamica: nessun costruttore da eseguire. */
static std::atomic<uint64_t> g_workerprof_c[WP_COUNT];
static std::atomic<uint32_t> g_workerprof_inflight_max(0u);
static uint64_t g_workerprof_prev[WP_COUNT];
static uint64_t g_workerprof_next_token_log;

/* Rendezvous fra thread di decode e route worker.  Ogni coppia (sequence,
 * istante) e' pubblicata scrivendo prima l'istante e poi la sequence con una
 * release; il lettore fa acquire sulla sequence e accetta l'istante solo se
 * la sequence combacia con quella che sta trattando.  Una coppia scartata
 * costa un contatore, mai una stima. */
static std::atomic<uint32_t> g_workerprof_submit_seq(0u);
static std::atomic<uint64_t> g_workerprof_submit_ns(0u);
static std::atomic<uint32_t> g_workerprof_wait_seq(0u);
static std::atomic<uint64_t> g_workerprof_wait_ns(0u);
static std::atomic<uint32_t> g_workerprof_pickup_seq(0u);
static std::atomic<uint64_t> g_workerprof_pickup_ns(0u);
static std::atomic<uint32_t> g_workerprof_ready_seq(0u);
static std::atomic<uint64_t> g_workerprof_ready_ns(0u);
static std::atomic<int> g_workerprof_token_active(0);

/* Base monotona presa una sola volta: tiene i nanosecondi lontani dal limite
 * di precisione del double anche su una macchina accesa da settimane. */
static const double g_workerprof_base_sec = os_monotonic_sec();

static int cuda_worker_profile_enabled(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_WORKER_PROFILE");
        cached = (env != NULL && env[0] != '\0' && env[0] != '0') ? 1 : 0;
    }
    return cached;
}

/* Budget di polling attivo del route worker dopo ogni job durante un token.
 * Zero conserva il percorso storico: yield immediato a ogni poll vuoto. */
static uint32_t cuda_worker_pickup_spin_us(void) {
    static int resolved = 0;
    static uint32_t cached = 0u;
    if (resolved) return cached;
    resolved = 1;
    const char *env = getenv("DS4_CUDA_WORKER_PICKUP_SPIN_US");
    if (!env || !env[0] || strcmp(env, "0") == 0) return cached;
    char *end = NULL;
    errno = 0;
    const unsigned long value = strtoul(env, &end, 10);
    if (errno == 0 && end != env && end && *end == '\0' &&
        value <= 1000000ul) {
        cached = (uint32_t)value;
    } else {
        fprintf(stderr,
                "ds4: invalid DS4_CUDA_WORKER_PICKUP_SPIN_US=%s "
                "(expected 0..1000000); using 0\n",
                env);
    }
    return cached;
}

static inline void ds4_worker_pickup_pause(void) {
#ifdef _WIN32
    YieldProcessor();
#elif defined(__i386__) || defined(__x86_64__)
    __builtin_ia32_pause();
#else
    std::atomic_signal_fence(std::memory_order_seq_cst);
#endif
}

static uint64_t cuda_worker_profile_every_tokens(void) {
    static int resolved = 0;
    static uint64_t cached = 32ull;
    if (resolved) return cached;
    resolved = 1;
    const char *env = getenv("DS4_CUDA_WORKER_PROFILE_EVERY_TOKENS");
    if (env && env[0]) {
        char *end = NULL;
        errno = 0;
        const unsigned long long value = strtoull(env, &end, 10);
        if (end != env && errno == 0 && end && *end == '\0' && value > 0ull) {
            cached = (uint64_t)value;
        } else {
            fprintf(stderr,
                    "ds4: invalid DS4_CUDA_WORKER_PROFILE_EVERY_TOKENS=%s; "
                    "using 32\n",
                    env);
        }
    }
    return cached;
}

static inline uint64_t ds4_workerprof_now_ns(void) {
    const double delta = cuda_wall_sec() - g_workerprof_base_sec;
    return delta > 0.0 ? (uint64_t)(delta * 1.0e9) : 0u;
}

static inline void ds4_workerprof_add(int index, uint64_t value) {
    g_workerprof_c[index].fetch_add(value, std::memory_order_relaxed);
}

static inline uint64_t ds4_workerprof_span_ns(uint64_t from_ns, uint64_t to_ns) {
    return to_ns > from_ns ? to_ns - from_ns : 0u;
}

/* Stato delle letture in volo.  Toccato SOLO dal route worker: entrambe le
 * letture strumentate (pread a chunk e overlapped QD4) girano su quel thread,
 * quindi non serve sincronizzazione sullo stato corrente.  Gli aggregati
 * pubblicati sono atomici perche' l'emettitore li legge dal thread di decode.
 *
 * L'integrale e' pesato sul tempo: inflight_avg = integrale / busy risponde
 * "quante letture erano davvero contemporanee MENTRE si leggeva", che e' la
 * misura che conferma o falsifica la serializzazione. */
static uint32_t g_workerprof_inflight;
static uint64_t g_workerprof_inflight_mark_ns;

static void ds4_workerprof_inflight_advance(uint64_t now_ns, int delta) {
    if (g_workerprof_inflight_mark_ns != 0u && g_workerprof_inflight != 0u) {
        const uint64_t dt =
            ds4_workerprof_span_ns(g_workerprof_inflight_mark_ns, now_ns);
        if (dt != 0u) {
            ds4_workerprof_add(WP_INFLIGHT_INTEGRAL_NS,
                               dt * (uint64_t)g_workerprof_inflight);
            ds4_workerprof_add(WP_INFLIGHT_BUSY_NS, dt);
        }
    }
    g_workerprof_inflight_mark_ns = now_ns;
    if (delta > 0) {
        g_workerprof_inflight += (uint32_t)delta;
        if (g_workerprof_inflight >
            g_workerprof_inflight_max.load(std::memory_order_relaxed)) {
            g_workerprof_inflight_max.store(
                g_workerprof_inflight, std::memory_order_relaxed);
        }
    } else if (delta < 0) {
        const uint32_t drop = (uint32_t)(-delta);
        g_workerprof_inflight =
            g_workerprof_inflight > drop ? g_workerprof_inflight - drop : 0u;
    }
}

/* Falli di pagina del processo, campionati ai due capi del job.
 *
 * Serve perche' i contatori di I/O del PROCESSO restano fermi mentre il disco
 * legge: i byte arrivano da pagine mappate, e un fault dentro una memcpy non
 * passa da nessuna read.  Senza questa voce il tempo speso a impaginare
 * sarebbe indistinguibile dal residuo, e il residuo direbbe "non lo so" dove
 * invece la risposta esiste.
 *
 * Attenzione a come si legge: PageFaultCount conta soft + hard.  Un delta
 * grande NON prova da solo che si e' andati su disco; un delta ~zero invece
 * ESCLUDE che i byte del job siano arrivati impaginando.  E' un test a una
 * coda, e va usato come tale.  Fuori da Windows resta 0 e la riga lo mostra. */
static inline uint64_t ds4_workerprof_faults_now(int prof) {
    if (!prof) return 0u;
#ifdef _WIN32
    PROCESS_MEMORY_COUNTERS counters;
    memset(&counters, 0, sizeof(counters));
    counters.cb = sizeof(counters);
    if (!GetProcessMemoryInfo(
            GetCurrentProcess(), &counters, sizeof(counters))) {
        return 0u;
    }
    return (uint64_t)counters.PageFaultCount;
#else
    return 0u;
#endif
}

/* Una singola richiesta di lettura entra in volo. */
static inline uint64_t ds4_workerprof_read_begin(int prof) {
    if (!prof) return 0u;
    const uint64_t now = ds4_workerprof_now_ns();
    ds4_workerprof_inflight_advance(now, 1);
    return now;
}

static inline void ds4_workerprof_read_end(int prof, int64_t got) {
    if (!prof) return;
    ds4_workerprof_inflight_advance(ds4_workerprof_now_ns(), -1);
    ds4_workerprof_add(WP_READ_CALLS, 1u);
    if (got > 0) ds4_workerprof_add(WP_READ_BYTES, (uint64_t)got);
}

/* Voce cronometrata al sito di chiamata: restituisce l'istante di inizio, o 0
 * a flag spento (e in quel caso ds4_workerprof_stop non fa nulla). */
static inline uint64_t ds4_workerprof_start(int prof) {
    return prof ? ds4_workerprof_now_ns() : 0u;
}

static inline void ds4_workerprof_stop(int prof, int index, uint64_t started_ns) {
    if (!prof) return;
    ds4_workerprof_add(
        index, ds4_workerprof_span_ns(started_ns, ds4_workerprof_now_ns()));
}

/* Variante per i siti che hanno gia' misurato il delta con un altro
 * cronometro (t_deliver_ms, t_drain_ms): riusa il numero, non ricronometra. */
static inline void ds4_workerprof_add_ms(int prof, int index, double ms) {
    if (!prof || !(ms > 0.0)) return;
    ds4_workerprof_add(index, (uint64_t)(ms * 1.0e6));
}

static void ds4_workerprof_publish_submit(int prof, uint32_t sequence) {
    if (!prof) return;
    g_workerprof_submit_ns.store(
        ds4_workerprof_now_ns(), std::memory_order_relaxed);
    g_workerprof_submit_seq.store(sequence, std::memory_order_release);
}

static void ds4_workerprof_publish_wait_start(
        int prof, uint32_t sequence, double wait_started_sec) {
    if (!prof) return;
    const double delta = wait_started_sec - g_workerprof_base_sec;
    g_workerprof_wait_ns.store(
        delta > 0.0 ? (uint64_t)(delta * 1.0e9) : 0u,
        std::memory_order_relaxed);
    g_workerprof_wait_seq.store(sequence, std::memory_order_release);
}

/* Ozio del worker.  Lo stato "token in corso" viene campionato all'inizio e
 * alla fine dell'intervallo di attesa: se combacia, l'intervallo e' attribuito
 * senza ambiguita'; se cambia, finisce in idle_edge invece di essere assegnato
 * a caso a uno dei due.  idle_token_ms e' la voce che risponde alla domanda
 * "il worker stava fermo mentre un token era in volo?". */
static void ds4_workerprof_note_idle(
        int prof, uint64_t from_ns, uint64_t to_ns, int token_at_start) {
    if (!prof || from_ns == 0u) return;
    const uint64_t dt = ds4_workerprof_span_ns(from_ns, to_ns);
    if (dt == 0u) return;
    const int token_at_end =
        g_workerprof_token_active.load(std::memory_order_acquire);
    if (token_at_start != token_at_end) {
        ds4_workerprof_add(WP_IDLE_EDGE_NS, dt);
    } else if (token_at_end) {
        ds4_workerprof_add(WP_IDLE_TOKEN_NS, dt);
    } else {
        ds4_workerprof_add(WP_IDLE_FREE_NS, dt);
    }
}

static void ds4_workerprof_publish_pickup(
        int prof, uint32_t sequence, uint64_t pickup_ns) {
    if (!prof) return;
    const uint32_t submit_seq =
        g_workerprof_submit_seq.load(std::memory_order_acquire);
    if (submit_seq == sequence) {
        ds4_workerprof_add(
            WP_QUEUE_NS,
            ds4_workerprof_span_ns(
                g_workerprof_submit_ns.load(std::memory_order_relaxed),
                pickup_ns));
    }
    g_workerprof_pickup_ns.store(pickup_ns, std::memory_order_relaxed);
    g_workerprof_pickup_seq.store(sequence, std::memory_order_release);
}

/* Chiusura del job: il worker ha finito di servire questa sequence.
 * Restituisce l'istante di chiusura cosi' il chiamante puo' riusarlo. */
static uint64_t ds4_workerprof_note_job_end(
        int prof, uint64_t pickup_ns, uint64_t faults_at_pickup) {
    if (!prof) return 0u;
    const uint64_t now = ds4_workerprof_now_ns();
    ds4_workerprof_add(WP_JOBS, 1u);
    ds4_workerprof_add(WP_JOB_NS, ds4_workerprof_span_ns(pickup_ns, now));
    const uint64_t faults_now = ds4_workerprof_faults_now(prof);
    if (faults_now > faults_at_pickup) {
        ds4_workerprof_add(WP_FAULTS, faults_now - faults_at_pickup);
    }
    return now;
}

/* Pubblicato SOLO dove route_ready_host viene davvero scritto dal worker.
 * Sui layer all-hit con G73 spento e' la GPU a rilasciare il chiamante: in
 * quel caso qui non si pubblica nulla e notice_ms resta correttamente vuoto
 * invece di misurare un rendezvous che non e' avvenuto. */
static void ds4_workerprof_publish_ready(
        int prof, uint32_t sequence, uint64_t ready_ns) {
    if (!prof) return;
    g_workerprof_ready_ns.store(ready_ns, std::memory_order_relaxed);
    g_workerprof_ready_seq.store(sequence, std::memory_order_release);
}

/* Chiusura dell'attesa, lato thread di decode.  ready_wait_seconds e' lo
 * stesso numero che alimenta worker_wait_ms, quindi la quadratura si chiude
 * sulla grandezza che il committente ha misurato, non su una sua copia. */
static void ds4_workerprof_note_wait(
        int prof, uint32_t sequence, double ready_wait_seconds) {
    if (!prof) return;
    const uint64_t now = ds4_workerprof_now_ns();
    const uint64_t wait_ns = ready_wait_seconds > 0.0
        ? (uint64_t)(ready_wait_seconds * 1.0e9) : 0u;
    ds4_workerprof_add(WP_WAITS, 1u);
    ds4_workerprof_add(WP_WAIT_NS, wait_ns);
    if (g_workerprof_pickup_seq.load(std::memory_order_acquire) != sequence) {
        /* Il worker non ha mai visto questa sequence: layer all-hit chiuso
         * dalla GPU.  Non e' tempo del worker e non viene attribuito. */
        ds4_workerprof_add(WP_WAITS_NO_WORKER, 1u);
        ds4_workerprof_add(WP_WAIT_NO_WORKER_NS, wait_ns);
        return;
    }
    const uint64_t pickup_ns =
        g_workerprof_pickup_ns.load(std::memory_order_relaxed);
    if (g_workerprof_wait_seq.load(std::memory_order_acquire) == sequence) {
        const uint64_t wait_started_ns =
            g_workerprof_wait_ns.load(std::memory_order_relaxed);
        if (pickup_ns >= wait_started_ns) {
            ds4_workerprof_add(
                WP_PICKUP_LAG_NS,
                ds4_workerprof_span_ns(wait_started_ns, pickup_ns));
        } else {
            /* Il worker era gia' partito prima che il chiamante entrasse
             * nell'attesa: pickup_lag e' zero per definizione, e il caso si
             * conta invece di essere assorbito in un numero negativo. */
            ds4_workerprof_add(WP_PICKUP_EARLY, 1u);
        }
    }
    if (g_workerprof_ready_seq.load(std::memory_order_acquire) == sequence) {
        ds4_workerprof_add(
            WP_NOTICE_NS,
            ds4_workerprof_span_ns(
                g_workerprof_ready_ns.load(std::memory_order_relaxed), now));
    }
}

static void ds4_workerprof_report(const char *tag) {
    if (!cuda_worker_profile_enabled()) return;
    uint64_t cur[WP_COUNT];
    uint64_t win[WP_COUNT];
    for (int i = 0; i < WP_COUNT; i++) {
        cur[i] = g_workerprof_c[i].load(std::memory_order_relaxed);
        win[i] = cur[i] - g_workerprof_prev[i];
    }
    /* inflight_max e' il PICCO DI SEMPRE, non della finestra: un massimo
     * azzerato a ogni riga direbbe solo cosa e' successo negli ultimi N token,
     * mentre la domanda e' se il runtime abbia MAI messo in volo piu' di una
     * lettura per volta.  inflight_avg invece e' della finestra. */
    const uint32_t inflight_max =
        g_workerprof_inflight_max.load(std::memory_order_relaxed);
    const int final_line = tag && strcmp(tag, "final") == 0;
    const uint64_t *v = final_line ? cur : win;

    const double ms = 1.0e-6;
    const double read_total_ms =
        (double)(v[WP_READ_GATE_NS] + v[WP_READ_UP_NS] + v[WP_READ_DOWN_NS] +
                 v[WP_READ_QD_NS] + v[WP_READ_OTHER_NS]) * ms;
    const double attributed_ms = read_total_ms +
        (double)(v[WP_LOAD_RAM_NS] +
                 v[WP_NESTED_FILL_NS] + v[WP_COPY_NS] + v[WP_DELIVER_NS] +
                 v[WP_PUBLISH_NS] + v[WP_SIGNAL_NS] + v[WP_DRAIN_NS] +
                 v[WP_SLOTPICK_NS] + v[WP_WRAP_POLL_NS]) * ms;
    const double job_ms = (double)v[WP_JOB_NS] * ms;
    const double wait_ms = (double)v[WP_WAIT_NS] * ms;
    const double wait_no_worker_ms = (double)v[WP_WAIT_NO_WORKER_NS] * ms;
    const double pickup_lag_ms = (double)v[WP_PICKUP_LAG_NS] * ms;
    const double notice_ms = (double)v[WP_NOTICE_NS] * ms;
    const double tokens = (double)v[WP_TOKENS];
    const double read_seconds = read_total_ms * 1.0e-3;

    fprintf(stderr,
            "ds4: [worker-prof] %s tokens=%llu waits=%llu jobs=%llu "
            "wait_ms=%.3f wait_no_worker_ms=%.3f waits_no_worker=%llu "
            "pickup_lag_ms=%.3f pickup_early=%llu job_ms=%.3f notice_ms=%.3f "
            "wait_residual_ms=%.3f queue_ms=%.3f idle_token_ms=%.3f "
            "idle_free_ms=%.3f idle_edge_ms=%.3f read_gate_ms=%.3f "
            "read_up_ms=%.3f read_down_ms=%.3f read_qd_ms=%.3f "
            "read_other_ms=%.3f read_total_ms=%.3f load_ram_ms=%.3f "
            "nested_fill_ms=%.3f "
            "copy_ms=%.3f deliver_ms=%.3f publish_ms=%.3f signal_ms=%.3f "
            "drain_ms=%.3f slotpick_ms=%.3f wrap_poll_ms=%.3f "
            "job_residual_ms=%.3f "
            "read_calls=%llu read_bytes=%llu read_mb_s=%.1f "
            "job_faults=%llu job_faults_per_token=%.1f "
            "inflight_max=%u inflight_avg=%.2f inflight_busy_ms=%.3f "
            "wait_ms_per_token=%.3f read_ms_per_token=%.3f "
            "read_calls_per_token=%.1f "
            "drain_overlap_ms=%.3f gpu_stall_on_drain_ms=%.3f "
            "deadline_slack_ms=%.3f deadline_slack_events=%llu "
            "deadline_exhausted=%llu cache_invalidates_total=%llu "
            "cache_invalidates_scoped=%llu cache_scoped_entries_dropped=%llu "
            "cache_full_valid_dropped=%llu\n",
            tag ? tag : "periodic",
            (unsigned long long)v[WP_TOKENS],
            (unsigned long long)v[WP_WAITS],
            (unsigned long long)v[WP_JOBS],
            wait_ms, wait_no_worker_ms,
            (unsigned long long)v[WP_WAITS_NO_WORKER],
            pickup_lag_ms,
            (unsigned long long)v[WP_PICKUP_EARLY],
            job_ms, notice_ms,
            wait_ms - wait_no_worker_ms - pickup_lag_ms - job_ms - notice_ms,
            (double)v[WP_QUEUE_NS] * ms,
            (double)v[WP_IDLE_TOKEN_NS] * ms,
            (double)v[WP_IDLE_FREE_NS] * ms,
            (double)v[WP_IDLE_EDGE_NS] * ms,
            (double)v[WP_READ_GATE_NS] * ms,
            (double)v[WP_READ_UP_NS] * ms,
            (double)v[WP_READ_DOWN_NS] * ms,
            (double)v[WP_READ_QD_NS] * ms,
            (double)v[WP_READ_OTHER_NS] * ms,
            read_total_ms,
            (double)v[WP_LOAD_RAM_NS] * ms,
            (double)v[WP_NESTED_FILL_NS] * ms,
            (double)v[WP_COPY_NS] * ms,
            (double)v[WP_DELIVER_NS] * ms,
            (double)v[WP_PUBLISH_NS] * ms,
            (double)v[WP_SIGNAL_NS] * ms,
            (double)v[WP_DRAIN_NS] * ms,
            (double)v[WP_SLOTPICK_NS] * ms,
            (double)v[WP_WRAP_POLL_NS] * ms,
            job_ms - attributed_ms,
            (unsigned long long)v[WP_READ_CALLS],
            (unsigned long long)v[WP_READ_BYTES],
            read_seconds > 0.0
                ? (double)v[WP_READ_BYTES] / 1048576.0 / read_seconds : 0.0,
            (unsigned long long)v[WP_FAULTS],
            tokens > 0.0 ? (double)v[WP_FAULTS] / tokens : 0.0,
            inflight_max,
            v[WP_INFLIGHT_BUSY_NS]
                ? (double)v[WP_INFLIGHT_INTEGRAL_NS] /
                  (double)v[WP_INFLIGHT_BUSY_NS] : 0.0,
            (double)v[WP_INFLIGHT_BUSY_NS] * ms,
            tokens > 0.0 ? wait_ms / tokens : 0.0,
            tokens > 0.0 ? read_total_ms / tokens : 0.0,
            tokens > 0.0 ? (double)v[WP_READ_CALLS] / tokens : 0.0,
            (double)v[WP_DRAIN_OVERLAP_NS] * ms,
            (double)v[WP_GPU_STALL_ON_DRAIN_NS] * ms,
            (double)v[WP_DEADLINE_SLACK_NS] * ms,
            (unsigned long long)v[WP_DEADLINE_SLACK_EVENTS],
            (unsigned long long)v[WP_DEADLINE_EXHAUSTED],
            (unsigned long long)v[WP_CACHE_INVALIDATES],
            (unsigned long long)v[WP_CACHE_INVALIDATES_SCOPED],
            (unsigned long long)v[WP_CACHE_SCOPED_ENTRIES_DROPPED],
            (unsigned long long)v[WP_CACHE_FULL_VALID_DROPPED]);

    for (int i = 0; i < WP_COUNT; i++) g_workerprof_prev[i] = cur[i];
}

/* Marcatori di token, chiamati dal thread di decode dentro
 * ds4_gpu_token_watch_begin/end prima dei loro early return, cosi' il
 * profilo del worker non dipende dagli altri osservatori per-token. */
static void ds4_workerprof_token_begin(void) {
    const int prof = cuda_worker_profile_enabled();
    if (!prof && cuda_worker_pickup_spin_us() == 0u) return;
    g_workerprof_token_active.store(1, std::memory_order_release);
}

static void ds4_workerprof_token_end(uint32_t token_count) {
    const int prof = cuda_worker_profile_enabled();
    if (!prof && cuda_worker_pickup_spin_us() == 0u) return;
    g_workerprof_token_active.store(0, std::memory_order_release);
    if (!prof || token_count == 0u) return;
    ds4_workerprof_add(WP_TOKENS, token_count);
    const uint64_t tokens =
        g_workerprof_c[WP_TOKENS].load(std::memory_order_relaxed);
    const uint64_t every = cuda_worker_profile_every_tokens();
    if (g_workerprof_next_token_log == 0ull) {
        g_workerprof_next_token_log = every;
    }
    if (tokens >= g_workerprof_next_token_log) {
        g_workerprof_next_token_log = tokens + every;
        ds4_workerprof_report("periodic");
    }
}

static int cuda_g133_tier_requested(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *value = getenv("DS4_G133_TIER");
        enabled = value && strcmp(value, "1") == 0;
        if (value && value[0] && strcmp(value, "0") != 0 && !enabled) {
            fprintf(stderr,
                    "ds4: invalid DS4_G133_TIER=%s; expected 0 or 1\n",
                    value);
        }
    }
    return enabled;
}

/* The decode thread owns this counter. Workers receive immutable copies in
 * cuda_moe_route_request and never read it directly. */
static uint64_t g_cuda_g133_decode_position_epoch = 0u;

extern "C" int ds4_gpu_g133_enabled = 0;
extern "C" ds4_gpu_g133_epoch ds4_gpu_g133_decode_position_begin(void);

static int cuda_g133_initialize_dispatch(void) {
    static int initialized = 0;
    static int valid = 1;
    if (initialized) return valid;
    initialized = 1;
    if (!cuda_g73_validate_hermetic_environment()) {
        valid = 0;
        return 0;
    }
    g_cuda_g73_open_enabled = cuda_g73_open_requested();
    g_cuda_g73_conservation_strict =
        cuda_g73_conservation_strict_requested();
    if (!cuda_g133_tier_requested()) return 1;

    const char *decay_env = getenv("DS4_G133_DECAY");
    if (decay_env && decay_env[0]) {
        char *end = NULL;
        errno = 0;
        const double decay = strtod(decay_env, &end);
        while (end && (*end == ' ' || *end == '\t')) end++;
        if (end == decay_env || errno != 0 || !end || *end != '\0' ||
            !isfinite(decay) || !(decay > 0.0 && decay < 1.0)) {
            fprintf(stderr,
                    "ds4: invalid DS4_G133_DECAY=%s; must satisfy 0 < decay < 1\n",
                    decay_env);
            valid = 0;
            return 0;
        }
    }
    ds4_gpu_g133_enabled = 1;
    return 1;
}

struct cuda_g133_telemetry_counters {
    std::atomic<uint64_t> upload_sync_wait_nanoseconds{0};
    std::atomic<uint64_t> vram_hits{0};
    std::atomic<uint64_t> ram_hits{0};
    std::atomic<uint64_t> selected{0};
    std::atomic<uint64_t> promotions{0};
    std::atomic<uint64_t> reaps{0};
    std::atomic<uint64_t> knock_promotions{0};
    std::atomic<uint64_t> thrash_guard_trips{0};
    std::atomic<uint64_t> out_of_mask_routes{0};
    std::atomic<uint64_t> served_transient{0};
    std::atomic<uint64_t> served_promoted{0};
    std::atomic<uint64_t> served_selected_fallback{0};
    std::atomic<uint64_t> served_terminal_exact{0};
    std::atomic<uint64_t> clamped{0};
    std::atomic<uint64_t> request_refused{0};
    std::atomic<uint64_t> rotation_promotions{0};
    std::atomic<uint64_t> rotation_reaps{0};
};
static cuda_g133_telemetry_counters g_cuda_g133_telemetry;

static void cuda_g133_telemetry_note_upload_sync_wait(double seconds) {
    if (!cuda_g133_tier_requested() || !(seconds > 0.0)) return;
    const double nanoseconds = seconds * 1.0e9;
    const uint64_t rounded = nanoseconds >= (double)UINT64_MAX
        ? UINT64_MAX : (uint64_t)(nanoseconds + 0.5);
    g_cuda_g133_telemetry.upload_sync_wait_nanoseconds.fetch_add(
        rounded, std::memory_order_relaxed);
}

static void cuda_g133_telemetry_increment(
        std::atomic<uint64_t> &counter, uint64_t value = 1u) {
    if (cuda_g133_tier_requested()) {
        counter.fetch_add(value, std::memory_order_relaxed);
    }
}

