    if (wrote < 0 || (size_t)wrote >= line_size - (size_t)*used) {
        *used = -1;
    } else {
        *used += wrote;
    }
}

static cuda_g133_attribution_snapshot_fn g_cuda_g133_attribution_snapshot =
    cuda_g133_attribution_snapshot_noop;
static cuda_g133_attribution_append_fn g_cuda_g133_attribution_append =
    cuda_g133_attribution_append_noop;

static void cuda_g130_attribution_init(void) {
    const char *value = getenv("DS4_G130_U1_ATTRIBUTION");
    g_cuda_g130_attribution_enabled =
        value && value[0] && strcmp(value, "0") != 0;
    if (cuda_g133_tier_requested()) {
        if (g_cuda_g73_open_enabled) {
            g_cuda_g133_attribution_snapshot =
                cuda_g73_attribution_snapshot_enabled;
            g_cuda_g133_attribution_append =
                cuda_g73_attribution_append_enabled;
        } else {
            g_cuda_g133_attribution_snapshot =
                cuda_g133_attribution_snapshot_enabled;
            g_cuda_g133_attribution_append =
                cuda_g133_attribution_append_enabled;
        }
    }
}

/* This is the only disabled-path gate used by CUDA call sites.  Its global
 * test precedes the TLS pointer load, so disabled runs never touch TLS. */
static cuda_g130_attribution_state *cuda_g130_attribution_token_state(void) {
    if (!g_cuda_g130_attribution_enabled) return NULL;
    cuda_g130_attribution_state *state = g_cuda_g130_attribution;
    return state && state->token_active ? state : NULL;
}

/* Charge the old bucket before changing buckets.  There is deliberately no
 * span stack: callers save and restore the returned enum, so overlap is not
 * representable. */
static cuda_g130_attribution_span cuda_g130_attribution_switch(
        cuda_g130_attribution_state *state,
        cuda_g130_attribution_span next_span) {
    const cuda_g130_attribution_span previous = state->current_span;
    const double now = cuda_wall_sec();
    if (previous >= 0 && previous < CUDA_G130_ATTRIB_COUNT) {
        state->token_span_seconds[previous] += now - state->span_started;
    }
    state->current_span = next_span;
    state->span_started = now;
    return previous;
}

struct cuda_g130_attribution_restore_guard {
    cuda_g130_attribution_state *state;
    cuda_g130_attribution_span previous;

    ~cuda_g130_attribution_restore_guard() {
        if (state) {
            (void)cuda_g130_attribution_switch(state, previous);
        }
    }
};

extern "C" void ds4_gpu_g130_attribution_request_begin(
        double decode_started) {
    if (!g_cuda_g130_attribution_enabled) return;
    cuda_g130_attribution_state *state = g_cuda_g130_attribution;
    if (!state) {
        state = (cuda_g130_attribution_state *)calloc(1, sizeof(*state));
        if (!state) return;
        g_cuda_g130_attribution = state;
    }
    memset(state, 0, sizeof(*state));
    state->request_active = 1;
    state->current_span = CUDA_G130_ATTRIB_NONE;
    state->request_started = decode_started;
}

extern "C" void ds4_gpu_g130_attribution_token_begin(
        uint64_t token_index, double decode_started) {
    if (!g_cuda_g130_attribution_enabled) return;
    cuda_g130_attribution_state *state = g_cuda_g130_attribution;
    if (!state || !state->request_active) return;
    memset(state->token_span_seconds, 0, sizeof(state->token_span_seconds));
    state->token_index = token_index;
    state->current_span = CUDA_G130_ATTRIB_NONE;
    state->token_started = decode_started;
    state->span_started = state->token_started;
    g_cuda_g133_attribution_snapshot(state);
    state->token_active = 1;
}

extern "C" void ds4_gpu_g130_attribution_token_end(
        uint64_t token_index, uint32_t token_count) {
    if (!g_cuda_g130_attribution_enabled) return;
    cuda_g130_attribution_state *state = g_cuda_g130_attribution;
    if (!state || !state->request_active || !state->token_active) return;
    const double decode_finished = cuda_wall_sec();
    if (state->current_span >= 0 &&
        state->current_span < CUDA_G130_ATTRIB_COUNT) {
        state->token_span_seconds[state->current_span] +=
            decode_finished - state->span_started;
    }
    state->current_span = CUDA_G130_ATTRIB_NONE;
    state->span_started = decode_finished;
    state->token_active = 0;
    if (token_count == 0u) {
        return;
    }

    const uint64_t first_token = token_index;
    double sum_seconds = 0.0;
    for (int i = 0; i < CUDA_G130_ATTRIB_COUNT; i++) {
        sum_seconds += state->token_span_seconds[i];
        state->request_span_seconds[i] += state->token_span_seconds[i];
    }
    const double decode_seconds = decode_finished - state->token_started;
    double residual_seconds = decode_seconds - sum_seconds;
    if (residual_seconds < 0.0 && residual_seconds > -1.0e-9) {
        residual_seconds = 0.0;
    }
    state->request_tokens += token_count;
    state->request_decode_seconds += decode_seconds;

    /* Speculative decode can commit several generated tokens in one target
     * evaluation.  Share that one wall interval evenly so the emission remains
     * one line per generated token and the request totals remain exact. */
    const double divisor = (double)token_count;
    for (uint32_t token_offset = 0; token_offset < token_count; token_offset++) {
        char line[2048];
        int used = snprintf(
            line, sizeof(line),
            "ds4: [g130-attrib] token=%llu decode_ms=%.6f",
            (unsigned long long)(first_token + token_offset),
            decode_seconds * 1000.0 / divisor);
        for (int i = 0;
             i < CUDA_G130_ATTRIB_COUNT && used > 0 &&
                 (size_t)used < sizeof(line);
             i++) {
            const int wrote = snprintf(
                line + used, sizeof(line) - (size_t)used,
                " span_%s_ms=%.6f",
                g_cuda_g130_attribution_span_names[i],
                state->token_span_seconds[i] * 1000.0 / divisor);
            if (wrote < 0) {
                used = -1;
                break;
            }
            used += wrote;
        }
        g_cuda_g133_attribution_append(
            state, line, sizeof(line), &used, divisor);
        if (used > 0 && (size_t)used < sizeof(line)) {
            (void)snprintf(
                line + used, sizeof(line) - (size_t)used,
                " sum_ms=%.6f residual_ms=%.6f\n",
                sum_seconds * 1000.0 / divisor,
                residual_seconds * 1000.0 / divisor);
            fputs(line, stderr);
        }
    }
}

extern "C" void ds4_gpu_g130_attribution_request_end(double decode_finished) {
    if (!g_cuda_g130_attribution_enabled) return;
    cuda_g130_attribution_state *state = g_cuda_g130_attribution;
    if (!state || !state->request_active) return;
    if (state->token_active) {
        ds4_gpu_g130_attribution_token_end(
            state->token_index, 0u);
    }
    double sum_seconds = 0.0;
    for (int i = 0; i < CUDA_G130_ATTRIB_COUNT; i++) {
        sum_seconds += state->request_span_seconds[i];
    }
    double residual_seconds = state->request_decode_seconds - sum_seconds;
    if (residual_seconds < 0.0 && residual_seconds > -1.0e-9) {
        residual_seconds = 0.0;
    }
    const double wall_seconds = decode_finished - state->request_started;
    double loop_overhead_seconds =
        wall_seconds - state->request_decode_seconds;
    if (loop_overhead_seconds < 0.0 && loop_overhead_seconds > -1.0e-9) {
        loop_overhead_seconds = 0.0;
    }
    const double residual_pct = state->request_decode_seconds > 0.0
        ? residual_seconds * 100.0 / state->request_decode_seconds : 0.0;
    char line[2048];
    int used = snprintf(
        line, sizeof(line),
        "ds4: [g130-attrib-summary] tokens=%llu decode_total_s=%.9f "
        "sum_total_s=%.9f residual_total_s=%.9f residual_pct=%.6f "
        "wall_total_s=%.9f loop_overhead_s=%.9f",
        (unsigned long long)state->request_tokens,
        state->request_decode_seconds, sum_seconds, residual_seconds,
        residual_pct, wall_seconds, loop_overhead_seconds);
    for (int i = 0;
         i < CUDA_G130_ATTRIB_COUNT && used > 0 &&
             (size_t)used < sizeof(line);
         i++) {
        const int wrote = snprintf(
            line + used, sizeof(line) - (size_t)used,
            " span_%s_total_s=%.9f",
            g_cuda_g130_attribution_span_names[i],
            state->request_span_seconds[i]);
        if (wrote < 0) {
            used = -1;
            break;
        }
        used += wrote;
    }
    if (used > 0 && (size_t)used + 1u < sizeof(line)) {
        line[used++] = '\n';
        line[used] = '\0';
        fputs(line, stderr);
    }
    state->request_active = 0;
}
#endif

static int cuda_q1_0_profile_requested(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *value = getenv("DS4_Q1_0_PROFILE");
        enabled = value && value[0] && strcmp(value, "0") != 0;
    }
    return enabled;
}

static void cuda_q1_0_mixed_profile_reset(int new_lifecycle) {
    /* The enable decision is cached for the process lifetime.  When it is
     * false no mixed-profile writer can run later, so retaining zero-initialized
     * state is safe and lifecycle calls avoid the profile mutex entirely. */
    if (!cuda_q1_0_profile_requested()) return;
    std::lock_guard<std::mutex> guard(g_q1_0_mixed_profile_mutex);
    g_q1_0_mixed_profile = cuda_q1_0_mixed_profile_stats{};
    if (new_lifecycle) g_q1_0_mixed_profile_final_emitted = 0;
}

static void cuda_q1_0_mixed_profile_record_entered(uint32_t routes) {
    std::lock_guard<std::mutex> guard(g_q1_0_mixed_profile_mutex);
    g_q1_0_mixed_profile.calls++;
    g_q1_0_mixed_profile.requested_routes += routes;
}

static void cuda_q1_0_mixed_profile_record_timer_failure(void) {
    std::lock_guard<std::mutex> guard(g_q1_0_mixed_profile_mutex);
    g_q1_0_mixed_profile.timer_failures++;
}

static void cuda_q1_0_mixed_profile_record_completed(
        const cuda_q1_0_mixed_profile_sample &sample,
        double call_seconds,
        uint32_t hot_routes,
        uint32_t q1_routes,
        int joined) {
    std::lock_guard<std::mutex> guard(g_q1_0_mixed_profile_mutex);
    cuda_q1_0_mixed_profile_stats &stats = g_q1_0_mixed_profile;
    cuda_q1_0_mixed_profile_sample &phases = stats.phases;
    phases.entry_contract_seconds += sample.entry_contract_seconds;
    phases.selection_d2h_seconds += sample.selection_d2h_seconds;
    phases.classify_map_seconds += sample.classify_map_seconds;
    phases.scratch_prepare_seconds += sample.scratch_prepare_seconds;
    phases.metadata_h2d_seconds += sample.metadata_h2d_seconds;
    phases.hot_branch_seconds += sample.hot_branch_seconds;
    phases.tier_observe_seconds += sample.tier_observe_seconds;
    phases.q1_dispatch_prepare_seconds +=
        sample.q1_dispatch_prepare_seconds;
    phases.q1_entry_seconds += sample.q1_entry_seconds;
    phases.q1_selected_load_seconds += sample.q1_selected_load_seconds;
    phases.q1_prepare_seconds += sample.q1_prepare_seconds;
    phases.q1_kernel_seconds += sample.q1_kernel_seconds;
    phases.q1_kernel_device_seconds += sample.q1_kernel_device_seconds;
    phases.join_publish_seconds += sample.join_publish_seconds;
    phases.entry_contract_calls += sample.entry_contract_calls;
    phases.selection_d2h_calls += sample.selection_d2h_calls;
    phases.classify_map_calls += sample.classify_map_calls;
    phases.scratch_prepare_calls += sample.scratch_prepare_calls;
    phases.metadata_h2d_calls += sample.metadata_h2d_calls;
    phases.hot_branch_calls += sample.hot_branch_calls;
    phases.tier_observe_calls += sample.tier_observe_calls;
    phases.q1_dispatch_prepare_calls += sample.q1_dispatch_prepare_calls;
    phases.q1_entry_calls += sample.q1_entry_calls;
    phases.q1_selected_load_calls += sample.q1_selected_load_calls;
    phases.q1_prepare_calls += sample.q1_prepare_calls;
    phases.q1_kernel_calls += sample.q1_kernel_calls;
    phases.q1_kernel_device_calls += sample.q1_kernel_device_calls;
    phases.q1_kernel_fenced_calls += sample.q1_kernel_fenced_calls;
    phases.join_publish_calls += sample.join_publish_calls;
    stats.call_seconds += call_seconds;
    stats.completed_calls++;
    stats.completed_routes += (uint64_t)hot_routes + q1_routes;
    stats.hot_routes += hot_routes;
    stats.q1_routes += q1_routes;
    stats.all_iq2_calls += q1_routes == 0u;
    stats.mixed_hot_q1_calls += hot_routes != 0u && q1_routes != 0u;
    stats.q1_only_calls += hot_routes == 0u && q1_routes != 0u;
    stats.join_kernel_calls += joined != 0;
}

static int cuda_q1_0_mixed_profile_timing_values_ok(
        const cuda_q1_0_mixed_profile_stats &stats,
        double bucket_seconds) {
    const cuda_q1_0_mixed_profile_sample &p = stats.phases;
    return std::isfinite(stats.call_seconds) && stats.call_seconds >= 0.0 &&
        std::isfinite(bucket_seconds) && bucket_seconds >= 0.0 &&
        std::isfinite(p.entry_contract_seconds) &&
        p.entry_contract_seconds >= 0.0 &&
        std::isfinite(p.selection_d2h_seconds) &&
        p.selection_d2h_seconds >= 0.0 &&
        std::isfinite(p.classify_map_seconds) &&
        p.classify_map_seconds >= 0.0 &&
        std::isfinite(p.scratch_prepare_seconds) &&
        p.scratch_prepare_seconds >= 0.0 &&
        std::isfinite(p.metadata_h2d_seconds) &&
        p.metadata_h2d_seconds >= 0.0 &&
        std::isfinite(p.hot_branch_seconds) &&
        p.hot_branch_seconds >= 0.0 &&
        std::isfinite(p.tier_observe_seconds) &&
        p.tier_observe_seconds >= 0.0 &&
        std::isfinite(p.q1_dispatch_prepare_seconds) &&
        p.q1_dispatch_prepare_seconds >= 0.0 &&
        std::isfinite(p.q1_entry_seconds) && p.q1_entry_seconds >= 0.0 &&
        std::isfinite(p.q1_selected_load_seconds) &&
        p.q1_selected_load_seconds >= 0.0 &&
        std::isfinite(p.q1_prepare_seconds) && p.q1_prepare_seconds >= 0.0 &&
        std::isfinite(p.q1_kernel_seconds) && p.q1_kernel_seconds >= 0.0 &&
        std::isfinite(p.q1_kernel_device_seconds) &&
        p.q1_kernel_device_seconds >= 0.0 &&
        std::isfinite(p.join_publish_seconds) &&
        p.join_publish_seconds >= 0.0;
}

static void cuda_q1_0_mixed_profile_finalize(
        cudaError_t cleanup_sync_error) {
    if (!cuda_q1_0_profile_requested()) return;
    cuda_q1_0_mixed_profile_stats stats = {};
    {
        std::lock_guard<std::mutex> guard(g_q1_0_mixed_profile_mutex);
        if (g_q1_0_mixed_profile_final_emitted) return;
        g_q1_0_mixed_profile_final_emitted = 1;
        stats = g_q1_0_mixed_profile;
    }
    const cuda_q1_0_mixed_profile_sample &p = stats.phases;
    const uint64_t failed_calls = stats.calls >= stats.completed_calls
        ? stats.calls - stats.completed_calls : 0;
    const uint64_t q1_path_calls =
        stats.mixed_hot_q1_calls + stats.q1_only_calls;
    const uint64_t q1_kernel_unfenced_calls =
        p.q1_kernel_calls >= p.q1_kernel_fenced_calls
            ? p.q1_kernel_calls - p.q1_kernel_fenced_calls : 0;
    const uint64_t q1_kernel_device_missing_calls =
        p.q1_kernel_calls >= p.q1_kernel_device_calls
            ? p.q1_kernel_calls - p.q1_kernel_device_calls : 0;
    const double bucket_seconds =
        p.entry_contract_seconds + p.selection_d2h_seconds +
        p.classify_map_seconds + p.scratch_prepare_seconds +
        p.metadata_h2d_seconds + p.hot_branch_seconds +
        p.tier_observe_seconds + p.q1_dispatch_prepare_seconds +
        p.q1_entry_seconds + p.q1_selected_load_seconds +
        p.q1_prepare_seconds + p.q1_kernel_seconds +
        p.join_publish_seconds;
    const double bucket_gap_seconds = stats.call_seconds - bucket_seconds;
    const double bucket_gap_tolerance_seconds = 1.0e-6;
    const int call_balance_ok =
        stats.calls == stats.completed_calls + failed_calls;
    const int route_balance_ok =
        stats.completed_routes == stats.hot_routes + stats.q1_routes;
    const int host_coverage_ok =
        p.entry_contract_calls == stats.completed_calls &&
        p.selection_d2h_calls == stats.completed_calls &&
        p.classify_map_calls == stats.completed_calls &&
        p.hot_branch_calls == stats.completed_calls &&
        p.join_publish_calls == stats.completed_calls &&
        p.scratch_prepare_calls == q1_path_calls &&
        p.metadata_h2d_calls == q1_path_calls &&
        p.tier_observe_calls == q1_path_calls &&
        p.q1_dispatch_prepare_calls == q1_path_calls &&
        p.q1_entry_calls == q1_path_calls &&
        p.q1_selected_load_calls == q1_path_calls &&
        p.q1_prepare_calls == q1_path_calls &&
        p.q1_kernel_calls == q1_path_calls &&
        stats.join_kernel_calls == q1_path_calls &&
        stats.all_iq2_calls + q1_path_calls == stats.completed_calls;
    const int device_coverage_ok =
        p.q1_kernel_device_calls == p.q1_kernel_calls &&
        p.q1_kernel_fenced_calls == p.q1_kernel_calls &&
        q1_kernel_device_missing_calls == 0 &&
        q1_kernel_unfenced_calls == 0;
    const int cleanup_sync_ok = cleanup_sync_error == cudaSuccess;
    const int timing_values_ok =
        cuda_q1_0_mixed_profile_timing_values_ok(stats, bucket_seconds);
    const int bucket_gap_ok = std::isfinite(bucket_gap_seconds) &&
        bucket_gap_seconds >= -bucket_gap_tolerance_seconds;
    const int coverage_ok = call_balance_ok && route_balance_ok &&
        host_coverage_ok && device_coverage_ok && failed_calls == 0 &&
        stats.timer_failures == 0 && cleanup_sync_ok && timing_values_ok &&
        bucket_gap_ok;
    const int summary_valid = coverage_ok;

    fprintf(stderr,
            "ds4: [q1-0-profile-route] result=summary final=1 "
            "path=mixed_q1 enabled=1 unit=seconds clock=host_monotonic "
            "bucket_scope=completed phase_model=disjoint "
            "denominator=per_bucket_calls "
            "limitation_hot_device=unmeasured_no_new_sync "
            "limitation_failed_calls=counts_only "
            "cleanup_required=1 missing_cleanup_policy=incomplete_negative "
            "host_device_additive=0 "
            "summary_valid=%d cleanup_sync_ok=%d cleanup_sync_error=%d "
            "timer_failures=%llu timing_values_ok=%d bucket_gap_ok=%d "
            "bucket_gap_tolerance_seconds=%.9f "
            "calls=%llu completed_calls=%llu "
            "failed_calls=%llu call_seconds=%.9f bucket_seconds=%.9f "
            "bucket_gap_seconds=%.9f "
            "entry_contract_calls=%llu entry_contract_seconds=%.9f "
            "selection_d2h_calls=%llu selection_d2h_seconds=%.9f "
            "classify_map_calls=%llu classify_map_seconds=%.9f "
            "scratch_prepare_calls=%llu scratch_prepare_seconds=%.9f "
            "metadata_h2d_calls=%llu metadata_h2d_seconds=%.9f "
            "hot_branch_calls=%llu hot_branch_seconds=%.9f "
            "tier_observe_calls=%llu tier_observe_seconds=%.9f "
            "q1_dispatch_prepare_calls=%llu "
            "q1_dispatch_prepare_seconds=%.9f "
            "q1_entry_calls=%llu q1_entry_seconds=%.9f "
            "q1_selected_load_calls=%llu q1_selected_load_seconds=%.9f "
            "q1_prepare_calls=%llu q1_prepare_seconds=%.9f "
            "q1_kernel_calls=%llu q1_kernel_seconds=%.9f "
            "q1_kernel_device_calls=%llu q1_kernel_device_seconds=%.9f "
            "q1_kernel_device_missing_calls=%llu "
            "q1_kernel_device_in_bucket=0 "
            "q1_kernel_fenced_calls=%llu q1_kernel_unfenced_calls=%llu "
            "join_publish_calls=%llu join_publish_seconds=%.9f\n",
            summary_valid, cleanup_sync_ok, (int)cleanup_sync_error,
            (unsigned long long)stats.timer_failures,
            timing_values_ok, bucket_gap_ok, bucket_gap_tolerance_seconds,
            (unsigned long long)stats.calls,
            (unsigned long long)stats.completed_calls,
            (unsigned long long)failed_calls,
            stats.call_seconds, bucket_seconds, bucket_gap_seconds,
            (unsigned long long)p.entry_contract_calls,
            p.entry_contract_seconds,
            (unsigned long long)p.selection_d2h_calls,
            p.selection_d2h_seconds,
            (unsigned long long)p.classify_map_calls,
            p.classify_map_seconds,
            (unsigned long long)p.scratch_prepare_calls,
            p.scratch_prepare_seconds,
            (unsigned long long)p.metadata_h2d_calls,
            p.metadata_h2d_seconds,
            (unsigned long long)p.hot_branch_calls,
            p.hot_branch_seconds,
            (unsigned long long)p.tier_observe_calls,
            p.tier_observe_seconds,
            (unsigned long long)p.q1_dispatch_prepare_calls,
            p.q1_dispatch_prepare_seconds,
            (unsigned long long)p.q1_entry_calls,
            p.q1_entry_seconds,
            (unsigned long long)p.q1_selected_load_calls,
            p.q1_selected_load_seconds,
            (unsigned long long)p.q1_prepare_calls,
            p.q1_prepare_seconds,
            (unsigned long long)p.q1_kernel_calls,
            p.q1_kernel_seconds,
            (unsigned long long)p.q1_kernel_device_calls,
            p.q1_kernel_device_seconds,
            (unsigned long long)q1_kernel_device_missing_calls,
            (unsigned long long)p.q1_kernel_fenced_calls,
            (unsigned long long)q1_kernel_unfenced_calls,
            (unsigned long long)p.join_publish_calls,
            p.join_publish_seconds);
    fprintf(stderr,
            "ds4: [q1-0-profile-selection] result=summary final=1 "
            "path=mixed_q1 enabled=1 unit=count coverage_scope=completed "
            "denominator=completed_routes "
            "calls=%llu completed_calls=%llu failed_calls=%llu "
            "requested_routes=%llu completed_routes=%llu hot_routes=%llu "
            "q1_routes=%llu all_iq2_calls=%llu mixed_hot_q1_calls=%llu "
            "q1_only_calls=%llu join_kernel_calls=%llu "
            "timer_failures=%llu cleanup_sync_ok=%d "
            "call_balance_ok=%d route_balance_ok=%d "
            "host_coverage_ok=%d device_coverage_ok=%d coverage_ok=%d "
            "summary_valid=%d\n",
            (unsigned long long)stats.calls,
            (unsigned long long)stats.completed_calls,
            (unsigned long long)failed_calls,
            (unsigned long long)stats.requested_routes,
            (unsigned long long)stats.completed_routes,
            (unsigned long long)stats.hot_routes,
            (unsigned long long)stats.q1_routes,
            (unsigned long long)stats.all_iq2_calls,
            (unsigned long long)stats.mixed_hot_q1_calls,
            (unsigned long long)stats.q1_only_calls,
            (unsigned long long)stats.join_kernel_calls,
            (unsigned long long)stats.timer_failures,
            cleanup_sync_ok, call_balance_ok, route_balance_ok,
            host_coverage_ok, device_coverage_ok, coverage_ok,
            summary_valid);
}

static int cuda_request_phase_trace_enabled(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *value = getenv("DS4_REQUEST_PHASE_TRACE");
        enabled = value && value[0] && strcmp(value, "0") != 0;
    }
    return enabled;
}

static void cuda_request_phase_trace(const char *event) {
    if (!cuda_request_phase_trace_enabled()) return;
    fprintf(stderr, "ds4: [request-phase] event=%s mono=%.6f\n",
            event, cuda_wall_sec());
}

static int cuda_model_load_progress_enabled(void) {
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE") != NULL) return 0;
    return 1;
}

static int cuda_stderr_is_tty(void) {
#ifdef _WIN32
    const int fd = _fileno(stderr);
    return fd >= 0 && _isatty(fd) != 0;
#else
    return isatty(STDERR_FILENO) != 0;
#endif
}

static void cuda_model_load_progress_reset(void) {
    g_model_load_progress_next = 0;
    g_model_load_progress_last = 0.0;
    g_model_load_progress_started = 0;
    g_model_load_progress_tty = 0;
}

static void cuda_model_load_progress_note(uint64_t cached_bytes) {
    if (!cuda_model_load_progress_enabled()) return;

    const double now = cuda_wall_sec();
    if (!g_model_load_progress_started) {
        g_model_load_progress_started = 1;
        g_model_load_progress_tty = cuda_stderr_is_tty();
        g_model_load_progress_next = (g_model_load_progress_tty ? 2ull : 16ull) *
                                     1024ull * 1024ull * 1024ull;
        g_model_load_progress_last = now;
        if (g_model_load_progress_tty) {
            fprintf(stderr, "ds4: CUDA loading model tensors into device cache: 0.00 GiB");
        } else {
            fprintf(stderr, "ds4: CUDA loading model tensors into device cache\n");
        }
    }

    if (cached_bytes < g_model_load_progress_next &&
        now - g_model_load_progress_last < (g_model_load_progress_tty ? 2.0 : 10.0)) {
        return;
    }

    if (g_model_load_progress_tty) {
        fprintf(stderr, "\rds4: CUDA loading model tensors into device cache: %.2f GiB",
                (double)cached_bytes / 1073741824.0);
    } else {
        fprintf(stderr, "ds4: CUDA loading model tensors %.2f GiB cached\n",
                (double)cached_bytes / 1073741824.0);
    }
    fflush(stderr);
    g_model_load_progress_last = now;
    const uint64_t step = (g_model_load_progress_tty ? 2ull : 16ull) *
                          1024ull * 1024ull * 1024ull;
    while (g_model_load_progress_next <= cached_bytes) {
        g_model_load_progress_next += step;
    }
}

static int cuda_model_prefetch_range(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size) {
    if (!model_map || map_size == 0 || map_offset > model_size || map_size > model_size - map_offset) return 0;
#ifdef _WIN32
    return 0;
#else
    if (getenv("DS4_CUDA_NO_MODEL_PREFETCH") != NULL ||
        getenv("DS4_CUDA_COPY_MODEL") != NULL ||
        getenv("DS4_CUDA_WEIGHT_CACHE") != NULL ||
        getenv("DS4_CUDA_WEIGHT_PRELOAD") != NULL) {
        return 0;
    }

    int device = 0;
    if (cudaGetDevice(&device) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }

    int pageable = 0;
    cudaError_t err = cudaDeviceGetAttribute(&pageable, cudaDevAttrPageableMemoryAccess, device);
    if (err != cudaSuccess || !pageable) {
        (void)cudaGetLastError();
        return 0;
    }
    cudaMemLocation loc;
    memset(&loc, 0, sizeof(loc));
    loc.type = cudaMemLocationTypeDevice;
    loc.id = device;

    const uint64_t page_sz = cuda_page_size();
    const uintptr_t host_addr = (uintptr_t)((const char *)model_map + map_offset);
    const uintptr_t pre_addr = host_addr & ~(uintptr_t)(page_sz - 1u);
    const uint64_t pre_delta = (uint64_t)(host_addr - pre_addr);
    const uint64_t pre_bytes = (pre_delta + map_size + page_sz - 1u) & ~(page_sz - 1u);
    void *pre_ptr = (void *)pre_addr;

    const double t0 = cuda_wall_sec();
    err = cudaMemAdvise(pre_ptr, (size_t)pre_bytes, cudaMemAdviseSetReadMostly, loc);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model read-mostly advise skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    err = cudaMemAdvise(pre_ptr, (size_t)pre_bytes, cudaMemAdviseSetPreferredLocation, loc);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model preferred-location advise skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }

    if (!g_model_prefetch_stream) {
        err = cudaStreamCreateWithFlags(&g_model_prefetch_stream, cudaStreamNonBlocking);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model prefetch stream creation skipped: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }

    err = cudaMemPrefetchAsync(pre_ptr, (size_t)pre_bytes, loc, 0, g_model_prefetch_stream);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model prefetch skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    if (getenv("DS4_CUDA_MODEL_PREFETCH_SYNC") != NULL) {
        err = cudaStreamSynchronize(g_model_prefetch_stream);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model prefetch sync failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }
    const double t1 = cuda_wall_sec();
    fprintf(stderr,
            "ds4: CUDA ATS/HMM prefetch queued %.2f GiB of model tensors in %.3fs\n",
            (double)map_size / 1073741824.0,
            t1 - t0);
    g_model_hmm_direct = 1;
    return 1;
#endif
}

static uint64_t cuda_model_copy_chunk_bytes(void) {
    uint64_t mb = 64;
    const char *env = getenv("DS4_CUDA_COPY_CHUNK_MIB");
    if (!env || !env[0]) env = getenv("DS4_CUDA_MODEL_COPY_CHUNK_MB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(env, &end, 10);
        if (end != env && v > 0) mb = (uint64_t)v;
    }
    if (mb < 16) mb = 16;
    if (mb > 4096) mb = 4096;
    return mb * 1048576ull;
}

static void cuda_model_discard_source_pages(const void *model_map, uint64_t model_size, uint64_t offset, uint64_t bytes) {
#if defined(POSIX_MADV_DONTNEED)
    if (getenv("DS4_CUDA_KEEP_MODEL_PAGES") != NULL || !model_map || bytes == 0 || offset > model_size) return;
    if (bytes > model_size - offset) bytes = model_size - offset;
    const uint64_t page_sz = cuda_page_size();
    const uintptr_t h0 = (uintptr_t)((const char *)model_map + offset);
    const uintptr_t h1 = h0 + bytes;
    const uintptr_t p0 = h0 & ~(uintptr_t)(page_sz - 1u);
    const uintptr_t p1 = (h1 + page_sz - 1u) & ~(uintptr_t)(page_sz - 1u);
    if (p1 > p0) (void)posix_madvise((void *)p0, (size_t)(p1 - p0), POSIX_MADV_DONTNEED);
#else
    (void)model_map;
    (void)model_size;
    (void)offset;
    (void)bytes;
#endif
}

static void cuda_model_drop_file_pages(uint64_t offset, uint64_t bytes) {
#if defined(POSIX_FADV_DONTNEED)
    if (!g_model_file_valid || getenv("DS4_CUDA_KEEP_MODEL_PAGES") != NULL || bytes == 0) return;
    (void)posix_fadvise(g_model_file.fd, (off_t)offset, (off_t)bytes, POSIX_FADV_DONTNEED);
#else
    (void)offset;
    (void)bytes;
#endif
}

static void cuda_model_file_clear(void) {
    cuda_g73_terminal_release();
    if (g_model_file_sequential_valid) {
        os_file_close(&g_model_file_sequential);
        g_model_file_sequential_valid = 0;
    } else {
        os_file_init(&g_model_file_sequential);
    }
    if (g_model_file_valid) {
        os_file_close(&g_model_file);
        g_model_file_valid = 0;
    } else {
        os_file_init(&g_model_file);
    }
    if (g_model_direct_fd >= 0) {
#if defined(__linux__)
        (void)close(g_model_direct_fd);
#endif
        g_model_direct_fd = -1;
    }
    g_model_direct_align = 1;
    g_model_file_size = 0;
}

