            "ds4: CUDA Q1_0 routed-expert sidecar installed: %.2f GiB\n",
            (double)model_size / 1073741824.0);
    cuda_q1_0_mixed_profile_reset(1);
    return 1;
}

extern "C" int ds4_gpu_set_nested_residual_sidecar(
        const os_file_t *file,
        const void *source_map,
        uint64_t source_size) {
    cuda_nested_residual_clear();
    if (!file && !source_map && source_size == 0) return 1;
    if (!file || !os_file_valid(file) || !source_map || source_size == 0 ||
        !getenv("DS4_NESTED_RESIDUAL_EXACT")) {
        fprintf(stderr,
                "ds4: nested residual rejected incomplete exact source\n");
        return 0;
    }

    uint8_t header[112];
    if (!cuda_pread_full(file, header, sizeof(header), 0) ||
        memcmp(header, "DS4NRSC\0", 8) != 0 ||
        cuda_nested_read_u32(header + 8) != 2u ||
        cuda_nested_read_u32(header + 12) != sizeof(header) ||
        cuda_nested_read_u64(header + 16) != source_size) {
        fprintf(stderr,
                "ds4: nested residual rejected header/source identity\n");
        return 0;
    }
    const uint64_t payload_bytes = cuda_nested_read_u64(header + 56);
    const uint32_t stored_crc = cuda_nested_read_u32(header + 96);
    const uint64_t record_count64 = cuda_nested_read_u64(header + 100);
    const uint32_t record_size = cuda_nested_read_u32(header + 108);
    if (record_count64 == 0 || record_count64 > 129u || record_size != 108u ||
        record_count64 > SIZE_MAX / record_size) {
        fprintf(stderr, "ds4: nested residual rejected record table geometry\n");
        return 0;
    }
    const size_t record_count = (size_t)record_count64;
    const size_t record_bytes = record_count * record_size;
    std::vector<uint8_t> table(record_bytes);
    if (!cuda_pread_full(file, table.data(), record_bytes, sizeof(header))) {
        fprintf(stderr, "ds4: nested residual record table read failed\n");
        return 0;
    }
    uint8_t crc_header[sizeof(header)];
    memcpy(crc_header, header, sizeof(header));
    memset(crc_header + 96, 0, 4);
    uint32_t crc = cuda_nested_crc32_continue(
        0, crc_header, sizeof(crc_header));
    crc = cuda_nested_crc32_continue(crc, table.data(), table.size());
    if (crc != stored_crc) {
        fprintf(stderr,
                "ds4: nested residual header/record-table CRC mismatch\n");
        return 0;
    }
    const uint64_t file_size = os_file_size(file);
    const uint64_t payload_start = sizeof(header) + record_bytes;
    if (file_size == UINT64_MAX || payload_start > file_size ||
        payload_bytes != file_size - payload_start) {
        fprintf(stderr, "ds4: nested residual payload bounds mismatch\n");
        return 0;
    }

    cuda_nested_residual_state &state = g_nested_residual;
    const char *profile_env = getenv("DS4_NESTED_RESIDUAL_PROFILE");
    state.profile_enabled =
        profile_env && profile_env[0] && strcmp(profile_env, "0") != 0;
    memcpy(state.source_sha256, header + 24, 32);
    memcpy(state.payload_sha256, header + 64, 32);
    if (!cuda_nested_hex_matches(
            "DS4_NESTED_RESIDUAL_EXPECTED_SOURCE_SHA256",
            state.source_sha256) ||
        !cuda_nested_hex_matches(
            "DS4_NESTED_RESIDUAL_EXPECTED_PAYLOAD_SHA256",
            state.payload_sha256)) {
        cuda_nested_residual_clear();
        return 0;
    }

    for (size_t index = 0; index < record_count; index++) {
        const uint8_t *raw = table.data() + index * record_size;
        cuda_nested_residual_record record = {};
        record.layer = cuda_nested_read_u32(raw + 0);
        record.kind = cuda_nested_read_u32(raw + 4);
        record.source_type = cuda_nested_read_u32(raw + 8);
        record.ncols = cuda_nested_read_u64(raw + 12);
        record.nrows = cuda_nested_read_u64(raw + 20);
        record.nexperts = cuda_nested_read_u64(raw + 28);
        record.source_offset = cuda_nested_read_u64(raw + 36);
        record.source_bytes = cuda_nested_read_u64(raw + 44);
        record.residual_offset = cuda_nested_read_u64(raw + 52);
        record.residual_bytes = cuda_nested_read_u64(raw + 60);
        record.expert_stride = cuda_nested_read_u64(raw + 68);
        record.kind_offset = cuda_nested_read_u64(raw + 76);
        record.residual_expert_bytes = cuda_nested_read_u64(raw + 84);
        record.native_block_bytes = cuda_nested_read_u32(raw + 92);
        record.base_block_bytes = cuda_nested_read_u32(raw + 96);
        record.residual_block_bytes = cuda_nested_read_u32(raw + 100);
        const uint32_t reserved = cuda_nested_read_u32(raw + 104);
        const uint32_t expected_native =
            record.source_type == 16u ? 66u :
            (record.source_type == 10u ? 84u : 0u);
        const uint32_t expected_base =
            record.source_type == 16u ? 34u :
            (record.source_type == 10u ? 52u : 0u);
        if (record.layer >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
            record.kind == 0 || record.kind > 3u ||
            record.ncols == 0 || (record.ncols % 256u) != 0 ||
            record.nrows == 0 ||
            record.nexperts != CUDA_NESTED_RESIDUAL_EXPERT_COUNT ||
            expected_native == 0 ||
            record.native_block_bytes != expected_native ||
            record.base_block_bytes != expected_base ||
            record.residual_block_bytes != 32u || reserved != 0) {
            fprintf(stderr,
                    "ds4: nested residual record %zu geometry rejected\n",
                    index);
            cuda_nested_residual_clear();
            return 0;
        }
        uint64_t blocks_per_expert = 0;
        uint64_t residual_kind_bytes = 0;
        uint64_t expected_source_bytes = 0;
        uint64_t expected_residual_bytes = 0;
        if (!cuda_nested_mul_u64(
                record.ncols / 256u, record.nrows,
                &blocks_per_expert) ||
            !cuda_nested_mul_u64(
                blocks_per_expert, record.native_block_bytes,
                &record.native_kind_bytes) ||
            !cuda_nested_mul_u64(
                blocks_per_expert, record.base_block_bytes,
                &record.base_kind_bytes) ||
            !cuda_nested_mul_u64(
                blocks_per_expert, record.residual_block_bytes,
                &residual_kind_bytes) ||
            !cuda_nested_mul_u64(
                record.native_kind_bytes, 256u,
                &expected_source_bytes) ||
            !cuda_nested_mul_u64(
                residual_kind_bytes, 256u,
                &expected_residual_bytes) ||
            record.source_bytes != expected_source_bytes ||
            record.residual_bytes != expected_residual_bytes ||
            record.source_offset > source_size ||
            record.source_bytes > source_size - record.source_offset ||
            record.residual_offset < payload_start ||
            record.residual_offset > file_size ||
            residual_kind_bytes > file_size - record.residual_offset) {
            fprintf(stderr,
                    "ds4: nested residual record %zu bounds rejected\n",
                    index);
            cuda_nested_residual_clear();
            return 0;
        }
        cuda_nested_residual_layer &layer = state.layers[record.layer];
        const uint32_t part = record.kind - 1u;
        if (layer.present[part]) {
            fprintf(stderr, "ds4: nested residual duplicate layer/kind\n");
            cuda_nested_residual_clear();
            return 0;
        }
        layer.records[part] = record;
        layer.present[part] = 1;
    }

    uint64_t payload_cursor = payload_start;
    for (uint32_t layer_index = 0;
         layer_index < CUDA_NESTED_RESIDUAL_LAYER_COUNT; layer_index++) {
        cuda_nested_residual_layer &layer = state.layers[layer_index];
        const uint32_t present = layer.present[0] +
            layer.present[1] + layer.present[2];
        if (present == 0) continue;
        if (present != 3u) {
            fprintf(stderr,
                    "ds4: nested residual layer %u is missing a tensor part\n",
                    layer_index);
            cuda_nested_residual_clear();
            return 0;
        }
        uint64_t base_cursor = 0;
        uint64_t native_cursor = 0;
        uint64_t residual_cursor = 0;
        const uint64_t stride = layer.records[0].residual_expert_bytes;
        const uint64_t layer_start =
            layer.records[0].residual_offset - layer.records[0].kind_offset;
        for (uint32_t part = 0; part < 3u; part++) {
            cuda_nested_residual_record &record = layer.records[part];
            const uint64_t residual_kind_bytes =
                record.residual_bytes / record.nexperts;
            if (record.expert_stride != stride ||
                record.residual_expert_bytes != stride ||
                record.kind_offset != residual_cursor ||
                residual_cursor > UINT64_MAX - layer_start ||
                record.residual_offset != layer_start + residual_cursor ||
                record.base_kind_bytes > UINT64_MAX - base_cursor ||
                record.native_kind_bytes > UINT64_MAX - native_cursor ||
                residual_kind_bytes > UINT64_MAX - residual_cursor) {
                fprintf(stderr,
                        "ds4: nested residual layer %u interleave rejected\n",
                        layer_index);
                cuda_nested_residual_clear();
                return 0;
            }
            record.base_kind_offset = base_cursor;
            record.native_kind_offset = native_cursor;
            base_cursor += record.base_kind_bytes;
            native_cursor += record.native_kind_bytes;
            residual_cursor += residual_kind_bytes;
        }
        if (residual_cursor != stride || layer_start != payload_cursor ||
            stride > (UINT64_MAX - payload_cursor) / 256u) {
            fprintf(stderr,
                    "ds4: nested residual layer %u payload order rejected\n",
                    layer_index);
            cuda_nested_residual_clear();
            return 0;
        }
        layer.base_expert_bytes = base_cursor;
        layer.native_expert_bytes = native_cursor;
        layer.residual_layer_start = layer_start;
        layer.residual_expert_bytes = stride;
        layer.ready = 1;
        payload_cursor += stride * 256u;
    }
    if (payload_cursor != file_size ||
        os_file_dup(&state.file, file) != 0) {
        fprintf(stderr,
                "ds4: nested residual payload coverage/file duplicate failed\n");
        cuda_nested_residual_clear();
        return 0;
    }
    state.file_valid = 1;
    state.source_map = (const uint8_t *)source_map;
    state.source_size = source_size;
    state.file_size = file_size;
    state.payload_bytes = payload_bytes;
    if (!cuda_nested_residual_preload_base()) {
        state.failures++;
        cuda_nested_residual_clear();
        return 0;
    }
    state.active = 1;
    fprintf(stderr,
            "ds4: nested residual exact sidecar installed bytes=%llu "
            "payload=%llu version=2 record_crc=valid router=open\n",
            (unsigned long long)file_size,
            (unsigned long long)payload_bytes);
    return 1;
}

extern "C" void ds4_gpu_sparse_bake_reset(void) {
    cuda_sparse_bake_reset_state();
}

/* Called once after the startup pre-cache completes: from here on,
 * cuda_model_range_ptr_from_fd may evict LRU cold streamed ranges. */
extern "C" void ds4_gpu_model_streaming_begin(void) {
    const uint64_t startup_reserve = cuda_model_stream_reserve_bytes();
    g_model_streaming_active = 1;
    const char *runtime_env = getenv("DS4_CUDA_STREAM_RUNTIME_RESERVE_MB");
    if (runtime_env && runtime_env[0]) {
        char *end = NULL;
        const unsigned long long runtime_mb = strtoull(runtime_env, &end, 10);
        const uint64_t runtime_reserve = end != runtime_env
            ? (uint64_t)runtime_mb * 1048576ull
            : startup_reserve;
        fprintf(stderr,
                "ds4: CUDA stream reserve startup=%.2f GiB runtime=%.2f GiB switch=expert-cache-ready\n",
                (double)startup_reserve / 1073741824.0,
                (double)runtime_reserve / 1073741824.0);
    }
}

extern "C" int ds4_gpu_cache_q8_f16_range(const void *model_map, uint64_t model_size, uint64_t offset, uint64_t bytes, uint64_t in_dim, uint64_t out_dim, const char *label) {
    if (!model_map || bytes == 0) return 1;
    if (offset > model_size || bytes > model_size - offset) return 0;
    static int optional_q8_preload_disabled = 0;
    if (optional_q8_preload_disabled) return 1;
    const char *cache_label = label ? label : "q8_0";
    if (getenv("DS4_CUDA_Q8_F32_PRELOAD") != NULL &&
        cuda_q8_f32_cache_allowed(cache_label, in_dim, out_dim)) {
        if (cuda_q8_f32_ptr(model_map, offset, bytes, in_dim, out_dim, cache_label)) return 1;
        optional_q8_preload_disabled = 1;
        return 1;
    }
    if (!cuda_q8_f16_preload_allowed(cache_label, in_dim, out_dim)) return 1;
    if (cuda_q8_f16_ptr(model_map, offset, bytes, in_dim, out_dim, cache_label)) return 1;
    optional_q8_preload_disabled = 1;
    return 1;
}

extern "C" void ds4_gpu_print_memory_report(const char *label) {
    size_t free_b = 0, total_b = 0;
    (void)cudaMemGetInfo(&free_b, &total_b);
    fprintf(stderr, "ds4: CUDA memory report %s: free %.2f MiB total %.2f MiB\n",
            label ? label : "", (double)free_b / 1048576.0, (double)total_b / 1048576.0);
}

extern "C" void ds4_gpu_set_quality(bool quality) {
    g_quality_mode = quality ? 1 : 0;
    if (g_cublas_ready) {
        const cublasMath_t math_mode =
            (g_quality_mode || getenv("DS4_CUDA_NO_TF32") != NULL)
                ? CUBLAS_DEFAULT_MATH
                : CUBLAS_TF32_TENSOR_OP_MATH;
        (void)cublasSetMathMode(g_cublas, math_mode);
    }
}

__global__ static void embed_token_hc_kernel(float *out, const unsigned short *w, uint32_t token, uint32_t n_embd, uint32_t n_hc) {
    uint32_t i = blockIdx.x * blockDim.x + threadIdx.x;
    uint32_t n = n_embd * n_hc;
    if (i >= n) return;
    uint32_t e = i % n_embd;
    out[i] = __half2float(reinterpret_cast<const __half *>(w)[(uint64_t)token * n_embd + e]);
}

__global__ static void embed_tokens_hc_kernel(
        float *out,
        const int32_t *tokens,
        const __half *w,
        uint32_t n_vocab,
        uint32_t n_tokens,
        uint32_t n_embd,
        uint32_t n_hc) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * n_hc * n_embd;
    if (gid >= n) return;
    uint32_t d = gid % n_embd;
    uint64_t tmp = gid / n_embd;
    uint32_t t = tmp / n_hc;
    int32_t tok_i = tokens[t];
    uint32_t tok = tok_i < 0 ? 0u : (uint32_t)tok_i;
    if (tok >= n_vocab) tok = 0;
    out[gid] = __half2float(w[(uint64_t)tok * n_embd + d]);
}

__global__ static void embed_staged_rows_hc_kernel(
        float *out,
        const __half *rows,
        uint32_t n_tokens,
        uint32_t n_embd,
        uint32_t n_hc) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * n_hc * n_embd;
    if (gid >= n) return;
    uint32_t d = gid % n_embd;
    uint64_t tmp = gid / n_embd;
    uint32_t t = (uint32_t)(tmp / n_hc);
    out[gid] = __half2float(rows[(uint64_t)t * n_embd + d]);
}

__global__ static void matmul_f16_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;

    float sum = 0.0f;
    const __half *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = threadIdx.x; i < in_dim; i += blockDim.x) {
        sum += __half2float(wr[i]) * xr[i];
    }

    __shared__ float partial[256];
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) out[tok * out_dim + row] = partial[0];
}

__global__ static void matmul_f16_serial_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok || threadIdx.x != 0) return;

    float sum = 0.0f;
    const __half *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = 0; i < in_dim; i++) {
        sum += __half2float(wr[i]) * xr[i];
    }
    out[tok * out_dim + row] = sum;
}

__global__ static void matmul_f16_ordered_chunks_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;

    __shared__ float partial[32];
    const uint32_t tid = threadIdx.x;
    float sum = 0.0f;
    const uint64_t chunk = (in_dim + 31u) / 32u;
    const uint64_t k0 = (uint64_t)tid * chunk;
    uint64_t k1 = k0 + chunk;
    if (k1 > in_dim) k1 = in_dim;
    const __half *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = k0; i < k1; i++) {
        sum += __half2float(wr[i]) * xr[i];
    }
    partial[tid] = sum;
    __syncthreads();
    if (tid == 0) {
        float total = 0.0f;
        for (uint32_t i = 0; i < 32u; i++) total += partial[i];
        out[tok * out_dim + row] = total;
    }
}

__global__ static void matmul_f16_pair_ordered_chunks_kernel(
        float *out0,
        float *out1,
        const __half *w0,
        const __half *w1,
        const float *x,
        uint64_t in_dim,
        uint64_t out0_dim,
        uint64_t out1_dim) {
    uint64_t row = (uint64_t)blockIdx.x;
    if (row >= out0_dim && row >= out1_dim) return;

    __shared__ float partial0[32];
    __shared__ float partial1[32];
    const uint32_t tid = threadIdx.x;
    float sum0 = 0.0f;
    float sum1 = 0.0f;
    const uint64_t chunk = (in_dim + 31u) / 32u;
    const uint64_t k0 = (uint64_t)tid * chunk;
    uint64_t k1 = k0 + chunk;
    if (k1 > in_dim) k1 = in_dim;
    const __half *wr0 = row < out0_dim ? w0 + row * in_dim : w0;
    const __half *wr1 = row < out1_dim ? w1 + row * in_dim : w1;
    for (uint64_t i = k0; i < k1; i++) {
        const float xv = x[i];
        if (row < out0_dim) sum0 += __half2float(wr0[i]) * xv;
        if (row < out1_dim) sum1 += __half2float(wr1[i]) * xv;
    }
    partial0[tid] = sum0;
    partial1[tid] = sum1;
    __syncthreads();
    if (tid == 0) {
        float total0 = 0.0f;
        float total1 = 0.0f;
        for (uint32_t i = 0; i < 32u; i++) {
            total0 += partial0[i];
            total1 += partial1[i];
        }
        if (row < out0_dim) out0[row] = total0;
        if (row < out1_dim) out1[row] = total1;
    }
}

__global__ static void matmul_f32_kernel(
        float *out,
        const float *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;

    float sum = 0.0f;
    const float *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = threadIdx.x; i < in_dim; i += blockDim.x) {
        sum += wr[i] * xr[i];
    }

    __shared__ float partial[256];
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) out[tok * out_dim + row] = partial[0];
}

__global__ static void repeat_hc_kernel(float *out, const float *row, uint32_t n_embd, uint32_t n_hc) {
    uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_embd * n_hc;
    if (i >= n) return;
    out[i] = row[i % n_embd];
}

__global__ static void f32_to_f16_kernel(__half *out, const float *x, uint64_t n) {
    uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) out[i] = __float2half(x[i]);
}

__device__ static float warp_sum_f32(float v) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(0xffffffffu, v, offset);
    }
    return v;
}

__device__ static float warp_max_f32(float v) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        v = fmaxf(v, __shfl_down_sync(0xffffffffu, v, offset));
    }
    return v;
}

__device__ static float dot4_f32(float4 a, float4 b) {
    return a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
}

__device__ __forceinline__ static int32_t load_i8x4_i32_aligned(const int8_t *p) {
    return *(const int32_t *)p;
}

__device__ __forceinline__ static int32_t load_i8x4_i32_unaligned(const int8_t *p) {
    const uint8_t *u = (const uint8_t *)p;
    return (int32_t)((uint32_t)u[0] |
                     ((uint32_t)u[1] << 8) |
                     ((uint32_t)u[2] << 16) |
                     ((uint32_t)u[3] << 24));
}

__device__ __forceinline__ static int32_t dot_i8x32_dp4a(const int8_t *a, const int8_t *b) {
    int32_t dot = 0;
#pragma unroll
    for (uint32_t i = 0; i < 32u; i += 4u) {
        dot = __dp4a(load_i8x4_i32_unaligned(a + i), load_i8x4_i32_aligned(b + i), dot);
    }
    return dot;
}

__device__ __forceinline__ static int32_t dot_i8_block(const int8_t *a, const int8_t *b, uint64_t n, int use_dp4a) {
    if (use_dp4a && n == 32u) return dot_i8x32_dp4a(a, b);
    int32_t dot = 0;
    for (uint64_t i = 0; i < n; i++) dot += (int32_t)a[i] * (int32_t)b[i];
    return dot;
}

__global__ static DS4_CUDA_UNUSED void matmul_q8_0_kernel(
        float *out,
        const unsigned char *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;
    const uint64_t blocks = (in_dim + 31) / 32;
    const unsigned char *wr = w + row * blocks * 34;
    const float *xr = x + tok * in_dim;
    float acc = 0.0f;

    for (uint64_t b = threadIdx.x; b < blocks; b += blockDim.x) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        float amax = 0.0f;
        for (uint64_t i = 0; i < bn; i++) amax = fmaxf(amax, fabsf(xr[i0 + i]));
        float d = amax / 127.0f;
        float id = d != 0.0f ? 1.0f / d : 0.0f;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        int dot = 0;
        for (uint64_t i = 0; i < bn; i++) {
            int q = (int)lrintf(xr[i0 + i] * id);
            q = q > 127 ? 127 : (q < -128 ? -128 : q);
            dot += (int)qs[i] * q;
        }
        acc += __half2float(*scale_h) * d * (float)dot;
    }

    __shared__ float partial[256];
    partial[threadIdx.x] = acc;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) out[tok * out_dim + row] = partial[0];
}

__global__ static void quantize_q8_0_f32_kernel(
        int8_t *xq,
        float *xscale,
        const float *x,
        uint64_t in_dim,
        uint64_t blocks) {
    uint64_t b = blockIdx.x;
    uint64_t tok = blockIdx.y;
    if (b >= blocks) return;
    uint64_t i0 = b * 32;
    uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
    const float *xr = x + tok * in_dim + i0;

    float a = 0.0f;
    if (threadIdx.x < bn) a = fabsf(xr[threadIdx.x]);
    __shared__ float vals[32];
    vals[threadIdx.x] = a;
    __syncthreads();
    for (uint32_t stride = 16; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) vals[threadIdx.x] = fmaxf(vals[threadIdx.x], vals[threadIdx.x + stride]);
        __syncthreads();
    }
    const float d = vals[0] / 127.0f;
    const float id = d != 0.0f ? 1.0f / d : 0.0f;
    if (threadIdx.x == 0) xscale[tok * blocks + b] = d;
    int8_t *dst = xq + (tok * blocks + b) * 32;
    if (threadIdx.x < bn) {
        int v = (int)lrintf(xr[threadIdx.x] * id);
        v = v > 127 ? 127 : (v < -128 ? -128 : v);
        dst[threadIdx.x] = (int8_t)v;
    } else {
        dst[threadIdx.x] = 0;
    }
}

__global__ static void matmul_q8_0_preq_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok,
        uint64_t blocks,
        int use_dp4a) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;
    const unsigned char *wr = w + row * blocks * 34;
    const int8_t *xqr = xq + tok * blocks * 32;
    const float *xsr = xscale + tok * blocks;
    float acc = 0.0f;
    for (uint64_t b = threadIdx.x; b < blocks; b += blockDim.x) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xqr + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xsr[b] * (float)dot;
    }
    __shared__ float partial[256];
    partial[threadIdx.x] = acc;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) out[tok * out_dim + row] = partial[0];
}

__global__ static void matmul_q8_0_preq_warp8_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        int use_dp4a) {
    uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim) return;
    const unsigned char *wr = w + row * blocks * 34;
    float acc = 0.0f;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xq + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xscale[b] * (float)dot;
    }
    acc = warp_sum_f32(acc);
    if (lane == 0) out[row] = acc;
}

__global__ static void matmul_q8_0_pair_preq_warp8_kernel(
        float *out0,
        float *out1,
        const unsigned char *w0,
        const unsigned char *w1,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out0_dim,
        uint64_t out1_dim,
        uint64_t blocks,
        int use_dp4a) {
    uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    uint32_t lane = threadIdx.x & 31u;
    if (row >= out0_dim && row >= out1_dim) return;
    float acc0 = 0.0f;
    float acc1 = 0.0f;
    const unsigned char *wr0 = row < out0_dim ? w0 + row * blocks * 34 : NULL;
    const unsigned char *wr1 = row < out1_dim ? w1 + row * blocks * 34 : NULL;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const int8_t *xqb = xq + b * 32;
        const float xs = xscale[b];
        if (wr0) {
            const __half *scale_h = (const __half *)(wr0 + b * 34);
            const int8_t *qs = (const int8_t *)(wr0 + b * 34 + 2);
            int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc0 += __half2float(*scale_h) * xs * (float)dot;
        }
        if (wr1) {
            const __half *scale_h = (const __half *)(wr1 + b * 34);
            const int8_t *qs = (const int8_t *)(wr1 + b * 34 + 2);
            int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc1 += __half2float(*scale_h) * xs * (float)dot;
        }
    }
    acc0 = warp_sum_f32(acc0);
    acc1 = warp_sum_f32(acc1);
    if (lane == 0) {
        if (row < out0_dim) out0[row] = acc0;
        if (row < out1_dim) out1[row] = acc1;
    }
}

__global__ static void matmul_q8_0_hc_expand_preq_warp8_kernel(
        float *out_hc,
        float *block_out,
        const float *block_add,
        const float *residual_hc,
        const float *split,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint32_t n_embd,
        uint32_t n_hc,
        uint64_t blocks,
        int has_add,
        int use_dp4a) {
    const uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim) return;
    const unsigned char *wr = w + row * blocks * 34;
    float acc = 0.0f;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        const uint64_t i0 = b * 32;
        const uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xq + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xscale[b] * (float)dot;
    }
    acc = warp_sum_f32(acc);
    if (lane == 0) {
        const uint32_t d = (uint32_t)row;
        block_out[d] = acc;
        float block_v = acc;
        if (has_add) block_v += block_add[d];
        const float *post = split + n_hc;
        const float *comb = split + 2u * n_hc;
        for (uint32_t dst_hc = 0; dst_hc < n_hc; dst_hc++) {
            float hc_acc = block_v * post[dst_hc];
            for (uint32_t src_hc = 0; src_hc < n_hc; src_hc++) {
                const float comb_v = comb[dst_hc + (uint64_t)src_hc * n_hc];
                const float res_v = residual_hc[(uint64_t)src_hc * n_embd + d];
                hc_acc += comb_v * res_v;
            }
            out_hc[(uint64_t)dst_hc * n_embd + d] = hc_acc;
        }
    }
}

__global__ static void matmul_q8_0_preq_batch_warp8_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok,
        uint64_t blocks,
        int use_dp4a) {
    const uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint64_t tok = (uint64_t)blockIdx.y;
    const uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim || tok >= n_tok) return;

    const unsigned char *wr = w + row * blocks * 34;
    const int8_t *xqr = xq + tok * blocks * 32;
    const float *xsr = xscale + tok * blocks;
    float acc = 0.0f;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        const uint64_t i0 = b * 32;
        const uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xqr + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xsr[b] * (float)dot;
    }
    acc = warp_sum_f32(acc);
    if (lane == 0) out[tok * out_dim + row] = acc;
}

__global__ static void dequant_q8_0_to_f16_kernel(
        __half *out,
        const unsigned char *w,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = in_dim * out_dim;
    if (gid >= n) return;
    uint64_t row = gid / in_dim;
    uint64_t i = gid - row * in_dim;
    uint64_t b = i / 32;
    uint64_t j = i - b * 32;
    const unsigned char *blk = w + (row * blocks + b) * 34;
    const __half scale = *(const __half *)blk;
    const int8_t q = *(const int8_t *)(blk + 2 + j);
    out[gid] = __hmul(scale, __float2half((float)q));
}

__global__ static void dequant_q8_0_to_f32_kernel(
        float *out,
        const unsigned char *w,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = in_dim * out_dim;
    if (gid >= n) return;
    uint64_t row = gid / in_dim;
    uint64_t i = gid - row * in_dim;
    uint64_t b = i / 32;
    uint64_t j = i - b * 32;
    const unsigned char *blk = w + (row * blocks + b) * 34;
    const float scale = __half2float(*(const __half *)blk);
    const int8_t q = *(const int8_t *)(blk + 2 + j);
    out[gid] = scale * (float)q;
}

__global__ static void grouped_q8_0_a_preq_warp8_kernel(
        float *low,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t group_dim,
        uint64_t rank,
        uint32_t n_groups,
        uint32_t n_tokens,
        uint64_t blocks,
        int use_dp4a) {
    const uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint64_t tok = (uint64_t)blockIdx.y;
    const uint32_t lane = threadIdx.x & 31u;
    const uint64_t low_dim = (uint64_t)n_groups * rank;
    if (row >= low_dim || tok >= n_tokens) return;

    const uint64_t group = row / rank;
    const uint64_t row_in_group = row - group * rank;
    const unsigned char *wr = w + (group * rank + row_in_group) * blocks * 34;
    const uint64_t xrow = tok * (uint64_t)n_groups + group;
    const int8_t *xqr = xq + xrow * blocks * 32;
    const float *xsr = xscale + xrow * blocks;
    float acc = 0.0f;

    for (uint64_t b = lane; b < blocks; b += 32u) {
        const uint64_t i0 = b * 32;
        const uint64_t bn = group_dim - i0 < 32 ? group_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xqr + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xsr[b] * (float)dot;
    }
    acc = warp_sum_f32(acc);
    if (lane == 0) low[tok * low_dim + row] = acc;
}

__global__ static void rms_norm_plain_kernel(float *out, const float *x, uint32_t n, uint32_t rows, float eps) {
    uint32_t row = blockIdx.x;
    if (row >= rows) return;
    const float *xr = x + (uint64_t)row * n;
    float *orow = out + (uint64_t)row * n;
    float sum = 0.0f;
    for (uint32_t i = threadIdx.x; i < n; i += blockDim.x) {
        float v = xr[i];
        sum += v * v;
    }
    __shared__ float partial[256];
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    float scale = rsqrtf(partial[0] / (float)n + eps);
    for (uint32_t i = threadIdx.x; i < n; i += blockDim.x) {
        orow[i] = xr[i] * scale;
    }
}

__global__ static void rms_norm_weight_kernel(float *out, const float *x, const float *w, uint32_t n, uint32_t rows, float eps) {
    uint32_t row = blockIdx.x;
