static uint64_t cuda_decode_trace_qpc_now_raw(void) {
#ifdef _WIN32
    LARGE_INTEGER value;
    QueryPerformanceCounter(&value);
    return (uint64_t)value.QuadPart;
#else
    struct timespec value;
    clock_gettime(CLOCK_MONOTONIC, &value);
    return (uint64_t)value.tv_sec * 1000000000ull +
        (uint64_t)value.tv_nsec;
#endif
}

static double cuda_decode_trace_ticks_ms(uint64_t ticks) {
    return g_cuda_decode_trace.qpc_frequency
        ? (double)ticks * 1000.0 /
            (double)g_cuda_decode_trace.qpc_frequency
        : 0.0;
}

static int cuda_decode_trace_parse_ranges(
        const char *value,
        uint64_t maximum,
        std::vector<cuda_decode_trace_range> *ranges) {
    if (!value || !value[0] || !ranges) return 0;
    const char *cursor = value;
    while (*cursor) {
        while (*cursor == ' ' || *cursor == '\t' || *cursor == ',') cursor++;
        if (!*cursor) break;
        char *end = NULL;
        errno = 0;
        const unsigned long long first = strtoull(cursor, &end, 10);
        if (errno != 0 || end == cursor || first > maximum) return 0;
        uint64_t last = (uint64_t)first;
        cursor = end;
        if (*cursor == '-') {
            cursor++;
            errno = 0;
            const unsigned long long parsed_last =
                strtoull(cursor, &end, 10);
            if (errno != 0 || end == cursor || parsed_last > maximum ||
                parsed_last < first) {
                return 0;
            }
            last = (uint64_t)parsed_last;
            cursor = end;
        }
        while (*cursor == ' ' || *cursor == '\t') cursor++;
        if (*cursor && *cursor != ',') return 0;
        ranges->push_back(cuda_decode_trace_range{
            (uint64_t)first, last});
        if (*cursor == ',') cursor++;
    }
    return !ranges->empty();
}

static int cuda_decode_trace_nsys_positions(
        const std::vector<cuda_decode_trace_range> &ranges,
        uint64_t *first_out, uint64_t *last_out) {
    uint64_t values[2] = {0u, 0u};
    uint32_t count = 0u;
    for (const cuda_decode_trace_range &range : ranges) {
        if (range.last - range.first > 1u) return 0;
        for (uint64_t value = range.first; value <= range.last; value++) {
            if (count >= 2u ||
                (count != 0u && value != values[count - 1u] + 1u)) {
                return 0;
            }
            values[count++] = value;
            if (value == UINT64_MAX) break;
        }
    }
    if (count == 0u) return 0;
    if (first_out) *first_out = values[0];
    if (last_out) *last_out = values[count - 1u];
    return 1;
}

static int cuda_decode_trace_parser_selftest(void) {
    struct parser_case {
        const char *value;
        uint64_t maximum;
        int expected;
    };
    static const parser_case cases[] = {
        {"0", 42u, 1},
        {"0,4,20,42", 42u, 1},
        {"13-14", UINT64_MAX, 1},
        {"", 42u, 0},
        {"-1", 42u, 0},
        {"4-3", 42u, 0},
        {"43", 42u, 0},
        {"1x", 42u, 0},
    };
    for (const parser_case &test : cases) {
        std::vector<cuda_decode_trace_range> parsed;
        if (cuda_decode_trace_parse_ranges(
                test.value, test.maximum, &parsed) != test.expected) {
            return 0;
        }
    }
    std::vector<cuda_decode_trace_range> one;
    std::vector<cuda_decode_trace_range> two;
    std::vector<cuda_decode_trace_range> three;
    if (!cuda_decode_trace_parse_ranges("100", UINT64_MAX, &one) ||
        !cuda_decode_trace_parse_ranges("100-101", UINT64_MAX, &two) ||
        !cuda_decode_trace_parse_ranges("100-102", UINT64_MAX, &three) ||
        !cuda_decode_trace_nsys_positions(one, NULL, NULL) ||
        !cuda_decode_trace_nsys_positions(two, NULL, NULL) ||
        cuda_decode_trace_nsys_positions(three, NULL, NULL)) {
        return 0;
    }
    return 1;
}

static void cuda_decode_trace_nvtx_close(void) {
    if (g_cuda_decode_trace.nsys_token_range && g_cuda_decode_trace.nsys_domain) {
        nvtxDomainRangeEnd(
            g_cuda_decode_trace.nsys_domain,
            g_cuda_decode_trace.nsys_token_range);
        g_cuda_decode_trace.nsys_token_range = 0;
    }
    for (uint32_t layer = 0; layer < CUDA_MOE_LAYER_COUNT; layer++) {
        if (g_cuda_decode_trace.nsys_layer_range[layer] &&
            g_cuda_decode_trace.nsys_domain) {
            nvtxDomainRangeEnd(
                g_cuda_decode_trace.nsys_domain,
                g_cuda_decode_trace.nsys_layer_range[layer]);
            g_cuda_decode_trace.nsys_layer_range[layer] = 0;
        }
    }
    if (g_cuda_decode_trace.nsys_capture_range &&
        g_cuda_decode_trace.nsys_domain) {
        nvtxDomainRangeEnd(
            g_cuda_decode_trace.nsys_domain,
            g_cuda_decode_trace.nsys_capture_range);
        g_cuda_decode_trace.nsys_capture_range = 0;
    }
    g_cuda_decode_trace.nsys_capture_active = 0;
}

static void cuda_decode_trace_flush(void) {
    for (size_t index = 0;
         index < g_cuda_decode_trace.record_count; index++) {
        const cuda_decode_trace_record &record =
            g_cuda_decode_trace.records[index];
        uint64_t h2d_count = record.embedding_h2d_count;
        uint64_t h2d_bytes = record.embedding_h2d_bytes;
        uint64_t h2d_ticks = record.embedding_h2d_api_ticks;
        uint64_t d2h_count = record.logits_d2h_count;
        uint64_t d2h_bytes = record.logits_d2h_bytes;
        uint64_t d2h_ticks = record.logits_api_ticks;
        uint64_t kv_batch_count = 0u;
        uint64_t kv_span_count = 0u;
        uint64_t kv_h2d_count = 0u;
        uint64_t kv_h2d_bytes = 0u;
        uint64_t kv_h2d_ticks = 0u;
        uint64_t kv_wait_count = 0u;
        for (uint32_t layer = 0; layer < CUDA_MOE_LAYER_COUNT; layer++) {
            const cuda_decode_trace_layer_record &item =
                record.layer[layer];
            h2d_count += item.h2d_count + item.kv_h2d_count;
            h2d_bytes += item.h2d_bytes + item.kv_h2d_bytes;
            h2d_ticks += item.h2d_api_ticks + item.kv_h2d_api_ticks;
            d2h_count += item.d2h_count;
            d2h_bytes += item.d2h_bytes;
            d2h_ticks += item.d2h_api_ticks;
            kv_batch_count += item.kv_batch_count;
            kv_span_count += item.kv_span_count;
            kv_h2d_count += item.kv_h2d_count;
            kv_h2d_bytes += item.kv_h2d_bytes;
            kv_h2d_ticks += item.kv_h2d_api_ticks;
            kv_wait_count += item.kv_stream_wait_event_count;
        }
        const double host_ms = record.host_ended_qpc >=
                record.host_started_qpc
            ? cuda_decode_trace_ticks_ms(
                record.host_ended_qpc - record.host_started_qpc)
            : 0.0;
        const double wall_tps = host_ms > 0.0 ? 1000.0 / host_ms : 0.0;
        const double gpu_tps = record.gpu_default_window_ms > 0.0f
            ? 1000.0 / (double)record.gpu_default_window_ms : 0.0;
        fprintf(stderr,
                "ds4: [decode-trace-v2] {"
                "\"schema\":\"ds4.cuda.decode_trace.v2\","
                "\"record\":\"token\",\"sample_id\":%llu,"
                "\"position\":%llu,\"success\":%u,"
                "\"qpc_frequency_hz\":%llu,"
                "\"host_wall_ms\":%.6f,\"wall_tps\":%.6f,"
                "\"gpu_default_window_ms\":%.6f,"
                "\"gpu_default_tps\":%.6f,\"gpu_timing_valid\":%u,"
                "\"embedding_host_copy_ms\":%.6f,"
                "\"embedding_h2d_api_ms\":%.6f,"
                "\"embedding_h2d_count\":%llu,"
                "\"embedding_h2d_bytes\":%llu,"
                "\"embedding_gpu_window_ms\":%.6f,"
                "\"output_submit_ms\":%.6f,"
                "\"output_gpu_window_ms\":%.6f,"
                "\"split_sync_wait_ms\":%.6f,"
                "\"split_sync_count\":%llu,"
                "\"end_sync_wait_ms\":%.6f,\"end_sync_count\":1,"
                "\"logits_d2h_api_ms\":%.6f,"
                "\"logits_d2h_count\":%llu,"
                "\"logits_d2h_bytes\":%llu,"
                "\"pread_wait_ms\":%.6f,\"pread_count\":%llu,"
                "\"pread_bytes\":%llu,\"h2d_api_ms\":%.6f,"
                "\"h2d_count\":%llu,\"h2d_bytes\":%llu,"
                "\"d2h_api_ms\":%.6f,\"d2h_count\":%llu,"
                "\"d2h_bytes\":%llu,\"kv_batch_count\":%llu,"
                "\"kv_span_count\":%llu,\"kv_h2d_count\":%llu,"
                "\"kv_h2d_bytes\":%llu,\"kv_h2d_enqueue_ms\":%.6f,"
                "\"kv_stream_wait_event_count\":%llu,"
                "\"timing_event_count\":%u,\"event_sync_count\":0,"
                "\"dropped_records\":%llu,"
                "\"worker_attribution_errors\":%llu,"
                "\"io_counter_valid\":%u,\"record_complete\":%u}\n",
                (unsigned long long)record.sample_id,
                (unsigned long long)record.position,
                (unsigned)record.success,
                (unsigned long long)g_cuda_decode_trace.qpc_frequency,
                host_ms, wall_tps,
                (double)record.gpu_default_window_ms, gpu_tps,
                (unsigned)record.gpu_default_valid,
                cuda_decode_trace_ticks_ms(
                    record.embedding_host_copy_ticks),
                cuda_decode_trace_ticks_ms(
                    record.embedding_h2d_api_ticks),
                (unsigned long long)record.embedding_h2d_count,
                (unsigned long long)record.embedding_h2d_bytes,
                (double)record.embedding_gpu_window_ms,
                cuda_decode_trace_ticks_ms(record.output_submit_ticks),
                (double)record.output_gpu_window_ms,
                cuda_decode_trace_ticks_ms(record.split_sync_ticks),
                (unsigned long long)record.split_sync_count,
                cuda_decode_trace_ticks_ms(record.end_sync_ticks),
                cuda_decode_trace_ticks_ms(record.logits_api_ticks),
                (unsigned long long)record.logits_d2h_count,
                (unsigned long long)record.logits_d2h_bytes,
                cuda_decode_trace_ticks_ms(record.pread_wait_ticks),
                (unsigned long long)record.pread_count,
                (unsigned long long)record.pread_bytes,
                cuda_decode_trace_ticks_ms(h2d_ticks),
                (unsigned long long)h2d_count,
                (unsigned long long)h2d_bytes,
                cuda_decode_trace_ticks_ms(d2h_ticks),
                (unsigned long long)d2h_count,
                (unsigned long long)d2h_bytes,
                (unsigned long long)kv_batch_count,
                (unsigned long long)kv_span_count,
                (unsigned long long)kv_h2d_count,
                (unsigned long long)kv_h2d_bytes,
                cuda_decode_trace_ticks_ms(kv_h2d_ticks),
                (unsigned long long)kv_wait_count,
                (unsigned)CUDA_DECODE_TRACE_TIMING_EVENT_COUNT,
                (unsigned long long)g_cuda_decode_trace.dropped_records.load(
                    std::memory_order_relaxed),
                (unsigned long long)
                    g_cuda_decode_trace.worker_attribution_errors.load(
                        std::memory_order_relaxed),
                (unsigned)record.io_counter_valid,
                (unsigned)record.record_complete);
        for (uint32_t layer = 0; layer < CUDA_MOE_LAYER_COUNT; layer++) {
            const cuda_decode_trace_layer_record &item =
                record.layer[layer];
            if (!item.selected) continue;
            const uint64_t host_ticks = item.host_ended_qpc >=
                    item.host_started_qpc
                ? item.host_ended_qpc - item.host_started_qpc : 0u;
            fprintf(stderr,
                    "ds4: [decode-trace-v2] {"
                    "\"schema\":\"ds4.cuda.decode_trace.v2\","
                    "\"record\":\"layer\",\"sample_id\":%llu,"
                    "\"position\":%llu,\"layer\":%u,"
                    "\"host_encode_ms\":%.6f,"
                    "\"gpu_default_window_ms\":%.6f,"
                    "\"gpu_default_valid\":%u,"
                    "\"resolver_submit_ms\":%.6f,"
                    "\"queue_prior_consume_wait_ms\":%.6f,"
                    "\"worker_queue_wait_ms\":%.6f,"
                    "\"worker_service_ms\":%.6f,"
                    "\"resolver_stream_wait_ms\":%.6f,"
                    "\"worker_ready_wait_ms\":%.6f,"
                    "\"worker_ready_poll_count\":%llu,"
                    "\"pread_wait_ms\":%.6f,\"pread_count\":%llu,"
                    "\"pread_bytes\":%llu,"
                    "\"io_qd_submit_count\":%llu,"
                    "\"io_qd_completion_count\":%llu,"
                    "\"io_qd_max_inflight\":%llu,"
                    "\"h2d_api_ms\":%.6f,\"h2d_count\":%llu,"
                    "\"h2d_bytes\":%llu,\"d2h_api_ms\":%.6f,"
                    "\"d2h_count\":%llu,\"d2h_bytes\":%llu,"
                    "\"upload_gpu_window_ms\":%.6f,"
                    "\"upload_gpu_valid\":%u,"
                    "\"upload_drain_wait_ms\":%.6f,"
                    "\"upload_drain_count\":%llu,"
                    "\"publish_kernel_count\":%llu,"
                    "\"publish_route_count\":%llu,"
                    "\"kv_batch_count\":%llu,\"kv_span_count\":%llu,"
                    "\"kv_h2d_count\":%llu,\"kv_h2d_bytes\":%llu,"
                    "\"kv_h2d_enqueue_ms\":%.6f,"
                    "\"kv_stream_wait_event_count\":%llu,"
                    "\"sample_id_match\":%u}\n",
                    (unsigned long long)record.sample_id,
                    (unsigned long long)record.position, layer,
                    cuda_decode_trace_ticks_ms(host_ticks),
                    (double)item.gpu_default_window_ms,
                    (unsigned)item.gpu_default_valid,
                    cuda_decode_trace_ticks_ms(item.resolver_submit_ticks),
                    cuda_decode_trace_ticks_ms(
                        item.queue_prior_consume_ticks),
                    cuda_decode_trace_ticks_ms(item.worker_queue_ticks),
                    cuda_decode_trace_ticks_ms(item.worker_service_ticks),
                    cuda_decode_trace_ticks_ms(
                        item.resolver_stream_wait_ticks),
                    cuda_decode_trace_ticks_ms(
                        item.worker_ready_wait_ticks),
                    (unsigned long long)item.worker_ready_poll_count,
                    cuda_decode_trace_ticks_ms(item.pread_wait_ticks),
                    (unsigned long long)item.pread_count,
                    (unsigned long long)item.pread_bytes,
                    (unsigned long long)item.qd_submit_count,
                    (unsigned long long)item.qd_completion_count,
                    (unsigned long long)item.qd_max_inflight,
                    cuda_decode_trace_ticks_ms(item.h2d_api_ticks),
                    (unsigned long long)item.h2d_count,
                    (unsigned long long)item.h2d_bytes,
                    cuda_decode_trace_ticks_ms(item.d2h_api_ticks),
                    (unsigned long long)item.d2h_count,
                    (unsigned long long)item.d2h_bytes,
                    (double)item.upload_gpu_window_ms,
                    (unsigned)item.upload_gpu_valid,
                    cuda_decode_trace_ticks_ms(item.upload_drain_ticks),
                    (unsigned long long)item.upload_drain_count,
                    (unsigned long long)item.publish_kernel_count,
                    (unsigned long long)item.publish_route_count,
                    (unsigned long long)item.kv_batch_count,
                    (unsigned long long)item.kv_span_count,
                    (unsigned long long)item.kv_h2d_count,
                    (unsigned long long)item.kv_h2d_bytes,
                    cuda_decode_trace_ticks_ms(item.kv_h2d_api_ticks),
                    (unsigned long long)item.kv_stream_wait_event_count,
                    (unsigned)item.sample_id_match);
        }
    }
    g_cuda_decode_trace.record_count = 0u;
}

static void cuda_decode_trace_destroy_event(
        cuda_trace_timing_event *event) {
    if (event && event->handle) {
        (void)cudaEventDestroy(event->handle);
        event->handle = NULL;
    }
}

static void cuda_decode_trace_release(void) {
    ds4_gpu_decode_trace_enabled = 0;
    cuda_decode_trace_nvtx_close();
    cuda_decode_trace_flush();
    g_cuda_decode_trace.nsys_capture_requested = 0;
    g_cuda_decode_trace.active.store(0, std::memory_order_relaxed);
    g_cuda_decode_trace.active_sample_id.store(
        0u, std::memory_order_relaxed);
    g_cuda_decode_trace.active_layer.store(
        UINT32_MAX, std::memory_order_relaxed);
    if (g_moe_expert_cache.route_worker_safe_leaked.load(
            std::memory_order_acquire)) {
        /* The detached route worker may still touch upload trace events.
         * Quarantine owns them for process lifetime just like its staging. */
        return;
    }
    cuda_decode_trace_destroy_event(&g_cuda_decode_trace.token_start);
    cuda_decode_trace_destroy_event(&g_cuda_decode_trace.token_end);
    cuda_decode_trace_destroy_event(&g_cuda_decode_trace.embedding_start);
    cuda_decode_trace_destroy_event(&g_cuda_decode_trace.embedding_end);
    cuda_decode_trace_destroy_event(&g_cuda_decode_trace.output_start);
    cuda_decode_trace_destroy_event(&g_cuda_decode_trace.output_end);
    for (uint32_t layer = 0; layer < CUDA_MOE_LAYER_COUNT; layer++) {
        cuda_decode_trace_destroy_event(
            &g_cuda_decode_trace.layer_start[layer]);
        cuda_decode_trace_destroy_event(
            &g_cuda_decode_trace.layer_end[layer]);
        cuda_decode_trace_destroy_event(
            &g_cuda_decode_trace.upload_start[layer]);
        cuda_decode_trace_destroy_event(
            &g_cuda_decode_trace.upload_end[layer]);
        g_cuda_decode_trace.upload_started[layer].store(
            0u, std::memory_order_relaxed);
        g_cuda_decode_trace.upload_ended[layer].store(
            0u, std::memory_order_relaxed);
    }
    g_cuda_decode_trace.positions.clear();
    g_cuda_decode_trace.records.clear();
    g_cuda_decode_trace.record_count = 0u;
    g_cuda_decode_trace.sample_every = 0u;
    g_cuda_decode_trace.layer_mask = 0u;
    if (g_cuda_decode_trace.nsys_domain) {
        nvtxDomainDestroy(g_cuda_decode_trace.nsys_domain);
        g_cuda_decode_trace.nsys_domain = NULL;
    }
}

static int cuda_decode_trace_create_event(
        cuda_trace_timing_event *event) {
    return event &&
        cudaEventCreateWithFlags(
            &event->handle, cudaEventDefault) == cudaSuccess;
}

static int cuda_decode_trace_init(void) {
    cuda_decode_trace_release();
    const char *every_value =
        getenv("DS4_CUDA_DECODE_TRACE_SAMPLE_EVERY");
    const char *positions_value =
        getenv("DS4_CUDA_DECODE_TRACE_POSITIONS");
    const char *layers_value =
        getenv("DS4_CUDA_DECODE_TRACE_LAYERS");
    const char *nsys_value =
        getenv("DS4_CUDA_NSYS_CAPTURE");
    const char *selftest_value =
        getenv("DS4_CUDA_DECODE_TRACE_SELFTEST");
    if (selftest_value && selftest_value[0]) {
        if (strcmp(selftest_value, "1") != 0 ||
            !cuda_decode_trace_parser_selftest()) {
            fprintf(stderr,
                    "ds4: CUDA decode trace parser selftest failed\n");
            return 0;
        }
    }
    if ((!every_value || !every_value[0]) &&
        (!positions_value || !positions_value[0])) {
        if (nsys_value && nsys_value[0]) {
            fprintf(stderr,
                    "ds4: DS4_CUDA_NSYS_CAPTURE requires an explicit "
                    "decode trace sample/position selector\n");
            return 0;
        }
        return 1;
    }
    if (nsys_value && nsys_value[0]) {
        if (strcmp(nsys_value, "1") != 0) {
            fprintf(stderr,
                    "ds4: invalid DS4_CUDA_NSYS_CAPTURE=%s\n",
                    nsys_value);
            return 0;
        }
        g_cuda_decode_trace.nsys_capture_requested = 1;
        if (every_value && every_value[0]) {
            fprintf(stderr,
                    "ds4: DS4_CUDA_NSYS_CAPTURE requires explicit "
                    "POSITIONS and forbids SAMPLE_EVERY\n");
            return 0;
        }
    }

    if (every_value && every_value[0]) {
        char *end = NULL;
        errno = 0;
        const unsigned long long every =
            strtoull(every_value, &end, 10);
        if (errno != 0 || end == every_value || *end != '\0' ||
            every == 0u) {
            fprintf(stderr,
                    "ds4: invalid "
                    "DS4_CUDA_DECODE_TRACE_SAMPLE_EVERY=%s\n",
                    every_value);
            return 0;
        }
        g_cuda_decode_trace.sample_every = (uint64_t)every;
    }
    if (positions_value && positions_value[0] &&
        !cuda_decode_trace_parse_ranges(
            positions_value, UINT64_MAX,
            &g_cuda_decode_trace.positions)) {
        fprintf(stderr,
                "ds4: invalid DS4_CUDA_DECODE_TRACE_POSITIONS=%s\n",
                positions_value);
        cuda_decode_trace_release();
        return 0;
    }
    if (g_cuda_decode_trace.nsys_capture_requested &&
        !cuda_decode_trace_nsys_positions(
            g_cuda_decode_trace.positions,
            &g_cuda_decode_trace.nsys_first_position,
            &g_cuda_decode_trace.nsys_last_position)) {
        fprintf(stderr,
                "ds4: DS4_CUDA_NSYS_CAPTURE requires one or two "
                "contiguous explicit decode positions\n");
        cuda_decode_trace_release();
        return 0;
    }

    g_cuda_decode_trace.layer_mask =
        (1ull << CUDA_MOE_LAYER_COUNT) - 1ull;
    if (layers_value && layers_value[0]) {
        std::vector<cuda_decode_trace_range> layer_ranges;
        if (!cuda_decode_trace_parse_ranges(
                layers_value, CUDA_MOE_LAYER_COUNT - 1u,
                &layer_ranges)) {
            fprintf(stderr,
                    "ds4: invalid DS4_CUDA_DECODE_TRACE_LAYERS=%s\n",
                    layers_value);
            cuda_decode_trace_release();
            return 0;
        }
        g_cuda_decode_trace.layer_mask = 0u;
        for (const cuda_decode_trace_range &range : layer_ranges) {
            for (uint64_t layer = range.first; layer <= range.last; layer++) {
                g_cuda_decode_trace.layer_mask |= 1ull << layer;
            }
        }
    }

    if (!cuda_decode_trace_create_event(&g_cuda_decode_trace.token_start) ||
        !cuda_decode_trace_create_event(&g_cuda_decode_trace.token_end) ||
        !cuda_decode_trace_create_event(
            &g_cuda_decode_trace.embedding_start) ||
        !cuda_decode_trace_create_event(
            &g_cuda_decode_trace.embedding_end) ||
        !cuda_decode_trace_create_event(
            &g_cuda_decode_trace.output_start) ||
        !cuda_decode_trace_create_event(
            &g_cuda_decode_trace.output_end)) {
        fprintf(stderr,
                "ds4: CUDA decode trace token event allocation failed\n");
        (void)cudaGetLastError();
        cuda_decode_trace_release();
        return 0;
    }
    for (uint32_t layer = 0; layer < CUDA_MOE_LAYER_COUNT; layer++) {
        if (!cuda_decode_trace_create_event(
                &g_cuda_decode_trace.layer_start[layer]) ||
            !cuda_decode_trace_create_event(
                &g_cuda_decode_trace.layer_end[layer]) ||
            !cuda_decode_trace_create_event(
                &g_cuda_decode_trace.upload_start[layer]) ||
            !cuda_decode_trace_create_event(
                &g_cuda_decode_trace.upload_end[layer])) {
            fprintf(stderr,
                    "ds4: CUDA decode trace layer event allocation failed "
                    "layer=%u\n",
                    layer);
            (void)cudaGetLastError();
            cuda_decode_trace_release();
            return 0;
        }
    }
    try {
        g_cuda_decode_trace.records.resize(
            CUDA_DECODE_TRACE_MAX_RECORDS);
    } catch (const std::bad_alloc &) {
        fprintf(stderr,
                "ds4: CUDA decode trace host record allocation failed\n");
        cuda_decode_trace_release();
        return 0;
    }
#ifdef _WIN32
    LARGE_INTEGER frequency;
    if (!QueryPerformanceFrequency(&frequency) ||
        frequency.QuadPart <= 0) {
        fprintf(stderr, "ds4: CUDA decode trace QPC unavailable\n");
        cuda_decode_trace_release();
        return 0;
    }
    g_cuda_decode_trace.qpc_frequency =
        (uint64_t)frequency.QuadPart;
#else
    g_cuda_decode_trace.qpc_frequency = 1000000000ull;
#endif
    if (g_cuda_decode_trace.nsys_capture_requested) {
        g_cuda_decode_trace.nsys_domain =
            nvtxDomainCreateA("ds4.cuda");
        if (!g_cuda_decode_trace.nsys_domain) {
            fprintf(stderr,
                    "ds4: CUDA decode trace NVTX domain creation failed\n");
            cuda_decode_trace_release();
            return 0;
        }
    }
    g_cuda_decode_trace.active.store(0, std::memory_order_relaxed);
    g_cuda_decode_trace.active_position.store(0u, std::memory_order_relaxed);
    g_cuda_decode_trace.active_sample_id.store(
        0u, std::memory_order_relaxed);
    g_cuda_decode_trace.active_layer.store(
        UINT32_MAX, std::memory_order_relaxed);
    g_cuda_decode_trace.next_sample_id.store(
        0u, std::memory_order_relaxed);
    g_cuda_decode_trace.trace_pread_count.store(
        0u, std::memory_order_relaxed);
    g_cuda_decode_trace.trace_pread_bytes.store(
        0u, std::memory_order_relaxed);
    g_cuda_decode_trace.trace_pread_wait_ticks.store(
        0u, std::memory_order_relaxed);
    g_cuda_decode_trace.dropped_records.store(
        0u, std::memory_order_relaxed);
    g_cuda_decode_trace.worker_attribution_errors.store(
        0u, std::memory_order_relaxed);
    g_cuda_decode_trace.kv_populated.store(
        0, std::memory_order_relaxed);
    g_cuda_decode_trace.record_count = 0u;
    ds4_gpu_decode_trace_enabled = 1;
    fprintf(stderr,
            "ds4: [decode-trace-config] enabled=1 sample_every=%llu "
             "positions=%s layers_mask=0x%011llx timing_events=%u "
             "hot_path_event_sync=0 nsys_capture=%d\n",
            (unsigned long long)g_cuda_decode_trace.sample_every,
             positions_value && positions_value[0] ? positions_value : "none",
             (unsigned long long)g_cuda_decode_trace.layer_mask,
             (unsigned)CUDA_DECODE_TRACE_TIMING_EVENT_COUNT,
             g_cuda_decode_trace.nsys_capture_requested);
    return 1;
}

static int cuda_decode_trace_position_selected(uint64_t position) {
    if (g_cuda_decode_trace.sample_every != 0u &&
        position % g_cuda_decode_trace.sample_every == 0u) {
        return 1;
    }
    for (const cuda_decode_trace_range &range :
         g_cuda_decode_trace.positions) {
        if (position >= range.first && position <= range.last) return 1;
    }
    return 0;
}

static nvtxRangeId_t cuda_decode_trace_nvtx_range(
        const char *message, uint32_t color) {
    if (!g_cuda_decode_trace.nsys_domain) return 0;
    nvtxEventAttributes_t attributes = {};
    attributes.version = NVTX_VERSION;
    attributes.size = NVTX_EVENT_ATTRIB_STRUCT_SIZE;
    attributes.colorType = NVTX_COLOR_ARGB;
    attributes.color = color;
    attributes.messageType = NVTX_MESSAGE_TYPE_ASCII;
    attributes.message.ascii = message;
    return nvtxDomainRangeStartEx(
        g_cuda_decode_trace.nsys_domain, &attributes);
}

extern "C" void ds4_gpu_decode_trace_token_begin(uint64_t position) {
    if (!ds4_gpu_decode_trace_enabled ||
        !cuda_decode_trace_position_selected(position)) {
        return;
    }
    if (g_cuda_decode_trace.active.exchange(
            1, std::memory_order_acq_rel)) {
        g_cuda_decode_trace.dropped_records.fetch_add(
            1u, std::memory_order_relaxed);
        return;
    }
    memset(&g_cuda_decode_trace.current, 0,
           sizeof(g_cuda_decode_trace.current));
    const uint64_t sample_id =
        g_cuda_decode_trace.next_sample_id.fetch_add(
            1u, std::memory_order_relaxed) + 1u;
    g_cuda_decode_trace.current.sample_id = sample_id;
    g_cuda_decode_trace.current.position = position;
    g_cuda_decode_trace.current.host_started_qpc =
        cuda_decode_trace_qpc_now_raw();
    g_cuda_decode_trace.current.pread_count_begin =
        g_cuda_decode_trace.trace_pread_count.load(
            std::memory_order_acquire);
    g_cuda_decode_trace.current.pread_bytes_begin =
        g_cuda_decode_trace.trace_pread_bytes.load(
            std::memory_order_acquire);
    g_cuda_decode_trace.current.pread_wait_ticks_begin =
        g_cuda_decode_trace.trace_pread_wait_ticks.load(
            std::memory_order_acquire);
    g_cuda_decode_trace.active_position.store(
        position, std::memory_order_release);
    g_cuda_decode_trace.active_layer.store(
        UINT32_MAX, std::memory_order_release);
    memset(g_cuda_decode_trace.layer_started, 0,
           sizeof(g_cuda_decode_trace.layer_started));
    memset(g_cuda_decode_trace.layer_ended, 0,
           sizeof(g_cuda_decode_trace.layer_ended));
    for (uint32_t layer = 0; layer < CUDA_MOE_LAYER_COUNT; layer++) {
        g_cuda_decode_trace.upload_started[layer].store(
            0u, std::memory_order_relaxed);
        g_cuda_decode_trace.upload_ended[layer].store(
            0u, std::memory_order_relaxed);
    }
    g_cuda_decode_trace.embedding_started = 0u;
    g_cuda_decode_trace.embedding_ended = 0u;
    g_cuda_decode_trace.output_started = 0u;
    g_cuda_decode_trace.output_ended = 0u;
    if (g_cuda_decode_trace.nsys_capture_requested &&
        position == g_cuda_decode_trace.nsys_first_position &&
        g_cuda_decode_trace.kv_populated.load(
            std::memory_order_acquire)) {
        g_cuda_decode_trace.nsys_capture_range =
            cuda_decode_trace_nvtx_range(
                "ds4.decode.capture", 0xff00a0ffu);
        g_cuda_decode_trace.nsys_capture_active =
            g_cuda_decode_trace.nsys_capture_range != 0;
    }
    if (g_cuda_decode_trace.nsys_capture_active) {
        g_cuda_decode_trace.nsys_token_range =
            cuda_decode_trace_nvtx_range(
                "ds4.decode.token", 0xff00ff80u);
    }
    g_cuda_decode_trace.active_sample_id.store(
        sample_id, std::memory_order_release);
    if (cudaEventRecord(
            g_cuda_decode_trace.token_start.handle, 0) != cudaSuccess) {
        (void)cudaGetLastError();
        g_cuda_decode_trace.dropped_records.fetch_add(
            1u, std::memory_order_relaxed);
        g_cuda_decode_trace.active_sample_id.store(
            0u, std::memory_order_release);
        g_cuda_decode_trace.active.store(0, std::memory_order_release);
    }
}

extern "C" void ds4_gpu_decode_trace_layer_begin(
        uint32_t layer, uint64_t position) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position ||
        layer >= CUDA_MOE_LAYER_COUNT ||
        (g_cuda_decode_trace.layer_mask & (1ull << layer)) == 0u) {
        return;
    }
    cuda_decode_trace_layer_record &record =
        g_cuda_decode_trace.current.layer[layer];
    record.selected = 1u;
    record.sample_id_match = 1u;
    record.host_started_qpc = cuda_decode_trace_qpc_now_raw();
    g_cuda_decode_trace.active_layer.store(
        layer, std::memory_order_release);
    if (g_cuda_decode_trace.nsys_capture_active) {
        g_cuda_decode_trace.nsys_layer_range[layer] =
            cuda_decode_trace_nvtx_range(
                "ds4.decode.layer", 0xffffa000u);
    }
    if (cudaEventRecord(
            g_cuda_decode_trace.layer_start[layer].handle,
            0) == cudaSuccess) {
        g_cuda_decode_trace.layer_started[layer] = 1u;
    } else {
        (void)cudaGetLastError();
    }
}

extern "C" void ds4_gpu_decode_trace_layer_end(
        uint32_t layer, uint64_t position) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position ||
        layer >= CUDA_MOE_LAYER_COUNT ||
        !g_cuda_decode_trace.layer_started[layer]) {
        return;
    }
    g_cuda_decode_trace.current.layer[layer].host_ended_qpc =
        cuda_decode_trace_qpc_now_raw();
    if (cudaEventRecord(
            g_cuda_decode_trace.layer_end[layer].handle,
            0) == cudaSuccess) {
        g_cuda_decode_trace.layer_ended[layer] = 1u;
    } else {
        (void)cudaGetLastError();
    }
    if (g_cuda_decode_trace.nsys_layer_range[layer] &&
        g_cuda_decode_trace.nsys_domain) {
        nvtxDomainRangeEnd(
            g_cuda_decode_trace.nsys_domain,
            g_cuda_decode_trace.nsys_layer_range[layer]);
        g_cuda_decode_trace.nsys_layer_range[layer] = 0;
    }
    g_cuda_decode_trace.active_layer.store(
        UINT32_MAX, std::memory_order_release);
}

extern "C" void ds4_gpu_decode_trace_output_begin(
        uint64_t position) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position) {
        return;
    }
    g_cuda_decode_trace.current.output_submit_started_qpc =
        cuda_decode_trace_qpc_now_raw();
    if (cudaEventRecord(
            g_cuda_decode_trace.output_start.handle,
            0) == cudaSuccess) {
        g_cuda_decode_trace.output_started = 1u;
    } else {
        (void)cudaGetLastError();
    }
}

extern "C" void ds4_gpu_decode_trace_output_end(
        uint64_t position) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position ||
        !g_cuda_decode_trace.output_started) {
        return;
    }
    const uint64_t now = cuda_decode_trace_qpc_now_raw();
    g_cuda_decode_trace.current.output_submit_ticks +=
        now - g_cuda_decode_trace.current.output_submit_started_qpc;
    if (cudaEventRecord(
            g_cuda_decode_trace.output_end.handle,
            0) == cudaSuccess) {
        g_cuda_decode_trace.output_ended = 1u;
    } else {
        (void)cudaGetLastError();
    }
}

extern "C" void ds4_gpu_decode_trace_split_sync_begin(
        uint64_t position) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position) {
        return;
    }
    g_cuda_decode_trace.current.split_sync_started_qpc =
        cuda_decode_trace_qpc_now_raw();
}

extern "C" void ds4_gpu_decode_trace_split_sync_end(
        uint64_t position) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position ||
        !g_cuda_decode_trace.current.split_sync_started_qpc) {
        return;
    }
    g_cuda_decode_trace.current.split_sync_ticks +=
        cuda_decode_trace_qpc_now_raw() -
        g_cuda_decode_trace.current.split_sync_started_qpc;
    g_cuda_decode_trace.current.split_sync_count++;
    g_cuda_decode_trace.current.split_sync_started_qpc = 0u;
}

extern "C" void ds4_gpu_decode_trace_token_encoded(uint64_t position) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position) {
        return;
    }
    g_cuda_decode_trace.current.end_sync_started_qpc =
        cuda_decode_trace_qpc_now_raw();
    if (cudaEventRecord(
            g_cuda_decode_trace.token_end.handle,
            0) == cudaSuccess) {
        g_cuda_decode_trace.current.token_event_recorded = 1u;
    } else {
        (void)cudaGetLastError();
    }
}

static int cuda_decode_trace_elapsed(
        const cuda_trace_timing_event &start,
        const cuda_trace_timing_event &end,
        float *milliseconds) {
    if (!start.handle || !end.handle || !milliseconds) return 0;
    return cudaEventElapsedTime(
        milliseconds, start.handle, end.handle) == cudaSuccess;
}

extern "C" void ds4_gpu_decode_trace_sync_complete(
        uint64_t position, int success) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position) {
        return;
    }
    const uint64_t now = cuda_decode_trace_qpc_now_raw();
    if (g_cuda_decode_trace.current.end_sync_started_qpc) {
        g_cuda_decode_trace.current.end_sync_ticks =
            now - g_cuda_decode_trace.current.end_sync_started_qpc;
    }
    if (!success || !g_cuda_decode_trace.current.token_event_recorded) {
        return;
    }
    cuda_decode_trace_record &record = g_cuda_decode_trace.current;
    record.gpu_default_valid = cuda_decode_trace_elapsed(
        g_cuda_decode_trace.token_start,
        g_cuda_decode_trace.token_end,
        &record.gpu_default_window_ms) ? 1u : 0u;
    if (g_cuda_decode_trace.embedding_started &&
        g_cuda_decode_trace.embedding_ended) {
        record.embedding_gpu_valid = cuda_decode_trace_elapsed(
            g_cuda_decode_trace.embedding_start,
            g_cuda_decode_trace.embedding_end,
            &record.embedding_gpu_window_ms) ? 1u : 0u;
    }
    if (g_cuda_decode_trace.output_started &&
        g_cuda_decode_trace.output_ended) {
        record.output_gpu_valid = cuda_decode_trace_elapsed(
            g_cuda_decode_trace.output_start,
            g_cuda_decode_trace.output_end,
            &record.output_gpu_window_ms) ? 1u : 0u;
    }
    for (uint32_t layer = 0; layer < CUDA_MOE_LAYER_COUNT; layer++) {
        cuda_decode_trace_layer_record &item = record.layer[layer];
        if (g_cuda_decode_trace.layer_started[layer] &&
            g_cuda_decode_trace.layer_ended[layer]) {
            item.gpu_default_valid = cuda_decode_trace_elapsed(
                g_cuda_decode_trace.layer_start[layer],
                g_cuda_decode_trace.layer_end[layer],
                &item.gpu_default_window_ms) ? 1u : 0u;
        }
        if (g_cuda_decode_trace.upload_started[layer].load(
                std::memory_order_acquire) &&
            g_cuda_decode_trace.upload_ended[layer].load(
                std::memory_order_acquire)) {
            item.upload_gpu_valid = cuda_decode_trace_elapsed(
                g_cuda_decode_trace.upload_start[layer],
                g_cuda_decode_trace.upload_end[layer],
                &item.upload_gpu_window_ms) ? 1u : 0u;
        }
    }
    record.elapsed_resolved = 1u;
}

extern "C" void ds4_gpu_decode_trace_logits_begin(
        uint64_t position) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position) {
        return;
    }
    g_cuda_decode_trace.current.logits_started_qpc =
        cuda_decode_trace_qpc_now_raw();
}

extern "C" void ds4_gpu_decode_trace_logits_end(
        uint64_t position, uint64_t bytes, int success) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position ||
        !g_cuda_decode_trace.current.logits_started_qpc) {
        return;
    }
    g_cuda_decode_trace.current.logits_api_ticks +=
        cuda_decode_trace_qpc_now_raw() -
        g_cuda_decode_trace.current.logits_started_qpc;
    g_cuda_decode_trace.current.logits_d2h_count++;
    if (success) {
        g_cuda_decode_trace.current.logits_d2h_bytes += bytes;
    }
    g_cuda_decode_trace.current.logits_started_qpc = 0u;
}

static void cuda_decode_trace_upload_begin(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request) {
    const uint32_t layer = request.layer_index;
    if (!cache || !cache->route_upload_stream ||
        !g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        request.trace_sample_id == 0u ||
        request.trace_sample_id != g_cuda_decode_trace.active_sample_id.load(
            std::memory_order_acquire) ||
        layer >= CUDA_MOE_LAYER_COUNT ||
        (g_cuda_decode_trace.layer_mask & (1ull << layer)) == 0u) {
        return;
    }
    if (cudaEventRecord(
            g_cuda_decode_trace.upload_start[layer].handle,
            cache->route_upload_stream) == cudaSuccess) {
        g_cuda_decode_trace.upload_started[layer].store(
            1u, std::memory_order_release);
    } else {
        (void)cudaGetLastError();
    }
}

static void cuda_decode_trace_upload_end(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request) {
    const uint32_t layer = request.layer_index;
    if (!cache || !cache->route_upload_stream ||
        request.trace_sample_id == 0u ||
        request.trace_sample_id != g_cuda_decode_trace.active_sample_id.load(
            std::memory_order_acquire) ||
        layer >= CUDA_MOE_LAYER_COUNT ||
        !g_cuda_decode_trace.upload_started[layer].load(
            std::memory_order_acquire)) {
        return;
    }
    if (cudaEventRecord(
            g_cuda_decode_trace.upload_end[layer].handle,
            cache->route_upload_stream) == cudaSuccess) {
        g_cuda_decode_trace.upload_ended[layer].store(
            1u, std::memory_order_release);
    } else {
        (void)cudaGetLastError();
    }
}

extern "C" void ds4_gpu_decode_trace_token_end(
        uint64_t position, int success) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire) != position) {
        return;
    }
    cuda_decode_trace_record &record = g_cuda_decode_trace.current;
    record.host_ended_qpc = cuda_decode_trace_qpc_now_raw();
    record.success = success ? 1u : 0u;
    const uint64_t pread_count_end =
        g_cuda_decode_trace.trace_pread_count.load(
            std::memory_order_acquire);
    const uint64_t pread_bytes_end =
        g_cuda_decode_trace.trace_pread_bytes.load(
            std::memory_order_acquire);
    const uint64_t pread_wait_end =
        g_cuda_decode_trace.trace_pread_wait_ticks.load(
            std::memory_order_acquire);
    if (pread_count_end >= record.pread_count_begin &&
        pread_bytes_end >= record.pread_bytes_begin &&
        pread_wait_end >= record.pread_wait_ticks_begin) {
        record.pread_count =
            pread_count_end - record.pread_count_begin;
        record.pread_bytes =
            pread_bytes_end - record.pread_bytes_begin;
        record.pread_wait_ticks =
            pread_wait_end - record.pread_wait_ticks_begin;
        record.io_counter_valid = 1u;
    }
    record.record_complete =
        success && record.elapsed_resolved &&
        record.io_counter_valid ? 1u : 0u;
    if (g_cuda_decode_trace.record_count <
        g_cuda_decode_trace.records.size()) {
        g_cuda_decode_trace.records[
            g_cuda_decode_trace.record_count++] = record;
    } else {
        g_cuda_decode_trace.dropped_records.fetch_add(
            1u, std::memory_order_relaxed);
    }
    if (g_cuda_decode_trace.nsys_token_range &&
        g_cuda_decode_trace.nsys_domain) {
        nvtxDomainRangeEnd(
            g_cuda_decode_trace.nsys_domain,
            g_cuda_decode_trace.nsys_token_range);
        g_cuda_decode_trace.nsys_token_range = 0;
    }
    if (g_cuda_decode_trace.nsys_capture_active &&
        (position >= g_cuda_decode_trace.nsys_last_position ||
         !success)) {
        cuda_decode_trace_nvtx_close();
    }
    g_cuda_decode_trace.active_layer.store(
        UINT32_MAX, std::memory_order_release);
    g_cuda_decode_trace.active_sample_id.store(
        0u, std::memory_order_release);
    g_cuda_decode_trace.active.store(0, std::memory_order_release);
}

static cuda_decode_trace_layer_record *
cuda_decode_trace_current_layer(void) {
    if (!ds4_gpu_decode_trace_enabled ||
        !g_cuda_decode_trace.active.load(std::memory_order_acquire)) {
        return NULL;
    }
    const uint32_t layer = g_cuda_decode_trace.active_layer.load(
        std::memory_order_acquire);
    if (layer >= CUDA_MOE_LAYER_COUNT ||
        (g_cuda_decode_trace.layer_mask & (1ull << layer)) == 0u) {
        return NULL;
    }
    return &g_cuda_decode_trace.current.layer[layer];
}

static uint64_t cuda_decode_trace_embedding_begin(void) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire)) {
        return 0u;
    }
    if (cudaEventRecord(
            g_cuda_decode_trace.embedding_start.handle,
            0) == cudaSuccess) {
        g_cuda_decode_trace.embedding_started = 1u;
    } else {
        (void)cudaGetLastError();
    }
    return cuda_decode_trace_qpc_now_raw();
}

static uint64_t cuda_decode_trace_embedding_host_copy_end(
        uint64_t started) {
    if (!started ||
        !g_cuda_decode_trace.active.load(std::memory_order_acquire)) {
        return 0u;
    }
    const uint64_t now = cuda_decode_trace_qpc_now_raw();
    g_cuda_decode_trace.current.embedding_host_copy_ticks +=
        now - started;
    return now;
}

static uint64_t cuda_decode_trace_embedding_h2d_end(
        uint64_t started, uint64_t bytes, int success) {
    if (!started ||
        !g_cuda_decode_trace.active.load(std::memory_order_acquire)) {
        return 0u;
    }
    const uint64_t now = cuda_decode_trace_qpc_now_raw();
    g_cuda_decode_trace.current.embedding_h2d_api_ticks +=
        now - started;
    g_cuda_decode_trace.current.embedding_h2d_count++;
    if (success) {
        g_cuda_decode_trace.current.embedding_h2d_bytes += bytes;
    }
    return now;
}

static void cuda_decode_trace_embedding_end(void) {
    if (!g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        !g_cuda_decode_trace.embedding_started) {
        return;
    }
    if (cudaEventRecord(
            g_cuda_decode_trace.embedding_end.handle,
            0) == cudaSuccess) {
        g_cuda_decode_trace.embedding_ended = 1u;
    } else {
        (void)cudaGetLastError();
    }
}

static uint64_t cuda_decode_trace_kv_h2d_begin(void) {
    return cuda_decode_trace_current_layer()
        ? cuda_decode_trace_qpc_now_raw() : 0u;
}

static void cuda_decode_trace_kv_batch(
        uint32_t rows, uint32_t spans) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_current_layer();
    if (!record) return;
    record->kv_batch_count++;
    record->kv_span_count += spans;
    (void)rows;
}

static void cuda_decode_trace_kv_h2d_end(
        uint64_t started, uint64_t bytes, int success) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_current_layer();
    if (!record || !started) return;
    record->kv_h2d_api_ticks +=
        cuda_decode_trace_qpc_now_raw() - started;
    record->kv_h2d_count++;
    if (success) record->kv_h2d_bytes += bytes;
}

static void cuda_decode_trace_kv_wait_event(void) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_current_layer();
    if (record) record->kv_stream_wait_event_count++;
}

static uint64_t cuda_decode_trace_route_context(
        uint32_t layer, uint64_t *position_out) {
    if (!ds4_gpu_decode_trace_enabled ||
        !g_cuda_decode_trace.active.load(std::memory_order_acquire) ||
        layer >= CUDA_MOE_LAYER_COUNT ||
        (g_cuda_decode_trace.layer_mask & (1ull << layer)) == 0u) {
        return 0u;
    }
    const uint64_t sample_id =
        g_cuda_decode_trace.active_sample_id.load(
            std::memory_order_acquire);
    if (!sample_id) return 0u;
    if (position_out) {
        *position_out = g_cuda_decode_trace.active_position.load(
            std::memory_order_acquire);
    }
    return sample_id;
}

static cuda_decode_trace_layer_record *
cuda_decode_trace_request_layer(
        uint64_t sample_id, uint32_t layer) {
    if (!sample_id || layer >= CUDA_MOE_LAYER_COUNT ||
        sample_id != g_cuda_decode_trace.active_sample_id.load(
            std::memory_order_acquire) ||
        !g_cuda_decode_trace.active.load(std::memory_order_acquire)) {
        return NULL;
    }
    return &g_cuda_decode_trace.current.layer[layer];
}

static void cuda_decode_trace_note_resolver_submit(
        uint64_t sample_id, uint32_t layer,
        uint64_t started, uint64_t ended) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(sample_id, layer);
    if (record && ended >= started) {
        record->resolver_submit_ticks += ended - started;
    }
}

static void cuda_decode_trace_note_prior_queue(
        uint64_t sample_id, uint32_t layer,
        uint64_t started, uint64_t ended) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(sample_id, layer);
    if (record && ended >= started) {
        record->queue_prior_consume_ticks += ended - started;
    }
}

static void cuda_decode_trace_worker_begin(
        const cuda_moe_route_request &request) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(
            request.trace_sample_id, request.layer_index);
    if (!record) {
        if (request.trace_sample_id) {
            g_cuda_decode_trace.worker_attribution_errors.fetch_add(
                1u, std::memory_order_relaxed);
        }
        return;
    }
    const uint64_t now = cuda_decode_trace_qpc_now_raw();
    record->worker_started_qpc = now;
    if (request.trace_submit_qpc && now >= request.trace_submit_qpc) {
        record->worker_queue_ticks +=
            now - request.trace_submit_qpc;
    }
    record->sample_id_match = 1u;
}

static void cuda_decode_trace_worker_end(
        const cuda_moe_route_request &request) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(
            request.trace_sample_id, request.layer_index);
    if (!record || !record->worker_started_qpc) return;
    const uint64_t now = cuda_decode_trace_qpc_now_raw();
    record->worker_service_ticks +=
        now - record->worker_started_qpc;
    record->worker_started_qpc = 0u;
}

static uint64_t cuda_decode_trace_request_qpc(
        const cuda_moe_route_request &request) {
    return cuda_decode_trace_request_layer(
        request.trace_sample_id, request.layer_index)
        ? cuda_decode_trace_qpc_now_raw() : 0u;
}

static void cuda_decode_trace_note_pread(
        uint64_t sample_id, uint32_t layer, uint64_t started,
        uint64_t count, uint64_t bytes) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(sample_id, layer);
    if (!record) return;
    const uint64_t now = cuda_decode_trace_qpc_now_raw();
    const uint64_t ticks = started && now >= started
        ? now - started : 0u;
    record->pread_wait_ticks += ticks;
    record->pread_count += count;
    record->pread_bytes += bytes;
    g_cuda_decode_trace.trace_pread_wait_ticks.fetch_add(
        ticks, std::memory_order_relaxed);
    g_cuda_decode_trace.trace_pread_count.fetch_add(
        count, std::memory_order_relaxed);
    g_cuda_decode_trace.trace_pread_bytes.fetch_add(
        bytes, std::memory_order_relaxed);
}

static void cuda_decode_trace_note_qd(
        const cuda_moe_route_request &request, uint64_t started,
        uint64_t submits, uint64_t completions, uint64_t bytes,
        uint64_t max_inflight) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(
            request.trace_sample_id, request.layer_index);
    if (!record) return;
    record->qd_submit_count += submits;
    record->qd_completion_count += completions;
    if (max_inflight > record->qd_max_inflight) {
        record->qd_max_inflight = max_inflight;
    }
    cuda_decode_trace_note_pread(
        request.trace_sample_id, request.layer_index,
        started, completions, bytes);
}

static void cuda_decode_trace_note_h2d(
        const cuda_moe_route_request *request, uint64_t started,
        uint64_t count, uint64_t bytes, int success) {
    if (!request) return;
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(
            request->trace_sample_id, request->layer_index);
    if (!record) return;
    const uint64_t now = cuda_decode_trace_qpc_now_raw();
    if (started && now >= started) {
        record->h2d_api_ticks += now - started;
    }
    if (success) {
        record->h2d_count += count;
        record->h2d_bytes += bytes;
    }
}

static void cuda_decode_trace_note_d2h(
        uint32_t layer, uint64_t started,
        uint64_t count, uint64_t bytes, int success) {
    uint64_t position = 0u;
    const uint64_t sample_id =
        cuda_decode_trace_route_context(layer, &position);
    (void)position;
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(sample_id, layer);
    if (!record) return;
    const uint64_t now = cuda_decode_trace_qpc_now_raw();
    if (started && now >= started) {
        record->d2h_api_ticks += now - started;
    }
    record->d2h_count += count;
    if (success) record->d2h_bytes += bytes;
}

static void cuda_decode_trace_note_upload_drain(
        const cuda_moe_route_request *request, uint64_t started) {
    if (!request || !started) return;
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(
            request->trace_sample_id, request->layer_index);
    if (!record) return;
    record->upload_drain_ticks +=
        cuda_decode_trace_qpc_now_raw() - started;
    record->upload_drain_count++;
}

static void cuda_decode_trace_note_publish(
        const cuda_moe_route_request &request,
        uint64_t kernels, uint64_t routes) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(
            request.trace_sample_id, request.layer_index);
    if (!record) return;
    record->publish_kernel_count += kernels;
    record->publish_route_count += routes;
}

static void cuda_decode_trace_note_resolver_wait(
        uint64_t sample_id, uint32_t layer,
        uint64_t stream_ticks, uint64_t ready_ticks,
        uint64_t polls) {
    cuda_decode_trace_layer_record *record =
        cuda_decode_trace_request_layer(sample_id, layer);
    if (!record) return;
    record->resolver_stream_wait_ticks += stream_ticks;
    record->worker_ready_wait_ticks += ready_ticks;
    record->worker_ready_poll_count += polls;
}

static cuda_moe_expert_cache *cuda_moe_expert_cache_prepare(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes);

static int cuda_moe_expert_cache_grow_requested(void) {
    const char *env = getenv("DS4_CUDA_EXPERT_CACHE_GROW");
    return env && strcmp(env, "1") == 0;
}

/* =======================================================================
 * Ciclo di vita del probe del picco VRAM intra-token.
 * Riusa gli stessi tre punti di emissione della riga [vram-prio]:
 * decode-start (azzeramento + fotografia), osservatore per-token (riga
 * periodica) e request-end (sintesi con il minimo assoluto del run).
 * ======================================================================= */
static uint64_t ds4_vram_peak_query_free_bytes(void) {
    const double t0 = cuda_wall_sec();
    size_t free_bytes = 0;
    size_t total_bytes = 0;
    const cudaError_t err = cudaMemGetInfo(&free_bytes, &total_bytes);
    const double t1 = cuda_wall_sec();
    g_vram_peak.run_driver_queries.fetch_add(1u, std::memory_order_relaxed);
    const double dt_ns = (t1 - t0) * 1.0e9;
    g_vram_peak.run_probe_ns.fetch_add(
        dt_ns > 0.0 ? (uint64_t)dt_ns : 0ull, std::memory_order_relaxed);
    if (err != cudaSuccess) {
        (void)cudaGetLastError();
        return 0ull;
    }
    return (uint64_t)free_bytes;
}

static const char *ds4_vram_peak_str(const char *s, const char *fallback) {
    return (s && s[0]) ? s : fallback;
}

static void ds4_vram_peak_run_reset(void) {
    if (!ds4_vram_peak_probe_enabled()) return;
    g_vram_peak.armed.store(0, std::memory_order_release);
    g_vram_peak.run_free_min.store(0ull, std::memory_order_relaxed);
    g_vram_peak.run_min_token.store(0ull, std::memory_order_relaxed);
    g_vram_peak.run_pool_at_min.store(0ull, std::memory_order_relaxed);
    g_vram_peak.run_ranges_at_min.store(0ull, std::memory_order_relaxed);
    g_vram_peak.run_bytes_at_min.store(0ull, std::memory_order_relaxed);
    g_vram_peak.run_pool_hwm.store(0ull, std::memory_order_relaxed);
    g_vram_peak.run_what_at_min.store(NULL, std::memory_order_relaxed);
    g_vram_peak.run_phase_at_min.store(NULL, std::memory_order_relaxed);
    g_vram_peak.run_line_at_min.store(0, std::memory_order_relaxed);
    g_vram_peak.run_allocs.store(0ull, std::memory_order_relaxed);
    g_vram_peak.run_frees.store(0ull, std::memory_order_relaxed);
    g_vram_peak.run_samples.store(0ull, std::memory_order_relaxed);
    g_vram_peak.run_driver_queries.store(0ull, std::memory_order_relaxed);
    g_vram_peak.run_probe_ns.store(0ull, std::memory_order_relaxed);
    g_vram_peak.tokens_seen.store(0ull, std::memory_order_relaxed);
    g_vram_peak.next_log.store(0ull, std::memory_order_relaxed);
    fprintf(stderr,
            "ds4: [vram-peak] phase=arm every_tokens=%llu query_every=%llu "
            "free_at_decode_start=%llu\n",
            (unsigned long long)ds4_vram_peak_log_every_tokens(),
            (unsigned long long)ds4_vram_peak_query_every(),
            (unsigned long long)g_vram_free_at_decode_start);
}

static void ds4_vram_peak_token_begin(uint64_t token_index) {
    if (!ds4_vram_peak_probe_enabled()) return;
    const uint64_t free_now = ds4_vram_peak_query_free_bytes();
    g_vram_peak.token_index.store(token_index, std::memory_order_relaxed);
    g_vram_peak.free_at_token_start.store(free_now, std::memory_order_relaxed);
    g_vram_peak.tok_free_min.store(UINT64_MAX, std::memory_order_relaxed);
    g_vram_peak.tok_pool_at_min.store(0ull, std::memory_order_relaxed);
    g_vram_peak.tok_ranges_at_min.store(0ull, std::memory_order_relaxed);
    g_vram_peak.tok_bytes_at_min.store(0ull, std::memory_order_relaxed);
    g_vram_peak.tok_pool_hwm.store(0ull, std::memory_order_relaxed);
    g_vram_peak.tok_what_at_min.store(NULL, std::memory_order_relaxed);
    g_vram_peak.tok_phase_at_min.store(NULL, std::memory_order_relaxed);
    g_vram_peak.tok_line_at_min.store(0, std::memory_order_relaxed);
    g_vram_peak.tok_allocs.store(0ull, std::memory_order_relaxed);
    g_vram_peak.tok_frees.store(0ull, std::memory_order_relaxed);
    g_vram_peak.tok_samples.store(0ull, std::memory_order_relaxed);
    g_vram_peak.armed.store(1, std::memory_order_release);
}

static void ds4_vram_peak_token_end(uint64_t token_index,
                                    uint32_t token_count) {
    if (!ds4_vram_peak_probe_enabled()) return;
    g_vram_peak.armed.store(0, std::memory_order_release);
    if (token_count == 0u) return;
    const uint64_t every = ds4_vram_peak_log_every_tokens();
    if (every == 0ull) return;
    const uint64_t seen =
        g_vram_peak.tokens_seen.fetch_add(token_count,
                                          std::memory_order_relaxed) +
        token_count;
    uint64_t next = g_vram_peak.next_log.load(std::memory_order_relaxed);
    if (next == 0ull) next = every;
    if (seen < next) {
        g_vram_peak.next_log.store(next, std::memory_order_relaxed);
        return;
    }
    g_vram_peak.next_log.store(seen + every, std::memory_order_relaxed);

    const uint64_t start = g_vram_peak.free_at_token_start.load(
        std::memory_order_relaxed);
    const uint64_t samples = g_vram_peak.tok_samples.load(
        std::memory_order_relaxed);
    uint64_t min_bytes = g_vram_peak.tok_free_min.load(
        std::memory_order_relaxed);
    const char *what = ds4_vram_peak_str(
        g_vram_peak.tok_what_at_min.load(std::memory_order_relaxed), NULL);
    if (min_bytes == UINT64_MAX) {
        /* Nessun evento di alloc/free dentro il token: per quanto vede questo
         * processo la VRAM libera non e' scesa sotto il valore di inizio token.
         * Dichiarato, non riempito con una stima. */
        min_bytes = start;
        what = "no-alloc-event";
    }
    const uint64_t extra = (start > min_bytes) ? (start - min_bytes) : 0ull;
    fprintf(stderr,
            "ds4: [vram-peak] pos=%llu free_min_bytes=%llu "
            "free_at_token_start=%llu peak_extra_bytes=%llu what_at_min=%s "
            "allocs=%llu frees=%llu phase_at_min=%s line_at_min=%d "
            "bytes_at_min=%llu stream_pool_bytes_at_min=%llu "
            "model_range_bytes_at_min=%llu stream_pool_bytes_max=%llu "
            "stream_reserve_bytes=%llu "
            "samples=%llu free_min_mib=%.1f peak_extra_mib=%.1f\n",
            (unsigned long long)token_index,
            (unsigned long long)min_bytes,
            (unsigned long long)start,
            (unsigned long long)extra,
            ds4_vram_peak_str(what, "?"),
            (unsigned long long)g_vram_peak.tok_allocs.load(
                std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.tok_frees.load(
                std::memory_order_relaxed),
            ds4_vram_peak_str(
                g_vram_peak.tok_phase_at_min.load(std::memory_order_relaxed),
                "none"),
            g_vram_peak.tok_line_at_min.load(std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.tok_bytes_at_min.load(
                std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.tok_pool_at_min.load(
                std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.tok_ranges_at_min.load(
                std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.tok_pool_hwm.load(
                std::memory_order_relaxed),
            /* Soglia di policy che cuda_model_stream_alloc() impone prima di
             * concedere una cudaMalloc: e' il pavimento contro cui va letto
             * free_min_bytes, e quindi il numero che decide quanti slot di cache
             * esperti stanno davvero in piedi. */
            (unsigned long long)cuda_model_stream_reserve_bytes(),
            (unsigned long long)samples,
            (double)min_bytes / 1048576.0,
            (double)extra / 1048576.0);
}

static void ds4_vram_peak_summary(const char *phase) {
    if (!ds4_vram_peak_probe_enabled()) return;
    const uint64_t samples = g_vram_peak.run_samples.load(
        std::memory_order_relaxed);
    const uint64_t run_min = g_vram_peak.run_free_min.load(
        std::memory_order_relaxed);
    const uint64_t decode_start = g_vram_free_at_decode_start;
    const uint64_t extra = (samples != 0ull && decode_start > run_min)
        ? (decode_start - run_min) : 0ull;
    const uint64_t probe_ns = g_vram_peak.run_probe_ns.load(
        std::memory_order_relaxed);
    fprintf(stderr,
            "ds4: [vram-peak-summary] phase=%s run_free_min_bytes=%llu "
            "run_free_min_mib=%.1f min_at_pos=%llu what_at_min=%s "
            "phase_at_min=%s line_at_min=%d bytes_at_min=%llu "
            "stream_pool_bytes_at_min=%llu model_range_bytes_at_min=%llu "
            "stream_pool_bytes_max=%llu stream_reserve_bytes=%llu "
            "stream_hot_reserve_bytes=%llu free_at_decode_start=%llu "
            "peak_extra_vs_decode_start_bytes=%llu "
            "peak_extra_vs_decode_start_mib=%.1f tokens=%llu allocs=%llu "
            "frees=%llu samples=%llu driver_queries=%llu probe_ms=%.3f "
            "status=%s\n",
            phase ? phase : "?",
            (unsigned long long)run_min,
            (double)run_min / 1048576.0,
            (unsigned long long)g_vram_peak.run_min_token.load(
                std::memory_order_relaxed),
            ds4_vram_peak_str(
                g_vram_peak.run_what_at_min.load(std::memory_order_relaxed),
                "none"),
            ds4_vram_peak_str(
                g_vram_peak.run_phase_at_min.load(std::memory_order_relaxed),
                "none"),
            g_vram_peak.run_line_at_min.load(std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.run_bytes_at_min.load(
                std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.run_pool_at_min.load(
                std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.run_ranges_at_min.load(
                std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.run_pool_hwm.load(
                std::memory_order_relaxed),
            (unsigned long long)cuda_model_stream_reserve_bytes(),
            (unsigned long long)cuda_model_stream_hot_reserve_bytes(),
            (unsigned long long)decode_start,
            (unsigned long long)extra,
            (double)extra / 1048576.0,
            (unsigned long long)g_vram_peak.tokens_seen.load(
                std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.run_allocs.load(
                std::memory_order_relaxed),
            (unsigned long long)g_vram_peak.run_frees.load(
                std::memory_order_relaxed),
            (unsigned long long)samples,
            (unsigned long long)g_vram_peak.run_driver_queries.load(
                std::memory_order_relaxed),
            (double)probe_ns / 1.0e6,
            samples != 0ull ? "ok" : "no-samples");
}

static void cuda_vram_ledger_log(
        const char *phase,
        uint64_t released_bytes,
        const char *release_status) {
    size_t free_bytes = 0;
    size_t total_bytes = 0;
    const cudaError_t mem_err = cudaMemGetInfo(&free_bytes, &total_bytes);
    fprintf(stderr,
            "ds4: [vram-ledger] phase=%s free_bytes=%llu total_bytes=%llu "
            "g_cuda_tmp_bytes=%llu expert_cache_count=%u "
            "expert_cache_capacity=%u released_bytes=%llu "
            "release_status=%s mem_status=%s\n",
            phase,
            (unsigned long long)free_bytes,
            (unsigned long long)total_bytes,
            (unsigned long long)g_cuda_tmp_bytes,
            g_moe_expert_cache.count,
            g_moe_expert_cache.capacity,
            (unsigned long long)released_bytes,
            release_status,
            mem_err == cudaSuccess ? "ok" : cudaGetErrorString(mem_err));
}

/* Riga di stato del gestore VRAM a priorita' invertita, accanto a [vram-ledger].
 * EMESSA SEMPRE, in entrambi gli stati di DS4_CUDA_VRAM_INVERTED_PRIORITY, cosi' i due
 * bracci dell'A/B producono la stessa riga e sono confrontabili campo per campo.
 * evict_kv e' strutturalmente 0: la KV non e' registrata in g_model_ranges e quindi non
 * e' una classe di vittima su questo percorso (vedi .microbench/vraminv/ANALISI.md). */
static void cuda_vram_prio_log(const char *phase) {
    size_t free_bytes = 0;
    size_t total_bytes = 0;
    const cudaError_t mem_err = cudaMemGetInfo(&free_bytes, &total_bytes);
    if (mem_err != cudaSuccess) (void)cudaGetLastError();
    g_vram_prio_expert_slots_current = g_moe_expert_cache.capacity;
    fprintf(stderr,
            "ds4: [vram-prio] phase=%s inverted=%d elastic=%d "
            "evict_backbone=%llu evict_expert=%llu evict_kv=%llu "
            "backbone_evicted_bytes=%llu backbone_reload_bytes=%llu "
            "backbone_reloads=%llu expert_relaxed_saves=%llu "
            "expert_slots_current=%u expert_slots_resident=%u "
            "expert_slots_requested=%u "
            "vram_free_at_decode_start=%llu vram_free_now=%llu "
            "backbone_reserve_mib=%.1f hysteresis_mib=%.1f "
            "stabilized=%d stabilized_slots=%u evicts_total=%llu mem_status=%s\n",
            phase,
            cuda_vram_inverted_priority_enabled(),
            cuda_vram_elastic_expert_slots_enabled(),
            (unsigned long long)g_vram_prio_evict_backbone,
            (unsigned long long)g_vram_prio_evict_expert,
            (unsigned long long)g_vram_prio_evict_kv,
            (unsigned long long)g_vram_prio_backbone_evicted_bytes,
            (unsigned long long)g_vram_prio_backbone_reload_bytes,
            (unsigned long long)g_vram_prio_backbone_reloads,
            (unsigned long long)g_vram_prio_expert_relaxed_saves,
            g_vram_prio_expert_slots_current,
            g_moe_expert_cache.count,
            g_moe_expert_cache.requested,
            (unsigned long long)g_vram_free_at_decode_start,
            (unsigned long long)free_bytes,
            (double)cuda_vram_backbone_reserve_bytes() / 1048576.0,
            (double)cuda_vram_hysteresis_bytes() / 1048576.0,
            g_vram_prio_stabilized,
            g_vram_prio_stabilized_slots,
            (unsigned long long)g_model_evict_count,
            mem_err == cudaSuccess ? "ok" : "query-failed");
}

extern "C" void ds4_gpu_vram_ledger_decode_start(void) {
    /* FIX-B: il tetto ai ripieghi e' "per richiesta", quindi la serie
     * consecutiva riparte a ogni decode. Neutro a flag spento (resta 0). */
    g_transient_timeout_fallback_streak.store(0u, std::memory_order_relaxed);
    uint64_t released_bytes = 0;
    uint64_t staged_released_bytes = 0;
    (void)cuda_kv_staged_migrate_to_host(&staged_released_bytes);
    const char *release_status = "disabled";
    const char *release = getenv("DS4_CUDA_RELEASE_PREFILL_SCRATCH");
    if (release && strcmp(release, "1") == 0) {
        release_status = "empty";
        if (g_cuda_tmp) {
            /*
             * Every current g_cuda_tmp user launches on the default stream,
             * including the cuBLAS prefill paths.  Fence the device anyway so
             * future non-default-stream users cannot race this boundary free.
             *
             * The graph-owned prefill_tokens and batch_* tensor family are
             * also prefill-sized, but their lifetime and re-grow path belong
             * to ds4.c.  V1 deliberately releases only this backend-owned
             * high-water scratch.
             */
            const cudaError_t sync_err = cudaDeviceSynchronize();
            if (sync_err != cudaSuccess) {
                release_status = "sync-error";
                (void)cudaGetLastError();
            } else {
                const uint64_t scratch_bytes = g_cuda_tmp_bytes;
                const cudaError_t free_err = cudaFree(g_cuda_tmp);
                if (free_err == cudaSuccess) {
                    g_cuda_tmp = NULL;
                    g_cuda_tmp_bytes = 0;
                    released_bytes = scratch_bytes;
                    release_status = "released";
                } else {
                    release_status = "free-error";
                    (void)cudaGetLastError();
                }
            }
        }
    }
    cuda_vram_ledger_log("decode-start",
                         released_bytes + staged_released_bytes,
                         release_status);
    ds4_gpu_alloc_trace_summary("decode-start");

    /* Fotografia della VRAM libera nell'istante giusto per il sizing elastico: dopo il
     * rilascio dello scratch di prefill e la migrazione della KV staged, prima che lo
     * slab esperti prenda la sua fetta. E' il numero da cui dipende la capacita'. */
    {
        size_t prio_free = 0;
        size_t prio_total = 0;
        if (cudaMemGetInfo(&prio_free, &prio_total) == cudaSuccess) {
            g_vram_free_at_decode_start = (uint64_t)prio_free;
        } else {
            (void)cudaGetLastError();
            g_vram_free_at_decode_start = 0;
        }
    }

    if (cuda_moe_expert_cache_grow_requested()) {
        g_moe_expert_cache_decode_started = 1;
        const uint64_t deferred_gate =
            g_moe_expert_cache_deferred_gate_expert_bytes;
        const uint64_t deferred_down =
            g_moe_expert_cache_deferred_down_expert_bytes;
        if (g_moe_expert_cache.capacity == 0 &&
            deferred_gate != 0 && deferred_down != 0) {
            cuda_moe_expert_cache *cache =
                cuda_moe_expert_cache_prepare(
                    deferred_gate, deferred_down);
            if (cache) {
                fprintf(stderr,
                        "ds4: [expert-cache-grow] mode=two-phase "
                        "result=ok capacity=%u requested=%u residents=%u\n",
                        cache->capacity, cache->requested, cache->count);
            } else {
                /*
                 * prepare() already logs every CUDA allocation failure and
                 * retries at a smaller capacity. No prefill cache existed, so
                 * failure cannot corrupt or discard resident slots.
                 */
                fprintf(stderr,
                        "ds4: [expert-cache-grow] mode=two-phase "
                        "result=failed cache=disabled "
                        "fallback=exact-streaming\n");
            }
        }
    }
    if (ds4_gpu_decode_trace_enabled) {
        /* This lifecycle edge is reached only after prefill has populated KV.
         * Nsight capture may arm from the next explicitly selected decode
         * position, never during model load or prefill. */
        g_cuda_decode_trace.kv_populated.store(
            1, std::memory_order_release);
    }
    /* Dopo il grow, cosi' expert_slots_current riflette la capacita' definitiva. */
    cuda_vram_prio_log("decode-start");
    /* Request-scoped expert transport starts at the decode boundary: prefill
     * traffic is intentionally outside both byte totals and decode wall time. */
    ds4_transport_decode_begin();
    /* Stesso istante della fotografia [vram-prio]: da qui in poi il probe del
     * picco misura contro g_vram_free_at_decode_start. */
    ds4_vram_peak_run_reset();
}

extern "C" void ds4_gpu_vram_ledger_request_end(void) {
    if (ds4_gpu_decode_trace_enabled) {
        cuda_decode_trace_nvtx_close();
        cuda_decode_trace_flush();
        g_cuda_decode_trace.kv_populated.store(
            0, std::memory_order_release);
    }
    if (cuda_moe_expert_cache_grow_requested()) {
        g_moe_expert_cache_decode_started = 0;
    }
    const int restored = cuda_kv_staged_restore_to_device();
    cuda_vram_ledger_log("request-end", 0,
                         restored ? "n/a" : "kv-restore-pending");
    ds4_gpu_alloc_trace_summary("request-end");
    /* Riga di chiusura: porta i contatori di sfratto/reload accumulati nel decode.
     * E' la riga da diffare fra i due bracci dell'A/B. */
    cuda_vram_prio_log("request-end");
    /* Sintesi del probe: minimo assoluto del run e token in cui e' avvenuto. */
    ds4_vram_peak_summary("request-end");
    ds4_transport_request_end();
}

template <bool G73, bool G132 = false, bool SCOPED = false, bool DOV = false>
static void *cuda_moe_route_worker(void *arg);
static os_thread_fn g_cuda_moe_route_worker_dispatch =
    cuda_moe_route_worker<false>;

static void cuda_moe_route_memory_barrier(void) {
#ifdef _WIN32
    MemoryBarrier();
#else
    __sync_synchronize();
#endif
}

/* Rotator (SSD-wrap) per-job I/O budget. Default keeps the historical 50ms
 * cap; the preset can raise it because queueing delay alone was observed to
 * expire the 50ms budget (job failed in 2us at dequeue, wave 58 of
 * g73gate_20260722_122722), and a single expiry used to latch the whole
 * rotator dead. Clamped to the transient timeout upper bound. */
static double cuda_g133_rotator_io_timeout_seconds(void) {
    static int initialized = 0;
    static double timeout_seconds = 0.050;
    if (initialized) return timeout_seconds;
    initialized = 1;
    const char *value = getenv("DS4_G133_ROTATOR_IO_TIMEOUT_S");
    if (!value || !value[0]) return timeout_seconds;
    char *end = NULL;
    errno = 0;
    const double parsed = strtod(value, &end);
    if (errno == 0 && end && *end == '\0' && isfinite(parsed) &&
        parsed > 0.0 && parsed <= 3600.0) {
        timeout_seconds = parsed;
    } else {
        fprintf(stderr,
                "ds4: invalid DS4_G133_ROTATOR_IO_TIMEOUT_S; using %.3f\n",
                timeout_seconds);
    }
    return timeout_seconds;
}

static double cuda_g133_transient_io_timeout_seconds(void) {
    static int initialized = 0;
    static double timeout_seconds = 30.0;
    if (initialized) return timeout_seconds;
    initialized = 1;
    const char *value = getenv("DS4_G133_TRANSIENT_IO_TIMEOUT_S");
    if (!value || !value[0]) return timeout_seconds;
    char *end = NULL;
    errno = 0;
    const double parsed = strtod(value, &end);
    if (errno == 0 && end && *end == '\0' && isfinite(parsed) &&
        parsed > 0.0 && parsed <= 3600.0) {
        timeout_seconds = parsed;
    } else {
        fprintf(stderr,
                "ds4: invalid DS4_G133_TRANSIENT_IO_TIMEOUT_S=%s; "
                "using default 30 seconds\n",
                value);
    }
    return timeout_seconds;
}

static int cuda_moe_route_read_whole_requested(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_ROUTE_READ_WHOLE");
        cached = env && strcmp(env, "1") == 0 ? 1 : 0;
    }
    return cached;
}

static int cuda_moe_route_prefetch_hint_requested(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_ROUTE_PREFETCH_HINT");
        cached = env && strcmp(env, "1") == 0 ? 1 : 0;
    }
    return cached;
}

#ifdef _WIN32
/* Keep this dynamically resolved so the optional hint does not raise the
 * process-wide minimum Windows API target. Its layout is the documented
 * WIN32_MEMORY_RANGE_ENTRY ABI. */
struct cuda_moe_win_memory_range_entry {
    PVOID virtual_address;
    SIZE_T number_of_bytes;
};

typedef BOOL (WINAPI *cuda_moe_prefetch_virtual_memory_fn)(
    HANDLE process,
    ULONG_PTR entry_count,
    cuda_moe_win_memory_range_entry *entries,
    ULONG flags);

static int cuda_moe_route_prefetch_add_range(
        cuda_moe_win_memory_range_entry *entries,
        uint32_t *entry_count,
        uint64_t offset,
        uint64_t bytes) {
    if (!entries || !entry_count || !g_model_host_base || bytes == 0u ||
        bytes > SIZE_MAX || offset > g_model_registered_size ||
        bytes > g_model_registered_size - offset) {
        return 0;
    }
    entries[*entry_count].virtual_address =
        (PVOID)((const char *)g_model_host_base + offset);
    entries[*entry_count].number_of_bytes = (SIZE_T)bytes;
    (*entry_count)++;
    return 1;
}

static void cuda_moe_route_prefetch_hint(
        const cuda_moe_route_request &request) {
    if (!cuda_moe_route_prefetch_hint_requested() ||
        !g_model_file_valid || !g_model_host_base ||
        request.route_count == 0u ||
        request.route_count > CUDA_MOE_ROUTE_COUNT ||
        request.miss_count > request.route_count ||
        request.gate_expert_bytes == 0u ||
        request.down_expert_bytes == 0u) {
        return;
    }

    cuda_moe_win_memory_range_entry
        entries[CUDA_MOE_ROUTE_COUNT * 3u] = {};
    uint32_t entry_count = 0u;
    for (uint32_t miss = 0; miss < request.miss_count; miss++) {
        const uint32_t route = request.miss_routes[miss];
        if (route >= request.route_count) return;
        const int32_t expert_i = request.selected[route];
        if (expert_i < 0 || expert_i >= 256) return;
        const uint64_t expert = (uint64_t)(uint32_t)expert_i;
        if (expert > UINT64_MAX / request.gate_expert_bytes ||
            expert > UINT64_MAX / request.down_expert_bytes) {
            return;
        }
        const uint64_t gate_delta = expert * request.gate_expert_bytes;
        const uint64_t down_delta = expert * request.down_expert_bytes;
        if (request.gate_offset > UINT64_MAX - gate_delta ||
            request.up_offset > UINT64_MAX - gate_delta ||
            request.down_offset > UINT64_MAX - down_delta ||
            !cuda_moe_route_prefetch_add_range(
                entries, &entry_count,
                request.gate_offset + gate_delta,
                request.gate_expert_bytes) ||
            !cuda_moe_route_prefetch_add_range(
                entries, &entry_count,
                request.up_offset + gate_delta,
                request.gate_expert_bytes) ||
            !cuda_moe_route_prefetch_add_range(
                entries, &entry_count,
                request.down_offset + down_delta,
                request.down_expert_bytes)) {
            return;
        }
    }
    if (entry_count == 0u) return;

    static int resolved = 0;
    static cuda_moe_prefetch_virtual_memory_fn prefetch_fn = NULL;
    static int unavailable_logged = 0;
    static int failure_logged = 0;
    if (!resolved) {
        HMODULE kernel32 = GetModuleHandleW(L"kernel32.dll");
        prefetch_fn = kernel32
            ? reinterpret_cast<cuda_moe_prefetch_virtual_memory_fn>(
                  GetProcAddress(kernel32, "PrefetchVirtualMemory"))
            : NULL;
        resolved = 1;
    }
    if (!prefetch_fn) {
        if (!unavailable_logged) {
            unavailable_logged = 1;
            fprintf(stderr,
                    "ds4: DS4_CUDA_ROUTE_PREFETCH_HINT unavailable; "
                    "continuing without the optional hint\n");
        }
        return;
    }
    if (!prefetch_fn(
            GetCurrentProcess(), (ULONG_PTR)entry_count, entries, 0u) &&
        !failure_logged) {
        failure_logged = 1;
        fprintf(stderr,
                "ds4: DS4_CUDA_ROUTE_PREFETCH_HINT failed error=%lu; "
                "continuing without the optional hint\n",
                (unsigned long)GetLastError());
    }
}
#else
static void cuda_moe_route_prefetch_hint(
        const cuda_moe_route_request &request) {
    (void)request;
}
#endif

static int cuda_moe_transient_pread_chunked(
        cuda_moe_expert_cache *cache, uint32_t sequence,
        uint64_t trace_sample_id, uint32_t trace_layer,
        int transport_repeat,
        const os_file_t *file, void *buf, uint64_t bytes, uint64_t offset,
        double absolute_deadline) {
    const uint64_t chunk_bytes = 1u << 20;
    const int read_whole = cuda_moe_route_read_whole_requested();
    const int staged_kv_io_tracking =
        ds4_gpu_staged_kv_gate_requested();
    /* WORKER-PROF: il flag e' issato fuori dal ciclo, cosi' a flag spento il
     * corpo del ciclo paga un solo ramo prevedibile per chunk. */
    const int wprof = cuda_worker_profile_enabled();
    uint8_t *destination = (uint8_t *)buf;
    uint64_t completed = 0u;
    while (completed < bytes) {
        if (cache->route_transient_cancel_sequence.load(
                std::memory_order_acquire) == sequence ||
            (absolute_deadline > 0.0 &&
             cuda_wall_sec() >= absolute_deadline)) {
            ds4_transport_mark_incomplete();
            return -1;
        }
        const uint64_t remaining = bytes - completed;
        const uint64_t request_bytes = read_whole
            ? remaining
            : (remaining < chunk_bytes ? remaining : chunk_bytes);
        if (staged_kv_io_tracking) {
            cache->route_transient_io_sequence.store(
                sequence, std::memory_order_release);
        }
        const uint64_t trace_started =
            cuda_decode_trace_request_layer(
                trace_sample_id, trace_layer)
            ? cuda_decode_trace_qpc_now_raw() : 0u;
        /* WORKER-PROF: questa e' l'UNICA richiesta di lettura che questo
         * percorso mette in volo per volta.  Contarla qui, non attorno al
         * tensore, e' cio' che rende inflight_max/inflight_avg una misura e
         * non una congettura: se la tesi della serializzazione e' vera qui
         * inflight resta 1 anche a pieno carico. */
        const uint64_t wprof_read = ds4_workerprof_read_begin(wprof);
        /* Conta il tentativo quando viene emesso: la whole-read puo' restare
         * in volo fino alla cancellazione, mentre il ramo da 1 MiB rientra a
         * ogni chunk. I byte restano contabilizzati solo dopo il completamento
         * e solo per il valore effettivamente restituito. */
        g_transient_pread_calls.fetch_add(1u, std::memory_order_relaxed);
        const int64_t got = read_whole
            ? os_pread_cancellable_max_chunk(
                  file, destination + completed, request_bytes,
                  offset + completed, &cache->route_transient_pread,
                  sequence, request_bytes)
            : os_pread_cancellable(
                  file, destination + completed, request_bytes,
                  offset + completed, &cache->route_transient_pread,
                  sequence);
        (void)wprof_read;
        ds4_workerprof_read_end(wprof, got);
        cuda_decode_trace_note_pread(
            trace_sample_id, trace_layer, trace_started, 1u,
            got > 0 ? (uint64_t)got : 0u);
        /* FIX-B intervento 2: contatori cumulativi di processo, letti in
         * differenziale dalla riga [slow-token]. Sempre aggiornati, cosi' la
         * riga e' confrontabile fra i due bracci di un A/B. */
        if (got > 0) {
            g_transient_pread_bytes.fetch_add(
                (uint64_t)got, std::memory_order_relaxed);
            ds4_transport_record_file_bytes(
                transport_repeat, (uint64_t)got);
        }
        if (staged_kv_io_tracking) {
            cache->route_transient_io_sequence.store(
                0u, std::memory_order_release);
        }
        if (cache->route_worker_safe_leaked.load(
                std::memory_order_acquire)) return -1;
        /* A low-level cancel normally remains a pread failure. Only the
         * cancellation explicitly marked by the absolute-deadline watchdog is
         * promoted to the recoverable -1 classification. */
        if (got < 0 &&
            cache->route_transient_timeout_cancel_sequence.load(
                std::memory_order_acquire) == sequence) {
            ds4_transport_mark_incomplete();
            return -1;
        }
        if (got < 0 || (uint64_t)got != request_bytes) {
            ds4_transport_mark_incomplete();
            return 0;
        }
        completed += request_bytes;
        cache->route_transient_read_bytes.fetch_add(
            request_bytes, std::memory_order_release);
        if (absolute_deadline > 0.0 &&
            cuda_wall_sec() >= absolute_deadline) {
            ds4_transport_mark_incomplete();
            return -1;
        }
    }
    return 1;
}

static const char *cuda_moe_route_mailbox_state_name(uint32_t state) {
    switch (state) {
    case CUDA_MOE_ROUTE_MAILBOX_FREE: return "free";
    case CUDA_MOE_ROUTE_MAILBOX_GPU_WRITING: return "gpu-writing";
    case CUDA_MOE_ROUTE_MAILBOX_WORKER_OWNS: return "worker-owns";
    case CUDA_MOE_ROUTE_MAILBOX_UPLOAD_ENQUEUED: return "upload-enqueued";
    case CUDA_MOE_ROUTE_MAILBOX_CONSUMER_DONE: return "consumer-done";
    case CUDA_MOE_ROUTE_MAILBOX_QUARANTINED: return "quarantined";
    default: return "invalid";
    }
}

/* The decode watchdog shares the worker's absolute I/O deadline.  With the
 * recoverable mode enabled it may win that race, but it must cancel only the
 * current pread: setting route_stop would turn the timeout into a real worker
 * shutdown before the worker can enter the fallback.  The dedicated sequence
 * marker is the proof that this cancellation came from that exact deadline. */
static int cuda_moe_transient_timeout_cancel_for_fallback(
        cuda_moe_expert_cache *cache, uint32_t sequence) {
    if (!cache || !cuda_transient_timeout_recoverable_requested() ||
        cache->route_worker_safe_leaked.load(std::memory_order_acquire) ||
        cache->route_stop.load(std::memory_order_acquire) ||
        cache->route_transient_dead_sequence.load(
            std::memory_order_acquire) == sequence) {
        return 0;
    }
    cache->route_transient_timeout_cancel_sequence.store(
        sequence, std::memory_order_release);
    cache->route_transient_cancel_sequence.store(
        sequence, std::memory_order_release);
    (void)os_pread_cancel(&cache->route_transient_pread, sequence);
    return 1;
}

/* FIX-B intervento 1 - ripiego recuperabile allo scadere del timeout
 * transiente (DS4_CUDA_TRANSIENT_TIMEOUT_RECOVERABLE=1).
 *
 * Non e' un percorso nuovo: e' la STESSA rilettura sincrona che il percorso
 * normale usa, cuda_moe_transient_pread_chunked, rieseguita con la deadline
 * disattivata (absolute_deadline = 0.0) sui soli tensori non ancora
 * completati.  I byte serviti sono percio' identici byte-per-byte a quelli
 * che la richiesta avrebbe ottenuto senza timeout: il token completa con lo
 * stesso risultato numerico.
 *
 * stage_done = quanti dei tre tensori (gate, up, down) erano gia' completi
 * quando il timeout e' scaduto: 0 nessuno, 1 gate, 2 gate+up.
 *
 * Ritorna 1 se l'expert e' stato servito, 0 se il ripiego non e' applicabile
 * (cancellazione vera, worker fermato, cache safe-leaked) o e' fallito; in
 * quel caso skipped_reason spiega precisamente perche' il chiamante aborta. */
static int cuda_moe_transient_timeout_fallback_serve(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request,
        int transport_repeat, uint32_t stage_done,
        char *host_gate, char *host_up, char *host_down,
        uint64_t gate_src, uint64_t up_src, uint64_t down_src,
        const char **skipped_reason) {
    if (skipped_reason) *skipped_reason = "unknown";
    if (!cache || !g_model_file_valid || !host_gate || !host_up || !host_down) {
        if (skipped_reason) *skipped_reason = "invalid-fallback-context";
        return 0;
    }
    if (cache->route_worker_safe_leaked.load(std::memory_order_acquire)) {
        if (skipped_reason) *skipped_reason = "safe-leaked";
        return 0;
    }
    if (cache->route_stop.load(std::memory_order_acquire)) {
        if (skipped_reason) *skipped_reason = "route-stop";
        return 0;
    }
    if (cache->route_transient_dead_sequence.load(
            std::memory_order_acquire) == request.sequence) {
        if (skipped_reason) *skipped_reason = "dead-sequence";
        return 0;
    }
    const int cancelled =
        cache->route_transient_cancel_sequence.load(
            std::memory_order_acquire) == request.sequence;
    const int deadline_cancelled =
        cache->route_transient_timeout_cancel_sequence.load(
            std::memory_order_acquire) == request.sequence;
    if (cancelled && !deadline_cancelled) {
        if (skipped_reason) *skipped_reason = "cancel-sequence";
        return 0;
    }
    if (deadline_cancelled) {
        /* The cancellable call has returned before control reaches here, so its
         * persistent slot can be reset and reused.  Clear only the cancellation
         * carrying the dedicated deadline marker; a generic cancellation never
         * reaches this block. */
        os_pread_cancellable_reset(&cache->route_transient_pread);
        cache->route_transient_cancel_sequence.store(
            0u, std::memory_order_release);
        cache->route_transient_timeout_cancel_sequence.store(
            0u, std::memory_order_release);
    }
    /* Il watchdog del thread di decode (in cuda_moe_gpu_resident_routes_submit)
     * uccide la richiesta alla STESSA deadline che il worker ha pubblicato in
     * route_transient_read_deadline.  Va disarmata prima di rileggere, altrimenti
     * il ripiego non serve a nulla.  Resta attivo il watchdog di stallo (5 s
     * senza byte nuovi), che la rilettura tiene alimentato a ogni chunk da 1 MiB.
     * La ripubblicazione della sequence e' una release: il prossimo giro di
     * poll del thread di decode fa acquire e vede la deadline azzerata. */
    cache->route_transient_read_deadline = 0.0;
    cache->route_transient_read_sequence.store(
        request.sequence, std::memory_order_release);
    /* WORKER-PROF: il ripiego rilegge gli STESSI tensori del percorso normale,
     * quindi confluisce nelle stesse tre voci: il bilancio della lettura resta
     * uno solo anche quando un timeout ha spezzato la richiesta in due. */
    const int wprof = cuda_worker_profile_enabled();
    int result = 1;
    if (stage_done < 1u) {
        const uint64_t wprof_gate = ds4_workerprof_start(wprof);
        result = cuda_moe_transient_pread_chunked(
            cache, request.sequence, request.trace_sample_id,
            request.layer_index, transport_repeat, &g_model_file, host_gate,
            cache->gate_expert_bytes, gate_src, 0.0);
        ds4_workerprof_stop(wprof, WP_READ_GATE_NS, wprof_gate);
    }
    if (result == 1 && stage_done < 2u) {
        const uint64_t wprof_up = ds4_workerprof_start(wprof);
        result = cuda_moe_transient_pread_chunked(
            cache, request.sequence, request.trace_sample_id,
            request.layer_index, transport_repeat, &g_model_file, host_up,
            cache->gate_expert_bytes, up_src, 0.0);
        ds4_workerprof_stop(wprof, WP_READ_UP_NS, wprof_up);
    }
    if (result == 1) {
        const uint64_t wprof_down = ds4_workerprof_start(wprof);
        result = cuda_moe_transient_pread_chunked(
            cache, request.sequence, request.trace_sample_id,
            request.layer_index, transport_repeat, &g_model_file, host_down,
            cache->down_expert_bytes, down_src, 0.0);
        ds4_workerprof_stop(wprof, WP_READ_DOWN_NS, wprof_down);
    }
    if (result == 1) return 1;
    if (cache->route_worker_safe_leaked.load(std::memory_order_acquire)) {
        if (skipped_reason) *skipped_reason = "safe-leaked-during-fallback";
    } else if (cache->route_stop.load(std::memory_order_acquire)) {
        if (skipped_reason) *skipped_reason = "route-stop-during-fallback";
    } else if (cache->route_transient_dead_sequence.load(
                   std::memory_order_acquire) == request.sequence) {
        if (skipped_reason) *skipped_reason = "dead-sequence-during-fallback";
    } else if (cache->route_transient_cancel_sequence.load(
                   std::memory_order_acquire) == request.sequence) {
        if (skipped_reason) *skipped_reason = "cancel-sequence-during-fallback";
    } else {
        if (skipped_reason) *skipped_reason = "fallback-pread-failed";
    }
    return 0;
}

static int cuda_moe_route_mailbox_fail_closed(
        cuda_moe_expert_cache *cache,
        uint32_t sequence,
        uint64_t generation,
        const char *reason) {
    if (!cache) return 0;
    cuda_moe_route_mailbox_slot &slot =
        cache->route_mailbox[generation & 1u];
    const uint64_t observed_generation =
        slot.generation.load(std::memory_order_acquire);
    const uint32_t observed_state =
        slot.state.exchange(CUDA_MOE_ROUTE_MAILBOX_QUARANTINED,
                            std::memory_order_acq_rel);
    cache->route_worker_failed.store(1, std::memory_order_release);
    if (cuda_moe_prefill_tier_compose_requested() > 0) {
        g_dynamic_arena.hits_disabled = 1;
        g_dynamic_arena.submissions_blocked = 1;
        g_dynamic_arena.fatal_errors++;
    }
    cuda_moe_route_memory_barrier();
    fprintf(stderr,
            "ds4: [gpu-route-mailbox] result=failed-closed reason=%s "
            "sequence=%u generation=%llu observed_generation=%llu "
            "state=%s\n",
            reason ? reason : "unknown", sequence,
            (unsigned long long)generation,
            (unsigned long long)observed_generation,
            cuda_moe_route_mailbox_state_name(observed_state));
    return 0;
}

static int cuda_moe_route_mailbox_worker_claim(
        cuda_moe_expert_cache *cache,
        uint32_t sequence,
        uint64_t generation) {
    if (!cache || generation == 0u) return 0;

    if (generation > 1u) {
        const uint64_t prior_generation = generation - 1u;
        if (cache->route_cpu_staging_generation.load(
                std::memory_order_acquire) == prior_generation) {
            return cuda_moe_route_mailbox_fail_closed(
                cache, sequence, generation, "cpu-staging-reader-active");
        }
        cuda_moe_route_mailbox_slot &prior =
            cache->route_mailbox[prior_generation & 1u];
        const uint64_t recorded_generation =
            cache->route_consumer_event_generation.load(
                std::memory_order_acquire);
        const uint64_t prior_slot_generation =
            prior.generation.load(std::memory_order_acquire);
        const cudaError_t event_status =
            cache->route_consumer_done_event
                ? cudaEventQuery(cache->route_consumer_done_event)
                : cudaErrorInvalidResourceHandle;
        if (recorded_generation != prior_generation ||
            prior_slot_generation != prior_generation ||
            event_status != cudaSuccess) {
            if (event_status != cudaSuccess &&
                event_status != cudaErrorNotReady) {
                (void)cudaGetLastError();
            }
            return cuda_moe_route_mailbox_fail_closed(
                cache, sequence, generation,
                recorded_generation != prior_generation
                    ? "consumer-event-generation"
                    : (prior_slot_generation != prior_generation
                        ? "prior-slot-generation"
                        : "consumer-event-incomplete"));
        }
        uint32_t prior_state = CUDA_MOE_ROUTE_MAILBOX_UPLOAD_ENQUEUED;
        if (!prior.state.compare_exchange_strong(
                prior_state, CUDA_MOE_ROUTE_MAILBOX_CONSUMER_DONE,
                std::memory_order_acq_rel, std::memory_order_acquire)) {
            return cuda_moe_route_mailbox_fail_closed(
                cache, sequence, generation, "prior-slot-state");
        }
        cache->route_consumer_done_generation.store(
            prior_generation, std::memory_order_release);
    }

    cuda_moe_route_mailbox_slot &current =
        cache->route_mailbox[generation & 1u];
    if (current.generation.load(std::memory_order_acquire) != generation) {
        return cuda_moe_route_mailbox_fail_closed(
            cache, sequence, generation, "current-slot-generation");
    }
    uint32_t state = CUDA_MOE_ROUTE_MAILBOX_GPU_WRITING;
    if (!current.state.compare_exchange_strong(
            state, CUDA_MOE_ROUTE_MAILBOX_WORKER_OWNS,
            std::memory_order_acq_rel, std::memory_order_acquire)) {
        return cuda_moe_route_mailbox_fail_closed(
            cache, sequence, generation, "current-slot-state");
    }
    cache->route_consumed_sequence.store(
        sequence, std::memory_order_release);
    cache->route_consumed_generation.store(
        generation, std::memory_order_release);
    return 1;
}

static int cuda_moe_route_mailbox_publish_upload(
        cuda_moe_expert_cache *cache,
        uint32_t sequence,
        uint64_t generation) {
    if (!cache || generation == 0u) return 0;
    cuda_moe_route_mailbox_slot &slot =
        cache->route_mailbox[generation & 1u];
    if (slot.generation.load(std::memory_order_acquire) != generation) {
        return cuda_moe_route_mailbox_fail_closed(
            cache, sequence, generation, "upload-slot-generation");
    }
    uint32_t state = CUDA_MOE_ROUTE_MAILBOX_WORKER_OWNS;
    if (!slot.state.compare_exchange_strong(
            state, CUDA_MOE_ROUTE_MAILBOX_UPLOAD_ENQUEUED,
            std::memory_order_acq_rel, std::memory_order_acquire)) {
        return cuda_moe_route_mailbox_fail_closed(
            cache, sequence, generation, "upload-slot-state");
    }
    return 1;
}

static void cuda_moe_route_worker_publish_completed(
        cuda_moe_expert_cache *cache,
        uint32_t sequence,
        uint64_t generation) {
    cache->route_completed_sequence.store(
        sequence, std::memory_order_release);
    cache->route_completed_generation.store(
        generation, std::memory_order_release);
}

/* A joined host worker is not a drained CUDA producer: route_upload_stream is
 * non-blocking, so neither the default stream nor thread join orders its old
 * H2D copies/publication kernels. Under staged KV, refuse both invalidation and
 * respawn until that stream is quiescent; quarantine instead of touching global
 * CUDA state when the stream cannot be proven clean. */
static int cuda_moe_route_upload_stream_quiesce(
        cuda_moe_expert_cache *cache, uint32_t sequence,
        const char *site) {
    if (!cache || !cache->route_upload_stream ||
        !ds4_gpu_staged_kv_gate_requested()) {
        return 1;
    }
    const double drain_deadline = cuda_wall_sec() + 5.0;
    cudaError_t status = cudaStreamQuery(cache->route_upload_stream);
    while (status == cudaErrorNotReady && cuda_wall_sec() < drain_deadline) {
#ifdef _WIN32
        (void)SwitchToThread();
#else
        usleep(0);
#endif
        status = cudaStreamQuery(cache->route_upload_stream);
    }
    if (status == cudaSuccess) return 1;
    cache->route_worker_safe_leaked.store(1, std::memory_order_release);
    cache->route_worker_ready.store(0, std::memory_order_release);
    cache->route_worker_failed.store(1, std::memory_order_release);
    cuda_moe_route_memory_barrier();
    fprintf(stderr,
            "ds4: [g73-open] route upload stream quarantine seq=%u "
            "site=%s cuda=%s cache=safe-leaked\n",
            sequence, site ? site : "unknown",
            status == cudaErrorNotReady ? "not-ready" :
                cudaGetErrorString(status));
    return 0;
}

static int cuda_moe_route_worker_cancel_and_join(
        cuda_moe_expert_cache *cache, uint32_t sequence,
        double request_deadline) {
    if (!cache) return 0;
    cache->route_transient_cancel_sequence.store(
        sequence, std::memory_order_release);
    (void)os_pread_cancel(&cache->route_transient_pread, sequence);
    cache->route_stop.store(1, std::memory_order_release);
    if (cache->route_thread_started) {
        const double join_deadline =
            (request_deadline > 0.0 ? request_deadline : cuda_wall_sec()) + 5.0;
        const double remaining = join_deadline - cuda_wall_sec();
        const uint32_t timeout_ms = remaining <= 0.0 ? 0u :
            (uint32_t)std::min(ceil(remaining * 1000.0),
                               (double)UINT32_MAX);
        if (!os_thread_join_timeout(cache->route_thread, timeout_ms)) {
            /* Last resort: the route request/staging slot remains writer-owned
             * and the whole cache is permanently dead. Detach and leak it;
             * freeing or reusing a buffer that the OS may still write is not
             * safe on either Windows or best-effort-cancel POSIX. */
            cache->route_transient_dead_sequence.store(
                sequence, std::memory_order_release);
            cache->route_worker_safe_leaked.store(
                1, std::memory_order_release);
            os_thread_detach(cache->route_thread);
            cache->route_thread_started = 0;
            cache->route_worker_ready.store(0, std::memory_order_release);
            cache->route_worker_failed.store(1, std::memory_order_release);
            fprintf(stderr,
                    "ds4: CUDA route worker join deadline expired seq=%u; "
                    "writer slot/cache safe-leaked permanently\n",
                    sequence);
            return 0;
        }
        cache->route_thread_started = 0;
    }
    if (os_pread_cancellable_pending(&cache->route_transient_pread)) {
        /* The worker returned after a bounded cancel, but the kernel still owns
         * its persistent OVERLAPPED/AIO slot and host staging. Quarantine the
         * whole cache exactly as for a join timeout; no buffer may be reused. */
        cache->route_transient_dead_sequence.store(
            sequence, std::memory_order_release);
        cache->route_worker_safe_leaked.store(1, std::memory_order_release);
        cache->route_worker_ready.store(0, std::memory_order_release);
        cache->route_worker_failed.store(1, std::memory_order_release);
        fprintf(stderr,
                "ds4: CUDA route I/O cancellation still pending seq=%u; "
                "persistent I/O slot/cache safe-leaked permanently\n",
                sequence);
        return 0;
    }
    if (!cuda_moe_route_upload_stream_quiesce(
            cache, sequence, "cancel-and-join")) {
        return 0;
    }
    cache->route_worker_ready.store(0, std::memory_order_release);
    cache->route_worker_failed.store(1, std::memory_order_release);
    return 1;
}

static int cuda_moe_route_worker_drain_completed(const char *site) {
    cuda_moe_expert_cache *cache = &g_moe_expert_cache;
    const uint32_t target = cache->route_submitted_sequence.load(
        std::memory_order_acquire);
    const uint64_t target_generation =
        cache->route_submitted_generation.load(std::memory_order_acquire);
    if (target == 0u || target_generation == 0u ||
        (cache->route_completed_sequence.load(std::memory_order_acquire) ==
             target &&
         cache->route_completed_generation.load(std::memory_order_acquire) ==
             target_generation)) {
        return 1;
    }
    if (!cache->route_thread_started) return 0;
    double deadline = cuda_wall_sec() + 5.0;
    if (cache->route_transient_read_sequence.load(
            std::memory_order_acquire) == target &&
        cache->route_transient_read_deadline > deadline) {
        deadline = cache->route_transient_read_deadline + 5.0;
    }
    while (cache->route_completed_sequence.load(std::memory_order_acquire) !=
               target ||
           cache->route_completed_generation.load(
               std::memory_order_acquire) != target_generation) {
        if (cache->route_worker_failed.load(std::memory_order_acquire) ||
            cache->route_stop.load(std::memory_order_acquire) ||
            cuda_wall_sec() >= deadline) {
            fprintf(stderr,
                    "ds4: CUDA route worker completion drain failed "
                    "site=%s target=%u generation=%llu completed=%u "
                    "completed_generation=%llu\n",
                    site ? site : "unknown", target,
                    (unsigned long long)target_generation,
                    cache->route_completed_sequence.load(
                        std::memory_order_acquire),
                    (unsigned long long)
                        cache->route_completed_generation.load(
                            std::memory_order_acquire));
            (void)cuda_moe_route_mailbox_fail_closed(
                cache, target, target_generation, "completion-timeout");
            (void)cuda_moe_route_worker_cancel_and_join(
                cache, target, deadline - 5.0);
            return 0;
        }
#ifdef _WIN32
        (void)SwitchToThread();
#else
        usleep(0);
#endif
    }
    return 1;
}

extern "C" int ds4_gpu_moe_route_consumer_done(void) {
    cuda_moe_expert_cache *cache = &g_moe_expert_cache;
    if (!cache->route_consumer_done_event ||
        !cache->route_thread_started ||
        cache->route_worker_safe_leaked.load(std::memory_order_acquire)) {
        return 1;
    }
    const uint64_t generation =
        cache->route_submitted_generation.load(std::memory_order_acquire);
    if (generation == 0u ||
        cache->route_consumer_event_generation.load(
            std::memory_order_acquire) == generation) {
        return 1;
    }
    cuda_moe_route_mailbox_slot &slot =
        cache->route_mailbox[generation & 1u];
    const uint64_t slot_generation =
        slot.generation.load(std::memory_order_acquire);
    const uint32_t state = slot.state.load(std::memory_order_acquire);
    if (slot_generation != generation ||
        state == CUDA_MOE_ROUTE_MAILBOX_FREE ||
        state == CUDA_MOE_ROUTE_MAILBOX_CONSUMER_DONE ||
        state == CUDA_MOE_ROUTE_MAILBOX_QUARANTINED) {
        return cuda_moe_route_mailbox_fail_closed(
            cache,
            cache->route_submitted_sequence.load(std::memory_order_acquire),
            generation, "consumer-record-state");
    }
    const cudaError_t err =
        cudaEventRecord(cache->route_consumer_done_event, 0);
    if (err != cudaSuccess) {
        (void)cudaGetLastError();
        return cuda_moe_route_mailbox_fail_closed(
            cache,
            cache->route_submitted_sequence.load(std::memory_order_acquire),
            generation, "consumer-event-record");
    }
    cache->route_consumer_event_generation.store(
        generation, std::memory_order_release);
    return 1;
}

