extern "C" ds4_gpu_g133_epoch ds4_gpu_g133_decode_position_begin(void) {
    if (g_cuda_request_epoch == 0u) {
        /* Standalone layer benchmarks do not cross the session request hook. */
        g_cuda_request_epoch = 1u;
    }
    g_cuda_g133_decode_position_epoch++;
    if (g_cuda_g133_decode_position_epoch == 0u) {
        g_cuda_g133_decode_position_epoch++;
    }
    return ds4_gpu_g133_epoch{
        g_cuda_request_epoch, g_cuda_g133_decode_position_epoch};
}

static int cuda_g133_epoch_valid(const ds4_gpu_g133_epoch &epoch) {
    return epoch.request_epoch != 0u && epoch.position_epoch != 0u;
}

extern "C" int ds4_gpu_g133_validate_context(uint32_t ctx_size) {
    if (!ds4_gpu_g133_enabled) return 1;
    if (ctx_size == 0u || ctx_size > CUDA_G133_EPOCH_POSITION_MASK) {
        fprintf(stderr,
                "ds4: DS4_G133_TIER=1 requires context <= %llu tokens; "
                "G133 advisory position epoch is %u bits\n",
                (unsigned long long)CUDA_G133_EPOCH_POSITION_MASK,
                (unsigned)CUDA_G133_EPOCH_POSITION_BITS);
        return 0;
    }
    return 1;
}

static cuda_g133_advisory_fields cuda_g133_advisory_fields_from_epoch(
        const ds4_gpu_g133_epoch &epoch) {
    cuda_g133_advisory_fields fields = {};
    fields.promotion_age = (uint32_t)CUDA_G133_PROMOTION_AGE_MAX;
    fields.position_epoch =
        (uint32_t)(epoch.position_epoch & CUDA_G133_EPOCH_POSITION_MASK);
    fields.request_epoch =
        (uint32_t)(epoch.request_epoch & CUDA_G133_EPOCH_REQUEST_MASK);
    return fields;
}

static int cuda_g133_advisory_same_epoch(
        const cuda_g133_advisory_fields &a,
        const cuda_g133_advisory_fields &b) {
    return a.request_epoch == b.request_epoch &&
        a.position_epoch == b.position_epoch;
}

static int cuda_g133_advisory_epoch_after(
        const cuda_g133_advisory_fields &current,
        const cuda_g133_advisory_fields &prior) {
    if (current.request_epoch == prior.request_epoch) {
        return (int32_t)(current.position_epoch - prior.position_epoch) > 0;
    }
    const uint64_t request_delta =
        ((uint64_t)current.request_epoch - (uint64_t)prior.request_epoch) &
        CUDA_G133_EPOCH_REQUEST_MASK;
    return request_delta != 0u && request_delta < CUDA_G133_EPOCH_REQUEST_HALF;
}

static uint32_t cuda_g133_advisory_elapsed(
        const cuda_g133_advisory_fields &prior,
        const cuda_g133_advisory_fields &current) {
    if (!cuda_g133_advisory_epoch_after(current, prior)) return 0u;
    if (current.request_epoch != prior.request_epoch) {
        return current.position_epoch == 0u ? 1u : current.position_epoch;
    }
    if (current.position_epoch >= prior.position_epoch) {
        return current.position_epoch - prior.position_epoch;
    }
    return (uint32_t)CUDA_G133_PROMOTION_AGE_MAX;
}

static int cuda_g133_advisory_epoch_consecutive(
        const cuda_g133_advisory_fields &prior,
        const cuda_g133_advisory_fields &current) {
    return current.request_epoch == prior.request_epoch &&
        (uint32_t)(current.position_epoch - prior.position_epoch) == 1u;
}

static uint32_t cuda_g133_advisory_age_add(
        uint32_t age, uint32_t elapsed) {
    return elapsed >= CUDA_G133_PROMOTION_AGE_MAX ||
            age >= CUDA_G133_PROMOTION_AGE_MAX - elapsed
        ? (uint32_t)CUDA_G133_PROMOTION_AGE_MAX : age + elapsed;
}

static cuda_g133_advisory_fields cuda_g133_advisory_current_snapshot(
        uint64_t packed, const ds4_gpu_g133_epoch &epoch) {
    cuda_g133_advisory_fields current =
        cuda_g133_advisory_fields_from_epoch(epoch);
    if (packed == 0u) return current;
    cuda_g133_advisory_fields prior = cuda_g133_advisory_unpack(packed);
    if (cuda_g133_advisory_same_epoch(prior, current)) {
        return prior;
    }
    const uint32_t elapsed =
        cuda_g133_advisory_elapsed(prior, current);
    current.promotion_age =
        cuda_g133_advisory_age_add(prior.promotion_age, elapsed);
    current.streak = 0u;
    return current;
}

static uint32_t cuda_g133_consecutive_streak(
        const cuda_moe_tier_entry &entry) {
    return cuda_g133_advisory_unpack(
        entry.g133_advisory.streak_epoch.load(
            std::memory_order_relaxed)).streak;
}

static uint32_t cuda_g133_consecutive_streak_at(
        const cuda_moe_tier_entry &entry,
        const ds4_gpu_g133_epoch &epoch) {
    if (!cuda_g133_epoch_valid(epoch)) return cuda_g133_consecutive_streak(entry);
    const uint64_t packed = entry.g133_advisory.streak_epoch.load(
        std::memory_order_relaxed);
    const cuda_g133_advisory_fields fields =
        cuda_g133_advisory_current_snapshot(packed, epoch);
    return fields.streak;
}

static double cuda_g133_advisory_heat(
        const cuda_moe_tier_entry &entry,
        const ds4_gpu_g133_epoch &epoch) {
    const uint64_t packed = entry.g133_advisory.streak_epoch.load(
        std::memory_order_relaxed);
    const uint32_t elapsed = packed == 0u ? 0u :
        cuda_g133_advisory_elapsed(
            cuda_g133_advisory_unpack(packed),
            cuda_g133_advisory_fields_from_epoch(epoch));
    const double raw = (double)entry.g133_advisory.decayed_heat.load(
        std::memory_order_relaxed) / (double)CUDA_G133_TOUCH_SCALE;
    return elapsed == 0u ? raw : raw * pow(
        g_moe_tiering.g133_decay, (double)elapsed);
}

static void cuda_g133_mark_promotion(
        cuda_moe_tier_entry &entry, const ds4_gpu_g133_epoch &epoch) {
    if (!cuda_g133_epoch_valid(epoch)) return;
    const cuda_g133_advisory_fields current =
        cuda_g133_advisory_fields_from_epoch(epoch);
    uint64_t prior = entry.g133_advisory.streak_epoch.load(
        std::memory_order_relaxed);
    for (;;) {
        cuda_g133_advisory_fields next =
            cuda_g133_advisory_current_snapshot(prior, epoch);
        if (!cuda_g133_advisory_same_epoch(next, current)) {
            next = current;
        }
        next.promotion_age = 0u;
        const uint64_t packed = cuda_g133_advisory_pack(next);
        if (entry.g133_advisory.streak_epoch.compare_exchange_weak(
                prior, packed, std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            break;
        }
    }
}

static int cuda_g133_ram_candidate(
        const cuda_moe_tier_entry &entry,
        const ds4_gpu_g133_epoch &epoch) {
    return cuda_g133_consecutive_streak_at(entry, epoch) >=
        g_moe_tiering.g133_knock_x;
}

static int cuda_g133_ram_candidate_relaxed(
        const cuda_moe_tier_entry &entry) {
    return cuda_g133_consecutive_streak(entry) >=
        g_moe_tiering.g133_knock_x;
}

static int cuda_g133_vram_candidate(
        const cuda_moe_tier_entry &entry,
        const ds4_gpu_g133_epoch &epoch) {
    return (uint64_t)cuda_g133_consecutive_streak_at(entry, epoch) >=
        (uint64_t)g_moe_tiering.g133_knock_x +
            g_moe_tiering.g133_knock_y;
}

static int cuda_g133_demotion_eligible_at(
        const cuda_moe_tier_entry &entry,
        const ds4_gpu_g133_epoch &epoch) {
    if (!cuda_g133_epoch_valid(epoch)) return 0;
    const uint64_t packed = entry.g133_advisory.streak_epoch.load(
        std::memory_order_relaxed);
    if (packed == 0u) return 1;
    const cuda_g133_advisory_fields prior =
        cuda_g133_advisory_unpack(packed);
    const cuda_g133_advisory_fields current =
        cuda_g133_advisory_fields_from_epoch(epoch);
    const cuda_g133_advisory_fields snapshot =
        cuda_g133_advisory_current_snapshot(packed, epoch);
    const int streak_broken =
        !cuda_g133_advisory_same_epoch(prior, current) &&
        cuda_g133_advisory_epoch_after(current, prior);
    const int promotion_age_ready =
        snapshot.promotion_age >= g_moe_tiering.g133_knock_y;
    return streak_broken && promotion_age_ready;
}

static void cuda_g133_update_entry_candidate_state(
        cuda_moe_tier_entry &entry,
        const ds4_gpu_g133_epoch &epoch) {
    if (entry.state == CUDA_MOE_TIER_RAM_WARM &&
        cuda_g133_demotion_eligible_at(entry, epoch)) {
        entry.state = CUDA_MOE_TIER_RAM_PROBATION;
        cuda_g133_telemetry_increment(g_cuda_g133_telemetry.reaps);
    }
}

static void cuda_g133_refresh_entry(
        cuda_moe_tier_entry &entry,
        const ds4_gpu_g133_epoch &epoch) {
    if (!g_moe_tiering.g133_enabled || !cuda_g133_epoch_valid(epoch)) return;
    cuda_g133_update_entry_candidate_state(entry, epoch);
}

static void cuda_g133_record_observation(
        cuda_moe_tier_entry &entry,
        const ds4_gpu_g133_epoch &epoch, double weight) {
    (void)weight;
    const cuda_g133_advisory_fields current =
        cuda_g133_advisory_fields_from_epoch(epoch);
    uint64_t prior = entry.g133_advisory.streak_epoch.load(
        std::memory_order_relaxed);
    uint32_t elapsed = 0u;
    for (;;) {
        cuda_g133_advisory_fields prior_fields =
            cuda_g133_advisory_unpack(prior);
        cuda_g133_advisory_fields next = current;
        if (prior != 0u) {
            if (cuda_g133_advisory_same_epoch(prior_fields, current)) {
                if (prior_fields.streak != 0u) return;
                elapsed = 0u;
                next.promotion_age = prior_fields.promotion_age;
                next.streak = 1u;
            } else {
                if (!cuda_g133_advisory_epoch_after(current, prior_fields)) {
                    return;
                }
                elapsed = cuda_g133_advisory_elapsed(
                    prior_fields, current);
                next.promotion_age = cuda_g133_advisory_age_add(
                    prior_fields.promotion_age, elapsed);
                if (cuda_g133_advisory_epoch_consecutive(
                        prior_fields, current)) {
                    next.streak =
                        prior_fields.streak < CUDA_G133_STREAK_MAX
                            ? prior_fields.streak + 1u :
                        (uint32_t)CUDA_G133_STREAK_MAX;
                } else {
                    next.streak = 1u;
                }
            }
        } else {
            next.promotion_age =
                (uint32_t)CUDA_G133_PROMOTION_AGE_MAX;
            next.streak = 1u;
        }
        if (entry.g133_advisory.streak_epoch.compare_exchange_weak(
                prior, cuda_g133_advisory_pack(next), std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            break;
        }
    }
    const uint64_t raw = entry.g133_advisory.decayed_heat.load(
        std::memory_order_relaxed);
    const double retained = prior == 0u ? (double)raw :
        (double)raw * pow(g_moe_tiering.g133_decay, (double)elapsed);
    const uint64_t decayed = retained >=
            (double)(UINT64_MAX - CUDA_G133_TOUCH_SCALE)
        ? UINT64_MAX - CUDA_G133_TOUCH_SCALE : (uint64_t)retained;
    entry.g133_advisory.decayed_heat.store(
        decayed + CUDA_G133_TOUCH_SCALE, std::memory_order_relaxed);
    cuda_g133_update_entry_candidate_state(entry, epoch);
}

static double cuda_g133_decayed_heat(
        cuda_moe_tier_entry &entry,
        const ds4_gpu_g133_epoch &epoch) {
    cuda_g133_refresh_entry(entry, epoch);
    return cuda_g133_advisory_heat(entry, epoch);
}

static int cuda_g133_ram_demotion_eligible(
        cuda_moe_tier_entry &entry,
        const ds4_gpu_g133_epoch &epoch) {
    cuda_g133_refresh_entry(entry, epoch);
    return cuda_g133_demotion_eligible_at(entry, epoch);
}

static void cuda_g133_advisory_budget_refresh(
        const ds4_gpu_g133_epoch &epoch) {
    const uint64_t current = cuda_g133_advisory_pack(
        cuda_g133_advisory_fields_from_epoch(epoch));
    uint64_t maximum = g_cuda_g133_advisory_budget.max_epoch.load(
        std::memory_order_relaxed);
    while (cuda_g133_advisory_epoch_after(
            cuda_g133_advisory_unpack(current),
            cuda_g133_advisory_unpack(maximum))) {
        if (g_cuda_g133_advisory_budget.max_epoch.compare_exchange_weak(
                maximum, current, std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            g_cuda_g133_advisory_budget.remaining.store(
                g_moe_tiering.g133_promote_budget,
                std::memory_order_relaxed);
            break;
        }
    }
}

static int cuda_g133_advisory_budget_reserve(
        const ds4_gpu_g133_epoch &epoch) {
    cuda_g133_advisory_budget_refresh(epoch);
    uint32_t remaining = g_cuda_g133_advisory_budget.remaining.load(
        std::memory_order_relaxed);
    while (remaining != 0u) {
        if (g_cuda_g133_advisory_budget.remaining.compare_exchange_weak(
                remaining, remaining - 1u, std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return 1;
        }
    }
    return 0;
}

static void cuda_g133_advisory_budget_refund(void) {
    uint32_t remaining = g_cuda_g133_advisory_budget.remaining.load(
        std::memory_order_relaxed);
    while (remaining < g_moe_tiering.g133_promote_budget &&
           !g_cuda_g133_advisory_budget.remaining.compare_exchange_weak(
               remaining, remaining + 1u, std::memory_order_relaxed,
               std::memory_order_relaxed)) {}
}

static double cuda_moe_tiering_lfru(
        const cuda_moe_tier_entry &entry, uint64_t now) {
    const uint64_t age = now > entry.last_call ? now - entry.last_call : 0;
    return entry.mass + (double)entry.frequency / (double)(age + 1u);
}

static void cuda_moe_tiering_admit_adjust_threshold(
        uint32_t base, uint32_t *current,
        uint64_t free_promotions, uint64_t replacements) {
    if (!current) return;
    const uint64_t total = free_promotions + replacements;
    if (total == 0u) return;
    /* Per-boundary analogue of
     * policy_replacements/(policy_free_promotions+policy_replacements). */
    const double pressure = (double)replacements / (double)total;
    const uint32_t floor = std::max(1u, base);
    if (pressure >= 0.5) {
        if (*current < UINT16_MAX) (*current)++;
    } else if (pressure <= 0.25 && *current > floor) {
        (*current)--;
    }
}

static void cuda_moe_tiering_admit_refresh_window(void) {
    if (!g_moe_tiering.policy_admit_enabled ||
        g_moe_tiering.policy_clock_calls == 0u) {
        return;
    }
    const uint64_t epoch = g_moe_tiering.call_tick /
        (uint64_t)g_moe_tiering.policy_clock_calls;
    if (epoch == g_moe_tiering.policy_admit_epoch) return;
    if (g_moe_tiering.policy_admit_epoch != UINT64_MAX) {
        uint64_t elapsed = epoch > g_moe_tiering.policy_admit_epoch ?
            epoch - g_moe_tiering.policy_admit_epoch : 1u;
        if (elapsed > 16u) elapsed = 16u;
        for (uint32_t i = 0;
             i < CUDA_MOE_LAYER_COUNT * 256u; i++) {
            g_moe_tiering.admit_knocks[i] =
                (uint16_t)(g_moe_tiering.admit_knocks[i] >> elapsed);
        }
        if (g_moe_tiering.policy_admit_adaptive) {
            cuda_moe_tiering_admit_adjust_threshold(
                g_moe_tiering.policy_admit_knocks_ssd,
                &g_moe_tiering.policy_admit_current_ssd,
                g_moe_tiering.policy_admit_window_free_ssd,
                g_moe_tiering.policy_admit_window_replacements_ssd);
            cuda_moe_tiering_admit_adjust_threshold(
                g_moe_tiering.policy_admit_knocks_warm,
                &g_moe_tiering.policy_admit_current_warm,
                g_moe_tiering.policy_admit_window_free_warm,
                g_moe_tiering.policy_admit_window_replacements_warm);
            cuda_moe_tiering_admit_adjust_threshold(
                g_moe_tiering.policy_admit_knocks_vram,
                &g_moe_tiering.policy_admit_current_vram,
                g_moe_tiering.policy_admit_window_free_vram,
                g_moe_tiering.policy_admit_window_replacements_vram);
        }
        g_moe_tiering.policy_admit_window_free_ssd = 0u;
        g_moe_tiering.policy_admit_window_replacements_ssd = 0u;
        g_moe_tiering.policy_admit_window_free_warm = 0u;
        g_moe_tiering.policy_admit_window_replacements_warm = 0u;
        g_moe_tiering.policy_admit_window_free_vram = 0u;
        g_moe_tiering.policy_admit_window_replacements_vram = 0u;
    }
    g_moe_tiering.policy_admit_epoch = epoch;
}

static uint16_t cuda_moe_tiering_admit_note(
        uint32_t layer, uint32_t expert) {
    cuda_moe_tiering_admit_refresh_window();
    const size_t index = cuda_moe_tiering_entry_index(layer, expert);
    uint16_t &knocks = g_moe_tiering.admit_knocks[index];
    if (knocks != UINT16_MAX) knocks++;
    return knocks;
}

static int cuda_moe_tiering_admit_gate(
        const cuda_moe_tier_entry &entry, uint32_t layer, uint32_t expert,
        uint32_t threshold, double mass_bypass,
        uint64_t *knock_skips, uint64_t *mass_bypasses) {
    if (threshold == 0u) return 1;
    const uint16_t knocks = g_moe_tiering.admit_knocks[
        cuda_moe_tiering_entry_index(layer, expert)];
    if ((uint32_t)knocks >= threshold) return 1;
    if (mass_bypass > 0.0 && entry.mass >= mass_bypass) {
        if (mass_bypasses) (*mass_bypasses)++;
        return 1;
    }
    if (knock_skips) (*knock_skips)++;
    return 0;
}

static void cuda_moe_tiering_clear_owned_slots(void) {
    for (uint32_t entry_index = 0;
         entry_index < g_moe_tiering.entries.size(); entry_index++) {
        cuda_moe_tier_entry &entry = g_moe_tiering.entries[entry_index];
        if (entry.ram_slot >= g_dynamic_arena.slots.size()) continue;
        cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[entry.ram_slot];
        const uint32_t layer = entry_index / 256u;
        const uint32_t expert = entry_index % 256u;
        if (slot.layer == layer && slot.expert == expert &&
            slot.content_generation == entry.ram_generation) {
            slot.state = DS4_GPU_ARENA_FREE;
            slot.layer = UINT32_MAX;
            slot.expert = UINT32_MAX;
            slot.checksum = 0;
            slot.last_dma_sequence = 0;
        }
        entry.ram_slot = UINT32_MAX;
        entry.ram_generation = 0;
        entry.vram_eligible_after_call = 0;
        entry.has_2bit_ram = 0;
        entry.promoted_from_iq1_cold = 0;
    }
}

static void cuda_moe_tiering_report_and_reset(int flush_ssd_wrap) {
    if (flush_ssd_wrap) cuda_q1_0_ssd_wrap_flush();
    if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
        uint32_t states[4] = {0, 0, 0, 0};
        double mass_sum = 0.0;
        double lfru_top = 0.0;
        for (const cuda_moe_tier_entry &entry : g_moe_tiering.entries) {
            const uint32_t state = (uint32_t)entry.state;
            if (state < 4u) states[state]++;
            mass_sum += entry.mass;
            const double score = cuda_moe_tiering_lfru(
                entry, g_moe_tiering.call_tick);
            if (score > lfru_top) lfru_top = score;
        }
        if (g_moe_tiering.compose_prefill_mass_tiering) {
            fprintf(stderr,
                "ds4: [expert-tiering] final mode=%s policy=%s compose_prefill_mass_tiering=%u compose_router_open=%u snapshot_generation=%llu snapshot_backing_entries=%u snapshot_backing_hits=%llu snapshot_backing_misses=%llu snapshot_to_vram_bytes=%llu forbidden_cold_ssd_to_vram=%llu general_backing_reclaims=%llu clock_calls=%u replacement_budget=%u replacement_budget_base=%u adaptive_budget=%u adaptive_current_budget=%u adaptive_min=%u adaptive_max=%u adaptive_step=%u adaptive_pressure_threshold=%u adaptive_ups=%llu adaptive_downs=%llu adaptive_pressure_epochs=%llu adaptive_quiet_epochs=%llu adaptive_last_budget_skips_delta=%llu adaptive_last_replacements_delta=%llu min_frequency=%u hysteresis=%.9g calls=%llu selected=%llu cold=%llu ram_hits=%llu vram_hits=%llu cold_to_ram=%llu cold_to_vram=%llu ram_to_warm=%llu vram_promotions=%llu vram_demotions=%llu ram_evictions=%llu ram_admit_skips=%llu transient=%llu failures=%llu ssd_bytes=%llu ram_h2d_bytes=%llu policy_epochs=%llu policy_free_promotions=%llu policy_replacements=%llu policy_min_frequency_skips=%llu policy_budget_skips=%llu policy_score_skips=%llu admit_knocks_skips_ssd=%llu admit_knocks_skips_warm=%llu admit_knocks_skips_vram=%llu admit_mass_bypass_ssd=%llu admit_mass_bypass_warm=%llu admit_mass_bypass_vram=%llu admit_replaced_worse_ssd=%llu admit_current_knocks_ssd=%u admit_current_knocks_warm=%u admit_current_knocks_vram=%u states_ssd=%u states_probation=%u states_warm=%u states_vram=%u mass_sum=%.9g lfru_top=%.9g\n",
                cuda_moe_tiering_mode_name(g_moe_tiering.mode),
                cuda_moe_tiering_policy_name(g_moe_tiering.policy),
                g_moe_tiering.compose_prefill_mass_tiering ? 1u : 0u,
                g_moe_tiering.compose_router_open ? 1u : 0u,
                (unsigned long long)g_moe_tiering.snapshot_generation,
                g_moe_tiering.snapshot_backing_entries,
                (unsigned long long)g_moe_tiering.snapshot_backing_hits,
                (unsigned long long)g_moe_tiering.snapshot_backing_misses,
                (unsigned long long)g_moe_tiering.snapshot_to_vram_bytes,
                (unsigned long long)g_moe_tiering.forbidden_cold_ssd_to_vram,
                (unsigned long long)g_moe_tiering.general_backing_reclaims,
                g_moe_tiering.policy_clock_calls,
                g_moe_tiering.policy_replacement_budget,
                g_moe_tiering.policy_replacement_budget_base,
                g_moe_tiering.policy_adaptive_budget ? 1u : 0u,
                g_moe_tiering.policy_replacement_budget,
                g_moe_tiering.policy_adaptive_budget_min,
                g_moe_tiering.policy_adaptive_budget_max,
                g_moe_tiering.policy_adaptive_budget_step,
                g_moe_tiering.policy_adaptive_pressure_threshold,
                (unsigned long long)g_moe_tiering.policy_adaptive_budget_ups,
                (unsigned long long)g_moe_tiering.policy_adaptive_budget_downs,
                (unsigned long long)g_moe_tiering.policy_adaptive_pressure_epochs,
                (unsigned long long)g_moe_tiering.policy_adaptive_quiet_epochs,
                (unsigned long long)g_moe_tiering.policy_adaptive_last_budget_skips_delta,
                (unsigned long long)g_moe_tiering.policy_adaptive_last_replacements_delta,
                g_moe_tiering.policy_min_frequency,
                g_moe_tiering.policy_hysteresis,
                (unsigned long long)g_moe_tiering.calls,
                (unsigned long long)g_moe_tiering.selected,
                (unsigned long long)g_moe_tiering.cold,
                (unsigned long long)g_moe_tiering.ram_hits,
                (unsigned long long)g_moe_tiering.vram_hits,
                (unsigned long long)g_moe_tiering.cold_to_ram,
                (unsigned long long)g_moe_tiering.cold_to_vram,
                (unsigned long long)g_moe_tiering.ram_to_warm,
                (unsigned long long)g_moe_tiering.vram_promotions,
                (unsigned long long)g_moe_tiering.vram_demotions,
                (unsigned long long)g_moe_tiering.ram_evictions,
                (unsigned long long)g_moe_tiering.ram_admit_skips,
                (unsigned long long)g_moe_tiering.transient,
                (unsigned long long)g_moe_tiering.failures,
                (unsigned long long)g_moe_tiering.ssd_bytes,
                (unsigned long long)g_moe_tiering.ram_h2d_bytes,
                (unsigned long long)g_moe_tiering.policy_epochs,
                (unsigned long long)g_moe_tiering.policy_free_promotions,
                (unsigned long long)g_moe_tiering.policy_replacements,
                (unsigned long long)g_moe_tiering.policy_min_frequency_skips,
                (unsigned long long)g_moe_tiering.policy_budget_skips,
                (unsigned long long)g_moe_tiering.policy_score_skips,
                (unsigned long long)g_moe_tiering.admit_knocks_skips_ssd,
                (unsigned long long)g_moe_tiering.admit_knocks_skips_warm,
                (unsigned long long)g_moe_tiering.admit_knocks_skips_vram,
                (unsigned long long)g_moe_tiering.admit_mass_bypass_ssd,
                (unsigned long long)g_moe_tiering.admit_mass_bypass_warm,
                (unsigned long long)g_moe_tiering.admit_mass_bypass_vram,
                (unsigned long long)g_moe_tiering.admit_replaced_worse_ssd,
                g_moe_tiering.policy_admit_current_ssd,
                g_moe_tiering.policy_admit_current_warm,
                g_moe_tiering.policy_admit_current_vram,
                states[CUDA_MOE_TIER_SSD_COLD],
                states[CUDA_MOE_TIER_RAM_PROBATION],
                states[CUDA_MOE_TIER_RAM_WARM],
                states[CUDA_MOE_TIER_VRAM_PROTECTED],
                mass_sum, lfru_top);
        } else {
            fprintf(stderr,
                "ds4: [expert-tiering] final mode=%s policy=%s clock_calls=%u replacement_budget=%u replacement_budget_base=%u adaptive_budget=%u adaptive_current_budget=%u adaptive_min=%u adaptive_max=%u adaptive_step=%u adaptive_pressure_threshold=%u adaptive_ups=%llu adaptive_downs=%llu adaptive_pressure_epochs=%llu adaptive_quiet_epochs=%llu adaptive_last_budget_skips_delta=%llu adaptive_last_replacements_delta=%llu min_frequency=%u hysteresis=%.9g calls=%llu selected=%llu cold=%llu ram_hits=%llu vram_hits=%llu cold_to_ram=%llu cold_to_vram=%llu ram_to_warm=%llu vram_promotions=%llu vram_demotions=%llu ram_evictions=%llu ram_admit_skips=%llu general_backing_reclaims=%llu transient=%llu failures=%llu ssd_bytes=%llu ram_h2d_bytes=%llu policy_epochs=%llu policy_free_promotions=%llu policy_replacements=%llu policy_min_frequency_skips=%llu policy_budget_skips=%llu policy_score_skips=%llu admit_knocks_skips_ssd=%llu admit_knocks_skips_warm=%llu admit_knocks_skips_vram=%llu admit_mass_bypass_ssd=%llu admit_mass_bypass_warm=%llu admit_mass_bypass_vram=%llu admit_replaced_worse_ssd=%llu admit_current_knocks_ssd=%u admit_current_knocks_warm=%u admit_current_knocks_vram=%u states_ssd=%u states_probation=%u states_warm=%u states_vram=%u mass_sum=%.9g lfru_top=%.9g\n",
                cuda_moe_tiering_mode_name(g_moe_tiering.mode),
                cuda_moe_tiering_policy_name(g_moe_tiering.policy),
                g_moe_tiering.policy_clock_calls,
                g_moe_tiering.policy_replacement_budget,
                g_moe_tiering.policy_replacement_budget_base,
                g_moe_tiering.policy_adaptive_budget ? 1u : 0u,
                g_moe_tiering.policy_replacement_budget,
                g_moe_tiering.policy_adaptive_budget_min,
                g_moe_tiering.policy_adaptive_budget_max,
                g_moe_tiering.policy_adaptive_budget_step,
                g_moe_tiering.policy_adaptive_pressure_threshold,
                (unsigned long long)g_moe_tiering.policy_adaptive_budget_ups,
                (unsigned long long)g_moe_tiering.policy_adaptive_budget_downs,
                (unsigned long long)g_moe_tiering.policy_adaptive_pressure_epochs,
                (unsigned long long)g_moe_tiering.policy_adaptive_quiet_epochs,
                (unsigned long long)g_moe_tiering.policy_adaptive_last_budget_skips_delta,
                (unsigned long long)g_moe_tiering.policy_adaptive_last_replacements_delta,
                g_moe_tiering.policy_min_frequency,
                g_moe_tiering.policy_hysteresis,
                (unsigned long long)g_moe_tiering.calls,
                (unsigned long long)g_moe_tiering.selected,
                (unsigned long long)g_moe_tiering.cold,
                (unsigned long long)g_moe_tiering.ram_hits,
                (unsigned long long)g_moe_tiering.vram_hits,
                (unsigned long long)g_moe_tiering.cold_to_ram,
                (unsigned long long)g_moe_tiering.cold_to_vram,
                (unsigned long long)g_moe_tiering.ram_to_warm,
                (unsigned long long)g_moe_tiering.vram_promotions,
                (unsigned long long)g_moe_tiering.vram_demotions,
                (unsigned long long)g_moe_tiering.ram_evictions,
                (unsigned long long)g_moe_tiering.ram_admit_skips,
                (unsigned long long)g_moe_tiering.general_backing_reclaims,
                (unsigned long long)g_moe_tiering.transient,
                (unsigned long long)g_moe_tiering.failures,
                (unsigned long long)g_moe_tiering.ssd_bytes,
                (unsigned long long)g_moe_tiering.ram_h2d_bytes,
                (unsigned long long)g_moe_tiering.policy_epochs,
                (unsigned long long)g_moe_tiering.policy_free_promotions,
                (unsigned long long)g_moe_tiering.policy_replacements,
                (unsigned long long)g_moe_tiering.policy_min_frequency_skips,
                (unsigned long long)g_moe_tiering.policy_budget_skips,
                (unsigned long long)g_moe_tiering.policy_score_skips,
                (unsigned long long)g_moe_tiering.admit_knocks_skips_ssd,
                (unsigned long long)g_moe_tiering.admit_knocks_skips_warm,
                (unsigned long long)g_moe_tiering.admit_knocks_skips_vram,
                (unsigned long long)g_moe_tiering.admit_mass_bypass_ssd,
                (unsigned long long)g_moe_tiering.admit_mass_bypass_warm,
                (unsigned long long)g_moe_tiering.admit_mass_bypass_vram,
                (unsigned long long)g_moe_tiering.admit_replaced_worse_ssd,
                g_moe_tiering.policy_admit_current_ssd,
                g_moe_tiering.policy_admit_current_warm,
                g_moe_tiering.policy_admit_current_vram,
                states[CUDA_MOE_TIER_SSD_COLD],
                states[CUDA_MOE_TIER_RAM_PROBATION],
                states[CUDA_MOE_TIER_RAM_WARM],
                states[CUDA_MOE_TIER_VRAM_PROTECTED],
                mass_sum, lfru_top);
        }
    }
    if (g_iq1_promotion.requested_slots != 0u) {
        fprintf(stderr,
            "ds4: [iq1-promotion] final requested_slots=%u reserved_slots=%u "
            "strategy=%s "
            "min_touches=%llu min_weight=%.9g min_mass=%.9g "
            "request_budget=%llu window_calls=%llu window_budget=%llu "
            "snapshot_evictions=%llu cold_observed=%llu cold_existing_2bit=%llu "
            "cold_to_2bit_ram=%llu probation_ram_hits=%llu next_token_waits=%llu "
            "promotion_2bit_ssd_bytes=%llu promotion_2bit_ssd_seconds=%.9g "
            "direct_ssd_to_vram_rejected=%llu probation_backing_reclaims=%llu "
            "cold_gate_candidates=%llu weight_ge_001=%llu weight_ge_002=%llu "
            "weight_ge_005=%llu weight_ge_010=%llu skips_touches=%llu "
            "skips_weight=%llu skips_mass=%llu skips_request_budget=%llu "
            "skips_window_budget=%llu q1_0_observed=%llu "
            "q1_0_stage_attempts=%llu q1_0_stage_successes=%llu "
            "q1_0_next_call_guards=%llu "
            "q1_0_record_rejects=%llu q1_0_record_attempts=%llu "
            "q1_0_record_successes=%llu q1_0_record_failures=%llu "
            "failures=%llu\n",
            g_iq1_promotion.requested_slots,
            g_iq1_promotion.reserved_slots,
            g_moe_tiering.compose_router_open ?
                "pre-reserved-open-router" : "snapshot-evict",
            (unsigned long long)g_iq1_promotion.min_touches,
            g_iq1_promotion.min_weight,
            g_iq1_promotion.min_mass,
            (unsigned long long)g_iq1_promotion.request_budget,
            (unsigned long long)g_iq1_promotion.window_calls,
            (unsigned long long)g_iq1_promotion.window_budget,
            (unsigned long long)g_iq1_promotion.snapshot_evictions,
            (unsigned long long)g_iq1_promotion.cold_observed,
            (unsigned long long)g_iq1_promotion.cold_existing_2bit,
            (unsigned long long)g_iq1_promotion.cold_to_2bit_ram,
            (unsigned long long)g_iq1_promotion.probation_ram_hits,
            (unsigned long long)g_iq1_promotion.next_token_waits,
            (unsigned long long)g_iq1_promotion.promotion_2bit_ssd_bytes,
            g_iq1_promotion.promotion_2bit_ssd_seconds,
            (unsigned long long)g_iq1_promotion.direct_ssd_to_vram_rejected,
            (unsigned long long)g_iq1_promotion.probation_backing_reclaims,
            (unsigned long long)g_iq1_promotion.cold_gate_candidates,
            (unsigned long long)g_iq1_promotion.weight_ge_001,
            (unsigned long long)g_iq1_promotion.weight_ge_002,
            (unsigned long long)g_iq1_promotion.weight_ge_005,
            (unsigned long long)g_iq1_promotion.weight_ge_010,
            (unsigned long long)g_iq1_promotion.skips_touches,
            (unsigned long long)g_iq1_promotion.skips_weight,
            (unsigned long long)g_iq1_promotion.skips_mass,
            (unsigned long long)g_iq1_promotion.skips_request_budget,
            (unsigned long long)g_iq1_promotion.skips_window_budget,
            (unsigned long long)g_iq1_promotion.q1_0_observed,
            (unsigned long long)g_iq1_promotion.q1_0_stage_attempts,
            (unsigned long long)g_iq1_promotion.q1_0_stage_successes,
            (unsigned long long)g_iq1_promotion.q1_0_next_call_guards,
            (unsigned long long)g_iq1_promotion.q1_0_record_rejects,
            (unsigned long long)g_iq1_promotion.q1_0_record_attempts,
            (unsigned long long)g_iq1_promotion.q1_0_record_successes,
            (unsigned long long)g_iq1_promotion.q1_0_record_failures,
            (unsigned long long)g_iq1_promotion.failures);
    }
    if (!cuda_q1_0_ssd_wrap_tier_reset_begin()) return;
    g_dynamic_arena.tiering_exclusive = 0;
    g_moe_tiering = cuda_moe_tiering();
    g_iq1_promotion = cuda_iq1_promotion();
}

static void cuda_moe_tiering_request_boundary_reset(void) {
    if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF &&
        g_moe_tiering.compose_prefill_mass_tiering) {
        cuda_moe_tiering_report_and_reset(
            cuda_g133_shared_policy_active() ? 0 : 1);
    }
}

static int cuda_moe_tiering_reserve_open_router_slots(uint32_t requested) {
    if (requested == 0u) return 1;
    if (!g_moe_tiering.compose_prefill_mass_tiering ||
        !g_moe_tiering.compose_router_open ||
        requested >= g_moe_tiering.snapshot_backing_entries) {
        fprintf(stderr,
                "ds4: open-router backing reserve refused requested=%u backing=%u\n",
                requested, g_moe_tiering.snapshot_backing_entries);
        return 0;
    }
    try {
        g_moe_tiering.open_router_pool_slot.assign(
            g_dynamic_arena.slots.size(), 0u);
    } catch (...) {
        fprintf(stderr,
                "ds4: open-router backing reserve metadata allocation failed\n");
        return 0;
    }
    uint32_t free_slots = 0u;
    uint32_t reserved_slots = 0u;
    for (uint32_t slot = 0;
         slot < g_dynamic_arena.slots.size(); slot++) {
        if (g_dynamic_arena.slots[slot].state != DS4_GPU_ARENA_FREE ||
            (cuda_g73_open_requested() &&
             g_dynamic_arena.slots[slot].pageable)) {
            continue;
        }
        free_slots++;
        if (reserved_slots < requested) {
            g_moe_tiering.open_router_pool_slot[slot] = 1u;
            reserved_slots++;
        }
    }
    if (reserved_slots < requested) {
        fprintf(stderr,
                "ds4: open-router backing reserve short requested=%u free=%u\n",
                requested, free_slots);
        g_moe_tiering.open_router_pool_slot.clear();
        return 0;
    }
    g_moe_tiering.open_router_reserve_slots = reserved_slots;
    if (g_iq1_promotion.requested_slots != 0u) {
        g_iq1_promotion.reserved_slots = reserved_slots;
    }
    fprintf(stderr,
            "ds4: [expert-tiering] open-router backing ready requested_slots=%u "
            "reserved_slots=%u remaining_snapshot=%u free_slots=%u "
            "strategy=pre-reserved-open-router\n",
            requested, g_moe_tiering.open_router_reserve_slots,
            g_moe_tiering.snapshot_backing_entries,
            free_slots);
    return 1;
}

static int cuda_moe_tiering_prepare(void) {
    const int requested = cuda_moe_tiering_mode_requested();
    if (requested < 0) return 0;
    const int g133_enabled = cuda_g133_tier_requested();
    const int compose_requested = cuda_moe_prefill_tier_compose_requested();
    const int compose_router_open =
        cuda_moe_prefill_tier_router_open_requested();
    const int promotion_probation_slots =
        cuda_quant_promotion_probation_slots_requested();
    const int promotion_q1_0 =
        cuda_q1_0_dynamic_promotion_requested();
    const int configured_reserve_slots =
        cuda_moe_prefill_tier_reserve_slots_requested();
    if (compose_requested < 0 || compose_router_open < 0 ||
        promotion_probation_slots < 0 ||
        configured_reserve_slots < 0) return 0;
    if (cuda_q1_0_exclusive_arena_active() &&
        (requested != CUDA_MOE_TIER_OFF || compose_requested > 0 ||
         compose_router_open > 0 || promotion_probation_slots > 0 ||
         configured_reserve_slots > 0)) {
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] result=failed reason=mixed-host-resolver-not-implemented expert_tiering=%d compose=%d router_open=%d promotion_probation=%d reserve=%d\n",
                requested, compose_requested, compose_router_open,
                promotion_probation_slots, configured_reserve_slots);
        return 0;
    }
    uint64_t promotion_min_touches = 1u;
    double promotion_min_weight = 0.0;
    double promotion_min_mass = 0.0;
    uint64_t promotion_request_budget = 0u;
    uint64_t promotion_window_calls = 0u;
    uint64_t promotion_window_budget = 0u;
    if (promotion_probation_slots > 0 &&
        !cuda_quant_promotion_gate_config(
            promotion_q1_0,
            &promotion_min_touches, &promotion_min_weight,
            &promotion_min_mass, &promotion_request_budget,
            &promotion_window_calls, &promotion_window_budget)) {
        return 0;
    }
    if (compose_router_open && !compose_requested) {
        fprintf(stderr,
                "ds4: open prefill tier router requires composed tiering\n");
        return 0;
    }
    const char *iq1_mixed = getenv("DS4_IQ1_S_MIXED_COLD_K");
    if (cuda_g73_open_requested() &&
        (!g133_enabled || requested != CUDA_MOE_TIER_ENFORCE ||
         !compose_requested || !compose_router_open ||
         configured_reserve_slots <= 0 ||
         !cuda_moe_gpu_routes_requested() ||
         cuda_q1_0_mixed_cold_one_requested() ||
         (iq1_mixed && strcmp(iq1_mixed, "1") == 0) ||
         cuda_q1_0_snapshot_backing_requested())) {
        fprintf(stderr,
                "ds4: DS4_G73_OPEN=1 requires G133 enforce/mass-LFRU, "
                "composed open routing, reserved arena slots, GPU routes, "
                "and Q1/IQ1 serving disabled\n");
        return 0;
    }
    if (!promotion_q1_0 && promotion_probation_slots > 0 &&
        (requested != CUDA_MOE_TIER_ENFORCE || !compose_requested ||
         !compose_router_open ||
         configured_reserve_slots != promotion_probation_slots ||
         !g_iq1_s_sidecar_file_valid || !iq1_mixed ||
         strcmp(iq1_mixed, "1") != 0)) {
        fprintf(stderr,
                "ds4: IQ1 promotion probation requires mixed IQ1_S, open-router composed enforce tiering, matching reserve/probation slots, and a bound sidecar\n");
        return 0;
    }
    if (promotion_q1_0 &&
        (promotion_probation_slots <= 0 ||
         requested != CUDA_MOE_TIER_ENFORCE || !compose_requested ||
         !compose_router_open ||
         configured_reserve_slots != promotion_probation_slots ||
         !g_q1_0_sidecar_file_valid ||
         !cuda_q1_0_dual_arena_requested() ||
         cuda_q1_0_snapshot_backing_requested())) {
        fprintf(stderr,
                "ds4: Q1_0 promotion probation requires full resident "
                "dual-arena Q1_0, open-router composed enforce tiering, "
                "and matching reserve/probation slots\n");
        return 0;
    }
    if (requested == CUDA_MOE_TIER_OFF) {
        if (g133_enabled) {
            fprintf(stderr,
                    "ds4: DS4_G133_TIER=1 requires DS4_EXPERT_TIERING=enforce\n");
            return 0;
        }
        if (compose_requested > 0) {
            fprintf(stderr,
                    "ds4: prefill/tiering compose requires expert tiering enforce\n");
            return 0;
        }
        if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
            cuda_moe_tiering_report_and_reset(1);
        }
        return 1;
    }
    const int policy_requested = cuda_moe_tiering_policy_requested();
    uint32_t clock_calls = 430u;
    uint32_t replacement_budget = 16u;
    int adaptive_budget = 0;
    uint32_t adaptive_budget_min = 16u;
    uint32_t adaptive_budget_max = 32u;
    uint32_t adaptive_budget_step = 8u;
    uint32_t adaptive_pressure_threshold = 64u;
    uint32_t min_frequency = 3u;
    int admit_adaptive = 0;
    uint32_t admit_knocks_ssd = 0u;
    uint32_t admit_knocks_warm = 0u;
    uint32_t admit_knocks_vram = 3u;
    double admit_mass_bypass_ssd = 0.0;
    double admit_mass_bypass_warm = 0.0;
    double admit_mass_bypass_vram = 0.0;
    double hysteresis = 1.25;
    uint32_t g133_knock_x = 3u;
    uint32_t g133_knock_y = 5u;
    uint32_t g133_promote_budget = 8u;
    double g133_decay = 0.98;
    const double g133_demotion_margin = 1.0;
    int g133_seed_dynamic = 1;
    if (policy_requested < 0 ||
        !cuda_moe_tiering_u32_env(
            "DS4_EXPERT_TIER_CLOCK_CALLS", 430u, 1u, 1000000u,
            &clock_calls) ||
        !cuda_moe_tiering_u32_env(
            "DS4_EXPERT_TIER_REPLACEMENT_BUDGET", 16u, 1u, 512u,
            &replacement_budget) ||
        !cuda_moe_tiering_u32_env(
            "DS4_EXPERT_TIER_MIN_FREQUENCY", 3u, 2u, 1000000u,
            &min_frequency) ||
         !cuda_moe_tiering_double_env(
             "DS4_EXPERT_TIER_HYSTERESIS", 1.25, 1.0, 100.0,
             &hysteresis)) {
        return 0;
    }
    admit_knocks_vram = min_frequency;
    const char *admit_knocks_vram_env =
        getenv("DS4_EXPERT_TIER_ADMIT_KNOCKS_VRAM");
    if (!cuda_g133_bool_env(
            "DS4_EXPERT_TIER_ADMIT_ADAPTIVE", 0, &admit_adaptive) ||
        !cuda_moe_tiering_u32_env(
            "DS4_EXPERT_TIER_ADMIT_KNOCKS_SSD", 0u, 0u, UINT16_MAX,
            &admit_knocks_ssd) ||
        !cuda_moe_tiering_u32_env(
            "DS4_EXPERT_TIER_ADMIT_KNOCKS_WARM", 0u, 0u, UINT16_MAX,
            &admit_knocks_warm) ||
        !cuda_moe_tiering_u32_env(
            "DS4_EXPERT_TIER_ADMIT_KNOCKS_VRAM", min_frequency, 0u,
            UINT16_MAX, &admit_knocks_vram) ||
        !cuda_moe_tiering_double_env(
            "DS4_EXPERT_TIER_ADMIT_MASS_BYPASS_SSD", 0.0, 0.0, 1.0e300,
            &admit_mass_bypass_ssd) ||
        !cuda_moe_tiering_double_env(
            "DS4_EXPERT_TIER_ADMIT_MASS_BYPASS_WARM", 0.0, 0.0, 1.0e300,
            &admit_mass_bypass_warm) ||
        !cuda_moe_tiering_double_env(
            "DS4_EXPERT_TIER_ADMIT_MASS_BYPASS_VRAM", 0.0, 0.0, 1.0e300,
            &admit_mass_bypass_vram)) {
        return 0;
    }
    if (!admit_adaptive &&
        ((admit_mass_bypass_ssd > 0.0 && admit_knocks_ssd == 0u) ||
         (admit_mass_bypass_warm > 0.0 && admit_knocks_warm == 0u))) {
        fprintf(stderr,
                "ds4: SSD/warm mass bypass requires a positive boundary "
                "knock threshold or adaptive admission\n");
        return 0;
    }
    const int admit_ssd_enabled =
        admit_adaptive || admit_knocks_ssd > 0u ||
        admit_mass_bypass_ssd > 0.0;
    const int admit_warm_enabled =
        admit_adaptive || admit_knocks_warm > 0u ||
        admit_mass_bypass_warm > 0.0;
    const int admit_vram_enabled =
        admit_adaptive ||
        (admit_knocks_vram_env && admit_knocks_vram_env[0]) ||
        admit_mass_bypass_vram > 0.0;
    const int admit_policy_enabled =
        admit_ssd_enabled || admit_warm_enabled || admit_vram_enabled;
    if (g133_enabled &&
        (!cuda_moe_tiering_u32_env(
             "DS4_G133_KNOCK_X", 3u, 1u,
             (uint32_t)CUDA_G133_STREAK_MAX,
             &g133_knock_x) ||
         !cuda_moe_tiering_u32_env(
             "DS4_G133_KNOCK_Y", 5u, 1u,
             (uint32_t)CUDA_G133_STREAK_MAX,
             &g133_knock_y) ||
         !cuda_moe_tiering_double_env(
             "DS4_G133_DECAY", 0.98, 0.000001, 1.0,
             &g133_decay) ||
         !cuda_g133_bool_env(
             "DS4_G133_SEED_DYNAMIC", 1, &g133_seed_dynamic) ||
         !cuda_moe_tiering_u32_env(
             "DS4_G133_PROMOTE_BUDGET", 8u, 1u, 512u,
             &g133_promote_budget))) {
        return 0;
    }
    if (g133_enabled && !(g133_decay > 0.0 && g133_decay < 1.0)) {
        fprintf(stderr,
                "ds4: invalid DS4_G133_DECAY=%.17g; must satisfy 0 < decay < 1\n",
                g133_decay);
        return 0;
    }
    if (g133_enabled &&
        (uint64_t)g133_knock_x + (uint64_t)g133_knock_y >
            CUDA_G133_STREAK_MAX) {
        fprintf(stderr,
                "ds4: invalid DS4_G133_KNOCK_X+DS4_G133_KNOCK_Y=%llu; "
                "must be <= %llu because G133 advisory streak is %u bits\n",
                (unsigned long long)(
                    (uint64_t)g133_knock_x + (uint64_t)g133_knock_y),
                (unsigned long long)CUDA_G133_STREAK_MAX,
                (unsigned)CUDA_G133_STREAK_BITS);
        return 0;
    }
    if (g133_enabled &&
        (requested != CUDA_MOE_TIER_ENFORCE ||
         policy_requested != CUDA_MOE_TIER_POLICY_MASS_LFRU)) {
        fprintf(stderr,
                "ds4: DS4_G133_TIER=1 requires enforce mass-lfru tiering\n");
        return 0;
    }
    if (!cuda_moe_tiering_adaptive_budget_requested(&adaptive_budget)) {
        adaptive_budget = 0;
    }
    if (adaptive_budget) {
        int adaptive_config_ok = 1;
        adaptive_config_ok = adaptive_config_ok &&
            cuda_moe_tiering_u32_env(
                "DS4_EXPERT_TIER_ADAPTIVE_BUDGET_MIN", 16u, 1u, 512u,
                &adaptive_budget_min);
        adaptive_config_ok = adaptive_config_ok &&
            cuda_moe_tiering_u32_env(
                "DS4_EXPERT_TIER_ADAPTIVE_BUDGET_MAX", 32u, 1u, 512u,
                &adaptive_budget_max);
        adaptive_config_ok = adaptive_config_ok &&
            cuda_moe_tiering_u32_env(
                "DS4_EXPERT_TIER_ADAPTIVE_BUDGET_STEP", 8u, 1u, 512u,
                &adaptive_budget_step);
        adaptive_config_ok = adaptive_config_ok &&
            cuda_moe_tiering_u32_env(
                "DS4_EXPERT_TIER_ADAPTIVE_PRESSURE_THRESHOLD", 64u, 1u,
                1000000u, &adaptive_pressure_threshold);
        if (!adaptive_config_ok ||
            adaptive_budget_min > adaptive_budget_max ||
            adaptive_budget_step >
                adaptive_budget_max - adaptive_budget_min + 1u ||
            replacement_budget < adaptive_budget_min ||
            replacement_budget > adaptive_budget_max) {
            fprintf(stderr,
                    "ds4: invalid adaptive expert tier budget config; adaptive budget disabled\n");
            adaptive_budget = 0;
            adaptive_budget_min = 16u;
            adaptive_budget_max = 32u;
            adaptive_budget_step = 8u;
            adaptive_pressure_threshold = 64u;
        }
    }
    if (policy_requested == CUDA_MOE_TIER_POLICY_SECOND_TOUCH) {
        if (admit_policy_enabled) {
            fprintf(stderr,
                    "ds4: boundary admission policy requires mass-lfru tiering\n");
            return 0;
        }
        clock_calls = 0u;
        replacement_budget = 0u;
        adaptive_budget = 0;
        min_frequency = 2u;
        hysteresis = 1.0;
    }
    if (g_moe_tiering.mode == (cuda_moe_tier_mode)requested &&
        g_moe_tiering.policy == (cuda_moe_tier_policy)policy_requested &&
        g_moe_tiering.policy_clock_calls == clock_calls &&
        g_moe_tiering.policy_replacement_budget_base == replacement_budget &&
        g_moe_tiering.policy_adaptive_budget == adaptive_budget &&
        g_moe_tiering.policy_adaptive_budget_min == adaptive_budget_min &&
        g_moe_tiering.policy_adaptive_budget_max == adaptive_budget_max &&
        g_moe_tiering.policy_adaptive_budget_step == adaptive_budget_step &&
        g_moe_tiering.policy_adaptive_pressure_threshold ==
            adaptive_pressure_threshold &&
        g_moe_tiering.policy_min_frequency == min_frequency &&
        g_moe_tiering.policy_admit_enabled == admit_policy_enabled &&
        g_moe_tiering.policy_admit_ssd_enabled == admit_ssd_enabled &&
        g_moe_tiering.policy_admit_warm_enabled == admit_warm_enabled &&
        g_moe_tiering.policy_admit_vram_enabled == admit_vram_enabled &&
        g_moe_tiering.policy_admit_adaptive == admit_adaptive &&
        g_moe_tiering.policy_admit_knocks_ssd == admit_knocks_ssd &&
        g_moe_tiering.policy_admit_knocks_warm == admit_knocks_warm &&
        g_moe_tiering.policy_admit_knocks_vram == admit_knocks_vram &&
        g_moe_tiering.policy_admit_mass_bypass_ssd ==
            admit_mass_bypass_ssd &&
        g_moe_tiering.policy_admit_mass_bypass_warm ==
            admit_mass_bypass_warm &&
        g_moe_tiering.policy_admit_mass_bypass_vram ==
            admit_mass_bypass_vram &&
        g_moe_tiering.policy_hysteresis == hysteresis &&
        g_moe_tiering.g133_enabled == g133_enabled &&
        g_moe_tiering.g133_seed_dynamic == g133_seed_dynamic &&
        g_moe_tiering.g133_knock_x == g133_knock_x &&
        g_moe_tiering.g133_knock_y == g133_knock_y &&
        g_moe_tiering.g133_promote_budget == g133_promote_budget &&
        g_moe_tiering.g133_decay == g133_decay &&
        g_iq1_promotion.requested_slots ==
            (uint32_t)promotion_probation_slots &&
        g_iq1_promotion.min_touches == promotion_min_touches &&
        g_iq1_promotion.min_weight == promotion_min_weight &&
        g_iq1_promotion.min_mass == promotion_min_mass &&
        g_iq1_promotion.request_budget == promotion_request_budget &&
        g_iq1_promotion.window_calls == promotion_window_calls &&
        g_iq1_promotion.window_budget == promotion_window_budget &&
        g_moe_tiering.open_router_reserve_slots ==
            (uint32_t)configured_reserve_slots &&
        g_moe_tiering.compose_prefill_mass_tiering == compose_requested &&
        g_moe_tiering.compose_router_open == compose_router_open &&
        (!compose_requested ||
         g_moe_tiering.snapshot_generation ==
             g_dynamic_arena.snapshot_generation) &&
        g_moe_tiering.entries.size() ==
            (size_t)CUDA_MOE_LAYER_COUNT * 256u) {
        return 1;
    }
    if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
        cuda_moe_tiering_report_and_reset(1);
    }
    if (requested == CUDA_MOE_TIER_ENFORCE) {
        if (!g_dynamic_arena.host_base || g_dynamic_arena.txn ||
            g_dynamic_arena.n_layer != CUDA_MOE_LAYER_COUNT ||
            g_dynamic_arena.n_expert != 256u ||
            g_dynamic_arena.slots.empty()) {
            fprintf(stderr,
                    "ds4: expert tiering enforce requires an idle pinned dynamic arena\n");
            return 0;
        }
        if (compose_requested) {
            if (policy_requested != CUDA_MOE_TIER_POLICY_MASS_LFRU ||
                g_dynamic_arena.snapshot_generation == 0 ||
                g_dynamic_arena.hits_disabled ||
                g_dynamic_arena.submissions_blocked ||
                g_dynamic_arena_observer.enabled ||
                !g_dynamic_arena_observer.target.empty() ||
                !g_dynamic_arena_observer.counts.empty() ||
                !g_prefill_mass_observer.enabled ||
                !g_prefill_mass_observer.finalized ||
                !g_prefill_mass_observer.wrap_published ||
                g_reap_mass_observer.enabled) {
                fprintf(stderr,
                        "ds4: prefill/tiering compose requires finalized published prefill snapshot and no dynamic/REAP observer\n");
                return 0;
            }
        } else if (g_dynamic_arena.snapshot_generation != 0 ||
                   g_dynamic_arena_observer.enabled ||
                   g_prefill_mass_observer.enabled ||
                   g_reap_mass_observer.enabled) {
            fprintf(stderr,
                    "ds4: expert tiering enforce requires an idle pinned dynamic arena\n");
            return 0;
        }
    }
    try {
        cuda_moe_tier_entry empty = {};
        empty.ram_slot = UINT32_MAX;
        empty.state = CUDA_MOE_TIER_SSD_COLD;
        g_moe_tiering.entries.assign(
            (size_t)CUDA_MOE_LAYER_COUNT * 256u, empty);
    } catch (...) {
        fprintf(stderr, "ds4: expert tiering metadata allocation failed\n");
        return 0;
    }
    g_moe_tiering.mode = (cuda_moe_tier_mode)requested;
    g_moe_tiering.policy = (cuda_moe_tier_policy)policy_requested;
    g_moe_tiering.compose_prefill_mass_tiering = compose_requested;
    g_moe_tiering.compose_router_open = compose_router_open;
    g_moe_tiering.policy_clock_calls = clock_calls;
    g_moe_tiering.policy_replacement_budget = replacement_budget;
    g_moe_tiering.policy_replacement_budget_base = replacement_budget;
    g_moe_tiering.policy_adaptive_budget = adaptive_budget;
    g_moe_tiering.policy_adaptive_budget_min = adaptive_budget_min;
    g_moe_tiering.policy_adaptive_budget_max = adaptive_budget_max;
    g_moe_tiering.policy_adaptive_budget_step = adaptive_budget_step;
    g_moe_tiering.policy_adaptive_pressure_threshold =
        adaptive_pressure_threshold;
    g_moe_tiering.policy_min_frequency = min_frequency;
    g_moe_tiering.policy_admit_enabled = admit_policy_enabled;
    g_moe_tiering.policy_admit_ssd_enabled = admit_ssd_enabled;
    g_moe_tiering.policy_admit_warm_enabled = admit_warm_enabled;
    g_moe_tiering.policy_admit_vram_enabled = admit_vram_enabled;
    g_moe_tiering.policy_admit_adaptive = admit_adaptive;
    g_moe_tiering.policy_admit_knocks_ssd = admit_knocks_ssd;
    g_moe_tiering.policy_admit_knocks_warm = admit_knocks_warm;
    g_moe_tiering.policy_admit_knocks_vram = admit_knocks_vram;
    g_moe_tiering.policy_admit_current_ssd =
        admit_adaptive ? std::max(1u, admit_knocks_ssd) : admit_knocks_ssd;
    g_moe_tiering.policy_admit_current_warm =
        admit_adaptive ? std::max(1u, admit_knocks_warm) : admit_knocks_warm;
    g_moe_tiering.policy_admit_current_vram =
        admit_adaptive ? std::max(1u, admit_knocks_vram) : admit_knocks_vram;
    g_moe_tiering.policy_admit_mass_bypass_ssd = admit_mass_bypass_ssd;
    g_moe_tiering.policy_admit_mass_bypass_warm = admit_mass_bypass_warm;
    g_moe_tiering.policy_admit_mass_bypass_vram = admit_mass_bypass_vram;
    g_moe_tiering.policy_admit_epoch = UINT64_MAX;
    g_moe_tiering.policy_hysteresis = hysteresis;
    g_moe_tiering.policy_epoch = UINT64_MAX;
    g_moe_tiering.g133_enabled = g133_enabled;
    g_moe_tiering.g133_seed_dynamic = g133_seed_dynamic;
    g_moe_tiering.g133_knock_x = g133_knock_x;
    g_moe_tiering.g133_knock_y = g133_knock_y;
    g_moe_tiering.g133_promote_budget = g133_promote_budget;
    g_cuda_g133_advisory_budget.max_epoch.store(
        0u, std::memory_order_relaxed);
    g_cuda_g133_advisory_budget.remaining.store(
        g133_promote_budget, std::memory_order_relaxed);
    g_moe_tiering.g133_decay = g133_decay;
    g_moe_tiering.g133_demotion_margin = g133_demotion_margin;
    g_iq1_promotion = cuda_iq1_promotion();
    g_iq1_promotion.requested_slots =
        (uint32_t)promotion_probation_slots;
    g_iq1_promotion.min_touches = promotion_min_touches;
    g_iq1_promotion.min_weight = promotion_min_weight;
    g_iq1_promotion.min_mass = promotion_min_mass;
    g_iq1_promotion.request_budget = promotion_request_budget;
    g_iq1_promotion.window_calls = promotion_window_calls;
    g_iq1_promotion.window_budget = promotion_window_budget;
    if (compose_requested) {
        g_moe_tiering.snapshot_generation =
            g_dynamic_arena.snapshot_generation;
        for (uint32_t entry_index = 0;
             entry_index < g_dynamic_arena.active.size() &&
             entry_index < g_moe_tiering.entries.size(); entry_index++) {
            const uint32_t layer = entry_index / 256u;
            const uint32_t expert = entry_index % 256u;
            if (cuda_dynamic_arena_binding_valid(
                    g_dynamic_arena,
                    g_dynamic_arena.active[entry_index],
                    layer, expert,
                    g_moe_tiering.snapshot_generation,
                    DS4_GPU_ARENA_READY)) {
                cuda_moe_tier_entry &entry =
                    g_moe_tiering.entries[entry_index];
                /* Snapshot-backed RAM is borrowed backing, not tier-owned. */
                entry.ram_slot = UINT32_MAX;
                entry.ram_generation = 0;
                entry.has_2bit_ram =
                    g_dynamic_arena.backing ==
                    CUDA_DYNAMIC_ARENA_BACKING_PRIMARY;
                entry.state = CUDA_MOE_TIER_RAM_PROBATION;
                g_moe_tiering.snapshot_backing_entries++;
            }
        }
        if (g_moe_tiering.snapshot_backing_entries == 0u) {
            fprintf(stderr,
                    "ds4: prefill/tiering compose requires non-empty snapshot backing\n");
            g_moe_tiering = cuda_moe_tiering();
            g_iq1_promotion = cuda_iq1_promotion();
            return 0;
        }
        if (!cuda_moe_tiering_reserve_open_router_slots(
                (uint32_t)configured_reserve_slots)) {
            g_moe_tiering = cuda_moe_tiering();
            g_iq1_promotion = cuda_iq1_promotion();
            return 0;
        }
    }
    if (g_moe_tiering.mode == CUDA_MOE_TIER_ENFORCE) {
        g_dynamic_arena.tiering_exclusive = 1;
    }
    if (g_moe_tiering.g133_enabled) {
        fprintf(stderr,
                "ds4: [g133-tier] enabled=1 knock_x=%u knock_y=%u "
                "decay=%.9g seed_dynamic=%u promote_budget=%u "
                "authority=cuda_moe_tier_entry lifecycle=writer-claims\n",
                g_moe_tiering.g133_knock_x,
                g_moe_tiering.g133_knock_y,
                g_moe_tiering.g133_decay,
                g_moe_tiering.g133_seed_dynamic ? 1u : 0u,
                g_moe_tiering.g133_promote_budget);
    }
    if (g_moe_tiering.policy_admit_enabled) {
        fprintf(stderr,
                "ds4: [expert-tiering] boundary-admission adaptive=%u "
                "ssd_enabled=%u warm_enabled=%u vram_enabled=%u "
                "knocks_ssd=%u knocks_warm=%u knocks_vram=%u "
                "current_ssd=%u current_warm=%u current_vram=%u "
                "mass_bypass_ssd=%.9g mass_bypass_warm=%.9g "
                "mass_bypass_vram=%.9g window=clock_calls\n",
                g_moe_tiering.policy_admit_adaptive ? 1u : 0u,
                g_moe_tiering.policy_admit_ssd_enabled ? 1u : 0u,
                g_moe_tiering.policy_admit_warm_enabled ? 1u : 0u,
                g_moe_tiering.policy_admit_vram_enabled ? 1u : 0u,
                g_moe_tiering.policy_admit_knocks_ssd,
                g_moe_tiering.policy_admit_knocks_warm,
                g_moe_tiering.policy_admit_knocks_vram,
                g_moe_tiering.policy_admit_current_ssd,
                g_moe_tiering.policy_admit_current_warm,
                g_moe_tiering.policy_admit_current_vram,
                g_moe_tiering.policy_admit_mass_bypass_ssd,
                g_moe_tiering.policy_admit_mass_bypass_warm,
                g_moe_tiering.policy_admit_mass_bypass_vram);
    }
    fprintf(stderr, "ds4: expert tiering active mode=%s policy=%s compose_prefill_mass_tiering=%u compose_router_open=%u snapshot_generation=%llu snapshot_backing_entries=%u clock_calls=%u replacement_budget=%u replacement_budget_base=%u adaptive_budget=%u adaptive_current_budget=%u adaptive_min=%u adaptive_max=%u adaptive_step=%u adaptive_pressure_threshold=%u adaptive_ups=%llu adaptive_downs=%llu adaptive_pressure_epochs=%llu adaptive_quiet_epochs=%llu adaptive_last_budget_skips_delta=%llu adaptive_last_replacements_delta=%llu min_frequency=%u hysteresis=%.9g entries=%u ram_slots=%u\n",
            cuda_moe_tiering_mode_name(g_moe_tiering.mode),
            cuda_moe_tiering_policy_name(g_moe_tiering.policy),
            g_moe_tiering.compose_prefill_mass_tiering ? 1u : 0u,
            g_moe_tiering.compose_router_open ? 1u : 0u,
            (unsigned long long)g_moe_tiering.snapshot_generation,
            g_moe_tiering.snapshot_backing_entries,
            g_moe_tiering.policy_clock_calls,
            g_moe_tiering.policy_replacement_budget,
            g_moe_tiering.policy_replacement_budget_base,
            g_moe_tiering.policy_adaptive_budget ? 1u : 0u,
            g_moe_tiering.policy_replacement_budget,
            g_moe_tiering.policy_adaptive_budget_min,
            g_moe_tiering.policy_adaptive_budget_max,
            g_moe_tiering.policy_adaptive_budget_step,
            g_moe_tiering.policy_adaptive_pressure_threshold,
            (unsigned long long)g_moe_tiering.policy_adaptive_budget_ups,
            (unsigned long long)g_moe_tiering.policy_adaptive_budget_downs,
            (unsigned long long)g_moe_tiering.policy_adaptive_pressure_epochs,
            (unsigned long long)g_moe_tiering.policy_adaptive_quiet_epochs,
            (unsigned long long)g_moe_tiering.policy_adaptive_last_budget_skips_delta,
            (unsigned long long)g_moe_tiering.policy_adaptive_last_replacements_delta,
            g_moe_tiering.policy_min_frequency,
            g_moe_tiering.policy_hysteresis,
            (uint32_t)g_moe_tiering.entries.size(),
            (uint32_t)g_dynamic_arena.slots.size());
    return 1;
}

/* arena_slot_out is optional and exists for P.5a: the zero-copy admission
 * test needs the arena slot index to read its pageable marker. Passing NULL
 * keeps the original contract. */
static int cuda_moe_tiering_snapshot_ram_ptrs(
        uint32_t layer, uint32_t expert,
        char **gate, char **up, char **down,
        uint32_t *arena_slot_out = NULL) {
    if (!g_moe_tiering.compose_prefill_mass_tiering ||
        g_dynamic_arena.backing != CUDA_DYNAMIC_ARENA_BACKING_PRIMARY ||
        layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        !gate || !up || !down ||
        g_dynamic_arena.snapshot_generation !=
            g_moe_tiering.snapshot_generation ||
        g_dynamic_arena.hits_disabled ||
        g_dynamic_arena.submissions_blocked) {
        return 0;
    }
    const uint32_t entry = layer * 256u + expert;
    if (entry >= g_dynamic_arena.active.size()) return 0;
    const cuda_dynamic_arena_binding &binding =
        g_dynamic_arena.active[entry];
    if (!cuda_dynamic_arena_binding_valid(
            g_dynamic_arena,
            binding, layer, expert,
            g_moe_tiering.snapshot_generation,
            DS4_GPU_ARENA_READY)) {
        return 0;
    }
    cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[binding.slot];
    *gate = slot.host_ptr;
    *up = slot.host_ptr + g_moe_expert_cache.gate_expert_bytes;
    *down = *up + g_moe_expert_cache.gate_expert_bytes;
    if (arena_slot_out) *arena_slot_out = binding.slot;
    return 1;
}

static int cuda_moe_tiering_ram_ptrs(
        uint32_t layer, uint32_t expert,
        char **gate, char **up, char **down,
        uint32_t *arena_slot_out = NULL) {
    if (layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        !gate || !up || !down) return 0;
    cuda_moe_tier_entry &entry =
        g_moe_tiering.entries[cuda_moe_tiering_entry_index(layer, expert)];
    if (entry.ram_slot >= g_dynamic_arena.slots.size()) return 0;
    cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[entry.ram_slot];
    if ((slot.state != DS4_GPU_ARENA_READY &&
         slot.state != DS4_GPU_ARENA_STAGED) ||
        slot.layer != layer || slot.expert != expert ||
        slot.content_generation != entry.ram_generation) {
        return 0;
    }
    *gate = slot.host_ptr;
    *up = slot.host_ptr + g_moe_expert_cache.gate_expert_bytes;
    *down = *up + g_moe_expert_cache.gate_expert_bytes;
    if (arena_slot_out) *arena_slot_out = entry.ram_slot;
    return 1;
}

/* ====================================================================== */
/* P.5a - ZERO-COPY EXPERT SERVICE (DS4_CUDA_EXPERT_ZEROCOPY)             */
/*                                                                        */
/* An expert that is already resident in the pinned PRIMARY arena does not */
/* need to be copied into a VRAM slot: under UVA the kernel can read it in */
/* place. The route publish then writes the three host addresses straight  */
/* into route_ptrs, and for that route the worker skips slot pick,         */
/* eviction, H2D, the copy publish and the LOADING->VALID transition.      */
/*                                                                        */
/* Modes (DS4_CUDA_EXPERT_ZEROCOPY, default 0):                            */
/*   0  OFF   - behaviour is exactly the pre-patch behaviour.              */
/*   1  ALL   - every RAM-resident miss inside the perimeter is served      */
/*              zero-copy. Isolates the cost of the delivery path.         */
/*   2  VALVE - only the FIRST touch of a (layer,expert) pair inside a      */
/*              decay window is served zero-copy; a repeat touch inside the */
/*              same window falls through to the normal slot+H2D path so    */
/*              the expert becomes resident. Isolates the anti-eviction     */
/*              effect: single-visit cold experts stop consuming slots and  */
/*              stop evicting hot ones, while genuinely reused experts      */
/*              still get promoted.                                        */
/*                                                                        */
/* DS4_CUDA_EXPERT_ZEROCOPY_WINDOW    valve decay window, in tokens (64).   */
/* DS4_CUDA_EXPERT_ZEROCOPY_LOG_EVERY route worker jobs between [zc] lines  */
/*                                    (256; 0 disables the periodic line).  */
/*                                                                        */
/* The counters below are maintained in EVERY mode, mode 0 included, so the */
/* control arm of the A/B emits the same row and the arms are comparable.   */
/* They are written only from the route worker thread and read without a    */
/* lock by the periodic and final printers, exactly like the existing       */
/* g_moe_tiering counters.                                                  */
/*                                                                        */
/* Honest note on the two timers, because attribution is the point of this  */
/* instrumentation:                                                        */
/*   t_deliver_ms      wall time inside the H2D submission calls. This is   */
/*                     ENQUEUE time; on an async stream the wire time lands */
/*                     in the drain, not here. In the zero-copy branch it   */
/*                     is zero by construction (no submission is made), and */
/*                     the PCIe reads move inside the compute kernel where  */
/*                     they are NOT separable without CUDA events - that is */
/*                     why zc reads are not timed here instead of being     */
/*                     invented.                                            */
/*   t_orchestration_ms pick_vram_slot + publish append/flush + the         */
/*                     reservation finish (stream drain + LOADING->VALID),  */
/*                     as mandated. Because the drain also absorbs the tail */
/*                     of the H2D transfer, t_drain_ms is reported          */
/*                     separately as a subset of it, so the transport tail  */
/*                     can be subtracted from the orchestration figure.     */
/* ====================================================================== */

enum cuda_moe_zerocopy_mode : int {
    CUDA_MOE_ZEROCOPY_OFF = 0,
    CUDA_MOE_ZEROCOPY_ALL = 1,
    CUDA_MOE_ZEROCOPY_VALVE = 2,
};

struct cuda_moe_zerocopy_state {
    int initialized;
    int mode;
    int caps_ok;
    int unified_addressing;
    int can_map_host_memory;
    int align_checked;
    int align_ok;
    uint32_t window_tokens;
    uint64_t log_every_jobs;

    /* service ledger */
    uint64_t zc_served;
    uint64_t zc_bytes;
    uint64_t h2d_served;
    uint64_t h2d_bytes;
    uint64_t ssd_served;
    uint64_t vram_hit;
    uint64_t routes_seen;
    uint64_t miss_seen;
    uint64_t requests_seen;

    /* explicit refusals - never a silent degrade */
    uint64_t rejected_pageable;
    uint64_t rejected_unaligned;
    uint64_t rejected_range;
    uint64_t rejected_backing;
    uint64_t rejected_wrap;
    uint64_t rejected_pipeline;
    uint64_t rejected_nested;

    /* valve / working-set observation */
    uint64_t first_touch;
    uint64_t promoted;
    uint64_t distinct_experts;
    uint64_t windows_closed;
    uint64_t tokens_observed;
    uint32_t window_token_cursor;
    uint32_t last_layer_index;
    std::vector<uint8_t> touch;

    /* the anti-eviction measurement */
    uint64_t evictions_caused_by_miss;

    /* timers, milliseconds, route worker thread */
    double t_deliver_ms;
    double t_orchestration_ms;
    double t_drain_ms;
};

static cuda_moe_zerocopy_state g_moe_zerocopy;

static inline double cuda_moe_zerocopy_now_ms(void) {
    return std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now().time_since_epoch()).count();
}

static uint64_t cuda_moe_zerocopy_parse_u64_env(
        const char *name, uint64_t fallback, uint64_t max_value) {
    const char *env = getenv(name);
    if (!env || !env[0]) return fallback;
    char *end = NULL;
    errno = 0;
    const unsigned long long value = strtoull(env, &end, 10);
    while (end && (*end == ' ' || *end == '\t')) end++;
    if (end == env || errno != 0 || !end || *end != '\0' ||
        (uint64_t)value > max_value) {
        fprintf(stderr,
                "ds4: invalid %s=%s; using %llu\n",
                name, env, (unsigned long long)fallback);
        return fallback;
    }
    return (uint64_t)value;
}

/* getenv and the device capability probe happen exactly once, guarded by the
 * initialized flag; the hot path only reads plain fields. */
static void cuda_moe_zerocopy_init(void) {
    cuda_moe_zerocopy_state &zc = g_moe_zerocopy;
    if (zc.initialized) return;
    zc.initialized = 1;
    zc.mode = CUDA_MOE_ZEROCOPY_OFF;
    zc.last_layer_index = UINT32_MAX;
    zc.window_tokens = (uint32_t)cuda_moe_zerocopy_parse_u64_env(
        "DS4_CUDA_EXPERT_ZEROCOPY_WINDOW", 64ull, 1000000ull);
    zc.log_every_jobs = cuda_moe_zerocopy_parse_u64_env(
        "DS4_CUDA_EXPERT_ZEROCOPY_LOG_EVERY", 256ull, 100000000ull);

    const char *env = getenv("DS4_CUDA_EXPERT_ZEROCOPY");
    int requested = CUDA_MOE_ZEROCOPY_OFF;
    if (env && env[0]) {
        if (strcmp(env, "1") == 0) {
            requested = CUDA_MOE_ZEROCOPY_ALL;
        } else if (strcmp(env, "2") == 0) {
            requested = CUDA_MOE_ZEROCOPY_VALVE;
        } else if (strcmp(env, "0") != 0) {
            fprintf(stderr,
                    "ds4: invalid DS4_CUDA_EXPERT_ZEROCOPY=%s; expected 0, 1 "
                    "or 2; zero-copy stays off\n",
                    env);
        }
    }

    int device = 0;
    cudaDeviceProp prop;
    memset(&prop, 0, sizeof(prop));
    if (cudaGetDevice(&device) == cudaSuccess &&
        cudaGetDeviceProperties(&prop, device) == cudaSuccess) {
        zc.unified_addressing = prop.unifiedAddressing ? 1 : 0;
        zc.can_map_host_memory = prop.canMapHostMemory ? 1 : 0;
    } else {
        (void)cudaGetLastError();
        zc.unified_addressing = 0;
        zc.can_map_host_memory = 0;
    }
    zc.caps_ok = zc.unified_addressing && zc.can_map_host_memory;

    try {
        zc.touch.assign((size_t)CUDA_MOE_LAYER_COUNT * 256u, 0u);
    } catch (...) {
        zc.touch.clear();
    }

    zc.mode = requested;
    if (zc.mode != CUDA_MOE_ZEROCOPY_OFF && !zc.caps_ok) {
        fprintf(stderr,
                "ds4: [zc] result=auto-disabled reason=device-caps "
                "requested=%d unifiedAddressing=%d canMapHostMemory=%d\n",
                requested, zc.unified_addressing, zc.can_map_host_memory);
        zc.mode = CUDA_MOE_ZEROCOPY_OFF;
    }
    if (zc.mode == CUDA_MOE_ZEROCOPY_VALVE && zc.touch.empty()) {
        fprintf(stderr,
                "ds4: [zc] result=auto-disabled reason=touch-table-allocation "
                "requested=%d\n",
                requested);
        zc.mode = CUDA_MOE_ZEROCOPY_OFF;
    }
    fprintf(stderr,
            "ds4: [zc] init requested=%d mode=%d window_tokens=%u "
            "log_every_jobs=%llu unifiedAddressing=%d canMapHostMemory=%d "
            "touch_table_bytes=%llu\n",
            requested, zc.mode, zc.window_tokens,
            (unsigned long long)zc.log_every_jobs,
            zc.unified_addressing, zc.can_map_host_memory,
            (unsigned long long)zc.touch.size());
}

/* One call per route request, before the request is served. Detects the token
 * boundary from the layer index going backwards, which costs one compare and
 * needs no new plumbing through the mailbox. */
static void cuda_moe_zerocopy_note_request(
        uint32_t layer_index, uint32_t route_count,
        uint32_t hit_count, uint32_t miss_count) {
    cuda_moe_zerocopy_state &zc = g_moe_zerocopy;
    if (!zc.initialized) cuda_moe_zerocopy_init();
    zc.requests_seen++;
    zc.routes_seen += route_count;
    zc.vram_hit += hit_count;
    zc.miss_seen += miss_count;
    if (zc.last_layer_index != UINT32_MAX &&
        layer_index < zc.last_layer_index) {
        zc.tokens_observed++;
        zc.window_token_cursor++;
        if (zc.window_tokens != 0u &&
            zc.window_token_cursor >= zc.window_tokens) {
            zc.window_token_cursor = 0u;
            zc.windows_closed++;
            if (!zc.touch.empty()) {
                memset(zc.touch.data(), 0, zc.touch.size());
            }
        }
    }
    zc.last_layer_index = layer_index;
}

/* Returns 1 on the first touch of this (layer,expert) inside the window.
 * Maintained in every mode so distinct_experts is comparable across arms. */
static int cuda_moe_zerocopy_touch(uint32_t layer, uint32_t expert) {
    cuda_moe_zerocopy_state &zc = g_moe_zerocopy;
    const size_t index = (size_t)layer * 256u + (size_t)expert;
    if (index >= zc.touch.size()) return 1;
    uint8_t &counter = zc.touch[index];
    if (counter == 0u) {
        counter = 1u;
        zc.distinct_experts++;
        return 1;
    }
    if (counter < 255u) counter++;
    return 0;
}

/* Z2/Z3 guards. Every refusal is counted; the branch never serves bytes it
 * has not verified and never degrades silently. */
static int cuda_moe_zerocopy_pointers_admissible(
        const char *host_gate, const char *host_up, const char *host_down,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        uint32_t arena_slot) {
    cuda_moe_zerocopy_state &zc = g_moe_zerocopy;
    if (g_dynamic_arena.backing != CUDA_DYNAMIC_ARENA_BACKING_PRIMARY ||
        !g_dynamic_arena.host_base ||
        g_dynamic_arena.allocated_bytes == 0ull) {
        zc.rejected_backing++;
        return 0;
    }
    /* Z2a: the VirtualAlloc overflow region is not device addressable. */
    if (arena_slot >= g_dynamic_arena.slots.size() ||
        g_dynamic_arena.slots[arena_slot].pageable != 0u) {
        zc.rejected_pageable++;
        return 0;
    }
    /* Z2b: the three spans must sit inside the pinned primary allocation and
     * be the contiguous gate||up||down triple the arena promises. */
    const char *base = g_dynamic_arena.host_base;
    const char *end = base + g_dynamic_arena.allocated_bytes;
    if (!host_gate || !host_up || !host_down ||
        host_up != host_gate + gate_expert_bytes ||
        host_down != host_up + gate_expert_bytes ||
        host_gate < base || host_gate >= end ||
        host_down + down_expert_bytes > end) {
        zc.rejected_range++;
        return 0;
    }
    /* Z3: one-time alignment contract. gate_expert_bytes drives up/down, and
     * slot_bytes drives every other slot base, so checking the first observed
     * triple plus the two strides settles it for the whole arena. */
    if (!zc.align_checked) {
        zc.align_checked = 1;
        zc.align_ok =
            (gate_expert_bytes % 16ull) == 0ull &&
            (g_dynamic_arena.slot_bytes % 16ull) == 0ull &&
            ((uintptr_t)host_gate % 16u) == 0u &&
            ((uintptr_t)base % 16u) == 0u;
        fprintf(stderr,
                "ds4: [zc] align check gate_expert_bytes=%llu "
                "down_expert_bytes=%llu slot_bytes=%llu host_gate_mod16=%u "
                "host_base_mod16=%u result=%s\n",
                (unsigned long long)gate_expert_bytes,
                (unsigned long long)down_expert_bytes,
                (unsigned long long)g_dynamic_arena.slot_bytes,
                (unsigned)((uintptr_t)host_gate % 16u),
                (unsigned)((uintptr_t)base % 16u),
                zc.align_ok ? "ok" : "refused");
    }
    if (!zc.align_ok) {
        zc.rejected_unaligned++;
        return 0;
    }
    return 1;
}

static void cuda_moe_zerocopy_report(const char *tag) {
    cuda_moe_zerocopy_state &zc = g_moe_zerocopy;
    if (!zc.initialized) return;
    const uint64_t lookups = zc.routes_seen;
    const double hit_rate = lookups
        ? (double)zc.vram_hit / (double)lookups : 0.0;
    const double tokens = zc.tokens_observed ? (double)zc.tokens_observed : 0.0;
    fprintf(stderr,
            "ds4: [zc] %s mode=%d window_tokens=%u tokens=%llu requests=%llu "
            "zc_served=%llu zc_bytes=%llu vram_hit=%llu h2d_served=%llu "
            "h2d_bytes=%llu ssd_served=%llu routes=%llu misses=%llu "
            "hit_rate=%.6f hit_per_token=%.3f miss_per_token=%.3f "
            "zc_per_token=%.3f h2d_per_token=%.3f "
            "zc_rejected_pageable=%llu zc_rejected_unaligned=%llu "
            "zc_rejected_range=%llu zc_rejected_backing=%llu "
            "zc_rejected_wrap=%llu zc_rejected_pipeline=%llu "
            "zc_rejected_nested=%llu zc_first_touch=%llu zc_promoted=%llu "
            "distinct_experts=%llu windows=%llu distinct_per_token=%.3f "
            "evictions_caused_by_miss=%llu evictions_per_token=%.3f "
            "t_deliver_ms=%.3f t_orchestration_ms=%.3f t_drain_ms=%.3f "
            "transient_timeout_fallbacks=%llu transient_timeout_aborts=%llu\n",
            tag ? tag : "periodic", zc.mode, zc.window_tokens,
            (unsigned long long)zc.tokens_observed,
            (unsigned long long)zc.requests_seen,
            (unsigned long long)zc.zc_served,
            (unsigned long long)zc.zc_bytes,
            (unsigned long long)zc.vram_hit,
            (unsigned long long)zc.h2d_served,
            (unsigned long long)zc.h2d_bytes,
            (unsigned long long)zc.ssd_served,
            (unsigned long long)zc.routes_seen,
            (unsigned long long)zc.miss_seen,
            hit_rate,
            tokens ? (double)zc.vram_hit / tokens : 0.0,
            tokens ? (double)zc.miss_seen / tokens : 0.0,
            tokens ? (double)zc.zc_served / tokens : 0.0,
            tokens ? (double)zc.h2d_served / tokens : 0.0,
            (unsigned long long)zc.rejected_pageable,
            (unsigned long long)zc.rejected_unaligned,
            (unsigned long long)zc.rejected_range,
            (unsigned long long)zc.rejected_backing,
            (unsigned long long)zc.rejected_wrap,
            (unsigned long long)zc.rejected_pipeline,
            (unsigned long long)zc.rejected_nested,
            (unsigned long long)zc.first_touch,
            (unsigned long long)zc.promoted,
            (unsigned long long)zc.distinct_experts,
            (unsigned long long)zc.windows_closed,
            tokens ? (double)zc.distinct_experts / tokens : 0.0,
            (unsigned long long)zc.evictions_caused_by_miss,
            tokens ? (double)zc.evictions_caused_by_miss / tokens : 0.0,
            zc.t_deliver_ms, zc.t_orchestration_ms, zc.t_drain_ms,
            (unsigned long long)g_transient_timeout_fallbacks.load(
                std::memory_order_relaxed),
            (unsigned long long)g_transient_timeout_aborts.load(
                std::memory_order_relaxed));
}

/* =======================================================================
 * FIX-B interventi 2 e 3 - osservatore per-token.
 *
 * Vive sul thread che genera il token (lo stesso che esegue il decode), e'
 * pilotato da ds4_server.c e con entrambi i flag spenti costa una sola
 * lettura di due int cachati per token.
 *
 * worker_wait_ms viene da route_ready_wait_seconds, l'attesa che il thread di
 * decode passa fermo sul route worker; e' scritto dallo stesso thread che
 * legge qui, quindi non c'e' corsa.  transient_serves (ssd_served) ed
 * evict_backbone sono contatori diagnostici scritti dal route worker: la
 * lettura e' volutamente non sincronizzata, come le altre righe di stato.
 * ======================================================================= */
struct cuda_token_watch_state {
    int active;
    uint64_t token_index;
    double started;
    double worker_wait_seconds;
    uint64_t pread_calls;
    uint64_t pread_bytes;
    uint64_t transient_serves;
    uint64_t evict_backbone;
    uint64_t tokens_seen;
    uint64_t next_vram_log;
};
static cuda_token_watch_state g_token_watch;

static int cuda_token_watch_requested(void) {
    return cuda_slow_token_log_requested() ||
        cuda_vram_prio_log_every_tokens() != 0ull ||
        ds4_vram_peak_probe_enabled();
}

extern "C" void ds4_gpu_token_watch_begin(uint64_t token_index) {
    /* WORKER-PROF: marcatore indipendente, prima dell'early return, cosi' il
     * profilo del route worker non eredita il gating degli altri osservatori
     * per-token e non ne arma nessuno (il probe del picco VRAM resta spento). */
    ds4_workerprof_token_begin();
    if (!cuda_token_watch_requested()) return;
    /* Arma la finestra del probe del picco: da qui fino a token_watch_end ogni
     * alloc/free di device campiona la VRAM libera. */
    ds4_vram_peak_token_begin(token_index);
    g_token_watch.active = 1;
    g_token_watch.token_index = token_index;
    g_token_watch.started = cuda_wall_sec();
    g_token_watch.worker_wait_seconds =
        g_moe_expert_cache.route_ready_wait_seconds;
    g_token_watch.pread_calls =
        g_transient_pread_calls.load(std::memory_order_relaxed);
    g_token_watch.pread_bytes =
        g_transient_pread_bytes.load(std::memory_order_relaxed);
    g_token_watch.transient_serves = g_moe_zerocopy.ssd_served;
    g_token_watch.evict_backbone = g_vram_prio_evict_backbone;
}

extern "C" void ds4_gpu_token_watch_end(
        uint64_t token_index, uint32_t token_count) {
    ds4_workerprof_token_end(token_count);
    ds4_transport_token_end(token_count);
    if (!g_token_watch.active) return;
    g_token_watch.active = 0;
    /* Disarma sempre (anche con token_count==0) ed emette la riga [vram-peak]
     * periodica.  Precede la riga [slow-token] cosi' i due osservatori dello
     * stesso token restano adiacenti nel log. */
    ds4_vram_peak_token_end(token_index, token_count);
    if (token_count == 0u) return;
    const double total_ms =
        (cuda_wall_sec() - g_token_watch.started) * 1000.0;
    if (cuda_slow_token_log_requested() &&
        total_ms > cuda_slow_token_threshold_ms()) {
        const double worker_wait_ms =
            (g_moe_expert_cache.route_ready_wait_seconds -
             g_token_watch.worker_wait_seconds) * 1000.0;
        const uint64_t pread_calls =
            g_transient_pread_calls.load(std::memory_order_relaxed) -
            g_token_watch.pread_calls;
        const uint64_t pread_bytes =
            g_transient_pread_bytes.load(std::memory_order_relaxed) -
            g_token_watch.pread_bytes;
        const uint64_t transient_serves =
            g_moe_zerocopy.ssd_served - g_token_watch.transient_serves;
        const uint64_t evict_backbone_delta =
            g_vram_prio_evict_backbone - g_token_watch.evict_backbone;
        fprintf(stderr,
                "ds4: [slow-token] pos=%llu total_ms=%.3f worker_wait_ms=%.3f "
                "pread_calls=%llu pread_bytes=%llu transient_serves=%llu "
                "evict_backbone_delta=%llu tokens_in_step=%u\n",
                (unsigned long long)token_index, total_ms, worker_wait_ms,
                (unsigned long long)pread_calls,
                (unsigned long long)pread_bytes,
                (unsigned long long)transient_serves,
                (unsigned long long)evict_backbone_delta,
                token_count);
    }
    const uint64_t every = cuda_vram_prio_log_every_tokens();
    if (every == 0ull) return;
    g_token_watch.tokens_seen += token_count;
    if (g_token_watch.next_vram_log == 0ull) {
        g_token_watch.next_vram_log = every;
    }
    if (g_token_watch.tokens_seen >= g_token_watch.next_vram_log) {
        g_token_watch.next_vram_log = g_token_watch.tokens_seen + every;
        /* Stesso schema del [zc] periodico: si riusa l'emettitore che gia'
         * esiste, cosi' la riga e' campo-per-campo la stessa dei due punti
         * fissi decode-start e request-end. */
        cuda_vram_prio_log("periodic");
    }
}

static int cuda_moe_tiering_has_exact_vram(
        uint32_t layer, uint32_t expert) {
    if (layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        g_moe_expert_cache.host_slot_by_layer_expert.empty()) {
        return 0;
    }
    const uint32_t map_index = layer * 256u + expert;
    if (map_index >= g_moe_expert_cache.host_slot_by_layer_expert.size()) {
        return 0;
    }
    const int32_t slot_i =
        g_moe_expert_cache.host_slot_by_layer_expert[map_index];
    if (slot_i < 0 || (uint32_t)slot_i >= g_moe_expert_cache.slots.size()) {
        return 0;
    }
    const cuda_moe_cache_slot &slot =
        g_moe_expert_cache.slots[(uint32_t)slot_i];
    return slot.state == CUDA_MOE_CACHE_VALID &&
        slot.layer_index == layer &&
        slot.expert_id == expert;
}

static int cuda_moe_tiering_pick_ram_slot(
        uint32_t current_layer, uint32_t current_expert,
        size_t *victim_entry_out, const ds4_gpu_g133_epoch &g133_epoch,
        int preferred_pageable = -1, int strict_storage = 0) {
    if (!victim_entry_out) return -1;
    *victim_entry_out = SIZE_MAX;
    const int open_router_pool_active =
        g_moe_tiering.compose_prefill_mass_tiering &&
        g_moe_tiering.compose_router_open &&
        g_moe_tiering.open_router_reserve_slots > 0u;
    const auto slot_allowed = [open_router_pool_active](uint32_t slot) -> bool {
        if (!open_router_pool_active) return true;
        return slot < g_moe_tiering.open_router_pool_slot.size() &&
            g_moe_tiering.open_router_pool_slot[slot] != 0u;
    };
    cuda_moe_tier_entry &candidate = g_moe_tiering.entries[
        cuda_moe_tiering_entry_index(current_layer, current_expert)];
    const double candidate_score = g_moe_tiering.g133_enabled
        ? cuda_g133_decayed_heat(candidate, g133_epoch) : 0.0;
    const uint32_t storage_passes =
        preferred_pageable < 0 || strict_storage ? 1u : 2u;
    for (uint32_t pass = 0; pass < storage_passes; pass++) {
        for (uint32_t slot = 0; slot < g_dynamic_arena.slots.size(); slot++) {
            if (!slot_allowed(slot)) continue;
            if (cuda_q1_0_ssd_wrap_slot_reserved(slot)) continue;
            cuda_dynamic_arena_slot &arena_slot =
                g_dynamic_arena.slots[slot];
            if (arena_slot.state != DS4_GPU_ARENA_FREE ||
                cuda_dynamic_arena_slot_refs_load(
                    &arena_slot.cpu_lane_slot_refs) != 0u) {
                continue;
            }
            if (pass == 0u && preferred_pageable >= 0 &&
                (int)arena_slot.pageable != preferred_pageable) {
                continue;
            }
            if (cuda_dynamic_arena_slot_writer_try_acquire(&arena_slot)) {
                return (int)slot;
            }
        }
    }
    for (uint32_t pass = 0; pass < storage_passes; pass++) {
        int after_writer_cas_loss = 0;
        double lost_score = 0.0;
        size_t lost_entry = 0;
        for (;;) {
            int best_slot = -1;
            size_t best_entry = 0;
            double best_score = 1.0e300;
            for (size_t index = 0; index < g_moe_tiering.entries.size(); index++) {
                cuda_moe_tier_entry &entry = g_moe_tiering.entries[index];
                const uint32_t entry_layer = (uint32_t)(index / 256u);
                const uint32_t entry_expert = (uint32_t)(index % 256u);
                const int reclaimable_vram_backing =
                    entry.state == CUDA_MOE_TIER_VRAM_PROTECTED &&
                    cuda_moe_tiering_has_exact_vram(entry_layer, entry_expert);
                if (entry.ram_slot >= g_dynamic_arena.slots.size() ||
                    !slot_allowed(entry.ram_slot) ||
                    cuda_q1_0_ssd_wrap_slot_reserved(entry.ram_slot) ||
                    cuda_dynamic_arena_slot_refs_load(
                        &g_dynamic_arena.slots[entry.ram_slot].
                            cpu_lane_slot_refs) != 0u ||
                    (pass == 0u && preferred_pageable >= 0 &&
                     (int)g_dynamic_arena.slots[entry.ram_slot].pageable !=
                         preferred_pageable) ||
                    (entry.state == CUDA_MOE_TIER_VRAM_PROTECTED &&
                     !reclaimable_vram_backing) ||
                    entry.last_call == g_moe_tiering.call_tick ||
                    index == cuda_moe_tiering_entry_index(
                        current_layer, current_expert)) {
                    continue;
                }
                if (g_moe_tiering.g133_enabled &&
                    !cuda_g133_ram_demotion_eligible(entry, g133_epoch)) {
                    continue;
                }
                const double score = g_moe_tiering.g133_enabled
                    ? cuda_g133_decayed_heat(entry, g133_epoch)
                    : cuda_moe_tiering_lfru(entry, g_moe_tiering.call_tick);
                if (g_moe_tiering.g133_enabled &&
                    candidate_score <=
                        score + g_moe_tiering.g133_demotion_margin) {
                    continue;
                }
                /* A failed writer CAS removes only that ranked victim from
                 * this attempt; continue with the next eligible score. */
                if (after_writer_cas_loss &&
                    (score < lost_score ||
                     (score == lost_score && index <= lost_entry))) {
                    continue;
                }
                if (score < best_score ||
                    (score == best_score && index < best_entry)) {
                    best_score = score;
                    best_slot = (int)entry.ram_slot;
                    best_entry = index;
                }
            }
            if (best_slot < 0) break;
            cuda_dynamic_arena_slot &arena_slot =
                g_dynamic_arena.slots[(uint32_t)best_slot];
            if (cuda_dynamic_arena_slot_writer_try_acquire(&arena_slot)) {
                *victim_entry_out = best_entry;
                return best_slot;
            }
            after_writer_cas_loss = 1;
            lost_score = best_score;
            lost_entry = best_entry;
        }
    }
    return -1;
}

/* Opt-in SSD -> RAM selector. The legacy selector above remains the complete
 * default path. This copy adds the missing merit comparison at a full arena. */
static int cuda_moe_tiering_pick_ram_slot_admit(
        uint32_t current_layer, uint32_t current_expert,
        size_t *victim_entry_out, const ds4_gpu_g133_epoch &g133_epoch,
        int preferred_pageable = -1, int strict_storage = 0) {
    if (!victim_entry_out) return -1;
    *victim_entry_out = SIZE_MAX;
    const int open_router_pool_active =
        g_moe_tiering.compose_prefill_mass_tiering &&
        g_moe_tiering.compose_router_open &&
        g_moe_tiering.open_router_reserve_slots > 0u;
    const auto slot_allowed = [open_router_pool_active](uint32_t slot) -> bool {
        if (!open_router_pool_active) return true;
        return slot < g_moe_tiering.open_router_pool_slot.size() &&
            g_moe_tiering.open_router_pool_slot[slot] != 0u;
    };
    cuda_moe_tier_entry &candidate = g_moe_tiering.entries[
        cuda_moe_tiering_entry_index(current_layer, current_expert)];
    const double candidate_score = g_moe_tiering.g133_enabled
        ? cuda_g133_decayed_heat(candidate, g133_epoch)
        : cuda_moe_tiering_lfru(candidate, g_moe_tiering.call_tick);
    const uint32_t storage_passes =
        preferred_pageable < 0 || strict_storage ? 1u : 2u;
    for (uint32_t pass = 0; pass < storage_passes; pass++) {
        for (uint32_t slot = 0; slot < g_dynamic_arena.slots.size(); slot++) {
            if (!slot_allowed(slot)) continue;
            if (cuda_q1_0_ssd_wrap_slot_reserved(slot)) continue;
            cuda_dynamic_arena_slot &arena_slot =
                g_dynamic_arena.slots[slot];
            if (arena_slot.state != DS4_GPU_ARENA_FREE ||
                cuda_dynamic_arena_slot_refs_load(
                    &arena_slot.cpu_lane_slot_refs) != 0u) {
                continue;
            }
            if (pass == 0u && preferred_pageable >= 0 &&
                (int)arena_slot.pageable != preferred_pageable) {
                continue;
            }
            if (cuda_dynamic_arena_slot_writer_try_acquire(&arena_slot)) {
                return (int)slot;
            }
        }
    }
    for (uint32_t pass = 0; pass < storage_passes; pass++) {
        int after_writer_cas_loss = 0;
        double lost_score = 0.0;
        size_t lost_entry = 0;
        for (;;) {
            int best_slot = -1;
            size_t best_entry = 0;
            double best_score = 1.0e300;
            for (size_t index = 0; index < g_moe_tiering.entries.size();
                 index++) {
                cuda_moe_tier_entry &entry = g_moe_tiering.entries[index];
                const uint32_t entry_layer = (uint32_t)(index / 256u);
                const uint32_t entry_expert = (uint32_t)(index % 256u);
                const int reclaimable_vram_backing =
                    entry.state == CUDA_MOE_TIER_VRAM_PROTECTED &&
                    cuda_moe_tiering_has_exact_vram(
                        entry_layer, entry_expert);
                if (entry.ram_slot >= g_dynamic_arena.slots.size() ||
                    !slot_allowed(entry.ram_slot) ||
                    cuda_q1_0_ssd_wrap_slot_reserved(entry.ram_slot) ||
                    cuda_dynamic_arena_slot_refs_load(
                        &g_dynamic_arena.slots[entry.ram_slot].
                            cpu_lane_slot_refs) != 0u ||
                    (pass == 0u && preferred_pageable >= 0 &&
                     (int)g_dynamic_arena.slots[entry.ram_slot].pageable !=
                         preferred_pageable) ||
                    (entry.state == CUDA_MOE_TIER_VRAM_PROTECTED &&
                     !reclaimable_vram_backing) ||
                    entry.last_call == g_moe_tiering.call_tick ||
                    index == cuda_moe_tiering_entry_index(
                        current_layer, current_expert)) {
                    continue;
                }
                if (g_moe_tiering.g133_enabled &&
                    !cuda_g133_ram_demotion_eligible(entry, g133_epoch)) {
                    continue;
                }
                const double score = g_moe_tiering.g133_enabled
                    ? cuda_g133_decayed_heat(entry, g133_epoch)
                    : cuda_moe_tiering_lfru(
                        entry, g_moe_tiering.call_tick);
                if (g_moe_tiering.g133_enabled) {
                    if (candidate_score <=
                            score + g_moe_tiering.g133_demotion_margin) {
                        continue;
                    }
                } else if (candidate_score <= score) {
                    continue;
                }
                if (after_writer_cas_loss &&
                    (score < lost_score ||
                     (score == lost_score && index <= lost_entry))) {
                    continue;
                }
                if (score < best_score ||
                    (score == best_score && index < best_entry)) {
                    best_score = score;
                    best_slot = (int)entry.ram_slot;
                    best_entry = index;
                }
            }
            if (best_slot < 0) break;
            cuda_dynamic_arena_slot &arena_slot =
                g_dynamic_arena.slots[(uint32_t)best_slot];
            if (cuda_dynamic_arena_slot_writer_try_acquire(&arena_slot)) {
                *victim_entry_out = best_entry;
                return best_slot;
            }
            after_writer_cas_loss = 1;
            lost_score = best_score;
            lost_entry = best_entry;
        }
    }
    return -1;
}

