static cuda_q1_0_ssd_wrap_state g_q1_0_ssd_wrap;

static int cuda_q1_0_ssd_wrap_tier_reset_begin(void) {
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    if (!state.mutex_ready) {
        cuda_moe_tiering_clear_owned_slots();
        return 1;
    }
    os_mutex_lock(&state.mutex);
    uint32_t committing = 0u;
    for (const cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        if (job.state == CUDA_Q1_0_SSD_WRAP_RAM_COMMITTING) committing++;
    }
    std::vector<cuda_moe_tier_entry> *retained_entries = NULL;
    if (committing != 0u) {
        retained_entries = new (std::nothrow)
            std::vector<cuda_moe_tier_entry>();
        if (!retained_entries) {
            os_mutex_unlock(&state.mutex);
            fprintf(stderr,
                    "ds4: [q1-0-ssd-wrap] tier reset deferred: unable to "
                    "retain entries for %u committing publisher(s)\n",
                    committing);
            return 0;
        }
    }
    state.tier_generation++;
    if (state.tier_generation == 0u) state.tier_generation++;
    if (committing != 0u) {
        for (cuda_q1_0_ssd_wrap_job &job : state.jobs) {
            if (job.state != CUDA_Q1_0_SSD_WRAP_RAM_COMMITTING) continue;
            job.commit_safe_leaked = 1u;
        }
        state.commit_safe_leaked = 1;
        g_cuda_dynamic_arena_storage_safe_leaked = 1;
    }
    cuda_moe_tiering_clear_owned_slots();
    if (retained_entries) {
        /* A timed-out publisher may have captured an entry address before its
         * generation check. Move that allocation out of the reset object and
         * deliberately leak it until process exit; freeing it is never safe. */
        retained_entries->swap(g_moe_tiering.entries);
        fprintf(stderr,
                "ds4: [q1-0-ssd-wrap] retained tier entries permanently "
                "for %u generation-invalidated publisher(s)\n",
                committing);
    }
    os_mutex_unlock(&state.mutex);
    return 1;
}

static const char *cuda_q1_0_ssd_wrap_state_name(
        cuda_q1_0_ssd_wrap_job_state state) {
    switch (state) {
    case CUDA_Q1_0_SSD_WRAP_REQUESTED:      return "REQUESTED";
    case CUDA_Q1_0_SSD_WRAP_SSD_INFLIGHT:  return "SSD_INFLIGHT";
    case CUDA_Q1_0_SSD_WRAP_RAM_READY:     return "RAM_READY";
    case CUDA_Q1_0_SSD_WRAP_RAM_COMMITTING:return "RAM_COMMITTING";
    case CUDA_Q1_0_SSD_WRAP_FAILED:         return "FAILED";
    case CUDA_Q1_0_SSD_WRAP_DEAD:           return "DEAD";
    default:                                return "FREE";
    }
}

static int cuda_q1_0_ssd_wrap_sha_env_valid(const char *name) {
    const char *value = getenv(name);
    if (!value || strlen(value) != 64u) return 0;
    for (uint32_t i = 0; i < 64u; i++) {
        const char c = value[i];
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') ||
              (c >= 'A' && c <= 'F'))) {
            return 0;
        }
    }
    return 1;
}

static uint64_t cuda_q1_0_ssd_wrap_queue_depth_locked(void) {
    uint64_t depth = 0;
    for (const cuda_q1_0_ssd_wrap_job &job : g_q1_0_ssd_wrap.jobs) {
        if (job.state != CUDA_Q1_0_SSD_WRAP_FREE) depth++;
    }
    return depth;
}

static void cuda_q1_0_ssd_wrap_working_set_sample(const char *phase) {
    if (!g_q1_0_ssd_wrap.enabled) return;
#ifdef _WIN32
    SYSTEM_INFO system_info;
    GetSystemInfo(&system_info);
    const uint64_t page_size = system_info.dwPageSize;
    if (page_size == 0) return;
    const uint64_t pages =
        (g_dynamic_arena.pageable_bytes + page_size - 1u) / page_size;
    if (pages != 0u && !g_dynamic_arena.pageable_base) {
        fprintf(stderr,
                "ds4: [q1-0-ssd-wrap-working-set] result=failed "
                "reason=pageable-base phase=%s\n",
                phase ? phase : "unknown");
        cuda_q1_0_ssd_wrap_disable("working-set-pageable-base");
        return;
    }
    const uint32_t batch_capacity = 16384u;
    std::vector<PSAPI_WORKING_SET_EX_INFORMATION> batch;
    try {
        batch.resize((size_t)std::min<uint64_t>(pages, batch_capacity));
    } catch (...) {
        fprintf(stderr,
                "ds4: [q1-0-ssd-wrap-working-set] result=failed "
                "reason=allocation phase=%s\n", phase ? phase : "unknown");
        cuda_q1_0_ssd_wrap_disable("working-set-allocation");
        return;
    }
    uint64_t resident_pages = 0;
    uint64_t shared_pages = 0;
    uint64_t locked_pages = 0;
    uint64_t queried_pages = 0;
    for (uint64_t cursor = 0; cursor < pages;) {
        const uint32_t count = (uint32_t)std::min<uint64_t>(
            pages - cursor, batch.size());
        for (uint32_t i = 0; i < count; i++) {
            memset(&batch[i], 0, sizeof(batch[i]));
            batch[i].VirtualAddress = g_dynamic_arena.pageable_base +
                (cursor + i) * page_size;
        }
        if (!QueryWorkingSetEx(
                GetCurrentProcess(), batch.data(),
                (DWORD)((size_t)count * sizeof(batch[0])))) {
            fprintf(stderr,
                    "ds4: [q1-0-ssd-wrap-working-set] result=failed "
                    "reason=query phase=%s error=%lu\n",
                    phase ? phase : "unknown", (unsigned long)GetLastError());
            cuda_q1_0_ssd_wrap_disable("working-set-query");
            return;
        }
        for (uint32_t i = 0; i < count; i++) {
            const PSAPI_WORKING_SET_EX_BLOCK attributes =
                batch[i].VirtualAttributes;
            resident_pages += attributes.Valid ? 1u : 0u;
            shared_pages += attributes.Valid && attributes.Shared ? 1u : 0u;
            locked_pages += attributes.Valid && attributes.Locked ? 1u : 0u;
        }
        queried_pages += count;
        cursor += count;
    }
    PROCESS_MEMORY_COUNTERS_EX counters;
    memset(&counters, 0, sizeof(counters));
    counters.cb = sizeof(counters);
    const int process_memory_ok = GetProcessMemoryInfo(
        GetCurrentProcess(), (PROCESS_MEMORY_COUNTERS *)&counters,
        sizeof(counters)) ? 1 : 0;
    fprintf(stderr,
            "ds4: [q1-0-ssd-wrap-working-set] result=sample phase=%s "
            "page_size=%llu pages=%llu queried_pages=%llu "
            "resident_pages=%llu resident_bytes=%llu paged_out_pages=%llu "
            "paged_out_bytes=%llu shared_pages=%llu shared_bytes=%llu "
            "locked_pages=%llu locked_bytes=%llu page_fault_count=%llu "
            "hard_fault_source=external-sampler\n",
            phase ? phase : "unknown", (unsigned long long)page_size,
            (unsigned long long)pages, (unsigned long long)queried_pages,
            (unsigned long long)resident_pages,
            (unsigned long long)(resident_pages * page_size),
            (unsigned long long)(pages - resident_pages),
            (unsigned long long)((pages - resident_pages) * page_size),
            (unsigned long long)shared_pages,
            (unsigned long long)(shared_pages * page_size),
            (unsigned long long)locked_pages,
            (unsigned long long)(locked_pages * page_size),
            (unsigned long long)(process_memory_ok ? counters.PageFaultCount : 0u));
#else
    fprintf(stderr,
            "ds4: [q1-0-ssd-wrap-working-set] result=unsupported "
            "phase=%s platform=non-windows\n", phase ? phase : "unknown");
#endif
}

struct cuda_q1_0_ssd_wrap_part {
    uint64_t source_offset;
    uint64_t bytes;
    char *destination;
};

struct cuda_q1_0_ssd_wrap_read_result {
    cuda_q1_0_ssd_wrap_io_status status;
    uint32_t ranges_read;
    uint32_t coalesced;
    uint32_t failure_range;
    uint64_t expected_bytes;
    int64_t actual_bytes;
    int os_error;
};

static const char *cuda_q1_0_ssd_wrap_io_status_name(
        cuda_q1_0_ssd_wrap_io_status status) {
    switch (status) {
        case CUDA_Q1_0_SSD_WRAP_IO_OK: return "ok";
        case CUDA_Q1_0_SSD_WRAP_IO_CONTRACT: return "contract";
        case CUDA_Q1_0_SSD_WRAP_IO_DEADLINE: return "deadline-before-range";
        case CUDA_Q1_0_SSD_WRAP_IO_TIMEOUT: return "timeout";
        case CUDA_Q1_0_SSD_WRAP_IO_CANCELLED: return "cancelled";
        case CUDA_Q1_0_SSD_WRAP_IO_PREAD: return "pread-error";
        case CUDA_Q1_0_SSD_WRAP_IO_SHORT_READ: return "short-read";
        default: return "none";
    }
}

struct cuda_q1_0_ssd_wrap_service_timing {
    double queue_age_seconds;
    double service_budget_seconds;
    double service_deadline;
    double io_deadline;
};

static cuda_q1_0_ssd_wrap_service_timing
cuda_q1_0_ssd_wrap_service_timing_for_job(
        const cuda_q1_0_ssd_wrap_job &job, double io_started) {
    cuda_q1_0_ssd_wrap_service_timing timing = {};
    timing.queue_age_seconds = std::max(
        0.0, io_started - job.queued_at);
    timing.service_budget_seconds = std::min(
        cuda_g133_rotator_io_timeout_seconds(),
        cuda_g133_transient_io_timeout_seconds());
    timing.service_deadline = io_started + timing.service_budget_seconds;
    timing.io_deadline =
        !job.g73_open_rotation && job.request.absolute_deadline > 0.0
            ? std::min(
                timing.service_deadline, job.request.absolute_deadline)
            : timing.service_deadline;
    return timing;
}

static cuda_q1_0_ssd_wrap_read_result cuda_q1_0_ssd_wrap_read_job(
        cuda_q1_0_ssd_wrap_job *job, double absolute_deadline) {
    cuda_q1_0_ssd_wrap_read_result result = {};
    result.status = CUDA_Q1_0_SSD_WRAP_IO_CONTRACT;
    result.failure_range = UINT32_MAX;
    result.actual_bytes = -1;
    if (!job || !job->read_base ||
        job->record.destination_bytes != g_dynamic_arena.slot_bytes) {
        return result;
    }
    const int transport_repeat =
        ds4_transport_file_load_begin(job->layer, job->expert);
    cuda_q1_0_ssd_wrap_part parts[3] = {
        {job->record.destination_gate_offset,
         job->record.destination_gate_bytes, job->read_base},
        {job->record.destination_up_offset,
         job->record.destination_up_bytes,
         job->read_base + job->record.destination_gate_bytes},
        {job->record.destination_down_offset,
         job->record.destination_down_bytes,
         job->read_base + job->record.destination_gate_bytes +
             job->record.destination_up_bytes},
    };
    std::sort(parts, parts + 3,
              [](const cuda_q1_0_ssd_wrap_part &a,
                 const cuda_q1_0_ssd_wrap_part &b) {
                  return a.source_offset < b.source_offset;
              });
    for (uint32_t i = 0; i < 3u;) {
        uint64_t source = parts[i].source_offset;
        uint64_t bytes = parts[i].bytes;
        char *destination = parts[i].destination;
        uint32_t next = i + 1u;
        while (next < 3u && source <= UINT64_MAX - bytes &&
               destination + bytes == parts[next].destination &&
               source + bytes == parts[next].source_offset &&
               bytes <= UINT64_MAX - parts[next].bytes) {
            bytes += parts[next].bytes;
            result.coalesced++;
            next++;
        }
        const uint32_t remaining_ms =
            cuda_deadline_remaining_ms(absolute_deadline);
        if (remaining_ms == 0u) {
            ds4_transport_mark_incomplete();
            result.status = CUDA_Q1_0_SSD_WRAP_IO_DEADLINE;
            result.failure_range = i;
            result.expected_bytes = bytes;
            result.actual_bytes = 0;
            result.os_error = ETIMEDOUT;
            return result;
        }
        errno = 0;
        const int64_t got = os_pread_cancellable_timeout(
            &g_q1_0_ssd_wrap.file, destination, bytes, source,
            &g_q1_0_ssd_wrap.pread, job->io_sequence, remaining_ms);
        const int read_errno = errno;
        if (got > 0) {
            ds4_transport_record_file_bytes(
                transport_repeat, (uint64_t)got);
        }
        if (got < 0) {
            ds4_transport_mark_incomplete();
            result.status = read_errno == ETIMEDOUT
                ? CUDA_Q1_0_SSD_WRAP_IO_TIMEOUT
                : (read_errno == ECANCELED
                    ? CUDA_Q1_0_SSD_WRAP_IO_CANCELLED
                    : CUDA_Q1_0_SSD_WRAP_IO_PREAD);
            result.failure_range = i;
            result.expected_bytes = bytes;
            result.actual_bytes = got;
            result.os_error = read_errno;
            return result;
        }
        if ((uint64_t)got != bytes) {
            ds4_transport_mark_incomplete();
            result.status = CUDA_Q1_0_SSD_WRAP_IO_SHORT_READ;
            result.failure_range = i;
            result.expected_bytes = bytes;
            result.actual_bytes = got;
            result.os_error = read_errno;
            return result;
        }
        result.ranges_read++;
        i = next;
    }
    result.status = CUDA_Q1_0_SSD_WRAP_IO_OK;
    result.failure_range = UINT32_MAX;
    result.expected_bytes = 0u;
    result.actual_bytes = 0;
    result.os_error = 0;
    return result;
}

static void cuda_q1_0_ssd_wrap_fail_and_release_all_locked(
    const char *reason);

static void *cuda_q1_0_ssd_wrap_worker(void *) {
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
#ifdef _WIN32
    if (cuda_g73_open_requested()) {
        (void)SetThreadPriority(
            GetCurrentThread(), THREAD_MODE_BACKGROUND_BEGIN);
    }
#endif
    for (;;) {
        std::vector<uint32_t> selected;
        uint8_t prefill_wave = 0;
        uint64_t wave_id = 0;
        uint64_t wave_limit_bytes = 0;
        uint32_t wave_limit_count = 0;
        os_mutex_lock(&state.mutex);
        for (;;) {
            if (state.stop || state.failed) break;
            uint32_t first = UINT32_MAX;
            uint64_t first_sequence = UINT64_MAX;
            for (uint32_t i = 0; i < state.jobs.size(); i++) {
                const cuda_q1_0_ssd_wrap_job &job = state.jobs[i];
                if (job.state == CUDA_Q1_0_SSD_WRAP_REQUESTED &&
                    job.enqueue_sequence < first_sequence) {
                    first = i;
                    first_sequence = job.enqueue_sequence;
                }
            }
            if (first != UINT32_MAX) {
                prefill_wave = state.jobs[first].prefill_wave;
                break;
            }
            (void)os_cond_wait(&state.cond, &state.mutex);
        }
        if (state.stop || state.failed) {
            os_mutex_unlock(&state.mutex);
            break;
        }
        wave_limit_count = prefill_wave ? state.prefill_wave_max_count :
            state.decode_wave_max_count;
        wave_limit_bytes = prefill_wave ? state.prefill_wave_max_bytes :
            state.decode_wave_max_bytes;
        try {
            for (uint32_t i = 0; i < state.jobs.size(); i++) {
                if (state.jobs[i].state == CUDA_Q1_0_SSD_WRAP_REQUESTED &&
                    state.jobs[i].prefill_wave == prefill_wave) {
                    selected.push_back(i);
                }
            }
            std::sort(selected.begin(), selected.end(),
                [&state](uint32_t lhs, uint32_t rhs) {
                    const cuda_q1_0_ssd_wrap_job &a = state.jobs[lhs];
                    const cuda_q1_0_ssd_wrap_job &b = state.jobs[rhs];
                    const uint64_t ao = std::min(
                        a.record.destination_gate_offset,
                        std::min(a.record.destination_up_offset,
                                 a.record.destination_down_offset));
                    const uint64_t bo = std::min(
                        b.record.destination_gate_offset,
                        std::min(b.record.destination_up_offset,
                                 b.record.destination_down_offset));
                    if (ao != bo) return ao < bo;
                    return a.enqueue_sequence < b.enqueue_sequence;
                });
        } catch (...) {
            cuda_q1_0_ssd_wrap_fail_and_release_all_locked(
                "rotator-wave-allocation");
            os_mutex_unlock(&state.mutex);
            break;
        }
        uint64_t selected_bytes = 0;
        uint32_t keep = 0;
        for (; keep < selected.size() && keep < wave_limit_count; keep++) {
            const uint64_t bytes = state.jobs[selected[keep]].bytes_requested;
            if (keep != 0u && (selected_bytes > UINT64_MAX - bytes ||
                selected_bytes + bytes > wave_limit_bytes)) {
                break;
            }
            selected_bytes += bytes;
        }
        if (keep == 0u) keep = 1u;
        selected.resize(keep);
        for (uint32_t index : selected) {
            state.jobs[index].state = CUDA_Q1_0_SSD_WRAP_SSD_INFLIGHT;
        }
        wave_id = ++state.wave_sequence;
        if (prefill_wave) state.waves_prefill++;
        else state.waves_decode++;
        os_mutex_unlock(&state.mutex);

        const double wave_started = cuda_wall_sec();
        uint64_t wave_requested = 0;
        uint64_t wave_read = 0;
        uint64_t wave_useful = 0;
        uint32_t wave_ranges_requested = 0;
        uint32_t wave_ranges_read = 0;
        uint32_t wave_coalesced = 0;
        uint32_t wave_ready = 0;
        uint32_t wave_failed = 0;
        double wave_queue_age_max_seconds = 0.0;
        double wave_service_budget_seconds = 0.0;
        for (uint32_t index : selected) {
            cuda_q1_0_ssd_wrap_job local;
            os_mutex_lock(&state.mutex);
            if (index >= state.jobs.size() || state.stop || state.failed ||
                state.jobs[index].state !=
                    CUDA_Q1_0_SSD_WRAP_SSD_INFLIGHT) {
                os_mutex_unlock(&state.mutex);
                break;
            }
            local = state.jobs[index];
            os_mutex_unlock(&state.mutex);
            const double io_started = cuda_wall_sec();
            os_pread_cancellable_reset(&state.pread);
            /* G73 rotation is advisory and starts only after exact transient
             * serving has succeeded. Queue residence is governed separately by
             * max_age_calls/admission backpressure; it must not consume the
             * per-job I/O budget. Each acquired job receives the configured
             * service budget from io_started. Non-G73 promotion additionally
             * retains the original fail-closed request deadline coupling. */
            const cuda_q1_0_ssd_wrap_service_timing timing =
                cuda_q1_0_ssd_wrap_service_timing_for_job(
                    local, io_started);
            const cuda_q1_0_ssd_wrap_read_result read_result =
                cuda_q1_0_ssd_wrap_read_job(&local, timing.io_deadline);
            const int read_ok =
                read_result.status == CUDA_Q1_0_SSD_WRAP_IO_OK;
            const double io_seconds = cuda_wall_sec() - io_started;
            os_mutex_lock(&state.mutex);
            if (index >= state.jobs.size() || state.stop || state.failed ||
                state.jobs[index].enqueue_sequence != local.enqueue_sequence) {
                os_mutex_unlock(&state.mutex);
                break;
            }
            cuda_q1_0_ssd_wrap_job *job = &state.jobs[index];
            job->io_seconds = io_seconds;
            job->io_status = read_result.status;
            job->ranges_read = read_result.ranges_read;
            job->io_failure_range = read_result.failure_range;
            job->io_expected_bytes = read_result.expected_bytes;
            job->io_actual_bytes = read_result.actual_bytes;
            job->io_errno = read_result.os_error;
            job->bytes_read = read_ok ? job->bytes_requested : 0u;
            if (read_ok) {
                job->state = CUDA_Q1_0_SSD_WRAP_RAM_READY;
                state.ram_ready++;
                wave_ready++;
            } else {
                job->failure_reason =
                    cuda_q1_0_ssd_wrap_io_status_name(read_result.status);
                job->state = CUDA_Q1_0_SSD_WRAP_FAILED;
                job->failure_counted = 1u;
                wave_failed++;
            }
            state.bytes_read += job->bytes_read;
            state.bytes_useful += job->bytes_read;
            state.ranges_read += read_result.ranges_read;
            state.coalesced_ranges += read_result.coalesced;
            if (!read_ok) {
                /* Job-local failure only: the FAILED job is consumed and
                 * released by cuda_q1_0_ssd_wrap_finish_one (failure_reason
                 * set -> ok=0 path). A single missed read used to latch the
                 * whole rotator dead via fail_and_release_all (measured:
                 * wave 58/79 expired in-queue and killed 78 working
                 * rotations for the rest of the run). The route it was
                 * rotating simply stays SSD-served until re-requested. */
                state.failures++;
                if (job->g73_open_rotation) state.advisory_failures++;
                fprintf(stderr,
                        "ds4: [q1-0-ssd-wrap-io] result=%s mode=%s "
                        "action=%s status=%s wave_id=%llu job=%u sequence=%llu "
                        "layer=%u expert=%u range=%u expected=%llu "
                        "actual=%lld errno=%d deadline=%s "
                        "queue_age_ms=%.9g service_budget_ms=%.9g "
                        "service_seconds=%.9g\n",
                        job->g73_open_rotation ? "degraded" : "failed",
                        job->g73_open_rotation ? "advisory" : "terminal",
                        job->g73_open_rotation ? "release-job-local" :
                                                "fail-closed",
                        cuda_q1_0_ssd_wrap_io_status_name(
                            read_result.status),
                        (unsigned long long)wave_id, index,
                        (unsigned long long)job->enqueue_sequence,
                        job->layer, job->expert,
                        read_result.failure_range,
                        (unsigned long long)read_result.expected_bytes,
                        (long long)read_result.actual_bytes,
                        read_result.os_error,
                        job->g73_open_rotation ? "rotator-local" :
                                                "request-bounded",
                        timing.queue_age_seconds * 1000.0,
                        timing.service_budget_seconds * 1000.0,
                        io_seconds);
            }
            os_cond_broadcast(&state.cond);
            os_mutex_unlock(&state.mutex);
            wave_requested += local.bytes_requested;
            wave_read += read_ok ? local.bytes_requested : 0u;
            wave_useful += read_ok ? local.bytes_requested : 0u;
            wave_ranges_requested += local.ranges_requested;
            wave_ranges_read += read_result.ranges_read;
            wave_coalesced += read_result.coalesced;
            wave_queue_age_max_seconds = std::max(
                wave_queue_age_max_seconds, timing.queue_age_seconds);
            wave_service_budget_seconds = timing.service_budget_seconds;
        }
        const double wave_seconds = cuda_wall_sec() - wave_started;
        os_mutex_lock(&state.mutex);
        state.service_seconds += wave_seconds;
        const uint64_t queue_depth = cuda_q1_0_ssd_wrap_queue_depth_locked();
        os_mutex_unlock(&state.mutex);
        fprintf(stderr,
                "ds4: [q1-0-ssd-wrap-wave] result=%s wave_id=%llu "
                "regime=%s requests=%u ranges_requested=%u ranges_read=%u "
                "coalesced_ranges=%u bytes_requested=%llu bytes_read=%llu "
                "bytes_useful=%llu queue_depth=%llu service_seconds=%.9g "
                "queue_age_ms=%.9g service_budget_ms=%.9g "
                "ram_ready=%u failures=%u coalesce_ratio=%.9g\n",
                wave_failed ? "failed" : "ready",
                (unsigned long long)wave_id,
                prefill_wave ? "prefill-rebuild" : "decode-micro",
                (unsigned)selected.size(), wave_ranges_requested,
                wave_ranges_read, wave_coalesced,
                (unsigned long long)wave_requested,
                (unsigned long long)wave_read,
                (unsigned long long)wave_useful,
                (unsigned long long)queue_depth, wave_seconds,
                wave_queue_age_max_seconds * 1000.0,
                wave_service_budget_seconds * 1000.0,
                wave_ready, wave_failed,
                wave_ranges_read == 0u ? 0.0 :
                    (double)wave_ranges_requested / wave_ranges_read);
    }
    return NULL;
}

static int cuda_q1_0_ssd_wrap_init(void) {
    const int requested = cuda_q1_0_ssd_wrap_requested();
    if (requested <= 0) return requested == 0;
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    if (state.enabled) return !state.failed;
    if ((!cuda_q1_0_dynamic_promotion_requested() &&
         !cuda_g73_open_requested()) ||
        !g_model_file_valid || g_model_file_size == 0u ||
        !cuda_q1_0_ssd_wrap_sha_env_valid("DS4_MODEL_SHA256") ||
        (!cuda_g73_open_requested() &&
         !cuda_q1_0_ssd_wrap_sha_env_valid(
             "DS4_Q1_0_EXPERT_SIDECAR_SHA256")) ||
        !g_dynamic_arena.host_base || g_dynamic_arena.slots.empty() ||
        g_dynamic_arena.ssd_wrap_ssd_ring_slots !=
            CUDA_Q1_0_SSD_WRAP_SSD_RING_SLOTS ||
        g_dynamic_arena.ssd_wrap_h2d_ring_slots !=
            CUDA_Q1_0_SSD_WRAP_H2D_RING_SLOTS ||
        !g_dynamic_arena.ssd_wrap_ssd_ring_base ||
        !g_dynamic_arena.ssd_wrap_h2d_ring_base) {
        fprintf(stderr,
                "ds4: [q1-0-ssd-wrap] result=failed "
                "reason=init-contract\n");
        return 0;
    }
    uint32_t queue_capacity = 64u;
    uint32_t prefill_count = 64u;
    uint32_t decode_count = 8u;
    uint32_t prefill_mib = 512u;
    uint32_t decode_mib = 64u;
    uint32_t max_age_calls = 40u;
    uint32_t pinned_min_touches = 3u;
    uint32_t pinned_deadline_calls = 1u;
    double pinned_min_mass = 0.05;
    double pinned_min_weight = 0.02;
    if (!cuda_q1_0_ssd_wrap_u32_env(
            "DS4_Q1_0_SSD_WRAP_QUEUE_CAPACITY", 64u, 2u, 256u,
            &queue_capacity) ||
        !cuda_q1_0_ssd_wrap_u32_env(
            "DS4_Q1_0_SSD_WRAP_PREFILL_WAVE_COUNT", 64u, 1u, 256u,
            &prefill_count) ||
        !cuda_q1_0_ssd_wrap_u32_env(
            "DS4_Q1_0_SSD_WRAP_DECODE_WAVE_COUNT", 8u, 1u, 64u,
            &decode_count) ||
        !cuda_q1_0_ssd_wrap_u32_env(
            "DS4_Q1_0_SSD_WRAP_PREFILL_WAVE_MIB", 512u, 1u, 4096u,
            &prefill_mib) ||
        !cuda_q1_0_ssd_wrap_u32_env(
            "DS4_Q1_0_SSD_WRAP_DECODE_WAVE_MIB", 64u, 1u, 1024u,
            &decode_mib) ||
        !cuda_q1_0_ssd_wrap_u32_env(
            "DS4_Q1_0_SSD_WRAP_MAX_AGE_CALLS", 40u, 1u, 1000000u,
            &max_age_calls) ||
        !cuda_q1_0_ssd_wrap_u32_env(
            "DS4_Q1_0_IQ2_PINNED_MIN_TOUCHES", 3u, 1u, 1000000u,
            &pinned_min_touches) ||
        !cuda_q1_0_ssd_wrap_u32_env(
            "DS4_Q1_0_IQ2_PINNED_DEADLINE_CALLS", 1u, 1u, 1000000u,
            &pinned_deadline_calls) ||
        !cuda_q1_0_ssd_wrap_double_env(
            "DS4_Q1_0_IQ2_PINNED_MIN_MASS", 0.05, 0.0, 1000000.0,
            &pinned_min_mass) ||
        !cuda_q1_0_ssd_wrap_double_env(
            "DS4_Q1_0_IQ2_PINNED_MIN_WEIGHT", 0.02, 0.0, 1000000.0,
            &pinned_min_weight)) {
        return 0;
    }
    os_file_init(&state.file);
    os_pread_cancellable_init(&state.pread);
    if (os_pread_cancellable_prepare(&state.pread) != 0) {
        fprintf(stderr,
                "ds4: [q1-0-ssd-wrap] result=failed "
                "reason=persistent-io-slot error=%s\n",
                strerror(errno));
        return 0;
    }
    if (os_file_reopen_read_sequential(
            &state.file, &g_model_file, 1) != 0) {
        fprintf(stderr,
                "ds4: [q1-0-ssd-wrap] result=failed reason=file-open\n");
        return 0;
    }
    try {
        state.jobs.assign(queue_capacity, cuda_q1_0_ssd_wrap_job{});
        state.ring_busy.assign(
            CUDA_Q1_0_SSD_WRAP_SSD_RING_SLOTS, 0u);
        g_q1_0_ssd_wrap_reserved_slots.assign(
            g_dynamic_arena.slots.size(), 0u);
    } catch (...) {
        os_file_close(&state.file);
        return 0;
    }
    state.queue_capacity = queue_capacity;
    state.prefill_wave_max_count = prefill_count;
    state.decode_wave_max_count = decode_count;
    state.prefill_wave_max_bytes = (uint64_t)prefill_mib << 20;
    state.decode_wave_max_bytes = (uint64_t)decode_mib << 20;
    state.max_age_calls = max_age_calls;
    state.pinned_min_touches = pinned_min_touches;
    state.pinned_min_mass = pinned_min_mass;
    state.pinned_min_weight = pinned_min_weight;
    state.pinned_deadline_calls = pinned_deadline_calls;
    if (os_mutex_init(&state.mutex) != 0) {
        os_file_close(&state.file);
        return 0;
    }
    state.mutex_ready = 1;
    if (os_cond_init(&state.cond) != 0) {
        cuda_q1_0_ssd_wrap_release(0);
        return 0;
    }
    state.cond_ready = 1;
    for (uint32_t i = 0; i < CUDA_Q1_0_SSD_WRAP_H2D_RING_SLOTS; i++) {
        const cudaError_t event_error = cudaEventCreateWithFlags(
            &state.h2d_done[i], cudaEventDisableTiming);
        if (event_error != cudaSuccess) {
            (void)cudaGetLastError();
            cuda_q1_0_ssd_wrap_release(0);
            return 0;
        }
    }
    state.enabled = 1;
    if (os_thread_create(
            &state.thread, cuda_q1_0_ssd_wrap_worker, NULL) != 0) {
        cuda_q1_0_ssd_wrap_release(0);
        return 0;
    }
    state.thread_started = 1;
    fprintf(stderr,
            "ds4: [q1-0-ssd-wrap] result=ready enabled=1 "
            "queue_capacity=%u prefill_wave_count=%u "
            "prefill_wave_bytes=%llu decode_wave_count=%u "
            "decode_wave_bytes=%llu max_age_calls=%u "
            "pinned_min_touches=%llu pinned_min_mass=%.9g "
            "pinned_min_weight=%.9g pinned_deadline_calls=%u "
            "host_budget_bytes=%llu pinned_resident_slots=%u "
            "pageable_resident_slots=%u ssd_ring_slots=%u "
            "h2d_ring_slots=%u slot_bytes=%llu "
            "ownership=exclusive-transition-bounded\n",
            state.queue_capacity, state.prefill_wave_max_count,
            (unsigned long long)state.prefill_wave_max_bytes,
            state.decode_wave_max_count,
            (unsigned long long)state.decode_wave_max_bytes,
            state.max_age_calls,
            (unsigned long long)state.pinned_min_touches,
            state.pinned_min_mass, state.pinned_min_weight,
            state.pinned_deadline_calls,
            (unsigned long long)g_dynamic_arena.host_budget_bytes,
            g_dynamic_arena.pinned_slot_count,
            g_dynamic_arena.pageable_slot_count,
            g_dynamic_arena.ssd_wrap_ssd_ring_slots,
            g_dynamic_arena.ssd_wrap_h2d_ring_slots,
            (unsigned long long)g_dynamic_arena.slot_bytes);
    cuda_q1_0_ssd_wrap_working_set_sample("init");
    return !state.failed;
}

static void cuda_q1_0_ssd_wrap_job_release_locked(
        cuda_q1_0_ssd_wrap_job *job) {
    if (!job) return;
    if (!job->replacing && job->slot < g_dynamic_arena.slots.size()) {
        cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[job->slot];
        if (slot.state == DS4_GPU_ARENA_LOADING &&
            slot.layer == job->layer && slot.expert == job->expert) {
            slot.state = DS4_GPU_ARENA_FREE;
            slot.layer = UINT32_MAX;
            slot.expert = UINT32_MAX;
            slot.checksum = 0u;
        }
    }
    if (job->writer_claimed && job->slot < g_dynamic_arena.slots.size()) {
        cuda_dynamic_arena_slot_writer_release(
            &g_dynamic_arena.slots[job->slot]);
    }
    if (job->slot < g_q1_0_ssd_wrap_reserved_slots.size()) {
        g_q1_0_ssd_wrap_reserved_slots[job->slot] = 0u;
    }
    if (job->ring_slot < g_q1_0_ssd_wrap.ring_busy.size()) {
        g_q1_0_ssd_wrap.ring_busy[job->ring_slot] = 0u;
    }
    *job = cuda_q1_0_ssd_wrap_job{};
}

static void cuda_q1_0_ssd_wrap_fail_and_release_all_locked(
        const char *reason) {
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    state.failed = 1;
    state.stop = 1;
    const double commit_deadline = cuda_wall_sec() + 0.050;
    for (;;) {
        uint32_t committing = 0u;
        for (uint32_t i = 0; i < state.jobs.size(); i++) {
            cuda_q1_0_ssd_wrap_job &job = state.jobs[i];
            if (job.state == CUDA_Q1_0_SSD_WRAP_FREE) continue;
            if (job.commit_safe_leaked) continue;
            if (job.state == CUDA_Q1_0_SSD_WRAP_RAM_COMMITTING) {
                if (!job.commit_safe_leaked) committing++;
                continue;
            }
            job.failure_reason = reason ? reason : "rotator-disabled";
            job.state = CUDA_Q1_0_SSD_WRAP_FAILED;
            if (!job.failure_counted) {
                state.failures++;
                job.failure_counted = 1u;
            }
            state.dropped++;
            cuda_q1_0_ssd_wrap_job_release_locked(&job);
        }
        if (committing == 0u) break;
        const uint32_t remaining_ms =
            cuda_deadline_remaining_ms(commit_deadline);
        if (remaining_ms == 0u) {
            for (uint32_t i = 0; i < state.jobs.size(); i++) {
                cuda_q1_0_ssd_wrap_job &job = state.jobs[i];
                if (job.state != CUDA_Q1_0_SSD_WRAP_RAM_COMMITTING ||
                    job.commit_safe_leaked) {
                    continue;
                }
                /* The publisher may still hold a raw slot pointer. Preserve the
                 * arena allocation and leave its writer claim set forever: this
                 * slot is dead and can neither be served nor selected again. */
                job.commit_safe_leaked = 1u;
                state.commit_safe_leaked = 1;
                g_cuda_dynamic_arena_storage_safe_leaked = 1;
                fprintf(stderr,
                        "ds4: [q1-0-ssd-wrap] commit deadline expired "
                        "job=%u slot=%u; writer claim/slot safe-leaked "
                        "permanently\n",
                        i, job.slot);
            }
            break;
        }
        (void)os_cond_timedwait_ms(
            &state.cond, &state.mutex, remaining_ms);
    }
    os_cond_broadcast(&state.cond);
}

static void cuda_q1_0_ssd_wrap_disable(const char *reason) {
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    if (!state.mutex_ready) {
        state.failed = 1;
        state.stop = 1;
        return;
    }
    uint32_t active_sequence = 0u;
    os_mutex_lock(&state.mutex);
    for (const cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        if (job.state == CUDA_Q1_0_SSD_WRAP_SSD_INFLIGHT) {
            active_sequence = job.io_sequence;
            break;
        }
    }
    os_mutex_unlock(&state.mutex);
    if (active_sequence != 0u) {
        (void)os_pread_cancel(&state.pread, active_sequence);
    }
    os_mutex_lock(&state.mutex);
    cuda_q1_0_ssd_wrap_fail_and_release_all_locked(reason);
    os_mutex_unlock(&state.mutex);
}

static int cuda_q1_0_ssd_wrap_finish_one(
        uint32_t index, int force) {
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    cuda_q1_0_ssd_wrap_job local;
    os_mutex_lock(&state.mutex);
    if (index >= state.jobs.size() ||
        (state.jobs[index].state != CUDA_Q1_0_SSD_WRAP_RAM_READY &&
         state.jobs[index].state != CUDA_Q1_0_SSD_WRAP_FAILED)) {
        os_mutex_unlock(&state.mutex);
        return 1;
    }
    if (!force && state.jobs[index].state == CUDA_Q1_0_SSD_WRAP_RAM_READY &&
        g_moe_tiering.call_tick <=
            state.jobs[index].record.observation_call) {
        os_mutex_unlock(&state.mutex);
        return 1;
    }
    local = state.jobs[index];
    local.tier_generation = state.tier_generation;
    state.jobs[index].tier_generation = state.tier_generation;
    cuda_dynamic_arena_slot *slot = local.slot < g_dynamic_arena.slots.size()
        ? &g_dynamic_arena.slots[local.slot] : NULL;
    char *slot_host_ptr = slot ? slot->host_ptr : NULL;
    state.jobs[index].state = CUDA_Q1_0_SSD_WRAP_RAM_COMMITTING;
    /* Publication owns only the arena writer claim. Teardown can take the
     * rotator mutex, release other jobs, and bounded-await this marker. */
    os_mutex_unlock(&state.mutex);

    if (state.selftest_stall_committing_publication) {
        os_mutex_lock(&state.mutex);
        state.selftest_committing_publication_stalled = 1;
        os_cond_broadcast(&state.cond);
        while (!state.selftest_release_committing_publication) {
            (void)os_cond_wait(&state.cond, &state.mutex);
        }
        os_mutex_unlock(&state.mutex);
    }

    int ok = local.failure_reason == NULL;
    const int advisory_io_failure =
        local.g73_open_rotation &&
        local.io_status != CUDA_Q1_0_SSD_WRAP_IO_NONE &&
        local.io_status != CUDA_Q1_0_SSD_WRAP_IO_OK;
    const char *reason = local.failure_reason;
    uint64_t stale_delta = 0u;
    uint64_t host_copy_bytes = 0u;
    double host_copy_seconds = 0.0;
    if (ok && (!slot || !slot_host_ptr || local.request_epoch == 0u ||
        local.record.request_epoch != local.request_epoch ||
        local.record.first_eligible_call <=
            local.record.observation_call)) {
        ok = 0;
        reason = "stale_or_epoch";
        stale_delta++;
    }
    if (ok && (!local.writer_claimed ||
               cuda_dynamic_arena_slot_refs_load(
                   &slot->cpu_lane_slot_refs) !=
                       CUDA_DYNAMIC_ARENA_SLOT_WRITER)) {
        ok = 0;
        reason = "writer_claim_lost";
        stale_delta++;
    }
    uint64_t slot_checksum = 0u;
    if (ok) {
        const double copy_started = cuda_wall_sec();
        memcpy(slot_host_ptr, local.read_base,
               (size_t)g_dynamic_arena.slot_bytes);
        host_copy_bytes = g_dynamic_arena.slot_bytes;
        host_copy_seconds = cuda_wall_sec() - copy_started;
        slot_checksum = cuda_dynamic_arena_fnv1a64(
            (const uint8_t *)slot_host_ptr, g_dynamic_arena.slot_bytes);
    }

    os_mutex_lock(&state.mutex);
    if (local.tier_generation != state.tier_generation) {
        /* Reset retained the old entry allocation and invalidated this
         * publisher before replacing tier state. The copied slot stays
         * writer-claimed and permanently dead; no tier or slot metadata is
         * read or written after observing the generation change. */
        state.host_copy_bytes += host_copy_bytes;
        state.host_copy_seconds += host_copy_seconds;
        state.generation_abandons++;
        if (index < state.jobs.size()) {
            state.jobs[index].state = CUDA_Q1_0_SSD_WRAP_DEAD;
            state.jobs[index].failure_reason = "tier-generation-changed";
            state.jobs[index].commit_safe_leaked = 1u;
        }
        state.commit_safe_leaked = 1;
        g_cuda_dynamic_arena_storage_safe_leaked = 1;
        os_cond_broadcast(&state.cond);
        os_mutex_unlock(&state.mutex);
        return 0;
    }
    if (ok && local.replacing) {
        if (local.victim_entry_index >= g_moe_tiering.entries.size()) {
            ok = 0;
            reason = "victim_contract";
        } else {
            cuda_moe_tier_entry &victim =
                g_moe_tiering.entries[local.victim_entry_index];
            if (victim.ram_slot != local.slot ||
                victim.ram_generation != local.victim_generation ||
                victim.state != local.victim_state ||
                slot->layer != local.victim_layer ||
                slot->expert != local.victim_expert ||
                slot->content_generation != local.victim_generation ||
                (slot->state != DS4_GPU_ARENA_READY &&
                 slot->state != DS4_GPU_ARENA_STAGED)) {
                ok = 0;
                reason = "victim_stale";
                stale_delta++;
            }
        }
    } else if (ok &&
               (slot->state != DS4_GPU_ARENA_LOADING ||
                slot->layer != local.layer || slot->expert != local.expert)) {
        ok = 0;
        reason = "destination_stale";
        stale_delta++;
    }
    if (ok && local.replacing) {
        cuda_moe_tier_entry &victim =
            g_moe_tiering.entries[local.victim_entry_index];
        const int victim_stays_in_vram =
            victim.state == CUDA_MOE_TIER_VRAM_PROTECTED &&
            cuda_moe_tiering_has_exact_vram(
                local.victim_layer, local.victim_expert);
        if (victim.state == CUDA_MOE_TIER_VRAM_PROTECTED &&
            !victim_stays_in_vram) {
            ok = 0;
            reason = "victim_vram_contract";
        } else {
            victim.ram_slot = UINT32_MAX;
            victim.ram_generation = 0;
            victim.has_2bit_ram = 0;
            victim.vram_eligible_after_call = 0;
            victim.promoted_from_iq1_cold = 0;
            if (victim_stays_in_vram) {
                g_moe_tiering.general_backing_reclaims++;
                g_iq1_promotion.probation_backing_reclaims++;
            } else {
                victim.state = CUDA_MOE_TIER_SSD_COLD;
            }
            g_moe_tiering.ram_evictions++;
            if (g_moe_tiering.g133_enabled) {
                cuda_g133_telemetry_increment(
                    g_cuda_g133_telemetry.reaps);
            }
            if (local.g73_open_rotation) {
                cuda_g133_telemetry_increment(
                    g_cuda_g133_telemetry.rotation_reaps);
            }
        }
    }
    if (ok) {
        slot->state = DS4_GPU_ARENA_LOADING;
        slot->layer = local.layer;
        slot->expert = local.expert;
        if (local.replacing) {
            slot->content_generation = ++g_dynamic_arena.next_generation;
        }
        slot->checksum = slot_checksum;
        slot->last_dma_sequence = 0;
        slot->state = DS4_GPU_ARENA_READY;
        cuda_moe_tier_entry &entry = g_moe_tiering.entries[
            cuda_moe_tiering_entry_index(local.layer, local.expert)];
        entry.ram_slot = local.slot;
        entry.ram_generation = slot->content_generation;
        entry.vram_eligible_after_call = local.record.first_eligible_call;
        entry.has_2bit_ram = 1;
        entry.promoted_from_iq1_cold =
            local.g73_open_rotation ? 0u : 1u;
        entry.state = g_moe_tiering.g133_enabled &&
                cuda_g133_ram_candidate_relaxed(entry)
            ? CUDA_MOE_TIER_RAM_WARM : CUDA_MOE_TIER_RAM_PROBATION;
        if (entry.state == CUDA_MOE_TIER_RAM_WARM) {
            cuda_g133_mark_promotion(entry, local.request.g133_epoch);
            g_moe_tiering.ram_to_warm++;
        }
        g_moe_tiering.cold_to_ram++;
        g_moe_tiering.ssd_bytes += local.bytes_read;
        if (!local.g73_open_rotation) {
            g_iq1_promotion.cold_to_2bit_ram++;
            g_iq1_promotion.promotion_2bit_ssd_bytes += local.bytes_read;
            g_iq1_promotion.promotion_2bit_ssd_seconds += local.io_seconds;
            g_iq1_promotion.q1_0_stage_successes++;
            g_iq1_promotion.q1_0_next_call_guards++;
            g_iq1_promotion.q1_0_record_successes++;
        } else {
            cuda_g133_telemetry_increment(
                g_cuda_g133_telemetry.rotation_promotions);
        }
        if (!local.g73_open_rotation) {
            cuda_q1_0_promotion_record_emit(
                "success", "success", "staged", &local.record,
                "exact_iq2_ram", local.slot, slot->content_generation);
        }
    } else {
        if (!local.replacing && local.slot < g_dynamic_arena.slots.size()) {
            cuda_dynamic_arena_slot &failed_slot =
                g_dynamic_arena.slots[local.slot];
            if (failed_slot.state == DS4_GPU_ARENA_LOADING &&
                failed_slot.layer == local.layer &&
                failed_slot.expert == local.expert) {
                failed_slot.state = DS4_GPU_ARENA_FREE;
                failed_slot.layer = UINT32_MAX;
                failed_slot.expert = UINT32_MAX;
                failed_slot.checksum = 0;
            }
        }
        if (!local.g73_open_rotation) {
            g_iq1_promotion.q1_0_record_failures++;
            g_iq1_promotion.failures++;
            g_moe_tiering.failures++;
        }
        if (!local.g73_open_rotation) {
            cuda_q1_0_promotion_record_emit(
                "failure", "failed", reason ? reason : "ssd_wrap_failed",
                &local.record, "exact_iq2_ram_failed", UINT32_MAX, 0u);
        }
    }
    state.stale += stale_delta;
    state.host_copy_bytes += host_copy_bytes;
    state.host_copy_seconds += host_copy_seconds;
    if (ok) {
        state.successes++;
        if (slot->pageable) state.pageable_ready++;
        else state.pinned_ready++;
    }
    if (index < state.jobs.size() &&
        state.jobs[index].commit_safe_leaked) {
        /* Teardown expired while publication was outside the mutex. Never
         * release this writer claim; its process-lifetime slot remains dead. */
        os_cond_broadcast(&state.cond);
        os_mutex_unlock(&state.mutex);
        return ok;
    }
    if (!ok) {
        if (index < state.jobs.size()) {
            state.jobs[index].state = CUDA_Q1_0_SSD_WRAP_FAILED;
            state.jobs[index].failure_reason =
                reason ? reason : "ssd-wrap-commit-failure";
        }
        if (advisory_io_failure && index < state.jobs.size()) {
            /* Exact transient serving completed before this G73 rotation was
             * scheduled. A failed advisory read publishes nothing and owns no
             * serving fallback: release only this job so later rotations can
             * proceed. The experiment gate remains degraded via the explicit
             * advisory counter. */
            state.advisory_releases++;
            cuda_q1_0_ssd_wrap_job_release_locked(&state.jobs[index]);
        } else {
            cuda_q1_0_ssd_wrap_fail_and_release_all_locked(
                reason ? reason : "ssd-wrap-commit-failure");
        }
    } else if (index < state.jobs.size()) {
        cuda_q1_0_ssd_wrap_job_release_locked(&state.jobs[index]);
    }
    os_cond_broadcast(&state.cond);
    os_mutex_unlock(&state.mutex);
    return ok || advisory_io_failure;
}

static void *cuda_q1_0_ssd_wrap_selftest_finish_one(void *arg) {
    const uint32_t index = *(const uint32_t *)arg;
    (void)cuda_q1_0_ssd_wrap_finish_one(index, 1);
    return NULL;
}

static int cuda_q1_0_ssd_wrap_poll_internal(int force) {
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    if (!state.enabled) return 1;
    os_mutex_lock(&state.mutex);
    for (cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        if (job.state == CUDA_Q1_0_SSD_WRAP_REQUESTED &&
            g_moe_tiering.call_tick > job.enqueue_call &&
            g_moe_tiering.call_tick - job.enqueue_call >
                state.max_age_calls) {
            job.failure_reason = "stale_age";
            job.state = CUDA_Q1_0_SSD_WRAP_FAILED;
            state.stale++;
            state.dropped++;
        }
    }
    os_cond_broadcast(&state.cond);
    os_mutex_unlock(&state.mutex);
    int ok = 1;
    for (uint32_t i = 0; i < state.jobs.size(); i++) {
        if (!cuda_q1_0_ssd_wrap_finish_one(i, force)) ok = 0;
    }
    return ok && !state.failed;
}

static int cuda_q1_0_ssd_wrap_poll(void) {
    return cuda_q1_0_ssd_wrap_poll_internal(0);
}

static int cuda_q1_0_ssd_wrap_submit(
        const cuda_moe_route_request &request, uint32_t layer,
        uint32_t expert, cuda_q1_0_promotion_record_context *record,
        int g73_open_rotation = 0) {
    if (!record || !record->active || !cuda_q1_0_ssd_wrap_init() ||
        !cuda_q1_0_ssd_wrap_poll()) {
        return 0;
    }
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    os_mutex_lock(&state.mutex);
    if (state.failed || state.stop) {
        os_mutex_unlock(&state.mutex);
        return 0;
    }
    for (const cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        if (job.state != CUDA_Q1_0_SSD_WRAP_FREE &&
            job.layer == layer && job.expert == expert) {
            state.deduplicated++;
            os_mutex_unlock(&state.mutex);
            return 2;
        }
    }
    os_mutex_unlock(&state.mutex);

    const uint64_t deadline = record->first_eligible_call >=
            record->current_call ?
        record->first_eligible_call - record->current_call : UINT64_MAX;
    const int prefer_pinned =
        record->touch_count >= state.pinned_min_touches &&
        deadline <= state.pinned_deadline_calls &&
        (record->mass >= state.pinned_min_mass ||
         fabs((double)record->weight) >= state.pinned_min_weight);
    size_t victim_entry_index = SIZE_MAX;
    const int slot_i = cuda_moe_tiering_pick_ram_slot(
        layer, expert, &victim_entry_index, request.g133_epoch,
        g73_open_rotation ? 0 : (prefer_pinned ? 0 : 1),
        g73_open_rotation != 0);
    if (slot_i < 0) {
        state.backpressure++;
        return 3;
    }
    cuda_dynamic_arena_slot &slot =
        g_dynamic_arena.slots[(uint32_t)slot_i];
    const int replacing = victim_entry_index != SIZE_MAX;
    if (g73_open_rotation == 2) {
        os_mutex_lock(&state.mutex);
        cuda_q1_0_ssd_wrap_fail_and_release_all_locked(
            "selftest-stop-after-writer-claim");
        os_mutex_unlock(&state.mutex);
    }
    uint32_t ring_slot = UINT32_MAX;
    uint32_t job_index = UINT32_MAX;
    os_mutex_lock(&state.mutex);
    /* The writer claim is acquired outside this mutex, then revalidated here.
     * Teardown wins before admission; after COMMITTING, it skips the writer and
     * uses the bounded-await/safe-leak publication contract. */
    if (state.failed || state.stop) {
        cuda_dynamic_arena_slot_writer_release(&slot);
        os_mutex_unlock(&state.mutex);
        return 0;
    }
    for (uint32_t i = 0; i < state.jobs.size(); i++) {
        if (state.jobs[i].state == CUDA_Q1_0_SSD_WRAP_FREE) {
            job_index = i;
            break;
        }
    }
    for (uint32_t i = 0; i < state.ring_busy.size(); i++) {
        if (!state.ring_busy[i]) {
            ring_slot = i;
            break;
        }
    }
    if (job_index == UINT32_MAX || ring_slot == UINT32_MAX ||
        (uint32_t)slot_i >= g_q1_0_ssd_wrap_reserved_slots.size() ||
        g_q1_0_ssd_wrap_reserved_slots[(uint32_t)slot_i]) {
        state.backpressure++;
        os_mutex_unlock(&state.mutex);
        cuda_dynamic_arena_slot_writer_release(&slot);
        return 3;
    }
    cuda_q1_0_ssd_wrap_job &job = state.jobs[job_index];
    job = cuda_q1_0_ssd_wrap_job{};
    job.state = CUDA_Q1_0_SSD_WRAP_REQUESTED;
    job.record = *record;
    job.request = request;
    job.request_epoch = record->request_epoch;
    job.enqueue_call = g_moe_tiering.call_tick;
    job.enqueue_sequence = ++state.enqueue_sequence;
    job.io_sequence = (uint32_t)job.enqueue_sequence;
    if (job.io_sequence == 0u) job.io_sequence = 1u;
    job.bytes_requested = record->destination_bytes;
    job.ranges_requested = 3u;
    job.layer = layer;
    job.expert = expert;
    job.slot = (uint32_t)slot_i;
    job.ring_slot = ring_slot;
    job.victim_entry_index = victim_entry_index;
    job.replacing = replacing ? 1u : 0u;
    job.writer_claimed = 1u;
    job.g73_open_rotation = g73_open_rotation ? 1u : 0u;
    job.prefill_wave =
        g_prefill_mass_observer.enabled &&
        !g_prefill_mass_observer.finalized ? 1u : 0u;
    job.destination_pageable = slot.pageable;
    job.queued_at = cuda_wall_sec();
    job.read_base = g_dynamic_arena.ssd_wrap_ssd_ring_base +
        (uint64_t)ring_slot * g_dynamic_arena.slot_bytes;
    state.ring_busy[ring_slot] = 1u;
    if (replacing) {
        cuda_moe_tier_entry &victim =
            g_moe_tiering.entries[victim_entry_index];
        job.victim_generation = victim.ram_generation;
        job.victim_layer = (uint32_t)(victim_entry_index / 256u);
        job.victim_expert = (uint32_t)(victim_entry_index % 256u);
        job.victim_state = victim.state;
    } else {
        slot.state = DS4_GPU_ARENA_LOADING;
        slot.layer = layer;
        slot.expert = expert;
        slot.content_generation = ++g_dynamic_arena.next_generation;
        slot.checksum = 0;
        slot.last_dma_sequence = 0;
    }
    g_q1_0_ssd_wrap_reserved_slots[(uint32_t)slot_i] = 1u;
    if (!g73_open_rotation) {
        record->record_id = ++g_iq1_promotion.q1_0_record_attempts;
        record->attempt_started = 1;
    }
    job.record = *record;
    state.requested++;
    state.attempts++;
    state.bytes_requested += job.bytes_requested;
    state.ranges_requested += job.ranges_requested;
    const uint64_t depth = cuda_q1_0_ssd_wrap_queue_depth_locked();
    state.max_queue_depth = std::max(state.max_queue_depth, depth);
    if (!g73_open_rotation) g_iq1_promotion.q1_0_stage_attempts++;
    os_cond_signal(&state.cond);
    os_mutex_unlock(&state.mutex);
    if (!g73_open_rotation) {
        cuda_q1_0_promotion_record_emit(
            "attempt", "attempt", "admitted", record,
            slot.pageable ? "exact_iq2_pageable_pending" :
                            "exact_iq2_pinned_pending",
            (uint32_t)slot_i, 0u);
    }
    return 1;
}

static void cuda_g73_open_maybe_schedule_rotation(
        const cuda_moe_route_request &request, uint32_t route,
        uint32_t expert, cuda_moe_tier_entry &entry) {
    if (entry.state != CUDA_MOE_TIER_SSD_COLD ||
        route >= request.route_count ||
        !cuda_g133_ram_candidate(entry, request.g133_epoch)) {
        return;
    }
    cuda_q1_0_promotion_record_context record;
    if (!cuda_g73_open_rotation_record_context_init(
            &record, request, expert, request.weights[route], entry)) {
        return;
    }
    /* Serving already uses the exact transient buffers. Rotation is advisory:
     * queue/backpressure/failure may cost a future read, never this request. */
    (void)cuda_q1_0_ssd_wrap_submit(
        request, request.layer_index, expert, &record, 1);
}

static int cuda_q1_0_ssd_wrap_release_boundary_jobs_locked(
        const char *reason) {
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    const double commit_deadline = cuda_wall_sec() + 0.050;
    for (;;) {
        uint32_t committing = 0u;
        for (uint32_t i = 0; i < state.jobs.size(); i++) {
            cuda_q1_0_ssd_wrap_job &job = state.jobs[i];
            if (job.state == CUDA_Q1_0_SSD_WRAP_FREE) continue;
            if (job.state == CUDA_Q1_0_SSD_WRAP_RAM_COMMITTING) {
                committing++;
                continue;
            }
            if (job.state == CUDA_Q1_0_SSD_WRAP_FAILED ||
                job.state == CUDA_Q1_0_SSD_WRAP_DEAD ||
                job.commit_safe_leaked ||
                job.state == CUDA_Q1_0_SSD_WRAP_SSD_INFLIGHT) {
                cuda_q1_0_ssd_wrap_fail_and_release_all_locked(
                    reason ? reason : "request-boundary-transport-failure");
                return 0;
            }
            /* RAM_READY jobs were force-published before this locked pass.
             * A REQUESTED job is cleanly discardable because route workers are
             * quiescent and the SSD worker has not acquired its ring buffer. */
            job.failure_reason = reason ? reason : "request-boundary-release";
            state.dropped++;
            cuda_q1_0_ssd_wrap_job_release_locked(&job);
        }
        if (committing == 0u) {
            state.stop = 0;
            os_pread_cancellable_reset(&state.pread);
            os_cond_broadcast(&state.cond);
            return !state.failed;
        }
        const uint32_t remaining_ms =
            cuda_deadline_remaining_ms(commit_deadline);
        if (remaining_ms == 0u) {
            /* Round-5 terminal: the publisher may hold raw slot and tier-entry
             * pointers. Latch the rotator and preserve both allocations plus
             * the writer claim forever; re-arming this case would permit reuse. */
            state.failed = 1;
            state.stop = 1;
            for (uint32_t i = 0; i < state.jobs.size(); i++) {
                cuda_q1_0_ssd_wrap_job &job = state.jobs[i];
                if (job.state != CUDA_Q1_0_SSD_WRAP_RAM_COMMITTING ||
                    job.commit_safe_leaked) {
                    continue;
                }
                job.commit_safe_leaked = 1u;
                state.commit_safe_leaked = 1;
                g_cuda_dynamic_arena_storage_safe_leaked = 1;
                fprintf(stderr,
                        "ds4: [q1-0-ssd-wrap] commit deadline expired "
                        "job=%u slot=%u; writer claim/slot safe-leaked "
                        "permanently\n",
                        i, job.slot);
            }
            os_cond_broadcast(&state.cond);
            return 0;
        }
        (void)os_cond_timedwait_ms(
            &state.cond, &state.mutex, remaining_ms);
    }
}

static void cuda_q1_0_ssd_wrap_flush(void) {
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    if (!state.enabled || !state.mutex_ready) return;
    const double absolute_deadline = cuda_wall_sec() + 0.010;
    for (;;) {
        os_mutex_lock(&state.mutex);
        int worker_pending = 0;
        for (const cuda_q1_0_ssd_wrap_job &job : state.jobs) {
            if (job.state == CUDA_Q1_0_SSD_WRAP_REQUESTED ||
                job.state == CUDA_Q1_0_SSD_WRAP_SSD_INFLIGHT) {
                worker_pending = 1;
                break;
            }
        }
        if (!worker_pending || state.failed) {
            os_mutex_unlock(&state.mutex);
            break;
        }
        const uint32_t remaining_ms =
            cuda_deadline_remaining_ms(absolute_deadline);
        if (remaining_ms == 0u) {
            uint32_t active_sequence = 0u;
            for (cuda_q1_0_ssd_wrap_job &job : state.jobs) {
                if (job.state == CUDA_Q1_0_SSD_WRAP_SSD_INFLIGHT) {
                    active_sequence = job.io_sequence;
                    break;
                }
            }
            if (active_sequence == 0u) {
                /* The worker never acquired these clean requests. Release in
                 * job-table order; the final forced poll below still publishes
                 * every RAM_READY owner before the rotator is re-armed. */
                for (cuda_q1_0_ssd_wrap_job &job : state.jobs) {
                    if (job.state != CUDA_Q1_0_SSD_WRAP_REQUESTED) continue;
                    job.failure_reason = "request-boundary-release";
                    state.dropped++;
                    cuda_q1_0_ssd_wrap_job_release_locked(&job);
                }
                os_mutex_unlock(&state.mutex);
                break;
            }
            os_mutex_unlock(&state.mutex);
            (void)os_pread_cancel(&state.pread, active_sequence);
            os_mutex_lock(&state.mutex);
            cuda_q1_0_ssd_wrap_fail_and_release_all_locked(
                "request-boundary-transport-stall");
            os_mutex_unlock(&state.mutex);
            fprintf(stderr,
                    "ds4: [g73-open] advisory rotator detached at request "
                    "boundary after bounded transport deadline\n");
            return;
        }
        (void)os_cond_timedwait_ms(
            &state.cond, &state.mutex, remaining_ms);
        os_mutex_unlock(&state.mutex);
    }
    /* Request-boundary teardown has three explicit cases:
     *  1. Normal: force-publish completed RAM_READY jobs, deterministically
     *     release clean queued owners/reservations/claims, then re-arm.
     *  2. Stalled publication: bounded-await RAM_COMMITTING; expiry retains the
     *     round-5 generation guard and safe-leaks its entry block/slot claim.
     *  3. Transport failure/stall: retain the permanent failed/stop latch.
     * No tier reset may run until one of these ownership terminals is reached. */
    if (!cuda_q1_0_ssd_wrap_poll_internal(1)) return;
    os_mutex_lock(&state.mutex);
    (void)cuda_q1_0_ssd_wrap_release_boundary_jobs_locked(
        "request-boundary-release");
    os_mutex_unlock(&state.mutex);
}

static void cuda_q1_0_ssd_wrap_release(int report) {
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    if (state.enabled) cuda_q1_0_ssd_wrap_flush();
    if (state.mutex_ready) {
        os_mutex_lock(&state.mutex);
        int owns_work = 0;
        for (const cuda_q1_0_ssd_wrap_job &job : state.jobs) {
            if (job.state != CUDA_Q1_0_SSD_WRAP_FREE) {
                owns_work = 1;
                break;
            }
        }
        if (owns_work) {
            cuda_q1_0_ssd_wrap_fail_and_release_all_locked(
                "rotator-release");
        } else {
            state.stop = 1;
            if (state.cond_ready) os_cond_broadcast(&state.cond);
        }
        os_mutex_unlock(&state.mutex);
    }
    if (state.thread_started) {
        if (!os_thread_join_timeout(state.thread, 50u)) {
            os_thread_detach(state.thread);
            state.thread_detached = 1;
            state.thread_started = 0;
            fprintf(stderr,
                    "ds4: [q1-0-ssd-wrap] worker detached after bounded "
                    "cancel/join; static rotator storage safe-leaked\n");
        } else {
            state.thread_started = 0;
        }
    }
    if (state.thread_detached) {
        /* The process-lifetime state, file handle, events, and ring remain
         * valid until the cancelled read returns. All tier claims were already
         * released atomically by fail_and_release_all_locked(). */
        return;
    }
    if (state.commit_safe_leaked) {
        /* A publisher can still hold a raw slot pointer. Keep the mutex,
         * job table, file/rings, and arena allocation alive for the process. */
        fprintf(stderr,
                "ds4: [q1-0-ssd-wrap] committing slot and rotator storage "
                "safe-leaked after bounded teardown\n");
        return;
    }
    os_pread_cancellable_destroy(&state.pread);
    for (uint32_t i = 0; i < CUDA_Q1_0_SSD_WRAP_H2D_RING_SLOTS; i++) {
        if (state.h2d_pending[i] && state.h2d_done[i]) {
            (void)cudaEventSynchronize(state.h2d_done[i]);
        }
        if (state.h2d_done[i]) (void)cudaEventDestroy(state.h2d_done[i]);
        state.h2d_done[i] = NULL;
        state.h2d_pending[i] = 0;
    }
    if (report && state.enabled) {
        cuda_q1_0_ssd_wrap_working_set_sample("release");
        fprintf(stderr,
                "ds4: [q1-0-ssd-wrap] result=%s requested=%llu "
                "deduplicated=%llu backpressure=%llu attempts=%llu "
                "successes=%llu failures=%llu advisory_failures=%llu "
                "advisory_releases=%llu advisory_degraded=%u "
                "structural_rejects=%llu "
                "bytes_requested=%llu bytes_read=%llu bytes_useful=%llu "
                "ranges_requested=%llu ranges_read=%llu "
                "coalesced_ranges=%llu max_queue_depth=%llu "
                "waves_prefill=%llu waves_decode=%llu ram_ready=%llu "
                "pinned_ready=%llu pageable_ready=%llu pinned_hits=%llu "
                "pageable_hits=%llu stale=%llu "
                "dropped=%llu host_copy_bytes=%llu host_copy_seconds=%.9g "
                "h2d_waits=%llu h2d_wait_seconds=%.9g "
                "pageable_paged_out_before_copy=%llu first_use=%llu "
                "wasted=%llu service_seconds=%.9g\n",
                state.failed ? "failed" :
                    (state.advisory_failures ? "degraded" : "complete"),
                (unsigned long long)state.requested,
                (unsigned long long)state.deduplicated,
                (unsigned long long)state.backpressure,
                (unsigned long long)state.attempts,
                (unsigned long long)state.successes,
                (unsigned long long)state.failures,
                (unsigned long long)state.advisory_failures,
                (unsigned long long)state.advisory_releases,
                state.advisory_failures ? 1u : 0u,
                (unsigned long long)state.structural_rejects,
                (unsigned long long)state.bytes_requested,
                (unsigned long long)state.bytes_read,
                (unsigned long long)state.bytes_useful,
                (unsigned long long)state.ranges_requested,
                (unsigned long long)state.ranges_read,
                (unsigned long long)state.coalesced_ranges,
                (unsigned long long)state.max_queue_depth,
                (unsigned long long)state.waves_prefill,
                (unsigned long long)state.waves_decode,
                (unsigned long long)state.ram_ready,
                (unsigned long long)state.pinned_ready,
                (unsigned long long)state.pageable_ready,
                (unsigned long long)state.pinned_hits,
                (unsigned long long)state.pageable_hits,
                (unsigned long long)state.stale,
                (unsigned long long)state.dropped,
                (unsigned long long)state.host_copy_bytes,
                state.host_copy_seconds,
                (unsigned long long)state.h2d_waits,
                state.h2d_wait_seconds,
                (unsigned long long)state.pageable_paged_out_before_copy,
                (unsigned long long)state.first_use,
                (unsigned long long)state.wasted,
                state.service_seconds);
    }
    if (os_file_valid(&state.file)) os_file_close(&state.file);
    if (state.cond_ready) os_cond_destroy(&state.cond);
    if (state.mutex_ready) os_mutex_destroy(&state.mutex);
    g_q1_0_ssd_wrap_reserved_slots.clear();
    state = cuda_q1_0_ssd_wrap_state{};
}

static int cuda_q1_0_ssd_wrap_host_is_pageable(
        uint32_t layer, uint32_t expert, int from_snapshot,
        int from_probation) {
    if (!g_q1_0_ssd_wrap.enabled) return 0;
    if (from_snapshot) {
        const uint32_t entry = layer * 256u + expert;
        if (entry >= g_dynamic_arena.active.size()) return -1;
        const cuda_dynamic_arena_binding &binding =
            g_dynamic_arena.active[entry];
        if (binding.slot >= g_dynamic_arena.slots.size()) return -1;
        return g_dynamic_arena.slots[binding.slot].pageable ? 1 : 0;
    }
    if (from_probation) {
        const cuda_moe_tier_entry &tier = g_moe_tiering.entries[
            cuda_moe_tiering_entry_index(layer, expert)];
        if (tier.ram_slot >= g_dynamic_arena.slots.size()) return -1;
        return g_dynamic_arena.slots[tier.ram_slot].pageable ? 1 : 0;
    }
    return 0;
}

static int cuda_q1_0_ssd_wrap_prepare_h2d_source(
        char **gate, char **up, char **down, uint64_t gate_bytes,
        uint64_t down_bytes, int pageable, uint32_t *ring_out) {
    if (ring_out) *ring_out = UINT32_MAX;
    if (!g_q1_0_ssd_wrap.enabled || !pageable) {
        if (g_q1_0_ssd_wrap.enabled) g_q1_0_ssd_wrap.pinned_hits++;
        return 1;
    }
    if (!gate || !up || !down || !*gate || !*up || !*down || !ring_out ||
        *up != *gate + gate_bytes || *down != *up + gate_bytes ||
        gate_bytes > UINT64_MAX - gate_bytes ||
        gate_bytes * 2u > UINT64_MAX - down_bytes ||
        gate_bytes * 2u + down_bytes != g_dynamic_arena.slot_bytes) {
        cuda_q1_0_ssd_wrap_disable("h2d-source-contract");
        return 0;
    }
    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    const uint32_t ring = state.h2d_cursor++ %
        CUDA_Q1_0_SSD_WRAP_H2D_RING_SLOTS;
    if (state.h2d_pending[ring]) {
        const double wait_started = cuda_wall_sec();
        const cudaError_t waited = cudaEventSynchronize(state.h2d_done[ring]);
        state.h2d_waits++;
        state.h2d_wait_seconds += cuda_wall_sec() - wait_started;
        state.h2d_pending[ring] = 0;
        if (waited != cudaSuccess) {
            (void)cudaGetLastError();
            cuda_q1_0_ssd_wrap_disable("h2d-reuse-event");
            return 0;
        }
    }
    char *bounce = g_dynamic_arena.ssd_wrap_h2d_ring_base +
        (uint64_t)ring * g_dynamic_arena.slot_bytes;
    const double copy_started = cuda_wall_sec();
    memcpy(bounce, *gate, (size_t)g_dynamic_arena.slot_bytes);
    state.host_copy_seconds += cuda_wall_sec() - copy_started;
    state.host_copy_bytes += g_dynamic_arena.slot_bytes;
    state.pageable_hits++;
    *gate = bounce;
    *up = bounce + gate_bytes;
    *down = *up + gate_bytes;
    *ring_out = ring;
    return 1;
}

static int cuda_q1_0_ssd_wrap_record_h2d(
        uint32_t ring, cudaStream_t stream) {
    if (ring == UINT32_MAX) return 1;
    if (!g_q1_0_ssd_wrap.enabled ||
        ring >= CUDA_Q1_0_SSD_WRAP_H2D_RING_SLOTS) {
        return 0;
    }
    const cudaError_t recorded = cudaEventRecord(
        g_q1_0_ssd_wrap.h2d_done[ring], stream);
    if (recorded != cudaSuccess) {
        (void)cudaGetLastError();
        cuda_q1_0_ssd_wrap_disable("h2d-record-event");
        return 0;
    }
    g_q1_0_ssd_wrap.h2d_pending[ring] = 1;
    g_q1_0_ssd_wrap.first_use++;
    return 1;
}

static int cuda_moe_tiering_load_to_ram(
        const cuda_moe_route_request &request,
        uint32_t layer, uint32_t expert,
        cuda_q1_0_promotion_record_context *promotion_record = NULL,
        int *admission_denied = NULL) {
    if (admission_denied) *admission_denied = 0;
    if (g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
        layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        g_dynamic_arena.slot_bytes !=
            request.gate_expert_bytes * 2ull + request.down_expert_bytes) {
        return 0;
    }
    size_t victim_entry_index = SIZE_MAX;
    int slot_i = -1;
    if (!g_moe_tiering.policy_admit_ssd_enabled) {
        /* Preserve the pre-boundary-policy path verbatim when all new
         * admission knobs are absent. */
        slot_i = cuda_moe_tiering_pick_ram_slot(
            layer, expert, &victim_entry_index, request.g133_epoch);
    } else {
        cuda_moe_tier_entry &candidate = g_moe_tiering.entries[
            cuda_moe_tiering_entry_index(layer, expert)];
        if (!cuda_moe_tiering_admit_gate(
                candidate, layer, expert,
                g_moe_tiering.policy_admit_current_ssd,
                g_moe_tiering.policy_admit_mass_bypass_ssd,
                &g_moe_tiering.admit_knocks_skips_ssd,
                &g_moe_tiering.admit_mass_bypass_ssd)) {
            if (admission_denied) *admission_denied = 1;
            if (promotion_record && promotion_record->active) {
                promotion_record->preadmit_reject_reason =
                    "ram_admit_knocks";
            }
            return 0;
        }
        slot_i = cuda_moe_tiering_pick_ram_slot_admit(
            layer, expert, &victim_entry_index, request.g133_epoch);
    }
    if (slot_i < 0) {
        if (admission_denied) *admission_denied = 1;
        if (promotion_record && promotion_record->active) {
            promotion_record->preadmit_reject_reason = "ram_admit_skip";
        }
        g_moe_tiering.ram_admit_skips++;
        return 0;
    }
    cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[(uint32_t)slot_i];
    cuda_dynamic_arena_slot_writer_guard writer_guard(&slot);
    if (cuda_dynamic_arena_slot_refs_load(&slot.cpu_lane_slot_refs) !=
            CUDA_DYNAMIC_ARENA_SLOT_WRITER) {
        if (admission_denied) *admission_denied = 1;
        g_moe_tiering.ram_admit_skips++;
        return 0;
    }
    const int replacing = victim_entry_index != SIZE_MAX;
    static thread_local std::vector<char> replacement_scratch;
    char *read_base = slot.host_ptr;
    if (replacing) {
        try {
            replacement_scratch.resize((size_t)g_dynamic_arena.slot_bytes);
        } catch (...) {
            if (promotion_record && promotion_record->active) {
                promotion_record->preadmit_reject_reason = "ram_admit_alloc";
            }
            g_moe_tiering.ram_admit_skips++;
            g_moe_tiering.failures++;
            return 0;
        }
        read_base = replacement_scratch.data();
    } else {
        slot.state = DS4_GPU_ARENA_LOADING;
        slot.layer = layer;
        slot.expert = expert;
        slot.content_generation = ++g_dynamic_arena.next_generation;
        slot.checksum = 0;
        slot.last_dma_sequence = 0;
    }
    char *host_gate = read_base;
    char *host_up = host_gate + request.gate_expert_bytes;
    char *host_down = host_up + request.gate_expert_bytes;
    uint64_t gate_src = 0;
    uint64_t up_src = 0;
    uint64_t down_src = 0;
    uint64_t destination_bytes = 0;
    if (!cuda_q1_0_promotion_checked_triplet(
            request.gate_offset, request.up_offset, request.down_offset,
            expert, request.gate_expert_bytes, request.gate_expert_bytes,
            request.down_expert_bytes, request.gate_expert_bytes,
            request.gate_expert_bytes, request.down_expert_bytes,
            g_model_file_size != 0 ? g_model_file_size :
                g_dynamic_arena.model_size,
            &gate_src, &up_src, &down_src, &destination_bytes)) {
        if (!replacing) {
            slot.state = DS4_GPU_ARENA_FREE;
            slot.layer = UINT32_MAX;
            slot.expert = UINT32_MAX;
            slot.checksum = 0;
        }
        if (promotion_record && promotion_record->active) {
            promotion_record->preadmit_reject_reason =
                "destination_offset_overflow";
        }
        g_moe_tiering.failures++;
        return 0;
    }
    if (promotion_record && promotion_record->active &&
        (promotion_record->destination_gate_offset != gate_src ||
         promotion_record->destination_up_offset != up_src ||
         promotion_record->destination_down_offset != down_src ||
         promotion_record->destination_bytes != destination_bytes)) {
        if (!replacing) {
            slot.state = DS4_GPU_ARENA_FREE;
            slot.layer = UINT32_MAX;
            slot.expert = UINT32_MAX;
            slot.checksum = 0;
        }
        promotion_record->preadmit_reject_reason =
            "destination_offset_mismatch";
        g_moe_tiering.failures++;
        return 0;
    }
    if (promotion_record && promotion_record->active) {
        promotion_record->record_id =
            ++g_iq1_promotion.q1_0_record_attempts;
        promotion_record->attempt_started = 1;
        g_iq1_promotion.q1_0_stage_attempts++;
        cuda_q1_0_promotion_record_emit(
            "attempt", "attempt", "admitted", promotion_record,
            "exact_iq2_ram_pending", (uint32_t)slot_i, 0u);
    }
    const int transport_repeat = g_model_file_valid
        ? ds4_transport_file_load_begin(layer, expert) : -1;
    int file_ok = g_model_file_valid;
    if (file_ok) {
        file_ok = cuda_pread_full(
            &g_model_file, host_gate, request.gate_expert_bytes, gate_src);
        if (file_ok) {
            ds4_transport_record_file_bytes(
                transport_repeat, request.gate_expert_bytes);
        }
    }
    if (file_ok) {
        file_ok = cuda_pread_full(
            &g_model_file, host_up, request.gate_expert_bytes, up_src);
        if (file_ok) {
            ds4_transport_record_file_bytes(
                transport_repeat, request.gate_expert_bytes);
        }
    }
    if (file_ok) {
        file_ok = cuda_pread_full(
            &g_model_file, host_down, request.down_expert_bytes, down_src);
        if (file_ok) {
            ds4_transport_record_file_bytes(
                transport_repeat, request.down_expert_bytes);
        }
    }
    if (!file_ok) {
        /* cuda_pread_full exposes only success/failure.  A short failed read
         * has no exact byte count at this call site, so flag the run. */
        ds4_transport_mark_incomplete();
        if (!replacing) {
            slot.state = DS4_GPU_ARENA_FREE;
            slot.layer = UINT32_MAX;
            slot.expert = UINT32_MAX;
            slot.checksum = 0;
        }
        if (promotion_record && promotion_record->active &&
            promotion_record->attempt_started &&
            !promotion_record->terminal_emitted) {
            g_iq1_promotion.q1_0_record_failures++;
            cuda_q1_0_promotion_record_emit(
                "failure", "failed", "pread_failed",
                promotion_record, "exact_iq2_ram_failed", UINT32_MAX, 0u);
            promotion_record->terminal_emitted = 1;
        }
        g_moe_tiering.failures++;
        return 0;
    }
    if (replacing) {
        if (victim_entry_index >= g_moe_tiering.entries.size()) {
            if (promotion_record && promotion_record->active &&
                promotion_record->attempt_started &&
                !promotion_record->terminal_emitted) {
                g_iq1_promotion.q1_0_record_failures++;
                cuda_q1_0_promotion_record_emit(
                    "failure", "failed", "victim_contract",
                    promotion_record, "exact_iq2_ram_failed", UINT32_MAX, 0u);
                promotion_record->terminal_emitted = 1;
            }
            g_moe_tiering.failures++;
            return 0;
        }
        cuda_moe_tier_entry &victim =
            g_moe_tiering.entries[victim_entry_index];
        const uint32_t victim_layer =
            (uint32_t)(victim_entry_index / 256u);
        const uint32_t victim_expert =
            (uint32_t)(victim_entry_index % 256u);
        if (victim.ram_slot != (uint32_t)slot_i ||
            victim.ram_generation != slot.content_generation ||
            slot.layer != victim_layer || slot.expert != victim_expert ||
            (slot.state != DS4_GPU_ARENA_READY &&
             slot.state != DS4_GPU_ARENA_STAGED)) {
            if (promotion_record && promotion_record->active &&
                promotion_record->attempt_started &&
                !promotion_record->terminal_emitted) {
                g_iq1_promotion.q1_0_record_failures++;
                cuda_q1_0_promotion_record_emit(
                    "failure", "failed", "victim_contract",
                    promotion_record, "exact_iq2_ram_failed", UINT32_MAX, 0u);
                promotion_record->terminal_emitted = 1;
            }
            g_moe_tiering.failures++;
            return 0;
        }
        const int victim_stays_in_vram =
            victim.state == CUDA_MOE_TIER_VRAM_PROTECTED &&
            cuda_moe_tiering_has_exact_vram(victim_layer, victim_expert);
        if (victim.state == CUDA_MOE_TIER_VRAM_PROTECTED &&
            !victim_stays_in_vram) {
            if (promotion_record && promotion_record->active &&
                promotion_record->attempt_started &&
                !promotion_record->terminal_emitted) {
                g_iq1_promotion.q1_0_record_failures++;
                cuda_q1_0_promotion_record_emit(
                    "failure", "failed", "victim_contract",
                    promotion_record, "exact_iq2_ram_failed", UINT32_MAX, 0u);
                promotion_record->terminal_emitted = 1;
            }
            g_moe_tiering.failures++;
            return 0;
        }
        victim.ram_slot = UINT32_MAX;
        victim.ram_generation = 0;
        victim.has_2bit_ram = 0;
        if (victim_stays_in_vram) {
            /* The exact device copy remains authoritative. Reclaim only the
             * duplicate RAM backing; a later VRAM demotion will fall
             * back to snapshot backing or SSD as appropriate. */
            victim.vram_eligible_after_call = 0;
            victim.promoted_from_iq1_cold = 0;
            g_moe_tiering.general_backing_reclaims++;
            if (g_iq1_promotion.requested_slots != 0u) {
                g_iq1_promotion.probation_backing_reclaims++;
            }
        } else {
            victim.vram_eligible_after_call = 0;
            victim.promoted_from_iq1_cold = 0;
            victim.state = CUDA_MOE_TIER_SSD_COLD;
        }
        slot.state = DS4_GPU_ARENA_LOADING;
        slot.layer = layer;
        slot.expert = expert;
        slot.content_generation = ++g_dynamic_arena.next_generation;
        slot.checksum = 0;
        slot.last_dma_sequence = 0;
        memcpy(slot.host_ptr, replacement_scratch.data(),
               (size_t)g_dynamic_arena.slot_bytes);
        g_moe_tiering.ram_evictions++;
        if (g_moe_tiering.policy_admit_ssd_enabled) {
            g_moe_tiering.admit_replaced_worse_ssd++;
            g_moe_tiering.policy_admit_window_replacements_ssd++;
        }
        if (g_moe_tiering.g133_enabled) {
            cuda_g133_telemetry_increment(g_cuda_g133_telemetry.reaps);
        }
    }
    slot.checksum = cuda_dynamic_arena_fnv1a64(
        (const uint8_t *)slot.host_ptr, g_dynamic_arena.slot_bytes);
    slot.state = DS4_GPU_ARENA_READY;
    cuda_moe_tier_entry &entry =
        g_moe_tiering.entries[cuda_moe_tiering_entry_index(layer, expert)];
    entry.ram_slot = (uint32_t)slot_i;
    entry.ram_generation = slot.content_generation;
    entry.vram_eligible_after_call = 0;
    entry.has_2bit_ram = 1;
    entry.state = g_moe_tiering.g133_enabled &&
            cuda_g133_ram_candidate(entry, request.g133_epoch)
        ? CUDA_MOE_TIER_RAM_WARM : CUDA_MOE_TIER_RAM_PROBATION;
    if (entry.state == CUDA_MOE_TIER_RAM_WARM) {
        cuda_g133_mark_promotion(entry, request.g133_epoch);
        g_moe_tiering.ram_to_warm++;
    }
    if (g_moe_tiering.policy_admit_ssd_enabled && !replacing) {
        g_moe_tiering.policy_admit_window_free_ssd++;
    }
    g_moe_tiering.cold_to_ram++;
    g_moe_tiering.ssd_bytes += g_dynamic_arena.slot_bytes;
    return 1;
}

static cuda_moe_tier_state cuda_moe_tiering_observe_route(
        uint32_t layer, uint32_t expert, float weight,
        const ds4_gpu_g133_epoch &g133_epoch) {
    cuda_moe_tier_entry &entry =
        g_moe_tiering.entries[cuda_moe_tiering_entry_index(layer, expert)];
    const cuda_moe_tier_state prior = entry.state;
    if (g_moe_tiering.policy_admit_enabled) {
        (void)cuda_moe_tiering_admit_note(layer, expert);
    }
    if (g_moe_tiering.g133_enabled && cuda_g133_epoch_valid(g133_epoch)) {
        cuda_g133_record_observation(entry, g133_epoch, (double)weight);
    }
    if (prior == CUDA_MOE_TIER_SSD_COLD) g_moe_tiering.cold++;
    else if (prior == CUDA_MOE_TIER_VRAM_PROTECTED) g_moe_tiering.vram_hits++;
    else g_moe_tiering.ram_hits++;
    entry.mass = entry.mass * 0.95 + fabs((double)weight);
    entry.last_weight = weight;
    entry.frequency++;
    entry.last_call = g_moe_tiering.call_tick;
    if (g_moe_tiering.policy_admit_warm_enabled &&
        entry.state == CUDA_MOE_TIER_RAM_PROBATION &&
        g_moe_tiering.policy_admit_current_warm != 0u) {
        if (cuda_moe_tiering_admit_gate(
                entry, layer, expert,
                g_moe_tiering.policy_admit_current_warm,
                g_moe_tiering.policy_admit_mass_bypass_warm,
                &g_moe_tiering.admit_knocks_skips_warm,
                &g_moe_tiering.admit_mass_bypass_warm)) {
            entry.state = CUDA_MOE_TIER_RAM_WARM;
            g_moe_tiering.ram_to_warm++;
            g_moe_tiering.policy_admit_window_free_warm++;
        }
    }
    if (g_moe_tiering.g133_enabled && cuda_g133_epoch_valid(g133_epoch)) {
        if ((!g_moe_tiering.policy_admit_warm_enabled ||
             g_moe_tiering.policy_admit_current_warm == 0u) &&
            entry.state == CUDA_MOE_TIER_RAM_PROBATION &&
            cuda_g133_ram_candidate(entry, g133_epoch)) {
            entry.state = CUDA_MOE_TIER_RAM_WARM;
            cuda_g133_mark_promotion(entry, g133_epoch);
            g_moe_tiering.ram_to_warm++;
        }
        cuda_g133_telemetry_increment(g_cuda_g133_telemetry.selected);
        if (prior == CUDA_MOE_TIER_VRAM_PROTECTED) {
            cuda_g133_telemetry_increment(g_cuda_g133_telemetry.vram_hits);
        } else if (prior == CUDA_MOE_TIER_RAM_PROBATION ||
                   prior == CUDA_MOE_TIER_RAM_WARM) {
            cuda_g133_telemetry_increment(g_cuda_g133_telemetry.ram_hits);
        }
    }
    return prior;
}

static uint64_t cuda_iq1_promotion_current_request_epoch(void) {
    return g_cuda_request_epoch;
}

static uint64_t cuda_iq1_promotion_current_window_epoch(void) {
    if (g_iq1_promotion.window_calls == 0u) return 0u;
    const uint64_t tick =
        g_moe_tiering.call_tick == 0u ? 1u : g_moe_tiering.call_tick;
    return (tick - 1u) / g_iq1_promotion.window_calls;
}

static uint64_t cuda_iq1_promotion_next_call_tick(void) {
    return g_moe_tiering.call_tick == UINT64_MAX ? UINT64_MAX :
        g_moe_tiering.call_tick + 1u;
}

static int cuda_moe_tiering_advance_call_tick(const char *site) {
    if (g_moe_tiering.call_tick == UINT64_MAX) {
        g_moe_tiering.failures++;
        fprintf(stderr,
                "ds4: [expert-tiering] result=failed "
                "reason=call_tick_overflow site=%s call_tick=%llu\n",
                site ? site : "unknown",
                (unsigned long long)g_moe_tiering.call_tick);
        return 0;
    }
    g_moe_tiering.call_tick++;
    return 1;
}

static int cuda_q1_0_promotion_structural_reject_reason(
        const char *reason) {
    return reason &&
        (!strcmp(reason, "ram_admit_alloc") ||
         !strcmp(reason, "destination_offset_overflow") ||
         !strcmp(reason, "destination_offset_mismatch"));
}

static void cuda_q1_0_promotion_record_emit(
        const char *kind, const char *result, const char *reason,
        const cuda_q1_0_promotion_record_context *record,
        const char *destination_kind,
        uint32_t destination_ram_slot, uint64_t destination_ram_generation) {
    if (!record || !record->active) return;
    fprintf(stderr,
            "ds4: [q1-0-promotion-record] kind=%s result=%s reason=%s "
            "record_id=%llu request_epoch=%llu promotion_window_epoch=%llu "
            "current_call=%llu "
            "observation_call=%llu first_eligible_call=%llu "
            "layer=%u expert=%u touch_count=%llu weight=%.9g mass=%.9g "
            "gate_min_touches=%llu gate_min_weight=%.9g gate_min_mass=%.9g "
            "gate_request_budget=%llu gate_request_used=%llu "
            "gate_window_calls=%llu gate_window_budget=%llu "
            "gate_window_used=%llu source_kind=q1_resident "
            "source_sidecar_sha256=%s source_sidecar_size=%llu "
            "source_q1_snapshot=0 source_gate_base_offset=%llu "
            "source_up_base_offset=%llu source_down_base_offset=%llu "
            "source_gate_stride=%llu source_up_stride=%llu "
            "source_down_stride=%llu source_gate_offset=%llu "
            "source_up_offset=%llu source_down_offset=%llu "
            "source_gate_bytes=%llu source_up_bytes=%llu "
            "source_down_bytes=%llu source_bytes=%llu "
            "destination_kind=%s destination_model_sha256=%s "
            "destination_model_size=%llu destination_gate_base_offset=%llu "
            "destination_up_base_offset=%llu "
            "destination_down_base_offset=%llu "
            "destination_gate_stride=%llu destination_up_stride=%llu "
            "destination_down_stride=%llu destination_gate_offset=%llu "
            "destination_up_offset=%llu destination_down_offset=%llu "
            "destination_gate_bytes=%llu destination_up_bytes=%llu "
            "destination_down_bytes=%llu destination_bytes=%llu "
            "destination_ram_slot=%u destination_ram_generation=%llu "
            "direct_ssd_to_vram_current_token=0 same_call_eligible=0\n",
            kind, result, reason,
            (unsigned long long)record->record_id,
            (unsigned long long)record->request_epoch,
            (unsigned long long)record->promotion_window_epoch,
            (unsigned long long)record->current_call,
            (unsigned long long)record->observation_call,
            (unsigned long long)record->first_eligible_call,
            record->layer, record->expert,
            (unsigned long long)record->touch_count,
            record->weight, record->mass,
            (unsigned long long)g_iq1_promotion.min_touches,
            g_iq1_promotion.min_weight,
            g_iq1_promotion.min_mass,
            (unsigned long long)g_iq1_promotion.request_budget,
            (unsigned long long)record->gate_request_used,
            (unsigned long long)g_iq1_promotion.window_calls,
            (unsigned long long)g_iq1_promotion.window_budget,
            (unsigned long long)record->gate_window_used,
            cuda_env_text_or_unknown("DS4_Q1_0_EXPERT_SIDECAR_SHA256"),
            (unsigned long long)record->source_sidecar_size,
            (unsigned long long)record->source_gate_base_offset,
            (unsigned long long)record->source_up_base_offset,
            (unsigned long long)record->source_down_base_offset,
            (unsigned long long)record->source_gate_stride,
            (unsigned long long)record->source_up_stride,
            (unsigned long long)record->source_down_stride,
            (unsigned long long)record->source_gate_offset,
            (unsigned long long)record->source_up_offset,
            (unsigned long long)record->source_down_offset,
            (unsigned long long)record->source_gate_bytes,
            (unsigned long long)record->source_up_bytes,
            (unsigned long long)record->source_down_bytes,
            (unsigned long long)record->source_bytes,
            destination_kind,
            cuda_env_text_or_unknown("DS4_MODEL_SHA256"),
            (unsigned long long)record->destination_model_size,
            (unsigned long long)record->destination_gate_base_offset,
            (unsigned long long)record->destination_up_base_offset,
            (unsigned long long)record->destination_down_base_offset,
            (unsigned long long)record->destination_gate_stride,
            (unsigned long long)record->destination_up_stride,
            (unsigned long long)record->destination_down_stride,
            (unsigned long long)record->destination_gate_offset,
            (unsigned long long)record->destination_up_offset,
            (unsigned long long)record->destination_down_offset,
            (unsigned long long)record->destination_gate_bytes,
            (unsigned long long)record->destination_up_bytes,
            (unsigned long long)record->destination_down_bytes,
            (unsigned long long)record->destination_bytes,
            destination_ram_slot,
            (unsigned long long)destination_ram_generation);
}

static void cuda_q1_0_promotion_record_emit(
        const char *kind, const char *result, const char *reason,
        uint64_t record_id, uint32_t layer, uint32_t expert, float weight,
        uint64_t touch_count, double mass, uint64_t first_eligible_call,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        uint64_t q1_gate_offset, uint64_t q1_up_offset,
        uint64_t q1_down_offset, uint64_t q1_gate_expert_bytes,
        uint64_t q1_down_expert_bytes, const char *destination_kind,
        uint32_t destination_ram_slot, uint64_t destination_ram_generation) {
    cuda_q1_0_promotion_record_context record;
    (void)cuda_q1_0_promotion_record_context_init(
        &record, layer, expert, weight, touch_count, mass,
        first_eligible_call, gate_offset, up_offset, down_offset,
        gate_expert_bytes, down_expert_bytes, q1_gate_offset,
        q1_up_offset, q1_down_offset, q1_gate_expert_bytes,
        q1_down_expert_bytes);
    record.active = 1;
    record.record_id = record_id;
    cuda_q1_0_promotion_record_emit(
        kind, result, reason, &record, destination_kind,
        destination_ram_slot, destination_ram_generation);
}

static int cuda_moe_tiering_stage_observed_quant_cold_to_2bit_ram(
        uint32_t layer, uint32_t expert, float weight,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        int q1_0_source,
        uint64_t q1_gate_offset, uint64_t q1_up_offset,
        uint64_t q1_down_offset, uint64_t q1_gate_expert_bytes,
        uint64_t q1_down_expert_bytes) {
    if (g_iq1_promotion.requested_slots == 0u) return 1;
    if (g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
        !g_moe_tiering.compose_prefill_mass_tiering ||
        !g_moe_tiering.compose_router_open ||
        layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        g_dynamic_arena.slot_bytes !=
            gate_expert_bytes * 2ull + down_expert_bytes) {
        if (q1_0_source) {
            const uint64_t record_id =
                ++g_iq1_promotion.q1_0_record_rejects;
            cuda_q1_0_promotion_record_emit(
                "reject", "rejected", "entry_contract", record_id,
                layer, expert, weight, 0u, 0.0, 0u,
                gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes,
                q1_gate_offset, q1_up_offset, q1_down_offset,
                q1_gate_expert_bytes, q1_down_expert_bytes,
                "none", UINT32_MAX, 0u);
        }
        g_iq1_promotion.failures++;
        return 0;
    }

    g_iq1_promotion.cold_observed++;
    if (q1_0_source) g_iq1_promotion.q1_0_observed++;
    cuda_moe_tier_entry &entry = g_moe_tiering.entries[
        cuda_moe_tiering_entry_index(layer, expert)];
    cuda_q1_0_promotion_record_context q1_record;
    memset(&q1_record, 0, sizeof(q1_record));
    const uint64_t first_eligible_call =
        cuda_iq1_promotion_next_call_tick();
    if (q1_0_source) {
        if (cuda_iq1_promotion_current_request_epoch() == 0u) {
            const uint64_t record_id =
                ++g_iq1_promotion.q1_0_record_rejects;
            cuda_q1_0_promotion_record_emit(
                "reject", "rejected", "request_epoch_missing", record_id,
                layer, expert, weight, entry.frequency, entry.mass, 0u,
                gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes,
                q1_gate_offset, q1_up_offset, q1_down_offset,
                q1_gate_expert_bytes, q1_down_expert_bytes,
                "none", UINT32_MAX, 0u);
            g_iq1_promotion.failures++;
            return 0;
        }
        if (g_moe_tiering.call_tick == UINT64_MAX ||
            first_eligible_call == UINT64_MAX) {
            const uint64_t record_id =
                ++g_iq1_promotion.q1_0_record_rejects;
            cuda_q1_0_promotion_record_emit(
                "reject", "rejected", "call_tick_overflow", record_id,
                layer, expert, weight, entry.frequency, entry.mass, 0u,
                gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes,
                q1_gate_offset, q1_up_offset, q1_down_offset,
                q1_gate_expert_bytes, q1_down_expert_bytes,
                "none", UINT32_MAX, 0u);
            g_iq1_promotion.failures++;
            return 0;
        }
    }
    if (entry.state == CUDA_MOE_TIER_VRAM_PROTECTED) {
        g_iq1_promotion.cold_existing_2bit++;
        return 1;
    }

    char *host_gate = NULL;
    char *host_up = NULL;
    char *host_down = NULL;
    const int from_snapshot = cuda_moe_tiering_snapshot_ram_ptrs(
        layer, expert, &host_gate, &host_up, &host_down);
    const int from_probation = !from_snapshot && cuda_moe_tiering_ram_ptrs(
        layer, expert, &host_gate, &host_up, &host_down);
    if (from_snapshot || from_probation) {
        entry.has_2bit_ram = 1;
        entry.promoted_from_iq1_cold = 1;
        entry.vram_eligible_after_call =
            cuda_iq1_promotion_next_call_tick();
        g_iq1_promotion.cold_existing_2bit++;
        return 1;
    }

    g_iq1_promotion.cold_gate_candidates++;
    const double abs_weight = fabs((double)weight);
    if (abs_weight >= 0.01) g_iq1_promotion.weight_ge_001++;
    if (abs_weight >= 0.02) g_iq1_promotion.weight_ge_002++;
    if (abs_weight >= 0.05) g_iq1_promotion.weight_ge_005++;
    if (abs_weight >= 0.10) g_iq1_promotion.weight_ge_010++;
    if (entry.frequency < g_iq1_promotion.min_touches) {
        g_iq1_promotion.skips_touches++;
        return 1;
    }
    if (abs_weight < g_iq1_promotion.min_weight) {
        g_iq1_promotion.skips_weight++;
        return 1;
    }
    if (entry.mass < g_iq1_promotion.min_mass) {
        g_iq1_promotion.skips_mass++;
        return 1;
    }
    if (g_iq1_promotion.request_budget != 0u &&
        g_iq1_promotion.request_used >= g_iq1_promotion.request_budget) {
        g_iq1_promotion.skips_request_budget++;
        return 1;
    }
    if (g_iq1_promotion.window_calls != 0u) {
        const uint64_t tick =
            g_moe_tiering.call_tick == 0u ? 1u : g_moe_tiering.call_tick;
        const uint64_t epoch =
            (tick - 1u) / g_iq1_promotion.window_calls;
        if (epoch != g_iq1_promotion.window_epoch) {
            g_iq1_promotion.window_epoch = epoch;
            g_iq1_promotion.window_used = 0u;
        }
        if (g_iq1_promotion.window_used >= g_iq1_promotion.window_budget) {
            g_iq1_promotion.skips_window_budget++;
            return 1;
        }
    }

    if (q1_0_source &&
        !cuda_q1_0_promotion_record_context_init(
            &q1_record, layer, expert, weight,
            entry.frequency, entry.mass, first_eligible_call,
            gate_offset, up_offset, down_offset, gate_expert_bytes,
            down_expert_bytes, q1_gate_offset, q1_up_offset,
            q1_down_offset, q1_gate_expert_bytes,
            q1_down_expert_bytes)) {
        const uint64_t record_id =
            ++g_iq1_promotion.q1_0_record_rejects;
        cuda_q1_0_promotion_record_emit(
            "reject", "rejected", "offset_overflow", record_id,
            layer, expert, weight, entry.frequency, entry.mass, 0u,
            gate_offset, up_offset, down_offset,
            gate_expert_bytes, down_expert_bytes,
            q1_gate_offset, q1_up_offset, q1_down_offset,
            q1_gate_expert_bytes, q1_down_expert_bytes,
            "none", UINT32_MAX, 0u);
        g_iq1_promotion.failures++;
        return 0;
    }

    entry.ram_slot = UINT32_MAX;
    entry.ram_generation = 0;
    entry.vram_eligible_after_call = 0;
    entry.has_2bit_ram = 0;
    entry.state = CUDA_MOE_TIER_SSD_COLD;
    cuda_moe_route_request request;
    memset(&request, 0, sizeof(request));
    request.layer_index = layer;
    request.gate_offset = gate_offset;
    request.up_offset = up_offset;
    request.down_offset = down_offset;
    request.gate_expert_bytes = gate_expert_bytes;
    request.down_expert_bytes = down_expert_bytes;
    if (q1_0_source) {
        const int ssd_wrap_requested = cuda_q1_0_ssd_wrap_requested();
        if (ssd_wrap_requested < 0) {
            g_iq1_promotion.failures++;
            return 0;
        }
        if (ssd_wrap_requested == 1) {
            const int submitted = cuda_q1_0_ssd_wrap_submit(
                request, layer, expert, &q1_record);
            if (submitted == 0) {
                g_iq1_promotion.failures++;
                return 0;
            }
            if (submitted == 1) {
                if (g_iq1_promotion.request_budget != 0u) {
                    g_iq1_promotion.request_used++;
                }
                if (g_iq1_promotion.window_calls != 0u) {
                    g_iq1_promotion.window_used++;
                }
            }
            /* Dedup and bounded backpressure deliberately retain the resident
             * Q1 representation. A queued attempt becomes visible only from
             * a later mixed-resolver call after poll/commit. */
            return 1;
        }
    }
    const double stage_started = cuda_wall_sec();
    if (!cuda_moe_tiering_load_to_ram(
            request, layer, expert,
            q1_0_source ? &q1_record : NULL)) {
        g_iq1_promotion.promotion_2bit_ssd_seconds +=
            cuda_wall_sec() - stage_started;
        if (q1_0_source && q1_record.active &&
            !q1_record.attempt_started && !q1_record.terminal_emitted &&
            cuda_q1_0_promotion_structural_reject_reason(
                q1_record.preadmit_reject_reason)) {
            q1_record.record_id =
                ++g_iq1_promotion.q1_0_record_rejects;
            cuda_q1_0_promotion_record_emit(
                "reject", "rejected", q1_record.preadmit_reject_reason,
                &q1_record, "none", UINT32_MAX, 0u);
            q1_record.terminal_emitted = 1;
        }
        g_iq1_promotion.failures++;
        return 0;
    }
    g_iq1_promotion.promotion_2bit_ssd_seconds +=
        cuda_wall_sec() - stage_started;
    entry.has_2bit_ram = 1;
    entry.promoted_from_iq1_cold = 1;
    entry.vram_eligible_after_call = first_eligible_call;
    g_iq1_promotion.cold_to_2bit_ram++;
    if (q1_0_source) {
        g_iq1_promotion.q1_0_stage_successes++;
        g_iq1_promotion.q1_0_next_call_guards++;
        g_iq1_promotion.q1_0_record_successes++;
        cuda_q1_0_promotion_record_emit(
            "success", "success", "staged", &q1_record,
            "exact_iq2_ram", entry.ram_slot, entry.ram_generation);
        q1_record.terminal_emitted = 1;
    }
    g_iq1_promotion.promotion_2bit_ssd_bytes +=
        gate_expert_bytes * 2ull + down_expert_bytes;
    if (g_iq1_promotion.request_budget != 0u) {
        g_iq1_promotion.request_used++;
    }
    if (g_iq1_promotion.window_calls != 0u) {
        g_iq1_promotion.window_used++;
    }
    return 1;
}

static int cuda_moe_tiering_stage_iq1_cold_to_2bit_ram(
        uint32_t layer, uint32_t expert, float weight,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        const ds4_gpu_g133_epoch &g133_epoch) {
    if (g_iq1_promotion.requested_slots == 0u) return 1;
    if (g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
        !g_moe_tiering.compose_prefill_mass_tiering ||
        !g_moe_tiering.compose_router_open ||
        layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        g_dynamic_arena.slot_bytes !=
            gate_expert_bytes * 2ull + down_expert_bytes) {
        g_iq1_promotion.failures++;
        return 0;
    }
    g_moe_tiering.selected++;
    (void)cuda_moe_tiering_observe_route(
        layer, expert, weight, g133_epoch);
    return cuda_moe_tiering_stage_observed_quant_cold_to_2bit_ram(
        layer, expert, weight,
        gate_offset, up_offset, down_offset,
        gate_expert_bytes, down_expert_bytes, 0,
        0u, 0u, 0u, 0u, 0u);
}

static void cuda_moe_tiering_demote_cache_entry(
        uint32_t layer, uint32_t expert,
        const ds4_gpu_g133_epoch &g133_epoch = ds4_gpu_g133_epoch{}) {
    if (g_moe_tiering.mode == CUDA_MOE_TIER_OFF ||
        layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u) return;
    cuda_moe_tier_entry &entry =
        g_moe_tiering.entries[cuda_moe_tiering_entry_index(layer, expert)];
    if (entry.state != CUDA_MOE_TIER_VRAM_PROTECTED) return;
    cuda_g133_refresh_entry(entry, g133_epoch);
    if (entry.ram_slot < g_dynamic_arena.slots.size()) {
        entry.state = CUDA_MOE_TIER_RAM_WARM;
        cuda_g133_mark_promotion(entry, g133_epoch);
    } else {
        char *snapshot_gate = NULL;
        char *snapshot_up = NULL;
        char *snapshot_down = NULL;
        if (cuda_moe_tiering_snapshot_ram_ptrs(
                layer, expert,
                &snapshot_gate, &snapshot_up, &snapshot_down)) {
            entry.state = CUDA_MOE_TIER_RAM_PROBATION;
            entry.has_2bit_ram = 1;
        } else {
            entry.state = CUDA_MOE_TIER_SSD_COLD;
            entry.vram_eligible_after_call = 0;
            entry.has_2bit_ram = 0;
            entry.promoted_from_iq1_cold = 0;
        }
    }
    g_moe_tiering.vram_demotions++;
    if (g_moe_tiering.g133_enabled) {
        cuda_g133_telemetry_increment(g_cuda_g133_telemetry.reaps);
    }
}

static void cuda_moe_expert_cache_invalidate(const char *site) {
    /* DRAIN3-STRUM: ogni invalidazione azzera la residenza e forza il refill
     * all-miss dei layer successivi.  Nei run degradati del 28/7 e' il bordo
     * del ciclo invalidate -> all-miss -> guardiano -> invalidate, finora
     * invisibile nei contatori.  A flag spento resta un ramo su int cachato.
     *
     * INVALIDATE-STRUM: il sito chiamante e le voci VALID/LOADING buttate
     * rendono ogni evento giudicabile da solo: i due reset di avvio
     * (set-model-file, expert-cache-prepare) buttano zero voci per
     * costruzione, quelli dei percorsi di fallimento riportano il costo
     * reale.  Telemetria sotto lo stesso guardiano DS4_CUDA_WORKER_PROFILE
     * gia' usato dal contatore. */
    if (cuda_worker_profile_enabled()) {
        ds4_workerprof_add(WP_CACHE_INVALIDATES, 1u);
    }
    uint32_t invalidate_valid_dropped = 0u;
    uint32_t invalidate_loading_dropped = 0u;
    for (cuda_moe_cache_slot &slot : g_moe_expert_cache.slots) {
        if (slot.state == CUDA_MOE_CACHE_VALID) {
            invalidate_valid_dropped++;
        } else if (slot.state == CUDA_MOE_CACHE_LOADING) {
            invalidate_loading_dropped++;
        }
        if (slot.state == CUDA_MOE_CACHE_VALID &&
            slot.layer_index < CUDA_MOE_LAYER_COUNT &&
            slot.expert_id < 256u) {
            cuda_moe_tiering_demote_cache_entry(
                slot.layer_index, slot.expert_id);
        }
        slot.state = CUDA_MOE_CACHE_EMPTY;
        slot.age = 0;
        slot.layer_key = 0;
        slot.layer_index = UINT32_MAX;
        slot.expert_id = UINT32_MAX;
        slot.layer_owned = 0;
    }
    std::fill(g_moe_expert_cache.host_slot_by_layer_expert.begin(),
              g_moe_expert_cache.host_slot_by_layer_expert.end(), -1);
    if (g_moe_expert_cache.device_slot_by_layer_expert) {
        (void)cudaMemset(g_moe_expert_cache.device_slot_by_layer_expert, 0xff,
                         (size_t)CUDA_MOE_LAYER_COUNT * 256u * sizeof(int32_t));
    }
    if (g_moe_expert_cache.route_ready_host) {
        *g_moe_expert_cache.route_ready_host = 0;
    }
    if (g_moe_expert_cache.route_failed_host) {
        *g_moe_expert_cache.route_failed_host = 0;
    }
    if (g_moe_expert_cache.route_request_host) {
        memset(g_moe_expert_cache.route_request_host, 0,
               sizeof(*g_moe_expert_cache.route_request_host));
    }
    if (g_moe_expert_cache.device_route_hit_mask) {
        (void)cudaMemset(g_moe_expert_cache.device_route_hit_mask, 0, sizeof(uint32_t));
    }
    g_moe_expert_cache.route_g73_outcome_sequence = 0u;
    g_moe_expert_cache.route_g73_outcomes = cuda_g73_route_outcomes{};
    g_moe_expert_cache.tick = 0;
    g_moe_expert_cache.count = 0;
    if (cuda_worker_profile_enabled()) {
        ds4_workerprof_add(WP_CACHE_FULL_VALID_DROPPED,
                           invalidate_valid_dropped);
        fprintf(stderr,
                "ds4: [cache-invalidate] scope=full site=%s valid_dropped=%u "
                "loading_dropped=%u\n",
                site ? site : "unattributed",
                invalidate_valid_dropped, invalidate_loading_dropped);
    }
}

/* =======================================================================
 * DRAIN4 (DS4_CUDA_DRAIN_OVERLAP4=1, opt-in) — drain sovrapposto al compute.
 *
 * Il worker smette di drenare route_upload_stream in modo bloccante prima
 * di pubblicare route_ready: registra un evento CUDA sull'upload stream
 * (dopo l'ultimo publish) e il consumer accoda cudaStreamWaitEvent su
 * stream 0 prima dei kernel che dereferenziano slot o route_ptrs in volo.
 * Lo spigolo di visibilita' (I1) passa da host a device; la transazione
 * slot LOADING->VALID (I2) diventa ottimistica ed e' legale perche' l'unico
 * lettore (i kernel consumer) sta dietro il waitEvent e l'unico riciclatore
 * (il worker alla generazione successiva) sta dietro il claim-gate, il cui
 * done-event su stream 0 sta — in ordine di stream — DOPO il waitEvent e
 * quindi prova transitivamente il completamento fisico degli upload (I3).
 * Il registro dei trasporti non riceve batch non provati: sotto overlap il
 * batch e' invalidato, versione minima dichiarata (I4).
 *
 * Forma: quarto parametro di template DOV su route worker / enforce /
 * finish / submit / launch_impl, selezionato UNA VOLTA in
 * cuda_g73_route_dispatch_init come G132 e SCOPED.  Ogni riga nuova sta in
 * `if constexpr (DOV)`: nelle istanze false il codice non esiste nel
 * percorso compilato.  Lo stato vive in QUESTO sidecar globale, mai dentro
 * cuda_moe_expert_cache (lezione dei due tentativi morti: niente slittamenti
 * di layout condiviso).  Scrittori: solo il thread worker (arm/retire) e i
 * campi consumer_* solo il thread di decode; il consumer legge il resto con
 * acquire.  Zero-inizializzato a memoria statica come g_workerprof_c.
 * ======================================================================= */
struct cuda_moe_drain_overlap4_state {
    /* Un evento per parita' di generazione: il riuso della stessa parita'
     * (N e N+2) e' serializzato dal claim-gate, quindi il record di N+2 non
     * puo' precedere l'esecuzione del waitEvent di N. */
    cudaEvent_t ready_event[2];
    int events_created;
    int transport_note_emitted;
    /* Generazione armata (0 = niente in volo), pubblicata con release dopo
     * i timestamp; complete_ns==0 con armed!=0 significa overlap ancora
     * outstanding. */
    std::atomic<uint64_t> armed_generation;
    std::atomic<uint64_t> armed_ns;
    std::atomic<uint64_t> complete_ns;
    /* Solo thread di decode: finestra della sync del resolver usata per
     * gpu_stall_on_drain_ms. */
    uint64_t consumer_sync_started_ns;
};
static cuda_moe_drain_overlap4_state g_moe_drain_overlap4;

static int cuda_moe_drain_overlap4_requested(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_DRAIN_OVERLAP4");
        cached = env && strcmp(env, "1") == 0;
    }
    return cached;
}

static int cuda_moe_drain_overlap4_events_ready(void) {
    return g_moe_drain_overlap4.events_created &&
        g_moe_drain_overlap4.ready_event[0] &&
        g_moe_drain_overlap4.ready_event[1];
}

/* Creazione SOLO a flag acceso, dalla prepare (come drain2 righe 107-113,
 * la parte giudicata giusta).  Fallimento = niente eventi = ogni arm
 * ricade sul drain bloccante; la prepare non viene bocciata. */
static cudaError_t cuda_moe_drain_overlap4_events_create(void) {
    if (g_moe_drain_overlap4.events_created) return cudaSuccess;
    for (uint32_t parity = 0; parity < 2u; parity++) {
        const cudaError_t event_error = cudaEventCreateWithFlags(
            &g_moe_drain_overlap4.ready_event[parity],
            cudaEventDisableTiming);
        if (event_error != cudaSuccess) {
            for (uint32_t undo = 0; undo < parity; undo++) {
                (void)cudaEventDestroy(
                    g_moe_drain_overlap4.ready_event[undo]);
                g_moe_drain_overlap4.ready_event[undo] = NULL;
            }
            g_moe_drain_overlap4.ready_event[parity] = NULL;
            return event_error;
        }
    }
    g_moe_drain_overlap4.events_created = 1;
    return cudaSuccess;
}

static void cuda_moe_drain_overlap4_events_destroy(void) {
    for (uint32_t parity = 0; parity < 2u; parity++) {
        if (g_moe_drain_overlap4.ready_event[parity]) {
            (void)cudaEventDestroy(
                g_moe_drain_overlap4.ready_event[parity]);
            g_moe_drain_overlap4.ready_event[parity] = NULL;
        }
    }
    g_moe_drain_overlap4.events_created = 0;
    g_moe_drain_overlap4.armed_generation.store(
        0u, std::memory_order_release);
    g_moe_drain_overlap4.armed_ns.store(0u, std::memory_order_relaxed);
    g_moe_drain_overlap4.complete_ns.store(0u, std::memory_order_relaxed);
    g_moe_drain_overlap4.consumer_sync_started_ns = 0u;
}

static int cuda_moe_drain_overlap4_outstanding(void) {
    return g_moe_drain_overlap4.armed_generation.load(
               std::memory_order_acquire) != 0u &&
        g_moe_drain_overlap4.complete_ns.load(
            std::memory_order_acquire) == 0u;
}

/* Chiusura della finestra di overlap (thread worker).  credit=1 quando il
 * completamento e' provato (stream query Success o claim-gate): alimenta
 * drain_overlap_ms = quota di drain avvenuta sotto il compute. */
static void cuda_moe_drain_overlap4_retire(int wprof, int credit_overlap) {
    const uint64_t now_ns = ds4_workerprof_now_ns();
    const uint64_t armed_ns = g_moe_drain_overlap4.armed_ns.load(
        std::memory_order_relaxed);
    g_moe_drain_overlap4.complete_ns.store(
        now_ns, std::memory_order_release);
    if (wprof && credit_overlap) {
        ds4_workerprof_add(WP_DRAIN_OVERLAP_NS,
                           ds4_workerprof_span_ns(armed_ns, now_ns));
    }
}

/* Loop idle del worker: UNA cudaStreamQuery per iterazione finche' l'upload
 * armato non risulta completo (contratto drain_overlap_ms di
 * .microbench/drain3/ANALISI.md §4).  Errore != NotReady: NON si inghiotte
 * e NON si azzera (§3.4) — restera' visibile al prossimo confine CUDA
 * (record del done-event del consumer o cudaEventQuery del claim); qui si
 * chiude solo la finestra di telemetria per non riloggare. */
static void cuda_moe_drain_overlap4_poll(
        cuda_moe_expert_cache *cache, int wprof) {
    if (!cache || !cache->route_upload_stream) return;
    if (g_moe_drain_overlap4.armed_generation.load(
            std::memory_order_relaxed) == 0u ||
        g_moe_drain_overlap4.complete_ns.load(
            std::memory_order_relaxed) != 0u) {
        return;
    }
    const cudaError_t status = cudaStreamQuery(cache->route_upload_stream);
    if (status == cudaErrorNotReady) return;
    if (status != cudaSuccess) {
        fprintf(stderr,
                "ds4: [drain-overlap4] result=upload-stream-error cuda=%s "
                "(errore lasciato pendente: sara' intercettato al prossimo "
                "confine done-event/claim)\n",
                cudaGetErrorString(status));
    }
    cuda_moe_drain_overlap4_retire(wprof, status == cudaSuccess);
}

/* Al claim della generazione N+1 il gate ha appena esatto
 * cudaEventQuery(route_consumer_done_event) == cudaSuccess: il done-event
 * sta, in ordine di stream 0, dopo il waitEvent dell'upload di N, quindi
 * l'upload e' fisicamente completo (I3).  Ritiro senza query aggiuntive. */
static void cuda_moe_drain_overlap4_retire_at_claim(int wprof) {
    if (g_moe_drain_overlap4.armed_generation.load(
            std::memory_order_relaxed) == 0u ||
        g_moe_drain_overlap4.complete_ns.load(
            std::memory_order_relaxed) != 0u) {
        return;
    }
    cuda_moe_drain_overlap4_retire(wprof, 1);
}

/* Fence del consumer (§3.1): se la generazione armata coincide con quella
 * sottomessa, i kernel consumer accodati DOPO questo punto su stream 0 non
 * possono eseguire prima del completamento fisico delle copie (I1).
 * Ritorna 0 solo su errore del waitEvent: il chiamante fa fail-closed
 * (cancel_and_join + invalidate) come i percorsi watchdog esistenti. */
static int cuda_moe_drain_overlap4_consumer_fence(
        cuda_moe_expert_cache *cache, uint32_t sequence, const char *site) {
    if (!cache) return 1;
    const uint64_t armed_generation =
        g_moe_drain_overlap4.armed_generation.load(
            std::memory_order_acquire);
    if (armed_generation == 0u ||
        armed_generation != cache->route_submitted_generation.load(
            std::memory_order_acquire)) {
        return 1;
    }
    cudaEvent_t ready_event =
        g_moe_drain_overlap4.ready_event[armed_generation & 1u];
    const cudaError_t wait_error = ready_event
        ? cudaStreamWaitEvent(0, ready_event, 0)
        : cudaErrorInvalidResourceHandle;
    if (wait_error == cudaSuccess) return 1;
    fprintf(stderr,
            "ds4: [drain-overlap4] result=wait-event-failed seq=%u "
            "generation=%llu site=%s cuda=%s\n",
            sequence, (unsigned long long)armed_generation,
            site ? site : "unknown", cudaGetErrorString(wait_error));
    return 0;
}

/* Telemetria gpu_stall_on_drain_ms (thread di decode, stesso punto della
 * sync del resolver gia' cronometrata in route_resolve_sync_seconds).
 * enter campiona l'overlap outstanding all'ingresso; exit attribuisce la
 * porzione [inizio sync, completamento osservato dal worker] — se il worker
 * non ha ancora stampato il completamento, l'intera sync e' il limite
 * superiore onesto, dichiarato. */
static void cuda_moe_drain_overlap4_consumer_sync_enter(void) {
    g_moe_drain_overlap4.consumer_sync_started_ns = 0u;
    if (!cuda_moe_drain_overlap4_outstanding()) return;
    g_moe_drain_overlap4.consumer_sync_started_ns = ds4_workerprof_now_ns();
}

static void cuda_moe_drain_overlap4_consumer_sync_exit(void) {
    const uint64_t started_ns = g_moe_drain_overlap4.consumer_sync_started_ns;
    if (started_ns == 0u) return;
    g_moe_drain_overlap4.consumer_sync_started_ns = 0u;
    if (!cuda_worker_profile_enabled()) return;
    const uint64_t now_ns = ds4_workerprof_now_ns();
    const uint64_t complete_ns = g_moe_drain_overlap4.complete_ns.load(
        std::memory_order_acquire);
    uint64_t stall_end_ns = now_ns;
    if (complete_ns >= started_ns && complete_ns < stall_end_ns) {
        stall_end_ns = complete_ns;
    }
    ds4_workerprof_add(WP_GPU_STALL_ON_DRAIN_NS,
                       ds4_workerprof_span_ns(started_ns, stall_end_ns));
}

static void cuda_moe_expert_cache_release(void) {
    g_model_expert_cache_ready = 0;
    if (g_moe_expert_cache.route_worker_safe_leaked.load(
            std::memory_order_acquire)) return;
    if (g_moe_expert_cache.route_thread_started) {
        const uint32_t sequence =
            g_moe_expert_cache.route_submitted_sequence.load(
                std::memory_order_acquire);
        const double request_deadline =
            g_moe_expert_cache.route_transient_read_sequence.load(
                std::memory_order_acquire) == sequence
            ? g_moe_expert_cache.route_transient_read_deadline
            : cuda_wall_sec();
        if (!cuda_moe_route_worker_cancel_and_join(
                &g_moe_expert_cache, sequence, request_deadline)) {
            return;
        }
    }
    if (g_moe_expert_cache.route_upload_stream) {
        (void)cudaStreamSynchronize(g_moe_expert_cache.route_upload_stream);
    }
    if (g_moe_expert_cache.route_consumer_done_event) {
        (void)cudaEventDestroy(
            g_moe_expert_cache.route_consumer_done_event);
    }
    /* DRAIN4: distruzione dopo la cudaStreamSynchronize dell'upload stream
     * qui sopra — nessun evento puo' essere ancora in volo.  A flag spento
     * events_created e' 0 e il ciclo di destroy non trova nulla. */
    cuda_moe_drain_overlap4_events_destroy();
#ifdef _WIN32
    for (uint32_t i = 0; i < 4u; i++) {
        if (g_moe_expert_cache.route_io_qd_event[i]) {
            (void)CloseHandle(g_moe_expert_cache.route_io_qd_event[i]);
        }
    }
#endif
    os_pread_cancellable_destroy(
        &g_moe_expert_cache.route_transient_pread);
    /* P.5a: printed next to the resident-route ledger so both arms of the A/B
     * end with the same row, mode 0 included. */
    cuda_moe_zerocopy_report("final");
    /* WORKER-PROF: riga finale CUMULATIVA (non la finestra), emessa dopo il
     * join del worker cosi' nessun contatore e' ancora in movimento. */
    ds4_workerprof_report("final");
    if (g_moe_expert_cache.route_calls != 0 ||
        g_moe_expert_cache.route_worker_jobs != 0) {
        fprintf(stderr,
                "ds4: [gpu-resident-routes] final calls=%llu split_calls=%llu all_hit=%llu worker_jobs=%llu miss_experts=%llu errors=%llu worker=%.3fms/job resolve=%.3fms/call wait=%.3fms/call queries=%llu default_sync=%llu no_default_sync=%llu cache_count=%u cache_calls=%llu cache_hits=%llu cache_misses=%llu cache_admissions=%llu cache_evictions=%llu direct_loads=%llu split_fused_calls=%llu split_fused_hits=%llu split_fused_misses=%llu split_fused_miss_scratch_bytes_avoided=%llu split_fused_sum_read_bytes_avoided=%llu packed_copy_requested=%u packed_copy_experts=%llu packed_copy_submissions=%llu packed_copy_bytes=%llu legacy_copy_submissions=%llu batched_publish_requested=%u batched_publish_kernels=%llu batched_publish_routes=%llu legacy_publish_kernels=%llu demand_pipeline_requested=%u demand_pipeline_layers=%llu demand_pipeline_routes=%llu demand_pipeline_h2d_submissions=%llu demand_pipeline_h2d_bytes=%llu demand_pipeline_publish_kernels=%llu demand_pipeline_legacy_layers=%llu g73_host_selected_requested=%u g73_host_selected_reuse=%llu g73_host_selected_fallbacks=%llu g73_classification_d2h=%llu g73_host_selected_wait=%.3fms/reuse route_io_qd_requested=%u route_io_qd_calls=%llu route_io_qd_routes=%llu route_io_qd_spans=%llu route_io_qd_submits=%llu route_io_qd_completions=%llu route_io_qd_bytes=%llu route_io_qd_failures=%llu route_io_qd_fallbacks=%llu route_io_qd_max_inflight=%u route_io_qd=%.3fms/call\n",
                (unsigned long long)g_moe_expert_cache.route_calls,
                (unsigned long long)g_moe_expert_cache.route_split_calls,
                (unsigned long long)g_moe_expert_cache.route_all_hit_observed,
                (unsigned long long)g_moe_expert_cache.route_worker_jobs,
                (unsigned long long)g_moe_expert_cache.route_miss_experts,
                (unsigned long long)g_moe_expert_cache.route_worker_errors,
                g_moe_expert_cache.route_worker_jobs ?
                    1000.0 * g_moe_expert_cache.route_worker_seconds /
                        (double)g_moe_expert_cache.route_worker_jobs : 0.0,
                g_moe_expert_cache.route_calls ?
                    1000.0 * g_moe_expert_cache.route_resolve_sync_seconds /
                        (double)g_moe_expert_cache.route_calls : 0.0,
                g_moe_expert_cache.route_calls ?
                    1000.0 * g_moe_expert_cache.route_ready_wait_seconds /
                        (double)g_moe_expert_cache.route_calls : 0.0,
                (unsigned long long)g_moe_expert_cache.route_stream_queries,
                (unsigned long long)g_moe_expert_cache.route_default_sync_calls,
                (unsigned long long)g_moe_expert_cache.route_no_default_sync_calls,
                g_moe_expert_cache.count,
                (unsigned long long)g_moe_expert_cache.calls,
                (unsigned long long)g_moe_expert_cache.hits,
                (unsigned long long)g_moe_expert_cache.misses,
                (unsigned long long)g_moe_expert_cache.admissions,
                (unsigned long long)g_moe_expert_cache.evictions,
                (unsigned long long)g_moe_expert_cache.direct_loads,
                (unsigned long long)g_moe_expert_cache.route_split_fused_calls,
                (unsigned long long)g_moe_expert_cache.route_split_fused_hits,
                (unsigned long long)g_moe_expert_cache.route_split_fused_misses,
                (unsigned long long)g_moe_expert_cache.route_split_fused_miss_scratch_bytes_avoided,
                (unsigned long long)g_moe_expert_cache.route_split_fused_sum_read_bytes_avoided,
                g_moe_expert_cache.packed_copy_requested ? 1u : 0u,
                (unsigned long long)g_moe_expert_cache.packed_copy_experts,
                (unsigned long long)g_moe_expert_cache.packed_copy_submissions,
                (unsigned long long)g_moe_expert_cache.packed_copy_bytes,
                (unsigned long long)g_moe_expert_cache.legacy_copy_submissions,
                g_moe_expert_cache.batched_publish_requested ? 1u : 0u,
                (unsigned long long)g_moe_expert_cache.batched_publish_kernels,
                (unsigned long long)g_moe_expert_cache.batched_publish_routes,
                (unsigned long long)g_moe_expert_cache.legacy_publish_kernels,
                g_moe_expert_cache.demand_pipeline_requested ? 1u : 0u,
                (unsigned long long)g_moe_expert_cache.demand_pipeline_layers,
                (unsigned long long)g_moe_expert_cache.demand_pipeline_routes,
                (unsigned long long)g_moe_expert_cache.demand_pipeline_h2d_submissions,
                (unsigned long long)g_moe_expert_cache.demand_pipeline_h2d_bytes,
                (unsigned long long)g_moe_expert_cache.demand_pipeline_publish_kernels,
                (unsigned long long)g_moe_expert_cache.demand_pipeline_legacy_layers,
                g_moe_expert_cache.g73_host_selected_requested ? 1u : 0u,
                (unsigned long long)g_moe_expert_cache.g73_host_selected_reuse,
                (unsigned long long)g_moe_expert_cache.g73_host_selected_fallbacks,
                (unsigned long long)g_moe_expert_cache.g73_classification_d2h,
                g_moe_expert_cache.g73_host_selected_reuse ?
                    1000.0 *
                        g_moe_expert_cache.g73_host_selected_wait_seconds /
                        (double)g_moe_expert_cache.g73_host_selected_reuse :
                    0.0,
                g_moe_expert_cache.route_io_qd_requested,
                (unsigned long long)g_moe_expert_cache.route_io_qd_calls,
                (unsigned long long)g_moe_expert_cache.route_io_qd_routes,
                (unsigned long long)g_moe_expert_cache.route_io_qd_spans,
                (unsigned long long)g_moe_expert_cache.route_io_qd_submits,
                (unsigned long long)g_moe_expert_cache.route_io_qd_completions,
                (unsigned long long)g_moe_expert_cache.route_io_qd_bytes,
                (unsigned long long)g_moe_expert_cache.route_io_qd_failures,
                (unsigned long long)g_moe_expert_cache.route_io_qd_fallbacks,
                g_moe_expert_cache.route_io_qd_max_inflight,
                g_moe_expert_cache.route_io_qd_calls ?
                    1000.0 * g_moe_expert_cache.route_io_qd_seconds /
                        (double)g_moe_expert_cache.route_io_qd_calls :
                    0.0);
    }
    cuda_moe_tiering_report_and_reset(1);
    if (g_moe_expert_cache.packed_base) {
        (void)cudaFree(g_moe_expert_cache.packed_base);
    } else {
        if (g_moe_expert_cache.gate) (void)cudaFree(g_moe_expert_cache.gate);
        if (g_moe_expert_cache.up) (void)cudaFree(g_moe_expert_cache.up);
        if (g_moe_expert_cache.down) (void)cudaFree(g_moe_expert_cache.down);
    }
    if (g_moe_expert_cache.device_slot_by_layer_expert) {
        (void)cudaFree(g_moe_expert_cache.device_slot_by_layer_expert);
    }
    if (g_moe_expert_cache.device_route_ptrs) {
        (void)cudaFree(g_moe_expert_cache.device_route_ptrs);
    }
    if (g_moe_expert_cache.device_route_hit_mask) {
        (void)cudaFree(g_moe_expert_cache.device_route_hit_mask);
    }
    if (g_moe_expert_cache.device_route_split_down) {
        (void)cudaFree(g_moe_expert_cache.device_route_split_down);
    }
    if (g_moe_expert_cache.route_transient_packed_base) {
        (void)cudaFree(g_moe_expert_cache.route_transient_packed_base);
    } else if (g_moe_expert_cache.route_transient_gate) {
        (void)cudaFree(g_moe_expert_cache.route_transient_gate);
    }
    if (!g_moe_expert_cache.route_transient_packed_base &&
        g_moe_expert_cache.route_transient_up) {
        (void)cudaFree(g_moe_expert_cache.route_transient_up);
    }
    if (!g_moe_expert_cache.route_transient_packed_base &&
        g_moe_expert_cache.route_transient_down) {
        (void)cudaFree(g_moe_expert_cache.route_transient_down);
    }
    if (g_moe_expert_cache.route_ready_host) {
        (void)cudaFreeHost(g_moe_expert_cache.route_ready_host);
    }
    if (g_moe_expert_cache.route_failed_host) {
        (void)cudaFreeHost(g_moe_expert_cache.route_failed_host);
    }
    if (g_moe_expert_cache.route_request_host) {
        (void)cudaFreeHost(g_moe_expert_cache.route_request_host);
    }
    if (g_moe_expert_cache.route_host_packed_base) {
        (void)cudaFreeHost(g_moe_expert_cache.route_host_packed_base);
    } else {
        if (g_moe_expert_cache.route_host_gate) (void)cudaFreeHost(g_moe_expert_cache.route_host_gate);
        if (g_moe_expert_cache.route_host_up) (void)cudaFreeHost(g_moe_expert_cache.route_host_up);
        if (g_moe_expert_cache.route_host_down) (void)cudaFreeHost(g_moe_expert_cache.route_host_down);
    }
    if (g_moe_expert_cache.route_upload_stream) {
        (void)cudaStreamDestroy(g_moe_expert_cache.route_upload_stream);
    }
