struct cuda_moe_prefill_vram_seed_entry {
    uint32_t entry;
    double prior_mass;
    double prior_weight;
};

static int cuda_moe_prefill_vram_seed(
        cuda_moe_expert_cache *cache,
        uint32_t requested_per_layer,
        uint32_t requested_total,
        uint32_t floor_per_layer) {
    const uint32_t first_layer = 3u;
    const uint32_t routed_layers = CUDA_MOE_LAYER_COUNT - first_layer;
    const int global_mode = requested_total > 0u;
    const uint64_t requested_entries_64 = global_mode
        ? (uint64_t)requested_total
        : (uint64_t)requested_per_layer * routed_layers;
    const uint32_t requested_entries =
        requested_entries_64 <= UINT32_MAX ?
        (uint32_t)requested_entries_64 : UINT32_MAX;
    const double started = cuda_wall_sec();
    const char *reason = "contract";
    uint64_t uploaded_bytes = 0;
    double selected_prior_mass = 0.0;
    const int q1_0_exact_iq2_seed =
        cuda_q1_0_mixed_exact_iq2_resolver_requested();
    const int primary_mmap_source =
        q1_0_exact_iq2_seed;
    std::vector<cuda_moe_prefill_vram_seed_entry> selected;
    std::vector<cuda_moe_prefill_vram_seed_entry> global_ranked;

    if (!cache || requested_entries == 0u ||
        (global_mode && requested_per_layer != 0u) ||
        (!global_mode && floor_per_layer != 0u) ||
        (global_mode &&
         (uint64_t)floor_per_layer * routed_layers > requested_total) ||
        g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
        g_moe_tiering.policy != CUDA_MOE_TIER_POLICY_MASS_LFRU ||
        !g_moe_tiering.compose_prefill_mass_tiering) {
        reason = "config-contract";
        goto failed;
    }
    if (!g_prefill_mass_observer.enabled ||
        !g_prefill_mass_observer.finalized ||
        !g_prefill_mass_observer.wrap_published) {
        reason = "observer-contract";
        goto failed;
    }
    if (!cache->device_slot_by_layer_expert ||
        !cache->route_upload_stream ||
        cache->capacity < requested_entries) {
        reason = "cache-capacity";
        fprintf(stderr,
                "ds4: [prefill-vram-seed-contract] cache_capacity=%u requested_entries=%u device_map=%d upload_stream=%d\n",
                cache->capacity, requested_entries,
                cache->device_slot_by_layer_expert ? 1 : 0,
                cache->route_upload_stream ? 1 : 0);
        goto failed;
    }
    if (g_dynamic_arena.snapshot_generation == 0 ||
        g_dynamic_arena.snapshot_generation !=
            g_moe_tiering.snapshot_generation ||
        g_dynamic_arena.n_layer != CUDA_MOE_LAYER_COUNT ||
        g_dynamic_arena.n_expert != 256u) {
        reason = "snapshot-contract";
        goto failed;
    }
    if (cuda_q1_0_snapshot_backing_requested() &&
        (g_primary_moe_geometry_map != g_model_host_base ||
         g_primary_moe_geometry_size != g_model_registered_size ||
         g_primary_moe_geometry_n_expert != 256u ||
         g_primary_moe_geometry.size() != CUDA_MOE_LAYER_COUNT)) {
        reason = "source-contract";
        goto failed;
    }
    if (q1_0_exact_iq2_seed &&
        !cuda_q1_0_snapshot_backing_requested() &&
        (g_dynamic_arena.backing != CUDA_DYNAMIC_ARENA_BACKING_PRIMARY ||
         g_dynamic_arena.model_map != g_model_host_base ||
         g_dynamic_arena.model_size != g_model_registered_size ||
         g_dynamic_arena.layers.size() != CUDA_MOE_LAYER_COUNT)) {
        reason = "source-contract";
        goto failed;
    }
    if (g_prefill_mass_observer.mass.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u ||
        g_prefill_mass_observer.counts.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u ||
        g_prefill_mass_observer.candidate.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u ||
        cache->host_slot_by_layer_expert.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u) {
        reason = "metadata-contract";
        goto failed;
    }

    if (g_moe_tiering.g133_enabled &&
        g_moe_tiering.g133_seed_dynamic) {
        /* Seed bounded advisory touches from the M0c observation count. The
         * prefill mass still ranks the initial seed; no position history is
         * retained by the decode controller. */
        for (uint32_t entry_index = 0;
             entry_index < g_moe_tiering.entries.size(); entry_index++) {
            cuda_moe_tier_entry &tier =
                g_moe_tiering.entries[entry_index];
            const double mass = g_prefill_mass_observer.mass[entry_index];
            const uint64_t touches =
                g_prefill_mass_observer.counts[entry_index];
            const uint64_t mass_floor = isfinite(mass) && mass > 0.0
                ? (uint64_t)mass : 0u;
            const uint64_t bounded_touches = std::min(
                std::max(touches, mass_floor),
                UINT64_MAX / CUDA_G133_TOUCH_SCALE);
            tier.g133_advisory.decayed_heat.store(
                bounded_touches * CUDA_G133_TOUCH_SCALE,
                std::memory_order_relaxed);
            const uint32_t seed_streak = (uint32_t)std::min(
                bounded_touches, CUDA_G133_STREAK_MAX);
            cuda_g133_advisory_fields seed_fields =
                cuda_g133_advisory_fields_from_epoch(ds4_gpu_g133_epoch{
                    g_cuda_request_epoch,
                    g_cuda_g133_decode_position_epoch});
            seed_fields.streak = seed_streak;
            seed_fields.promotion_age =
                (uint32_t)CUDA_G133_PROMOTION_AGE_MAX;
            tier.g133_advisory.streak_epoch.store(
                cuda_g133_advisory_pack(seed_fields),
                std::memory_order_relaxed);
        }
    }

    reason = "rank";
    try {
        selected.reserve(requested_entries);
        if (global_mode) {
            global_ranked.reserve((size_t)routed_layers * 256u);
        }
        for (uint32_t layer = first_layer;
             layer < CUDA_MOE_LAYER_COUNT; layer++) {
            std::vector<cuda_moe_prefill_vram_seed_entry> ranked;
            ranked.reserve(256u);
            const uint32_t base = layer * 256u;
            for (uint32_t expert = 0; expert < 256u; expert++) {
                const uint32_t entry = base + expert;
                if ((!q1_0_exact_iq2_seed &&
                     !g_prefill_mass_observer.candidate[entry]) ||
                    g_prefill_mass_observer.counts[entry] == 0u) {
                    continue;
                }
                const cuda_dynamic_arena_binding &binding =
                    g_dynamic_arena.active[entry];
                if (!q1_0_exact_iq2_seed &&
                    !cuda_dynamic_arena_binding_valid(
                        g_dynamic_arena,
                        binding, layer, expert,
                        g_dynamic_arena.snapshot_generation,
                        DS4_GPU_ARENA_READY)) {
                    continue;
                }
                /* Keep the same mass definition used by the prefill snapshot:
                 * normalized gate weight accumulated over the request. Dividing
                 * by observations would favor rare high-weight spikes instead
                 * of the experts expected to save the most decode H2D traffic. */
                const double prior =
                    g_prefill_mass_observer.mass[entry];
                if (!isfinite(prior) || prior <= 0.0) continue;
                const double prior_weight = prior /
                    (double)g_prefill_mass_observer.counts[entry];
                if (!isfinite(prior_weight) || prior_weight <= 0.0) continue;
                ranked.push_back({entry, prior, prior_weight});
            }
            std::sort(ranked.begin(), ranked.end(),
                      [](const cuda_moe_prefill_vram_seed_entry &a,
                         const cuda_moe_prefill_vram_seed_entry &b) {
                          if (a.prior_mass != b.prior_mass) {
                              return a.prior_mass > b.prior_mass;
                          }
                          return a.entry < b.entry;
                      });
            const uint32_t layer_floor = global_mode
                ? floor_per_layer : requested_per_layer;
            if (ranked.size() < layer_floor) goto failed;
            for (uint32_t rank = 0; rank < layer_floor; rank++) {
                selected.push_back(ranked[rank]);
                selected_prior_mass += ranked[rank].prior_mass;
            }
            if (global_mode) {
                global_ranked.insert(global_ranked.end(),
                                     ranked.begin() + layer_floor,
                                     ranked.end());
            }
        }
        if (global_mode) {
            std::sort(global_ranked.begin(), global_ranked.end(),
                      [](const cuda_moe_prefill_vram_seed_entry &a,
                         const cuda_moe_prefill_vram_seed_entry &b) {
                          if (a.prior_mass != b.prior_mass) {
                              return a.prior_mass > b.prior_mass;
                          }
                          return a.entry < b.entry;
                      });
            const uint32_t remaining = requested_total -
                (uint32_t)selected.size();
            if (global_ranked.size() < remaining) goto failed;
            for (uint32_t rank = 0; rank < remaining; rank++) {
                selected.push_back(global_ranked[rank]);
                selected_prior_mass += global_ranked[rank].prior_mass;
            }
        }
    } catch (...) {
        reason = "metadata-allocation";
        goto failed;
    }
    if (selected.size() != requested_entries) goto failed;

    reason = "upload";
    {
        std::vector<int32_t> seed_map(
            (size_t)CUDA_MOE_LAYER_COUNT * 256u, -1);
        int upload_ok = 1;
        for (uint32_t slot = 0;
             upload_ok && slot < selected.size(); slot++) {
            const uint32_t entry = selected[slot].entry;
            const uint32_t layer = entry / 256u;
            const uint32_t expert = entry % 256u;
            const ds4_gpu_dynamic_arena_layer &geometry =
                cuda_q1_0_snapshot_backing_requested()
                    ? g_primary_moe_geometry[layer]
                    : g_dynamic_arena.layers[layer];
            const cuda_dynamic_arena_binding &binding =
                g_dynamic_arena.active[entry];
            if (geometry.gate_expert_bytes != cache->gate_expert_bytes ||
                geometry.up_expert_bytes != cache->gate_expert_bytes ||
                geometry.down_expert_bytes != cache->down_expert_bytes ||
                (!primary_mmap_source &&
                 binding.slot >= g_dynamic_arena.slots.size())) {
                reason = "geometry";
                upload_ok = 0;
                break;
            }
            const uint64_t gate_dst =
                (uint64_t)slot * cache->gate_expert_bytes;
            const uint64_t down_dst =
                (uint64_t)slot * cache->down_expert_bytes;
            const char *host_gate = NULL;
            const char *host_up = NULL;
            const char *host_down = NULL;
            if (primary_mmap_source) {
                const char *base = (const char *)(
                    cuda_q1_0_snapshot_backing_requested()
                        ? g_primary_moe_geometry_map
                        : g_model_host_base);
                host_gate = base + geometry.gate_offset +
                    (uint64_t)expert * geometry.gate_expert_bytes;
                host_up = base + geometry.up_offset +
                    (uint64_t)expert * geometry.up_expert_bytes;
                host_down = base + geometry.down_offset +
                    (uint64_t)expert * geometry.down_expert_bytes;
            } else {
                const cuda_dynamic_arena_slot &arena_slot =
                    g_dynamic_arena.slots[binding.slot];
                if (!arena_slot.host_ptr) {
                    reason = "source";
                    upload_ok = 0;
                    break;
                }
                host_gate = arena_slot.host_ptr;
                host_up = host_gate + cache->gate_expert_bytes;
                host_down = host_up + cache->gate_expert_bytes;
            }
            cudaError_t copy_error = cudaMemcpyAsync(
                cache->gate + gate_dst, host_gate,
                (size_t)cache->gate_expert_bytes, cudaMemcpyHostToDevice,
                cache->route_upload_stream);
            if (copy_error == cudaSuccess) {
                copy_error = cudaMemcpyAsync(
                    cache->up + gate_dst, host_up,
                    (size_t)cache->gate_expert_bytes, cudaMemcpyHostToDevice,
                    cache->route_upload_stream);
            }
            if (copy_error == cudaSuccess) {
                copy_error = cudaMemcpyAsync(
                    cache->down + down_dst, host_down,
                    (size_t)cache->down_expert_bytes, cudaMemcpyHostToDevice,
                    cache->route_upload_stream);
            }
            if (copy_error != cudaSuccess) {
                reason = "copy";
                fprintf(stderr,
                        "ds4: prefill VRAM seed copy failed source=%s layer=%u expert=%u error=%s\n",
                        primary_mmap_source ? "primary-mmap" : "primary-arena",
                        layer, expert, cudaGetErrorString(copy_error));
                (void)cudaGetLastError();
                upload_ok = 0;
                break;
            }
            seed_map[entry] = (int32_t)slot;
        }
        if (upload_ok &&
            cudaMemcpyAsync(cache->device_slot_by_layer_expert,
                            seed_map.data(),
                            seed_map.size() * sizeof(int32_t),
                            cudaMemcpyHostToDevice,
                            cache->route_upload_stream) != cudaSuccess) {
            reason = "map-copy";
            (void)cudaGetLastError();
            upload_ok = 0;
        }
        const cudaError_t upload_sync =
            cudaStreamSynchronize(cache->route_upload_stream);
        if (!upload_ok || upload_sync != cudaSuccess) {
            if (upload_ok) reason = "sync";
            (void)cudaGetLastError();
            goto failed;
        }
        cache->host_slot_by_layer_expert.swap(seed_map);
    }

    for (uint32_t slot = 0; slot < selected.size(); slot++) {
        const uint32_t entry_index = selected[slot].entry;
        const uint32_t layer = entry_index / 256u;
        const uint32_t expert = entry_index % 256u;
        const ds4_gpu_dynamic_arena_layer &geometry =
            cuda_q1_0_snapshot_backing_requested()
                ? g_primary_moe_geometry[layer]
                : g_dynamic_arena.layers[layer];
        cuda_moe_cache_slot &cache_entry = cache->slots[slot];
        cache_entry.key = {
            geometry.gate_offset +
                (uint64_t)expert * geometry.gate_expert_bytes,
            geometry.up_offset +
                (uint64_t)expert * geometry.up_expert_bytes,
            geometry.down_offset +
                (uint64_t)expert * geometry.down_expert_bytes
        };
        cache_entry.layer_key = geometry.gate_offset;
        cache_entry.age = ++cache->tick;
        cache_entry.layer_index = layer;
        cache_entry.expert_id = expert;
        cache_entry.layer_owned = 0;
        cache_entry.state = CUDA_MOE_CACHE_VALID;

        cuda_moe_tier_entry &tier = g_moe_tiering.entries[entry_index];
        tier.frequency = 1u;
        tier.last_call = 0u;
        /* Rank by cumulative request mass, but seed the decode EMA with one
         * synthetic observation in weight units so the initial request does
         * not make the cache permanently sticky. */
        tier.mass = selected[slot].prior_weight;
        tier.last_weight = (float)selected[slot].prior_weight;
        tier.state = CUDA_MOE_TIER_VRAM_PROTECTED;
    }
    cache->count = requested_entries;
    cache->admissions += requested_entries;
    g_moe_tiering.vram_promotions += requested_entries;
    g_moe_tiering.policy_free_promotions += requested_entries;
    uploaded_bytes = (uint64_t)requested_entries *
        (cache->gate_expert_bytes * 2ull + cache->down_expert_bytes);
    g_moe_tiering.snapshot_to_vram_bytes += uploaded_bytes;
    g_moe_tiering.ram_h2d_bytes += uploaded_bytes;
    fprintf(stderr,
            "ds4: [prefill-vram-seed-source] source=%s bytes=%llu semantics=one-time-exact-iq2\n",
            primary_mmap_source ? "primary-mmap" : "primary-arena",
            (unsigned long long)uploaded_bytes);
    if (global_mode) {
        fprintf(stderr,
                "ds4: [prefill-vram-seed-global] result=ok reason=ok requested_total=%u floor_per_layer=%u layers=%u entries=%u bytes=%llu seconds=%.3f failures=0 prior_mass=%.9g semantics=request-scoped-global-mass\n",
                requested_total, floor_per_layer, routed_layers,
                requested_entries, (unsigned long long)uploaded_bytes,
                cuda_wall_sec() - started, selected_prior_mass);
    } else {
        fprintf(stderr,
                "ds4: [prefill-vram-seed] result=ok reason=ok requested_per_layer=%u layers=%u entries=%u bytes=%llu seconds=%.3f failures=0 prior_mass=%.9g semantics=request-scoped-top-per-layer\n",
                requested_per_layer, routed_layers, requested_entries,
                (unsigned long long)uploaded_bytes,
                cuda_wall_sec() - started, selected_prior_mass);
    }
    return 1;

failed:
    g_moe_tiering.failures++;
    if (global_mode) {
        fprintf(stderr,
                "ds4: [prefill-vram-seed-global] result=failed reason=%s requested_total=%u floor_per_layer=%u layers=%u entries=0 bytes=0 seconds=%.3f failures=1 prior_mass=0 semantics=request-scoped-global-mass\n",
                reason, requested_total, floor_per_layer, routed_layers,
                cuda_wall_sec() - started);
    } else {
        fprintf(stderr,
                "ds4: [prefill-vram-seed] result=failed reason=%s requested_per_layer=%u layers=%u entries=0 bytes=0 seconds=%.3f failures=1 prior_mass=0 semantics=request-scoped-top-per-layer\n",
                reason, requested_per_layer, routed_layers,
                cuda_wall_sec() - started);
    }
    return 0;
}

/* Respawn the route worker thread on an existing, otherwise-healthy cache
 * after a transient-io kill (cuda_moe_route_worker_cancel_and_join marks the
 * worker dead and nothing restarts it, so one 200ms deadline miss used to
 * poison every later decode call of the request with silent selected-load
 * fallbacks). Buffers are reused as-is; safe-leaked caches must never get
 * here (the kernel may still own their staging). */
static int cuda_moe_route_worker_respawn(cuda_moe_expert_cache *cache) {
    if (!cache || cache->route_worker_safe_leaked.load(
            std::memory_order_acquire)) return 0;
    if (!cache->route_request_device || !cache->route_ready_host ||
        !cache->route_failed_host) {
        return 0;
    }
    if (cache->route_thread_started) {
        /* Kill paths join before clearing the flag; anything else still
         * holding a thread must be joined before a new one is spawned. */
        if (!cuda_moe_route_worker_cancel_and_join(
                cache,
                cache->route_submitted_sequence.load(
                    std::memory_order_acquire),
                0.0)) {
            return 0;
        }
    }
    const uint32_t submitted_sequence =
        cache->route_submitted_sequence.load(std::memory_order_acquire);
    const uint64_t submitted_generation =
        cache->route_submitted_generation.load(std::memory_order_acquire);
    if (!cuda_moe_route_upload_stream_quiesce(
            cache, submitted_sequence, "respawn")) {
        return 0;
    }
    /* Retire the killed request so the new worker never serves a stale
     * submission; sequences stay monotonic (no reset) so the persistent
     * pread slot's old cancel_sequence can never match a future read. */
    cache->route_completed_sequence.store(
        submitted_sequence, std::memory_order_release);
    cache->route_completed_generation.store(
        submitted_generation, std::memory_order_release);
    if (submitted_generation != 0u) {
        if (!cache->route_consumer_done_event ||
            cudaEventRecord(cache->route_consumer_done_event, 0) !=
                cudaSuccess) {
            (void)cudaGetLastError();
            return 0;
        }
        cuda_moe_route_mailbox_slot &slot =
            cache->route_mailbox[submitted_generation & 1u];
        slot.generation.store(
            submitted_generation, std::memory_order_release);
        slot.state.store(
            CUDA_MOE_ROUTE_MAILBOX_UPLOAD_ENQUEUED,
            std::memory_order_release);
        cache->route_consumer_event_generation.store(
            submitted_generation, std::memory_order_release);
    }
    cache->route_transient_read_sequence.store(0u, std::memory_order_relaxed);
    cache->route_transient_io_sequence.store(0u, std::memory_order_relaxed);
    cache->route_transient_cancel_sequence.store(0u, std::memory_order_relaxed);
    cache->route_transient_timeout_cancel_sequence.store(
        0u, std::memory_order_relaxed);
    cache->route_transient_read_bytes.store(0u, std::memory_order_relaxed);
    cache->route_transient_read_deadline = 0.0;
    cache->route_stop.store(0, std::memory_order_relaxed);
    cache->route_worker_ready.store(0, std::memory_order_relaxed);
    cache->route_worker_failed.store(0, std::memory_order_relaxed);
    cuda_moe_route_memory_barrier();
    if (os_thread_create(&cache->route_thread,
                         g_cuda_moe_route_worker_dispatch, cache) != 0) {
        cache->route_worker_failed.store(1, std::memory_order_release);
        return 0;
    }
    cache->route_thread_started = 1;
    const double ready_deadline = cuda_wall_sec() + 2.0;
    while (!cache->route_worker_ready.load(std::memory_order_acquire) &&
           !cache->route_worker_failed.load(std::memory_order_acquire) &&
           cuda_wall_sec() < ready_deadline) {
#ifdef _WIN32
        (void)SwitchToThread();
#else
        usleep(0);
#endif
    }
    if (!cache->route_worker_ready.load(std::memory_order_acquire) ||
        cache->route_worker_failed.load(std::memory_order_acquire)) {
        (void)cuda_moe_route_worker_cancel_and_join(
            cache,
            cache->route_submitted_sequence.load(
                std::memory_order_acquire),
            0.0);
        return 0;
    }
    return 1;
}

static cuda_moe_expert_cache *cuda_moe_expert_cache_prepare(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (g_moe_expert_cache.route_worker_safe_leaked.load(
            std::memory_order_acquire)) return NULL;
    const uint32_t requested = cuda_moe_expert_cache_requested();
    const int tier_mode = cuda_moe_tiering_mode_requested();
    const int compose_requested = cuda_moe_prefill_tier_compose_requested();
    const int compose_router_open =
        cuda_moe_prefill_tier_router_open_requested();
    const int promotion_probation_slots =
        cuda_quant_promotion_probation_slots_requested();
    const int promotion_q1_0 =
        cuda_q1_0_dynamic_promotion_requested();
    const int gpu_routes = cuda_moe_gpu_routes_requested();
    const int packed_copy_requested = cuda_moe_route_packed_copy_requested();
    const int batched_publish_requested =
        cuda_moe_route_batched_publish_requested();
    const int demand_pipeline_requested =
        cuda_moe_demand_pipeline_requested();
    const int demand_packed_layout =
        packed_copy_requested || demand_pipeline_requested;
    const int g73_host_selected_requested =
        cuda_g73_host_selected_reuse_requested();
    const uint32_t route_io_qd_requested =
        cuda_g73_route_io_qd_requested();
    const int route_io_qd_allow_no_g73 =
        cuda_route_io_qd_allow_no_g73_requested();
    const int prefill_vram_seed_per_layer =
        cuda_moe_prefill_vram_seed_per_layer_requested();
    const int prefill_vram_seed_total =
        cuda_moe_prefill_vram_seed_total_requested();
    const int prefill_vram_seed_floor_per_layer =
        cuda_moe_prefill_vram_seed_floor_per_layer_requested();
    if (cuda_moe_expert_cache_grow_requested() &&
        !g_moe_expert_cache_decode_started &&
        g_moe_expert_cache.capacity == 0 &&
        requested != 0 &&
        gate_expert_bytes != 0 && down_expert_bytes != 0 &&
        gate_expert_bytes <=
            (UINT64_MAX - down_expert_bytes) / 2ull) {
        /*
         * Capture geometry before observer/config early returns. The
         * decode-start hook can then perform the one definitive allocation
         * immediately after prefill scratch and staged KV are released.
         */
        g_moe_expert_cache_deferred_gate_expert_bytes =
            gate_expert_bytes;
        g_moe_expert_cache_deferred_down_expert_bytes =
            down_expert_bytes;
    }
    uint64_t promotion_min_touches = 1u;
    double promotion_min_weight = 0.0;
    double promotion_min_mass = 0.0;
    uint64_t promotion_request_budget = 0u;
    uint64_t promotion_window_calls = 0u;
    uint64_t promotion_window_budget = 0u;
    if (promotion_probation_slots > 0 &&
        !cuda_quant_promotion_gate_config(
            promotion_q1_0,
            &promotion_min_touches, &promotion_min_weight,
            &promotion_min_mass, &promotion_request_budget,
            &promotion_window_calls, &promotion_window_budget)) {
        return NULL;
    }
    if (compose_requested > 0 && g_prefill_mass_observer.enabled &&
        (!g_prefill_mass_observer.finalized ||
         !g_prefill_mass_observer.wrap_published)) {
        return NULL;
    }
    if (tier_mode < 0 || compose_requested < 0 || compose_router_open < 0 ||
        promotion_probation_slots < 0 ||
        prefill_vram_seed_per_layer < 0 ||
        prefill_vram_seed_total < 0 ||
        prefill_vram_seed_floor_per_layer < 0 ||
        (tier_mode != CUDA_MOE_TIER_OFF && !gpu_routes)) {
        if (tier_mode != CUDA_MOE_TIER_OFF) {
            fprintf(stderr,
                    "ds4: expert tiering requires GPU-resident routes\n");
        }
        return NULL;
    }
    if ((prefill_vram_seed_per_layer > 0 ||
         prefill_vram_seed_total > 0) &&
        (tier_mode != CUDA_MOE_TIER_ENFORCE ||
         !compose_requested || !gpu_routes)) {
        fprintf(stderr,
                "ds4: prefill VRAM seed requires composed enforce tiering and GPU-resident routes\n");
        return NULL;
    }
    if ((prefill_vram_seed_per_layer > 0 &&
         prefill_vram_seed_total > 0) ||
        (prefill_vram_seed_floor_per_layer > 0 &&
         prefill_vram_seed_total == 0) ||
        (prefill_vram_seed_total > 0 &&
         (uint64_t)prefill_vram_seed_floor_per_layer *
             (CUDA_MOE_LAYER_COUNT - 3u) >
             (uint64_t)prefill_vram_seed_total)) {
        fprintf(stderr,
                "ds4: prefill VRAM seed mode/budget contract invalid\n");
        return NULL;
    }
    if (requested == 0) {
        if (cuda_moe_expert_cache_grow_requested()) {
            g_moe_expert_cache_deferred_gate_expert_bytes = 0;
            g_moe_expert_cache_deferred_down_expert_bytes = 0;
        }
        if (g_moe_expert_cache.capacity != 0) cuda_moe_expert_cache_release();
        return NULL;
    }
    if (gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        return NULL;
    }
    /*
     * F10 two-phase sizing: prefill remains on the existing exact compact
     * fallback. Resident storage, seed publication and route-worker creation
     * are postponed together, so there is no worker or upload stream that
     * could observe a reallocation before decode-start.
     */
    if (cuda_moe_expert_cache_grow_requested() &&
        !g_moe_expert_cache_decode_started &&
        g_moe_expert_cache.capacity == 0) {
        return NULL;
    }
    if (g_moe_expert_cache.capacity != 0 &&
        g_moe_expert_cache.requested == requested &&
        g_moe_expert_cache.gate_expert_bytes == gate_expert_bytes &&
        g_moe_expert_cache.down_expert_bytes == down_expert_bytes &&
        g_moe_expert_cache.packed_copy_requested ==
            (packed_copy_requested ? 1u : 0u) &&
        g_moe_expert_cache.batched_publish_requested ==
            (batched_publish_requested ? 1u : 0u) &&
        g_moe_expert_cache.demand_pipeline_requested ==
            (demand_pipeline_requested ? 1u : 0u) &&
        g_moe_expert_cache.g73_host_selected_requested ==
            (g73_host_selected_requested ? 1u : 0u) &&
        g_moe_expert_cache.route_io_qd_requested ==
            route_io_qd_requested &&
        g_moe_expert_cache.route_io_qd_allow_no_g73 ==
            (route_io_qd_allow_no_g73 ? 1u : 0u) &&
        g_moe_expert_cache.prefill_vram_seed_per_layer ==
            (uint32_t)prefill_vram_seed_per_layer &&
        g_moe_expert_cache.prefill_vram_seed_total ==
            (uint32_t)prefill_vram_seed_total &&
        g_moe_expert_cache.prefill_vram_seed_floor_per_layer ==
            (uint32_t)prefill_vram_seed_floor_per_layer &&
        g_moe_tiering.mode == (cuda_moe_tier_mode)tier_mode &&
        g_moe_tiering.compose_prefill_mass_tiering == compose_requested &&
        g_moe_tiering.compose_router_open == compose_router_open &&
        g_iq1_promotion.requested_slots ==
            (uint32_t)promotion_probation_slots &&
        g_iq1_promotion.min_touches == promotion_min_touches &&
        g_iq1_promotion.min_weight == promotion_min_weight &&
        g_iq1_promotion.min_mass == promotion_min_mass &&
        g_iq1_promotion.request_budget == promotion_request_budget &&
        g_iq1_promotion.window_calls == promotion_window_calls &&
        g_iq1_promotion.window_budget == promotion_window_budget &&
        (tier_mode != CUDA_MOE_TIER_ENFORCE ||
         (g_moe_expert_cache.route_transient_gate &&
          g_moe_expert_cache.route_transient_up &&
          g_moe_expert_cache.route_transient_down))) {
        const int worker_healthy = !gpu_routes ||
            (g_moe_expert_cache.route_thread_started &&
             g_moe_expert_cache.route_worker_ready.load(
                 std::memory_order_acquire) &&
             !g_moe_expert_cache.route_worker_failed.load(
                 std::memory_order_acquire) &&
             !g_moe_expert_cache.route_stop.load(
                 std::memory_order_acquire));
        if (worker_healthy) {
            return &g_moe_expert_cache;
        }
        /* Config still matches but the worker died (transient-io deadline
         * kill). Respawn only the thread on the intact cache instead of
         * handing back a dead cache that every begin() rejects silently. */
        if (cuda_moe_route_worker_respawn(&g_moe_expert_cache)) {
            fprintf(stderr,
                    "ds4: [g73-open] route worker respawned after "
                    "transient-io kill\n");
            return &g_moe_expert_cache;
        }
        return NULL;
    }
    cuda_moe_expert_cache_release();

    const uint64_t per_expert = gate_expert_bytes * 2ull + down_expert_bytes;
    size_t free_b = 0;
    size_t total_b = 0;
    cudaError_t err = cudaMemGetInfo(&free_b, &total_b);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA resident expert cache memory query failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return NULL;
    }
    uint64_t reserve = cuda_moe_expert_cache_reserve_bytes();
    if (total_b != 0 && reserve > (uint64_t)total_b / 2ull) reserve = (uint64_t)total_b / 2ull;
    /* ---- Sizing a priorita' invertita (DS4_CUDA_VRAM_INVERTED_PRIORITY=1) ----
     * Requisito 2 e 3, in versione PREVENTIVA: invece di curare la sovra-sottoscrizione
     * sfrattando (impossibile senza restringere lo slab a caldo, vedi ANALISI.md),
     * la si impedisce qui trattenendo l'headroom di crescita del backbone + isteresi.
     * Effetto voluto: a ctx grande free_b e' piccolo e la capacita' SI AUTOLIMITA
     * invece di onorare ciecamente DS4_CUDA_STREAMING_EXPERT_CACHE_N (che e' cio' che
     * oggi spinge fuori il backbone e costa 8-9x); a ctx piccolo free_b e' grande e con
     * DS4_CUDA_VRAM_ELASTIC_EXPERT_SLOTS=1 la capacita' cresce oltre la richiesta,
     * usando tutta la VRAM residua.
     * Requisito 5: un solo budget in BYTE (free_b meno tutte le riserve) da cui si
     * derivano gli slot, invece di conteggi indipendenti per consumatore. */
    const uint64_t base_reserve = reserve;
    const int vram_inverted = cuda_vram_inverted_priority_enabled();
    int vram_elastic = vram_inverted && cuda_vram_elastic_expert_slots_enabled();
    /* SICUREZZA: il sizing elastico ha senso solo se l'allocazione definitiva avviene a
     * decode-start, con lo scratch di prefill gia' rilasciato. Senza
     * DS4_CUDA_EXPERT_CACHE_GROW=1 questa funzione gira ancora in prefill e free_b non
     * e' la VRAM residua reale: auto-disabilito la parte elastica DICENDOLO, invece di
     * dimensionare in silenzio su un numero sbagliato. */
    if (vram_elastic && !cuda_moe_expert_cache_grow_requested()) {
        static int warned_elastic_needs_grow = 0;
        if (!warned_elastic_needs_grow) {
            warned_elastic_needs_grow = 1;
            fprintf(stderr,
                    "ds4: [vram-prio] elastic=auto-disabled "
                    "reason=requires-DS4_CUDA_EXPERT_CACHE_GROW=1 "
                    "effect=capacity-capped-at-requested\n");
        }
        vram_elastic = 0;
    }
    uint64_t backbone_reserve = 0;
    uint64_t hysteresis = 0;
    uint32_t target = requested;
    if (vram_inverted) {
        backbone_reserve = cuda_vram_backbone_reserve_bytes();
        hysteresis = cuda_vram_hysteresis_bytes();
        const uint64_t extra = (backbone_reserve > UINT64_MAX - hysteresis)
            ? UINT64_MAX : (backbone_reserve + hysteresis);
        reserve = (reserve > UINT64_MAX - extra) ? UINT64_MAX : reserve + extra;
        /* Non affamare del tutto la cache: tetto della riserva a 3/4 della VRAM totale. */
        if (total_b != 0 && reserve > (uint64_t)total_b * 3ull / 4ull) {
            reserve = (uint64_t)total_b * 3ull / 4ull;
        }
        if (vram_elastic) {
            target = cuda_vram_elastic_max_slots();
            /* Requisito 4: se abbiamo dichiarato oscillazione, la capacita' e' fissata. */
            if (g_vram_prio_stabilized && g_vram_prio_stabilized_slots != 0u &&
                target > g_vram_prio_stabilized_slots) {
                target = g_vram_prio_stabilized_slots;
            }
            /* Mai sotto la richiesta esplicita dell'operatore. */
            if (target < requested) target = requested;
        }
    }
    uint32_t cap = 0;
    if ((uint64_t)free_b > reserve) {
        const uint64_t max_slots = ((uint64_t)free_b - reserve) / per_expert;
        cap = max_slots < target ? (uint32_t)max_slots : target;
    }
    /* SICUREZZA: la riserva backbone azzererebbe la cache. NON rimettiamo la capacita'
     * piena (sarebbe tornare esattamente alla configurazione che thrasha): concediamo un
     * PAVIMENTO di slot, attingendo solo alla riserva base, e lo dichiariamo. Se non ci
     * sta nemmeno il pavimento, cade nel disabled log sottostante -> exact-streaming. */
    if (vram_inverted && cap == 0u) {
        const uint32_t floor_slots = cuda_vram_min_expert_slots();
        const uint64_t above_base = ((uint64_t)free_b > base_reserve)
            ? ((uint64_t)free_b - base_reserve) : 0ull;
        uint64_t floor_fit = (per_expert != 0ull) ? (above_base / per_expert) : 0ull;
        if (floor_fit > (uint64_t)floor_slots) floor_fit = (uint64_t)floor_slots;
        if (floor_fit != 0ull) {
            cap = (uint32_t)floor_fit;
            fprintf(stderr,
                    "ds4: [vram-prio] expert_cache=floor "
                    "reason=backbone-reserve-exceeds-free capacity=%u floor_slots=%u "
                    "free_mib=%.1f wanted_reserve_mib=%.1f base_reserve_mib=%.1f\n",
                    cap, floor_slots,
                    (double)free_b / 1048576.0,
                    (double)reserve / 1048576.0,
                    (double)base_reserve / 1048576.0);
        }
    }
    if (cap == 0) {
        fprintf(stderr,
                "ds4: CUDA resident expert cache disabled: free %.2f GiB <= reserve %.2f GiB\n",
                (double)free_b / 1073741824.0, (double)reserve / 1073741824.0);
        return NULL;
    }
    g_vram_prio_expert_slots_current = cap;
    if (vram_inverted) {
        fprintf(stderr,
                "ds4: [vram-prio] sizing=%s requested=%u target=%u capacity=%u "
                "per_expert_bytes=%llu free_at_size_mib=%.1f base_reserve_mib=%.1f "
                "backbone_reserve_mib=%.1f hysteresis_mib=%.1f effective_reserve_mib=%.1f "
                "elastic=%d stabilized=%d decode_started=%d\n",
                /* Onesta' della label: senza DS4_CUDA_EXPERT_CACHE_GROW=1 questo sizing
                 * gira ancora in prefill, con lo scratch allocato, quindi free_b non e'
                 * il residuo di decode-start. L'elastico vuole GROW=1. */
                g_moe_expert_cache_decode_started ? "decode-start" : "prefill",
                requested, target, cap,
                (unsigned long long)per_expert,
                (double)free_b / 1048576.0,
                (double)base_reserve / 1048576.0,
                (double)backbone_reserve / 1048576.0,
                (double)hysteresis / 1048576.0,
                (double)reserve / 1048576.0,
                vram_elastic,
                g_vram_prio_stabilized,
                g_moe_expert_cache_decode_started);
    }
    /* Diagnostic only: the other consumer sized from cudaMemGetInfo. Emitted in the
     * order it executes so the sizing race against [q1-vram-lru] is readable. */
    fprintf(stderr,
            "ds4: [iq2-expert-cache-size] result=%s requested=%u capacity=%u "
            "per_expert_bytes=%llu total_mib=%.1f free_at_size_mib=%.1f "
            "reserve_mib=%.1f\n",
            "sized", requested, cap, (unsigned long long)per_expert,
            (double)((uint64_t)cap * per_expert) / 1048576.0,
            (double)free_b / 1048576.0,
            (double)reserve / 1048576.0);

    while (cap != 0) {
        void *packed_base = NULL;
        void *gate = NULL;
        void *up = NULL;
        void *down = NULL;
        int32_t *device_map = NULL;
        uint64_t *device_routes = NULL;
        uint32_t *device_hit_mask = NULL;
        uint32_t *ready_host = NULL;
        uint32_t *failed_host = NULL;
        uint32_t *device_ready = NULL;
        uint32_t *device_failed = NULL;
        cuda_moe_route_request *request_host = NULL;
        cuda_moe_route_request *request_device = NULL;
        char *host_packed_base = NULL;
        char *host_gate = NULL;
        char *host_up = NULL;
        char *host_down = NULL;
        char *transient_packed_base = NULL;
        char *transient_gate = NULL;
        char *transient_up = NULL;
        char *transient_down = NULL;
        cudaStream_t route_stream = NULL;
        cudaEvent_t consumer_done_event = NULL;
#ifdef _WIN32
        HANDLE route_io_qd_event[4] = {NULL, NULL, NULL, NULL};
#endif
        if (packed_copy_requested) {
            const uint64_t gate_plane_bytes =
                (uint64_t)cap * gate_expert_bytes;
            const uint64_t down_plane_bytes =
                (uint64_t)cap * down_expert_bytes;
            if (gate_plane_bytes >
                    (UINT64_MAX - down_plane_bytes) / 2ull) {
                err = cudaErrorMemoryAllocation;
            } else {
                const uint64_t packed_bytes =
                    gate_plane_bytes * 2ull + down_plane_bytes;
                err = cudaMalloc(&packed_base, (size_t)packed_bytes);
            }
            if (err == cudaSuccess) {
                gate = packed_base;
                up = (char *)packed_base + gate_plane_bytes;
                down = (char *)packed_base + gate_plane_bytes * 2ull;
            }
        } else {
            err = cudaMalloc(&gate, (size_t)((uint64_t)cap * gate_expert_bytes));
            if (err == cudaSuccess) err = cudaMalloc(&up, (size_t)((uint64_t)cap * gate_expert_bytes));
            if (err == cudaSuccess) err = cudaMalloc(&down, (size_t)((uint64_t)cap * down_expert_bytes));
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaMalloc((void **)&device_map,
                (size_t)CUDA_MOE_LAYER_COUNT * 256u * sizeof(int32_t));
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaMalloc((void **)&device_routes,
                (size_t)CUDA_MOE_ROUTE_COUNT * 3u * sizeof(uint64_t));
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaMalloc((void **)&device_hit_mask, sizeof(uint32_t));
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostAlloc((void **)&ready_host, sizeof(uint32_t),
                                cudaHostAllocMapped);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostGetDevicePointer((void **)&device_ready, ready_host, 0);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostAlloc((void **)&failed_host, sizeof(uint32_t),
                                cudaHostAllocMapped);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostGetDevicePointer((void **)&device_failed, failed_host, 0);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostAlloc((void **)&request_host, sizeof(*request_host),
                                cudaHostAllocMapped);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostGetDevicePointer((void **)&request_device, request_host, 0);
        }
        if (err == cudaSuccess && gpu_routes && demand_packed_layout) {
            const uint64_t gate_plane_bytes =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes;
            const uint64_t down_plane_bytes =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * down_expert_bytes;
            if (gate_plane_bytes >
                    (UINT64_MAX - down_plane_bytes) / 2ull) {
                err = cudaErrorMemoryAllocation;
            } else {
                const uint64_t packed_bytes =
                    gate_plane_bytes * 2ull + down_plane_bytes;
                err = cudaHostAlloc((void **)&host_packed_base,
                    (size_t)packed_bytes, cudaHostAllocDefault);
            }
            if (err == cudaSuccess) {
                host_gate = host_packed_base;
                host_up = host_packed_base + gate_plane_bytes;
                host_down = host_packed_base + gate_plane_bytes * 2ull;
            }
        }
        if (err == cudaSuccess && gpu_routes && !demand_packed_layout) {
            err = cudaHostAlloc((void **)&host_gate,
                (size_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes, cudaHostAllocDefault);
        }
        if (err == cudaSuccess && gpu_routes && !demand_packed_layout) {
            err = cudaHostAlloc((void **)&host_up,
                (size_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes, cudaHostAllocDefault);
        }
        if (err == cudaSuccess && gpu_routes && !demand_packed_layout) {
            err = cudaHostAlloc((void **)&host_down,
                (size_t)CUDA_MOE_ROUTE_COUNT * down_expert_bytes, cudaHostAllocDefault);
        }
        if (err == cudaSuccess && tier_mode == CUDA_MOE_TIER_ENFORCE &&
            demand_packed_layout) {
            const uint64_t gate_plane_bytes =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes;
            const uint64_t down_plane_bytes =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * down_expert_bytes;
            if (gate_plane_bytes >
                    (UINT64_MAX - down_plane_bytes) / 2ull) {
                err = cudaErrorMemoryAllocation;
            } else {
                const uint64_t packed_bytes =
                    gate_plane_bytes * 2ull + down_plane_bytes;
                err = cudaMalloc((void **)&transient_packed_base,
                    (size_t)packed_bytes);
            }
            if (err == cudaSuccess) {
                transient_gate = transient_packed_base;
                transient_up = transient_packed_base + gate_plane_bytes;
                transient_down = transient_packed_base +
                    gate_plane_bytes * 2ull;
            }
        }
        if (err == cudaSuccess && tier_mode == CUDA_MOE_TIER_ENFORCE &&
            !demand_packed_layout) {
            err = cudaMalloc((void **)&transient_gate,
                (size_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes);
        }
        if (err == cudaSuccess && tier_mode == CUDA_MOE_TIER_ENFORCE &&
            !demand_packed_layout) {
            err = cudaMalloc((void **)&transient_up,
                (size_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes);
        }
        if (err == cudaSuccess && tier_mode == CUDA_MOE_TIER_ENFORCE &&
            !demand_packed_layout) {
            err = cudaMalloc((void **)&transient_down,
                (size_t)CUDA_MOE_ROUTE_COUNT * down_expert_bytes);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaStreamCreateWithFlags(&route_stream, cudaStreamNonBlocking);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaEventCreateWithFlags(
                &consumer_done_event, cudaEventDisableTiming);
        }
        /* DRAIN4: eventi creati SOLO a flag acceso, alla prepare.  Un
         * fallimento non boccia la prepare: senza eventi ogni arm ricade
         * sul drain bloccante identico a oggi, e il log + drain_overlap_ms
         * fermo a zero rendono la degradazione visibile nel protocollo. */
        if (err == cudaSuccess && gpu_routes &&
            cuda_moe_drain_overlap4_requested()) {
            const cudaError_t overlap_event_error =
                cuda_moe_drain_overlap4_events_create();
            if (overlap_event_error != cudaSuccess) {
                /* Errore di init, loggato qui sotto: si azzera lo stato
                 * pendente perche' non contamini la prima cudaGetLastError
                 * di un job. */
                (void)cudaGetLastError();
                fprintf(stderr,
                        "ds4: [drain-overlap4] result=event-create-failed "
                        "cuda=%s; overlap disattivato, drain bloccante\n",
                        cudaGetErrorString(overlap_event_error));
            }
        }
#ifdef _WIN32
        if (err == cudaSuccess && gpu_routes && route_io_qd_requested) {
            for (uint32_t i = 0; i < route_io_qd_requested; i++) {
                route_io_qd_event[i] =
                    CreateEventW(NULL, TRUE, FALSE, NULL);
                if (!route_io_qd_event[i]) {
                    err = cudaErrorUnknown;
                    break;
                }
            }
        }
#endif
        if (err == cudaSuccess) {
            try {
                g_moe_expert_cache.slots.resize(cap);
                if (gpu_routes) {
                    g_moe_expert_cache.host_slot_by_layer_expert.assign(
                        (size_t)CUDA_MOE_LAYER_COUNT * 256u, -1);
                }
            } catch (...) {
                err = cudaErrorMemoryAllocation;
            }
        }
        if (err == cudaSuccess) {
            g_moe_expert_cache.packed_base = (char *)packed_base;
            g_moe_expert_cache.gate = (char *)gate;
            g_moe_expert_cache.up = (char *)up;
            g_moe_expert_cache.down = (char *)down;
            g_moe_expert_cache.gate_expert_bytes = gate_expert_bytes;
            g_moe_expert_cache.down_expert_bytes = down_expert_bytes;
            g_moe_expert_cache.requested = requested;
            g_moe_expert_cache.capacity = cap;
            g_moe_expert_cache.prefill_vram_seed_per_layer =
                (uint32_t)prefill_vram_seed_per_layer;
            g_moe_expert_cache.prefill_vram_seed_total =
                (uint32_t)prefill_vram_seed_total;
            g_moe_expert_cache.prefill_vram_seed_floor_per_layer =
                (uint32_t)prefill_vram_seed_floor_per_layer;
            g_moe_expert_cache.device_slot_by_layer_expert = device_map;
            g_moe_expert_cache.device_route_ptrs = device_routes;
            g_moe_expert_cache.device_route_hit_mask = device_hit_mask;
            g_moe_expert_cache.route_ready_host = ready_host;
            g_moe_expert_cache.route_failed_host = failed_host;
            g_moe_expert_cache.device_route_ready_sequence = device_ready;
            g_moe_expert_cache.device_route_failed_sequence = device_failed;
            g_moe_expert_cache.route_request_host = request_host;
            g_moe_expert_cache.route_request_device = request_device;
            g_moe_expert_cache.route_host_packed_base = host_packed_base;
            g_moe_expert_cache.route_host_gate = host_gate;
            g_moe_expert_cache.route_host_up = host_up;
            g_moe_expert_cache.route_host_down = host_down;
            g_moe_expert_cache.route_transient_packed_base =
                transient_packed_base;
            g_moe_expert_cache.route_transient_gate = transient_gate;
            g_moe_expert_cache.route_transient_up = transient_up;
            g_moe_expert_cache.route_transient_down = transient_down;
            g_moe_expert_cache.packed_copy_requested =
                packed_copy_requested ? 1u : 0u;
            g_moe_expert_cache.batched_publish_requested =
                batched_publish_requested ? 1u : 0u;
            g_moe_expert_cache.demand_pipeline_requested =
                demand_pipeline_requested ? 1u : 0u;
            g_moe_expert_cache.g73_host_selected_requested =
                g73_host_selected_requested ? 1u : 0u;
            g_moe_expert_cache.route_io_qd_requested =
                route_io_qd_requested;
            g_moe_expert_cache.route_io_qd_allow_no_g73 =
                route_io_qd_allow_no_g73 ? 1u : 0u;
#ifdef _WIN32
            memset(g_moe_expert_cache.route_io_qd_overlapped, 0,
                   sizeof(g_moe_expert_cache.route_io_qd_overlapped));
            for (uint32_t i = 0; i < 4u; i++) {
                g_moe_expert_cache.route_io_qd_event[i] =
                    route_io_qd_event[i];
                route_io_qd_event[i] = NULL;
            }
#endif
            g_moe_expert_cache.packed_resident_alloc =
                packed_base ? 1u : 0u;
            g_moe_expert_cache.packed_route_host_alloc =
                host_packed_base ? 1u : 0u;
            g_moe_expert_cache.packed_transient_alloc =
                transient_packed_base ? 1u : 0u;
            g_moe_expert_cache.route_upload_stream = route_stream;
            g_moe_expert_cache.route_consumer_done_event =
                consumer_done_event;
            g_moe_expert_cache.route_stop.store(
                0, std::memory_order_relaxed);
            g_moe_expert_cache.route_worker_ready.store(
                0, std::memory_order_relaxed);
            g_moe_expert_cache.route_worker_failed.store(
                0, std::memory_order_relaxed);
            g_moe_expert_cache.route_worker_safe_leaked.store(
                0, std::memory_order_relaxed);
            g_moe_expert_cache.route_submitted_sequence.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_consumed_sequence.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_completed_sequence.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_generation = 0u;
            g_moe_expert_cache.route_submitted_generation.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_consumed_generation.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_completed_generation.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_consumer_event_generation.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_consumer_done_generation.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_cpu_staging_generation.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_cpu_plan = cuda_g132_general_plan{};
            for (uint32_t slot = 0; slot < 2u; slot++) {
                g_moe_expert_cache.route_mailbox[slot].generation.store(
                    0u, std::memory_order_relaxed);
                g_moe_expert_cache.route_mailbox[slot].state.store(
                    CUDA_MOE_ROUTE_MAILBOX_FREE,
                    std::memory_order_relaxed);
            }
            g_moe_expert_cache.route_transient_read_sequence.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_transient_io_sequence.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_transient_cancel_sequence.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_transient_timeout_cancel_sequence.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_transient_dead_sequence.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_transient_read_bytes.store(
                0u, std::memory_order_relaxed);
            g_moe_expert_cache.route_transient_read_deadline = 0.0;
            os_pread_cancellable_init(
                &g_moe_expert_cache.route_transient_pread);
            if (os_pread_cancellable_prepare(
                    &g_moe_expert_cache.route_transient_pread) != 0) {
                fprintf(stderr,
                        "ds4: persistent route I/O slot preparation failed: %s\n",
                        strerror(errno));
                cuda_moe_expert_cache_release();
                return NULL;
            }
            (void)cudaGetDevice(&g_moe_expert_cache.route_device);
            if (!cuda_moe_tiering_prepare()) {
                fprintf(stderr, "ds4: expert tiering preparation failed\n");
                cuda_moe_expert_cache_release();
                return NULL;
            }
            cuda_moe_expert_cache_invalidate("expert-cache-prepare");
            if ((prefill_vram_seed_per_layer > 0 ||
                 prefill_vram_seed_total > 0) &&
                !cuda_moe_prefill_vram_seed(
                    &g_moe_expert_cache,
                    (uint32_t)prefill_vram_seed_per_layer,
                    (uint32_t)prefill_vram_seed_total,
                    (uint32_t)prefill_vram_seed_floor_per_layer)) {
                fprintf(stderr, "ds4: prefill VRAM seed failed\n");
                cuda_moe_expert_cache_release();
                return NULL;
            }
            if (gpu_routes &&
                os_thread_create(&g_moe_expert_cache.route_thread,
                                 g_cuda_moe_route_worker_dispatch,
                                 &g_moe_expert_cache) != 0) {
                fprintf(stderr, "ds4: CUDA GPU-resident route worker creation failed\n");
                cuda_moe_expert_cache_release();
                return NULL;
            }
            g_moe_expert_cache.route_thread_started = gpu_routes ? 1 : 0;
            if (gpu_routes) {
                const double ready_deadline = cuda_wall_sec() + 2.0;
                while (!g_moe_expert_cache.route_worker_ready.load(
                           std::memory_order_acquire) &&
                       !g_moe_expert_cache.route_worker_failed.load(
                           std::memory_order_acquire) &&
                       cuda_wall_sec() < ready_deadline) {
#ifdef _WIN32
                    (void)SwitchToThread();
#else
                    usleep(0);
#endif
                }
                if (!g_moe_expert_cache.route_worker_ready.load(
                        std::memory_order_acquire)) {
                    fprintf(stderr, "ds4: CUDA GPU-resident route worker failed to initialize\n");
                    cuda_moe_expert_cache_release();
                    return NULL;
                }
            }
            const uint64_t startup_reserve = cuda_model_stream_reserve_bytes();
            g_model_expert_cache_ready = 1;
            const uint64_t runtime_reserve = cuda_model_stream_reserve_bytes();
            fprintf(stderr,
                    "ds4: CUDA resident expert cache ready: %u/%u experts, %.2f MiB/expert, %.2f GiB total\n",
                    cap, requested, (double)per_expert / 1048576.0,
                    (double)((uint64_t)cap * per_expert) / 1073741824.0);
            if (gpu_routes) {
                fprintf(stderr,
                        "ds4: CUDA GPU-resident route resolver active: exact miss worker, %u slots\n",
                        cap);
                if (cuda_moe_route_read_whole_requested()) {
                    fprintf(stderr,
                            "ds4: CUDA route whole-read active: "
                            "source_layout=tensor-major preads_per_expert=3 "
                            "worker_threads=1\n");
                }
                if (cuda_moe_route_prefetch_hint_requested()) {
#ifdef _WIN32
                    fprintf(stderr,
                            "ds4: CUDA route PrefetchVirtualMemory hint active\n");
#else
                    fprintf(stderr,
                            "ds4: CUDA route prefetch hint ignored: "
                            "PrefetchVirtualMemory is Windows-only\n");
#endif
                }
                if (packed_copy_requested) {
                    fprintf(stderr,
                            "ds4: CUDA route packed H2D copy active: gate_bytes=%llu down_bytes=%llu submissions_per_expert=2 resident_gate_pitch=%llu transient_gate_pitch=%llu\n",
                            (unsigned long long)gate_expert_bytes,
                            (unsigned long long)down_expert_bytes,
                            (unsigned long long)((uint64_t)cap * gate_expert_bytes),
                            (unsigned long long)((uint64_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes));
                }
                if (batched_publish_requested) {
                    fprintf(stderr,
                            "ds4: CUDA route batched publish active: "
                            "max_routes=%u kernel_args=by-value stream=upload\n",
                            CUDA_MOE_ROUTE_COUNT);
                }
                if (demand_pipeline_requested) {
                    fprintf(stderr,
                            "ds4: CUDA MoE demand pipeline active: "
                            "scope=tiering-enforce max_h2d_per_layer=%u "
                            "max_publish_per_layer=%u max_h2d_per_token=%u "
                            "max_publish_per_token=%u route_q1_0=legacy "
                            "nested-residual=legacy packed-copy=%s "
                            "batched-publish=%s route-io-qd=%u\n",
                            CUDA_MOE_DEMAND_PIPELINE_H2D_PER_LAYER,
                            CUDA_MOE_DEMAND_PIPELINE_PUBLISH_PER_LAYER,
                            CUDA_MOE_DEMAND_PIPELINE_MAX_H2D_PER_TOKEN,
                            CUDA_MOE_DEMAND_PIPELINE_MAX_PUBLISH_PER_TOKEN,
                            packed_copy_requested ? "composed" : "off",
                            batched_publish_requested ? "composed" : "off",
                            route_io_qd_requested);
                }
                if (g73_host_selected_requested) {
                    fprintf(stderr,
                            "ds4: CUDA G73 host-selected reuse active: "
                            "source=route-mailbox fallback=classification-d2h\n");
                }
                if (route_io_qd_requested) {
                    if (route_io_qd_allow_no_g73) {
                        fprintf(stderr,
                                "ds4: CUDA route source I/O active: "
                                "queue_depth=%u destination=per-route-pinned "
                                "fallback=serial-cancellable allow_no_g73=1\n",
                                route_io_qd_requested);
                    } else {
                        fprintf(stderr,
                                "ds4: CUDA G73 route source I/O active: "
                                "queue_depth=%u destination=per-route-pinned "
                                "fallback=serial-cancellable\n",
                                route_io_qd_requested);
                    }
                }
            }
            if (startup_reserve != runtime_reserve) {
                fprintf(stderr,
                        "ds4: CUDA stream runtime reserve activated: %.2f GiB -> %.2f GiB\n",
                        (double)startup_reserve / 1073741824.0,
                        (double)runtime_reserve / 1073741824.0);
            }
            if (cuda_moe_expert_cache_grow_requested()) {
                g_moe_expert_cache_deferred_gate_expert_bytes = 0;
                g_moe_expert_cache_deferred_down_expert_bytes = 0;
            }
            return &g_moe_expert_cache;
        }
        const char *why = cudaGetErrorString(err);
        (void)cudaGetLastError();
        g_moe_expert_cache.slots.clear();
        if (packed_base) {
            (void)cudaFree(packed_base);
        } else {
            if (gate) (void)cudaFree(gate);
            if (up) (void)cudaFree(up);
            if (down) (void)cudaFree(down);
        }
        if (device_map) (void)cudaFree(device_map);
        if (device_routes) (void)cudaFree(device_routes);
        if (device_hit_mask) (void)cudaFree(device_hit_mask);
        if (ready_host) (void)cudaFreeHost(ready_host);
        if (failed_host) (void)cudaFreeHost(failed_host);
        if (request_host) (void)cudaFreeHost(request_host);
        if (host_packed_base) {
            (void)cudaFreeHost(host_packed_base);
        } else {
            if (host_gate) (void)cudaFreeHost(host_gate);
            if (host_up) (void)cudaFreeHost(host_up);
            if (host_down) (void)cudaFreeHost(host_down);
        }
        if (transient_packed_base) {
            (void)cudaFree(transient_packed_base);
        } else {
            if (transient_gate) (void)cudaFree(transient_gate);
            if (transient_up) (void)cudaFree(transient_up);
            if (transient_down) (void)cudaFree(transient_down);
        }
        if (route_stream) (void)cudaStreamDestroy(route_stream);
        if (consumer_done_event) {
            (void)cudaEventDestroy(consumer_done_event);
        }
#ifdef _WIN32
        for (uint32_t i = 0; i < 4u; i++) {
            if (route_io_qd_event[i]) {
                (void)CloseHandle(route_io_qd_event[i]);
            }
        }
#endif
        const uint32_t release = (cap + 9u) / 10u;
        const uint32_t next = cap > release ? cap - release : 0;
        fprintf(stderr,
                "ds4: CUDA resident expert cache allocation failed at %u slots: %s; retry=%u\n",
                cap, why, next);
        cap = next;
    }
    cuda_moe_expert_cache_release();
    return NULL;
}

static int cuda_moe_expert_cache_find(
        cuda_moe_expert_cache *cache,
        const cuda_moe_cache_key &key) {
    if (!cache) return -1;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_moe_cache_slot &slot = cache->slots[i];
        if (slot.state == CUDA_MOE_CACHE_VALID &&
            slot.key.gate_src == key.gate_src &&
            slot.key.up_src == key.up_src &&
            slot.key.down_src == key.down_src) {
            return (int)i;
        }
    }
    return -1;
}

static int cuda_moe_expert_cache_lru_slot(
        cuda_moe_expert_cache *cache,
        const std::vector<uint8_t> &claimed) {
    if (!cache || claimed.size() < cache->capacity) return -1;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        if (!claimed[i] && cache->slots[i].state == CUDA_MOE_CACHE_EMPTY) return (int)i;
    }
    int best = -1;
    uint64_t best_age = UINT64_MAX;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_moe_cache_slot &slot = cache->slots[i];
        if (claimed[i] || slot.state != CUDA_MOE_CACHE_VALID) continue;
        if (slot.age < best_age) {
            best = (int)i;
            best_age = slot.age;
        }
    }
    return best;
}

static int cuda_moe_route_worker_pick_slot(
        cuda_moe_expert_cache *cache,
        const uint8_t *claimed) {
    if (!cache || !claimed) return -1;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        if (!claimed[i] && cache->slots[i].state == CUDA_MOE_CACHE_EMPTY) {
            return (int)i;
        }
    }
    int best = -1;
    uint64_t best_age = UINT64_MAX;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_moe_cache_slot &slot = cache->slots[i];
        if (claimed[i] || slot.state != CUDA_MOE_CACHE_VALID) continue;
        if (slot.age < best_age) {
            best = (int)i;
            best_age = slot.age;
        }
    }
    return best;
}

static int cuda_moe_route_copy_expert_h2d_async(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request *trace_request,
        char *dst_gate,
        char *dst_up,
        char *dst_down,
        uint64_t dst_pitch,
        const char *host_gate,
        const char *host_up,
        const char *host_down,
        uint64_t src_pitch) {
    if (!cache || !cache->packed_copy_requested ||
        cache->gate_expert_bytes == 0 ||
        cache->down_expert_bytes == 0 ||
        !dst_gate || !dst_up || !dst_down ||
        !host_gate || !host_up || !host_down ||
        dst_pitch == 0 || src_pitch == 0) {
        return 0;
    }
    if (dst_up != dst_gate + dst_pitch ||
        host_up != host_gate + src_pitch) {
        fprintf(stderr,
                "ds4: CUDA route packed H2D copy refused: gate/up layout is not contiguous\n");
        return 0;
    }
    const uint64_t trace_started = trace_request
        ? cuda_decode_trace_request_qpc(*trace_request) : 0u;
    const int copy_ok =
        cudaMemcpy2DAsync(dst_gate, (size_t)dst_pitch,
                          host_gate, (size_t)src_pitch,
                          (size_t)cache->gate_expert_bytes, 2u,
                          cudaMemcpyHostToDevice,
                          cache->route_upload_stream) != cudaSuccess ||
        cudaMemcpyAsync(dst_down, host_down,
                        (size_t)cache->down_expert_bytes,
                        cudaMemcpyHostToDevice,
                        cache->route_upload_stream) != cudaSuccess
        ? 0 : 1;
    cuda_decode_trace_note_h2d(
        trace_request, trace_started, 2u,
        cache->gate_expert_bytes * 2ull +
            cache->down_expert_bytes,
        copy_ok);
    if (!copy_ok) {
        (void)cudaGetLastError();
        return 0;
    }
    cache->packed_copy_experts++;
    cache->packed_copy_submissions += 2ull;
    cache->packed_copy_bytes +=
        cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
    return 1;
}

static int cuda_moe_route_legacy_copy_expert_h2d_async(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request *trace_request,
        char *dst_gate,
        char *dst_up,
        char *dst_down,
        const char *host_gate,
        const char *host_up,
        const char *host_down) {
    if (!cache || !dst_gate || !dst_up || !dst_down ||
        !host_gate || !host_up || !host_down) {
        return 0;
    }
    const uint64_t trace_started = trace_request
        ? cuda_decode_trace_request_qpc(*trace_request) : 0u;
    const int copy_ok =
        cudaMemcpyAsync(dst_gate, host_gate,
                        (size_t)cache->gate_expert_bytes,
                        cudaMemcpyHostToDevice,
                        cache->route_upload_stream) != cudaSuccess ||
        cudaMemcpyAsync(dst_up, host_up,
                        (size_t)cache->gate_expert_bytes,
                        cudaMemcpyHostToDevice,
                        cache->route_upload_stream) != cudaSuccess ||
        cudaMemcpyAsync(dst_down, host_down,
                        (size_t)cache->down_expert_bytes,
                        cudaMemcpyHostToDevice,
                        cache->route_upload_stream) != cudaSuccess
        ? 0 : 1;
    cuda_decode_trace_note_h2d(
        trace_request, trace_started, 3u,
        cache->gate_expert_bytes * 2ull +
            cache->down_expert_bytes,
        copy_ok);
    if (!copy_ok) {
        (void)cudaGetLastError();
        return 0;
    }
    cache->legacy_copy_submissions += 3ull;
    return 1;
}

static int cuda_moe_route_publish_batch_append(
        cuda_moe_route_publish_batch *batch,
        int32_t old_map_index,
        uint32_t new_map_index,
        uint32_t cache_slot,
        uint32_t route,
        uint32_t transient_slot,
        uint32_t resident) {
    if (!batch || batch->count >= CUDA_MOE_ROUTE_COUNT ||
        route >= CUDA_MOE_ROUTE_COUNT) {
        return 0;
    }
    cuda_moe_route_publish_entry &entry = batch->entries[batch->count++];
    entry.old_map_index = old_map_index;
    entry.new_map_index = new_map_index;
    entry.cache_slot = cache_slot;
    entry.route = route;
    entry.transient_slot = transient_slot;
    entry.resident = resident ? 1u : 0u;
    entry.host_direct = 0u;
    entry.host_gate = 0ull;
    entry.host_up = 0ull;
    entry.host_down = 0ull;
    return 1;
}

/* P.5a: publish the pinned host arena addresses for one route. No cache slot,
 * no transient slot and no copy are associated with the entry. */
static int cuda_moe_route_publish_batch_append_host(
        cuda_moe_route_publish_batch *batch,
        uint32_t route,
        uint64_t host_gate,
        uint64_t host_up,
        uint64_t host_down) {
    if (!batch || batch->count >= CUDA_MOE_ROUTE_COUNT ||
        route >= CUDA_MOE_ROUTE_COUNT ||
        host_gate == 0ull || host_up == 0ull || host_down == 0ull) {
        return 0;
    }
    cuda_moe_route_publish_entry &entry = batch->entries[batch->count++];
    entry = cuda_moe_route_publish_entry{};
    entry.old_map_index = -1;
    entry.route = route;
    entry.host_direct = 1u;
    entry.host_gate = host_gate;
    entry.host_up = host_up;
    entry.host_down = host_down;
    return 1;
}

static int cuda_moe_route_publish_batch_flush(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request,
        cuda_moe_route_publish_batch *batch) {
    if (!cache || !batch || request.route_count == 0u ||
        request.route_count > CUDA_MOE_ROUTE_COUNT) {
        return 0;
    }
    if (batch->count == 0u) return 1;
    const uint32_t route_count = batch->count;
    moe_publish_route_batch_kernel<<<
            1, 1, 0, cache->route_upload_stream>>>(
        cache->device_slot_by_layer_expert,
        cache->device_route_ptrs,
        *batch,
        request.route_count,
        cache->gate,
        cache->up,
        cache->down,
        cache->route_transient_gate,
        cache->route_transient_up,
        cache->route_transient_down,
        cache->gate_expert_bytes,
        cache->down_expert_bytes);
    const cudaError_t publish_error = cudaGetLastError();
    if (publish_error != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }
    cache->batched_publish_kernels++;
    cache->batched_publish_routes += route_count;
    cuda_decode_trace_note_publish(
        request, 1u, route_count);
    batch->count = 0u;
    return 1;
}

static void cuda_moe_demand_pipeline_batch_init(
        cuda_moe_demand_pipeline_batch *batch) {
    if (!batch) return;
    *batch = cuda_moe_demand_pipeline_batch{};
}

static int cuda_moe_demand_pipeline_stage_host(
        cuda_moe_expert_cache *cache,
        cuda_moe_demand_pipeline_batch *batch,
        const char *host_gate,
        const char *host_up,
        const char *host_down,
        uint32_t ssd_wrap_h2d_ring) {
    if (!cache || !batch || !host_gate || !host_up || !host_down ||
        batch->publish.count >= CUDA_MOE_ROUTE_COUNT) {
        return 0;
    }
    const uint32_t batch_slot = batch->publish.count;
    char *stage_gate = cache->route_host_gate +
        (uint64_t)batch_slot * cache->gate_expert_bytes;
    char *stage_up = cache->route_host_up +
        (uint64_t)batch_slot * cache->gate_expert_bytes;
    char *stage_down = cache->route_host_down +
        (uint64_t)batch_slot * cache->down_expert_bytes;
    if (stage_gate != host_gate) {
        memmove(stage_gate, host_gate, (size_t)cache->gate_expert_bytes);
    }
    if (stage_up != host_up) {
        memmove(stage_up, host_up, (size_t)cache->gate_expert_bytes);
    }
    if (stage_down != host_down) {
        memmove(stage_down, host_down, (size_t)cache->down_expert_bytes);
    }
    /* Pageable WRAP bounce ownership ends at this synchronous consolidation,
     * not at the later layer H2D. Fence it now so another miss cannot reuse
     * the ring while this worker is still copying from it. */
    return cuda_q1_0_ssd_wrap_record_h2d(
        ssd_wrap_h2d_ring, cache->route_upload_stream);
}

static int cuda_moe_demand_pipeline_flush(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request,
        cuda_moe_demand_pipeline_batch *batch,
        uint32_t cpu_routes) {
    if (!cache || !batch ||
        batch->publish.count + cpu_routes != request.miss_count ||
        request.miss_count > request.route_count ||
        request.route_count > CUDA_MOE_ROUTE_COUNT) {
        return 0;
    }
    if (batch->publish.count == 0u) return cpu_routes != 0u;
    const uint32_t batch_count = batch->publish.count;
    const uint64_t gate_plane_bytes =
        (uint64_t)CUDA_MOE_ROUTE_COUNT * cache->gate_expert_bytes;
    const uint64_t down_plane_bytes =
        (uint64_t)CUDA_MOE_ROUTE_COUNT * cache->down_expert_bytes;
    if (!cache->route_host_packed_base ||
        !cache->route_transient_packed_base ||
        cache->route_host_up != cache->route_host_gate + gate_plane_bytes ||
        cache->route_host_down != cache->route_host_up + gate_plane_bytes ||
        cache->route_transient_up !=
            cache->route_transient_gate + gate_plane_bytes ||
        cache->route_transient_down !=
            cache->route_transient_up + gate_plane_bytes ||
        down_plane_bytes == 0u) {
        fprintf(stderr,
                "ds4: [demand-pipeline] result=failed layer=%u sequence=%u "
                "reason=packed-layout\n",
                request.layer_index, request.sequence);
        return 0;
    }

    const uint64_t trace_started =
        cuda_decode_trace_request_qpc(request);
    uint32_t h2d_submissions = 1u;
    cudaError_t copy_error = cudaMemcpy2DAsync(
        cache->route_transient_gate, (size_t)gate_plane_bytes,
        cache->route_host_gate, (size_t)gate_plane_bytes,
        (size_t)((uint64_t)batch_count * cache->gate_expert_bytes), 2u,
        cudaMemcpyHostToDevice, cache->route_upload_stream);
    if (copy_error == cudaSuccess) {
        h2d_submissions++;
        copy_error = cudaMemcpyAsync(
            cache->route_transient_down, cache->route_host_down,
            (size_t)((uint64_t)batch_count * cache->down_expert_bytes),
            cudaMemcpyHostToDevice, cache->route_upload_stream);
    }
    const uint64_t h2d_bytes =
        (uint64_t)batch_count *
        (cache->gate_expert_bytes * 2ull + cache->down_expert_bytes);
    cuda_decode_trace_note_h2d(
        &request, trace_started, h2d_submissions, h2d_bytes,
        copy_error == cudaSuccess);
    if (copy_error != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }

    moe_publish_demand_batch_kernel<<<
            batch_count, 256, 0, cache->route_upload_stream>>>(
        cache->device_slot_by_layer_expert,
        cache->device_route_ptrs,
        batch->publish,
        request.route_count,
        cache->gate,
        cache->up,
        cache->down,
        cache->route_transient_gate,
        cache->route_transient_up,
        cache->route_transient_down,
        cache->gate_expert_bytes,
        cache->down_expert_bytes);
    const cudaError_t publish_error = cudaGetLastError();
    if (publish_error != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }

    cache->demand_pipeline_layers++;
    cache->demand_pipeline_routes += batch_count;
    cache->demand_pipeline_h2d_submissions +=
        CUDA_MOE_DEMAND_PIPELINE_H2D_PER_LAYER;
    cache->demand_pipeline_h2d_bytes += h2d_bytes;
    cache->demand_pipeline_publish_kernels++;
    if (cache->batched_publish_requested) {
        cache->batched_publish_kernels++;
        cache->batched_publish_routes += batch_count;
    }
    cuda_decode_trace_note_publish(request, 1u, batch_count);
    batch->publish.count = 0u;
    return 1;
}

static double cuda_moe_tiering_mass_lfru_score(
        const cuda_moe_tier_entry &entry) {
    const uint64_t age = g_moe_tiering.call_tick > entry.last_call ?
        g_moe_tiering.call_tick - entry.last_call : 0;
    const double clock = g_moe_tiering.policy_clock_calls ?
        (double)g_moe_tiering.policy_clock_calls : 1.0;
    const double recency = 1.0 / (1.0 + (double)age / clock);
    const double frequency = 1.0 + log1p((double)entry.frequency);
    return entry.mass * frequency * recency;
}

struct cuda_moe_vram_promotion_reservation {
    uint32_t cache_slot;
    uint32_t candidate_layer;
    uint32_t candidate_expert;
    uint32_t victim_layer;
    uint32_t victim_expert;
    cuda_moe_tier_state candidate_prior_state;
    uint8_t active;
    uint8_t victim_valid;
    uint8_t from_snapshot;
    uint8_t free_promotion;
    uint8_t replacement;
    uint8_t policy_budget_reserved;
    uint8_t g133_budget_reserved;
};

static int cuda_moe_tiering_pick_vram_slot(
        cuda_moe_expert_cache *cache, const uint8_t *claimed,
        cuda_moe_tier_entry &candidate,
        cuda_moe_vram_promotion_reservation *reservation,
        const ds4_gpu_g133_epoch &g133_epoch) {
    if (!reservation) return -1;
    *reservation = cuda_moe_vram_promotion_reservation{};
    if (candidate.promoted_from_iq1_cold) {
        if (!candidate.has_2bit_ram) return -1;
        if (g_moe_tiering.call_tick < candidate.vram_eligible_after_call) {
            g_iq1_promotion.next_token_waits++;
            return -1;
        }
    }
    if (!g_moe_tiering.policy_admit_vram_enabled) {
        const uint32_t min_frequency =
            g_moe_tiering.policy == CUDA_MOE_TIER_POLICY_MASS_LFRU ?
            g_moe_tiering.policy_min_frequency : 2u;
        if (!g_moe_tiering.g133_enabled &&
            candidate.frequency < min_frequency) {
            g_moe_tiering.policy_min_frequency_skips++;
            return -1;
        }
    } else {
        if (g_moe_tiering.policy_admit_warm_enabled &&
            g_moe_tiering.policy_admit_current_warm != 0u &&
            candidate.state == CUDA_MOE_TIER_RAM_PROBATION) {
            return -1;
        }
        const size_t candidate_index =
            (size_t)(&candidate - g_moe_tiering.entries.data());
        const uint32_t candidate_layer =
            (uint32_t)(candidate_index / 256u);
        const uint32_t candidate_expert =
            (uint32_t)(candidate_index % 256u);
        if (!cuda_moe_tiering_admit_gate(
                candidate, candidate_layer, candidate_expert,
                g_moe_tiering.policy_admit_current_vram,
                g_moe_tiering.policy_admit_mass_bypass_vram,
                &g_moe_tiering.admit_knocks_skips_vram,
                &g_moe_tiering.admit_mass_bypass_vram)) {
            return -1;
        }
    }
    if (g_moe_tiering.g133_enabled) {
        cuda_g133_refresh_entry(candidate, g133_epoch);
        if (!cuda_g133_vram_candidate(candidate, g133_epoch)) {
            if (cuda_g133_ram_candidate(candidate, g133_epoch)) {
                cuda_g133_telemetry_increment(
                    g_cuda_g133_telemetry.thrash_guard_trips);
            }
            return -1;
        }
        cuda_g133_advisory_budget_refresh(g133_epoch);
        if (g_cuda_g133_advisory_budget.remaining.load(
                std::memory_order_relaxed) == 0u) {
            cuda_g133_telemetry_increment(
                g_cuda_g133_telemetry.thrash_guard_trips);
            return -1;
        }
    }
    for (uint32_t slot = 0; slot < cache->capacity; slot++) {
        if (!claimed[slot] &&
            cache->slots[slot].state == CUDA_MOE_CACHE_EMPTY) {
            reservation->free_promotion = 1u;
            if (g_moe_tiering.g133_enabled) {
                if (!cuda_g133_advisory_budget_reserve(g133_epoch)) return -1;
                reservation->g133_budget_reserved = 1u;
            }
            return (int)slot;
        }
    }
    if (g_moe_tiering.policy == CUDA_MOE_TIER_POLICY_SECOND_TOUCH) {
        const int slot = cuda_moe_route_worker_pick_slot(cache, claimed);
        if (slot >= 0) {
            reservation->replacement = 1u;
            if (g_moe_tiering.g133_enabled) {
                if (!cuda_g133_advisory_budget_reserve(g133_epoch)) return -1;
                reservation->g133_budget_reserved = 1u;
            }
        }
        return slot;
    }

    const uint64_t epoch = g_moe_tiering.call_tick /
        (uint64_t)g_moe_tiering.policy_clock_calls;
    if (epoch != g_moe_tiering.policy_epoch) {
        const int completed_epoch =
            g_moe_tiering.policy_epoch != UINT64_MAX;
        if (g_moe_tiering.policy_adaptive_budget && completed_epoch) {
            const uint64_t budget_skips_delta =
                g_moe_tiering.policy_budget_skips >=
                    g_moe_tiering.policy_adaptive_last_budget_skips ?
                g_moe_tiering.policy_budget_skips -
                    g_moe_tiering.policy_adaptive_last_budget_skips : 0ull;
            const uint64_t replacements_delta =
                g_moe_tiering.policy_replacements >=
                    g_moe_tiering.policy_adaptive_last_replacements ?
                g_moe_tiering.policy_replacements -
                    g_moe_tiering.policy_adaptive_last_replacements : 0ull;
            g_moe_tiering.policy_adaptive_last_budget_skips =
                g_moe_tiering.policy_budget_skips;
            g_moe_tiering.policy_adaptive_last_replacements =
                g_moe_tiering.policy_replacements;
            g_moe_tiering.policy_adaptive_last_budget_skips_delta =
                budget_skips_delta;
            g_moe_tiering.policy_adaptive_last_replacements_delta =
                replacements_delta;
            if (budget_skips_delta >=
                    (uint64_t)g_moe_tiering.policy_adaptive_pressure_threshold &&
                replacements_delta >=
                    (uint64_t)g_moe_tiering.policy_replacement_budget) {
                g_moe_tiering.policy_adaptive_pressure_epochs++;
                g_moe_tiering.policy_adaptive_quiet_epochs = 0ull;
                if (g_moe_tiering.policy_replacement_budget <
                        g_moe_tiering.policy_adaptive_budget_max) {
                    uint32_t next_budget =
                        g_moe_tiering.policy_replacement_budget +
                        g_moe_tiering.policy_adaptive_budget_step;
                    if (next_budget <
                            g_moe_tiering.policy_replacement_budget ||
                        next_budget >
                            g_moe_tiering.policy_adaptive_budget_max) {
                        next_budget =
                            g_moe_tiering.policy_adaptive_budget_max;
                    }
                    if (next_budget !=
                            g_moe_tiering.policy_replacement_budget) {
                        g_moe_tiering.policy_replacement_budget = next_budget;
                        g_moe_tiering.policy_adaptive_budget_ups++;
                    }
                }
            } else if (budget_skips_delta == 0ull) {
                g_moe_tiering.policy_adaptive_quiet_epochs++;
                if (g_moe_tiering.policy_adaptive_quiet_epochs >= 2ull &&
                    g_moe_tiering.policy_replacement_budget >
                        g_moe_tiering.policy_adaptive_budget_min) {
                    const uint32_t step =
                        g_moe_tiering.policy_adaptive_budget_step;
                    g_moe_tiering.policy_replacement_budget =
                        g_moe_tiering.policy_replacement_budget >
                            g_moe_tiering.policy_adaptive_budget_min + step ?
                        g_moe_tiering.policy_replacement_budget - step :
                        g_moe_tiering.policy_adaptive_budget_min;
                    g_moe_tiering.policy_adaptive_budget_downs++;
                    g_moe_tiering.policy_adaptive_quiet_epochs = 0ull;
                }
            } else {
                g_moe_tiering.policy_adaptive_quiet_epochs = 0ull;
            }
        }
        g_moe_tiering.policy_epoch = epoch;
        g_moe_tiering.policy_budget_remaining =
            g_moe_tiering.policy_replacement_budget;
        g_moe_tiering.policy_epochs++;
    }
    if (g_moe_tiering.policy_budget_remaining == 0u) {
        g_moe_tiering.policy_budget_skips++;
        if (g_moe_tiering.g133_enabled) {
            cuda_g133_telemetry_increment(
                g_cuda_g133_telemetry.thrash_guard_trips);
        }
        return -1;
    }

    int victim_slot = -1;
    double victim_score = 1.0e300;
    for (uint32_t slot = 0; slot < cache->capacity; slot++) {
        const cuda_moe_cache_slot &cache_entry = cache->slots[slot];
        if (claimed[slot] || cache_entry.state != CUDA_MOE_CACHE_VALID ||
            cache_entry.layer_index >= CUDA_MOE_LAYER_COUNT ||
            cache_entry.expert_id >= 256u) {
            continue;
        }
        cuda_moe_tier_entry &tier_entry = g_moe_tiering.entries[
            cuda_moe_tiering_entry_index(
                cache_entry.layer_index, cache_entry.expert_id)];
        if (tier_entry.state != CUDA_MOE_TIER_VRAM_PROTECTED) continue;
        if (g_moe_tiering.g133_enabled &&
            !cuda_g133_ram_demotion_eligible(tier_entry, g133_epoch)) {
            continue;
        }
        const double score = g_moe_tiering.g133_enabled
            ? cuda_g133_decayed_heat(tier_entry, g133_epoch)
            : cuda_moe_tiering_mass_lfru_score(tier_entry);
        if (score < victim_score) {
            victim_score = score;
            victim_slot = (int)slot;
        }
    }
    if (victim_slot < 0) {
        g_moe_tiering.policy_score_skips++;
        return -1;
    }
    const double candidate_score = g_moe_tiering.g133_enabled
        ? cuda_g133_decayed_heat(candidate, g133_epoch)
        : cuda_moe_tiering_mass_lfru_score(candidate);
    if (g_moe_tiering.g133_enabled) {
        if (candidate_score <= victim_score) {
            g_moe_tiering.policy_score_skips++;
            cuda_g133_telemetry_increment(
                g_cuda_g133_telemetry.thrash_guard_trips);
            return -1;
        }
    } else if (candidate_score <
                   victim_score * g_moe_tiering.policy_hysteresis) {
        g_moe_tiering.policy_score_skips++;
        return -1;
    }
    g_moe_tiering.policy_budget_remaining--;
    reservation->policy_budget_reserved = 1u;
    if (g_moe_tiering.g133_enabled) {
        if (!cuda_g133_advisory_budget_reserve(g133_epoch)) {
            g_moe_tiering.policy_budget_remaining++;
            reservation->policy_budget_reserved = 0u;
            return -1;
        }
        reservation->g133_budget_reserved = 1u;
    }
    reservation->replacement = 1u;
    return victim_slot;
}

static void cuda_moe_tiering_commit_vram_reservations(
        cuda_moe_expert_cache *cache,
        const cuda_moe_vram_promotion_reservation *reservations,
        uint32_t count, const ds4_gpu_g133_epoch &g133_epoch) {
    if (!cache || !reservations) return;
    const uint64_t expert_bytes =
        cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
    for (uint32_t i = 0; i < count; i++) {
        const cuda_moe_vram_promotion_reservation &reservation =
            reservations[i];
        if (!reservation.active || reservation.cache_slot >= cache->capacity) {
            continue;
        }
        if (reservation.victim_valid) {
            cuda_moe_tiering_demote_cache_entry(
                reservation.victim_layer, reservation.victim_expert,
                g133_epoch);
            const size_t old_map_index = cuda_moe_tiering_entry_index(
                reservation.victim_layer, reservation.victim_expert);
            if (old_map_index < cache->host_slot_by_layer_expert.size() &&
                cache->host_slot_by_layer_expert[old_map_index] ==
                    (int32_t)reservation.cache_slot) {
                cache->host_slot_by_layer_expert[old_map_index] = -1;
            }
        }
        const size_t new_map_index = cuda_moe_tiering_entry_index(
            reservation.candidate_layer, reservation.candidate_expert);
        if (new_map_index < cache->host_slot_by_layer_expert.size()) {
            cache->host_slot_by_layer_expert[new_map_index] =
                (int32_t)reservation.cache_slot;
        }
        if (reservation.free_promotion && cache->count < cache->capacity) {
            cache->count++;
            g_moe_tiering.policy_free_promotions++;
            if (g_moe_tiering.policy_admit_vram_enabled) {
                g_moe_tiering.policy_admit_window_free_vram++;
            }
        } else if (reservation.replacement) {
            cache->evictions++;
            g_moe_tiering.policy_replacements++;
            if (g_moe_tiering.policy_admit_vram_enabled) {
                g_moe_tiering.policy_admit_window_replacements_vram++;
            }
        }
        cache->admissions++;
        if (reservation.candidate_prior_state ==
                CUDA_MOE_TIER_RAM_PROBATION) {
            g_moe_tiering.ram_to_warm++;
        }
        if (reservation.from_snapshot) {
            g_moe_tiering.snapshot_to_vram_bytes += expert_bytes;
        }
        cuda_moe_tier_entry &candidate = g_moe_tiering.entries[new_map_index];
        candidate.state = CUDA_MOE_TIER_VRAM_PROTECTED;
        cuda_g133_mark_promotion(candidate, g133_epoch);
        g_moe_tiering.vram_promotions++;
        if (g_moe_tiering.g133_enabled) {
            cuda_g133_telemetry_increment(
                g_cuda_g133_telemetry.promotions);
            cuda_g133_telemetry_increment(
                g_cuda_g133_telemetry.knock_promotions);
        }
        g_moe_tiering.ram_h2d_bytes += expert_bytes;
    }
}

static void cuda_moe_tiering_refund_failed_promotions(
        const cuda_moe_vram_promotion_reservation *reservations,
        uint32_t count, const ds4_gpu_g133_epoch &g133_epoch) {
    if (!reservations) return;
    for (uint32_t i = 0; i < count; i++) {
        const cuda_moe_vram_promotion_reservation &reservation =
            reservations[i];
        if (!reservation.active) continue;
        if (reservation.policy_budget_reserved &&
            g_moe_tiering.policy_budget_remaining <
                g_moe_tiering.policy_replacement_budget) {
            g_moe_tiering.policy_budget_remaining++;
        }
        if (reservation.g133_budget_reserved) {
            cuda_g133_advisory_budget_refund();
        }
        cuda_moe_tier_entry &candidate = g_moe_tiering.entries[
            cuda_moe_tiering_entry_index(
                reservation.candidate_layer, reservation.candidate_expert)];
        candidate.state = reservation.candidate_prior_state;
        if (reservation.victim_valid) {
            /* Its device slot may be partially overwritten; failure rollback
             * therefore restores the candidate and coherently demotes the
             * no-longer-valid victim before whole-cache invalidation. */
            cuda_moe_tiering_demote_cache_entry(
                reservation.victim_layer, reservation.victim_expert,
                g133_epoch);
        }
    }
}

/* =======================================================================
 * INVALIDATE-SCOPED (DS4_CUDA_SCOPED_INVALIDATE=1, opt-in).
 *
 * Invariante protetto — lo stesso del reset totale: ogni voce della mappa
 * device (layer,expert)->slot visibile al resolver deve puntare a uno slot
 * i cui byte VRAM sono i pesi COMPLETI e CORRENTI di quella coppia, e gli
 * indici host (slots[], host_slot_by_layer_expert, count) devono
 * concordare.  Su una richiesta fallita le sole voci che possono violarlo
 * sono quelle del registro di prenotazione della richiesta stessa
 * (promotion_reservations): lo slot prenotato (byte eventualmente
 * sovrascritti a meta' dagli H2D accodati), la chiave candidata (publish
 * eventualmente eseguito) e la chiave vittima (publish eventualmente NON
 * eseguito con H2D gia' passato: mappa device stantia su byte
 * sovrascritti).  Ogni altro slot resta intatto per costruzione:
 * pick_vram_slot reclama solo gli slot del registro e le richieste sono
 * serializzate dalla mailbox.
 *
 * Il rollback mirato e' lecito SOLO a stream di upload provato quieto:
 * con publish ancora in volo la mappa device puo' mutare in un istante
 * arbitrario (ds4_cuda.cu, commento "A joined host worker is not a drained
 * CUDA producer").  transfer_ok del drain e' la prova nel caso comune
 * (G73_OPEN=0: poll senza deadline fino a quiescenza); altrimenti si
 * ri-polla con lo stesso bound di cancel_and_join e, se non si dimostra,
 * si ricade sul reset totale di oggi.
 *
 * Tutto il codice nuovo e' raggiungibile solo dalle specializzazioni
 * SCOPED=true del route worker, selezionate una volta all'init: a flag
 * spento le istanze compilate del percorso attivo sono le stesse di oggi.
 * ======================================================================= */
static std::atomic<uint32_t> g_moe_route_failure_scoped_sequence(0u);

static void cuda_moe_route_failure_scoped_sign(
        uint32_t sequence, uint32_t reservations,
        uint32_t slots_emptied, uint32_t victims_unmapped,
        const char *note) {
    if (sequence == 0u) return;
    g_moe_route_failure_scoped_sequence.store(
        sequence, std::memory_order_release);
    if (cuda_worker_profile_enabled()) {
        ds4_workerprof_add(WP_CACHE_INVALIDATES_SCOPED, 1u);
        ds4_workerprof_add(WP_CACHE_SCOPED_ENTRIES_DROPPED, slots_emptied);
        fprintf(stderr,
                "ds4: [cache-invalidate] scope=scoped seq=%u reservations=%u "
                "slots_emptied=%u victims_unmapped=%u note=%s\n",
                sequence, reservations, slots_emptied, victims_unmapped,
                note ? note : "none");
    }
}

static int cuda_moe_route_failure_scoped_consume(uint32_t sequence) {
    return sequence != 0u &&
        g_moe_route_failure_scoped_sequence.load(
            std::memory_order_acquire) == sequence;
}

static int cuda_moe_tiering_scoped_invalidate(
        cuda_moe_expert_cache *cache,
        const cuda_moe_vram_promotion_reservation *reservations,
        uint32_t count, uint32_t sequence, int stream_known_quiet) {
    if (!cache || !reservations || sequence == 0u) return 0;
    if (!stream_known_quiet && cache->route_upload_stream) {
        /* Drain fallito o non concluso: prova la quiescenza con lo stesso
         * bound del percorso cancel_and_join prima di toccare la mappa. */
        const double quiesce_deadline = cuda_wall_sec() + 5.0;
        cudaError_t status = cudaStreamQuery(cache->route_upload_stream);
        while (status == cudaErrorNotReady &&
               cuda_wall_sec() < quiesce_deadline) {
#ifdef _WIN32
            (void)SwitchToThread();
#else
            usleep(0);
#endif
            status = cudaStreamQuery(cache->route_upload_stream);
        }
        if (status != cudaSuccess) {
            (void)cudaGetLastError();
            return 0;
        }
    }
    uint32_t slots_emptied = 0u;
    uint32_t victims_unmapped = 0u;
    const int32_t empty_map_entry = -1;
    for (uint32_t i = 0; i < count; i++) {
        const cuda_moe_vram_promotion_reservation &reservation =
            reservations[i];
        if (!reservation.active ||
            reservation.cache_slot >= cache->capacity ||
            reservation.candidate_layer >= CUDA_MOE_LAYER_COUNT ||
            reservation.candidate_expert >= 256u) {
            continue;
        }
        cuda_moe_cache_slot &entry = cache->slots[reservation.cache_slot];
        /* Idempotente: il drain anticipato fallito e quello finale possono
         * rieseguire lo stesso registro; il secondo passaggio trova lo slot
         * gia' EMPTY e non riconta ne' ridecrementa. */
        const int first_pass = entry.state != CUDA_MOE_CACHE_EMPTY;
        const size_t new_map_index = cuda_moe_tiering_entry_index(
            reservation.candidate_layer, reservation.candidate_expert);
        if (new_map_index < cache->host_slot_by_layer_expert.size() &&
            cache->host_slot_by_layer_expert[new_map_index] ==
                (int32_t)reservation.cache_slot) {
            cache->host_slot_by_layer_expert[new_map_index] = -1;
        }
        if (cache->device_slot_by_layer_expert &&
            cudaMemcpy(cache->device_slot_by_layer_expert + new_map_index,
                       &empty_map_entry, sizeof(int32_t),
                       cudaMemcpyHostToDevice) != cudaSuccess) {
            (void)cudaGetLastError();
            return 0;
        }
        if (reservation.victim_valid &&
            reservation.victim_layer < CUDA_MOE_LAYER_COUNT &&
            reservation.victim_expert < 256u) {
            const size_t old_map_index = cuda_moe_tiering_entry_index(
                reservation.victim_layer, reservation.victim_expert);
            if (old_map_index < cache->host_slot_by_layer_expert.size() &&
                cache->host_slot_by_layer_expert[old_map_index] ==
                    (int32_t)reservation.cache_slot) {
                cache->host_slot_by_layer_expert[old_map_index] = -1;
            }
            if (cache->device_slot_by_layer_expert &&
                cudaMemcpy(cache->device_slot_by_layer_expert + old_map_index,
                           &empty_map_entry, sizeof(int32_t),
                           cudaMemcpyHostToDevice) != cudaSuccess) {
                (void)cudaGetLastError();
                return 0;
            }
            if (first_pass) {
                victims_unmapped++;
                if (cache->count > 0u) cache->count--;
            }
        }
        /* Il rollback di stato tier (candidato ripristinato, vittima
         * demansionata) e' gia' stato fatto da refund_failed_promotions,
         * chiamata prima di questa funzione: qui si azzera solo l'indice. */
        entry.state = CUDA_MOE_CACHE_EMPTY;
        entry.age = 0;
        entry.layer_key = 0;
        entry.layer_index = UINT32_MAX;
        entry.expert_id = UINT32_MAX;
        entry.layer_owned = 0;
        if (first_pass) slots_emptied++;
    }
    cuda_moe_route_failure_scoped_sign(
        sequence, count, slots_emptied, victims_unmapped,
        stream_known_quiet ? "drain-clean" : "quiesced");
    return 1;
}

/* DRAIN4 — braccio armato: sostituisce la coppia [drain bloccante -> VALID]
 * con [cudaEventRecord sull'upload stream -> commit ottimistico].
 * Raggiungibile SOLO dalle istanze DOV=true.  Ritorna 1 se l'overlap e'
 * armato (il chiamante salta il drain bloccante e invalida il batch del
 * registro, I4); ritorna 0 su QUALUNQUE precondizione mancante o fallimento
 * del record, e il chiamante esegue il percorso bloccante attuale riga per
 * riga — l'eventuale errore CUDA pendente NON viene azzerato qui (Peek, non
 * Get), cosi' la cudaGetLastError del percorso bloccante lo attribuisce
 * esattamente come oggi (niente errori inghiottiti).
 *
 * reservations/g133_epoch: non-NULL solo nel percorso ENFORCE (commit del
 * tiering sul confine ottimistico, I2); il percorso legacy non-ENFORCE
 * passa NULL e riceve solo la promozione LOADING->VALID degli slot admitted. */
static int cuda_moe_drain_overlap4_arm(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request,
        const uint32_t *admitted,
        const cuda_moe_vram_promotion_reservation *reservations,
        uint32_t admitted_count,
        const ds4_gpu_g133_epoch *g133_epoch) {
    if (!cache || !cache->route_upload_stream ||
        request.host_generation == 0u) {
        return 0;
    }
    /* §3.3 del disegno: mai armare sotto la policy condivisa G133 (Q1 /
     * SSD-wrap): quei percorsi leggono route_completed_* ai confini
     * (request-boundary, q1-0-mixed-entry, ...) come prova di quiescenza
     * del lavoro di rotta, e con un overlap armato la publicazione di
     * completed non implicherebbe piu' upload drenato. */
    if (cuda_g133_shared_policy_active()) return 0;
    if (!cuda_moe_drain_overlap4_events_ready()) return 0;
    if (cudaPeekAtLastError() != cudaSuccess) return 0;
    cudaEvent_t ready_event =
        g_moe_drain_overlap4.ready_event[request.host_generation & 1u];
    const cudaError_t record_error =
        cudaEventRecord(ready_event, cache->route_upload_stream);
    if (record_error != cudaSuccess) {
        fprintf(stderr,
                "ds4: [drain-overlap4] result=record-failed seq=%u layer=%u "
                "cuda=%s; ricado sul drain bloccante\n",
                request.sequence, request.layer_index,
                cudaGetErrorString(record_error));
        return 0;
    }
    /* Commit ottimistico (I2): nessun attore puo' osservare questi VALID
     * con copie in volo — i kernel consumer stanno dietro il waitEvent del
     * consumer, il riciclo degli slot dietro il claim-gate. */
    for (uint32_t i = 0; i < admitted_count; i++) {
        cache->slots[admitted[i]].state = CUDA_MOE_CACHE_VALID;
    }
    if (reservations && g133_epoch) {
        cuda_moe_tiering_commit_vram_reservations(
            cache, reservations, admitted_count, *g133_epoch);
    }
    /* I4, versione minima DICHIARATA: senza prova di completamento al
     * finish il batch H2D va invalidato, mai contabilizzato.  Una riga di
     * dichiarazione una-tantum accanto al registro, mai taciuta. */
    if (!g_moe_drain_overlap4.transport_note_emitted &&
        cuda_transport_ledger_enabled()) {
        g_moe_drain_overlap4.transport_note_emitted = 1;
        fprintf(stderr,
                "ds4: [transport] drain_overlap4=minimal: i batch H2D "
                "sotto overlap sono invalidati (ledger_complete=0 per "
                "disegno)\n");
    }
    /* Pubblicazione del sidecar: prima i timestamp (relaxed), poi la
     * generazione (release) — il consumer fa acquire sulla generazione. */
    g_moe_drain_overlap4.complete_ns.store(0u, std::memory_order_relaxed);
    g_moe_drain_overlap4.armed_ns.store(
        ds4_workerprof_now_ns(), std::memory_order_relaxed);
    g_moe_drain_overlap4.armed_generation.store(
        request.host_generation, std::memory_order_release);
    return 1;
}

template <bool SCOPED>
static int cuda_moe_tiering_finish_vram_reservations(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request *trace_request,
        const uint32_t *admitted,
        const cuda_moe_vram_promotion_reservation *reservations,
        uint32_t count, const ds4_gpu_g133_epoch &g133_epoch,
        int commit_on_success, double absolute_deadline) {
    const double sync_started = g_moe_tiering.g133_enabled
        ? cuda_wall_sec() : 0.0;
    const uint64_t trace_sync_started = trace_request
        ? cuda_decode_trace_request_qpc(*trace_request) : 0u;
    const cudaError_t pending_error = cudaGetLastError();
    const cudaError_t sync_error = cuda_g73_finish_launched_copy(
        cache->route_upload_stream, absolute_deadline,
        count > 0u ? reservations[0].candidate_layer : 0u,
        "tiering-reservation");
    cuda_decode_trace_note_upload_drain(
        trace_request, trace_sync_started);
    if (sync_started != 0.0) {
        cuda_g133_telemetry_note_upload_sync_wait(
            cuda_wall_sec() - sync_started);
    }
    const int transfer_ok =
        pending_error == cudaSuccess && sync_error == cudaSuccess;
    if (!transfer_ok || !commit_on_success) {
        (void)cudaGetLastError();
        cuda_moe_tiering_refund_failed_promotions(
            reservations, count, g133_epoch);
        if constexpr (SCOPED) {
            /* INVALIDATE-SCOPED: butta solo le voci del registro di questa
             * richiesta (fino a 6 slot su ~140) invece dell'intera cache, e
             * firma la sequence cosi' il consumer non riesegue il reset
             * totale.  count==0 (fallimento puramente transiente, nessuna
             * promozione accodata): la cache non e' stata toccata e non c'e'
             * nulla da buttare.  Se la quiescenza dello stream non e'
             * dimostrabile si ricade sul reset totale identico a oggi. */
            const uint32_t scoped_sequence =
                trace_request ? trace_request->sequence : 0u;
            if (count == 0u) {
                cuda_moe_route_failure_scoped_sign(
                    scoped_sequence, 0u, 0u, 0u, "no-reservations");
            } else if (!cuda_moe_tiering_scoped_invalidate(
                           cache, reservations, count,
                           scoped_sequence, transfer_ok)) {
                cuda_moe_expert_cache_invalidate(
                    "worker-enforce-failure-scoped-fallback");
            }
        } else {
            if (count > 0u) {
                cuda_moe_expert_cache_invalidate("worker-enforce-failure");
            }
        }
        return transfer_ok;
    }
    for (uint32_t i = 0; i < count; i++) {
        cache->slots[admitted[i]].state = CUDA_MOE_CACHE_VALID;
    }
    cuda_moe_tiering_commit_vram_reservations(
        cache, reservations, count, g133_epoch);
    return 1;
}

static void cuda_g73_classify_request(
        const cuda_moe_route_request &request,
        cuda_g73_route_outcomes *outcomes,
        uint8_t out_of_mask[CUDA_MOE_ROUTE_COUNT]) {
    if (!outcomes || !out_of_mask) return;
    *outcomes = cuda_g73_route_outcomes{};
    memset(out_of_mask, 0, CUDA_MOE_ROUTE_COUNT);
    for (uint32_t route = 0; route < request.route_count; route++) {
        const int32_t expert_i = request.selected[route];
        if (expert_i < 0 || expert_i >= 256) continue;
        char *gate = NULL;
        char *up = NULL;
        char *down = NULL;
        if (cuda_moe_tiering_snapshot_ram_ptrs(
                request.layer_index, (uint32_t)expert_i,
                &gate, &up, &down)) {
            continue;
        }
        out_of_mask[route] = 1u;
        outcomes->out_of_mask_routes++;
        /* A VRAM hit remains exact after its RAM probation backing is reaped. */
        if (request.hit_slots[route] >= 0) outcomes->served_promoted++;
    }
}

static void cuda_g73_publish_pending_outcomes(
        cuda_moe_expert_cache *cache, uint32_t sequence,
        const cuda_g73_route_outcomes &outcomes) {
    if (!cache) return;
    cache->route_g73_outcomes = outcomes;
    cache->route_g73_outcome_sequence = sequence;
}

struct cuda_moe_route_io_span {
    void *destination;
    uint64_t offset;
    uint64_t bytes;
    uint32_t expert;
    int transport_repeat;
};

#ifdef _WIN32
static void cuda_moe_route_io_qd_cancel_pending(
        cuda_moe_expert_cache *cache,
        const int pending[4],
        uint32_t count) {
    if (!cache || !g_model_file_valid) return;
    for (uint32_t i = 0; i < count; i++) {
        if (pending[i]) {
            (void)CancelIoEx(
                g_model_file.h, &cache->route_io_qd_overlapped[i]);
        }
    }
    for (uint32_t i = 0; i < count; i++) {
        if (!pending[i]) continue;
        DWORD ignored = 0;
        (void)GetOverlappedResult(
            g_model_file.h, &cache->route_io_qd_overlapped[i],
            &ignored, TRUE);
    }
}

static int cuda_moe_route_io_qd_read(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request,
        const cuda_moe_route_io_span *spans,
        uint32_t span_count,
        uint32_t route_count,
        double absolute_deadline) {
    if (!cache || cache->route_io_qd_requested != 4u ||
        !g_model_file_valid || !spans || span_count == 0u ||
        span_count > CUDA_MOE_ROUTE_COUNT * 3u || route_count == 0u ||
        span_count != route_count * 3u) {
        return 0;
    }
    for (uint32_t i = 0; i < 4u; i++) {
        if (!cache->route_io_qd_event[i]) return 0;
    }

    const double started_at = cuda_wall_sec();
    const int wprof = cuda_worker_profile_enabled();
    const uint64_t wprof_started = ds4_workerprof_start(wprof);
    /* WORKER-PROF: quante letture di QUESTA chiamata sono ancora in volo.
     * Serve per rimettere a zero il contatore globale anche quando il batch
     * esce per cancellazione o errore. */
    uint32_t wprof_outstanding = 0u;
    const uint64_t trace_started =
        cuda_decode_trace_request_qpc(request);
    uint64_t trace_submits = 0u;
    uint64_t trace_completions = 0u;
    uint64_t trace_bytes = 0u;
    uint64_t trace_max_inflight = 0u;
    cache->route_io_qd_calls++;
    cache->route_io_qd_routes += route_count;
    cache->route_io_qd_spans += span_count;
    int result = 1;
    uint32_t base = 0u;
    const uint64_t max_submit_bytes =
        cuda_route_io_qd_span_bytes_requested();
    cache->route_transient_io_sequence.store(
        request.sequence, std::memory_order_release);
    while (base < span_count && result == 1) {
        const uint32_t count =
            span_count - base < 4u ? span_count - base : 4u;
        uint64_t span_completed[4] = {0u, 0u, 0u, 0u};
        for (uint32_t i = 0; i < count; i++) {
            const cuda_moe_route_io_span &span = spans[base + i];
            if (!span.destination || span.bytes == 0u ||
                span.bytes > 0xffffffffull ||
                span.offset > g_model_file_size ||
                span.bytes > g_model_file_size - span.offset) {
                result = 0;
                break;
            }
        }

        int group_complete = 0;
        while (result == 1 && !group_complete) {
            int pending[4] = {0, 0, 0, 0};
            HANDLE events[4] = {NULL, NULL, NULL, NULL};
            uint32_t logical_slot[4] = {0u, 0u, 0u, 0u};
            uint64_t expected_bytes[4] = {0u, 0u, 0u, 0u};
            uint32_t submitted = 0u;
            group_complete = 1;
            for (uint32_t logical = 0; logical < count; logical++) {
                const cuda_moe_route_io_span &span =
                    spans[base + logical];
                if (span_completed[logical] == span.bytes) continue;
                group_complete = 0;
                const uint32_t slot = submitted++;
                const uint64_t remaining =
                    span.bytes - span_completed[logical];
                const uint64_t submit_bytes =
                    remaining < max_submit_bytes ?
                    remaining : max_submit_bytes;
                const uint64_t submit_offset =
                    span.offset + span_completed[logical];
                OVERLAPPED &overlapped =
                    cache->route_io_qd_overlapped[slot];
                memset(&overlapped, 0, sizeof(overlapped));
                overlapped.Offset =
                    (DWORD)(submit_offset & 0xffffffffu);
                overlapped.OffsetHigh = (DWORD)(submit_offset >> 32);
                overlapped.hEvent = cache->route_io_qd_event[slot];
                events[slot] = overlapped.hEvent;
                logical_slot[slot] = logical;
                expected_bytes[slot] = submit_bytes;
                (void)ResetEvent(overlapped.hEvent);
                const BOOL started = ReadFile(
                    g_model_file.h,
                    (uint8_t *)span.destination +
                        span_completed[logical],
                    (DWORD)submit_bytes, NULL, &overlapped);
                if (!started && GetLastError() != ERROR_IO_PENDING) {
                    result = 0;
                    break;
                }
                pending[slot] = 1;
                trace_submits++;
                cache->route_io_qd_submits++;
                if (wprof) {
                    ds4_workerprof_inflight_advance(
                        ds4_workerprof_now_ns(), 1);
                    wprof_outstanding++;
                }
            }
            if (submitted > trace_max_inflight) {
                trace_max_inflight = submitted;
            }
            if (submitted > cache->route_io_qd_max_inflight) {
                cache->route_io_qd_max_inflight = submitted;
            }

            while (result == 1 && submitted > 0u) {
                if (cache->route_transient_cancel_sequence.load(
                        std::memory_order_acquire) == request.sequence) {
                    result = -1;
                    break;
                }
                DWORD wait_ms = 5u;
                if (absolute_deadline > 0.0) {
                    const double remaining =
                        absolute_deadline - cuda_wall_sec();
                    if (remaining <= 0.0) {
                        result = -1;
                        break;
                    }
                    const double remaining_ms = remaining * 1000.0;
                    if (remaining_ms < (double)wait_ms) {
                        wait_ms = (DWORD)ceil(remaining_ms);
                        if (wait_ms == 0u) wait_ms = 1u;
                    }
                }
                const DWORD wait_result = WaitForMultipleObjects(
                    submitted, events, TRUE, wait_ms);
                if (wait_result == WAIT_OBJECT_0) break;
                if (wait_result != WAIT_TIMEOUT) {
                    result = 0;
                    break;
                }
            }

            if (result == 1) {
                for (uint32_t slot = 0; slot < submitted; slot++) {
                    DWORD got = 0;
                    const uint32_t logical = logical_slot[slot];
                    const cuda_moe_route_io_span &span =
                        spans[base + logical];
                    const BOOL completed = GetOverlappedResult(
                        g_model_file.h,
                        &cache->route_io_qd_overlapped[slot],
                        &got, FALSE);
                    if (got > 0u) {
                        ds4_transport_record_file_bytes(
                            span.transport_repeat, (uint64_t)got);
                    }
                    if (!completed ||
                        got != (DWORD)expected_bytes[slot]) {
                        result = 0;
                        break;
                    }
                    pending[slot] = 0;
                    span_completed[logical] += (uint64_t)got;
                    trace_completions++;
                    trace_bytes += (uint64_t)got;
                    cache->route_io_qd_completions++;
                    cache->route_io_qd_bytes += (uint64_t)got;
                    cache->route_transient_read_bytes.fetch_add(
                        (uint64_t)got, std::memory_order_release);
                    if (wprof && wprof_outstanding != 0u) {
                        ds4_workerprof_inflight_advance(
                            ds4_workerprof_now_ns(), -1);
                        wprof_outstanding--;
                        ds4_workerprof_add(WP_READ_CALLS, 1u);
                        ds4_workerprof_add(
                            WP_READ_BYTES, (uint64_t)got);
                    }
                }
            }
            if (result != 1) {
                cuda_moe_route_io_qd_cancel_pending(
                    cache, pending, submitted);
            }
            /* cancel_pending attende ogni richiesta ancora aperta, quindi dopo
             * questo punto il batch non ha piu' nulla in volo: il residuo va
             * scaricato o inflight resterebbe alto per sempre. */
            if (wprof && wprof_outstanding != 0u) {
                const uint64_t drained = ds4_workerprof_now_ns();
                while (wprof_outstanding != 0u) {
                    ds4_workerprof_inflight_advance(drained, -1);
                    wprof_outstanding--;
                }
            }
        }
        base += count;
    }
    cache->route_transient_io_sequence.store(
        0u, std::memory_order_release);
    ds4_workerprof_stop(wprof, WP_READ_QD_NS, wprof_started);

    cache->route_io_qd_seconds += cuda_wall_sec() - started_at;
    cuda_decode_trace_note_qd(
        request, trace_started, trace_submits, trace_completions,
        trace_bytes, trace_max_inflight);
    if (result != 1) {
        cache->route_io_qd_failures++;
        /* CancelIoEx/GetOverlappedResult is drained by the helper, but that
         * helper intentionally discards each cancelled request's byte count. */
        ds4_transport_mark_incomplete();
    }
    return result;
}
#endif

static int cuda_g132_general_requested(void) {
    return g_g132_cpu_lane.requested &&
        g_g132_cpu_lane.general_requested &&
        g_g132_cpu_lane.ready &&
        !g_g132_cpu_lane.failed_open;
}

static void cuda_g132_general_plan_release(
        cuda_moe_expert_cache *cache,
        cuda_g132_general_plan *plan) {
    if (!cache || !plan) return;
    for (uint32_t i = 0; i < plan->cpu_count; i++) {
        const cuda_g132_general_route &route = plan->routes[i];
        if (route.backing == CUDA_G132_CPU_LANE_BACKING_ARENA &&
            route.slot_identity < g_dynamic_arena.slots.size()) {
            cuda_dynamic_arena_slot_reader_release(
                &g_dynamic_arena.slots[route.slot_identity]);
        }
    }
    if (plan->staging_count != 0u) {
        uint64_t expected = plan->generation;
        (void)cache->route_cpu_staging_generation.compare_exchange_strong(
            expected, 0u, std::memory_order_acq_rel,
            std::memory_order_acquire);
    }
    *plan = cuda_g132_general_plan{};
}

static void cuda_g132_general_plan_begin(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request) {
    cuda_g132_general_plan &plan = cache->route_cpu_plan;
    cuda_g132_general_plan_release(cache, &plan);
    if (!request.cpu_lane_allowed || !cuda_g132_general_requested() ||
        g_g132_cpu_lane.async_fault ||
        request.route_count < 2u ||
        request.layer_index >= CUDA_G132_CPU_LANE_LAYER_COUNT) {
        /* async_fault: a CPU job failed after its join chain was already
         * enqueued; the lane fails closed from the next engagement on. */
        return;
    }
    plan.sequence = request.sequence;
    plan.generation = request.host_generation;
    plan.layer_index = request.layer_index;
    plan.route_count = request.route_count;
    os_mutex_lock(&g_g132_cpu_lane.mutex);
    /* lane_econ: timestamp of the worker-phase start.  prepare_general
     * reads it after finish(): the difference is the window the CPU lane
     * could overlap (resolver + staging + drain), measured per dispatch. */
    g_g132_cpu_lane.plan_begin_wall = cuda_wall_sec();
    const uint32_t adaptive_target =
        g_g132_cpu_lane.layer_target_cpu[request.layer_index];
    os_mutex_unlock(&g_g132_cpu_lane.mutex);
    plan.target_cpu = std::min(
        adaptive_target,
        std::min(g_g132_cpu_lane.max_experts_per_layer,
                 request.route_count - 1u));
}

static int cuda_g132_general_plan_admit(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request,
        uint32_t route,
        uint32_t expert,
        const char *host_gate,
        const char *host_up,
        const char *host_down,
        int have_ram,
        int from_nested,
        int demand_pipeline_active,
        uint32_t arena_slot,
        uint32_t ssd_wrap_h2d_ring) {
    cuda_g132_general_plan &plan = cache->route_cpu_plan;
    if (plan.sequence != request.sequence ||
        plan.generation != request.host_generation ||
        plan.target_cpu == 0u || route >= request.route_count ||
        !host_gate || !host_up || !host_down) {
        return 0;
    }
    plan.eligible++;
    if (plan.cpu_count >= plan.target_cpu) {
        if (plan.target_cpu >= g_g132_cpu_lane.max_experts_per_layer) {
            plan.rejected_cap++;
        } else {
            plan.rejected_balance++;
        }
        return 0;
    }
    if (from_nested) {
        g_g132_cpu_lane.general_fallback_contract++;
        return 0;
    }
    if (!have_ram && demand_pipeline_active) {
        /* P4a compacts later GPU misses toward route_host slot zero.  A CPU
         * reader of an earlier SSD slice would otherwise be overwritten. */
        g_g132_cpu_lane.general_fallback_pipeline++;
        return 0;
    }
    if (ssd_wrap_h2d_ring != UINT32_MAX) {
        g_g132_cpu_lane.general_fallback_wrap++;
        return 0;
    }

    cuda_g132_general_route admitted = {};
    admitted.gate = host_gate;
    admitted.up = host_up;
    admitted.down = host_down;
    admitted.route = route;
    admitted.expert = (int32_t)expert;
    admitted.weight = request.weights[route];
    admitted.slot_identity = UINT32_MAX;
    admitted.slot_generation = 0u;
    admitted.backing = have_ram
        ? CUDA_G132_CPU_LANE_BACKING_ARENA
        : CUDA_G132_CPU_LANE_BACKING_ROUTE_STAGING;
    if (have_ram) {
        if (arena_slot >= g_dynamic_arena.slots.size()) {
            g_g132_cpu_lane.general_fallback_reservation++;
            return 0;
        }
        cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[arena_slot];
        const int reader_acquired =
            cuda_dynamic_arena_slot_reader_acquire(&slot);
        if (!reader_acquired || slot.pageable || !slot.host_ptr ||
            slot.layer != request.layer_index || slot.expert != expert ||
            slot.content_generation == 0u ||
            host_gate != slot.host_ptr ||
            host_up != slot.host_ptr + cache->gate_expert_bytes ||
            host_down != host_up + cache->gate_expert_bytes) {
            if (reader_acquired) {
                cuda_dynamic_arena_slot_reader_release(&slot);
            }
            g_g132_cpu_lane.general_fallback_reservation++;
            return 0;
        }
        admitted.slot_identity = arena_slot;
        admitted.slot_generation = slot.content_generation;
    } else {
        uint64_t expected = 0u;
        if (!cache->route_cpu_staging_generation.compare_exchange_strong(
                expected, request.host_generation,
                std::memory_order_acq_rel, std::memory_order_acquire) &&
            expected != request.host_generation) {
            g_g132_cpu_lane.general_fallback_reservation++;
            return 0;
        }
        plan.staging_count++;
    }
    plan.routes[plan.cpu_count++] = admitted;
    plan.cpu_mask |= 1u << route;
    return 1;
}

template <bool G73, bool G132 = false, bool SCOPED = false, bool DOV = false>
static int cuda_moe_tiering_enforce_request(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request,
        uint8_t *claimed) {
    if (!cache || !claimed ||
        g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
        !cache->route_transient_gate || !cache->route_transient_up ||
        !cache->route_transient_down) {
        fprintf(stderr,
                "ds4: [tiering-enforce] result=refused layer=%u sequence=%u "
                "cache=%d claimed=%d mode=%u gate=%d up=%d down=%d\n",
                request.layer_index, request.sequence, cache != NULL,
                claimed != NULL, (unsigned)g_moe_tiering.mode,
                cache && cache->route_transient_gate,
                cache && cache->route_transient_up,
                cache && cache->route_transient_down);
        return 0;
    }
    uint32_t admitted[CUDA_MOE_ROUTE_COUNT] = {0};
    cuda_moe_vram_promotion_reservation
        promotion_reservations[CUDA_MOE_ROUTE_COUNT] = {};
    uint32_t admitted_count = 0;
    cuda_moe_route_publish_batch publish_batch = {};
    ds4_transport_h2d_batch transport_batch = {};
    /* P.5a: zero-copy routes get their own publish batch so they are neither
     * gated on DS4_CUDA_MOE_ROUTE_BATCHED_PUBLISH nor mixed into the demand
     * pipeline batch, whose flush contract requires count == miss_count. */
    cuda_moe_route_publish_batch zerocopy_batch = {};
    cuda_moe_demand_pipeline_batch demand_batch;
    cuda_moe_demand_pipeline_batch_init(&demand_batch);
    const int demand_pipeline_active =
        cache->demand_pipeline_requested &&
        !cuda_nested_residual_layer_required(request.layer_index);
    if (cache->demand_pipeline_requested && !demand_pipeline_active) {
        cache->demand_pipeline_legacy_layers++;
    }
    cuda_g73_route_outcomes g73_outcomes = {};
    uint8_t g73_out_of_mask[CUDA_MOE_ROUTE_COUNT] = {0};
    if constexpr (G73) {
        cuda_g73_classify_request(request, &g73_outcomes, g73_out_of_mask);
    }
    int ok = 1;
    const char *failure_reason = "none";
    /* WORKER-PROF: issato una volta per richiesta di rotta. */
    const int wprof = cuda_worker_profile_enabled();
    const int staged_kv_service_deadline =
        G73 && request.absolute_deadline <= 0.0 &&
        ds4_gpu_should_use_staged_kv_cache();
    const double transient_request_deadline = request.absolute_deadline > 0.0
        ? cuda_g73_io_deadline(request.absolute_deadline)
        : (staged_kv_service_deadline
            ? 0.0
            : cuda_wall_sec() + cuda_g133_transient_io_timeout_seconds());
    int transient_read_published = 0;
    /* FIX-B: ripieghi consumati da QUESTA richiesta di rotta. Se la richiesta
     * chiude senza averne avuto bisogno, la serie consecutiva riparte da zero. */
    uint32_t transient_fallbacks_used = 0u;
    if constexpr (G132) {
        cuda_g132_general_plan_begin(cache, request);
    }
    if (g_moe_tiering.compose_prefill_mass_tiering &&
        g_dynamic_arena.snapshot_generation !=
            g_moe_tiering.snapshot_generation) {
        g_moe_tiering.failures++;
        fprintf(stderr,
                "ds4: [tiering-enforce] result=snapshot-generation-mismatch "
                "layer=%u sequence=%u arena=%llu tier=%llu\n",
                request.layer_index, request.sequence,
                (unsigned long long)g_dynamic_arena.snapshot_generation,
                (unsigned long long)g_moe_tiering.snapshot_generation);
        if constexpr (G132) {
            cuda_g132_general_plan_release(
                cache, &cache->route_cpu_plan);
        }
        return 0;
    }
    /* The router has published this layer's exact miss list. Hint all three
     * tensor-major file slices now; this is cache population only and never
     * changes the later positioned-read/error path. */
    cuda_moe_route_prefetch_hint(request);
    uint8_t route_io_qd_ready[CUDA_MOE_ROUTE_COUNT] = {0};
#ifdef _WIN32
    if (G73 || cache->route_io_qd_allow_no_g73) {
        if (cache->route_io_qd_requested == 4u &&
            g_model_file_valid &&
            (!g_moe_tiering.compose_prefill_mass_tiering ||
             g_moe_tiering.compose_router_open) &&
            !cuda_nested_residual_layer_required(request.layer_index)) {
            cuda_moe_route_io_span
                spans[CUDA_MOE_ROUTE_COUNT * 3u] = {};
            uint32_t qd_misses[CUDA_MOE_ROUTE_COUNT] = {0};
            uint32_t span_count = 0u;
            uint32_t qd_miss_count = 0u;
            int plan_valid = 1;
            for (uint32_t miss = 0;
                 miss < request.miss_count && plan_valid; miss++) {
                const uint32_t route = request.miss_routes[miss];
                if (route >= request.route_count) {
                    plan_valid = 0;
                    break;
                }
                const int32_t expert_i = request.selected[route];
                if (expert_i < 0 || expert_i >= 256) {
                    plan_valid = 0;
                    break;
                }
                char *ignored_gate = NULL;
                char *ignored_up = NULL;
                char *ignored_down = NULL;
                const uint32_t expert = (uint32_t)expert_i;
                if (g_sparse_bake_active &&
                    !cuda_sparse_bake_expert_retained(
                        request.layer_index, expert)) {
                    plan_valid = 0;
                    break;
                }
                const int already_host_resident =
                    cuda_moe_tiering_snapshot_ram_ptrs(
                        request.layer_index, expert,
                        &ignored_gate, &ignored_up, &ignored_down) ||
                    cuda_moe_tiering_ram_ptrs(
                        request.layer_index, expert,
                        &ignored_gate, &ignored_up, &ignored_down);
                if (already_host_resident) continue;

                char *host_gate = cache->route_host_gate +
                    (uint64_t)miss * cache->gate_expert_bytes;
                char *host_up = cache->route_host_up +
                    (uint64_t)miss * cache->gate_expert_bytes;
                char *host_down = cache->route_host_down +
                    (uint64_t)miss * cache->down_expert_bytes;
                const uint64_t gate_src = request.gate_offset +
                    (uint64_t)expert * cache->gate_expert_bytes;
                const uint64_t up_src = request.up_offset +
                    (uint64_t)expert * cache->gate_expert_bytes;
                const uint64_t down_src = request.down_offset +
                    (uint64_t)expert * cache->down_expert_bytes;
                spans[span_count++] = cuda_moe_route_io_span{
                    host_gate, gate_src, cache->gate_expert_bytes, expert,
                    -1};
                spans[span_count++] = cuda_moe_route_io_span{
                    host_up, up_src, cache->gate_expert_bytes, expert,
                    -1};
                spans[span_count++] = cuda_moe_route_io_span{
                    host_down, down_src, cache->down_expert_bytes, expert,
                    -1};
                qd_misses[qd_miss_count++] = miss;
            }
            if (plan_valid && span_count > 0u) {
                for (uint32_t i = 0; i < qd_miss_count; i++) {
                    const uint32_t qd_miss = qd_misses[i];
                    const uint32_t qd_route = request.miss_routes[qd_miss];
                    const uint32_t qd_expert =
                        (uint32_t)request.selected[qd_route];
                    const int transport_repeat =
                        ds4_transport_file_load_begin(
                            request.layer_index, qd_expert);
                    for (uint32_t part = 0; part < 3u; part++) {
                        spans[i * 3u + part].transport_repeat =
                            transport_repeat;
                    }
                }
                os_pread_cancellable_reset(
                    &cache->route_transient_pread);
                cache->route_transient_read_bytes.store(
                    0u, std::memory_order_release);
                cache->route_transient_cancel_sequence.store(
                    0u, std::memory_order_release);
                cache->route_transient_timeout_cancel_sequence.store(
                    0u, std::memory_order_release);
                cache->route_transient_read_deadline =
                    transient_request_deadline;
                cache->route_transient_read_sequence.store(
                    request.sequence, std::memory_order_release);
                transient_read_published = 1;
                const int qd_result = cuda_moe_route_io_qd_read(
                    cache, request, spans, span_count,
                    qd_miss_count, transient_request_deadline);
                if (qd_result == 1) {
                    for (uint32_t i = 0; i < qd_miss_count; i++) {
                        route_io_qd_ready[qd_misses[i]] = 1u;
                    }
                } else if (qd_result < 0) {
                    g_moe_tiering.failures++;
                    failure_reason = "route-io-qd-timeout";
                    ok = 0;
                } else {
                    cache->route_io_qd_fallbacks++;
                }
            }
        }
    }
#endif
    for (uint32_t miss = 0; ok && miss < request.miss_count; miss++) {
        const uint32_t route = request.miss_routes[miss];
        if (route >= request.route_count) {
            failure_reason = "route-oob";
            ok = 0;
            break;
        }
        const int32_t expert_i = request.selected[route];
        if (expert_i < 0 || expert_i >= 256) {
            failure_reason = "expert-oob";
            ok = 0;
            break;
        }
        const uint32_t expert = (uint32_t)expert_i;
        if (g_sparse_bake_active &&
            !cuda_sparse_bake_expert_retained(request.layer_index, expert)) {
            g_sparse_bake_route_rejections++;
            fprintf(stderr,
                    "ds4: sparse bake rejected tiering route miss "
                    "layer=%u seq=%u route=%u expert=%u\n",
                    request.layer_index, request.sequence, route, expert);
            g_moe_tiering.failures++;
            failure_reason = "sparse-rejected";
            ok = 0;
            break;
        }
        cuda_moe_tier_entry &tier = g_moe_tiering.entries[
            cuda_moe_tiering_entry_index(request.layer_index, expert)];

        char *host_gate = NULL;
        char *host_up = NULL;
        char *host_down = NULL;
        /* P.5a needs the arena slot behind the RAM pointers to read its
         * pageable marker before serving the bytes to the kernel. */
        uint32_t zc_arena_slot = UINT32_MAX;
        int from_nested = 0;
        if (cuda_nested_residual_gpu_cache_requested() &&
            cuda_nested_residual_layer_required(request.layer_index)) {
            if (cuda_nested_residual_gpu_join_requested()) {
                from_nested = 1;
            } else {
                host_gate = cache->route_host_gate +
                    (uint64_t)miss * cache->gate_expert_bytes;
                host_up = cache->route_host_up +
                    (uint64_t)miss * cache->gate_expert_bytes;
                host_down = cache->route_host_down +
                    (uint64_t)miss * cache->down_expert_bytes;
                /* WORKER-PROF: lettura e ricostruzione sono fuse dentro questa
                 * chiamata (base + residuo in un solo passaggio), quindi la
                 * voce resta unica e NON viene divisa fra t_read e t_copy. */
                const uint64_t wprof_nested = ds4_workerprof_start(wprof);
                from_nested = cuda_nested_residual_fill_route_host_exact(
                    request.layer_index, expert,
                    request.gate_offset, request.up_offset, request.down_offset,
                    cache->gate_expert_bytes, cache->down_expert_bytes,
                    host_gate, host_up, host_down);
                ds4_workerprof_stop(wprof, WP_NESTED_FILL_NS, wprof_nested);
                if (from_nested != 1) {
                    failure_reason = "nested-exact";
                    ok = 0;
                    break;
                }
            }
        }
        const int from_snapshot = !from_nested &&
            cuda_moe_tiering_snapshot_ram_ptrs(
            request.layer_index, expert,
            &host_gate, &host_up, &host_down, &zc_arena_slot);
        const int from_probation = !from_nested && !from_snapshot &&
            cuda_moe_tiering_ram_ptrs(
                request.layer_index, expert,
                &host_gate, &host_up, &host_down, &zc_arena_slot);
        int have_ram = from_nested || from_snapshot || from_probation;
        if (from_snapshot) {
            g_moe_tiering.snapshot_backing_hits++;
        } else if (from_probation) {
            g_iq1_promotion.probation_ram_hits++;
        } else if (g_moe_tiering.compose_prefill_mass_tiering) {
            g_moe_tiering.snapshot_backing_misses++;
            if (!g_moe_tiering.compose_router_open) {
                g_moe_tiering.forbidden_cold_ssd_to_vram++;
                g_moe_tiering.failures++;
                failure_reason = "snapshot-miss";
                ok = 0;
                break;
            }
        }
        int ram_admission_denied = 0;
        if (!have_ram &&
            (!g_moe_tiering.compose_prefill_mass_tiering ||
             g_moe_tiering.compose_router_open) &&
            tier.state == CUDA_MOE_TIER_SSD_COLD &&
            !G73) {
            /* Mixed 5+1 keeps the five high-weight routes exact. An open
             * snapshot miss must first enter the pinned probation pool;
             * only the minimum-weight sixth route executes as IQ1_S and is
             * staged for a later token by the mixed path. */
            /* WORKER-PROF: promozione SSD -> arena pinnata.  Ramo vivo solo con
             * G73 spento (il compilatore lo elimina nell'istanza G73=true), ma
             * strumentato lo stesso: il residuo deve significare "non
             * attribuito", non "non strumentato". */
            const uint64_t wprof_load = ds4_workerprof_start(wprof);
            (void)cuda_moe_tiering_load_to_ram(
                request, request.layer_index, expert, NULL,
                &ram_admission_denied);
            ds4_workerprof_stop(wprof, WP_LOAD_RAM_NS, wprof_load);
            have_ram = cuda_moe_tiering_ram_ptrs(
                request.layer_index, expert,
                &host_gate, &host_up, &host_down, &zc_arena_slot);
        }
        if (!have_ram &&
            (!g_moe_tiering.compose_prefill_mass_tiering ||
             g_moe_tiering.compose_router_open) &&
            tier.state != CUDA_MOE_TIER_SSD_COLD &&
            !G73) {
            if (tier.state == CUDA_MOE_TIER_VRAM_PROTECTED) {
                /* A protected entry must have been resolved as a device-map
                 * hit before the miss worker. Never create a second resident
                 * slot for the same expert if that map invariant is broken. */
                g_moe_tiering.failures++;
                failure_reason = "vram-map-miss";
                ok = 0;
                break;
            }
            const cuda_moe_tier_state prior_state = tier.state;
            const uint32_t prior_ram_slot = tier.ram_slot;
            const uint64_t prior_ram_generation = tier.ram_generation;
            tier.state = CUDA_MOE_TIER_SSD_COLD;
            tier.ram_slot = UINT32_MAX;
            tier.ram_generation = 0;
            int retry_admission_denied = 0;
            const uint64_t wprof_load_retry = ds4_workerprof_start(wprof);
            (void)cuda_moe_tiering_load_to_ram(
                request, request.layer_index, expert, NULL,
                &retry_admission_denied);
            ds4_workerprof_stop(wprof, WP_LOAD_RAM_NS, wprof_load_retry);
            if (retry_admission_denied) {
                /* Policy denial is a serving decision, not a residency
                 * transition. Preserve the exact pre-attempt tier record. */
                tier.state = prior_state;
                tier.ram_slot = prior_ram_slot;
                tier.ram_generation = prior_ram_generation;
                ram_admission_denied = 1;
            }
            have_ram = cuda_moe_tiering_ram_ptrs(
                request.layer_index, expert,
                &host_gate, &host_up, &host_down, &zc_arena_slot);
        }
        if (!have_ram) {
            const int serve_transient_on_admission_denial =
                g_moe_tiering.compose_prefill_mass_tiering &&
                (ram_admission_denied ||
                 (G73 &&
                  g_moe_tiering.compose_router_open));
            if (g_moe_tiering.compose_prefill_mass_tiering &&
                !serve_transient_on_admission_denial) {
                g_moe_tiering.forbidden_cold_ssd_to_vram++;
                g_moe_tiering.failures++;
                failure_reason = "ram-required";
                ok = 0;
                break;
            }
            /* A policy-denied SSD serve is independent of promotions already
             * enqueued for other experts. Publish or refund those reservations
             * before entering a potentially slow blocking read. */
            if (admitted_count > 0u && !demand_pipeline_active) {
                const double early_publish_started = cuda_moe_zerocopy_now_ms();
                const int early_publish_ok =
                    !cache->batched_publish_requested ||
                    cuda_moe_route_publish_batch_flush(
                        cache, request, &publish_batch);
                const double early_publish_ms =
                    cuda_moe_zerocopy_now_ms() - early_publish_started;
                g_moe_zerocopy.t_orchestration_ms += early_publish_ms;
                /* WORKER-PROF: riusa il delta gia' calcolato, non ricronometra. */
                ds4_workerprof_add_ms(wprof, WP_PUBLISH_NS, early_publish_ms);
                if (!early_publish_ok) {
                    failure_reason = "publish-before-transient";
                    ok = 0;
                    break;
                }
                const double early_drain_started = cuda_moe_zerocopy_now_ms();
                const int early_finish_ok =
                    cuda_moe_tiering_finish_vram_reservations<SCOPED>(
                        cache, &request, admitted, promotion_reservations,
                        admitted_count, request.g133_epoch, 1,
                        request.absolute_deadline);
                ds4_transport_h2d_batch_finish(
                    &transport_batch, early_finish_ok);
                const double early_drain_ms =
                    cuda_moe_zerocopy_now_ms() - early_drain_started;
                g_moe_zerocopy.t_drain_ms += early_drain_ms;
                g_moe_zerocopy.t_orchestration_ms += early_drain_ms;
                ds4_workerprof_add_ms(wprof, WP_DRAIN_NS, early_drain_ms);
                if (!early_finish_ok) {
                    failure_reason = "resident-copy-before-transient";
                    ok = 0;
                    break;
                }
                admitted_count = 0u;
            }
            /* Exact non-resident serve: SSD -> per-route host staging -> the
             * existing transient GPU buffers below. Admission denial must not
             * alter tier state or make decode availability policy-dependent. */
            host_gate = cache->route_host_gate +
                (uint64_t)miss * cache->gate_expert_bytes;
            host_up = cache->route_host_up +
                (uint64_t)miss * cache->gate_expert_bytes;
            host_down = cache->route_host_down +
                (uint64_t)miss * cache->down_expert_bytes;
            const uint64_t gate_src = request.gate_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t up_src = request.up_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t down_src = request.down_offset +
                (uint64_t)expert * cache->down_expert_bytes;
            int read_result = route_io_qd_ready[miss] ? 1 : 0;
            int transport_repeat = -1;
            /* FIX-B: tensori gia' completi quando il timeout scade, cosi' il
             * ripiego rilegge solo cio' che manca (0=nessuno, 1=gate, 2=gate+up). */
            uint32_t transient_stage_done = 0u;
            if (read_result != 1 && g_model_file_valid) {
                transport_repeat = ds4_transport_file_load_begin(
                    request.layer_index, expert);
                if (!transient_read_published) {
                    os_pread_cancellable_reset(
                        &cache->route_transient_pread);
                    cache->route_transient_read_bytes.store(
                        0u, std::memory_order_release);
                    cache->route_transient_cancel_sequence.store(
                        0u, std::memory_order_release);
                    cache->route_transient_timeout_cancel_sequence.store(
                        0u, std::memory_order_release);
                    cache->route_transient_read_deadline =
                        transient_request_deadline;
                    cache->route_transient_read_sequence.store(
                        request.sequence, std::memory_order_release);
                    /* DRAIN3-STRUM: budget residuo del guardiano al PRIMO
                     * ingresso transiente della richiesta.  Il timer parte
                     * all'ingresso in enforce (transient_request_deadline,
                     * testa della funzione): quel che manca qui e' stato
                     * bruciato DENTRO la richiesta prima di leggere (drain
                     * anticipato, load RAM), non dalla lettura stessa.
                     * Discrimina "IO lento" da "budget consumato a monte"
                     * nei run che abortiscono con transient-io-timeout. */
                    if (wprof && transient_request_deadline > 0.0) {
                        const double drain3_slack_sec =
                            transient_request_deadline - cuda_wall_sec();
                        ds4_workerprof_add(WP_DEADLINE_SLACK_EVENTS, 1u);
                        if (drain3_slack_sec > 0.0) {
                            ds4_workerprof_add(
                                WP_DEADLINE_SLACK_NS,
                                (uint64_t)(drain3_slack_sec * 1.0e9));
                        } else {
                            ds4_workerprof_add(WP_DEADLINE_EXHAUSTED, 1u);
                        }
                    }
                    transient_read_published = 1;
                }
                /* GGUF stores gate/up/down as three tensor-major planes, so
                 * one expert's slices are not source-contiguous. READ_WHOLE
                 * therefore performs one cancellable positioned read per
                 * tensor (three per expert), into the existing full-size
                 * route staging slices. The OFF branch retains 1 MiB pacing. */
                /* WORKER-PROF: i tre tensori sono cronometrati al sito di
                 * chiamata perche' e' l'unico punto in cui gate / up / down
                 * sono distinguibili: dentro la funzione a chunk restano tre
                 * span anonimi.  Il tempo misurato include il pacing a 1 MiB
                 * e i controlli di cancellazione, che e' esattamente cio' che
                 * il worker spende "dentro la lettura". */
                const uint64_t wprof_gate = ds4_workerprof_start(wprof);
                read_result = cuda_moe_transient_pread_chunked(
                    cache, request.sequence,
                    request.trace_sample_id, request.layer_index,
                    transport_repeat,
                    &g_model_file, host_gate,
                    cache->gate_expert_bytes, gate_src,
                    transient_request_deadline);
                ds4_workerprof_stop(wprof, WP_READ_GATE_NS, wprof_gate);
                if (read_result == 1) {
                    transient_stage_done = 1u;
                    const uint64_t wprof_up = ds4_workerprof_start(wprof);
                    read_result = cuda_moe_transient_pread_chunked(
                        cache, request.sequence,
                        request.trace_sample_id, request.layer_index,
                        transport_repeat,
                        &g_model_file, host_up,
                        cache->gate_expert_bytes, up_src,
                        transient_request_deadline);
                    ds4_workerprof_stop(wprof, WP_READ_UP_NS, wprof_up);
                }
                if (read_result == 1) {
                    transient_stage_done = 2u;
                    const uint64_t wprof_down = ds4_workerprof_start(wprof);
                    read_result = cuda_moe_transient_pread_chunked(
                        cache, request.sequence,
                        request.trace_sample_id, request.layer_index,
                        transport_repeat,
                        &g_model_file, host_down,
                        cache->down_expert_bytes, down_src,
                        transient_request_deadline);
                    ds4_workerprof_stop(wprof, WP_READ_DOWN_NS, wprof_down);
                }
            }
            /* FIX-B intervento 1. Con il flag spento questo blocco non esiste
             * (una sola getenv cachata) e il timeout resta terminale come oggi. */
            if (read_result < 0 &&
                cuda_transient_timeout_recoverable_requested()) {
                const char *fallback_skipped_reason = "not-attempted";
                const uint64_t streak =
                    g_transient_timeout_fallback_streak.load(
                        std::memory_order_relaxed);
                const uint64_t max_fallbacks =
                    cuda_transient_timeout_max_fallbacks();
                if (streak >= max_fallbacks) {
                    g_transient_timeout_aborts.fetch_add(
                        1u, std::memory_order_relaxed);
                    fprintf(stderr,
                            "ds4: [transient-timeout] result=abort layer=%u "
                            "sequence=%u expert=%u consecutive_fallbacks=%llu "
                            "max_fallbacks=%llu "
                            "reason=fallback-budget-exhausted "
                            "fallback_skipped_reason=budget-exhausted\n",
                            request.layer_index, request.sequence, expert,
                            (unsigned long long)streak,
                            (unsigned long long)max_fallbacks);
                } else if (cuda_moe_transient_timeout_fallback_serve(
                               cache, request, transport_repeat,
                               transient_stage_done,
                               host_gate, host_up, host_down,
                               gate_src, up_src, down_src,
                               &fallback_skipped_reason)) {
                    transient_fallbacks_used++;
                    g_transient_timeout_fallback_streak.fetch_add(
                        1u, std::memory_order_relaxed);
                    g_transient_timeout_fallbacks.fetch_add(
                        1u, std::memory_order_relaxed);
                    read_result = 1;
                } else {
                    g_transient_timeout_aborts.fetch_add(
                        1u, std::memory_order_relaxed);
                    fprintf(stderr,
                            "ds4: [transient-timeout] result=abort layer=%u "
                            "sequence=%u expert=%u "
                            "reason=fallback-unavailable "
                            "fallback_skipped_reason=%s\n",
                            request.layer_index, request.sequence, expert,
                            fallback_skipped_reason);
                }
            }
            if (read_result != 1) {
                g_moe_tiering.failures++;
                failure_reason = read_result < 0
                    ? "transient-io-timeout" : "pread";
                ok = 0;
                break;
            }
            g_moe_tiering.ssd_bytes +=
                cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
            g_moe_zerocopy.ssd_served++;
        }

        uint32_t ssd_wrap_h2d_ring = UINT32_MAX;
        if (have_ram && !from_nested && g_q1_0_ssd_wrap.enabled) {
            const int pageable = cuda_q1_0_ssd_wrap_host_is_pageable(
                request.layer_index, expert, from_snapshot, from_probation);
            /* WORKER-PROF: t_copy.  E' l'unico staging verso un buffer pinnato
             * presente su questo percorso; le pread scrivono gia' direttamente
             * nelle slice pinnate route_host_*, quindi senza il wrap attivo
             * copy_ms resta zero - ed e' un fatto, non un buco di misura. */
            const uint64_t wprof_copy = ds4_workerprof_start(wprof);
            /* Corto-circuito preservato: con pageable < 0 la prepare non viene
             * chiamata, esattamente come prima della strumentazione. */
            const int wrap_ok = pageable >= 0 &&
                cuda_q1_0_ssd_wrap_prepare_h2d_source(
                    &host_gate, &host_up, &host_down,
                    cache->gate_expert_bytes, cache->down_expert_bytes,
                    pageable, &ssd_wrap_h2d_ring);
            ds4_workerprof_stop(wprof, WP_COPY_NS, wprof_copy);
            if (!wrap_ok) {
                failure_reason = "ssd-wrap-host-source";
                ok = 0;
                break;
            }
        }

        /* ---------------------------------------------------------------
         * P.5a ZERO-COPY DISPATCH.
         *
         * Perimeter (all must hold, every refusal counted):
         *   - mode != OFF and the device advertises UVA + mapped host memory;
         *   - tiering enforce (we are inside it) with the PRIMARY arena;
         *   - have_ram == 1 for this route, i.e. the bytes are already in the
         *     pinned arena, so no SSD read is bypassed;
         *   - not a nested/residual layer (its host buffers are the per-route
         *     staging slices, not arena slots);
         *   - the Q1_0 SSD wrap is off, because it rewrites host_gate/up/down
         *     to a ring buffer;
         *   - the P4a demand pipeline is off for this layer, because its flush
         *     asserts publish.count == miss_count;
         *   - the arena slot is not pageable, the triple is inside
         *     [host_base, host_base + allocated_bytes) and 16B aligned.
         *
         * In VALVE mode the route is additionally required to be the first
         * touch of this (layer,expert) inside the decay window; a repeat touch
         * deliberately falls through to slot+H2D so that reused experts still
         * become resident.
         *
         * Pointer lifetime. A zero-copy route keeps the kernel reading the
         * arena slot for the whole layer, not just until a copy drains, so the
         * slot must not be rewritten underneath it. That is already
         * guaranteed: cuda_moe_route_mailbox_worker_claim fails closed unless
         * the previous generation's route_consumer_done_event has completed,
         * so the worker cannot start serving request N+1 - and therefore
         * cannot admit anything new into the arena - before request N's
         * consumer kernels have finished on stream 0. This is the same
         * handshake that protects the shared route_transient_* buffers.
         *
         * Extension point for P.5a V-B (resolver serves host pointers by
         * itself, removing the B2/B3/W rendezvous for all-hit layers): the
         * host-side lookup array would be published here, at the same instant
         * this route is proven arena-resident. V-B is deliberately NOT
         * implemented in this patch.
         * --------------------------------------------------------------- */
        /* Touched once per miss route in every mode, SSD-only misses included,
         * so distinct_experts is a true working-set measure and the two A/B
         * arms report the same quantity. */
        const int zc_first_touch =
            cuda_moe_zerocopy_touch(request.layer_index, expert);
        int zerocopy_route = 0;
        if (have_ram) {
            const cuda_moe_zerocopy_state &zc_mode = g_moe_zerocopy;
            if (zc_mode.mode != CUDA_MOE_ZEROCOPY_OFF) {
                if (from_nested ||
                    cuda_nested_residual_layer_required(request.layer_index)) {
                    g_moe_zerocopy.rejected_nested++;
                } else if (g_q1_0_ssd_wrap.enabled) {
                    g_moe_zerocopy.rejected_wrap++;
                } else if (demand_pipeline_active) {
                    g_moe_zerocopy.rejected_pipeline++;
                } else if (zc_mode.mode == CUDA_MOE_ZEROCOPY_VALVE &&
                           !zc_first_touch) {
                    g_moe_zerocopy.promoted++;
                } else if (cuda_moe_zerocopy_pointers_admissible(
                               host_gate, host_up, host_down,
                               cache->gate_expert_bytes,
                               cache->down_expert_bytes,
                               zc_arena_slot)) {
                    zerocopy_route = 1;
                    if (zc_mode.mode == CUDA_MOE_ZEROCOPY_VALVE) {
                        g_moe_zerocopy.first_touch++;
                    }
                }
            }
        }
        if (zerocopy_route) {
            const double zc_publish_started = cuda_moe_zerocopy_now_ms();
            const int zc_publish_ok =
                cuda_moe_route_publish_batch_append_host(
                    &zerocopy_batch, route,
                    (uint64_t)(uintptr_t)host_gate,
                    (uint64_t)(uintptr_t)host_up,
                    (uint64_t)(uintptr_t)host_down);
            {
                const double zc_publish_ms =
                    cuda_moe_zerocopy_now_ms() - zc_publish_started;
                g_moe_zerocopy.t_orchestration_ms += zc_publish_ms;
                ds4_workerprof_add_ms(wprof, WP_PUBLISH_NS, zc_publish_ms);
            }
            if (!zc_publish_ok) {
                failure_reason = "zerocopy-publish-append";
                ok = 0;
                break;
            }
            g_moe_zerocopy.zc_served++;
            g_moe_zerocopy.zc_bytes +=
                cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
            if constexpr (G73) {
                /* A zero-copy serve leaves the expert non-resident, exactly
                 * like a transient serve, so the G73 conservation ledger must
                 * see it the same way and the rotation policy must be the
                 * same. Only the transport differs. */
                if (g73_out_of_mask[route]) g73_outcomes.served_transient++;
                cuda_g73_open_maybe_schedule_rotation(
                    request, route, expert, tier);
            }
            continue;
        }

        /* Transport accounting is representation-neutral: for supported nested
         * types, base plus residual bytes equal the native expert byte count. */
        cuda_moe_vram_promotion_reservation pending_reservation = {};
        const double pick_started = cuda_moe_zerocopy_now_ms();
        const int cache_slot_i = have_ram ?
            cuda_moe_tiering_pick_vram_slot(
                cache, claimed, tier, &pending_reservation,
                request.g133_epoch) : -1;
        {
            /* WORKER-PROF: scelta dello slot VRAM e contabilita' di sfratto.
             * E' la parte di orchestrazione che non e' ne' lettura ne'
             * trasporto, e va isolata o finirebbe nel residuo. */
            const double pick_ms = cuda_moe_zerocopy_now_ms() - pick_started;
            g_moe_zerocopy.t_orchestration_ms += pick_ms;
            ds4_workerprof_add_ms(wprof, WP_SLOTPICK_NS, pick_ms);
        }
        const int promote = cache_slot_i >= 0;
        if (promote) {
            const uint32_t cache_slot = (uint32_t)cache_slot_i;
            claimed[cache_slot] = 1u;
            cuda_moe_cache_slot &entry = cache->slots[cache_slot];
            pending_reservation.active = 1u;
            pending_reservation.cache_slot = cache_slot;
            pending_reservation.candidate_layer = request.layer_index;
            pending_reservation.candidate_expert = expert;
            pending_reservation.candidate_prior_state = tier.state;
            pending_reservation.from_snapshot = from_snapshot ? 1u : 0u;
            admitted[admitted_count++] = cache_slot;
            promotion_reservations[admitted_count - 1u] = pending_reservation;
            int32_t old_map_index = -1;
            const int was_valid = entry.state == CUDA_MOE_CACHE_VALID;
            if (was_valid && entry.layer_index < CUDA_MOE_LAYER_COUNT &&
                entry.expert_id < 256u) {
                /* P.5a: this is the direct anti-eviction measurement. A miss
                 * that lands on an already VALID slot throws a resident expert
                 * out. The zero-copy branch never reaches this point. */
                g_moe_zerocopy.evictions_caused_by_miss++;
                promotion_reservations[admitted_count - 1u].victim_valid = 1u;
                promotion_reservations[admitted_count - 1u].victim_layer =
                    entry.layer_index;
                promotion_reservations[admitted_count - 1u].victim_expert =
                    entry.expert_id;
                old_map_index = (int32_t)(
                    entry.layer_index * 256u + entry.expert_id);
            }
            entry.state = CUDA_MOE_CACHE_LOADING;
            const uint64_t gate_dst =
                (uint64_t)cache_slot * cache->gate_expert_bytes;
            const uint64_t down_dst =
                (uint64_t)cache_slot * cache->down_expert_bytes;
            const uint64_t resident_pitch =
                (uint64_t)cache->capacity * cache->gate_expert_bytes;
            const uint64_t source_pitch =
                (from_nested || (!have_ram && !from_snapshot)) ?
                    (uint64_t)CUDA_MOE_ROUTE_COUNT *
                        cache->gate_expert_bytes :
                    cache->gate_expert_bytes;
            const double h2d_enqueue_started =
                from_nested && g_nested_residual.profile_enabled ?
                cuda_wall_sec() : 0.0;
            const uint32_t demand_batch_slot =
                demand_batch.publish.count;
            const double deliver_started = cuda_moe_zerocopy_now_ms();
            if (!demand_pipeline_active) {
                ds4_transport_h2d_batch_begin(&transport_batch);
            }
            const int copy_ok =
                demand_pipeline_active ?
                cuda_moe_demand_pipeline_stage_host(
                    cache, &demand_batch,
                    host_gate, host_up, host_down,
                    ssd_wrap_h2d_ring) :
                (from_nested && cuda_nested_residual_gpu_join_requested() ?
                cuda_nested_residual_join_to_device_exact(
                    request.layer_index, expert,
                    request.gate_offset, request.up_offset,
                    request.down_offset,
                    cache->gate_expert_bytes, cache->down_expert_bytes,
                    cache->gate + gate_dst,
                    cache->up + gate_dst,
                    cache->down + down_dst,
                    cache->route_upload_stream) == 1 :
                (cache->packed_copy_requested ?
                    cuda_moe_route_copy_expert_h2d_async(
                        cache,
                        &request,
                        cache->gate + gate_dst,
                        cache->up + gate_dst,
                        cache->down + down_dst,
                        resident_pitch,
                        host_gate, host_up, host_down,
                        source_pitch) :
                    cuda_moe_route_legacy_copy_expert_h2d_async(
                        cache,
                        &request,
                        cache->gate + gate_dst,
                        cache->up + gate_dst,
                        cache->down + down_dst,
                        host_gate, host_up, host_down)));
            {
                /* WORKER-PROF: t_copy verso il device, cioe' la sola
                 * ACCODATURA dell'H2D; il costo del trasferimento vero e'
                 * misurato piu' avanti come drain. */
                const double deliver_ms =
                    cuda_moe_zerocopy_now_ms() - deliver_started;
                g_moe_zerocopy.t_deliver_ms += deliver_ms;
                ds4_workerprof_add_ms(wprof, WP_DELIVER_NS, deliver_ms);
            }
            if (copy_ok) {
                ds4_transport_h2d_batch_append(
                    &transport_batch, request.layer_index, expert,
                    cache->gate_expert_bytes * 2ull +
                        cache->down_expert_bytes);
            } else if (!demand_pipeline_active) {
                ds4_transport_h2d_batch_invalidate(&transport_batch);
            }
            if (copy_ok) {
                g_moe_zerocopy.h2d_served++;
                g_moe_zerocopy.h2d_bytes +=
                    cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
            }
            if (from_nested && g_nested_residual.profile_enabled) {
                g_nested_residual.profile_h2d_enqueue_calls++;
                g_nested_residual.profile_h2d_enqueue_seconds +=
                    cuda_wall_sec() - h2d_enqueue_started;
            }
            if (!copy_ok) {
                if (from_nested) g_nested_residual.gpu_cache_failures++;
                failure_reason = "resident-copy";
                ok = 0;
                break;
            }
            if (!demand_pipeline_active &&
                !cuda_q1_0_ssd_wrap_record_h2d(
                    ssd_wrap_h2d_ring, cache->route_upload_stream)) {
                failure_reason = "ssd-wrap-h2d-event";
                ok = 0;
                break;
            }
            if (from_nested && cuda_nested_residual_gpu_join_requested()) {
                g_nested_residual.route_h2d_bytes +=
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
            }
            const uint64_t gate_src = request.gate_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t up_src = request.up_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t down_src = request.down_offset +
                (uint64_t)expert * cache->down_expert_bytes;
            const uint32_t new_map_index =
                request.layer_index * 256u + expert;
            int publish_ok = 0;
            if (demand_pipeline_active) {
                publish_ok = cuda_moe_route_publish_batch_append(
                    &demand_batch.publish, old_map_index, new_map_index,
                    cache_slot, route, demand_batch_slot, 1u);
            } else if (cache->batched_publish_requested) {
                publish_ok = cuda_moe_route_publish_batch_append(
                    &publish_batch, old_map_index, new_map_index,
                    cache_slot, route, 0u, 1u);
            } else {
                moe_publish_resident_route_kernel<<<
                        1, 1, 0, cache->route_upload_stream>>>(
                    cache->device_slot_by_layer_expert,
                    cache->device_route_ptrs,
                    old_map_index,
                    new_map_index,
                    cache_slot,
                    request.route_count,
                    route,
                    cache->gate,
                    cache->up,
                    cache->down,
                    cache->gate_expert_bytes,
                    cache->down_expert_bytes);
                publish_ok = cudaGetLastError() == cudaSuccess;
                if (publish_ok) {
                    cache->legacy_publish_kernels++;
                    cuda_decode_trace_note_publish(
                        request, 1u, 1u);
                }
            }
            if (!publish_ok) {
                (void)cudaGetLastError();
                failure_reason = "resident-publish";
                ok = 0;
                break;
            }
            entry.key = {gate_src, up_src, down_src};
            entry.layer_index = request.layer_index;
            entry.expert_id = expert;
            entry.age = ++cache->tick;
            entry.layer_owned = 0;
            entry.layer_key = request.gate_offset;
            if constexpr (G73) {
                if (g73_out_of_mask[route]) {
                    g73_outcomes.served_promoted++;
                }
            }
        } else {
            if constexpr (G132) {
                if (request.cpu_lane_allowed &&
                    cuda_g132_general_plan_admit(
                        cache, request, route, expert,
                        host_gate, host_up, host_down,
                        have_ram, from_nested, demand_pipeline_active,
                        zc_arena_slot,
                        ssd_wrap_h2d_ring)) {
                    g_moe_tiering.transient++;
                    if constexpr (G73) {
                        if (g73_out_of_mask[route]) {
                            g73_outcomes.served_transient++;
                        }
                        cuda_g73_open_maybe_schedule_rotation(
                            request, route, expert, tier);
                    }
                    continue;
                }
            }
            if (from_snapshot) {
                g_moe_tiering.snapshot_to_vram_bytes +=
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
            }
            const uint64_t gate_dst =
                (uint64_t)route * cache->gate_expert_bytes;
            const uint64_t down_dst =
                (uint64_t)route * cache->down_expert_bytes;
            const uint64_t transient_pitch =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * cache->gate_expert_bytes;
            const uint64_t source_pitch =
                (from_nested || (!have_ram && !from_snapshot)) ?
                    transient_pitch : cache->gate_expert_bytes;
            const double h2d_enqueue_started =
                from_nested && g_nested_residual.profile_enabled ?
                cuda_wall_sec() : 0.0;
            const uint32_t demand_batch_slot =
                demand_batch.publish.count;
            const double deliver_started = cuda_moe_zerocopy_now_ms();
            if (!demand_pipeline_active) {
                ds4_transport_h2d_batch_begin(&transport_batch);
            }
            const int copy_ok =
                demand_pipeline_active ?
                cuda_moe_demand_pipeline_stage_host(
                    cache, &demand_batch,
                    host_gate, host_up, host_down,
                    ssd_wrap_h2d_ring) :
                (from_nested && cuda_nested_residual_gpu_join_requested() ?
                cuda_nested_residual_join_to_device_exact(
                    request.layer_index, expert,
                    request.gate_offset, request.up_offset,
                    request.down_offset,
                    cache->gate_expert_bytes, cache->down_expert_bytes,
                    cache->route_transient_gate + gate_dst,
                    cache->route_transient_up + gate_dst,
                    cache->route_transient_down + down_dst,
                    cache->route_upload_stream) == 1 :
                (cache->packed_copy_requested ?
                    cuda_moe_route_copy_expert_h2d_async(
                        cache,
                        &request,
                        cache->route_transient_gate + gate_dst,
                        cache->route_transient_up + gate_dst,
                        cache->route_transient_down + down_dst,
                        transient_pitch,
                        host_gate, host_up, host_down,
                        source_pitch) :
                    cuda_moe_route_legacy_copy_expert_h2d_async(
                        cache,
                        &request,
                        cache->route_transient_gate + gate_dst,
                        cache->route_transient_up + gate_dst,
                        cache->route_transient_down + down_dst,
                        host_gate, host_up, host_down)));
            {
                /* WORKER-PROF: t_copy verso il device, cioe' la sola
                 * ACCODATURA dell'H2D; il costo del trasferimento vero e'
                 * misurato piu' avanti come drain. */
                const double deliver_ms =
                    cuda_moe_zerocopy_now_ms() - deliver_started;
                g_moe_zerocopy.t_deliver_ms += deliver_ms;
                ds4_workerprof_add_ms(wprof, WP_DELIVER_NS, deliver_ms);
            }
            if (copy_ok) {
                ds4_transport_h2d_batch_append(
                    &transport_batch, request.layer_index, expert,
                    cache->gate_expert_bytes * 2ull +
                        cache->down_expert_bytes);
            } else if (!demand_pipeline_active) {
                ds4_transport_h2d_batch_invalidate(&transport_batch);
            }
            if (copy_ok) {
                g_moe_zerocopy.h2d_served++;
                g_moe_zerocopy.h2d_bytes +=
                    cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
            }
            if (from_nested && g_nested_residual.profile_enabled) {
                g_nested_residual.profile_h2d_enqueue_calls++;
                g_nested_residual.profile_h2d_enqueue_seconds +=
                    cuda_wall_sec() - h2d_enqueue_started;
            }
            if (!copy_ok) {
                if (from_nested) g_nested_residual.gpu_cache_failures++;
                failure_reason = "transient-copy";
                ok = 0;
                break;
            }
            if (!demand_pipeline_active &&
                !cuda_q1_0_ssd_wrap_record_h2d(
                    ssd_wrap_h2d_ring, cache->route_upload_stream)) {
                failure_reason = "ssd-wrap-h2d-event";
                ok = 0;
                break;
            }
            if (from_nested && cuda_nested_residual_gpu_join_requested()) {
                g_nested_residual.route_h2d_bytes +=
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
            }
            int publish_ok = 0;
            if (demand_pipeline_active) {
                publish_ok = cuda_moe_route_publish_batch_append(
                    &demand_batch.publish, -1, 0u, 0u, route,
                    demand_batch_slot, 0u);
            } else if (cache->batched_publish_requested) {
                publish_ok = cuda_moe_route_publish_batch_append(
                    &publish_batch, -1, 0u, 0u, route, route, 0u);
            } else {
                moe_publish_transient_route_kernel<<<
                        1, 1, 0, cache->route_upload_stream>>>(
                    cache->device_route_ptrs,
                    request.route_count,
                    route,
                    route,
                    cache->route_transient_gate,
                    cache->route_transient_up,
                    cache->route_transient_down,
                    cache->gate_expert_bytes,
                    cache->down_expert_bytes);
                publish_ok = cudaGetLastError() == cudaSuccess;
                if (publish_ok) {
                    cache->legacy_publish_kernels++;
                    cuda_decode_trace_note_publish(
                        request, 1u, 1u);
                }
            }
            if (!publish_ok) {
                (void)cudaGetLastError();
                failure_reason = "transient-publish";
                ok = 0;
                break;
            }
            g_moe_tiering.transient++;
            g_moe_tiering.ram_h2d_bytes +=
                cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
            if constexpr (G73) {
                if (g73_out_of_mask[route]) g73_outcomes.served_transient++;
                cuda_g73_open_maybe_schedule_rotation(
                    request, route, expert, tier);
            }
        }
        if (from_nested && !cuda_nested_residual_gpu_join_requested()) {
            const uint64_t native_bytes =
                cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
            g_nested_residual.h2d_bytes += native_bytes;
            g_nested_residual.route_h2d_bytes += native_bytes;
        }
    }
    const double h2d_sync_started =
        g_nested_residual.profile_enabled &&
        cuda_nested_residual_gpu_cache_requested() &&
        cuda_nested_residual_layer_required(request.layer_index) ?
         cuda_wall_sec() : 0.0;
    /* P4a replaces the serial per-miss H2D/publish loop above with one
     * layer accumulation point: exactly one gate+up H2D, one down H2D, then
     * one ordered demand materialize/publish kernel. */
    const double flush_started = cuda_moe_zerocopy_now_ms();
    if (ok && demand_pipeline_active) {
        ds4_transport_h2d_batch_begin(&transport_batch);
    }
    if (ok && demand_pipeline_active &&
        !cuda_moe_demand_pipeline_flush(
            cache, request, &demand_batch,
            G132 ? cache->route_cpu_plan.cpu_count : 0u)) {
        ds4_transport_h2d_batch_invalidate(&transport_batch);
        failure_reason = "demand-pipeline-batch";
        ok = 0;
    } else if (ok && cache->batched_publish_requested &&
        !cuda_moe_route_publish_batch_flush(cache, request, &publish_batch)) {
        failure_reason = "publish-batch";
        ok = 0;
    }
    /* P.5a: the zero-copy pointers must reach route_ptrs before the upload
     * stream is drained below, which is what makes them visible to the
     * consumer kernels. Ordering therefore matches the copy path exactly. */
    if (ok && zerocopy_batch.count != 0u &&
        !cuda_moe_route_publish_batch_flush(cache, request, &zerocopy_batch)) {
        failure_reason = "zerocopy-publish-batch";
        ok = 0;
    }
    {
        const double flush_ms = cuda_moe_zerocopy_now_ms() - flush_started;
        g_moe_zerocopy.t_orchestration_ms += flush_ms;
        ds4_workerprof_add_ms(wprof, WP_PUBLISH_NS, flush_ms);
    }
    const double drain_started = cuda_moe_zerocopy_now_ms();
    int transfers_ok;
    if constexpr (DOV) {
        /* DRAIN4 §3.1: al posto della coppia [drain bloccante -> VALID ->
         * ready], record dell'evento dopo l'ultimo publish (i flush qui
         * sopra) e commit ottimistico.  Su qualunque fallimento dell'arm il
         * ramo else e' il percorso bloccante attuale, riga per riga.  Il
         * drain anticipato pre-SSD piu' in alto resta bloccante (I2: e' un
         * rollback, mai ottimistico).  drain_ms misura ora il costo
         * dell'arm (~us): la quota spostata sotto il compute e' visibile in
         * drain_overlap_ms. */
        if (ok && cuda_moe_drain_overlap4_arm(
                cache, request, admitted, promotion_reservations,
                admitted_count, &request.g133_epoch)) {
            transfers_ok = 1;
            ds4_transport_h2d_batch_invalidate(&transport_batch);
            ds4_transport_h2d_batch_finish(&transport_batch, 1);
        } else {
            transfers_ok = cuda_moe_tiering_finish_vram_reservations<SCOPED>(
                cache, &request, admitted, promotion_reservations,
                admitted_count, request.g133_epoch, ok,
                request.absolute_deadline);
            ds4_transport_h2d_batch_finish(&transport_batch, transfers_ok);
        }
    } else {
        transfers_ok = cuda_moe_tiering_finish_vram_reservations<SCOPED>(
            cache, &request, admitted, promotion_reservations, admitted_count,
            request.g133_epoch, ok, request.absolute_deadline);
        ds4_transport_h2d_batch_finish(&transport_batch, transfers_ok);
    }
    {
        const double drain_ms = cuda_moe_zerocopy_now_ms() - drain_started;
        g_moe_zerocopy.t_drain_ms += drain_ms;
        g_moe_zerocopy.t_orchestration_ms += drain_ms;
        /* WORKER-PROF: qui il worker aspetta davvero il completamento degli
         * H2D accodati sopra (sync dello stream di upload). */
        ds4_workerprof_add_ms(wprof, WP_DRAIN_NS, drain_ms);
    }
    if (h2d_sync_started != 0.0) {
        g_nested_residual.profile_h2d_sync_calls++;
        g_nested_residual.profile_h2d_sync_seconds +=
            cuda_wall_sec() - h2d_sync_started;
    }
    if (!transfers_ok) {
        failure_reason = "upload-sync";
        ok = 0;
    }
    if constexpr (G73) {
        if (ok) cuda_g73_publish_pending_outcomes(
            cache, request.sequence, g73_outcomes);
    }
    if (!ok) {
        fprintf(stderr,
                "ds4: [tiering-enforce] result=failed layer=%u sequence=%u "
                "routes=%u misses=%u reason=%s admitted=%u\n",
                request.layer_index, request.sequence, request.route_count,
                request.miss_count, failure_reason, admitted_count);
    }
    /* FIX-B: la serie di ripieghi e' CONSECUTIVA. Una richiesta di rotta che
     * chiude bene senza ripieghi la riazzera, cosi' il tetto
     * DS4_CUDA_TRANSIENT_TIMEOUT_RECOVERABLE_MAX_FALLBACKS colpisce solo una
     * raffica reale e non la somma di episodi isolati e distanti. */
    if (ok && transient_fallbacks_used == 0u &&
        g_transient_timeout_fallback_streak.load(
            std::memory_order_relaxed) != 0u) {
        g_transient_timeout_fallback_streak.store(
            0u, std::memory_order_relaxed);
    }
    if constexpr (G132) {
        if (!ok) {
            cuda_g132_general_plan_release(
                cache, &cache->route_cpu_plan);
        }
    }
    return ok;
}

template <bool G73, bool G132, bool SCOPED, bool DOV>
static void *cuda_moe_route_worker(void *arg) {
    cuda_moe_expert_cache *cache = (cuda_moe_expert_cache *)arg;
    if (!cache || cudaSetDevice(cache->route_device) != cudaSuccess) {
        if (cache) {
            cache->route_worker_errors++;
            cache->route_worker_failed.store(
                1, std::memory_order_release);
        }
        (void)cudaGetLastError();
        return NULL;
    }
    cache->route_worker_ready.store(1, std::memory_order_release);
    uint32_t consumed_sequence = 0u;
    uint64_t consumed_generation = 0u;
    std::vector<uint8_t> claimed(cache->capacity, 0u);
    /* WORKER-PROF: issato una volta per vita del thread; nel ciclo di spin
     * resta un ramo prevedibile. */
    const int wprof = cuda_worker_profile_enabled();
    const uint32_t pickup_spin_us = cuda_worker_pickup_spin_us();
    using pickup_clock = std::chrono::steady_clock;
    pickup_clock::time_point pickup_spin_deadline;
    /* 0 = disarmato, 1 = spin in corso, 2 = budget esaurito. */
    uint32_t pickup_spin_state = 0u;
    /* Istante in cui il worker e' entrato nello spin senza lavoro, e stato
     * "token in corso" campionato in quell'istante. */
    uint64_t wprof_idle_started = wprof ? ds4_workerprof_now_ns() : 0u;
    int wprof_idle_token = wprof
        ? g_workerprof_token_active.load(std::memory_order_acquire) : 0;
    /* Istante del pickup della richiesta corrente, cioe' la PRIMA volta che
     * il worker ha visto questa sequence.  Va preso prima del claim e della
     * validazione: un pickup datato dopo il claim nasconderebbe proprio il
     * ritardo che si vuole misurare. */
    uint64_t wprof_pickup_ns = 0u;
    uint64_t wprof_pickup_faults = 0u;
    uint32_t wprof_seen_sequence = 0u;

    while (!cache->route_stop.load(std::memory_order_acquire)) {
        const uint32_t sequence = cache->route_request_host->sequence;
        if (sequence == 0u || sequence == consumed_sequence) {
            if constexpr (DOV) {
                /* DRAIN4: con un overlap outstanding, una cudaStreamQuery
                 * per iterazione idle chiude la finestra e alimenta
                 * drain_overlap_ms.  Senza overlap: un load relaxed. */
                cuda_moe_drain_overlap4_poll(cache, wprof);
            }
            if (pickup_spin_us != 0u) {
                const int token_active = g_workerprof_token_active.load(
                    std::memory_order_acquire);
                if (!token_active) {
                    pickup_spin_state = 0u;
                } else if (pickup_spin_state != 2u) {
                    const pickup_clock::time_point now = pickup_clock::now();
                    if (pickup_spin_state == 0u) {
                        pickup_spin_deadline =
                            now + std::chrono::microseconds(pickup_spin_us);
                        pickup_spin_state = 1u;
                    }
                    if (now < pickup_spin_deadline) {
                        ds4_worker_pickup_pause();
                        continue;
                    }
                    pickup_spin_state = 2u;
                }
            }
#ifdef _WIN32
            (void)SwitchToThread();
#else
            usleep(0);
#endif
            continue;
        }
        /* La prossima fase idle dopo questo job riceve un budget nuovo. */
        pickup_spin_state = 0u;
        if (wprof && wprof_seen_sequence != sequence) {
            wprof_seen_sequence = sequence;
            wprof_pickup_ns = ds4_workerprof_now_ns();
            wprof_pickup_faults = ds4_workerprof_faults_now(wprof);
            ds4_workerprof_note_idle(
                wprof, wprof_idle_started, wprof_pickup_ns, wprof_idle_token);
            wprof_idle_started = 0u;
            ds4_workerprof_publish_pickup(wprof, sequence, wprof_pickup_ns);
        }
#ifdef _WIN32
        MemoryBarrier();
#else
        __sync_synchronize();
#endif
        cuda_moe_route_request request;
        memcpy(&request, cache->route_request_host, sizeof(request));
        if (request.sequence != sequence ||
            request.host_generation == 0u ||
            request.host_generation == consumed_generation) {
            continue;
        }
        if (!cuda_moe_route_mailbox_worker_claim(
                cache, sequence, request.host_generation)) {
            break;
        }
        if constexpr (DOV) {
            /* DRAIN4: il claim appena riuscito prova (done-event eseguito su
             * stream 0, dietro il waitEvent del consumer) che l'upload della
             * generazione precedente e' fisicamente completo: ritira un
             * eventuale overlap che il loop idle non ha visto chiudersi. */
            cuda_moe_drain_overlap4_retire_at_claim(wprof);
        }
        /* sequence is the GPU->host publication word: the resolver writes it
         * only after __threadfence_system().  host_generation is ordinary
         * request payload and may become visible while sequence still names
         * the preceding request.  Never accept a new generation behind an
         * unchanged sequence or the worker can consume a torn snapshot and
         * publish readiness for the wrong sequence. */
        consumed_sequence = sequence;
        consumed_generation = request.host_generation;
        if (sequence <= 2u) {
            fprintf(stderr,
                    "ds4: [gpu-route-debug] request seq=%u generation=%llu "
                    "layer=%u misses=%u\n",
                    sequence,
                    (unsigned long long)request.host_generation,
                    request.layer_index, request.miss_count);
        }
        cuda_decode_trace_worker_begin(request);
        cuda_decode_trace_upload_begin(cache, request);
        int request_valid =
            request.route_count > 0u &&
            request.route_count <= CUDA_MOE_ROUTE_COUNT &&
            request.miss_count <= request.route_count &&
            request.layer_index < CUDA_MOE_LAYER_COUNT &&
            request.gate_expert_bytes == cache->gate_expert_bytes &&
            request.down_expert_bytes == cache->down_expert_bytes &&
            (!g_moe_tiering.g133_enabled ||
             cuda_g133_epoch_valid(request.g133_epoch));
        if (request_valid &&
            !cuda_sparse_bake_validate_selected(
                request.layer_index, request.selected,
                request.route_count, "gpu resident route",
                sequence)) {
            request_valid = 0;
        }
        if (!request_valid) {
            fprintf(stderr,
                    "ds4: [gpu-route-request] result=invalid sequence=%u "
                    "layer=%u routes=%u misses=%u gate_bytes=%llu/%llu "
                    "down_bytes=%llu/%llu\n",
                    request.sequence, request.layer_index,
                    request.route_count, request.miss_count,
                    (unsigned long long)request.gate_expert_bytes,
                    (unsigned long long)cache->gate_expert_bytes,
                    (unsigned long long)request.down_expert_bytes,
                    (unsigned long long)cache->down_expert_bytes);
        }
        if (request_valid &&
            g_moe_tiering.compose_prefill_mass_tiering &&
            g_dynamic_arena.snapshot_generation !=
                g_moe_tiering.snapshot_generation) {
            g_moe_tiering.failures++;
            request_valid = 0;
        }
        if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF && request_valid) {
            if (!cuda_moe_tiering_advance_call_tick("gpu-route-request")) {
                request_valid = 0;
            }
        }
        if constexpr (G73) {
            /* Background rotation is fail-open: publication failures disable
             * future rotation, while the transient exact serving path stays live. */
            /* WORKER-PROF: sta FRA il pickup e il servizio, quindi e' tempo che
             * il chiamante aspetta.  Prende il mutex della rotazione e puo'
             * bloccarsi dietro al thread di wrap: senza questa voce finirebbe
             * indistinguibile dal residuo del job. */
            const uint64_t wprof_wrap = ds4_workerprof_start(wprof);
            (void)cuda_q1_0_ssd_wrap_poll();
            ds4_workerprof_stop(wprof, WP_WRAP_POLL_NS, wprof_wrap);
        }
        if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF && request_valid) {
            g_moe_tiering.calls++;
            g_moe_tiering.selected += request.route_count;
            for (uint32_t route = 0;
                 route < request.route_count; route++) {
                const int32_t expert_i = request.selected[route];
                if (expert_i < 0 || expert_i >= 256) {
                    request_valid = 0;
                    break;
                }
                (void)cuda_moe_tiering_observe_route(
                    request.layer_index, (uint32_t)expert_i,
                    request.weights[route], request.g133_epoch);
            }
            if (!request_valid) {
                fprintf(stderr,
                        "ds4: [gpu-route-request] result=invalid-selected "
                        "sequence=%u layer=%u routes=%u selected="
                        "%d,%d,%d,%d,%d,%d\n",
                        request.sequence, request.layer_index,
                        request.route_count,
                        request.selected[0], request.selected[1],
                        request.selected[2], request.selected[3],
                        request.selected[4], request.selected[5]);
            }
        }
        /* P.5a instrumentation: one call per route request the worker sees,
         * before it is served, so the token/window cursor advances ahead of
         * the enforce pass and the hit/miss split is recorded for both the
         * all-hit fast path and the miss path. Layers that the resolver
         * completes on the GPU without waking the worker are not visible
         * here; routes/hit_rate are therefore worker-scoped, and that is
         * stated rather than papered over. */
        if (request_valid) {
            cuda_moe_zerocopy_note_request(
                request.layer_index, request.route_count,
                request.miss_count <= request.route_count
                    ? request.route_count - request.miss_count
                    : 0u,
                request.miss_count);
        }
        const char *precheck_failure_reason = "request-invalid";
        if (request_valid && request.miss_count == 0u) {
            if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
                for (uint32_t route = 0;
                     route < request.route_count; route++) {
                    const uint32_t expert =
                        (uint32_t)request.selected[route];
                    cuda_moe_tier_entry &tier = g_moe_tiering.entries[
                        cuda_moe_tiering_entry_index(
                            request.layer_index, expert)];
                    if (g_moe_tiering.mode == CUDA_MOE_TIER_ENFORCE &&
                        tier.state != CUDA_MOE_TIER_VRAM_PROTECTED) {
                        if (tier.state == CUDA_MOE_TIER_SSD_COLD) {
                            g_moe_tiering.forbidden_cold_ssd_to_vram++;
                            g_iq1_promotion.direct_ssd_to_vram_rejected++;
                        }
                        fprintf(stderr,
                                "ds4: [tiering-enforce] result=all-hit-state-mismatch "
                                "layer=%u sequence=%u expert=%u state=%u\n",
                                request.layer_index, request.sequence, expert,
                                (unsigned)tier.state);
                        g_moe_tiering.failures++;
                        if (g_iq1_promotion.requested_slots != 0u) {
                            g_iq1_promotion.failures++;
                        }
                        precheck_failure_reason =
                            "all-hit-tier-state-mismatch";
                        request_valid = 0;
                        break;
                    }
                    if (tier.state != CUDA_MOE_TIER_VRAM_PROTECTED) {
                        if (tier.state == CUDA_MOE_TIER_SSD_COLD) {
                            g_moe_tiering.cold_to_vram++;
                            if (g_moe_tiering.compose_prefill_mass_tiering) {
                                g_moe_tiering.forbidden_cold_ssd_to_vram++;
                            }
                        } else {
                            g_moe_tiering.vram_promotions++;
                        }
                        tier.state = CUDA_MOE_TIER_VRAM_PROTECTED;
                        cuda_g133_mark_promotion(tier, request.g133_epoch);
                    }
                }
            }
            if (request_valid) {
                if constexpr (G73) {
                    cuda_g73_route_outcomes g73_outcomes = {};
                    uint8_t g73_out_of_mask[CUDA_MOE_ROUTE_COUNT] = {0};
                    cuda_g73_classify_request(
                        request, &g73_outcomes, g73_out_of_mask);
                    cuda_g73_publish_pending_outcomes(
                        cache, sequence, g73_outcomes);
                }
                cache->route_all_hit_observed++;
                cache->hits += request.route_count;
                cache->calls++;
                const uint64_t wprof_signal = ds4_workerprof_start(wprof);
                cuda_decode_trace_worker_end(request);
                cuda_decode_trace_upload_end(cache, request);
                if (!cuda_moe_route_mailbox_publish_upload(
                        cache, sequence, request.host_generation)) {
                    break;
                }
                {
                    const uint64_t wprof_ready =
                        ds4_workerprof_note_job_end(
                    wprof, wprof_pickup_ns, wprof_pickup_faults);
                    ds4_workerprof_stop(wprof, WP_SIGNAL_NS, wprof_signal);
                    (void)wprof_ready;
                    if constexpr (G73) {
                        cuda_moe_route_memory_barrier();
                        *cache->route_ready_host = sequence;
                        cuda_moe_route_memory_barrier();
                        /* Con G73 spento questo ramo non esiste: e' la GPU a
                         * rilasciare il chiamante e qui non si pubblica nulla,
                         * cosi' notice_ms non misura un rendezvous mai
                         * avvenuto. */
                        ds4_workerprof_publish_ready(
                            wprof, sequence, wprof_ready);
                    }
                }
                cuda_moe_route_worker_publish_completed(
                    cache, sequence, request.host_generation);
                if (wprof) {
                    wprof_idle_started = ds4_workerprof_now_ns();
                    wprof_idle_token = g_workerprof_token_active.load(
                        std::memory_order_acquire);
                }
                continue;
            }
        }
        const double started = cuda_wall_sec();
        const int nested_profile_request =
            g_nested_residual.profile_enabled &&
            cuda_nested_residual_gpu_cache_requested() &&
            cuda_nested_residual_layer_required(request.layer_index);
        int ok = request_valid &&
                 request.miss_count > 0u &&
                 request.miss_count <= request.route_count;
        const char *failure_reason = ok ? "none" : precheck_failure_reason;
        cudaError_t failure_cuda_error = cudaSuccess;
        std::fill(claimed.begin(), claimed.end(), 0u);
        for (uint32_t route = 0; ok && route < request.route_count; route++) {
            const int32_t slot = request.hit_slots[route];
            if (slot >= 0) {
                if ((uint32_t)slot >= cache->capacity) {
                    fprintf(stderr,
                            "ds4: [gpu-route-request] result=invalid-hit-slot "
                            "sequence=%u layer=%u route=%u slot=%d capacity=%u\n",
                            request.sequence, request.layer_index, route, slot,
                            cache->capacity);
                    ok = 0;
                    failure_reason = "hit-slot-oob";
                    break;
                }
                claimed[(uint32_t)slot] = 1u;
                cache->slots[(uint32_t)slot].age = ++cache->tick;
            }
        }

        uint32_t admitted[CUDA_MOE_ROUTE_COUNT] = {0};
        uint32_t admitted_count = 0;
        cuda_moe_route_publish_batch publish_batch = {};
        ds4_transport_h2d_batch transport_batch = {};
        if (ok && g_moe_tiering.mode == CUDA_MOE_TIER_ENFORCE) {
            ok = cuda_moe_tiering_enforce_request<G73, G132, SCOPED, DOV>(
                cache, request, claimed.data());
            if (cache->route_worker_safe_leaked.load(
                    std::memory_order_acquire)) return NULL;
        }
        for (uint32_t miss = 0;
             ok && g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE &&
             miss < request.miss_count; miss++) {
            const uint32_t route = request.miss_routes[miss];
            if (route >= request.route_count) {
                ok = 0;
                failure_reason = "miss-route-oob";
                break;
            }
            const int32_t expert_i = request.selected[route];
            if (expert_i < 0 || expert_i >= 256) {
                ok = 0;
                failure_reason = "expert-oob";
                break;
            }
            const uint32_t expert = (uint32_t)expert_i;
            if (g_sparse_bake_active &&
                !cuda_sparse_bake_expert_retained(request.layer_index, expert)) {
                g_sparse_bake_route_rejections++;
                fprintf(stderr,
                        "ds4: sparse bake rejected route worker miss "
                        "layer=%u seq=%u route=%u expert=%u\n",
                        request.layer_index, sequence, route, expert);
                ok = 0;
                failure_reason = "sparse-rejected";
                break;
            }
            const int cache_slot_i = cuda_moe_route_worker_pick_slot(cache, claimed.data());
            if (cache_slot_i < 0) {
                ok = 0;
                failure_reason = "no-cache-slot";
                break;
            }
            const uint32_t cache_slot = (uint32_t)cache_slot_i;
            claimed[cache_slot] = 1u;
            cuda_moe_cache_slot &entry = cache->slots[cache_slot];
            admitted[admitted_count++] = cache_slot;
            int32_t old_map_index = -1;
            const int was_valid = entry.state == CUDA_MOE_CACHE_VALID;
            if (was_valid && entry.layer_index < CUDA_MOE_LAYER_COUNT &&
                entry.expert_id < 256u) {
                cuda_moe_tiering_demote_cache_entry(
                    entry.layer_index, entry.expert_id);
                old_map_index = (int32_t)(entry.layer_index * 256u + entry.expert_id);
                if ((size_t)old_map_index < cache->host_slot_by_layer_expert.size() &&
                    cache->host_slot_by_layer_expert[(size_t)old_map_index] ==
                        (int32_t)cache_slot) {
                    cache->host_slot_by_layer_expert[(size_t)old_map_index] = -1;
                }
            }
            entry.state = CUDA_MOE_CACHE_LOADING;

            char *host_gate = cache->route_host_gate +
                (uint64_t)miss * cache->gate_expert_bytes;
            char *host_up = cache->route_host_up +
                (uint64_t)miss * cache->gate_expert_bytes;
            char *host_down = cache->route_host_down +
                (uint64_t)miss * cache->down_expert_bytes;
            const uint64_t gate_src = request.gate_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t up_src = request.up_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t down_src = request.down_offset +
                (uint64_t)expert * cache->down_expert_bytes;
            int from_nested = 0;
            if (cuda_nested_residual_gpu_cache_requested() &&
                cuda_nested_residual_layer_required(request.layer_index)) {
                if (cuda_nested_residual_gpu_join_requested()) {
                    from_nested = 1;
                } else {
                    const uint64_t wprof_nested = ds4_workerprof_start(wprof);
                    from_nested = cuda_nested_residual_fill_route_host_exact(
                        request.layer_index, expert,
                        request.gate_offset, request.up_offset,
                        request.down_offset,
                        cache->gate_expert_bytes, cache->down_expert_bytes,
                        host_gate, host_up, host_down);
                    ds4_workerprof_stop(wprof, WP_NESTED_FILL_NS, wprof_nested);
                    if (from_nested != 1) {
                        ok = 0;
                        failure_reason = "nested-exact";
                        break;
                    }
                }
            } else if (!g_model_file_valid) {
                    ok = 0;
                    failure_reason = "pread";
                    break;
            } else {
                const uint64_t trace_pread_started =
                    cuda_decode_trace_request_qpc(request);
                uint64_t trace_pread_count = 0u;
                uint64_t trace_pread_bytes = 0u;
                int read_ok = 1;
                const int transport_repeat =
                    ds4_transport_file_load_begin(
                        request.layer_index, expert);
                trace_pread_count++;
                /* WORKER-PROF: percorso NON-enforce.  cuda_pread_full e' usata
                 * anche dal caricamento del modello e dai sidecar, quindi la
                 * strumentazione sta al sito di chiamata del worker e non
                 * dentro la funzione: cosi' read_calls/read_bytes restano
                 * letture del route worker e non un totale di processo. */
                uint64_t wprof_rd = ds4_workerprof_read_begin(wprof);
                uint64_t wprof_t = ds4_workerprof_start(wprof);
                if (cuda_pread_full(
                        &g_model_file, host_gate,
                        cache->gate_expert_bytes, gate_src)) {
                    trace_pread_bytes += cache->gate_expert_bytes;
                    ds4_transport_record_file_bytes(
                        transport_repeat, cache->gate_expert_bytes);
                } else {
                    ds4_transport_mark_incomplete();
                    read_ok = 0;
                }
                ds4_workerprof_stop(wprof, WP_READ_GATE_NS, wprof_t);
                ds4_workerprof_read_end(
                    wprof, read_ok ? (int64_t)cache->gate_expert_bytes : 0);
                (void)wprof_rd;
                if (read_ok) {
                    trace_pread_count++;
                    wprof_rd = ds4_workerprof_read_begin(wprof);
                    wprof_t = ds4_workerprof_start(wprof);
                    if (cuda_pread_full(
                            &g_model_file, host_up,
                            cache->gate_expert_bytes, up_src)) {
                        trace_pread_bytes += cache->gate_expert_bytes;
                        ds4_transport_record_file_bytes(
                            transport_repeat, cache->gate_expert_bytes);
                    } else {
                        ds4_transport_mark_incomplete();
                        read_ok = 0;
                    }
                    ds4_workerprof_stop(wprof, WP_READ_UP_NS, wprof_t);
                    ds4_workerprof_read_end(
                        wprof, read_ok ? (int64_t)cache->gate_expert_bytes : 0);
                }
                if (read_ok) {
                    trace_pread_count++;
                    wprof_rd = ds4_workerprof_read_begin(wprof);
                    wprof_t = ds4_workerprof_start(wprof);
                    if (cuda_pread_full(
                            &g_model_file, host_down,
                            cache->down_expert_bytes, down_src)) {
                        trace_pread_bytes += cache->down_expert_bytes;
                        ds4_transport_record_file_bytes(
                            transport_repeat, cache->down_expert_bytes);
                    } else {
                        ds4_transport_mark_incomplete();
                        read_ok = 0;
                    }
                    ds4_workerprof_stop(wprof, WP_READ_DOWN_NS, wprof_t);
                    ds4_workerprof_read_end(
                        wprof, read_ok ? (int64_t)cache->down_expert_bytes : 0);
                }
                cuda_decode_trace_note_pread(
                    request.trace_sample_id, request.layer_index,
                    trace_pread_started, trace_pread_count,
                    trace_pread_bytes);
                if (!read_ok) {
                    ok = 0;
                    failure_reason = "pread";
                    break;
                }
            }
            const uint64_t gate_dst = (uint64_t)cache_slot * cache->gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)cache_slot * cache->down_expert_bytes;
            const uint64_t resident_pitch =
                (uint64_t)cache->capacity * cache->gate_expert_bytes;
            const uint64_t source_pitch =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * cache->gate_expert_bytes;
            const double h2d_enqueue_started =
                from_nested && g_nested_residual.profile_enabled ?
                cuda_wall_sec() : 0.0;
            const uint64_t wprof_deliver = ds4_workerprof_start(wprof);
            ds4_transport_h2d_batch_begin(&transport_batch);
            const int copy_ok =
                from_nested && cuda_nested_residual_gpu_join_requested() ?
                cuda_nested_residual_join_to_device_exact(
                    request.layer_index, expert,
                    request.gate_offset, request.up_offset,
                    request.down_offset,
                    cache->gate_expert_bytes, cache->down_expert_bytes,
                    cache->gate + gate_dst,
                    cache->up + gate_dst,
                    cache->down + down_dst,
                    cache->route_upload_stream) == 1 :
                (cache->packed_copy_requested ?
                    cuda_moe_route_copy_expert_h2d_async(
                        cache,
                        &request,
                        cache->gate + gate_dst,
                        cache->up + gate_dst,
                        cache->down + down_dst,
                        resident_pitch,
                        host_gate, host_up, host_down,
                        source_pitch) :
                    cuda_moe_route_legacy_copy_expert_h2d_async(
                        cache,
                        &request,
                        cache->gate + gate_dst,
                        cache->up + gate_dst,
                        cache->down + down_dst,
                        host_gate, host_up, host_down));
            ds4_workerprof_stop(wprof, WP_DELIVER_NS, wprof_deliver);
            if (from_nested && g_nested_residual.profile_enabled) {
                g_nested_residual.profile_h2d_enqueue_calls++;
                g_nested_residual.profile_h2d_enqueue_seconds +=
                    cuda_wall_sec() - h2d_enqueue_started;
            }
            if (!copy_ok) {
                ds4_transport_h2d_batch_invalidate(&transport_batch);
                if (from_nested) g_nested_residual.gpu_cache_failures++;
                ok = 0;
                failure_reason = "h2d-copy";
                failure_cuda_error = cudaPeekAtLastError();
                break;
            }
            ds4_transport_h2d_batch_append(
                &transport_batch, request.layer_index, expert,
                cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes);
            if (from_nested && cuda_nested_residual_gpu_join_requested()) {
                g_nested_residual.route_h2d_bytes +=
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
            }
            if (from_nested && !cuda_nested_residual_gpu_join_requested()) {
                const uint64_t native_bytes =
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
                g_nested_residual.h2d_bytes += native_bytes;
                g_nested_residual.route_h2d_bytes += native_bytes;
            }
            const uint32_t new_map_index = request.layer_index * 256u + expert;
            int publish_ok = 0;
            if (cache->batched_publish_requested) {
                publish_ok = cuda_moe_route_publish_batch_append(
                    &publish_batch, old_map_index, new_map_index,
                    cache_slot, route, 0u, 1u);
            } else {
                moe_publish_resident_route_kernel<<<
                        1, 1, 0, cache->route_upload_stream>>>(
                    cache->device_slot_by_layer_expert,
                    cache->device_route_ptrs,
                    old_map_index,
                    new_map_index,
                    cache_slot,
                    request.route_count,
                    route,
                    cache->gate,
                    cache->up,
                    cache->down,
                    cache->gate_expert_bytes,
                    cache->down_expert_bytes);
                const cudaError_t publish_error = cudaGetLastError();
                publish_ok = publish_error == cudaSuccess;
                if (publish_ok) {
                    cache->legacy_publish_kernels++;
                    cuda_decode_trace_note_publish(
                        request, 1u, 1u);
                } else {
                    failure_cuda_error = publish_error;
                }
            }
            if (!publish_ok) {
                ok = 0;
                failure_reason = "publish-launch";
                break;
            }
            entry.key = {gate_src, up_src, down_src};
            entry.layer_index = request.layer_index;
            entry.expert_id = expert;
            entry.age = ++cache->tick;
            entry.layer_owned = 0;
            entry.layer_key = request.gate_offset;
            cache->host_slot_by_layer_expert[new_map_index] = (int32_t)cache_slot;
            if (!was_valid && cache->count < cache->capacity) cache->count++;
            else if (was_valid) cache->evictions++;
            cache->admissions++;
            if (g_moe_tiering.mode == CUDA_MOE_TIER_OBSERVE) {
                cuda_moe_tier_entry &tier = g_moe_tiering.entries[
                    cuda_moe_tiering_entry_index(
                        request.layer_index, expert)];
                if (tier.state == CUDA_MOE_TIER_SSD_COLD) {
                    g_moe_tiering.cold_to_vram++;
                } else if (tier.state != CUDA_MOE_TIER_VRAM_PROTECTED) {
                    g_moe_tiering.vram_promotions++;
                }
                tier.state = CUDA_MOE_TIER_VRAM_PROTECTED;
                cuda_g133_mark_promotion(tier, request.g133_epoch);
            }
        }

        if (g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE) {
            const uint64_t wprof_flush = ds4_workerprof_start(wprof);
            if (ok && cache->batched_publish_requested &&
                !cuda_moe_route_publish_batch_flush(
                    cache, request, &publish_batch)) {
                failure_reason = "publish-batch";
                failure_cuda_error = cudaPeekAtLastError();
                ok = 0;
            }
            ds4_workerprof_stop(wprof, WP_PUBLISH_NS, wprof_flush);
            if constexpr (DOV) {
                /* DRAIN4 §3.1, gemello non-ENFORCE: arm dopo l'ultimo
                 * publish (il flush qui sopra).  Se l'arm riesce: VALID
                 * ottimistico fatto dall'arm, batch del registro invalidato
                 * (I4), niente sync.  Altrimenti il ramo else e' il blocco
                 * bloccante attuale, copiato riga per riga (il ramo
                 * else esterno dell'istanza DOV=false resta il testo
                 * originale, token-identico). */
                if (ok && cuda_moe_drain_overlap4_arm(
                        cache, request, admitted, NULL,
                        admitted_count, NULL)) {
                    ds4_transport_h2d_batch_invalidate(&transport_batch);
                    ds4_transport_h2d_batch_finish(&transport_batch, 1);
                } else {
                    const double h2d_sync_started =
                        nested_profile_request ? cuda_wall_sec() : 0.0;
                    const uint64_t trace_upload_drain_started =
                        cuda_decode_trace_request_qpc(request);
                    const uint64_t wprof_drain = ds4_workerprof_start(wprof);
                    const cudaError_t pending_error = cudaGetLastError();
                    const cudaError_t sync_error =
                        cudaStreamSynchronize(cache->route_upload_stream);
                    ds4_workerprof_stop(wprof, WP_DRAIN_NS, wprof_drain);
                    cuda_decode_trace_note_upload_drain(
                        &request, trace_upload_drain_started);
                    if (nested_profile_request) {
                        g_nested_residual.profile_h2d_sync_calls++;
                        g_nested_residual.profile_h2d_sync_seconds +=
                            cuda_wall_sec() - h2d_sync_started;
                    }
                    ds4_transport_h2d_batch_finish(
                        &transport_batch,
                        pending_error == cudaSuccess &&
                            sync_error == cudaSuccess);
                    if (pending_error != cudaSuccess ||
                        sync_error != cudaSuccess) {
                        failure_cuda_error = pending_error != cudaSuccess ?
                            pending_error : sync_error;
                        failure_reason = pending_error != cudaSuccess ?
                            "pending-cuda-error" : "upload-sync";
                        ok = 0;
                    }
                    if (ok) {
                        for (uint32_t i = 0; i < admitted_count; i++) {
                            cache->slots[admitted[i]].state =
                                CUDA_MOE_CACHE_VALID;
                        }
                    } else if (admitted_count > 0u) {
                        for (uint32_t i = 0; i < admitted_count; i++) {
                            const cuda_moe_cache_slot &entry =
                                cache->slots[admitted[i]];
                            if (entry.layer_index < CUDA_MOE_LAYER_COUNT &&
                                entry.expert_id < 256u) {
                                cuda_moe_tiering_demote_cache_entry(
                                    entry.layer_index, entry.expert_id);
                            }
                        }
                        cuda_moe_expert_cache_invalidate(
                            "worker-legacy-failure");
                    }
                }
            } else {
            const double h2d_sync_started =
                nested_profile_request ? cuda_wall_sec() : 0.0;
            const uint64_t trace_upload_drain_started =
                cuda_decode_trace_request_qpc(request);
            const uint64_t wprof_drain = ds4_workerprof_start(wprof);
            const cudaError_t pending_error = cudaGetLastError();
            const cudaError_t sync_error =
                cudaStreamSynchronize(cache->route_upload_stream);
            ds4_workerprof_stop(wprof, WP_DRAIN_NS, wprof_drain);
            cuda_decode_trace_note_upload_drain(
                &request, trace_upload_drain_started);
            if (nested_profile_request) {
                g_nested_residual.profile_h2d_sync_calls++;
                g_nested_residual.profile_h2d_sync_seconds +=
                    cuda_wall_sec() - h2d_sync_started;
            }
            ds4_transport_h2d_batch_finish(
                &transport_batch,
                pending_error == cudaSuccess && sync_error == cudaSuccess);
            if (pending_error != cudaSuccess || sync_error != cudaSuccess) {
                failure_cuda_error = pending_error != cudaSuccess ?
                    pending_error : sync_error;
                failure_reason = pending_error != cudaSuccess ?
                    "pending-cuda-error" : "upload-sync";
                ok = 0;
            }
            if (ok) {
                for (uint32_t i = 0; i < admitted_count; i++) {
                    cache->slots[admitted[i]].state = CUDA_MOE_CACHE_VALID;
                }
            } else if (admitted_count > 0u) {
                for (uint32_t i = 0; i < admitted_count; i++) {
                    const cuda_moe_cache_slot &entry =
                        cache->slots[admitted[i]];
                    if (entry.layer_index < CUDA_MOE_LAYER_COUNT &&
                        entry.expert_id < 256u) {
                        cuda_moe_tiering_demote_cache_entry(
                            entry.layer_index, entry.expert_id);
                    }
                }
                cuda_moe_expert_cache_invalidate("worker-legacy-failure");
            }
            }
        }
        cache->route_worker_jobs++;
        if (g_moe_zerocopy.log_every_jobs != 0ull &&
            cache->route_worker_jobs % g_moe_zerocopy.log_every_jobs == 0ull) {
            cuda_moe_zerocopy_report("periodic");
        }
        cache->route_miss_experts += request.miss_count;
        cache->route_worker_seconds += cuda_wall_sec() - started;
        cache->misses += request.miss_count;
        cache->hits += request.route_count - request.miss_count;
        cache->calls++;
        if (!ok) {
            if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
                g_moe_tiering.failures++;
            }
            *cache->route_failed_host = sequence;
            cache->route_worker_errors++;
            fprintf(stderr,
                    "ds4: CUDA GPU-resident route worker failed seq=%u layer=%u "
                    "routes=%u misses=%u reason=%s cuda=%s\n",
                    sequence, request.layer_index, request.route_count,
                    request.miss_count, failure_reason,
                    failure_cuda_error == cudaSuccess ? "none" :
                        cudaGetErrorString(failure_cuda_error));
        }
#ifdef _WIN32
        MemoryBarrier();
#else
        __sync_synchronize();
#endif
        /* WORKER-PROF: handshake di rilascio.  Il job si chiude sulla
         * scrittura di route_ready_host, che e' l'istante esatto in cui il
         * thread di decode puo' uscire dallo spin: e' li' che va tagliato
         * job_ms perche' la quadratura con worker_wait_ms sia onesta. */
        const uint64_t wprof_signal = ds4_workerprof_start(wprof);
        cuda_decode_trace_worker_end(request);
        cuda_decode_trace_upload_end(cache, request);
        if (!cuda_moe_route_mailbox_publish_upload(
                cache, sequence, request.host_generation)) {
            break;
        }
        {
            const uint64_t wprof_ready =
                ds4_workerprof_note_job_end(
                    wprof, wprof_pickup_ns, wprof_pickup_faults);
            ds4_workerprof_stop(wprof, WP_SIGNAL_NS, wprof_signal);
            *cache->route_ready_host = sequence;
            ds4_workerprof_publish_ready(wprof, sequence, wprof_ready);
        }
#ifdef _WIN32
        MemoryBarrier();
#else
        __sync_synchronize();
#endif
        if (cache->route_transient_read_sequence.load(
                std::memory_order_acquire) == sequence) {
            cache->route_transient_read_sequence.store(
                0u, std::memory_order_release);
        }
        cache->route_transient_cancel_sequence.store(
            0u, std::memory_order_release);
        cache->route_transient_timeout_cancel_sequence.store(
            0u, std::memory_order_release);
        cuda_moe_route_worker_publish_completed(
            cache, sequence, request.host_generation);
        if (wprof) {
            wprof_idle_started = ds4_workerprof_now_ns();
            wprof_idle_token =
                g_workerprof_token_active.load(std::memory_order_acquire);
        }
    }
    return NULL;
}

static int cuda_moe_expert_cache_copy_to_compact_async(
        cuda_moe_expert_cache *cache,
        uint32_t cache_slot,
        uint32_t compact_slot) {
    const uint64_t gate_src = (uint64_t)cache_slot * cache->gate_expert_bytes;
    const uint64_t gate_dst = (uint64_t)compact_slot * cache->gate_expert_bytes;
    const uint64_t down_src = (uint64_t)cache_slot * cache->down_expert_bytes;
    const uint64_t down_dst = (uint64_t)compact_slot * cache->down_expert_bytes;
    return cudaMemcpyAsync(g_moe_gather.gate + gate_dst, cache->gate + gate_src,
                           (size_t)cache->gate_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess &&
           cudaMemcpyAsync(g_moe_gather.up + gate_dst, cache->up + gate_src,
                           (size_t)cache->gate_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess &&
           cudaMemcpyAsync(g_moe_gather.down + down_dst, cache->down + down_src,
                           (size_t)cache->down_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess;
}

/* Selected-load profiling accumulators (DS4_CUDA_SEL_PROFILE). */
static uint64_t g_sel_prof_calls;
static uint64_t g_sel_prof_experts;
static double g_sel_prof_fetch_s;
static uint64_t g_route_prof_calls;
static double g_route_prof_d2h_s;
static double g_route_prof_observe_s;
static double g_route_prof_map_s;
static double g_route_prof_transport_s;
static double g_route_prof_publish_s;

static int cuda_model_range_in_window(const void *model_map, uint64_t offset, uint64_t bytes) {
    if (model_map == g_mtp_model_host_base) {
        return cuda_mtp_model_range_ptr(model_map, offset, bytes) != NULL;
    }
    if (offset > UINT64_MAX - bytes) return 0;
    return g_model_window_bytes && model_map == g_model_host_base && g_model_device_base &&
           offset + bytes <= g_model_window_bytes;
}

static const os_file_t *cuda_model_route_source_file(
        const void *model_map,
        int *is_main_file) {
    if (is_main_file) *is_main_file = 0;
    if (g_iq1_s_sidecar_file_valid &&
        model_map == g_iq1_s_sidecar_host_base) {
        return &g_iq1_s_sidecar_file;
    }
    if (g_model_file_valid && model_map == g_model_host_base) {
        if (is_main_file) *is_main_file = 1;
        return &g_model_file;
    }
    return NULL;
}

/* Persistent staging rotation so consecutive span uploads pipeline (pread of the
 * next tensor overlaps the H2D copy of the previous one). */
static uint64_t g_stream_span_idx = 0;

/* Stream `bytes` from the model file at `offset` DIRECTLY into a caller-owned
 * device buffer `dst`, async on the upload stream via the pinned staging pool.
 * No cudaMalloc / eviction / range-cache: this is the fast path for MoE experts
 * (cross-token reuse ~0, so the per-expert VRAM cache's malloc/evict churn --
 * ~40 ms/expert on WDDM, disk-independent -- is pure overhead). The caller MUST
 * cudaStreamSynchronize(g_model_upload_stream) before the data is read elsewhere. */
static int cuda_model_stream_span_into(
        char *dst,
        const void *model_map,
        uint64_t offset,
        uint64_t bytes,
        char *mirror) {
    int is_main_file = 0;
    const os_file_t *source = cuda_model_route_source_file(
        model_map, &is_main_file);
    if (!source || bytes == 0 || !dst) return 0;
    const uint64_t chunk = cuda_model_copy_chunk_bytes();
    const uint64_t stage_bytes = chunk + (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!cuda_model_stage_pool_alloc(stage_bytes)) return 0;
    uint64_t copied = 0;
    while (copied < bytes) {
        const uint64_t n = (bytes - copied < chunk) ? (bytes - copied) : chunk;
        const uint64_t bi = g_stream_span_idx % 4u;
        if (g_stream_span_idx >= 4u) {
            if (cudaEventSynchronize(g_model_stage_event[bi]) != cudaSuccess) { (void)cudaGetLastError(); return 0; }
        }
        const char *payload = NULL;
        if (is_main_file) {
            if (!cuda_model_stage_read(g_model_stage[bi], g_model_stage_bytes,
                                       offset + copied, n, &payload)) return 0;
        } else {
            if (!cuda_pread_full(source, g_model_stage[bi], n,
                                 offset + copied)) return 0;
            payload = (const char *)g_model_stage[bi];
        }
        if (mirror) {
            memcpy(mirror + copied, payload, (size_t)n);
            if (memcmp(mirror + copied, payload, (size_t)n) != 0) return 0;
        }
        if (cudaMemcpyAsync(dst + copied, payload, (size_t)n, cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess) {
            (void)cudaGetLastError();
            return 0;
        }
        if (cudaEventRecord(g_model_stage_event[bi], g_model_upload_stream) != cudaSuccess) { (void)cudaGetLastError(); return 0; }
        if (is_main_file) cuda_model_drop_file_pages(offset + copied, n);
        copied += n;
        g_stream_span_idx++;
    }
    return 1;
}

#ifdef _WIN32
static uint32_t cuda_moe_io_queue_depth(void) {
    uint32_t qd = 1;
    const char *env = getenv("DS4_CUDA_MOE_IO_QD");
    if (env && env[0]) {
        char *end = NULL;
        const unsigned long v = strtoul(env, &end, 10);
        if (end != env && v > 0) qd = (uint32_t)v;
    }
    if (qd > 4u) qd = 4u;
    return qd;
}

static int cuda_moe_io_events_ensure(void) {
    for (uint32_t i = 0; i < 4u; i++) {
        if (g_moe_io_event[i]) continue;
        g_moe_io_event[i] = CreateEventW(NULL, TRUE, FALSE, NULL);
        if (!g_moe_io_event[i]) {
            fprintf(stderr, "ds4: CUDA MoE overlapped I/O event creation failed: %lu\n",
                    (unsigned long)GetLastError());
            return 0;
        }
    }
    return 1;
}

static void cuda_moe_io_cancel_pending(
        const os_file_t *source,
        const int pending[4],
        uint32_t count) {
    if (!source) return;
    for (uint32_t i = 0; i < count; i++) {
        if (pending[i]) (void)CancelIoEx(source->h, &g_moe_io_ov[i]);
    }
    for (uint32_t i = 0; i < count; i++) {
        if (!pending[i]) continue;
        DWORD ignored = 0;
        (void)GetOverlappedResult(source->h, &g_moe_io_ov[i], &ignored, TRUE);
    }
}

/* Batch selected-expert file spans through the existing pinned staging ring.
 * ReadFile operations are submitted concurrently; completed buffers are then
 * uploaded on the existing nonblocking CUDA stream. The caller retains the
 * layer-level upload sync, so this path changes only host I/O concurrency. */
static int cuda_moe_fill_spans_overlapped(
        const void *model_map,
        const std::vector<cuda_moe_gather::span> &spans,
        uint32_t qd) {
    int is_main_file = 0;
    const os_file_t *source = cuda_model_route_source_file(
        model_map, &is_main_file);
    if (qd < 2u || qd > 4u || !source) return 0;
    const uint64_t stage_bytes = cuda_model_copy_chunk_bytes() +
        (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!cuda_model_stage_pool_alloc(stage_bytes) || !cuda_moe_io_events_ensure()) return 0;

    size_t base = 0;
    while (base < spans.size()) {
        const uint32_t count = (uint32_t)((spans.size() - base < qd) ?
            spans.size() - base : qd);
        int pending[4] = {0, 0, 0, 0};

        for (uint32_t i = 0; i < count; i++) {
            const cuda_moe_gather::span &s = spans[base + i];
            if (cuda_model_range_in_window(model_map, s.offset, s.bytes)) {
                const char *src = g_model_device_base + s.offset;
                if (s.mirror) {
                    memcpy(s.mirror,
                           (const char *)model_map + s.offset,
                           (size_t)s.bytes);
                    if (memcmp(s.mirror,
                               (const char *)model_map + s.offset,
                               (size_t)s.bytes) != 0) {
                        cuda_moe_io_cancel_pending(source, pending, count);
                        return 0;
                    }
                    cuda_dynamic_arena_observer_mirror_done(
                        s.arena_entry, s.arena_part, s.bytes);
                }
                if (cudaMemcpyAsync(s.dst, src, (size_t)s.bytes, cudaMemcpyDefault,
                                    g_model_upload_stream) != cudaSuccess) {
                    (void)cudaGetLastError();
                    cuda_moe_io_cancel_pending(source, pending, count);
                    return 0;
                }
                continue;
            }
            if (s.bytes == 0 || s.bytes > g_model_stage_bytes || s.bytes > 0xffffffffull) {
                cuda_moe_io_cancel_pending(source, pending, count);
                return 0;
            }
            /* The serial and overlapped readers share this pinned staging
             * ring. Event ownership, not producer-local bookkeeping, decides
             * when a buffer may be overwritten by the next ReadFile. */
            if (cudaEventSynchronize(g_model_stage_event[i]) != cudaSuccess) {
                (void)cudaGetLastError();
                cuda_moe_io_cancel_pending(source, pending, count);
                return 0;
            }

            OVERLAPPED &ov = g_moe_io_ov[i];
            memset(&ov, 0, sizeof(ov));
            ov.Offset = (DWORD)(s.offset & 0xffffffffu);
            ov.OffsetHigh = (DWORD)(s.offset >> 32);
            ov.hEvent = g_moe_io_event[i];
            (void)ResetEvent(ov.hEvent);
            const BOOL started = ReadFile(source->h, g_model_stage[i],
                                          (DWORD)s.bytes, NULL, &ov);
            if (!started && GetLastError() != ERROR_IO_PENDING) {
                fprintf(stderr, "ds4: CUDA MoE overlapped read submit failed at %llu: %lu\n",
                        (unsigned long long)s.offset, (unsigned long)GetLastError());
                cuda_moe_io_cancel_pending(source, pending, count);
                return 0;
            }
            pending[i] = 1;
        }

        for (uint32_t i = 0; i < count; i++) {
            if (!pending[i]) continue;
            const cuda_moe_gather::span &s = spans[base + i];
            DWORD got = 0;
            if (!GetOverlappedResult(source->h, &g_moe_io_ov[i], &got, TRUE) ||
                got != (DWORD)s.bytes) {
                fprintf(stderr, "ds4: CUDA MoE overlapped read completion failed at %llu: %lu (%lu/%llu bytes)\n",
                        (unsigned long long)s.offset, (unsigned long)GetLastError(),
                        (unsigned long)got, (unsigned long long)s.bytes);
                cuda_moe_io_cancel_pending(source, pending, count);
                return 0;
            }
            pending[i] = 0;
            if (s.mirror) {
                memcpy(s.mirror, g_model_stage[i], (size_t)s.bytes);
                if (memcmp(s.mirror, g_model_stage[i],
                           (size_t)s.bytes) != 0) {
                    cuda_moe_io_cancel_pending(source, pending, count);
                    return 0;
                }
                cuda_dynamic_arena_observer_mirror_done(
                    s.arena_entry, s.arena_part, s.bytes);
            }
            if (cudaMemcpyAsync(s.dst, g_model_stage[i], (size_t)s.bytes,
                                cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess ||
                cudaEventRecord(g_model_stage_event[i], g_model_upload_stream) != cudaSuccess) {
                (void)cudaGetLastError();
                cuda_moe_io_cancel_pending(source, pending, count);
                return 0;
            }
            g_moe_io_stage_used[i] = 1;
            if (is_main_file) cuda_model_drop_file_pages(s.offset, s.bytes);
        }
        base += count;
    }
    static int notice_printed = 0;
    if (!notice_printed) {
        fprintf(stderr, "ds4: CUDA MoE overlapped read succeeded queue depth=%u\n", qd);
        notice_printed = 1;
    }
    return 1;
}
#endif

/* Fill one compact slot for one expert weight (gate/up/down): zero-copy D2D from
 * the pinned host window when in-window, else stream straight from the file.
 * All async on the upload stream; caller batches one sync per layer. */
static int cuda_moe_fill_span(
        char *dst,
        const void *model_map,
        uint64_t offset,
        uint64_t bytes,
        char *mirror) {
    if (cuda_model_range_in_window(model_map, offset, bytes)) {
        const char *src = g_model_device_base + offset;   /* device-mapped host window */
        if (mirror) {
            memcpy(mirror, (const char *)model_map + offset, (size_t)bytes);
            if (memcmp(mirror, (const char *)model_map + offset,
                       (size_t)bytes) != 0) {
                return 0;
            }
        }
        if (cudaMemcpyAsync(dst, src, (size_t)bytes, cudaMemcpyDefault, g_model_upload_stream) != cudaSuccess) {
            (void)cudaGetLastError();
            return 0;
        }
        return 1;
    }
    return cuda_model_stream_span_into(dst, model_map, offset, bytes, mirror);
}

/* G73 selected-load shares the token's one absolute deadline. It never enters
 * os_pread(): every file span is an overlapped cancellable read, and every
 * staging-buffer reuse wait is polled against the same deadline. */
static int cuda_moe_fill_span_bounded(
        char *dst, const void *model_map, uint64_t offset, uint64_t bytes,
        char *mirror, double absolute_deadline) {
    if (cuda_model_range_in_window(model_map, offset, bytes)) {
        return cuda_moe_fill_span(dst, model_map, offset, bytes, mirror);
    }
    int is_main_file = 0;
    const os_file_t *source = cuda_model_route_source_file(
        model_map, &is_main_file);
    const uint64_t stage_bytes = cuda_model_copy_chunk_bytes() +
        (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!source || bytes == 0u || !dst || bytes > cuda_model_copy_chunk_bytes() ||
        !cuda_model_stage_pool_alloc(stage_bytes)) {
        return 0;
    }
    const uint64_t bi = g_stream_span_idx % 4u;
    for (;;) {
        const cudaError_t ready = cudaEventQuery(g_model_stage_event[bi]);
        if (ready == cudaSuccess) break;
        if (ready != cudaErrorNotReady ||
            cuda_deadline_remaining_ms(absolute_deadline) == 0u) {
            (void)cudaGetLastError();
            return 0;
        }
#ifdef _WIN32
        (void)SwitchToThread();
#else
        usleep(0);
#endif
    }
    const uint32_t remaining_ms =
        cuda_deadline_remaining_ms(absolute_deadline);
    if (remaining_ms == 0u) return 0;
    os_pread_cancellable_reset(&g_model_stage_pread[bi]);
    const int64_t got = os_pread_cancellable_timeout(
        source, g_model_stage[bi], bytes, offset,
        &g_model_stage_pread[bi], 1u,
        remaining_ms);
    if (got < 0 || (uint64_t)got != bytes) return 0;
    if (mirror) {
        memcpy(mirror, g_model_stage[bi], (size_t)bytes);
        if (memcmp(mirror, g_model_stage[bi], (size_t)bytes) != 0) return 0;
    }
    if (cuda_deadline_remaining_ms(absolute_deadline) == 0u ||
        cudaMemcpyAsync(dst, g_model_stage[bi], (size_t)bytes,
                        cudaMemcpyHostToDevice,
                        g_model_upload_stream) != cudaSuccess ||
        cudaEventRecord(g_model_stage_event[bi],
                        g_model_upload_stream) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }
    if (is_main_file) cuda_model_drop_file_pages(offset, bytes);
    g_stream_span_idx++;
    return 1;
}

static int cuda_moe_gather_ensure(char **ptr, uint64_t *cap, uint64_t bytes, const char *what) {
    if (bytes == 0) return 1;
    if (*ptr && *cap >= bytes) return 1;
    if (*ptr) { (void)cudaFree(*ptr); *ptr = NULL; *cap = 0; }
    char *dev = cuda_model_stream_alloc(bytes, 1, what, 0);
    if (!dev) return 0;
    *ptr = dev; *cap = bytes; return 1;
}

static int cuda_moe_gather_ensure_i32(int32_t **ptr, uint64_t *cap, uint32_t count, const char *what) {
    return cuda_moe_gather_ensure((char **)ptr, cap, (uint64_t)count * sizeof(int32_t), what);
}

static int cuda_iq1_s_vram_cache_requested_per_layer(void) {
    const char *env = getenv("DS4_IQ1_S_VRAM_CACHE_PER_LAYER");
    if (!env || !env[0] || strcmp(env, "0") == 0) return 0;
    char *end = NULL;
    errno = 0;
    const unsigned long value = strtoul(env, &end, 10);
    while (end && (*end == ' ' || *end == '\t')) end++;
    if (end == env || errno != 0 || !end || *end != '\0' ||
        value == 0 || value > 4) {
        fprintf(stderr, "ds4: invalid DS4_IQ1_S_VRAM_CACHE_PER_LAYER=%s\n", env);
        return -1;
    }
    return (int)value;
}

static void cuda_iq1_s_vram_cache_release(void) {
    cuda_iq1_s_vram_cache &cache = g_iq1_s_vram_cache;
    if (cache.attempted || cache.hits || cache.misses || cache.failures) {
        fprintf(stderr,
                "ds4: [iq1-s-vram-cache] result=summary per_layer=%u "
                "capacity=%u count=%u slot_bytes=%llu hits=%llu misses=%llu "
                "evictions=%llu h2d_bytes=%llu failures=%llu\n",
                cache.per_layer, cache.capacity, cache.count,
                (unsigned long long)cache.slot_bytes,
                (unsigned long long)cache.hits,
                (unsigned long long)cache.misses,
                (unsigned long long)cache.evictions,
                (unsigned long long)cache.h2d_bytes,
                (unsigned long long)cache.failures);
    }
    if (cache.device_base) (void)cudaFree(cache.device_base);
    cache.device_base = NULL;
    cache.allocated_bytes = 0;
    cache.slot_bytes = 0;
    cache.gate_expert_bytes = 0;
    cache.down_expert_bytes = 0;
    cache.tick = 0;
    cache.hits = 0;
    cache.misses = 0;
    cache.evictions = 0;
    cache.h2d_bytes = 0;
    cache.failures = 0;
    cache.per_layer = 0;
    cache.capacity = 0;
    cache.count = 0;
    cache.attempted = 0;
    cache.slots.clear();
}

/* Returns 1 when ready, 0 when disabled, and -1 on requested failure. */
static int cuda_iq1_s_vram_cache_prepare(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    cuda_iq1_s_vram_cache &cache = g_iq1_s_vram_cache;
    const int requested = cuda_iq1_s_vram_cache_requested_per_layer();
    if (requested == 0) return 0;
    if (requested < 0 || gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        cache.attempted = 1;
        cache.failures++;
        return -1;
    }
    const uint64_t slot_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    const uint32_t capacity = CUDA_IQ1_S_LAYER_COUNT * (uint32_t)requested;
    if (slot_bytes > UINT64_MAX / capacity) {
        cache.attempted = 1;
        cache.failures++;
        return -1;
    }
    const uint64_t allocated_bytes = slot_bytes * capacity;
    if (cache.device_base) {
        return cache.per_layer == (uint32_t)requested &&
               cache.capacity == capacity && cache.slot_bytes == slot_bytes &&
               cache.gate_expert_bytes == gate_expert_bytes &&
               cache.down_expert_bytes == down_expert_bytes ? 1 : -1;
    }
    if (cache.attempted) return -1;
    cache.attempted = 1;
    cache.per_layer = (uint32_t)requested;
    cache.capacity = capacity;
    cache.slot_bytes = slot_bytes;
    cache.gate_expert_bytes = gate_expert_bytes;
    cache.down_expert_bytes = down_expert_bytes;
    cache.allocated_bytes = allocated_bytes;
    cudaError_t err = cudaMalloc((void **)&cache.device_base,
                                 (size_t)allocated_bytes);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: IQ1_S VRAM cache allocation failed: %s requested=%.3f GiB\n",
                cudaGetErrorString(err),
                (double)allocated_bytes / 1073741824.0);
        (void)cudaGetLastError();
        cache.device_base = NULL;
        cache.failures++;
        return -1;
    }
    try {
        cache.slots.resize(capacity);
    } catch (...) {
        (void)cudaFree(cache.device_base);
        cache.device_base = NULL;
        cache.failures++;
        return -1;
    }
    fprintf(stderr,
            "ds4: [iq1-s-vram-cache] result=ready per_layer=%u capacity=%u "
            "allocated_bytes=%llu slot_bytes=%llu policy=layer-lru\n",
            cache.per_layer, cache.capacity,
            (unsigned long long)cache.allocated_bytes,
            (unsigned long long)cache.slot_bytes);
    return 1;
}

/* Returns the device slot. hit=1 is immediately usable; hit=0 is reserved
 * invalid until the caller completes and fences its H2D upload. */
static int cuda_iq1_s_vram_cache_resolve_slot(
        uint32_t layer_index,
        uint32_t expert_id,
        int *hit,
        int *evicted) {
    if (!hit || !evicted || layer_index >= CUDA_IQ1_S_LAYER_COUNT ||
        expert_id >= 256u)
        return -1;
    *evicted = 0;
    cuda_iq1_s_vram_cache &cache = g_iq1_s_vram_cache;
    if (!cache.device_base || cache.per_layer == 0) return -1;
    const uint32_t first = layer_index * cache.per_layer;
    uint32_t victim = UINT32_MAX;
    uint64_t oldest = UINT64_MAX;
    for (uint32_t i = 0; i < cache.per_layer; i++) {
        const uint32_t slot_index = first + i;
        cuda_iq1_s_vram_cache_slot &slot = cache.slots[slot_index];
        if (slot.valid && slot.expert_id == (int32_t)expert_id) {
            slot.age = ++cache.tick;
            cache.hits++;
            *hit = 1;
            return (int)slot_index;
        }
        if (!slot.valid) {
            victim = slot_index;
            break;
        } else if (slot.age < oldest) {
            oldest = slot.age;
            victim = slot_index;
        }
    }
    if (victim == UINT32_MAX) {
        cache.failures++;
        return -1;
    }
    cuda_iq1_s_vram_cache_slot &slot = cache.slots[victim];
    if (slot.valid) {
        cache.evictions++;
        *evicted = 1;
    }
    slot.valid = 0;
    slot.expert_id = (int32_t)expert_id;
    slot.age = ++cache.tick;
    cache.misses++;
    *hit = 0;
    return (int)victim;
}

static char *cuda_iq1_s_vram_cache_slot_base(uint32_t slot_index) {
    cuda_iq1_s_vram_cache &cache = g_iq1_s_vram_cache;
    if (!cache.device_base || slot_index >= cache.capacity) return NULL;
    return cache.device_base + (uint64_t)slot_index * cache.slot_bytes;
}

static int cuda_prefill_waves_requested(void) {
    const char *env = getenv("DS4_CUDA_PREFILL_WAVES");
    return env && env[0] && strcmp(env, "0") != 0;
}

static int cuda_prefill_wave_double_buffer_requested(void) {
    const char *env = getenv("DS4_CUDA_PREFILL_WAVE_DOUBLE_BUFFER");
    if (!env || !env[0] || strcmp(env, "0") == 0) return 0;
    if (strcmp(env, "1") == 0) return 1;
    fprintf(stderr,
            "ds4: [prefill-wave-overlap] invalid DS4_CUDA_PREFILL_WAVE_DOUBLE_BUFFER=%s; request refused\n",
            env);
    return -1;
}

static uint32_t cuda_prefill_wave_force_experts(void) {
    const char *env = getenv("DS4_CUDA_PREFILL_WAVE_FORCE_EXPERTS");
    if (!env || !env[0]) return 0;
    char *end = NULL;
    errno = 0;
    const unsigned long v = strtoul(env, &end, 10);
    while (end && (*end == ' ' || *end == '\t')) end++;
    if (end == env || errno != 0 || !end || *end != '\0' || v == 0 || v > 256ul) {
        fprintf(stderr,
                "ds4: [prefill-waves] invalid DS4_CUDA_PREFILL_WAVE_FORCE_EXPERTS=%s; request refused\n",
                env);
        return UINT32_MAX;
    }
    return (uint32_t)v;
}

static int cuda_prefill_wave_debug_dump_active(void) {
    static const char *names[] = {
        "DS4_METAL_GRAPH_DUMP_PREFIX",
        "DS4_METAL_GRAPH_DUMP_LOGITS",
        "DS4_METAL_DUMP_PREFILL_LOGITS",
        "DS4_CPU_DUMP_PREFILL_LOGITS",
        "DS4_CPU_DUMP_LOGITS",
        "DS4_CUDA_GRAPH_DUMP_PREFIX",
        "DS4_CUDA_DUMP_PREFILL_LOGITS",
        "DS4_CUDA_DUMP_LOGITS",
        "DS4_CUDA_DUMP_TENSORS",
    };
    for (uint32_t i = 0; i < (uint32_t)(sizeof(names) / sizeof(names[0])); i++) {
        const char *value = getenv(names[i]);
        if (value && value[0]) return 1;
    }
    return 0;
}

static uint32_t cuda_prefill_wave_budget_experts(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        int double_buffer) {
    if (gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        return 0;
    }
    const uint64_t expert_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    if (expert_bytes == 0) return 0;
    if (double_buffer && expert_bytes > UINT64_MAX / 2ull) return 0;
    size_t free_b = 0, total_b = 0;
    if (cudaMemGetInfo(&free_b, &total_b) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }
    uint64_t free_bytes = (uint64_t)free_b;
    const uint64_t reserve = cuda_model_stream_reserve_bytes();
    const uint64_t reusable = cuda_u64_saturating_add(
        cuda_u64_saturating_add(g_moe_gather.gate_cap, g_moe_gather.up_cap),
        g_moe_gather.down_cap);
    uint64_t reusable_db = 0;
    if (double_buffer) {
        for (uint32_t i = 0; i < 2u; i++) {
            reusable_db = cuda_u64_saturating_add(
                reusable_db,
                cuda_u64_saturating_add(
                    cuda_u64_saturating_add(g_moe_gather.wave_gate_cap[i],
                                            g_moe_gather.wave_up_cap[i]),
                    g_moe_gather.wave_down_cap[i]));
        }
    }
    if (free_bytes > reserve) free_bytes -= reserve;
    else free_bytes = 0;
    const uint64_t budget = cuda_u64_saturating_add(
        free_bytes, double_buffer ? reusable_db : reusable);
    const uint64_t divisor = double_buffer ? expert_bytes * 2ull : expert_bytes;
    if (divisor == 0) return 0;
    uint64_t experts = budget / divisor;
    if (experts > 256ull) experts = 256ull;
    return (uint32_t)experts;
}

static int cuda_moe_wave_slab_ensure(
        uint32_t parity,
        uint32_t wave_experts,
        uint32_t slot_count,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (parity >= 2u) return 0;
    const uint64_t cgate = (uint64_t)wave_experts * gate_expert_bytes;
    const uint64_t cdown = (uint64_t)wave_experts * down_expert_bytes;
    if (!cuda_moe_gather_ensure(&g_moe_gather.wave_gate[parity],
                                &g_moe_gather.wave_gate_cap[parity],
                                cgate, "moe wave overlap gate") ||
        !cuda_moe_gather_ensure(&g_moe_gather.wave_up[parity],
                                &g_moe_gather.wave_up_cap[parity],
                                cgate, "moe wave overlap up") ||
        !cuda_moe_gather_ensure(&g_moe_gather.wave_down[parity],
                                &g_moe_gather.wave_down_cap[parity],
                                cdown, "moe wave overlap down") ||
        !cuda_moe_gather_ensure_i32(&g_moe_gather.wave_slot[parity],
                                     &g_moe_gather.wave_slot_cap[parity],
                                     slot_count, "moe wave overlap slots") ||
        !cuda_moe_gather_ensure(
            (char **)&g_moe_gather.wave_pair[parity],
            &g_moe_gather.wave_pair_cap[parity],
            (uint64_t)slot_count * sizeof(uint32_t),
            "moe wave overlap pairs")) {
        return 0;
    }
    if (!g_moe_gather.wave_upload_ready_db[parity] &&
        !cuda_ok(cudaEventCreateWithFlags(
                     &g_moe_gather.wave_upload_ready_db[parity],
                     cudaEventDisableTiming),
                 "moe wave overlap upload event")) {
        return 0;
    }
    if (!g_moe_gather.wave_compute_done[parity] &&
        !cuda_ok(cudaEventCreateWithFlags(
                     &g_moe_gather.wave_compute_done[parity],
                     cudaEventDisableTiming),
                 "moe wave overlap compute event")) {
        return 0;
    }
    return 1;
}

static int cuda_moe_selected_stage_wave(
        const void *model_map,
        uint32_t layer_index,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        uint32_t n_total_expert,
        uint32_t n_expert,
        uint32_t n_tokens,
        uint32_t wave_index) {
    if (!g_moe_gather.wave_active || g_moe_gather.wave_max_experts == 0 ||
        n_total_expert == 0 || n_expert == 0 ||
        wave_index >= g_moe_gather.wave_count) {
        return 0;
    }
    const uint32_t slot_count = n_tokens * n_expert;
    const uint32_t begin = wave_index * g_moe_gather.wave_max_experts;
    uint32_t end = begin + g_moe_gather.wave_max_experts;
    const uint32_t compact_count = (uint32_t)g_moe_gather.h_compact_ids.size();
    if (begin >= compact_count) return 0;
    if (end > compact_count) end = compact_count;
    const uint32_t wave_experts = end - begin;
    const uint32_t parity = wave_index & 1u;
    const int double_buffer = g_moe_gather.wave_double_buffer != 0;
    const uint64_t cgate = (uint64_t)wave_experts * gate_expert_bytes;
    const uint64_t cdown = (uint64_t)wave_experts * down_expert_bytes;
    char *gate_dst_base = NULL;
    char *up_dst_base = NULL;
    char *down_dst_base = NULL;
    int32_t *slot_dst_base = NULL;
    cudaEvent_t upload_ready = NULL;
    std::vector<int32_t> *wave_slots_ptr = &g_moe_gather.h_wave_slots;
    std::vector<uint32_t> *wave_pairs_ptr = &g_moe_gather.h_wave_pairs;
    if (double_buffer) {
        if (g_moe_gather.wave_compute_recorded[parity]) {
            if (!cuda_ok(cudaEventSynchronize(
                             g_moe_gather.wave_compute_done[parity]),
                         "moe wave overlap reuse fence")) {
                return 0;
            }
            g_moe_gather.wave_compute_recorded[parity] = 0;
            g_prefill_wave_overlap_stats.reuse_waits =
                cuda_u64_saturating_add(
                    g_prefill_wave_overlap_stats.reuse_waits, 1);
        }
        /* A staged parity may not have reached compute ownership when a prior
         * launch failed. Fence its upload before ensure can resize/free the
         * destination slabs or the pageable metadata vectors are rewritten. */
        if (g_moe_gather.wave_upload_ready_db[parity] &&
            !cuda_ok(cudaEventSynchronize(
                         g_moe_gather.wave_upload_ready_db[parity]),
                     "moe wave overlap prior upload fence")) {
            return 0;
        }
        if (!cuda_moe_wave_slab_ensure(parity, wave_experts, slot_count,
                                       gate_expert_bytes, down_expert_bytes)) {
            return 0;
        }
        gate_dst_base = g_moe_gather.wave_gate[parity];
        up_dst_base = g_moe_gather.wave_up[parity];
        down_dst_base = g_moe_gather.wave_down[parity];
        slot_dst_base = g_moe_gather.wave_slot[parity];
        upload_ready = g_moe_gather.wave_upload_ready_db[parity];
        wave_slots_ptr = &g_moe_gather.h_wave_slots_db[parity];
        wave_pairs_ptr = &g_moe_gather.h_wave_pairs_db[parity];
    } else {
        if (!cuda_moe_gather_ensure(&g_moe_gather.gate, &g_moe_gather.gate_cap,
                                    cgate, "moe wave gate") ||
            !cuda_moe_gather_ensure(&g_moe_gather.up, &g_moe_gather.up_cap,
                                    cgate, "moe wave up") ||
            !cuda_moe_gather_ensure(&g_moe_gather.down, &g_moe_gather.down_cap,
                                    cdown, "moe wave down") ||
            !cuda_moe_gather_ensure_i32(&g_moe_gather.slot,
                                        &g_moe_gather.slot_cap,
                                        slot_count, "moe wave slots")) {
            return 0;
        }
        if (!g_moe_gather.wave_upload_ready &&
            !cuda_ok(cudaEventCreateWithFlags(
                         &g_moe_gather.wave_upload_ready,
                         cudaEventDisableTiming),
                     "moe wave upload event")) {
            return 0;
        }
        gate_dst_base = g_moe_gather.gate;
        up_dst_base = g_moe_gather.up;
        down_dst_base = g_moe_gather.down;
        slot_dst_base = g_moe_gather.slot;
        upload_ready = g_moe_gather.wave_upload_ready;
    }

    std::vector<int32_t> &wave_slots = *wave_slots_ptr;
    std::vector<uint32_t> &wave_pairs = *wave_pairs_ptr;
    wave_slots.assign(slot_count, 0);
    wave_pairs.clear();
    wave_pairs.reserve(slot_count);
    std::vector<int32_t> &e2s = g_moe_gather.h_expert_to_slot;
    e2s.assign(n_total_expert, -1);
    for (uint32_t i = begin; i < end; i++) {
        const int32_t expert = g_moe_gather.h_compact_ids[i];
        if (expert < 0 || (uint32_t)expert >= n_total_expert) return 0;
        e2s[(uint32_t)expert] = (int32_t)(i - begin);
    }
    for (uint32_t i = 0; i < slot_count; i++) {
        const int32_t expert = g_moe_gather.h_sel[i];
        if (expert < 0 || (uint32_t)expert >= n_total_expert) return 0;
        const int32_t wave_slot = e2s[(uint32_t)expert];
        if (wave_slot >= 0) {
            wave_slots[i] = wave_slot;
            wave_pairs.push_back(i);
        }
    }
    if (wave_pairs.empty()) return 0;

    std::vector<cuda_moe_gather::span> &spans = g_moe_gather.h_spans;
    std::vector<uint8_t> &arena_resident = g_moe_gather.h_arena_resident;
    spans.clear();
    spans.reserve((size_t)wave_experts * 3u);
    arena_resident.assign(wave_experts, 0);
    const int arena_active = g_dynamic_arena.host_base &&
        g_dynamic_arena.snapshot_generation != 0 &&
        !g_dynamic_arena.hits_disabled &&
        !g_dynamic_arena.submissions_blocked;
    auto append_span = [&](char *destination,
                           uint64_t source,
                           uint64_t bytes,
                           uint32_t expert,
                           uint8_t part) {
        uint32_t arena_entry = UINT32_MAX;
        char *mirror = cuda_dynamic_arena_observer_mirror_ptr(
            model_map, layer_index, expert, part, source, bytes,
            &arena_entry);
        spans.push_back({
            destination, source, bytes, mirror, arena_entry, part
        });
    };
    for (uint32_t i = 0; i < wave_experts; i++) {
        const uint32_t expert = (uint32_t)g_moe_gather.h_compact_ids[begin + i];
        const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
        if (arena_active) {
            const cuda_dynamic_arena_copy_status arena_status =
                cuda_dynamic_arena_copy_expert_async(
                    g_dynamic_arena,
                    model_map, layer_index, expert,
                    gate_offset, up_offset, down_offset,
                    gate_dst_base + gate_dst,
                    up_dst_base + gate_dst,
                    down_dst_base + down_dst,
                    gate_expert_bytes, gate_expert_bytes,
                    down_expert_bytes);
            if (arena_status == CUDA_DYNAMIC_ARENA_FATAL) {
                (void)cudaStreamSynchronize(g_model_upload_stream);
                return 0;
            }
            if (arena_status == CUDA_DYNAMIC_ARENA_ENQUEUED) {
                arena_resident[i] = 1u;
                continue;
            }
        }
        append_span(gate_dst_base + gate_dst,
                    gate_offset + (uint64_t)expert * gate_expert_bytes,
                    gate_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_GATE);
        append_span(up_dst_base + gate_dst,
                    up_offset + (uint64_t)expert * gate_expert_bytes,
                    gate_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_UP);
        append_span(down_dst_base + down_dst,
                    down_offset + (uint64_t)expert * down_expert_bytes,
                    down_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_DOWN);
    }

    int fill_ok = 0;
#ifdef _WIN32
    const uint32_t io_qd = cuda_moe_io_queue_depth();
    if (io_qd > 1u) {
        fill_ok = cuda_moe_fill_spans_overlapped(model_map, spans, io_qd);
    } else
#endif
    {
        fill_ok = 1;
        for (const cuda_moe_gather::span &s : spans) {
            if (!cuda_moe_fill_span(
                    s.dst, model_map, s.offset, s.bytes, s.mirror)) {
                fill_ok = 0;
                break;
            }
            if (s.mirror) {
                cuda_dynamic_arena_observer_mirror_done(
                    s.arena_entry, s.arena_part, s.bytes);
            }
        }
    }
    int metadata_ok = fill_ok &&
        cuda_ok(cudaMemcpyAsync(slot_dst_base, wave_slots.data(),
                                (size_t)slot_count * sizeof(int32_t),
                                cudaMemcpyHostToDevice,
                                g_model_upload_stream),
                "moe wave slots upload");
    if (metadata_ok && double_buffer) {
        metadata_ok = cuda_ok(cudaMemcpyAsync(
                                  g_moe_gather.wave_pair[parity],
                                  wave_pairs.data(),
                                  (size_t)wave_pairs.size() * sizeof(uint32_t),
                                  cudaMemcpyHostToDevice,
                                  g_model_upload_stream),
                              "moe wave overlap pairs upload");
    }
    if (!metadata_ok ||
        !cuda_ok(cudaEventRecord(upload_ready, g_model_upload_stream),
                 "moe wave upload ready")) {
        (void)cudaStreamSynchronize(g_model_upload_stream);
        return 0;
    }
    uint64_t source_span_bytes = 0;
    uint64_t arena_experts = 0;
    for (const cuda_moe_gather::span &span : spans) {
        source_span_bytes = cuda_u64_saturating_add(
            source_span_bytes, span.bytes);
    }
    for (uint8_t resident : arena_resident) {
        arena_experts += resident != 0;
    }
    uint64_t expert_bytes = UINT64_MAX;
    if (gate_expert_bytes <= (UINT64_MAX - down_expert_bytes) / 2ull) {
        expert_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    }
    g_moe_gather.wave_source_span_bytes = cuda_u64_saturating_add(
        g_moe_gather.wave_source_span_bytes, source_span_bytes);
    g_moe_gather.wave_arena_h2d_bytes = cuda_u64_saturating_add(
        g_moe_gather.wave_arena_h2d_bytes,
        cuda_u64_saturating_mul(arena_experts, expert_bytes));
    g_moe_gather.wave_arena_experts = cuda_u64_saturating_add(
        g_moe_gather.wave_arena_experts, arena_experts);
    g_moe_gather.wave_direct_experts = cuda_u64_saturating_add(
        g_moe_gather.wave_direct_experts, wave_experts - arena_experts);
    g_moe_gather.slot_tensor.ptr = slot_dst_base;
    g_moe_gather.slot_tensor.bytes = (uint64_t)slot_count * sizeof(int32_t);
    g_moe_gather.slot_tensor.owner = 0;
    g_moe_gather.wave_index = wave_index;
    g_moe_gather.wave_current_experts = wave_experts;
    g_moe_gather.wave_active_pairs = (uint32_t)wave_pairs.size();
    if (double_buffer) {
        g_moe_gather.wave_current_experts_db[parity] = wave_experts;
        g_moe_gather.wave_active_pairs_db[parity] =
            (uint32_t)wave_pairs.size();
    }
    return 1;
}

/* Publish ownership of a parity after any of its slabs have been consumed by
 * stream 0. On the exceptional event-record path, drain stream 0 before
 * returning failure so later requests cannot reuse in-flight storage. */
static int cuda_moe_wave_compute_seal(uint32_t parity) {
    if (parity >= 2u || !g_moe_gather.wave_compute_done[parity]) return 0;
    cudaError_t err = cudaEventRecord(
        g_moe_gather.wave_compute_done[parity], 0);
    if (err == cudaSuccess) {
        g_moe_gather.wave_compute_recorded[parity] = 1;
        g_prefill_wave_overlap_stats.compute_records =
            cuda_u64_saturating_add(
                g_prefill_wave_overlap_stats.compute_records, 1);
        return 1;
    }
    fprintf(stderr, "ds4: CUDA moe wave overlap compute seal failed: %s\n",
            cudaGetErrorString(err));
    (void)cudaGetLastError();
    err = cudaStreamSynchronize(0);
    g_moe_gather.wave_compute_recorded[parity] = 0;
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA moe wave overlap failure drain failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
    }
    return 0;
}

extern "C" int ds4_gpu_routed_moe_prepare_selected(
        const void *model_map, uint64_t model_size,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        const ds4_gpu_tensor *selected, uint32_t n_expert, uint32_t n_tokens) {
    g_moe_selected_prepared.valid = 0;
    const char *env = getenv("DS4_CUDA_MOE_OVERLAP_SHARED");
    const char *full_env = getenv("DS4_CUDA_MOE_OVERLAP_SHARED_FULL");
    const int minimal_enabled = env && env[0] && strcmp(env, "0") != 0;
    const int full_enabled = full_env && full_env[0] && strcmp(full_env, "0") != 0;
    if ((!minimal_enabled && !full_enabled) ||
        getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL ||
        cuda_moe_expert_cache_requested() != 0) {
        return 0;
    }
    const uint32_t n_total_expert = 256u;
    if (!model_map || !selected || !selected->ptr || n_expert == 0 || n_tokens == 0 ||
        gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        n_tokens > UINT32_MAX / n_expert) {
        return 0;
    }
    const uint32_t slot_count = n_tokens * n_expert;
    if (selected->bytes < (uint64_t)slot_count * sizeof(int32_t) ||
        gate_expert_bytes > UINT64_MAX / n_total_expert ||
        down_expert_bytes > UINT64_MAX / n_total_expert) {
        return 0;
    }
    const uint64_t gate_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_offset > model_size || gate_bytes > model_size - gate_offset ||
        up_offset > model_size || gate_bytes > model_size - up_offset ||
        down_offset > model_size || down_bytes > model_size - down_offset) {
        return 0;
    }
    if (cuda_model_range_in_window(model_map, gate_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, up_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, down_offset, down_bytes)) {
        return 0;
    }

    g_moe_gather.h_sel.resize(slot_count);
    if (!cuda_ok(cudaMemcpy(g_moe_gather.h_sel.data(), selected->ptr,
                            (size_t)slot_count * sizeof(int32_t),
                            cudaMemcpyDeviceToHost), "moe overlap selected D2H")) {
        return 0;
    }
    g_moe_selected_prepared.model_map = model_map;
    g_moe_selected_prepared.selected_ptr = selected->ptr;
    g_moe_selected_prepared.gate_offset = gate_offset;
    g_moe_selected_prepared.up_offset = up_offset;
    g_moe_selected_prepared.down_offset = down_offset;
    g_moe_selected_prepared.gate_expert_bytes = gate_expert_bytes;
    g_moe_selected_prepared.down_expert_bytes = down_expert_bytes;
    g_moe_selected_prepared.n_expert = n_expert;
    g_moe_selected_prepared.n_tokens = n_tokens;
    g_moe_selected_prepared.full = full_enabled;
    g_moe_selected_prepared.valid = 1;
    return 1;
}

static int cuda_nested_residual_resolve_exact(
        uint32_t layer_index, uint32_t expert, uint32_t *slot_out) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (state.residual_cache_enabled) {
        fprintf(stderr,
                "ds4: nested residual CPU resolver refused in residual-cache mode\n");
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.failures++;
        state.hard_failure = 1;
        return -1;
    }
    if (!slot_out || !state.active ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        expert >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT ||
        !state.layers[layer_index].ready) {
        return 0;
    }
    const int profile = state.profile_enabled != 0;
    const double lookup_started = profile ? cuda_wall_sec() : 0.0;
    if (profile) state.profile_lookup_calls++;
    const uint32_t map_index = layer_index *
        CUDA_NESTED_RESIDUAL_EXPERT_COUNT + expert;
    const int32_t cached = state.cache_by_layer_expert[map_index];
    if (cached >= 0 && (uint32_t)cached < state.cache_capacity) {
        cuda_nested_residual_cache_slot &slot =
            state.cache_slots[(uint32_t)cached];
        if (slot.valid && slot.layer == layer_index && slot.expert == expert) {
            if (profile) {
                state.profile_lookup_seconds +=
                    cuda_wall_sec() - lookup_started;
            }
            slot.age = ++state.age;
            state.exact_cache_hits++;
            *slot_out = (uint32_t)cached;
            return 1;
        }
        if (profile) {
            state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
        }
        state.reconstruction_mismatches++;
        state.failures++;
        return -1;
    }

    uint32_t victim = UINT32_MAX;
    uint64_t oldest = UINT64_MAX;
    for (uint32_t i = 0; i < state.cache_capacity; i++) {
        const cuda_nested_residual_cache_slot &slot = state.cache_slots[i];
        if (!slot.valid) {
            victim = i;
            break;
        }
        if (slot.age < oldest) {
            oldest = slot.age;
            victim = i;
        }
    }
    if (victim == UINT32_MAX) {
        if (profile) {
            state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
        }
        state.failures++;
        return -1;
    }
    if (profile) {
        state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
    }
    cuda_nested_residual_cache_slot &slot = state.cache_slots[victim];
    const int victim_was_valid = slot.valid != 0;

    cuda_nested_residual_layer &layer = state.layers[layer_index];
    const uint64_t residual_offset = layer.residual_layer_start +
        (uint64_t)expert * layer.residual_expert_bytes;
    if (layer.residual_expert_bytes > state.residual_scratch.size() ||
        residual_offset > state.file_size ||
        layer.residual_expert_bytes > state.file_size - residual_offset) {
        state.failures++;
        return -1;
    }
    const double pread_started = profile ? cuda_wall_sec() : 0.0;
    const int transport_repeat =
        ds4_transport_file_load_begin(layer_index, expert);
    const int pread_ok = cuda_pread_full(
        &state.file, state.residual_scratch.data(),
        layer.residual_expert_bytes, residual_offset);
    if (profile) {
        state.profile_pread_calls++;
        state.profile_pread_seconds += cuda_wall_sec() - pread_started;
    }
    if (!pread_ok) {
        ds4_transport_mark_incomplete();
        state.failures++;
        return -1;
    }
    ds4_transport_record_file_bytes(
        transport_repeat, layer.residual_expert_bytes);
    state.exact_cache_misses++;
    state.residual_preads++;
    state.residual_bytes += layer.residual_expert_bytes;

    if (slot.copy_pending) {
        const double wait_started = profile ? cuda_wall_sec() : 0.0;
        const cudaError_t wait = cudaEventSynchronize(slot.reuse_event);
        if (profile) {
            state.profile_reuse_wait_calls++;
            state.profile_reuse_wait_seconds +=
                cuda_wall_sec() - wait_started;
        }
        if (wait != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual cache reuse wait failed: %s\n",
                    cudaGetErrorString(wait));
            (void)cudaGetLastError();
            state.failures++;
            return -1;
        }
        slot.copy_pending = 0;
    }
    if (slot.valid) {
        const uint32_t old_index = slot.layer *
            CUDA_NESTED_RESIDUAL_EXPERT_COUNT + slot.expert;
        if (state.cache_by_layer_expert[old_index] == (int32_t)victim) {
            state.cache_by_layer_expert[old_index] = -1;
        }
        slot.valid = 0;
    }

    uint8_t base_pageable = 0;
    const uint8_t *expert_base = cuda_nested_residual_base_expert(
        state, layer_index, expert, &base_pageable);
    if (!expert_base) {
        state.failures++;
        return -1;
    }
    if (base_pageable) {
        state.base_pageable_hits++;
    } else {
        state.base_pinned_hits++;
    }
    uint8_t *native = state.cache +
        (uint64_t)victim * state.cache_slot_bytes;
    if (profile) state.profile_reconstruct_calls++;
    for (uint32_t part = 0; part < CUDA_NESTED_RESIDUAL_PART_COUNT;
         part++) {
        const cuda_nested_residual_record &record = layer.records[part];
        const uint64_t blocks = (record.ncols / 256u) * record.nrows;
        const uint8_t *base = expert_base + record.base_kind_offset;
        const uint8_t *residual = state.residual_scratch.data() +
            record.kind_offset;
        uint8_t *destination = native + record.native_kind_offset;
        const double reconstruct_started = profile ? cuda_wall_sec() : 0.0;
        for (uint64_t block = 0; block < blocks; block++) {
            cuda_nested_join_block(
                record.source_type,
                base + block * record.base_block_bytes,
                residual + block * record.residual_block_bytes,
                destination + block * record.native_block_bytes);
        }
        if (profile) {
            state.profile_reconstruct_blocks += blocks;
            state.profile_reconstruct_seconds +=
                cuda_wall_sec() - reconstruct_started;
        }
        if (getenv("DS4_NESTED_RESIDUAL_VERIFY_RECONSTRUCTION") != NULL) {
            const uint8_t *authoritative = state.source_map +
                record.source_offset +
                (uint64_t)expert * record.native_kind_bytes;
            const double verify_started = profile ? cuda_wall_sec() : 0.0;
            const int verify_mismatch =
                memcmp(destination, authoritative,
                       (size_t)record.native_kind_bytes) != 0;
            if (profile) {
                state.profile_verify_calls++;
                state.profile_verify_bytes += record.native_kind_bytes;
                state.profile_verify_seconds +=
                    cuda_wall_sec() - verify_started;
            }
            if (verify_mismatch) {
                state.reconstruction_mismatches++;
                state.failures++;
                return -1;
            }
        }
    }
    slot.layer = layer_index;
    slot.expert = expert;
    slot.age = ++state.age;
    slot.valid = 1;
    if (!victim_was_valid && state.cache_count < state.cache_capacity) {
        state.cache_count++;
    }
    state.cache_by_layer_expert[map_index] = (int32_t)victim;
    state.reconstructed_experts++;
    *slot_out = victim;
    return 1;
}

static int cuda_nested_residual_cache_scan_range(
        cuda_nested_residual_state &state,
        uint32_t layer_index,
        uint32_t *begin_out,
        uint32_t *count_out) {
    if (!begin_out || !count_out ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        state.cache_capacity == 0) {
        cuda_nested_residual_note_cache_invariant_failure(state);
        return 0;
    }
    uint32_t begin = 0;
    uint32_t count = state.cache_capacity;
    if (state.cache_layer_partitioned) {
        begin = state.cache_layer_begin[layer_index];
        count = state.cache_layer_capacity[layer_index];
        if (count == 0 || begin > state.cache_capacity ||
            count > state.cache_capacity - begin) {
            cuda_nested_residual_note_cache_invariant_failure(state);
            return 0;
        }
    }
    *begin_out = begin;
    *count_out = count;
    return 1;
}

static int cuda_nested_residual_resolve_residual_slot_locked(
        uint32_t layer_index, uint32_t expert, uint32_t *slot_out) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (!slot_out || !state.residual_cache_enabled ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        expert >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT ||
        !state.layers[layer_index].ready) {
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.failures++;
        return -1;
    }
    cuda_nested_residual_layer &layer = state.layers[layer_index];
    if (layer.residual_expert_bytes == 0 ||
        layer.residual_expert_bytes > state.cache_slot_bytes ||
        state.cache_capacity == 0 ||
        state.cache_by_layer_expert.size() <
            CUDA_NESTED_RESIDUAL_LAYER_COUNT *
                CUDA_NESTED_RESIDUAL_EXPERT_COUNT) {
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.failures++;
        return -1;
    }

    uint32_t scan_begin = 0;
    uint32_t scan_count = 0;
    if (!cuda_nested_residual_cache_scan_range(
            state, layer_index, &scan_begin, &scan_count)) {
        state.failures++;
        return -1;
    }

    const int profile = state.profile_enabled != 0;
    const double lookup_started = profile ? cuda_wall_sec() : 0.0;
    if (profile) state.profile_lookup_calls++;
    const uint32_t map_index = layer_index *
        CUDA_NESTED_RESIDUAL_EXPERT_COUNT + expert;
    const int32_t cached = state.cache_by_layer_expert[map_index];
    if (cached >= 0 && (uint32_t)cached < state.cache_capacity) {
        if ((uint32_t)cached < scan_begin ||
            (uint32_t)cached >= scan_begin + scan_count) {
            cuda_nested_residual_note_cache_invariant_failure(state);
            state.failures++;
            return -1;
        }
        cuda_nested_residual_cache_slot &slot =
            state.cache_slots[(uint32_t)cached];
        if (slot.valid && slot.layer == layer_index && slot.expert == expert) {
            if (profile) {
                state.profile_lookup_seconds +=
                    cuda_wall_sec() - lookup_started;
            }
            slot.age = ++state.age;
            state.residual_cache_hits++;
            state.residual_cache_pread_bytes_avoided +=
                layer.residual_expert_bytes;
            *slot_out = (uint32_t)cached;
            return 1;
        }
        if (profile) {
            state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
        }
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.reconstruction_mismatches++;
        state.failures++;
        return -1;
    }

    uint32_t victim = UINT32_MAX;
    uint64_t oldest = UINT64_MAX;
    for (uint32_t offset = 0; offset < scan_count; offset++) {
        const uint32_t i = scan_begin + offset;
        const cuda_nested_residual_cache_slot &slot = state.cache_slots[i];
        if (!slot.valid) {
            victim = i;
            break;
        }
        if (slot.age < oldest) {
            oldest = slot.age;
            victim = i;
        }
    }
    if (victim == UINT32_MAX) {
        if (profile) {
            state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
        }
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.failures++;
        return -1;
    }
    if (profile) {
        state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
    }

    cuda_nested_residual_cache_slot &slot = state.cache_slots[victim];
    if (slot.copy_pending) {
        const double wait_started = profile ? cuda_wall_sec() : 0.0;
        const cudaError_t wait = cudaEventSynchronize(slot.reuse_event);
        if (profile) {
            state.profile_reuse_wait_calls++;
            state.profile_reuse_wait_seconds +=
                cuda_wall_sec() - wait_started;
        }
        if (wait != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual residual-cache reuse wait failed: %s\n",
                    cudaGetErrorString(wait));
            (void)cudaGetLastError();
            cuda_nested_residual_note_cache_invariant_failure(state);
            state.failures++;
            return -1;
        }
        slot.copy_pending = 0;
    }
    if (slot.valid) {
        if (state.cache_layer_partitioned && slot.layer != layer_index) {
            cuda_nested_residual_note_cache_invariant_failure(state);
            state.failures++;
            return -1;
        }
        const uint32_t old_index = slot.layer *
            CUDA_NESTED_RESIDUAL_EXPERT_COUNT + slot.expert;
        if (old_index < state.cache_by_layer_expert.size() &&
            state.cache_by_layer_expert[old_index] == (int32_t)victim) {
            state.cache_by_layer_expert[old_index] = -1;
        }
        slot.valid = 0;
        if (state.cache_count > 0) state.cache_count--;
        state.residual_cache_evictions++;
    }

    const uint64_t residual_offset = layer.residual_layer_start +
        (uint64_t)expert * layer.residual_expert_bytes;
    if (residual_offset > state.file_size ||
        layer.residual_expert_bytes > state.file_size - residual_offset) {
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.failures++;
        return -1;
    }
    uint8_t *destination = state.cache +
        (uint64_t)victim * state.cache_slot_bytes;
    const double pread_started = profile ? cuda_wall_sec() : 0.0;
    const int transport_repeat =
        ds4_transport_file_load_begin(layer_index, expert);
    const int pread_ok = cuda_pread_full(
        &state.file, destination, layer.residual_expert_bytes,
        residual_offset);
    if (profile) {
        state.profile_pread_calls++;
        state.profile_pread_seconds += cuda_wall_sec() - pread_started;
    }
    if (!pread_ok) {
        ds4_transport_mark_incomplete();
        state.failures++;
        return -1;
    }
    ds4_transport_record_file_bytes(
        transport_repeat, layer.residual_expert_bytes);
    state.residual_cache_misses++;
    state.residual_preads++;
    state.residual_bytes += layer.residual_expert_bytes;
    state.residual_cache_pread_bytes += layer.residual_expert_bytes;
    slot.layer = layer_index;
    slot.expert = expert;
    slot.age = ++state.age;
    slot.valid = 1;
    if (state.cache_count < state.cache_capacity) {
        state.cache_count++;
    }
    state.cache_by_layer_expert[map_index] = (int32_t)victim;
    *slot_out = victim;
    return 1;
}

static int cuda_nested_residual_join_to_device_exact(
        uint32_t layer_index, uint32_t expert,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        char *dst_gate, char *dst_up, char *dst_down,
        cudaStream_t stream) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (state.hard_failure) return -1;
    if (!cuda_nested_residual_gpu_join_requested()) return 0;
    state.gpu_join_observed = 1u;
    if (!state.active || !state.gpu_join_ready || !stream ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        !state.layers[layer_index].ready) {
        state.gpu_join_failures++;
        state.failures++;
        return -1;
    }
    if (expert >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT ||
        !dst_gate || !dst_up || !dst_down) {
        state.gpu_join_failures++;
        state.failures++;
        return -1;
    }
    cuda_nested_residual_layer &layer = state.layers[layer_index];
    const cuda_nested_residual_record &gate = layer.records[0];
    const cuda_nested_residual_record &up = layer.records[1];
    const cuda_nested_residual_record &down = layer.records[2];
    uint64_t residual_offset = 0;
    const uint8_t *expert_base = NULL;
    uint8_t base_pageable = 0;
    const uint8_t *residual_host_source = state.gpu_join_residual_host;
    uint32_t residual_cache_slot = UINT32_MAX;
    double join_started = 0.0;
    cudaError_t err = cudaSuccess;
    char *dst[CUDA_NESTED_RESIDUAL_PART_COUNT] = {
        dst_gate, dst_up, dst_down
    };
    if (gate.source_offset != gate_offset || up.source_offset != up_offset ||
        down.source_offset != down_offset ||
        gate.native_kind_bytes != gate_expert_bytes ||
        up.native_kind_bytes != gate_expert_bytes ||
        down.native_kind_bytes != down_expert_bytes ||
        layer.base_expert_bytes > state.gpu_join_base_device_bytes ||
        layer.residual_expert_bytes > state.gpu_join_residual_device_bytes ||
        layer.native_expert_bytes > state.gpu_join_verify_host_bytes) {
        fprintf(stderr,
                "ds4: nested residual GPU join geometry mismatch layer=%u\n",
                layer_index);
        state.gpu_join_failures++;
        state.failures++;
        return -1;
    }
    for (uint32_t part = 0; part < CUDA_NESTED_RESIDUAL_PART_COUNT; part++) {
        const cuda_nested_residual_record &record = layer.records[part];
        const uint64_t residual_kind_bytes =
            record.residual_bytes / record.nexperts;
        if ((record.source_type != 16u && record.source_type != 10u) ||
            record.residual_block_bytes != 32u ||
            record.base_kind_offset > layer.base_expert_bytes ||
            record.base_kind_bytes >
                layer.base_expert_bytes - record.base_kind_offset ||
            record.kind_offset > layer.residual_expert_bytes ||
            residual_kind_bytes >
                layer.residual_expert_bytes - record.kind_offset) {
            state.gpu_join_failures++;
            state.failures++;
            return -1;
        }
    }
    if (!state.gpu_join_mutex_ready || !state.gpu_join_event_created) {
        state.gpu_join_failures++;
        state.failures++;
        return -1;
    }
    os_mutex_lock(&state.gpu_join_mutex);
    int scratch_locked = 1;
    int stream_touched = 0;
    if (state.gpu_join_event_pending) {
        const double wait_started = cuda_wall_sec();
        const cudaError_t wait =
            cudaEventSynchronize(state.gpu_join_done_event);
        state.gpu_join_wait_calls++;
        state.gpu_join_wait_seconds += cuda_wall_sec() - wait_started;
        if (wait != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual GPU join scratch wait failed: %s\n",
                    cudaGetErrorString(wait));
            (void)cudaGetLastError();
            state.gpu_join_failures++;
            state.failures++;
            os_mutex_unlock(&state.gpu_join_mutex);
            return -1;
        }
        state.gpu_join_event_pending = 0u;
    }
    if (state.residual_cache_enabled) {
        if (cuda_nested_residual_resolve_residual_slot_locked(
                layer_index, expert, &residual_cache_slot) != 1) {
            state.gpu_join_failures++;
            goto fail_locked;
        }
        residual_host_source = state.cache +
            (uint64_t)residual_cache_slot * state.cache_slot_bytes;
    } else {
        residual_offset = layer.residual_layer_start +
            (uint64_t)expert * layer.residual_expert_bytes;
        if (residual_offset > state.file_size ||
            layer.residual_expert_bytes > state.file_size - residual_offset) {
            state.gpu_join_failures++;
            state.failures++;
            goto fail_locked;
        }
        if (!cuda_pread_full(&state.file, state.gpu_join_residual_host,
                             layer.residual_expert_bytes, residual_offset)) {
            state.gpu_join_failures++;
            state.failures++;
            goto fail_locked;
        }
        state.exact_cache_misses++;
        state.residual_preads++;
        state.residual_bytes += layer.residual_expert_bytes;
    }

    expert_base = cuda_nested_residual_base_expert(
        state, layer_index, expert, &base_pageable);
    if (!expert_base) {
        state.gpu_join_failures++;
        state.failures++;
        goto fail_locked;
    }
    join_started = cuda_wall_sec();
    err = cudaMemcpyAsync(
        state.gpu_join_base_device, expert_base,
        (size_t)layer.base_expert_bytes, cudaMemcpyHostToDevice, stream);
    if (err == cudaSuccess) stream_touched = 1;
    if (err == cudaSuccess) {
        err = cudaMemcpyAsync(
            state.gpu_join_residual_device, residual_host_source,
            (size_t)layer.residual_expert_bytes,
            cudaMemcpyHostToDevice, stream);
        if (err == cudaSuccess) stream_touched = 1;
    }
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: nested residual GPU join H2D failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        state.gpu_join_failures++;
        state.failures++;
        goto fail_locked;
    }
    state.gpu_join_base_h2d_bytes += layer.base_expert_bytes;
    state.gpu_join_residual_h2d_bytes += layer.residual_expert_bytes;
    if (base_pageable) {
        state.base_pageable_hits++;
        state.base_pageable_h2d_bytes += layer.base_expert_bytes;
    } else {
        state.base_pinned_hits++;
        state.base_pinned_h2d_bytes += layer.base_expert_bytes;
    }
    if (state.residual_cache_enabled) {
        state.residual_cache_h2d_bytes += layer.residual_expert_bytes;
        state.residual_cache_cached_join_calls++;
    }
    state.h2d_bytes +=
        layer.base_expert_bytes + layer.residual_expert_bytes;

    for (uint32_t part = 0; part < CUDA_NESTED_RESIDUAL_PART_COUNT; part++) {
        const cuda_nested_residual_record &record = layer.records[part];
        const uint64_t blocks = (record.ncols / 256u) * record.nrows;
        const uint32_t threads = 128u;
        const uint32_t grid = (uint32_t)((blocks + threads - 1u) / threads);
        cuda_nested_join_blocks_kernel<<<grid, threads, 0, stream>>>(
            record.source_type,
            state.gpu_join_base_device + record.base_kind_offset,
            state.gpu_join_residual_device + record.kind_offset,
            (uint8_t *)dst[part],
            blocks,
            record.base_block_bytes,
            record.residual_block_bytes,
            record.native_block_bytes);
        err = cudaGetLastError();
        if (err == cudaSuccess) stream_touched = 1;
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual GPU join launch failed: %s\n",
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            state.gpu_join_failures++;
            state.failures++;
            goto fail_locked;
        }
        state.gpu_join_blocks += blocks;
    }
    state.gpu_join_calls++;
    state.gpu_join_seconds += cuda_wall_sec() - join_started;
    state.reconstructed_experts++;

    if (getenv("DS4_NESTED_RESIDUAL_VERIFY_RECONSTRUCTION") != NULL) {
        const double verify_started = cuda_wall_sec();
        for (uint32_t part = 0; part < CUDA_NESTED_RESIDUAL_PART_COUNT;
             part++) {
            const cuda_nested_residual_record &record = layer.records[part];
            err = cudaMemcpyAsync(
                state.gpu_join_verify_host, dst[part],
                (size_t)record.native_kind_bytes,
                cudaMemcpyDeviceToHost, stream);
            if (err != cudaSuccess) {
                (void)cudaGetLastError();
                state.gpu_join_failures++;
                state.failures++;
                goto fail_locked;
            }
            err = cudaStreamSynchronize(stream);
            if (err != cudaSuccess) {
                (void)cudaGetLastError();
                state.gpu_join_failures++;
                state.failures++;
                goto fail_locked;
            }
            stream_touched = 0;
            const uint8_t *authoritative = state.source_map +
                record.source_offset +
                (uint64_t)expert * record.native_kind_bytes;
            state.gpu_join_verify_calls++;
            state.gpu_join_verify_bytes += record.native_kind_bytes;
            if (memcmp(state.gpu_join_verify_host, authoritative,
                       (size_t)record.native_kind_bytes) != 0) {
                state.gpu_join_verify_mismatches++;
                state.reconstruction_mismatches++;
                state.gpu_join_failures++;
                state.failures++;
                state.gpu_join_verify_seconds +=
                    cuda_wall_sec() - verify_started;
                goto fail_locked;
            }
        }
        state.gpu_join_verify_seconds += cuda_wall_sec() - verify_started;
    }
    err = cudaEventRecord(state.gpu_join_done_event, stream);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: nested residual GPU join completion event failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        state.gpu_join_failures++;
        state.failures++;
        goto fail_locked;
    }
    state.gpu_join_event_pending = 1u;
    os_mutex_unlock(&state.gpu_join_mutex);
    scratch_locked = 0;
    return 1;

fail_locked:
    if (stream_touched) (void)cudaStreamSynchronize(stream);
    if (scratch_locked) os_mutex_unlock(&state.gpu_join_mutex);
    return -1;
}

/* Resolve one covered expert to authoritative native bytes, then copy it into
 * the route worker's pinned host buffers. CUDA ownership remains with the
 * route worker so a successful GPU-cache hit never touches this path. */
static int cuda_nested_residual_fill_route_host_exact(
        uint32_t layer_index, uint32_t expert,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        char *host_gate, char *host_up, char *host_down) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (state.hard_failure) return -1;
    if (!state.active ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        !state.layers[layer_index].ready) {
        return 0;
    }
    if (expert >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT ||
        !host_gate || !host_up || !host_down) {
        state.failures++;
        state.gpu_cache_failures++;
        state.hard_failure = 1;
        return -1;
    }
    cuda_nested_residual_layer &layer = state.layers[layer_index];
    const cuda_nested_residual_record &gate = layer.records[0];
    const cuda_nested_residual_record &up = layer.records[1];
    const cuda_nested_residual_record &down = layer.records[2];
    if (gate.source_offset != gate_offset || up.source_offset != up_offset ||
        down.source_offset != down_offset ||
        gate.native_kind_bytes != gate_expert_bytes ||
        up.native_kind_bytes != gate_expert_bytes ||
        down.native_kind_bytes != down_expert_bytes) {
        fprintf(stderr,
                "ds4: nested residual GPU-cache geometry mismatch layer=%u\n",
                layer_index);
        state.failures++;
        state.gpu_cache_failures++;
        state.hard_failure = 1;
        return -1;
    }
    uint32_t cache_slot = 0;
    if (cuda_nested_residual_resolve_exact(
            layer_index, expert, &cache_slot) <= 0) {
        state.gpu_cache_failures++;
        state.hard_failure = 1;
        return -1;
    }
    const uint8_t *native = state.cache +
        (uint64_t)cache_slot * state.cache_slot_bytes;
    const double copy_started =
        state.profile_enabled ? cuda_wall_sec() : 0.0;
    memcpy(host_gate, native + gate.native_kind_offset,
           (size_t)gate_expert_bytes);
    memcpy(host_up, native + up.native_kind_offset,
           (size_t)gate_expert_bytes);
    memcpy(host_down, native + down.native_kind_offset,
           (size_t)down_expert_bytes);
    if (state.profile_enabled) {
        state.profile_host_copy_calls++;
        state.profile_host_copy_seconds += cuda_wall_sec() - copy_started;
    }
    const uint64_t native_bytes =
        gate_expert_bytes * 2ull + down_expert_bytes;
    state.route_host_fills++;
    state.route_host_bytes += native_bytes;
    return 1;
}

/* Returns 1 when the target layer was filled from nested exact bytes, 0 when
 * the layer is not covered, and -1 for a fail-closed covered-layer error. */
static int cuda_nested_residual_upload_exact(
        uint32_t layer_index,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        const std::vector<int32_t> &compact) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (state.hard_failure) return -1;
    if (!state.active ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        !state.layers[layer_index].ready) {
        return 0;
    }
    cuda_nested_residual_layer &layer = state.layers[layer_index];
    const cuda_nested_residual_record &gate = layer.records[0];
    const cuda_nested_residual_record &up = layer.records[1];
    const cuda_nested_residual_record &down = layer.records[2];
    if (gate.source_offset != gate_offset || up.source_offset != up_offset ||
        down.source_offset != down_offset ||
        gate.native_kind_bytes != gate_expert_bytes ||
        up.native_kind_bytes != gate_expert_bytes ||
        down.native_kind_bytes != down_expert_bytes) {
        fprintf(stderr,
                "ds4: nested residual runtime geometry mismatch layer=%u\n",
                layer_index);
        state.failures++;
        state.hard_failure = 1;
        return -1;
    }
    if (cuda_nested_residual_gpu_join_requested()) {
        for (uint32_t i = 0; i < compact.size(); i++) {
            const int32_t selected = compact[i];
            if (selected < 0 ||
                (uint32_t)selected >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT) {
                state.failures++;
                state.gpu_join_failures++;
                state.hard_failure = 1;
                return -1;
            }
            const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
            if (cuda_nested_residual_join_to_device_exact(
                    layer_index, (uint32_t)selected,
                    gate_offset, up_offset, down_offset,
                    gate_expert_bytes, down_expert_bytes,
                    g_moe_gather.gate + gate_dst,
                    g_moe_gather.up + gate_dst,
                    g_moe_gather.down + down_dst,
                    g_model_upload_stream) != 1) {
                state.hard_failure = 1;
                return -1;
            }
        }
        state.router_open_calls++;
        return 1;
    }
    for (uint32_t i = 0; i < compact.size(); i++) {
        const int32_t selected = compact[i];
        if (selected < 0 ||
            (uint32_t)selected >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT) {
            state.failures++;
            state.hard_failure = 1;
            return -1;
        }
        uint32_t cache_slot = 0;
        if (cuda_nested_residual_resolve_exact(
                layer_index, (uint32_t)selected, &cache_slot) <= 0) {
            state.hard_failure = 1;
            return -1;
        }
        const uint8_t *native = state.cache +
            (uint64_t)cache_slot * state.cache_slot_bytes;
        const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
        if (cudaMemcpyAsync(
                g_moe_gather.gate + gate_dst,
                native + gate.native_kind_offset,
                (size_t)gate_expert_bytes,
                cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess ||
            cudaMemcpyAsync(
                g_moe_gather.up + gate_dst,
                native + up.native_kind_offset,
                (size_t)gate_expert_bytes,
                cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess ||
            cudaMemcpyAsync(
                g_moe_gather.down + down_dst,
                native + down.native_kind_offset,
                (size_t)down_expert_bytes,
                cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess) {
            (void)cudaGetLastError();
            (void)cudaStreamSynchronize(g_model_upload_stream);
            state.failures++;
            state.hard_failure = 1;
            return -1;
        }
        cuda_nested_residual_cache_slot &slot =
            state.cache_slots[cache_slot];
        if (!slot.event_created) {
            const cudaError_t created = cudaEventCreateWithFlags(
                &slot.reuse_event, cudaEventDisableTiming);
            if (created != cudaSuccess) {
                fprintf(stderr,
                        "ds4: nested residual reuse event creation failed: %s\n",
                        cudaGetErrorString(created));
                (void)cudaGetLastError();
                (void)cudaStreamSynchronize(g_model_upload_stream);
                state.failures++;
                state.hard_failure = 1;
                return -1;
            }
            slot.event_created = 1;
        }
        const cudaError_t recorded = cudaEventRecord(
            slot.reuse_event, g_model_upload_stream);
        if (recorded != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual reuse event record failed: %s\n",
                    cudaGetErrorString(recorded));
            (void)cudaGetLastError();
            (void)cudaStreamSynchronize(g_model_upload_stream);
            state.failures++;
            state.hard_failure = 1;
            return -1;
        }
        slot.copy_pending = 1;
        state.h2d_bytes += gate_expert_bytes * 2u + down_expert_bytes;
    }
    state.router_open_calls++;
    return 1;
}

static int cuda_nested_residual_layer_required(uint32_t layer_index) {
    return g_nested_residual.active &&
        layer_index < CUDA_NESTED_RESIDUAL_LAYER_COUNT &&
        g_nested_residual.layers[layer_index].ready;
}

/* Returns 1 and populates g_moe_gather (compact gate/up/down + remapped slot tensor)
 * on success; 0 on any failure (caller falls back to the whole-256-block path). */
static int cuda_moe_selected_load(
        const void *model_map, uint64_t model_size,
        uint32_t layer_index,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        uint32_t expert_in_dim,
        uint32_t n_total_expert, uint32_t n_expert, uint32_t n_tokens,
        const ds4_gpu_tensor *selected_arg,
        const ds4_gpu_tensor *weights_arg,
        const ds4_gpu_tensor *probs_arg,
        ds4_gpu_spex_queue *spex_queue,
        const ds4_gpu_spex_key *spex_key,
        int allow_prefill_mixed_route_ptrs,
        double absolute_deadline) {
    g_moe_last_selected.valid = 0;
    g_moe_gather.direct_cache_active = 0;
    g_moe_gather.mixed_direct_active = 0;
    g_moe_gather.mixed_cache_routes = 0;
    g_moe_gather.mixed_compact_routes = 0;
    g_moe_gather.wave_active = 0;
    g_moe_gather.wave_fail_closed = 0;
    g_moe_gather.wave_count = 0;
    g_moe_gather.wave_index = 0;
    g_moe_gather.wave_max_experts = 0;
    g_moe_gather.wave_current_experts = 0;
    g_moe_gather.wave_active_pairs = 0;
    g_moe_gather.wave_unique_experts = 0;
    g_moe_gather.wave_source_span_bytes = 0;
    g_moe_gather.wave_arena_h2d_bytes = 0;
    g_moe_gather.wave_arena_experts = 0;
    g_moe_gather.wave_direct_experts = 0;
    g_moe_gather.wave_double_buffer = 0;
    for (uint32_t i = 0; i < 2u; i++) {
        g_moe_gather.wave_active_pairs_db[i] = 0;
        g_moe_gather.wave_current_experts_db[i] = 0;
    }
    const int route_prof = getenv("DS4_CUDA_MOE_ROUTE_PROFILE") != NULL;
    const int prefill_union_stats = n_tokens > 1u &&
        getenv("DS4_CUDA_PREFILL_UNION_STATS") != NULL;
    const double route_t0 = route_prof ? cuda_wall_sec() : 0.0;
    double route_t_d2h = route_t0;
    double route_t_observe = route_t0;
    double route_t_map = route_t0;
    double route_t_transport = route_t0;
    (void)model_size;
    if (n_total_expert == 0 || n_expert == 0 || n_tokens == 0) return 0;
    if (!selected_arg || !selected_arg->ptr) return 0;
    if (gate_expert_bytes == 0 || down_expert_bytes == 0) return 0;
    if (n_tokens > UINT32_MAX / n_expert) return 0;
    const uint32_t slot_count = n_tokens * n_expert;
    if (slot_count == 0) return 0;
    if (selected_arg->bytes < (uint64_t)slot_count * sizeof(int32_t)) return 0;
    const int iq1_mixed_host_prepared =
        g_iq1_mixed_host_selected.valid && slot_count == 1u &&
        g_iq1_mixed_host_selected.model_map == model_map &&
        g_iq1_mixed_host_selected.selected_ptr == selected_arg->ptr &&
        g_iq1_mixed_host_selected.gate_offset == gate_offset &&
        g_iq1_mixed_host_selected.up_offset == up_offset &&
        g_iq1_mixed_host_selected.down_offset == down_offset &&
        g_iq1_mixed_host_selected.gate_expert_bytes == gate_expert_bytes &&
        g_iq1_mixed_host_selected.down_expert_bytes == down_expert_bytes;
    const int32_t iq1_mixed_host_expert =
        g_iq1_mixed_host_selected.expert;
    const float iq1_mixed_host_weight =
        g_iq1_mixed_host_selected.weight;
    g_iq1_mixed_host_selected.valid = 0;
    const int prefill_mass_weights =
        cuda_prefill_mass_observer_needs_weights();
    const int compose_requested =
        cuda_moe_prefill_tier_compose_requested();
    const int full_q1_snapshot_requested =
        cuda_q1_0_snapshot_backing_requested();
    if (n_tokens == 1u &&
        (compose_requested > 0 || full_q1_snapshot_requested) &&
        g_prefill_mass_observer.enabled &&
        g_prefill_mass_observer.finalized &&
        !g_prefill_mass_observer.wrap_published) {
        fprintf(stderr,
                "ds4: [prefill-mass-compose] decode refused: closed snapshot publication failed\n");
        return 0;
    }
    const int prefill_mass_full_probs = prefill_mass_weights &&
        n_tokens > 1u &&
        (compose_requested > 0 || full_q1_snapshot_requested);
    const int reap_mass_requested = n_tokens == 1 &&
        cuda_reap_mass_observer_needs_weights() &&
        g_reap_router_trace_valid;
    const int weights_available = weights_arg && weights_arg->ptr &&
        weights_arg->bytes >= (uint64_t)slot_count * sizeof(float);
    const int reap_mass_weights = reap_mass_requested && weights_available;
    if (reap_mass_requested && !weights_available) {
        g_reap_router_trace_valid = 0;
    }
    const int layer_top1 =
        cuda_moe_expert_cache_requested() != 0 && cuda_moe_expert_cache_layer_top1();
    if (layer_top1 &&
        !weights_available) {
        return 0;
    }
    const int packed_reap_trace = reap_mass_weights && weights_available &&
        g_reap_router_trace_device && g_reap_router_trace_host;
    const int copy_weights =
        weights_available &&
        (layer_top1 || prefill_mass_weights ||
         (reap_mass_weights && !packed_reap_trace));
    const int host_weights_available =
        copy_weights || packed_reap_trace || iq1_mixed_host_prepared;
    const uint64_t full_prob_count =
        (uint64_t)n_tokens * n_total_expert;
    if (prefill_mass_full_probs &&
        (!probs_arg || !probs_arg->ptr ||
         probs_arg->bytes < full_prob_count * sizeof(float) ||
         full_prob_count > UINT32_MAX)) {
        fprintf(stderr,
                "ds4: [prefill-mass] full router probabilities unavailable; observer disabled\n");
        cuda_prefill_mass_observer_release(0);
        return 0;
    }

    const int prepared =
        g_moe_selected_prepared.valid &&
        g_moe_selected_prepared.model_map == model_map &&
        g_moe_selected_prepared.selected_ptr == selected_arg->ptr &&
        g_moe_selected_prepared.gate_offset == gate_offset &&
        g_moe_selected_prepared.up_offset == up_offset &&
        g_moe_selected_prepared.down_offset == down_offset &&
        g_moe_selected_prepared.gate_expert_bytes == gate_expert_bytes &&
        g_moe_selected_prepared.down_expert_bytes == down_expert_bytes &&
        g_moe_selected_prepared.n_expert == n_expert &&
        g_moe_selected_prepared.n_tokens == n_tokens;
    g_moe_selected_prepared.valid = 0;
    if (prepared && g_moe_selected_prepared.full) {
        static int full_overlap_notice_printed = 0;
        if (!full_overlap_notice_printed) {
            fprintf(stderr, "ds4: CUDA MoE full shared-overlap consumed\n");
            full_overlap_notice_printed = 1;
        }
    } else if (prepared) {
        static int overlap_notice_printed = 0;
        if (!overlap_notice_printed) {
            fprintf(stderr, "ds4: CUDA MoE shared-overlap consumed\n");
            overlap_notice_printed = 1;
        }
    }

    /* 1. Router outputs -> host. Layer-top1 also consumes the selected weights
     * to choose residency; selection itself remains unchanged. */
    if (iq1_mixed_host_prepared) {
        if (iq1_mixed_host_expert < 0 ||
            (uint32_t)iq1_mixed_host_expert >= n_total_expert) {
            return 0;
        }
        g_moe_gather.h_sel.assign(1u, iq1_mixed_host_expert);
        g_moe_gather.h_weights.assign(1u, iq1_mixed_host_weight);
    } else if (prepared) {
        if (g_moe_gather.h_sel.size() != slot_count) return 0;
        if (packed_reap_trace) {
            g_moe_gather.h_weights.resize(slot_count);
            g_reap_router_trace_valid = 0;
            if (!cuda_ok(cudaMemcpy(
                    g_reap_router_trace_host, g_reap_router_trace_device,
                    sizeof(*g_reap_router_trace_host),
                    cudaMemcpyDeviceToHost), "moe packed router trace D2H")) {
                return 0;
            }
            memcpy(g_moe_gather.h_weights.data(),
                   g_reap_router_trace_host->weights,
                   (size_t)slot_count * sizeof(float));
        } else if (copy_weights) {
            g_moe_gather.h_weights.resize(slot_count);
            if (!cuda_ok(cudaMemcpy(
                    g_moe_gather.h_weights.data(), weights_arg->ptr,
                    (size_t)slot_count * sizeof(float),
                    cudaMemcpyDeviceToHost), "moe weights D2H")) {
                return 0;
            }
        }
    } else if (packed_reap_trace) {
        g_moe_gather.h_sel.resize(slot_count);
        g_moe_gather.h_weights.resize(slot_count);
        g_reap_router_trace_valid = 0;
        if (!cuda_ok(cudaMemcpy(
                g_reap_router_trace_host, g_reap_router_trace_device,
                sizeof(*g_reap_router_trace_host),
                cudaMemcpyDeviceToHost), "moe packed router trace D2H")) {
            return 0;
        }
        memcpy(g_moe_gather.h_sel.data(),
               g_reap_router_trace_host->selected,
               (size_t)slot_count * sizeof(int32_t));
        memcpy(g_moe_gather.h_weights.data(),
               g_reap_router_trace_host->weights,
               (size_t)slot_count * sizeof(float));
    } else if (copy_weights) {
        g_moe_gather.h_sel.resize(slot_count);
        g_moe_gather.h_weights.resize(slot_count);
        if (!cuda_ok(cudaMemcpyAsync(g_moe_gather.h_sel.data(), selected_arg->ptr,
                                     (size_t)slot_count * sizeof(int32_t),
                                     cudaMemcpyDeviceToHost, 0), "moe selected D2H enqueue") ||
            !cuda_ok(cudaMemcpyAsync(g_moe_gather.h_weights.data(), weights_arg->ptr,
                                     (size_t)slot_count * sizeof(float),
                                     cudaMemcpyDeviceToHost, 0), "moe weights D2H enqueue") ||
            !cuda_ok(cuda_g73_finish_launched_copy(
                         0, absolute_deadline, layer_index,
                         "selected-router-d2h"),
                     "moe router D2H deadline poll")) return 0;
    } else {
        g_moe_gather.h_sel.resize(slot_count);
        if (!cuda_ok(cudaMemcpy(g_moe_gather.h_sel.data(), selected_arg->ptr,
                                (size_t)slot_count * sizeof(int32_t),
                                cudaMemcpyDeviceToHost), "moe selected D2H")) return 0;
    }
    if (prefill_mass_full_probs) {
        g_moe_gather.h_probs.resize((size_t)full_prob_count);
        if (!cuda_ok(cudaMemcpy(
                g_moe_gather.h_probs.data(), probs_arg->ptr,
                (size_t)full_prob_count * sizeof(float),
                cudaMemcpyDeviceToHost), "moe full router probabilities D2H")) {
            return 0;
        }
    }
    if (!cuda_sparse_bake_validate_selected(
            layer_index, g_moe_gather.h_sel.data(), slot_count,
            "routed selection", 0u)) {
        return 0;
    }
    if (route_prof) route_t_d2h = cuda_wall_sec();

    cuda_prefill_mass_observe_selected(
        layer_index, n_tokens, g_moe_gather.h_sel.data(),
        host_weights_available ? g_moe_gather.h_weights.data() : NULL,
        slot_count,
        prefill_mass_full_probs ? g_moe_gather.h_probs.data() : NULL,
        prefill_mass_full_probs ? (uint32_t)full_prob_count : 0u);
    if (reap_mass_weights) {
        cuda_reap_mass_observe_selected(
            layer_index, n_tokens, g_moe_gather.h_sel.data(),
            g_moe_gather.h_weights.data(), slot_count);
    }

    /* Residency learning consumes the exact selected ids already required by
     * execution. It does not change router scores, top-k, or the active mask. */
    cuda_dynamic_arena_observe_selected(
        layer_index, n_tokens, g_moe_gather.h_sel.data(), slot_count);
    if (route_prof) route_t_observe = cuda_wall_sec();

    /* 2. dedupe -> compact ids (ascending expert order) + per-slot remap */
    std::vector<int32_t> &e2s = g_moe_gather.h_expert_to_slot;
    e2s.assign(n_total_expert, -1);
    std::vector<int32_t> &compact = g_moe_gather.h_compact_ids; compact.clear();
    std::vector<int32_t> &slots = g_moe_gather.h_slot_ids; slots.resize(slot_count);
    for (uint32_t i = 0; i < slot_count; i++) {
        const int32_t e = g_moe_gather.h_sel[i];
        if (e < 0 || (uint32_t)e >= n_total_expert) return 0;
        e2s[(uint32_t)e] = -2;
    }
    for (uint32_t e = 0; e < n_total_expert; e++) {
        if (e2s[e] != -2) continue;
        e2s[e] = (int32_t)compact.size();
        compact.push_back((int32_t)e);
    }
    for (uint32_t i = 0; i < slot_count; i++)
        slots[i] = e2s[(uint32_t)g_moe_gather.h_sel[i]];
    const uint32_t compact_count = (uint32_t)compact.size();
    if (compact_count == 0 || compact_count > n_total_expert) return 0;
    if (route_prof) route_t_map = cuda_wall_sec();

    if (cuda_prefill_waves_requested() && n_tokens > 1u) {
        if (cuda_prefill_wave_debug_dump_active()) {
            g_moe_gather.wave_fail_closed = 1;
            fprintf(stderr,
                    "ds4: [prefill-waves] refused reason=debug-dump-active layer=%u tokens=%u compact=%u\n",
                    layer_index, n_tokens, compact_count);
            return 0;
        }
        const int double_buffer_requested =
            cuda_prefill_wave_double_buffer_requested();
        if (double_buffer_requested < 0) {
            g_moe_gather.wave_fail_closed = 1;
            return 0;
        }
        uint32_t max_wave_experts = cuda_prefill_wave_force_experts();
        if (max_wave_experts == UINT32_MAX) {
            g_moe_gather.wave_fail_closed = 1;
            return 0;
        }
        if (max_wave_experts == 0) {
            const uint32_t budget_experts =
                cuda_prefill_wave_budget_experts(gate_expert_bytes,
                                                 down_expert_bytes,
                                                 double_buffer_requested > 0);
            if (budget_experts != 0 && compact_count > budget_experts) {
                max_wave_experts = budget_experts;
            }
        }
        if (max_wave_experts != 0 && max_wave_experts < compact_count) {
            g_moe_gather.wave_active = 1;
            g_moe_gather.wave_fail_closed = 1;
            g_moe_gather.wave_double_buffer =
                double_buffer_requested > 0 ? 1u : 0u;
            g_moe_gather.wave_max_experts = max_wave_experts;
            g_moe_gather.wave_count =
                (compact_count + max_wave_experts - 1u) / max_wave_experts;
            g_moe_gather.wave_unique_experts = compact_count;
            if (!cuda_moe_selected_stage_wave(
                    model_map, layer_index,
                    gate_offset, up_offset, down_offset,
                    gate_expert_bytes, down_expert_bytes,
                    n_total_expert, n_expert, n_tokens, 0u)) {
                if (g_moe_gather.wave_double_buffer) {
                    g_prefill_wave_overlap_stats.failures =
                        cuda_u64_saturating_add(
                            g_prefill_wave_overlap_stats.failures, 1);
                }
                return 0;
            }
            g_prefill_wave_stats.activations = cuda_u64_saturating_add(
                g_prefill_wave_stats.activations, 1);
            g_prefill_wave_stats.unique_experts = cuda_u64_saturating_add(
                g_prefill_wave_stats.unique_experts, compact_count);
            if (max_wave_experts > g_prefill_wave_stats.max_wave) {
                g_prefill_wave_stats.max_wave = max_wave_experts;
            }
            if (g_moe_gather.wave_double_buffer) {
                g_prefill_wave_overlap_stats.activations =
                    cuda_u64_saturating_add(
                        g_prefill_wave_overlap_stats.activations, 1);
            }
            if (route_prof) {
                route_t_transport = cuda_wall_sec();
                const double route_t_publish = cuda_wall_sec();
                g_route_prof_calls++;
                g_route_prof_d2h_s += route_t_d2h - route_t0;
                g_route_prof_observe_s += route_t_observe - route_t_d2h;
                g_route_prof_map_s += route_t_map - route_t_observe;
                g_route_prof_transport_s += route_t_transport - route_t_map;
                g_route_prof_publish_s += route_t_publish - route_t_transport;
            }
            return 1;
        }
    }

    /* 3. compact device buffers (grow-only, reused across layers/tokens) */
    const uint64_t cgate = (uint64_t)compact_count * gate_expert_bytes;
    const uint64_t cdown = (uint64_t)compact_count * down_expert_bytes;
    const int slot_will_grow = !g_moe_gather.slot ||
        g_moe_gather.slot_cap < (uint64_t)slot_count * sizeof(int32_t);
    const int iq1_sidecar_route = g_iq1_s_sidecar_file_valid &&
        model_map == g_iq1_s_sidecar_host_base;
    const int iq1_vram_cache_state = iq1_sidecar_route ?
        cuda_iq1_s_vram_cache_prepare(
            gate_expert_bytes, down_expert_bytes) : 0;
    if (iq1_vram_cache_state < 0 ||
        (iq1_vram_cache_state > 0 && compact_count != 1u)) {
        return 0;
    }
    const int iq1_vram_cache_active = iq1_vram_cache_state > 0;
    const int iq1_packed_h2d = !iq1_vram_cache_active &&
        compact_count == 1u && iq1_sidecar_route &&
        getenv("DS4_IQ1_S_PACKED_H2D") != NULL;
    const uint64_t iq1_packed_bytes = cgate * 2ull + cdown;
    if ((!iq1_vram_cache_active && iq1_packed_h2d &&
         !cuda_moe_gather_ensure(&g_moe_gather.iq1_packed,
                                 &g_moe_gather.iq1_packed_cap,
                                 iq1_packed_bytes,
                                 "moe IQ1_S packed gather")) ||
        (!iq1_vram_cache_active && !iq1_packed_h2d &&
         (!cuda_moe_gather_ensure(&g_moe_gather.gate, &g_moe_gather.gate_cap, cgate, "moe gather gate") ||
          !cuda_moe_gather_ensure(&g_moe_gather.up,   &g_moe_gather.up_cap,   cgate, "moe gather up") ||
          !cuda_moe_gather_ensure(&g_moe_gather.down, &g_moe_gather.down_cap, cdown, "moe gather down"))) ||
        !cuda_moe_gather_ensure_i32(&g_moe_gather.slot, &g_moe_gather.slot_cap, slot_count, "moe gather slots"))
        return 0;
    if (slot_will_grow) g_moe_gather.iq1_slot_zero_valid = 0;
    g_moe_gather.iq1_active_gate = NULL;
    g_moe_gather.iq1_active_up = NULL;
    g_moe_gather.iq1_active_down = NULL;

    /* Dynamic-arena hits go straight from their stable pinned slot to the
     * compact execution buffers. They never enter the legacy pread/staging
     * list and never take a detour through the persistent VRAM cache. */
    std::vector<uint8_t> &arena_resident = g_moe_gather.h_arena_resident;
    arena_resident.assign(compact_count, 0);
    const int nested_exact = cuda_nested_residual_upload_exact(
        layer_index,
        gate_offset, up_offset, down_offset,
        gate_expert_bytes, down_expert_bytes,
        compact);
    if (nested_exact < 0) {
        g_moe_gather.wave_fail_closed = 1;
        return 0;
    }
    if (nested_exact > 0) {
        std::fill(arena_resident.begin(), arena_resident.end(), 1u);
    }
    const int arena_active = nested_exact == 0 && g_dynamic_arena.host_base &&
        g_dynamic_arena.snapshot_generation != 0 &&
        !g_dynamic_arena.hits_disabled &&
        !g_dynamic_arena.submissions_blocked;
    if (arena_active) {
        for (uint32_t i = 0; i < compact_count; i++) {
            const uint32_t expert = (uint32_t)compact[i];
            const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
            const cuda_dynamic_arena_copy_status arena_status =
                cuda_dynamic_arena_copy_expert_async(
                    g_dynamic_arena,
                    model_map, layer_index, expert,
                    gate_offset, up_offset, down_offset,
                    g_moe_gather.gate + gate_dst,
                    g_moe_gather.up + gate_dst,
                    g_moe_gather.down + down_dst,
                    gate_expert_bytes, gate_expert_bytes,
                    down_expert_bytes);
            if (arena_status == CUDA_DYNAMIC_ARENA_FATAL) {
                (void)cuda_g73_finish_launched_copy(
                    g_model_upload_stream, absolute_deadline, layer_index,
                    "selected-arena-error-cleanup");
                return 0;
            }
            arena_resident[i] =
                arena_status == CUDA_DYNAMIC_ARENA_ENQUEUED ? 1u : 0u;
        }
    }

    std::vector<uint8_t> &iq1_ram_resident =
        g_moe_gather.h_iq1_ram_resident;
    iq1_ram_resident.assign(compact_count, 0);
    const int iq1_profile = getenv("DS4_IQ1_S_PROFILE") != NULL;
    const double iq1_enqueue_t0 = iq1_profile ? cuda_wall_sec() : 0.0;
    uint32_t iq1_upload_experts = 0;
    int iq1_vram_pending_slot = -1;
    int iq1_vram_pending_new = 0;
    if (iq1_sidecar_route) {
        for (uint32_t i = 0; i < compact_count; i++) {
            const uint32_t expert = (uint32_t)compact[i];
            char *iq1_vram_base = NULL;
            if (iq1_vram_cache_active) {
                int vram_hit = 0;
                int vram_evicted = 0;
                const int vram_slot = cuda_iq1_s_vram_cache_resolve_slot(
                    layer_index, expert, &vram_hit, &vram_evicted);
                if (vram_slot < 0) return 0;
                iq1_vram_base = cuda_iq1_s_vram_cache_slot_base(
                    (uint32_t)vram_slot);
                if (!iq1_vram_base) return 0;
                g_moe_gather.iq1_active_gate = iq1_vram_base;
                g_moe_gather.iq1_active_up =
                    iq1_vram_base + gate_expert_bytes;
                g_moe_gather.iq1_active_down =
                    iq1_vram_base + gate_expert_bytes * 2ull;
                iq1_ram_resident[i] = 1u;
                if (vram_hit) continue;
                iq1_vram_pending_slot = vram_slot;
                iq1_vram_pending_new = !vram_evicted;
            }
            const uint64_t gate_src = gate_offset +
                (uint64_t)expert * gate_expert_bytes;
            const uint64_t up_src = up_offset +
                (uint64_t)expert * gate_expert_bytes;
            const uint64_t down_src = down_offset +
                (uint64_t)expert * down_expert_bytes;
            const char *gate_host = NULL;
            const char *up_host = NULL;
            const char *down_host = NULL;
            const int resolved = cuda_iq1_s_ram_cache_resolve(
                layer_index, expert, gate_src, up_src, down_src,
                gate_expert_bytes, down_expert_bytes,
                &gate_host, &up_host, &down_host);
            if (resolved < 0) return 0;
            if (resolved == 0) {
                if (iq1_vram_cache_active) {
                    g_iq1_s_vram_cache.failures++;
                    return 0;
                }
                break;
            }
            const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
            const int single_copy_h2d = iq1_vram_cache_active ||
                iq1_packed_h2d;
            if (single_copy_h2d &&
                (up_host != gate_host + gate_expert_bytes ||
                 down_host != gate_host + gate_expert_bytes * 2ull)) {
                g_iq1_s_ram_cache.failures++;
                return 0;
            }
            char *single_copy_destination = iq1_vram_cache_active ?
                iq1_vram_base : g_moe_gather.iq1_packed;
            const int copy_ok = single_copy_h2d ?
                cudaMemcpyAsync(
                    single_copy_destination, gate_host,
                    (size_t)iq1_packed_bytes, cudaMemcpyHostToDevice,
                    g_model_upload_stream) == cudaSuccess :
                (cudaMemcpyAsync(
                     g_moe_gather.gate + gate_dst, gate_host,
                     (size_t)gate_expert_bytes, cudaMemcpyHostToDevice,
                     g_model_upload_stream) == cudaSuccess &&
                 cudaMemcpyAsync(
                     g_moe_gather.up + gate_dst, up_host,
                     (size_t)gate_expert_bytes, cudaMemcpyHostToDevice,
                     g_model_upload_stream) == cudaSuccess &&
                 cudaMemcpyAsync(
                     g_moe_gather.down + down_dst, down_host,
                     (size_t)down_expert_bytes, cudaMemcpyHostToDevice,
                     g_model_upload_stream) == cudaSuccess);
            if (!copy_ok) {
                (void)cudaGetLastError();
                g_iq1_s_ram_cache.failures++;
                if (iq1_vram_cache_active)
                    g_iq1_s_vram_cache.failures++;
                return 0;
            }
            g_iq1_s_ram_cache.h2d_copies += single_copy_h2d ? 1u : 3u;
            iq1_ram_resident[i] = 1u;
            iq1_upload_experts++;
            g_iq1_s_ram_cache.h2d_bytes +=
                gate_expert_bytes * 2ull + down_expert_bytes;
            if (iq1_vram_cache_active) {
                g_iq1_s_vram_cache.h2d_bytes +=
                    gate_expert_bytes * 2ull + down_expert_bytes;
            } else if (iq1_packed_h2d) {
                g_moe_gather.iq1_active_gate = g_moe_gather.iq1_packed;
                g_moe_gather.iq1_active_up =
                    g_moe_gather.iq1_packed + gate_expert_bytes;
                g_moe_gather.iq1_active_down =
                    g_moe_gather.iq1_packed + gate_expert_bytes * 2ull;
            }
        }
    }
    if (iq1_profile && iq1_upload_experts != 0) {
        g_iq1_s_ram_cache.h2d_batches++;
        g_iq1_s_ram_cache.h2d_enqueue_seconds +=
            cuda_wall_sec() - iq1_enqueue_t0;
    }

    int spex_prefetch_slot = -1;
    uint32_t spex_prediction_slot = 0;
    uint32_t spex_compact_slot = UINT32_MAX;
    if (spex_queue && spex_key && cuda_moe_expert_cache_requested() == 0) {
        (void)cuda_spex_prefetch_claim(
            spex_queue, spex_key,
            gate_offset, up_offset, down_offset,
            compact,
            &spex_prefetch_slot,
            &spex_prediction_slot,
            &spex_compact_slot);
        if (spex_prefetch_slot >= 0 &&
            spex_compact_slot < arena_resident.size() &&
            arena_resident[spex_compact_slot]) {
            cuda_spex_prefetch_release(
                spex_queue, spex_prefetch_slot, 1, 0);
            spex_prefetch_slot = -1;
            spex_compact_slot = UINT32_MAX;
        }
    }

    /* 4. Resolve exact-byte resident hits, admit misses into persistent VRAM
     * slots when enabled, and stream overflow misses directly into compact
     * buffers. Cache policy changes residency only; router selection and the
     * compact slot map are unchanged. */
    const int prof = getenv("DS4_CUDA_SEL_PROFILE") != NULL;
    const double t_fetch0 = prof ? cuda_wall_sec() : 0.0;
    cuda_moe_expert_cache *cache = allow_prefill_mixed_route_ptrs ? NULL :
        cuda_moe_expert_cache_prepare(gate_expert_bytes, down_expert_bytes);
    /* P3 owns persistent residency. The generic selected-load path still
     * serves prefill exactly through compact buffers, but must not smuggle a
     * first-touch expert straight into the persistent VRAM cache. Decode uses
     * the fail-closed GPU route worker below. */
    if (cuda_moe_tiering_mode_requested() == CUDA_MOE_TIER_ENFORCE) {
        cache = NULL;
    }
    std::vector<cuda_moe_gather::span> &spans = g_moe_gather.h_spans;
    std::vector<int32_t> &cache_slots = g_moe_gather.h_cache_slots;
    std::vector<uint8_t> &claimed = g_moe_gather.h_cache_claimed;
    std::vector<uint32_t> &admission_compact = g_moe_gather.h_cache_admission_compact;
    std::vector<uint32_t> &admission_slots = g_moe_gather.h_cache_admission_slots;
    std::vector<uint8_t> &admission_evicted = g_moe_gather.h_cache_admission_evicted;
    spans.clear();
    spans.reserve((size_t)compact_count * 3u);
    cache_slots.assign(compact_count, -1);
    claimed.assign(cache ? cache->capacity : 0u, 0u);
    admission_compact.clear();
    admission_slots.clear();
    admission_evicted.clear();
    admission_compact.reserve(compact_count);
    admission_slots.reserve(compact_count);
    admission_evicted.reserve(compact_count);

    uint64_t local_hits = 0;
    uint64_t local_misses = 0;
    uint64_t local_evictions = 0;
    uint64_t local_direct = 0;
    int cache_map_dirty = 0;

    auto expert_key = [&](uint32_t compact_slot) {
        const uint64_t e = (uint64_t)(uint32_t)compact[compact_slot];
        return cuda_moe_cache_key{
            gate_offset + e * gate_expert_bytes,
            up_offset + e * gate_expert_bytes,
            down_offset + e * down_expert_bytes,
        };
    };
    auto append_span = [&](char *destination,
                           uint64_t source,
                           uint64_t bytes,
                           uint32_t expert,
                           uint8_t part) {
        uint32_t arena_entry = UINT32_MAX;
        char *mirror = cuda_dynamic_arena_observer_mirror_ptr(
            model_map, layer_index, expert, part, source, bytes,
            &arena_entry);
        spans.push_back({
            destination, source, bytes, mirror, arena_entry, part
        });
    };
    auto append_direct = [&](uint32_t compact_slot, const cuda_moe_cache_key &key) {
        const uint32_t expert = (uint32_t)compact[compact_slot];
        append_span(
            g_moe_gather.gate + (uint64_t)compact_slot * gate_expert_bytes,
            key.gate_src, gate_expert_bytes, expert,
            CUDA_DYNAMIC_ARENA_MIRROR_GATE);
        append_span(
            g_moe_gather.up + (uint64_t)compact_slot * gate_expert_bytes,
            key.up_src, gate_expert_bytes, expert,
            CUDA_DYNAMIC_ARENA_MIRROR_UP);
        append_span(
            g_moe_gather.down + (uint64_t)compact_slot * down_expert_bytes,
            key.down_src, down_expert_bytes, expert,
            CUDA_DYNAMIC_ARENA_MIRROR_DOWN);
        local_direct++;
    };
    auto append_admission = [&](uint32_t compact_slot, uint32_t cache_slot,
                                 const cuda_moe_cache_key &key) {
        cuda_moe_cache_slot &entry = cache->slots[cache_slot];
        const uint8_t evicted = entry.state == CUDA_MOE_CACHE_VALID ? 1u : 0u;
        if (evicted && entry.layer_index < CUDA_MOE_LAYER_COUNT &&
            entry.expert_id < 256u &&
            !cache->host_slot_by_layer_expert.empty()) {
            const uint32_t old_index = entry.layer_index * 256u + entry.expert_id;
            if (cache->host_slot_by_layer_expert[old_index] == (int32_t)cache_slot) {
                cache->host_slot_by_layer_expert[old_index] = -1;
            }
        }
        entry.state = CUDA_MOE_CACHE_LOADING;
        entry.key = key;
        entry.age = 0;
        entry.layer_index = layer_index;
        entry.expert_id = (uint32_t)compact[compact_slot];
        claimed[cache_slot] = 1;
        cache_slots[compact_slot] = (int32_t)cache_slot;
        admission_compact.push_back(compact_slot);
        admission_slots.push_back(cache_slot);
        admission_evicted.push_back(evicted);
        local_evictions += evicted;
        if (!cache->host_slot_by_layer_expert.empty()) {
            cache->host_slot_by_layer_expert[
                layer_index * 256u + entry.expert_id] = (int32_t)cache_slot;
            cache_map_dirty = 1;
        }
        const uint64_t gate_dst = (uint64_t)cache_slot * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)cache_slot * down_expert_bytes;
        const uint32_t expert = (uint32_t)compact[compact_slot];
        append_span(cache->gate + gate_dst, key.gate_src,
                    gate_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_GATE);
        append_span(cache->up + gate_dst, key.up_src,
                    gate_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_UP);
        append_span(cache->down + down_dst, key.down_src,
                    down_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_DOWN);
    };
    if (cache && layer_top1) {
        int layer_slot = -1;
        for (uint32_t i = 0; i < cache->capacity; i++) {
            if (cache->slots[i].layer_owned && cache->slots[i].layer_key == gate_offset) {
                layer_slot = (int)i;
                break;
            }
        }
        if (layer_slot < 0) {
            for (uint32_t i = 0; i < cache->capacity; i++) {
                if (cache->slots[i].layer_owned) continue;
                cache->slots[i].layer_owned = 1;
                cache->slots[i].layer_key = gate_offset;
                layer_slot = (int)i;
                break;
            }
        }

        if (layer_slot >= 0 && cache->slots[(uint32_t)layer_slot].state == CUDA_MOE_CACHE_VALID) {
            const cuda_moe_cache_key resident = cache->slots[(uint32_t)layer_slot].key;
            for (uint32_t i = 0; i < compact_count; i++) {
                if (arena_resident[i] || iq1_ram_resident[i]) continue;
                const cuda_moe_cache_key key = expert_key(i);
                if (key.gate_src == resident.gate_src &&
                    key.up_src == resident.up_src &&
                    key.down_src == resident.down_src) {
                    cache_slots[i] = layer_slot;
                    claimed[(uint32_t)layer_slot] = 1;
                    local_hits = 1;
                    break;
                }
            }
        }
        uint32_t cache_eligible = 0;
        for (uint32_t i = 0; i < compact_count; i++) {
            cache_eligible +=
                arena_resident[i] == 0 && iq1_ram_resident[i] == 0;
        }
        local_misses = cache_eligible - local_hits;

        if (layer_slot >= 0 && local_hits == 0) {
            std::vector<float> &mass = g_moe_gather.h_compact_mass;
            mass.assign(compact_count, 0.0f);
            for (uint32_t i = 0; i < slot_count; i++) {
                mass[(uint32_t)slots[i]] += g_moe_gather.h_weights[i];
            }
            uint32_t candidate = UINT32_MAX;
            for (uint32_t i = 0; i < compact_count; i++) {
                if (arena_resident[i] || iq1_ram_resident[i]) continue;
                if (candidate == UINT32_MAX || mass[i] > mass[candidate]) {
                    candidate = i;
                }
            }
            if (candidate != UINT32_MAX) {
                append_admission(candidate, (uint32_t)layer_slot,
                                 expert_key(candidate));
            }
        }
        for (uint32_t i = 0; i < compact_count; i++) {
            if (!arena_resident[i] && !iq1_ram_resident[i] &&
                cache_slots[i] < 0 &&
                i != spex_compact_slot) {
                append_direct(i, expert_key(i));
            }
        }
    } else {
        if (cache) {
            for (uint32_t i = 0; i < compact_count; i++) {
                if (arena_resident[i] || iq1_ram_resident[i]) continue;
                const cuda_moe_cache_key key = expert_key(i);
                const int slot = cuda_moe_expert_cache_find(cache, key);
                if (slot >= 0 && !claimed[(uint32_t)slot]) {
                    cache_slots[i] = slot;
                    claimed[(uint32_t)slot] = 1;
                    local_hits++;
                } else {
                    local_misses++;
                }
            }
        }

        for (uint32_t i = 0; i < compact_count; i++) {
            if (arena_resident[i] || iq1_ram_resident[i]) continue;
            if (cache_slots[i] >= 0) continue;
            if (i == spex_compact_slot) continue;
            const cuda_moe_cache_key key = expert_key(i);
            const int cache_slot = cache ? cuda_moe_expert_cache_lru_slot(cache, claimed) : -1;
            if (cache_slot >= 0) {
                append_admission(i, (uint32_t)cache_slot, key);
            } else {
                append_direct(i, key);
            }
        }
    }
    int fill_ok = 0;
    if (spex_prefetch_slot >= 0) {
        const uint64_t gate_dst = (uint64_t)spex_compact_slot * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)spex_compact_slot * down_expert_bytes;
        if (!cuda_spex_prefetch_copy_to_compact(
                spex_queue,
                (uint32_t)spex_prefetch_slot,
                spex_prediction_slot,
                g_moe_gather.gate + gate_dst,
                g_moe_gather.up + gate_dst,
                g_moe_gather.down + down_dst)) {
            (void)cudaGetLastError();
            const int fenced = cuda_g73_finish_launched_copy(
                g_model_upload_stream, absolute_deadline, layer_index,
                "selected-prefetch-cleanup") == cudaSuccess;
            cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, fenced, 0);
            if (cache) cuda_moe_expert_cache_invalidate("selected-spex-copy");
            return 0;
        }
    }
    if (absolute_deadline > 0.0) {
        fill_ok = 1;
        for (const cuda_moe_gather::span &s : spans) {
            if (!cuda_moe_fill_span_bounded(
                    s.dst, model_map, s.offset, s.bytes, s.mirror,
                    absolute_deadline)) {
                fill_ok = 0;
                break;
            }
            if (s.mirror) {
                cuda_dynamic_arena_observer_mirror_done(
                    s.arena_entry, s.arena_part, s.bytes);
            }
        }
    } else {
#ifdef _WIN32
        const uint32_t io_qd = cuda_moe_io_queue_depth();
        if (io_qd > 1u) {
        fill_ok = cuda_moe_fill_spans_overlapped(model_map, spans, io_qd);
        if (!fill_ok) {
            fprintf(stderr, "ds4: CUDA MoE overlapped read failed; selected-load fallback requested\n");
        }
        }
        else
#endif
        {
            fill_ok = 1;
            for (const cuda_moe_gather::span &s : spans) {
                if (!cuda_moe_fill_span(
                        s.dst, model_map, s.offset, s.bytes, s.mirror)) {
                    fill_ok = 0;
                    break;
                }
                if (s.mirror) {
                    cuda_dynamic_arena_observer_mirror_done(
                        s.arena_entry, s.arena_part, s.bytes);
                }
            }
        }
    }
    if (!fill_ok) {
        const int fenced = cuda_g73_finish_launched_copy(
            g_model_upload_stream, absolute_deadline, layer_index,
            "selected-fill-cleanup") == cudaSuccess;
        cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, fenced, 0);
        if (cache) cuda_moe_expert_cache_invalidate("selected-fill");
        return 0;
    }

    const int mixed_direct_active =
        getenv("DS4_CUDA_MOE_MIXED_DIRECT") != NULL &&
        (n_tokens == 1u || allow_prefill_mixed_route_ptrs) &&
        n_expert == 6u && cache &&
        expert_in_dim / CUDA_QK_K <= 16u &&
        spex_prefetch_slot < 0 &&
        getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") == NULL &&
        getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") == NULL;
    int direct_cache_active = 0;
    if (!mixed_direct_active &&
        getenv("DS4_CUDA_MOE_DIRECT_CACHE_HITS") != NULL &&
        n_tokens == 1u && cache && spex_prefetch_slot < 0 &&
        admission_slots.empty() && spans.empty()) {
        direct_cache_active = 1;
        for (uint32_t i = 0; i < compact_count; i++) {
            if (arena_resident[i] || iq1_ram_resident[i] ||
                cache_slots[i] < 0) {
                direct_cache_active = 0;
                break;
            }
        }
    }

    if (cache && !direct_cache_active && !mixed_direct_active) {
        for (uint32_t i = 0; i < compact_count; i++) {
            if (cache_slots[i] < 0) continue;
            if (!cuda_moe_expert_cache_copy_to_compact_async(
                    cache, (uint32_t)cache_slots[i], i)) {
                (void)cudaGetLastError();
                const int fenced = cuda_g73_finish_launched_copy(
                    g_model_upload_stream, absolute_deadline, layer_index,
                    "selected-cache-cleanup") == cudaSuccess;
                cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, fenced, 0);
                if (cache) cuda_moe_expert_cache_invalidate("selected-cache-copy");
                return 0;
            }
        }
    }

    int arena_upload_pending = 0;
    for (uint32_t i = 0; i < compact_count; i++) {
        if (arena_resident[i]) {
            arena_upload_pending = 1;
            break;
        }
    }
    arena_upload_pending |= iq1_upload_experts != 0;
    const int iq1_vram_all_hit = iq1_vram_cache_active &&
        iq1_upload_experts == 0 && g_moe_gather.iq1_active_gate != NULL;
    const int upload_sync_required =
        !iq1_vram_all_hit && !direct_cache_active &&
        (!mixed_direct_active || !spans.empty() ||
         spex_prefetch_slot >= 0 || arena_upload_pending);
    const double iq1_sync_t0 =
        iq1_profile && iq1_upload_experts != 0 ? cuda_wall_sec() : 0.0;
    if (upload_sync_required &&
        !cuda_ok(cuda_g73_finish_launched_copy(
                     g_model_upload_stream, absolute_deadline, layer_index,
                     "selected-compact-upload"),
                 "moe compact upload completion")) {
        if (iq1_vram_pending_slot >= 0)
            g_iq1_s_vram_cache.failures++;
        cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 0, 0);
        if (cache) cuda_moe_expert_cache_invalidate("selected-compact-upload");
        return 0;
    }
    if (iq1_profile && iq1_upload_experts != 0 && upload_sync_required) {
        g_iq1_s_ram_cache.h2d_syncs++;
            g_iq1_s_ram_cache.h2d_sync_seconds += cuda_wall_sec() - iq1_sync_t0;
    }
    if (iq1_vram_pending_slot >= 0) {
        cuda_iq1_s_vram_cache_slot &slot =
            g_iq1_s_vram_cache.slots[(uint32_t)iq1_vram_pending_slot];
        slot.valid = 1;
        if (iq1_vram_pending_new &&
            g_iq1_s_vram_cache.count < g_iq1_s_vram_cache.capacity) {
            g_iq1_s_vram_cache.count++;
        }
    }
    if (prefill_union_stats) {
        uint64_t arena_experts = 0;
        uint64_t cache_copies = 0;
        uint64_t iq1_ram_experts = 0;
        uint64_t source_span_bytes = 0;
        uint64_t expert_bytes = UINT64_MAX;
        for (uint8_t resident : arena_resident) arena_experts += resident != 0;
        for (uint8_t resident : iq1_ram_resident) {
            iq1_ram_experts += resident != 0;
        }
        for (int32_t cache_slot : cache_slots) cache_copies += cache_slot >= 0;
        for (const cuda_moe_gather::span &span : spans) {
            source_span_bytes = cuda_u64_saturating_add(source_span_bytes, span.bytes);
        }
        if (gate_expert_bytes <= (UINT64_MAX - down_expert_bytes) / 2ull) {
            expert_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
        }
        g_prefill_union_stats.calls =
            cuda_u64_saturating_add(g_prefill_union_stats.calls, 1);
        g_prefill_union_stats.tokens =
            cuda_u64_saturating_add(g_prefill_union_stats.tokens, n_tokens);
        g_prefill_union_stats.selected_slots =
            cuda_u64_saturating_add(g_prefill_union_stats.selected_slots, slot_count);
        g_prefill_union_stats.unique_experts =
            cuda_u64_saturating_add(g_prefill_union_stats.unique_experts, compact_count);
        g_prefill_union_stats.arena_experts =
            cuda_u64_saturating_add(g_prefill_union_stats.arena_experts, arena_experts);
        g_prefill_union_stats.cache_hit_experts =
            cuda_u64_saturating_add(g_prefill_union_stats.cache_hit_experts, local_hits);
        g_prefill_union_stats.cache_admitted_experts = cuda_u64_saturating_add(
            g_prefill_union_stats.cache_admitted_experts, admission_slots.size());
        g_prefill_union_stats.direct_experts =
            cuda_u64_saturating_add(g_prefill_union_stats.direct_experts, local_direct);
        g_prefill_union_stats.spex_experts = cuda_u64_saturating_add(
            g_prefill_union_stats.spex_experts, spex_prefetch_slot >= 0);
        g_prefill_union_stats.nonresident_experts = cuda_u64_saturating_add(
            g_prefill_union_stats.nonresident_experts,
            compact_count - arena_experts - iq1_ram_experts - local_hits);
        g_prefill_union_stats.source_span_bytes = cuda_u64_saturating_add(
            g_prefill_union_stats.source_span_bytes, source_span_bytes);
        g_prefill_union_stats.arena_h2d_bytes = cuda_u64_saturating_add(
            g_prefill_union_stats.arena_h2d_bytes,
            cuda_u64_saturating_mul(arena_experts, expert_bytes));
        g_prefill_union_stats.cache_d2d_bytes = cuda_u64_saturating_add(
            g_prefill_union_stats.cache_d2d_bytes,
            cuda_u64_saturating_mul(cache_copies, expert_bytes));
        g_prefill_union_stats.upload_syncs = cuda_u64_saturating_add(
            g_prefill_union_stats.upload_syncs, upload_sync_required != 0);
        if (n_tokens > g_prefill_union_stats.max_tokens) {
            g_prefill_union_stats.max_tokens = n_tokens;
        }
        if (compact_count > g_prefill_union_stats.max_union) {
            g_prefill_union_stats.max_union = compact_count;
        }
    }
    if (cache) {
        for (size_t i = 0; i < admission_slots.size(); i++) {
            cuda_moe_cache_slot &entry = cache->slots[admission_slots[i]];
            entry.state = CUDA_MOE_CACHE_VALID;
            if (!admission_evicted[i] && cache->count < cache->capacity) cache->count++;
        }
        for (int32_t slot : cache_slots) {
            if (slot >= 0) cache->slots[(uint32_t)slot].age = ++cache->tick;
        }
        if (cache_map_dirty && cache->device_slot_by_layer_expert &&
            cudaMemcpyAsync(cache->device_slot_by_layer_expert,
                            cache->host_slot_by_layer_expert.data(),
                            cache->host_slot_by_layer_expert.size() * sizeof(int32_t),
                            cudaMemcpyHostToDevice, 0) != cudaSuccess) {
            (void)cudaGetLastError();
            cuda_moe_expert_cache_invalidate("selected-map-upload");
            return 0;
        }
        cache->calls++;
        cache->hits += local_hits;
        cache->misses += local_misses;
        cache->admissions += admission_slots.size();
        cache->evictions += local_evictions;
        cache->direct_loads += local_direct;
        const uint64_t stats_interval = cuda_moe_expert_cache_stats_interval();
        if (stats_interval != 0 && cache->calls % stats_interval == 0u) {
            const uint64_t lookups = cache->hits + cache->misses;
            fprintf(stderr,
                    "ds4: [moecache] calls=%llu layer=%u compact=%u cap=%u count=%u hits=%llu misses=%llu hit_rate=%.3f admissions=%llu evictions=%llu direct=%llu\n",
                    (unsigned long long)cache->calls, layer_index, compact_count,
                    cache->capacity, cache->count,
                    (unsigned long long)cache->hits, (unsigned long long)cache->misses,
                    lookups ? (double)cache->hits / (double)lookups : 0.0,
                    (unsigned long long)cache->admissions,
                    (unsigned long long)cache->evictions,
                    (unsigned long long)cache->direct_loads);
        }
    }
    if (prof) {
        g_sel_prof_calls++;
        g_sel_prof_experts += compact_count;
        g_sel_prof_fetch_s += cuda_wall_sec() - t_fetch0;
        if (g_sel_prof_calls % 60u == 0u) {
            fprintf(stderr, "ds4: [selprof] calls=%llu experts=%llu fill=%.3fs (%.2f ms/expert)\n",
                    (unsigned long long)g_sel_prof_calls, (unsigned long long)g_sel_prof_experts,
                    g_sel_prof_fetch_s,
                    g_sel_prof_experts ? 1000.0 * g_sel_prof_fetch_s / (double)g_sel_prof_experts : 0.0);
        }
    }

    /* 5. Publish either compact slots or stable resident-cache slots. Pure
     * hits read the persistent quantized bytes in place. Any miss retains the
     * existing compact-buffer path and its synchronization. */
    if (direct_cache_active) {
        for (uint32_t i = 0; i < slot_count; i++) {
            const uint32_t compact_slot = (uint32_t)slots[i];
            slots[i] = cache_slots[compact_slot];
        }
        g_moe_gather.direct_cache_active = 1;
        if (getenv("DS4_CUDA_MOE_DIRECT_CACHE_STATS") != NULL) {
            fprintf(stderr,
                    "ds4: CUDA MoE direct resident-cache hit layer=%u slots=%u compact=%u\n",
                    layer_index, slot_count, compact_count);
        }
    }
    if (route_prof) route_t_transport = cuda_wall_sec();
    if (mixed_direct_active) {
        const uint64_t route_ptr_count = (uint64_t)slot_count * 3ull;
        const uint64_t route_ptr_bytes = route_ptr_count * sizeof(uint64_t);
        if (!cuda_moe_gather_ensure(
                (char **)&g_moe_gather.route_ptrs,
                &g_moe_gather.route_ptrs_cap,
                route_ptr_bytes,
                "moe mixed route pointers")) {
            cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 1, 0);
            return 0;
        }
        std::vector<uint64_t> &route_ptrs = g_moe_gather.h_route_ptrs;
        route_ptrs.resize((size_t)route_ptr_count);
        uint32_t cache_routes = 0;
        uint32_t compact_routes = 0;
        for (uint32_t i = 0; i < slot_count; i++) {
            const uint32_t compact_slot = (uint32_t)slots[i];
            const int32_t cache_slot = cache_slots[compact_slot];
            if (cache_slot >= 0) {
                const uint64_t gate_off = (uint64_t)(uint32_t)cache_slot * gate_expert_bytes;
                const uint64_t down_off = (uint64_t)(uint32_t)cache_slot * down_expert_bytes;
                route_ptrs[i] = (uint64_t)(uintptr_t)(cache->gate + gate_off);
                route_ptrs[slot_count + i] = (uint64_t)(uintptr_t)(cache->up + gate_off);
                route_ptrs[2u * slot_count + i] = (uint64_t)(uintptr_t)(cache->down + down_off);
                cache_routes++;
            } else {
                const uint64_t gate_off = (uint64_t)compact_slot * gate_expert_bytes;
                const uint64_t down_off = (uint64_t)compact_slot * down_expert_bytes;
                route_ptrs[i] = (uint64_t)(uintptr_t)(g_moe_gather.gate + gate_off);
                route_ptrs[slot_count + i] = (uint64_t)(uintptr_t)(g_moe_gather.up + gate_off);
                route_ptrs[2u * slot_count + i] = (uint64_t)(uintptr_t)(g_moe_gather.down + down_off);
                compact_routes++;
            }
        }
        if (!cuda_ok(cudaMemcpy(
                g_moe_gather.route_ptrs, route_ptrs.data(),
                (size_t)route_ptr_bytes, cudaMemcpyHostToDevice),
                "moe mixed route pointers")) {
            cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 1, 0);
            return 0;
        }
        g_moe_gather.mixed_direct_active = 1;
        g_moe_gather.mixed_cache_routes = cache_routes;
        g_moe_gather.mixed_compact_routes = compact_routes;
        if (getenv("DS4_CUDA_MOE_MIXED_DIRECT_STATS") != NULL) {
            fprintf(stderr,
                    "ds4: CUDA MoE mixed direct layer=%u cache_routes=%u compact_routes=%u\n",
                    layer_index, cache_routes, compact_routes);
        }
    }
    const int slot_is_zero = slot_count == 1u && slots[0] == 0;
    if (!(iq1_vram_all_hit && slot_is_zero &&
          g_moe_gather.iq1_slot_zero_valid)) {
        if (!cuda_ok(cudaMemcpy(g_moe_gather.slot, slots.data(),
                                (size_t)slot_count * sizeof(int32_t),
                                cudaMemcpyHostToDevice), "moe gather slots")) {
            cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 1, 0);
            return 0;
        }
        g_moe_gather.iq1_slot_zero_valid = slot_is_zero ? 1u : 0u;
    }
    g_moe_gather.slot_tensor.ptr = g_moe_gather.slot;
    g_moe_gather.slot_tensor.bytes = (uint64_t)slot_count * sizeof(int32_t);
    g_moe_gather.slot_tensor.owner = 0;

    if (route_prof) {
        const double route_t_publish = cuda_wall_sec();
        g_route_prof_calls++;
        g_route_prof_d2h_s += route_t_d2h - route_t0;
        g_route_prof_observe_s += route_t_observe - route_t_d2h;
        g_route_prof_map_s += route_t_map - route_t_observe;
        g_route_prof_transport_s += route_t_transport - route_t_map;
        g_route_prof_publish_s += route_t_publish - route_t_transport;
        if (g_route_prof_calls % 60u == 0u) {
            const double scale = 1000.0 / (double)g_route_prof_calls;
            fprintf(stderr,
                    "ds4: [routeprof] calls=%llu d2h=%.3fms observe=%.3fms map=%.3fms transport=%.3fms publish=%.3fms\n",
                    (unsigned long long)g_route_prof_calls,
                    g_route_prof_d2h_s * scale,
                    g_route_prof_observe_s * scale,
                    g_route_prof_map_s * scale,
                    g_route_prof_transport_s * scale,
                    g_route_prof_publish_s * scale);
        }
    }

    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA MoE selected-load slots=%u compact=%u gate/up %.2f MiB down %.2f MiB\n",
                slot_count, compact_count,
                (double)cgate / 1048576.0, (double)cdown / 1048576.0);
    }
    g_moe_last_selected.gate_offset = gate_offset;
    g_moe_last_selected.count = compact_count;
    memcpy(g_moe_last_selected.ids, compact.data(),
           (size_t)compact_count * sizeof(g_moe_last_selected.ids[0]));
    g_moe_last_selected.valid = 1;
    cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 1, 1);
    return 1;
}

static int cuda_g73_contract_error(uint32_t layer, const char *reason) {
    fprintf(stderr,
            "ds4: [g73-open] contract error layer=%u reason=%s\n",
            layer, reason ? reason : "unknown");
    return 0;
}

static void cuda_g73_device_error(
        uint32_t layer, const char *reason,
        cudaError_t error = cudaSuccess) {
    fprintf(stderr,
            "ds4: [g73-open] CUDA DEVICE ERROR layer=%u reason=%s cuda=%s\n",
            layer, reason ? reason : "unknown",
            error == cudaSuccess ? "not-captured" :
                cudaGetErrorString(error));
    abort();
}

static int cuda_g73_classify_fallback(
        uint32_t layer, const int32_t *selected, uint32_t route_count,
        int terminal, cuda_g73_route_outcomes *outcomes) {
    if (!selected || !outcomes) {
        return cuda_g73_contract_error(layer, "classification");
    }
    *outcomes = cuda_g73_route_outcomes{};
    for (uint32_t route = 0; route < route_count; route++) {
        const int32_t expert_i = selected[route];
        if (expert_i < 0 || expert_i >= 256) {
            return cuda_g73_contract_error(layer, "selected-expert-range");
        }
        char *gate = NULL;
        char *up = NULL;
        char *down = NULL;
        if (cuda_moe_tiering_snapshot_ram_ptrs(
                layer, (uint32_t)expert_i, &gate, &up, &down)) {
            continue;
        }
        outcomes->out_of_mask_routes++;
        if (terminal) outcomes->served_terminal_exact++;
        else outcomes->served_selected_fallback++;
    }
    return 1;
}

static int cuda_g73_terminal_read_part(
        char *destination, uint64_t bytes, uint64_t offset,
        double absolute_deadline, uint32_t layer, uint32_t expert,
        const char *part) {
    cuda_g73_terminal_state &terminal = g_cuda_g73_terminal;
    const uint64_t max_chunk = 1024u * 1024u;
    uint64_t done = 0u;
    int overrun_logged = 0;
    while (done < bytes) {
        /* The terminal is the completing last resort: the deadline is observed
         * only between independent <=1 MiB synchronous reads (one-chunk overrun,
         * about 1 ms at expected NVMe rates), never by refusing or cancelling. */
        if (!overrun_logged && absolute_deadline > 0.0 &&
            cuda_wall_sec() >= absolute_deadline) {
            fprintf(stderr,
                    "ds4: [g73-open] budget_overrun layer=%u expert=%u "
                    "phase=terminal-plain-pread part=%s action=complete\n",
                    layer, expert, part ? part : "unknown");
            overrun_logged = 1;
        }
        const uint64_t remaining = bytes - done;
        const uint64_t chunk = std::min(remaining, max_chunk);
        const int64_t got = os_pread_plain(
            &terminal.file, destination + done, chunk, offset + done);
        if (got <= 0) return 0;
        done += (uint64_t)got;
    }
    return 1;
}

struct cuda_g73_terminal_mutex_guard {
    cuda_g73_terminal_state *terminal;
    cuda_g73_terminal_mutex_guard() : terminal(NULL) {}
    int lock(cuda_g73_terminal_state *state) {
        assert(!terminal);
        if (!state->mutex_ready) return 0;
        terminal = state;
        os_mutex_lock(&terminal->mutex);
        assert(!terminal->mutex_owned);
        terminal->mutex_owned = 1;
        return 1;
    }
    int held_for(const cuda_g73_terminal_state *state) const {
        return terminal == state && state->mutex_owned;
    }
    ~cuda_g73_terminal_mutex_guard() {
        if (!terminal) return;
        assert(terminal->mutex_owned);
        terminal->mutex_owned = 0;
        os_mutex_unlock(&terminal->mutex);
    }
};

/* Exact escape terminal: zero shared-resource dependency and zero mmap faults
 * on the serving path. A dedicated startup-opened plain fd supplies <=1 MiB
 * synchronous chunks; the absolute deadline is checked between chunks and an
 * overrun is logged, but this last resort completes. One dedicated mutex owns
 * the bounce, device slots, and route-pointer publication across direct callers.
 * The routed-MoE caller owns that mutex until all consumers are enqueued. */
static int cuda_g73_terminal_exact_load(
        const void *model_map, uint64_t model_size, uint32_t layer,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        uint32_t n_total_expert, uint32_t route_count,
        const ds4_gpu_tensor *selected_arg,
        cuda_g73_route_outcomes *outcomes, double absolute_deadline) {
    cuda_g73_terminal_state &terminal = g_cuda_g73_terminal;
    if (!model_map || model_map != g_model_host_base || !selected_arg ||
        !selected_arg->ptr || route_count == 0u ||
        route_count > CUDA_MOE_ROUTE_COUNT || n_total_expert != 256u) {
        return cuda_g73_contract_error(layer, "terminal-contract");
    }
    if (!terminal.mutex_ready) {
        return cuda_g73_contract_error(layer, "terminal-mutex");
    }
    assert(terminal.mutex_owned);
    const uint64_t slot_bytes =
        gate_expert_bytes * 2u + down_expert_bytes;
    if (!terminal.ready || terminal.slot_bytes != slot_bytes ||
        !terminal.device_slots || !terminal.host_bounce ||
        !terminal.host_route_ptrs || !terminal.device_route_ptrs ||
        !os_file_valid(&terminal.file)) {
        fprintf(stderr,
                "ds4: [g73-open] terminal unavailable after boot layer=%u\n",
                layer);
        return 0;
    }
    int32_t selected[CUDA_MOE_ROUTE_COUNT] = {0};
    int32_t compact[CUDA_MOE_ROUTE_COUNT] = {0};
    int32_t route_slot[CUDA_MOE_ROUTE_COUNT] = {0};
    if (cudaMemcpy(selected, selected_arg->ptr,
                   (size_t)route_count * sizeof(int32_t),
                   cudaMemcpyDeviceToHost) != cudaSuccess) {
        cuda_g73_device_error(layer, "terminal-selected-d2h");
    }
    uint32_t compact_count = 0u;
    for (uint32_t route = 0; route < route_count; route++) {
        const int32_t expert = selected[route];
        if (expert < 0 || (uint32_t)expert >= n_total_expert) {
            return cuda_g73_contract_error(layer, "terminal-selected-range");
        }
        uint32_t slot = 0u;
        for (; slot < compact_count && compact[slot] != expert; slot++) {}
        if (slot == compact_count) compact[compact_count++] = expert;
        route_slot[route] = (int32_t)slot;
    }
    for (uint32_t slot = 0; slot < compact_count; slot++) {
        const uint64_t expert = (uint64_t)(uint32_t)compact[slot];
        const uint64_t gate_src = gate_offset + expert * gate_expert_bytes;
        const uint64_t up_src = up_offset + expert * gate_expert_bytes;
        const uint64_t down_src = down_offset + expert * down_expert_bytes;
        if (gate_src > model_size || gate_expert_bytes > model_size - gate_src ||
            up_src > model_size || gate_expert_bytes > model_size - up_src ||
            down_src > model_size || down_expert_bytes > model_size - down_src) {
            return cuda_g73_contract_error(
                layer, "terminal-corrupt-model-range");
        }
        if (!cuda_g73_terminal_read_part(
                terminal.host_bounce, gate_expert_bytes,
                gate_src, absolute_deadline, layer, (uint32_t)expert,
                "gate") ||
            !cuda_g73_terminal_read_part(
                terminal.host_bounce + gate_expert_bytes,
                gate_expert_bytes, up_src, absolute_deadline, layer,
                (uint32_t)expert, "up") ||
            !cuda_g73_terminal_read_part(
                terminal.host_bounce + gate_expert_bytes * 2u,
                down_expert_bytes, down_src, absolute_deadline, layer,
                (uint32_t)expert, "down")) {
            fprintf(stderr,
                    "ds4: [g73-open] terminal plain read failed "
                    "layer=%u expert=%llu error=%s\n", layer,
                    (unsigned long long)expert, strerror(errno));
            return 0;
        }
        char *device_slot = terminal.device_slots +
            (uint64_t)slot * terminal.slot_bytes;
        const double copy_started = cuda_wall_sec();
        /* Accepted WDDM assumption: this one fixed 6.75 MiB copy starts from
         * pinned memory and completes at available PCIe bandwidth. WDDM offers
         * no formal wall-clock bound, so this is the system's sole accepted
         * bandwidth-bound step and an over-deadline completion is explicit. */
        const cudaError_t copy_error = cudaMemcpy(
            device_slot, terminal.host_bounce, (size_t)terminal.slot_bytes,
            cudaMemcpyHostToDevice);
        const double copy_finished = cuda_wall_sec();
        if (copy_error != cudaSuccess) {
            cuda_g73_device_error(layer, "terminal-exact-h2d");
        }
        if (absolute_deadline > 0.0 && copy_finished > absolute_deadline) {
            fprintf(stderr,
                    "ds4: [g73-open] budget_overrun layer=%u expert=%llu "
                    "phase=terminal-h2d bytes=%llu elapsed_ms=%.3f "
                    "assumption=pinned-pcie-bandwidth action=complete\n",
                    layer, (unsigned long long)expert,
                    (unsigned long long)terminal.slot_bytes,
                    (copy_finished - copy_started) * 1000.0);
        }
    }
    for (uint32_t route = 0; route < route_count; route++) {
        char *device_slot = terminal.device_slots +
            (uint64_t)(uint32_t)route_slot[route] * terminal.slot_bytes;
        terminal.host_route_ptrs[route] =
            (uint64_t)(uintptr_t)device_slot;
        terminal.host_route_ptrs[route_count + route] =
            (uint64_t)(uintptr_t)(device_slot + gate_expert_bytes);
        terminal.host_route_ptrs[2u * route_count + route] =
            (uint64_t)(uintptr_t)(device_slot + gate_expert_bytes * 2u);
    }
    std::atomic_thread_fence(std::memory_order_release);
    g_moe_gather.direct_cache_active = 0;
    g_moe_gather.mixed_direct_active = 1;
    return cuda_g73_classify_fallback(
        layer, selected, route_count, 1, outcomes);
}

static int cuda_g73_outcomes_conserved(
        const cuda_g73_route_outcomes &outcomes) {
    const uint64_t served = outcomes.served_transient +
        outcomes.served_promoted + outcomes.served_selected_fallback +
        outcomes.served_terminal_exact;
    return outcomes.out_of_mask_routes ==
            served + outcomes.clamped + outcomes.request_refused &&
        outcomes.clamped == 0u && outcomes.request_refused == 0u;
}

static int cuda_g73_commit_outcomes(
        uint32_t layer, const cuda_g73_route_outcomes &outcomes) {
    if (!cuda_g73_outcomes_conserved(outcomes)) {
        const uint64_t served = outcomes.served_transient +
            outcomes.served_promoted + outcomes.served_selected_fallback +
            outcomes.served_terminal_exact;
        const uint64_t accounted =
            served + outcomes.clamped + outcomes.request_refused;
        const int64_t delta = (int64_t)outcomes.out_of_mask_routes -
            (int64_t)accounted;
        fprintf(stderr,
                "ds4: [g73-open] outcome conservation mismatch layer=%u "
                "out_of_mask_routes=%llu served_transient=%llu "
                "served_promoted=%llu served_selected_fallback=%llu "
                "served_terminal_exact=%llu clamped=%llu "
                "request_refused=%llu delta=%lld strict=%d action=%s\n",
                layer,
                (unsigned long long)outcomes.out_of_mask_routes,
                (unsigned long long)outcomes.served_transient,
                (unsigned long long)outcomes.served_promoted,
                (unsigned long long)outcomes.served_selected_fallback,
                (unsigned long long)outcomes.served_terminal_exact,
                (unsigned long long)outcomes.clamped,
                (unsigned long long)outcomes.request_refused,
                (long long)delta, g_cuda_g73_conservation_strict,
                g_cuda_g73_conservation_strict ? "abort" : "continue");
        if (g_cuda_g73_conservation_strict) {
            return cuda_g73_contract_error(
                layer, "outcome-conservation-before-commit");
        }
    }
    cuda_g133_telemetry_increment(
        g_cuda_g133_telemetry.out_of_mask_routes,
        outcomes.out_of_mask_routes);
    cuda_g133_telemetry_increment(
        g_cuda_g133_telemetry.served_transient,
        outcomes.served_transient);
    cuda_g133_telemetry_increment(
        g_cuda_g133_telemetry.served_promoted,
        outcomes.served_promoted);
    cuda_g133_telemetry_increment(
        g_cuda_g133_telemetry.served_selected_fallback,
        outcomes.served_selected_fallback);
    cuda_g133_telemetry_increment(
        g_cuda_g133_telemetry.served_terminal_exact,
        outcomes.served_terminal_exact);
    return 1;
}

extern "C" int ds4_gpu_g73_open_selftest(const char *read_path) {
    int ok = 1;
    os_file_t file;
    os_file_init(&file);
    if (!read_path || os_file_open_read(&file, read_path) != 0) {
        fprintf(stderr,
                "ds4: [g73-open-selftest] result=failed phase=open-read\n");
        return 0;
    }
    static char cancelled_byte = 0;
    static char deadline_byte = 0;
    os_pread_cancellable_t cancelled_state;
    os_pread_cancellable_init(&cancelled_state);
    if (os_pread_cancellable_prepare(&cancelled_state) != 0) ok = 0;
    (void)os_pread_cancel(&cancelled_state, 7u);
    errno = 0;
    const int64_t cancelled = os_pread_cancellable_timeout(
        &file, &cancelled_byte, 1u, 0u, &cancelled_state, 7u, 1000u);
    if (cancelled != -1 || errno != ECANCELED) ok = 0;
    os_pread_cancellable_destroy(&cancelled_state);

    os_pread_cancellable_t deadline_state;
    os_pread_cancellable_init(&deadline_state);
    if (os_pread_cancellable_prepare(&deadline_state) != 0) ok = 0;
    errno = 0;
    const int64_t timed_out = os_pread_cancellable_timeout(
        &file, &deadline_byte, 1u, 0u, &deadline_state, 9u, 0u);
    if (timed_out != -1 || errno != ETIMEDOUT) ok = 0;
    os_pread_cancellable_destroy(&deadline_state);
    os_file_close(&file);

    cuda_g73_route_outcomes outcomes = {};
    outcomes.out_of_mask_routes = 4u;
    outcomes.served_transient = 1u;
    outcomes.served_promoted = 1u;
    outcomes.served_selected_fallback = 1u;
    outcomes.served_terminal_exact = 1u;
    if (!cuda_g73_outcomes_conserved(outcomes)) ok = 0;
    outcomes.out_of_mask_routes = 5u;
    outcomes.clamped = 1u;
    if (cuda_g73_outcomes_conserved(outcomes)) ok = 0;

    cuda_q1_0_ssd_wrap_state &state = g_q1_0_ssd_wrap;
    if (os_mutex_init(&state.mutex) != 0 || os_cond_init(&state.cond) != 0) {
        fprintf(stderr,
                "ds4: [g73-open-selftest] result=failed phase=sync-init\n");
        return 0;
    }
    state.mutex_ready = 1;
    state.cond_ready = 1;
    state.enabled = 1;
    state.failed = 0;
    state.stop = 0;
    state.jobs.resize(4u);
    state.ring_busy.assign(2u, 0u);
    state.queue_capacity = 4u;

    cuda_moe_tier_entry empty = {};
    empty.ram_slot = UINT32_MAX;
    empty.state = CUDA_MOE_TIER_SSD_COLD;
    g_moe_tiering.entries.assign(
        (size_t)CUDA_MOE_LAYER_COUNT * 256u, empty);
    g_dynamic_arena.slots.resize(2u);
    for (cuda_dynamic_arena_slot &slot : g_dynamic_arena.slots) {
        slot = cuda_dynamic_arena_slot{};
        slot.layer = UINT32_MAX;
        slot.expert = UINT32_MAX;
        slot.state = DS4_GPU_ARENA_FREE;
    }
    static char synthetic_ring[2] = {0x11, 0x22};
    static char synthetic_slots[2] = {0, 0};
    g_dynamic_arena.slot_bytes = 1u;
    g_dynamic_arena.ssd_wrap_ssd_ring_base = synthetic_ring;
    g_q1_0_ssd_wrap_reserved_slots.assign(2u, 0u);
    for (uint32_t i = 0; i < g_dynamic_arena.slots.size(); i++) {
        g_dynamic_arena.slots[i].host_ptr = &synthetic_slots[i];
    }

    cuda_moe_route_request request = {};
    request.layer_index = 0u;
    request.route_count = 1u;
    request.absolute_deadline = cuda_wall_sec() + 1.0;
    request.g133_epoch.request_epoch = 1u;
    request.g133_epoch.position_epoch = 1u;
    cuda_q1_0_promotion_record_context record = {};
    record.active = 1;
    record.layer = 0u;
    record.expert = 1u;
    record.destination_bytes = 1u;
    record.request_epoch = 1u;
    record.observation_call = 1u;
    record.current_call = 1u;
    record.first_eligible_call = 2u;
    const uint64_t rotation_promotions_before = state.successes;
    const int first_request_submitted = cuda_q1_0_ssd_wrap_submit(
        request, 0u, 1u, &record, 1);
    if (first_request_submitted != 1) ok = 0;
    os_mutex_lock(&state.mutex);
    for (cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        if (job.state == CUDA_Q1_0_SSD_WRAP_REQUESTED &&
            job.layer == 0u && job.expert == 1u) {
            job.bytes_read = 1u;
            job.state = CUDA_Q1_0_SSD_WRAP_RAM_READY;
        }
    }
    os_mutex_unlock(&state.mutex);
    cuda_q1_0_ssd_wrap_flush();

    request.g133_epoch.request_epoch = 2u;
    request.g133_epoch.position_epoch = 1u;
    record = cuda_q1_0_promotion_record_context{};
    record.active = 1;
    record.layer = 0u;
    record.expert = 2u;
    record.destination_bytes = 1u;
    record.request_epoch = 2u;
    record.observation_call = 2u;
    record.current_call = 2u;
    record.first_eligible_call = 3u;
    const int second_request_submitted = cuda_q1_0_ssd_wrap_submit(
        request, 0u, 2u, &record, 1);
    if (second_request_submitted != 1) ok = 0;
    os_mutex_lock(&state.mutex);
    for (cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        if (job.state == CUDA_Q1_0_SSD_WRAP_REQUESTED &&
            job.layer == 0u && job.expert == 2u) {
            job.bytes_read = 1u;
            job.state = CUDA_Q1_0_SSD_WRAP_RAM_READY;
        }
    }
    os_mutex_unlock(&state.mutex);
    cuda_q1_0_ssd_wrap_flush();
    const uint64_t rotation_promotions_after = state.successes;
    const int cross_request_rearm_ok =
        !state.failed && !state.stop && second_request_submitted == 1 &&
        rotation_promotions_after == rotation_promotions_before + 2u &&
        g_moe_tiering.entries[1u].ram_slot != UINT32_MAX &&
        g_moe_tiering.entries[2u].ram_slot != UINT32_MAX;
    if (!cross_request_rearm_ok) ok = 0;

    /* A queued advisory job owns no I/O deadline until the worker acquires it.
     * Queue age remains independently observable and the configured service
     * budget is unchanged. Each job in a wave gets its own acquisition time. */
    const double timing_started = cuda_wall_sec();
    cuda_q1_0_ssd_wrap_job aged_advisory_job = {};
    aged_advisory_job.g73_open_rotation = 1u;
    aged_advisory_job.queued_at = timing_started - 1.0;
    aged_advisory_job.request.absolute_deadline = timing_started - 0.5;
    const cuda_q1_0_ssd_wrap_service_timing aged_advisory_timing =
        cuda_q1_0_ssd_wrap_service_timing_for_job(
            aged_advisory_job, timing_started);
    const int service_deadline_fresh_ok =
        aged_advisory_timing.queue_age_seconds >= 0.999 &&
        aged_advisory_timing.service_budget_seconds > 0.0 &&
        fabs(aged_advisory_timing.service_deadline -
             (timing_started +
              aged_advisory_timing.service_budget_seconds)) < 1e-9 &&
        aged_advisory_timing.io_deadline ==
            aged_advisory_timing.service_deadline &&
        cuda_deadline_remaining_ms(aged_advisory_timing.io_deadline) > 0u;

    cuda_q1_0_ssd_wrap_job second_aged_advisory_job =
        aged_advisory_job;
    second_aged_advisory_job.queued_at = timing_started - 2.0;
    const double second_service_started = timing_started + 0.010;
    const cuda_q1_0_ssd_wrap_service_timing second_advisory_timing =
        cuda_q1_0_ssd_wrap_service_timing_for_job(
            second_aged_advisory_job, second_service_started);
    const int per_job_service_budget_ok =
        second_advisory_timing.queue_age_seconds >= 1.999 &&
        fabs(second_advisory_timing.service_deadline -
             (second_service_started +
              second_advisory_timing.service_budget_seconds)) < 1e-9 &&
        second_advisory_timing.service_deadline >
            aged_advisory_timing.service_deadline;

    cuda_q1_0_ssd_wrap_job non_g73_deadline_job = {};
    non_g73_deadline_job.queued_at = timing_started - 1.0;
    non_g73_deadline_job.request.absolute_deadline =
        timing_started +
        aged_advisory_timing.service_budget_seconds * 0.5;
    const cuda_q1_0_ssd_wrap_service_timing non_g73_timing =
        cuda_q1_0_ssd_wrap_service_timing_for_job(
            non_g73_deadline_job, timing_started);
    const int non_g73_request_deadline_ok =
        non_g73_timing.io_deadline ==
            non_g73_deadline_job.request.absolute_deadline &&
        non_g73_timing.io_deadline < non_g73_timing.service_deadline;
    if (!service_deadline_fresh_ok || !per_job_service_budget_ok ||
        !non_g73_request_deadline_ok) {
        ok = 0;
    }

    /* Restore empty synthetic ownership and inject the worker terminal for one
     * advisory I/O failure. It must release only that job; a later rotation
     * must still submit and publish without replaying or serving the failure. */
    g_moe_tiering.entries.assign(
        (size_t)CUDA_MOE_LAYER_COUNT * 256u, empty);
    for (uint32_t i = 0; i < g_dynamic_arena.slots.size(); i++) {
        g_dynamic_arena.slots[i] = cuda_dynamic_arena_slot{};
        g_dynamic_arena.slots[i].host_ptr = &synthetic_slots[i];
        g_dynamic_arena.slots[i].layer = UINT32_MAX;
        g_dynamic_arena.slots[i].expert = UINT32_MAX;
        g_dynamic_arena.slots[i].state = DS4_GPU_ARENA_FREE;
    }
    for (cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        job = cuda_q1_0_ssd_wrap_job{};
    }
    state.ring_busy.assign(2u, 0u);
    g_q1_0_ssd_wrap_reserved_slots.assign(2u, 0u);
    state.failed = 0;
    state.stop = 0;
    request.g133_epoch.request_epoch = 3u;
    record = cuda_q1_0_promotion_record_context{};
    record.active = 1;
    record.layer = 0u;
    record.expert = 3u;
    record.destination_bytes = 1u;
    record.request_epoch = 3u;
    record.observation_call = 3u;
    record.current_call = 3u;
    record.first_eligible_call = 4u;
    const uint64_t advisory_failures_before = state.advisory_failures;
    const uint64_t advisory_releases_before = state.advisory_releases;
    const uint64_t failures_before = state.failures;
    const int advisory_submitted = cuda_q1_0_ssd_wrap_submit(
        request, 0u, 3u, &record, 1);
    uint32_t advisory_job_index = UINT32_MAX;
    os_mutex_lock(&state.mutex);
    for (uint32_t i = 0; i < state.jobs.size(); i++) {
        cuda_q1_0_ssd_wrap_job &job = state.jobs[i];
        if (job.state == CUDA_Q1_0_SSD_WRAP_REQUESTED &&
            job.layer == 0u && job.expert == 3u) {
            advisory_job_index = i;
            job.io_status = CUDA_Q1_0_SSD_WRAP_IO_TIMEOUT;
            job.failure_reason = "timeout";
            job.io_errno = ETIMEDOUT;
            job.io_expected_bytes = 1u;
            job.io_actual_bytes = -1;
            job.io_failure_range = 0u;
            job.failure_counted = 1u;
            job.state = CUDA_Q1_0_SSD_WRAP_FAILED;
            state.failures++;
            state.advisory_failures++;
            break;
        }
    }
    os_mutex_unlock(&state.mutex);
    const int advisory_poll_ok =
        advisory_job_index != UINT32_MAX &&
        cuda_q1_0_ssd_wrap_finish_one(advisory_job_index, 1);
    int advisory_cleanup_ok = advisory_submitted == 1 &&
        advisory_poll_ok && !state.failed && !state.stop &&
        state.failures == failures_before + 1u &&
        state.advisory_failures == advisory_failures_before + 1u &&
        state.advisory_releases == advisory_releases_before + 1u &&
        g_moe_tiering.entries[3u].state == CUDA_MOE_TIER_SSD_COLD &&
        g_moe_tiering.entries[3u].ram_slot == UINT32_MAX;
    for (const cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        if (job.state != CUDA_Q1_0_SSD_WRAP_FREE) advisory_cleanup_ok = 0;
    }
    for (const cuda_dynamic_arena_slot &slot : g_dynamic_arena.slots) {
        if (cuda_dynamic_arena_slot_refs_load(&slot.cpu_lane_slot_refs) != 0u) {
            advisory_cleanup_ok = 0;
        }
    }
    for (uint8_t reserved : g_q1_0_ssd_wrap_reserved_slots) {
        if (reserved != 0u) advisory_cleanup_ok = 0;
    }
    for (uint8_t ring_busy : state.ring_busy) {
        if (ring_busy != 0u) advisory_cleanup_ok = 0;
    }

    request.g133_epoch.request_epoch = 4u;
    record = cuda_q1_0_promotion_record_context{};
    record.active = 1;
    record.layer = 0u;
    record.expert = 4u;
    record.destination_bytes = 1u;
    record.request_epoch = 4u;
    record.observation_call = 4u;
    record.current_call = 4u;
    record.first_eligible_call = 5u;
    const uint64_t post_failure_successes_before = state.successes;
    const int post_failure_submitted = cuda_q1_0_ssd_wrap_submit(
        request, 0u, 4u, &record, 1);
    os_mutex_lock(&state.mutex);
    for (cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        if (job.state == CUDA_Q1_0_SSD_WRAP_REQUESTED &&
            job.layer == 0u && job.expert == 4u) {
            job.bytes_read = 1u;
            job.io_status = CUDA_Q1_0_SSD_WRAP_IO_OK;
            job.state = CUDA_Q1_0_SSD_WRAP_RAM_READY;
        }
    }
    os_mutex_unlock(&state.mutex);
    cuda_q1_0_ssd_wrap_flush();
    const int advisory_followup_ok =
        post_failure_submitted == 1 && !state.failed && !state.stop &&
        state.successes == post_failure_successes_before + 1u &&
        g_moe_tiering.entries[4u].ram_slot != UINT32_MAX;
    if (!advisory_cleanup_ok || !advisory_followup_ok) ok = 0;

    /* Restore empty synthetic ownership, then retain the original fatal
     * teardown-versus-submit assertion as an independent structural case. */
    g_moe_tiering.entries.assign(
        (size_t)CUDA_MOE_LAYER_COUNT * 256u, empty);
    for (uint32_t i = 0; i < g_dynamic_arena.slots.size(); i++) {
        g_dynamic_arena.slots[i] = cuda_dynamic_arena_slot{};
        g_dynamic_arena.slots[i].host_ptr = &synthetic_slots[i];
        g_dynamic_arena.slots[i].layer = UINT32_MAX;
        g_dynamic_arena.slots[i].expert = UINT32_MAX;
        g_dynamic_arena.slots[i].state = DS4_GPU_ARENA_FREE;
    }
    for (cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        job = cuda_q1_0_ssd_wrap_job{};
    }
    state.ring_busy.assign(2u, 0u);
    g_q1_0_ssd_wrap_reserved_slots.assign(2u, 0u);
    state.failed = 0;
    state.stop = 0;
    request.g133_epoch.request_epoch = 3u;
    record = cuda_q1_0_promotion_record_context{};
    record.active = 1;
    record.layer = 0u;
    record.expert = 1u;
    record.destination_bytes = 1u;
    record.request_epoch = 3u;
    record.observation_call = 3u;
    record.current_call = 3u;
    record.first_eligible_call = 4u;
    const int submitted = cuda_q1_0_ssd_wrap_submit(
        request, 0u, 1u, &record, 1);
    if (submitted != 1) ok = 0;
    os_mutex_lock(&state.mutex);
    cuda_q1_0_ssd_wrap_fail_and_release_all_locked("selftest-teardown");
    os_mutex_unlock(&state.mutex);
    for (const cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        if (job.state != CUDA_Q1_0_SSD_WRAP_FREE) ok = 0;
    }
    for (const cuda_dynamic_arena_slot &slot : g_dynamic_arena.slots) {
        if (cuda_dynamic_arena_slot_refs_load(&slot.cpu_lane_slot_refs) != 0u) {
            ok = 0;
        }
    }
    for (uint8_t reserved : g_q1_0_ssd_wrap_reserved_slots) {
        if (reserved != 0u) ok = 0;
    }

    state.failed = 0;
    state.stop = 0;
    record = cuda_q1_0_promotion_record_context{};
    record.active = 1;
    record.layer = 0u;
    record.expert = 2u;
    record.destination_bytes = 1u;
    const int raced = cuda_q1_0_ssd_wrap_submit(
        request, 0u, 2u, &record, 2);
    if (raced != 0) ok = 0;
    for (const cuda_dynamic_arena_slot &slot : g_dynamic_arena.slots) {
        if (cuda_dynamic_arena_slot_refs_load(&slot.cpu_lane_slot_refs) != 0u) {
            ok = 0;
        }
    }

    /* Stall the real publisher after it enters COMMITTING, then execute the
     * production teardown/reset handshake. Reset must retain old entries and
     * the resumed publisher must abandon before touching either metadata set. */
    state.failed = 0;
    state.stop = 0;
    state.commit_safe_leaked = 0;
    state.generation_abandons = 0u;
    state.selftest_stall_committing_publication = 1;
    state.selftest_committing_publication_stalled = 0;
    state.selftest_release_committing_publication = 0;
    for (cuda_q1_0_ssd_wrap_job &job : state.jobs) {
        job = cuda_q1_0_ssd_wrap_job{};
    }
    const uint32_t publishing_entry_index = 3u;
    static char publishing_source = 0x2a;
    static char publishing_destination = 0;
    cuda_dynamic_arena_slot &publishing_slot = g_dynamic_arena.slots[0];
    publishing_slot = cuda_dynamic_arena_slot{};
    publishing_slot.host_ptr = &publishing_destination;
    publishing_slot.layer = 0u;
    publishing_slot.expert = publishing_entry_index;
    publishing_slot.content_generation = 17u;
    publishing_slot.state = DS4_GPU_ARENA_LOADING;
    if (!cuda_dynamic_arena_slot_writer_try_acquire(&publishing_slot)) ok = 0;
    cuda_moe_tier_entry &publishing_entry =
        g_moe_tiering.entries[publishing_entry_index];
    publishing_entry.ram_slot = 0u;
    publishing_entry.ram_generation = 17u;
    publishing_entry.state = CUDA_MOE_TIER_RAM_PROBATION;
    cuda_moe_tier_entry *retained_entry = &publishing_entry;
    cuda_q1_0_ssd_wrap_job &publishing_job = state.jobs[0];
    publishing_job.state = CUDA_Q1_0_SSD_WRAP_RAM_READY;
    publishing_job.record.request_epoch = 1u;
    publishing_job.record.observation_call = 1u;
    publishing_job.record.first_eligible_call = 2u;
    publishing_job.request_epoch = 1u;
    publishing_job.bytes_read = 1u;
    publishing_job.layer = 0u;
    publishing_job.expert = publishing_entry_index;
    publishing_job.slot = 0u;
    publishing_job.ring_slot = 0u;
    publishing_job.read_base = &publishing_source;
    publishing_job.writer_claimed = 1u;
    publishing_job.g73_open_rotation = 1u;
    const uint64_t tier_generation_before = state.tier_generation;
    const uint32_t publishing_job_index = 0u;
    os_thread_t publishing_thread;
    int publishing_thread_started = os_thread_create(
        &publishing_thread, cuda_q1_0_ssd_wrap_selftest_finish_one,
        (void *)&publishing_job_index) == 0;
    if (!publishing_thread_started) {
        ok = 0;
    } else {
        os_mutex_lock(&state.mutex);
        while (!state.selftest_committing_publication_stalled) {
            if (os_cond_timedwait_ms(&state.cond, &state.mutex, 1000u) != 0) {
                ok = 0;
                break;
            }
        }
        os_mutex_unlock(&state.mutex);
        os_mutex_lock(&state.mutex);
        cuda_q1_0_ssd_wrap_fail_and_release_all_locked(
            "selftest-teardown-during-committing");
        os_mutex_unlock(&state.mutex);
        if (!cuda_q1_0_ssd_wrap_tier_reset_begin()) ok = 0;
        if (state.tier_generation == tier_generation_before) ok = 0;
        const uint32_t retained_ram_slot = retained_entry->ram_slot;
        const uint64_t retained_ram_generation =
            retained_entry->ram_generation;
        const cuda_moe_tier_state retained_state = retained_entry->state;

        g_moe_tiering = cuda_moe_tiering();
        g_moe_tiering.entries.assign(
            (size_t)CUDA_MOE_LAYER_COUNT * 256u, empty);
        cuda_moe_tier_entry &replacement_entry =
            g_moe_tiering.entries[publishing_entry_index];
        replacement_entry.ram_slot = 91u;
        replacement_entry.ram_generation = 12345u;
        replacement_entry.state = CUDA_MOE_TIER_VRAM_PROTECTED;
        os_mutex_lock(&state.mutex);
        state.selftest_release_committing_publication = 1;
        os_cond_broadcast(&state.cond);
        os_mutex_unlock(&state.mutex);
        os_thread_join(publishing_thread);

        if (state.generation_abandons != 1u ||
            state.jobs[0].state != CUDA_Q1_0_SSD_WRAP_DEAD ||
            !state.jobs[0].commit_safe_leaked ||
            cuda_dynamic_arena_slot_refs_load(
                &publishing_slot.cpu_lane_slot_refs) !=
                    CUDA_DYNAMIC_ARENA_SLOT_WRITER ||
            publishing_slot.state != DS4_GPU_ARENA_FREE ||
            retained_entry->ram_slot != retained_ram_slot ||
            retained_entry->ram_generation != retained_ram_generation ||
            retained_entry->state != retained_state ||
            replacement_entry.ram_slot != 91u ||
            replacement_entry.ram_generation != 12345u ||
            replacement_entry.state != CUDA_MOE_TIER_VRAM_PROTECTED) {
            ok = 0;
        }
    }

    fprintf(stderr,
            "ds4: [g73-open-selftest] result=%s "
            "pread_cancel=start-then-cancel "
            "pread_deadline=start-then-cancel "
            "rotator=production sequential_consistency_hook=real "
            "cross_request_rearm=%s first_submit=%d second_submit=%d "
            "promotion_delta=%llu "
            "service_deadline=%s per_job_service_budget=%s "
            "queue_aging=separate non_g73_deadline=%s "
            "advisory_failure=%s advisory_followup=%s "
            "advisory_failure_delta=%llu advisory_release_delta=%llu "
            "structural_failure=terminal "
            "teardown_during_committing=generation-abandon "
            "invariant=real\n",
            ok ? "passed" : "failed",
            cross_request_rearm_ok ? "second-submit-promoted" : "failed",
            first_request_submitted, second_request_submitted,
            (unsigned long long)(rotation_promotions_after -
                                 rotation_promotions_before),
            service_deadline_fresh_ok ? "job-acquisition-fresh" : "failed",
            per_job_service_budget_ok ? "per-job-fresh" : "failed",
            non_g73_request_deadline_ok ? "request-bounded" : "failed",
            advisory_cleanup_ok ? "job-local-clean" : "failed",
            advisory_followup_ok ? "subsequent-promoted" : "failed",
            (unsigned long long)(state.advisory_failures -
                                 advisory_failures_before),
            (unsigned long long)(state.advisory_releases -
                                 advisory_releases_before));
    return ok;
}

extern "C" uint32_t ds4_gpu_routed_moe_last_selected(
        uint64_t gate_offset,
        int32_t *out_ids,
        uint32_t out_cap) {
    if (!out_ids || out_cap == 0 || !g_moe_last_selected.valid ||
        g_moe_last_selected.gate_offset != gate_offset) {
        return 0;
    }
    uint32_t count = g_moe_last_selected.count;
    if (count > out_cap) count = out_cap;
    memcpy(out_ids, g_moe_last_selected.ids,
           (size_t)count * sizeof(g_moe_last_selected.ids[0]));
    return count;
}

static int cuda_moe_route_split_down_ensure(
        cuda_moe_expert_cache *cache,
        uint32_t out_dim) {
    const uint64_t bytes =
        (uint64_t)CUDA_MOE_ROUTE_COUNT * out_dim * sizeof(float);
    if (cache->device_route_split_down &&
        cache->device_route_split_down_bytes >= bytes) {
        return 1;
    }
    if (cache->device_route_split_down) {
        (void)cudaFree(cache->device_route_split_down);
        cache->device_route_split_down = NULL;
        cache->device_route_split_down_bytes = 0;
    }
    if (cudaMalloc((void **)&cache->device_route_split_down, (size_t)bytes) !=
        cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }
    cache->device_route_split_down_bytes = bytes;
    return 1;
}

static int cuda_moe_q1_resident_upload_fail(
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        cuda_g130_attribution_state *attribution_state
#endif
        ) {
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    cuda_g130_attribution_span sync_previous = CUDA_G130_ATTRIB_NONE;
    if (attribution_state) {
        sync_previous = cuda_g130_attribution_switch(
            attribution_state,
            CUDA_G130_ATTRIB_EXISTING_STREAM_SYNC_WAIT);
    }
#endif
    (void)cudaStreamSynchronize(g_model_upload_stream);
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    if (attribution_state) {
        (void)cuda_g130_attribution_switch(
            attribution_state, sync_previous);
    }
#endif
    g_moe_gather.slot_tensor.ptr = NULL;
    g_moe_gather.slot_tensor.bytes = 0;
    g_moe_gather.slot_tensor.owner = 0;
    g_moe_gather.direct_cache_active = 0;
    g_moe_gather.mixed_direct_active = 0;
    g_moe_gather.mixed_cache_routes = 0;
    g_moe_gather.mixed_compact_routes = 0;
    return 0;
}

static int cuda_moe_selected_load_q1_0(
        const void *model_map, uint64_t model_size,
        uint32_t layer_index,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        uint32_t n_total_expert, uint32_t n_expert, uint32_t n_tokens,
        const ds4_gpu_tensor *selected_arg,
        const int32_t *selected_host_arg) {
    if (!g_q1_0_sidecar_file_valid ||
        model_map != g_q1_0_sidecar_host_base ||
        model_size != g_q1_0_sidecar_size ||
        getenv("DS4_Q1_0_SELECTED_LOAD") == NULL) {
        return 0;
    }
    if (!selected_arg || !selected_arg->ptr ||
        n_total_expert == 0 || n_expert == 0 || n_tokens == 0 ||
        gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        n_tokens > UINT32_MAX / n_expert) {
        return 0;
    }
    const uint32_t slot_count = n_tokens * n_expert;
    if (selected_arg->bytes < (uint64_t)slot_count * sizeof(int32_t)) return 0;

    g_moe_gather.h_sel.resize(slot_count);
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    cuda_g130_attribution_state *attribution_state =
        cuda_g130_attribution_token_state();
#endif
    int selected_ready = 1;
    if (selected_host_arg) {
        /* Mixed-Q1 already classified these exact IDs on the host; consuming
         * them directly avoids a second D2H behind the queued hot kernels. */
        memcpy(g_moe_gather.h_sel.data(), selected_host_arg,
               (size_t)slot_count * sizeof(int32_t));
    } else {
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        cuda_g130_attribution_span attribution_previous =
            CUDA_G130_ATTRIB_NONE;
        if (attribution_state) {
            attribution_previous = cuda_g130_attribution_switch(
                attribution_state,
                CUDA_G130_ATTRIB_SELECTION_D2H);
        }
#endif
        selected_ready = cuda_ok(
            cudaMemcpy(g_moe_gather.h_sel.data(), selected_arg->ptr,
                       (size_t)slot_count * sizeof(int32_t),
                       cudaMemcpyDeviceToHost),
            "Q1_0 selected D2H");
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        if (attribution_state) {
            (void)cuda_g130_attribution_switch(
                attribution_state, attribution_previous);
        }
#endif
    }
    if (!selected_ready) {
        return 0;
    }
    if (!cuda_sparse_bake_validate_selected(
            layer_index, g_moe_gather.h_sel.data(), slot_count,
            "Q1_0 routed selection", 0u)) {
        return 0;
    }

    std::vector<int32_t> &e2s = g_moe_gather.h_expert_to_slot;
    e2s.assign(n_total_expert, -1);
    std::vector<int32_t> &compact = g_moe_gather.h_compact_ids;
    compact.clear();
    std::vector<int32_t> &slots = g_moe_gather.h_slot_ids;
    slots.resize(slot_count);
    for (uint32_t i = 0; i < slot_count; i++) {
        const int32_t e = g_moe_gather.h_sel[i];
        if (e < 0 || (uint32_t)e >= n_total_expert) return 0;
        e2s[(uint32_t)e] = -2;
    }
    for (uint32_t e = 0; e < n_total_expert; e++) {
        if (e2s[e] != -2) continue;
        e2s[e] = (int32_t)compact.size();
        compact.push_back((int32_t)e);
    }
    for (uint32_t i = 0; i < slot_count; i++) {
        slots[i] = e2s[(uint32_t)g_moe_gather.h_sel[i]];
    }
    const uint32_t compact_count = (uint32_t)compact.size();
    if (compact_count == 0 || compact_count > n_total_expert) return 0;

    const uint64_t cgate = (uint64_t)compact_count * gate_expert_bytes;
    const uint64_t cdown = (uint64_t)compact_count * down_expert_bytes;
    g_moe_gather.q1_active_gate = NULL;
    g_moe_gather.q1_active_up = NULL;
    g_moe_gather.q1_active_down = NULL;
    const int q1_vram_lru_active =
        cuda_q1_0_resident_transport_requested() &&
        cuda_q1_vram_lru_prepare(
            gate_expert_bytes, down_expert_bytes) > 0 &&
        g_q1_vram_lru.capacity >= compact_count;
    if ((!q1_vram_lru_active &&
         (!cuda_moe_gather_ensure(&g_moe_gather.gate,
                                  &g_moe_gather.gate_cap,
                                  cgate, "Q1_0 gather gate") ||
          !cuda_moe_gather_ensure(&g_moe_gather.up,
                                  &g_moe_gather.up_cap,
                                  cgate, "Q1_0 gather up") ||
          !cuda_moe_gather_ensure(&g_moe_gather.down,
                                  &g_moe_gather.down_cap,
                                  cdown, "Q1_0 gather down"))) ||
        !cuda_moe_gather_ensure_i32(&g_moe_gather.slot, &g_moe_gather.slot_cap,
                                    slot_count, "Q1_0 gather slots")) {
        return 0;
    }

    if (cuda_q1_0_resident_transport_requested()) {
        cuda_dynamic_arena *q1_arena =
            cuda_q1_0_route_arena(layer_index);
        if (!q1_arena ||
            q1_arena->backing != CUDA_DYNAMIC_ARENA_BACKING_Q1_0 ||
            q1_arena->model_map != model_map ||
            q1_arena->model_size != model_size) {
            g_q1_0_resident_misses++;
            return 0;
        }
        std::vector<int32_t> lru_slots;
        std::vector<uint8_t> lru_hits;
        std::vector<uint8_t> lru_new;
        int lru_has_eviction = 0;
        const uint64_t q1_source_generation =
            g_q1_0_source_generation;
        if (q1_vram_lru_active) {
            try {
                lru_slots.resize(compact_count);
                lru_hits.resize(compact_count);
                lru_new.resize(compact_count);
            } catch (...) {
                return 0;
            }
            for (uint32_t i = 0; i < compact_count; i++) {
                int hit = 0;
                int evicted = 0;
                const int slot = cuda_q1_vram_lru_resolve(
                    layer_index, (uint32_t)compact[i],
                    q1_source_generation,
                    gate_offset, up_offset, down_offset,
                    &hit, &evicted);
                if (slot < 0) {
                    for (uint32_t j = 0; j < i; j++) {
                        if (!lru_hits[j]) {
                            g_q1_vram_lru.slots[(uint32_t)lru_slots[j]].pending = 0;
                        }
                    }
                    return 0;
                }
                lru_slots[i] = slot;
                lru_hits[i] = hit ? 1u : 0u;
                lru_new[i] = !hit && !evicted ? 1u : 0u;
                lru_has_eviction |= evicted;
            }
            for (uint32_t i = 0; i < slot_count; i++) {
                slots[i] = lru_slots[(uint32_t)slots[i]];
            }
            /* An evicted slot may still feed an earlier stream-0 kernel. Make
             * the upload stream wait for those consumers before overwriting. */
            if (lru_has_eviction &&
                (!cuda_ok(cudaEventRecord(g_q1_vram_lru.reuse_ready, 0),
                          "Q1_0 VRAM LRU reuse ready") ||
                 !cuda_ok(cudaStreamWaitEvent(
                              g_model_upload_stream,
                              g_q1_vram_lru.reuse_ready, 0),
                          "Q1_0 VRAM LRU reuse wait"))) {
                for (uint32_t i = 0; i < compact_count; i++) {
                    if (!lru_hits[i]) {
                        g_q1_vram_lru.slots[(uint32_t)lru_slots[i]].pending = 0;
                    }
                }
                return cuda_moe_q1_resident_upload_fail(
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
                    attribution_state
#endif
                );
            }
        }

        uint64_t route_h2d_bytes = 0;
        for (uint32_t i = 0; i < compact_count; i++) {
            if (q1_vram_lru_active && lru_hits[i]) continue;
            const uint32_t expert = (uint32_t)compact[i];
            const uint32_t destination = q1_vram_lru_active ?
                (uint32_t)lru_slots[i] : i;
            const uint64_t gate_dst =
                (uint64_t)destination * gate_expert_bytes;
            const uint64_t down_dst =
                (uint64_t)destination * down_expert_bytes;
            const cuda_dynamic_arena_copy_status status =
                cuda_dynamic_arena_copy_expert_async(
                    *q1_arena,
                    model_map, layer_index, expert,
                    gate_offset, up_offset, down_offset,
                    (q1_vram_lru_active ? g_q1_vram_lru.gate :
                                         g_moe_gather.gate) + gate_dst,
                    (q1_vram_lru_active ? g_q1_vram_lru.up :
                                         g_moe_gather.up) + gate_dst,
                    (q1_vram_lru_active ? g_q1_vram_lru.down :
                                         g_moe_gather.down) + down_dst,
                    gate_expert_bytes, gate_expert_bytes,
                    down_expert_bytes);
            if (status != CUDA_DYNAMIC_ARENA_ENQUEUED) {
                if (q1_vram_lru_active) {
                    g_q1_vram_lru.failures++;
                    for (uint32_t j = 0; j < compact_count; j++) {
                        if (!lru_hits[j]) {
                            g_q1_vram_lru.slots[(uint32_t)lru_slots[j]].pending = 0;
                        }
                    }
                }
                g_q1_0_resident_misses++;
                return cuda_moe_q1_resident_upload_fail(
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
                    attribution_state
#endif
                );
            }
            route_h2d_bytes += gate_expert_bytes * 2u + down_expert_bytes;
        }
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        cuda_g130_attribution_span h2d_previous = CUDA_G130_ATTRIB_NONE;
        if (attribution_state) {
            h2d_previous = cuda_g130_attribution_switch(
                attribution_state,
                CUDA_G130_ATTRIB_H2D_ENQUEUE);
        }
#endif
        const int slots_h2d_ok = cuda_ok(
            cudaMemcpyAsync(g_moe_gather.slot, slots.data(),
                            (size_t)slot_count * sizeof(int32_t),
                            cudaMemcpyHostToDevice,
                            q1_vram_lru_active ? 0 : g_model_upload_stream),
            "Q1_0 resident slots H2D");
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        if (attribution_state) {
            (void)cuda_g130_attribution_switch(
                attribution_state, h2d_previous);
        }
#endif
        if (!slots_h2d_ok) {
            if (q1_vram_lru_active) {
                g_q1_vram_lru.failures++;
                for (uint32_t i = 0; i < compact_count; i++) {
                    if (!lru_hits[i]) {
                        g_q1_vram_lru.slots[(uint32_t)lru_slots[i]].pending = 0;
                    }
                }
            }
            return cuda_moe_q1_resident_upload_fail(
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
                attribution_state
#endif
            );
        }
        /* The mixed dispatcher has already queued its hot IQ2 kernels on
         * stream 0. Fence only the cold Q1 consumer so resident uploads can
         * overlap that hot work instead of draining it on the host. */
        const int expert_upload_enqueued = route_h2d_bytes != 0;
        if ((!q1_vram_lru_active || expert_upload_enqueued) &&
            (!cuda_ok(cudaEventRecord(g_q1_upload_ready,
                                      g_model_upload_stream),
                      "Q1_0 resident upload ready") ||
             !cuda_ok(cudaStreamWaitEvent(0, g_q1_upload_ready, 0),
                      "Q1_0 resident upload wait"))) {
            if (q1_vram_lru_active) {
                g_q1_vram_lru.failures++;
                for (uint32_t i = 0; i < compact_count; i++) {
                    if (!lru_hits[i]) {
                        g_q1_vram_lru.slots[(uint32_t)lru_slots[i]].pending = 0;
                    }
                }
            }
            return cuda_moe_q1_resident_upload_fail(
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
                attribution_state
#endif
            );
        }
        if (q1_vram_lru_active) {
            for (uint32_t i = 0; i < compact_count; i++) {
                if (lru_hits[i]) continue;
                cuda_q1_vram_lru_slot &slot =
                    g_q1_vram_lru.slots[(uint32_t)lru_slots[i]];
                slot.pending = 0;
                slot.source_generation = q1_source_generation;
                slot.gate_offset = gate_offset;
                slot.up_offset = up_offset;
                slot.down_offset = down_offset;
                slot.valid = 1;
                if (lru_new[i] &&
                    g_q1_vram_lru.count < g_q1_vram_lru.capacity) {
                    g_q1_vram_lru.count++;
                }
            }
            g_q1_vram_lru.h2d_bytes += route_h2d_bytes;
            g_moe_gather.q1_active_gate = g_q1_vram_lru.gate;
            g_moe_gather.q1_active_up = g_q1_vram_lru.up;
            g_moe_gather.q1_active_down = g_q1_vram_lru.down;
        }
        g_q1_0_resident_hits += compact_count;
        g_q1_0_resident_h2d_bytes += route_h2d_bytes;
    } else {
        std::vector<uint8_t> host_gate;
        std::vector<uint8_t> host_up;
        std::vector<uint8_t> host_down;
        try {
            host_gate.resize((size_t)cgate);
            host_up.resize((size_t)cgate);
            host_down.resize((size_t)cdown);
        } catch (...) {
            return 0;
        }

        g_q1_0_direct_pread_fallbacks++;
        for (uint32_t i = 0; i < compact_count; i++) {
            const uint32_t expert = (uint32_t)compact[i];
            const uint64_t gate_src = gate_offset +
                (uint64_t)expert * gate_expert_bytes;
            const uint64_t up_src = up_offset +
                (uint64_t)expert * gate_expert_bytes;
            const uint64_t down_src = down_offset +
                (uint64_t)expert * down_expert_bytes;
            if (gate_src > g_q1_0_sidecar_size ||
                gate_expert_bytes > g_q1_0_sidecar_size - gate_src ||
                up_src > g_q1_0_sidecar_size ||
                gate_expert_bytes > g_q1_0_sidecar_size - up_src ||
                down_src > g_q1_0_sidecar_size ||
                down_expert_bytes > g_q1_0_sidecar_size - down_src) {
                return 0;
            }
            if (!cuda_pread_full(
                    &g_q1_0_sidecar_file,
                    host_gate.data() + (uint64_t)i * gate_expert_bytes,
                    gate_expert_bytes, gate_src) ||
                !cuda_pread_full(
                    &g_q1_0_sidecar_file,
                    host_up.data() + (uint64_t)i * gate_expert_bytes,
                    gate_expert_bytes, up_src) ||
                !cuda_pread_full(
                    &g_q1_0_sidecar_file,
                    host_down.data() + (uint64_t)i * down_expert_bytes,
                    down_expert_bytes, down_src)) {
                return 0;
            }
        }

#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        cuda_g130_attribution_span h2d_previous = CUDA_G130_ATTRIB_NONE;
        if (attribution_state) {
            h2d_previous = cuda_g130_attribution_switch(
                attribution_state,
                CUDA_G130_ATTRIB_H2D_ENQUEUE);
        }
#endif
        const int fallback_h2d_ok =
            cuda_ok(cudaMemcpy(g_moe_gather.gate, host_gate.data(),
                               (size_t)cgate, cudaMemcpyHostToDevice),
                    "Q1_0 gate H2D") &&
            cuda_ok(cudaMemcpy(g_moe_gather.up, host_up.data(),
                               (size_t)cgate, cudaMemcpyHostToDevice),
                    "Q1_0 up H2D") &&
            cuda_ok(cudaMemcpy(g_moe_gather.down, host_down.data(),
                                (size_t)cdown, cudaMemcpyHostToDevice),
                    "Q1_0 down H2D") &&
            cuda_ok(cudaMemcpy(g_moe_gather.slot, slots.data(),
                                (size_t)slot_count * sizeof(int32_t),
                                cudaMemcpyHostToDevice),
                    "Q1_0 slots H2D");
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        if (attribution_state) {
            (void)cuda_g130_attribution_switch(
                attribution_state, h2d_previous);
        }
#endif
        if (!fallback_h2d_ok) {
            return 0;
        }
        g_q1_0_direct_pread_bytes += cgate * 2u + cdown;
    }

    g_moe_gather.slot_tensor.ptr = g_moe_gather.slot;
    g_moe_gather.slot_tensor.bytes = (uint64_t)slot_count * sizeof(int32_t);
    g_moe_gather.slot_tensor.owner = 0;
    g_moe_gather.mixed_direct_active = 0;
    g_moe_gather.direct_cache_active = 0;
    return 1;
}

template <bool G73, bool G132 = false>
static cuda_moe_expert_cache *cuda_moe_gpu_resident_routes_begin(
        uint32_t layer_index,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        uint32_t expert_in_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_expert,
        uint32_t n_tokens,
        ds4_gpu_spex_queue *spex_queue,
        ds4_gpu_g133_epoch g133_epoch,
        double absolute_deadline,
        uint32_t split_out_dim,
        uint32_t *sequence_out) {
    const int compose_requested = cuda_moe_prefill_tier_compose_requested();
    if (!cuda_moe_gpu_routes_requested() || !selected || !selected->ptr ||
        compose_requested < 0 ||
        !weights || !weights->ptr ||
        n_tokens != 1u || n_expert == 0u || n_expert > CUDA_MOE_ROUTE_COUNT ||
        layer_index >= CUDA_MOE_LAYER_COUNT || spex_queue ||
        cuda_moe_expert_cache_layer_top1() ||
        g_dynamic_arena_observer.enabled ||
        (g_prefill_mass_observer.enabled &&
         (!compose_requested ||
          !g_prefill_mass_observer.finalized ||
          !g_prefill_mass_observer.wrap_published)) ||
        g_reap_mass_observer.enabled ||
        expert_in_dim / CUDA_QK_K > 16u ||
        getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") != NULL ||
        getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") != NULL) {
        if (n_expert != CUDA_MOE_ROUTE_COUNT) {
            fprintf(stderr,
                    "ds4: [gpu-route-variable] result=begin-refused routes=%u "
                    "requested=%d selected=%d weights=%d tokens=%u layer=%u "
                    "spex=%d top1=%d arena_observer=%d prefill_observer=%d "
                    "prefill_finalized=%d prefill_wrapped=%d reap_observer=%d "
                    "xq_blocks=%u no_lut=%d no_sum6=%d compose=%d\n",
                    n_expert, cuda_moe_gpu_routes_requested(),
                    selected && selected->ptr, weights && weights->ptr,
                    n_tokens, layer_index, spex_queue != NULL,
                    cuda_moe_expert_cache_layer_top1(),
                    g_dynamic_arena_observer.enabled,
                    g_prefill_mass_observer.enabled,
                    g_prefill_mass_observer.finalized,
                    g_prefill_mass_observer.wrap_published,
                    g_reap_mass_observer.enabled,
                    expert_in_dim / CUDA_QK_K,
                    getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") != NULL,
                    getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") != NULL,
                    compose_requested);
        }
        return NULL;
    }
    cuda_moe_expert_cache *cache =
        cuda_moe_expert_cache_prepare(gate_expert_bytes, down_expert_bytes);
    if (!cache || !cache->route_thread_started ||
        !cache->route_worker_ready.load(std::memory_order_acquire) ||
        cache->route_worker_safe_leaked.load(std::memory_order_acquire) ||
        cache->route_worker_failed.load(std::memory_order_acquire) ||
        cache->route_stop.load(std::memory_order_acquire) ||
        cache->capacity < CUDA_MOE_ROUTE_COUNT ||
        !cache->device_slot_by_layer_expert || !cache->device_route_ptrs ||
        !cache->device_route_hit_mask ||
        !cache->route_ready_host || !cache->route_failed_host ||
        !cache->device_route_ready_sequence ||
        !cache->device_route_failed_sequence ||
        !cache->route_request_device) {
        if (n_expert != CUDA_MOE_ROUTE_COUNT) {
            fprintf(stderr,
                    "ds4: [gpu-route-variable] result=cache-refused routes=%u "
                    "cache=%d thread=%d ready=%d failed=%d stop=%d capacity=%u "
                    "slot_map=%d ptrs=%d hit_mask=%d ready_host=%d failed_host=%d "
                    "ready_dev=%d failed_dev=%d request_dev=%d\n",
                    n_expert, cache != NULL,
                    cache ? cache->route_thread_started : 0,
                    cache ? cache->route_worker_ready.load(
                        std::memory_order_acquire) : 0,
                    cache ? cache->route_worker_failed.load(
                        std::memory_order_acquire) : 0,
                    cache ? cache->route_stop.load(
                        std::memory_order_acquire) : 0,
                    cache ? cache->capacity : 0,
                    cache && cache->device_slot_by_layer_expert,
                    cache && cache->device_route_ptrs,
                    cache && cache->device_route_hit_mask,
                    cache && cache->route_ready_host,
                    cache && cache->route_failed_host,
                    cache && cache->device_route_ready_sequence,
                    cache && cache->device_route_failed_sequence,
                    cache && cache->route_request_device);
        }
        return NULL;
    }
    if (split_out_dim != 0u &&
        !cuda_moe_route_split_down_ensure(cache, split_out_dim)) {
        if (n_expert != CUDA_MOE_ROUTE_COUNT) {
            fprintf(stderr,
                    "ds4: [gpu-route-variable] result=split-buffer-refused "
                    "routes=%u out_dim=%u\n",
                    n_expert, split_out_dim);
        }
        return NULL;
    }
    uint64_t trace_position = 0u;
    const uint64_t trace_sample_id =
        cuda_decode_trace_route_context(
            layer_index, &trace_position);
    const uint64_t trace_prior_wait_started = trace_sample_id
        ? cuda_decode_trace_qpc_now_raw() : 0u;
    if (trace_sample_id) {
        cuda_decode_trace_layer_record *trace_record =
            cuda_decode_trace_request_layer(
                trace_sample_id, layer_index);
        if (trace_record) {
            trace_record->resolver_started_qpc =
                trace_prior_wait_started;
        }
    }
    const uint32_t prior_sequence =
        cache->route_submitted_sequence.load(std::memory_order_acquire);
    const uint64_t prior_generation =
        cache->route_submitted_generation.load(std::memory_order_acquire);
    if (prior_sequence != 0u || prior_generation != 0u) {
        const double consume_deadline = cuda_wall_sec() + 5.0;
        while (cache->route_consumed_sequence.load(
                   std::memory_order_acquire) != prior_sequence ||
               cache->route_consumed_generation.load(
                   std::memory_order_acquire) != prior_generation) {
            if (cache->route_stop.load(std::memory_order_acquire) ||
                cache->route_worker_failed.load(std::memory_order_acquire) ||
                cuda_wall_sec() >= consume_deadline) {
                fprintf(stderr,
                        "ds4: CUDA route request snapshot was not consumed "
                        "before reuse seq=%u generation=%llu\n",
                        prior_sequence,
                        (unsigned long long)prior_generation);
                (void)cuda_moe_route_mailbox_fail_closed(
                    cache, prior_sequence, prior_generation,
                    "request-consume-timeout");
                return NULL;
            }
#ifdef _WIN32
            (void)SwitchToThread();
#else
            usleep(0);
#endif
        }
    }
    if (trace_sample_id) {
        cuda_decode_trace_note_prior_queue(
            trace_sample_id, layer_index,
            trace_prior_wait_started,
            cuda_decode_trace_qpc_now_raw());
    }
    uint32_t sequence = ++cache->route_sequence;
    if (sequence == 0u) sequence = ++cache->route_sequence;
    if (cache->route_generation == UINT64_MAX) {
        (void)cuda_moe_route_mailbox_fail_closed(
            cache, sequence, cache->route_generation,
            "generation-overflow");
        return NULL;
    }
    const uint64_t generation = cache->route_generation + 1u;
    cuda_moe_route_mailbox_slot &mailbox =
        cache->route_mailbox[generation & 1u];
    const uint32_t mailbox_state =
        mailbox.state.load(std::memory_order_acquire);
    if (mailbox_state != CUDA_MOE_ROUTE_MAILBOX_FREE &&
        mailbox_state != CUDA_MOE_ROUTE_MAILBOX_CONSUMER_DONE) {
        (void)cuda_moe_route_mailbox_fail_closed(
            cache, sequence, generation, "slot-reuse-before-consumer-done");
        return NULL;
    }
    mailbox.generation.store(generation, std::memory_order_release);
    mailbox.state.store(
        CUDA_MOE_ROUTE_MAILBOX_GPU_WRITING, std::memory_order_release);
    const int nested_profile = g_nested_residual.profile_enabled &&
        cuda_nested_residual_gpu_cache_requested() &&
        cuda_nested_residual_layer_required(layer_index);
    const double route_begin_started =
        nested_profile ? cuda_wall_sec() : 0.0;
    const uint64_t trace_submit_started = trace_sample_id
        ? cuda_decode_trace_qpc_now_raw() : 0u;
    /* WORKER-PROF: l'istante di accodamento va pubblicato PRIMA del lancio.
     * Il resolver GPU puo' scrivere la sequence e svegliare il worker mentre
     * questo thread e' ancora dentro cudaGetLastError(); pubblicarlo dopo
     * significherebbe far leggere al worker il timestamp della richiesta
     * precedente. */
    ds4_workerprof_publish_submit(
        cuda_worker_profile_enabled(), sequence);
    moe_resolve_resident_routes_kernel<<<1, 1>>>(
        cache->device_route_ptrs,
        cache->device_route_hit_mask,
        cache->device_route_ready_sequence,
        cache->route_request_device,
        (const int32_t *)selected->ptr,
        (const float *)weights->ptr,
        cache->device_slot_by_layer_expert,
        layer_index,
        sequence,
        generation,
        trace_sample_id,
        trace_position,
        trace_submit_started,
        cache->gate,
        cache->up,
        cache->down,
        gate_offset,
        up_offset,
        down_offset,
        gate_expert_bytes,
        down_expert_bytes,
        g133_epoch,
        absolute_deadline,
        G73 ? 1u : 0u,
        G132 ? 1u : 0u,
        n_expert);
    const cudaError_t resolve_launch_error = cudaGetLastError();
    if (trace_sample_id) {
        cuda_decode_trace_note_resolver_submit(
            trace_sample_id, layer_index,
            trace_submit_started,
            cuda_decode_trace_qpc_now_raw());
    }
    if (nested_profile) {
        g_nested_residual.profile_route_begin_calls++;
        g_nested_residual.profile_route_begin_seconds +=
            cuda_wall_sec() - route_begin_started;
    }
    if (resolve_launch_error != cudaSuccess) {
        mailbox.state.store(
            CUDA_MOE_ROUTE_MAILBOX_FREE, std::memory_order_release);
        mailbox.generation.store(0u, std::memory_order_release);
        if (n_expert != CUDA_MOE_ROUTE_COUNT) {
            fprintf(stderr,
                    "ds4: [gpu-route-variable] result=resolve-launch-failed "
                    "routes=%u error=%s\n",
                    n_expert, cudaGetErrorString(resolve_launch_error));
        }
        return NULL;
    }
    cache->route_generation = generation;
    cache->route_submitted_sequence.store(
        sequence, std::memory_order_release);
    cache->route_submitted_generation.store(
        generation, std::memory_order_release);
    if (sequence_out) *sequence_out = sequence;
    return cache;
}

template <bool G73, bool DOV = false>
static cuda_moe_expert_cache *cuda_moe_gpu_resident_routes_finish(
        cuda_moe_expert_cache *cache,
        uint32_t sequence,
        uint32_t layer_index,
        int split_mode,
        uint32_t split_out_dim,
        double absolute_deadline) {
    if (!cache || sequence == 0u) return NULL;
    const int nested_profile = g_nested_residual.profile_enabled &&
        cuda_nested_residual_gpu_cache_requested() &&
        cuda_nested_residual_layer_required(layer_index);
    uint64_t trace_position = 0u;
    const uint64_t trace_sample_id =
        cuda_decode_trace_route_context(
            layer_index, &trace_position);
    (void)trace_position;
    const uint64_t trace_stream_started = trace_sample_id
        ? cuda_decode_trace_qpc_now_raw() : 0u;
    uint64_t trace_stream_ticks = 0u;
    int trace_stream_waited = 0;
    if (cuda_moe_route_no_default_sync_requested()) {
        cache->route_no_default_sync_calls++;
    } else {
        cache->route_default_sync_calls++;
        trace_stream_waited = 1;
        const double resolve_started = cuda_wall_sec();
        if constexpr (DOV) {
            /* DRAIN4: questa sync (gia' cronometrata in
             * route_resolve_sync_seconds) e' il punto dove uno stallo GPU
             * attribuibile al drain spostato diventa attesa host: con il
             * fence, stream 0 completa solo dopo l'upload della generazione
             * precedente.  Campionamento host-side, nessun evento CUDA. */
            cuda_moe_drain_overlap4_consumer_sync_enter();
        }
        /* Preserve the original OFF synchronization exactly. Only the G73
         * specialization polls to its serving deadline and falls through. */
        const cudaError_t resolve_err = G73
            ? cuda_g73_finish_launched_copy(
                  0, absolute_deadline, layer_index,
                  "route-resolver-default")
            : cudaStreamSynchronize(0);
        const double resolve_seconds = cuda_wall_sec() - resolve_started;
        if constexpr (DOV) {
            cuda_moe_drain_overlap4_consumer_sync_exit();
        }
        cache->route_resolve_sync_seconds += resolve_seconds;
        if (nested_profile) {
            g_nested_residual.profile_route_resolve_sync_calls++;
            g_nested_residual.profile_route_resolve_sync_seconds +=
                resolve_seconds;
        }
        if (resolve_err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: CUDA GPU-resident route resolver sync failed: %s\n",
                    cudaGetErrorString(resolve_err));
            if (G73 && resolve_err == cudaErrorNotReady) {
                if (cuda_moe_route_worker_cancel_and_join(
                        cache, sequence, absolute_deadline)) {
                    cuda_moe_expert_cache_invalidate(
                        "consumer-resolver-notready");
                }
                return NULL;
            }
            abort();
        }
    }
    if (trace_stream_started && trace_stream_waited) {
        trace_stream_ticks =
            cuda_decode_trace_qpc_now_raw() - trace_stream_started;
    }
    const double wait_started = cuda_wall_sec();
    /* WORKER-PROF: da qui parte esattamente il numero che diventa
     * worker_wait_ms.  Pubblicarlo permette al worker di datare il proprio
     * pickup rispetto allo stesso istante, e quindi di dire quanta parte
     * dell'attesa precede il suo primo battito. */
    const int wprof = cuda_worker_profile_enabled();
    ds4_workerprof_publish_wait_start(wprof, sequence, wait_started);
    const uint64_t trace_ready_started = trace_sample_id
        ? cuda_decode_trace_qpc_now_raw() : 0u;
    uint64_t trace_ready_polls = 0u;
    const int staged_kv_service_deadline =
        G73 && absolute_deadline <= 0.0 &&
        ds4_gpu_should_use_staged_kv_cache();
    const double transient_stall_seconds = staged_kv_service_deadline
        ? cuda_g133_transient_io_timeout_seconds() : 5.0;
    double wait_deadline = staged_kv_service_deadline
        ? 0.0 : wait_started + 5.0;
    uint64_t last_read_progress = 0u;
    int transient_read_observed = 0;
    uint32_t transient_timeout_recovery_sequence = 0u;
    double transient_timeout_recovery_deadline = 0.0;
    while (*(volatile uint32_t *)cache->route_ready_host != sequence) {
        if (trace_sample_id) trace_ready_polls++;
        if (cache->route_stop.load(std::memory_order_acquire) ||
            cache->route_worker_failed.load(std::memory_order_acquire)) {
            fprintf(stderr,
                    "ds4: CUDA GPU-resident route resolver lost worker seq=%u\n",
                    sequence);
            if (cuda_moe_route_worker_cancel_and_join(
                    cache, sequence, cache->route_transient_read_deadline)) {
                cuda_moe_expert_cache_invalidate("consumer-worker-lost");
            }
            return NULL;
        }
        const double now = cuda_wall_sec();
        const int transient_published_now =
            cache->route_transient_read_sequence.load(
                std::memory_order_acquire) == sequence;
        const int transient_active_now = transient_published_now &&
            (!staged_kv_service_deadline ||
             cache->route_transient_io_sequence.load(
                 std::memory_order_acquire) == sequence);
        if (staged_kv_service_deadline && transient_read_observed &&
            !transient_active_now) {
            /* GPU scheduling and H2D are outside the expert-I/O watchdog. */
            transient_read_observed = 0;
            wait_deadline = 0.0;
        }
        if (transient_active_now && !transient_read_observed) {
            /* Establish a request-local baseline after the worker's release
             * publication. Bytes never reset again for this request. */
            last_read_progress = cache->route_transient_read_bytes.load(
                std::memory_order_acquire);
            transient_read_observed = 1;
            wait_deadline = now + transient_stall_seconds;
        }
        const double transient_absolute_deadline = transient_active_now
            ? cache->route_transient_read_deadline : 0.0;
        if (transient_active_now && transient_absolute_deadline > 0.0 &&
            wait_deadline > transient_absolute_deadline) {
            wait_deadline = transient_absolute_deadline;
        }
        if (transient_active_now && transient_absolute_deadline > 0.0 &&
            now >= transient_absolute_deadline) {
            if (transient_timeout_recovery_sequence == sequence) {
                if (now < transient_timeout_recovery_deadline) {
                    /* The deadline cancellation has been delivered without
                     * stopping the worker. Give it the ordinary stall window
                     * to enter and make progress in the no-deadline fallback. */
                    continue;
                }
                if (cuda_moe_route_worker_cancel_and_join(
                        cache, sequence, transient_absolute_deadline)) {
                    cuda_moe_expert_cache_invalidate(
                        "consumer-transient-recovery-stall");
                }
                return NULL;
            }
            const uint64_t progress = cache->route_transient_read_bytes.load(
                std::memory_order_acquire);
            fprintf(stderr,
                    "ds4: CUDA transient route read reached absolute "
                    "deadline seq=%u bytes=%llu\n",
                    sequence, (unsigned long long)progress);
            if (cuda_moe_transient_timeout_cancel_for_fallback(
                    cache, sequence)) {
                transient_timeout_recovery_sequence = sequence;
                transient_timeout_recovery_deadline =
                    now + transient_stall_seconds;
                wait_deadline = transient_timeout_recovery_deadline;
                continue;
            }
            if (cuda_moe_route_worker_cancel_and_join(
                    cache, sequence, transient_absolute_deadline)) {
                cuda_moe_expert_cache_invalidate(
                    "consumer-transient-deadline");
            }
            return NULL;
        }
        if (wait_deadline > 0.0 && now >= wait_deadline) {
            if (transient_active_now) {
                const uint64_t progress =
                    cache->route_transient_read_bytes.load(
                        std::memory_order_acquire);
                if ((transient_absolute_deadline <= 0.0 ||
                     now < transient_absolute_deadline) &&
                    progress > last_read_progress) {
                    last_read_progress = progress;
                    wait_deadline = now + transient_stall_seconds;
                    if (transient_absolute_deadline > 0.0 &&
                        wait_deadline > transient_absolute_deadline) {
                        wait_deadline = transient_absolute_deadline;
                    }
                    continue;
                }
                fprintf(stderr,
                        "ds4: CUDA transient route read timed out seq=%u "
                        "bytes=%llu absolute_deadline=%.3f\n",
                        sequence, (unsigned long long)progress,
                        transient_absolute_deadline);
                const double cancel_deadline = transient_absolute_deadline > 0.0
                    ? transient_absolute_deadline : now;
                if (cuda_moe_route_worker_cancel_and_join(
                        cache, sequence, cancel_deadline)) {
                    cuda_moe_expert_cache_invalidate(
                        "consumer-transient-stall");
                }
                return NULL;
            }
            fprintf(stderr,
                    "ds4: CUDA GPU-resident route worker starved seq=%u; "
                    "falling through to the exact terminal\n",
                    sequence);
            if (cuda_moe_route_worker_cancel_and_join(
                    cache, sequence, now)) {
                cuda_moe_expert_cache_invalidate("consumer-starved");
            }
            return NULL;
        }
#ifdef _WIN32
        (void)SwitchToThread();
#else
        usleep(0);
#endif
    }
#ifdef _WIN32
    MemoryBarrier();
#else
    __sync_synchronize();
#endif
    const double ready_wait_seconds = cuda_wall_sec() - wait_started;
    if (trace_sample_id) {
        cuda_decode_trace_note_resolver_wait(
            trace_sample_id, layer_index,
            trace_stream_ticks,
            cuda_decode_trace_qpc_now_raw() - trace_ready_started,
            trace_ready_polls);
    }
    cache->route_ready_wait_seconds += ready_wait_seconds;
    /* WORKER-PROF: chiusura della quadratura sulla STESSA grandezza che
     * alimenta worker_wait_ms, non su una sua copia rimisurata. */
    ds4_workerprof_note_wait(wprof, sequence, ready_wait_seconds);
    if (nested_profile) {
        g_nested_residual.profile_route_ready_wait_calls++;
        g_nested_residual.profile_route_ready_wait_seconds +=
            ready_wait_seconds;
    }
    if (*(volatile uint32_t *)cache->route_failed_host == sequence) {
        fprintf(stderr,
                "ds4: CUDA GPU-resident route resolver observed failure seq=%u; falling back\n",
                sequence);
        if (cuda_nested_residual_gpu_cache_requested() &&
            cuda_nested_residual_layer_required(layer_index)) {
            g_nested_residual.gpu_cache_failures++;
            g_nested_residual.hard_failure = 1;
        }
        if (cuda_g133_shared_policy_active() &&
            !cuda_moe_route_worker_drain_completed(
                "route-failure-invalidate")) {
            return NULL;
        }
        if (cuda_moe_route_failure_scoped_consume(sequence)) {
            /* INVALIDATE-SCOPED: il worker ha gia' eseguito e firmato il
             * rollback mirato delle sole voci toccate dalla richiesta
             * fallita; il reset totale qui sarebbe la punizione collettiva
             * che innesca la tempesta all-miss.  A flag spento la firma non
             * viene mai scritta e questo ramo e' morto. */
            return NULL;
        }
        cuda_moe_expert_cache_invalidate("consumer-route-failure");
        return NULL;
    }
    if constexpr (DOV) {
        /* DRAIN4 §3.1: fence dopo l'uscita dallo spin ready e il check di
         * route_failed_host.  Nei rami split (split_mode 1/2) il fence e'
         * rimandato al ramo split del launch impl — DOPO il kernel di
         * ownership del fix Fable e PRIMA della passata miss (§3.2), cosi'
         * il compute hit e il kernel Fable eseguono sotto le copie residue.
         * Su errore del waitEvent: fail-closed come i watchdog esistenti
         * (cancel_and_join quiesce l'upload stream prima dell'invalidate:
         * mai invalidare con copie in volo). */
        if (split_mode == 0 &&
            !cuda_moe_drain_overlap4_consumer_fence(
                cache, sequence, "finish-nonsplit")) {
            if (cuda_moe_route_worker_cancel_and_join(
                    cache, sequence, cuda_wall_sec())) {
                cuda_moe_expert_cache_invalidate("consumer-dov4-wait-event");
            }
            return NULL;
        }
    }
    const cuda_moe_route_request *request = cache->route_request_host;
    if (request && request->sequence == sequence &&
        request->host_generation ==
            cache->route_submitted_generation.load(
                std::memory_order_acquire) &&
        request->route_count > 0u &&
        request->route_count <= CUDA_MOE_ROUTE_COUNT &&
        request->layer_index == layer_index) {
        if (cuda_nested_residual_gpu_cache_requested() &&
            cuda_nested_residual_layer_required(layer_index)) {
            g_nested_residual.router_open_calls++;
            g_nested_residual.gpu_route_calls++;
            g_nested_residual.gpu_route_hits +=
                request->route_count - request->miss_count;
            g_nested_residual.gpu_route_misses += request->miss_count;
        }
        g_moe_last_selected.gate_offset = request->gate_offset;
        g_moe_last_selected.count = request->route_count;
        memcpy(g_moe_last_selected.ids, request->selected,
               request->route_count * sizeof(g_moe_last_selected.ids[0]));
        g_moe_last_selected.valid = 1;
    }
    if (sequence <= 2u) {
        fprintf(stderr,
                "ds4: [gpu-route-debug] submit seq=%u layer=%u\n",
                sequence, layer_index);
    }
    cache->route_calls++;
    if (split_mode == 1) {
        cache->route_split_calls++;
    } else if (split_mode == 2) {
        cache->route_split_fused_calls++;
        if (!request || request->sequence != sequence ||
            request->route_count == 0u ||
            request->route_count > CUDA_MOE_ROUTE_COUNT ||
            request->miss_count > request->route_count ||
            split_out_dim == 0u) {
            fprintf(stderr,
                    "ds4: CUDA fused split telemetry contract failed seq=%u\n",
                    sequence);
            if constexpr (DOV) {
                /* DRAIN4, chiusura difensiva di un buco che il disegno non
                 * copre: questo NULL arriva DOPO ready con worker sano e
                 * potenzialmente armato, e con G73 il chiamante prosegue il
                 * layer col replay esatto e registra il done-event.  Senza
                 * fence il done-event non proverebbe piu' il completamento
                 * degli upload (I3).  Fence best-effort; su errore,
                 * quiesce+invalidate come i watchdog. */
                if (!cuda_moe_drain_overlap4_consumer_fence(
                        cache, sequence, "fused-telemetry-contract")) {
                    if (cuda_moe_route_worker_cancel_and_join(
                            cache, sequence, cuda_wall_sec())) {
                        cuda_moe_expert_cache_invalidate(
                            "consumer-dov4-wait-event");
                    }
                }
            }
            return NULL;
        }
        const uint64_t misses = request->miss_count;
        const uint64_t hits = request->route_count - misses;
        cache->route_split_fused_hits += hits;
        cache->route_split_fused_misses += misses;
        cache->route_split_fused_miss_scratch_bytes_avoided +=
            misses * split_out_dim * sizeof(float);
        cache->route_split_fused_sum_read_bytes_avoided +=
            misses * split_out_dim * sizeof(float);
    }
    return cache;
}

template <bool G73, bool G132 = false, bool DOV = false>
static cuda_moe_expert_cache *cuda_moe_gpu_resident_routes_submit(
        uint32_t layer_index,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        uint32_t expert_in_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_expert,
        uint32_t n_tokens,
        ds4_gpu_spex_queue *spex_queue,
        ds4_gpu_g133_epoch g133_epoch,
        double absolute_deadline) {
    uint32_t sequence = 0;
    cuda_moe_expert_cache *cache = cuda_moe_gpu_resident_routes_begin<G73, G132>(
        layer_index, gate_offset, up_offset, down_offset,
        gate_expert_bytes, down_expert_bytes, expert_in_dim,
        selected, weights, n_expert, n_tokens, spex_queue, g133_epoch,
        absolute_deadline, 0u, &sequence);
    return cuda_moe_gpu_resident_routes_finish<G73, DOV>(
        cache, sequence, layer_index, 0, 0u, absolute_deadline);
}

static int cuda_g73_copy_selected_from_route_mailbox(
        cuda_moe_expert_cache *cache,
        uint32_t expected_sequence,
        uint32_t expected_layer,
        uint64_t expected_gate_offset,
        uint32_t expected_route_count,
        double absolute_deadline,
        int32_t *out_selected) {
    if (!cache || !cache->g73_host_selected_requested ||
        !cache->route_request_host || expected_sequence == 0u ||
        expected_route_count == 0u ||
        expected_route_count > CUDA_MOE_ROUTE_COUNT || !out_selected) {
        return 0;
    }

    const double wait_started = cuda_wall_sec();
    const double wait_deadline =
        absolute_deadline > 0.0 ? absolute_deadline : wait_started + 0.25;
    const uint64_t expected_generation =
        cache->route_submitted_generation.load(std::memory_order_acquire);
    if (expected_generation == 0u ||
        cache->route_submitted_sequence.load(std::memory_order_acquire) !=
            expected_sequence) {
        cache->g73_host_selected_fallbacks++;
        return 0;
    }

    while (*(volatile uint32_t *)&cache->route_request_host->sequence !=
           expected_sequence) {
        if (cache->route_stop.load(std::memory_order_acquire) ||
            cache->route_worker_failed.load(std::memory_order_acquire) ||
            cuda_wall_sec() >= wait_deadline) {
            cache->g73_host_selected_fallbacks++;
            return 0;
        }
#ifdef _WIN32
        (void)SwitchToThread();
#else
        usleep(0);
#endif
    }
#ifdef _WIN32
    MemoryBarrier();
#else
    __sync_synchronize();
#endif

    cuda_moe_route_request request;
    memcpy(&request, cache->route_request_host, sizeof(request));
    if (request.sequence != expected_sequence ||
        request.host_generation != expected_generation ||
        request.layer_index != expected_layer ||
        request.gate_offset != expected_gate_offset ||
        request.route_count != expected_route_count) {
        cache->g73_host_selected_fallbacks++;
        return 0;
    }
    for (uint32_t route = 0; route < expected_route_count; route++) {
        if (request.selected[route] < 0 ||
            (uint32_t)request.selected[route] >= 256u) {
            cache->g73_host_selected_fallbacks++;
            return 0;
        }
    }

    memcpy(out_selected, request.selected,
           (size_t)expected_route_count * sizeof(out_selected[0]));
    cache->g73_host_selected_reuse++;
    cache->g73_host_selected_wait_seconds +=
        cuda_wall_sec() - wait_started;
    return 1;
}

template <bool G73, bool G132 = false, bool DOV = false>
static int routed_moe_launch_impl(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *model_map,
        uint64_t model_size,
        uint32_t layer_index,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint32_t gate_type,
        uint32_t down_type,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *probs,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x,
        uint32_t n_tokens,
        ds4_gpu_spex_queue *spex_queue,
        const ds4_gpu_spex_key *spex_key,
        const int32_t *selected_host,
        ds4_gpu_g133_epoch g133_epoch) {
    const uint32_t original_n_expert = n_expert;
    ds4_gpu_tensor g132_general_weights_tensor = {};
    int g132_general_candidate = 0;
    int g132_general_active = 0;
    const double g73_absolute_deadline =
        G73 && n_tokens == 1u
        ? cuda_wall_sec() + cuda_g133_transient_io_timeout_seconds()
        : 0.0;
    const int staged_kv_service_deadline =
        G73 && n_tokens == 1u && ds4_gpu_should_use_staged_kv_cache();
    /* Keep the terminal's diagnostic budget above, but do not spend it on
     * resolver/H2D scheduling when staged KV is active. A zero request deadline
     * selects the worker-local, active-pread watchdog below. */
    const double route_io_deadline = G73
        ? (staged_kv_service_deadline
            ? 0.0
            : cuda_g73_io_deadline(g73_absolute_deadline))
        : g73_absolute_deadline;
    cuda_g73_route_outcomes g73_outcomes = {};
    int g73_outcomes_ready = 0;
    cuda_g73_terminal_mutex_guard g73_terminal_guard;
    g_moe_last_selected.valid = 0;
    /* Wave state belongs to this routed-MoE invocation. Decode can take the
     * resident-route path without calling selected-load, so stale prefill
     * activation must never survive into the next layer/token. Per-parity
     * compute ownership is persistent and is cleared only by the reuse fence
     * in cuda_moe_selected_stage_wave(). */
    g_moe_gather.wave_active = 0;
    g_moe_gather.wave_fail_closed = 0;
    g_moe_gather.wave_double_buffer = 0;
    for (uint32_t i = 0; i < 2u; i++) {
        g_moe_gather.wave_active_pairs_db[i] = 0;
        g_moe_gather.wave_current_experts_db[i] = 0;
    }
    if (!out || !gate || !up || !mid || !down || !model_map || !selected || !weights || !x ||
        n_tokens == 0 || n_expert == 0 ||
        expert_in_dim % CUDA_QK_K != 0 || expert_mid_dim % CUDA_QK_K != 0 ||
        gate_offset > model_size || up_offset > model_size || down_offset > model_size ||
        x->bytes < (uint64_t)n_tokens * expert_in_dim * sizeof(float) ||
        selected->bytes < (uint64_t)n_tokens * n_expert * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_tokens * n_expert * sizeof(float) ||
        gate->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        up->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        mid->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        down->bytes < (uint64_t)n_tokens * n_expert * out_dim * sizeof(float) ||
        out->bytes < (uint64_t)n_tokens * out_dim * sizeof(float)) {
        return 0;
    }
    const uint32_t route_iq2_q2 = gate_type == 16u && down_type == 10u;
    const uint32_t route_iq1_s =
        gate_type == 19u && (down_type == 19u || down_type == 10u);
    const uint32_t route_q1_0 =
        gate_type == 41u && (down_type == 41u || down_type == 10u);
    if (!route_iq2_q2 && !route_iq1_s && !route_q1_0) return 0;
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    cuda_g130_attribution_state *attribution_state =
        cuda_g130_attribution_token_state();
#endif
    if (route_iq1_s) {
        g_iq1_s_route_calls++;
        g_iq1_s_route_slots += (uint64_t)n_tokens * n_expert;
        if (getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL) {
            g_iq1_s_selected_load_failures++;
            fprintf(stderr,
                    "ds4: IQ1_S sidecar requires selected expert loading at layer=%u\n",
                    layer_index);
            return 0;
        }
    }
    if (route_q1_0) {
        g_q1_0_route_calls++;
        g_q1_0_route_slots += (uint64_t)n_tokens * n_expert;
        if (down_type != 41u) {
            g_q1_0_selected_load_failures++;
            fprintf(stderr,
                    "ds4: Q1_0 sidecar requires Q1_0 down tensor at layer=%u\n",
                    layer_index);
            return 0;
        }
        if (getenv("DS4_Q1_0_SELECTED_LOAD") == NULL ||
            getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL) {
            g_q1_0_selected_load_failures++;
            fprintf(stderr,
                    "ds4: Q1_0 sidecar requires opt-in selected expert loading at layer=%u\n",
                    layer_index);
            return 0;
        }
    }
    const uint32_t n_total_expert = 256u;
    const uint64_t gate_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_offset > model_size || gate_bytes > model_size - gate_offset ||
        up_offset > model_size || gate_bytes > model_size - up_offset ||
        down_offset > model_size || down_bytes > model_size - down_offset) {
        if constexpr (G73) {
            return cuda_g73_contract_error(
                layer_index, "model-range-contract");
        }
        return 0;
    }
    const int sparse_bake_layer =
        cuda_sparse_bake_layer_is_sparse(layer_index);
    if (sparse_bake_layer &&
        getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL) {
        fprintf(stderr,
                "ds4: sparse bake requires selected expert loading at layer=%u\n",
                layer_index);
        return 0;
    }
    if (sparse_bake_layer) {
        spex_queue = NULL;
        spex_key = NULL;
    }
    const char *gate_w = NULL;
    const char *up_w = NULL;
    const char *down_w = NULL;
    uint32_t use_mixed_route_ptrs = 0;
    uint32_t use_split_hit_miss = 0;
    uint32_t use_split_fused = 0;
    uint32_t gpu_route_sequence = 0;
    const uint64_t *mixed_route_ptrs = NULL;
    const int nested_layer_required =
        cuda_nested_residual_layer_required(layer_index);
    const int nested_gpu_cache_requested = nested_layer_required &&
        cuda_nested_residual_gpu_cache_requested();
    if (nested_layer_required &&
        (getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL ||
         getenv("DS4_CUDA_PREFILL_WAVES") != NULL ||
         spex_queue != NULL)) {
        g_nested_residual.failures++;
        g_nested_residual.hard_failure = 1;
        fprintf(stderr,
                "ds4: nested residual covered layer requires exclusive "
                "selected-load transport layer=%u\n",
                layer_index);
        return 0;
    }
    if (g_nested_residual.active && g_nested_residual.hard_failure) {
        fprintf(stderr,
                "ds4: nested residual request refused after hard failure\n");
        return 0;
    }
    /* Selected-expert load: when the whole 256-expert block is beyond the pinned
     * host window (streaming regime), fetch/gather ONLY the routed experts into a
     * compact VRAM buffer and rebind `selected` to compact slots -- the unchanged
     * MoE kernels then touch top-6 of 256 (~42x less streamed per layer). Falls
     * back to the whole-block path on failure or when fully in-window (zero-copy). */
    const int whole_in_window =
        !route_iq1_s && !route_q1_0 && !sparse_bake_layer &&
        !nested_layer_required &&
        cuda_model_range_in_window(model_map, gate_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, up_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, down_offset, down_bytes);
    cuda_moe_expert_cache *gpu_route_cache = NULL;
    const int split_hit_miss_requested =
        (route_iq1_s || route_q1_0) ? 0 :
            (G73 ? 0 : cuda_moe_split_hit_miss_requested());
    /* G73 phase 2: split-fused overlap is allowed because a late
     * miss-transport failure now replays the whole layer through the exact
     * terminal inside the split branch; legacy split-hit/miss stays closed. */
    const int split_fused_requested =
        (route_iq1_s || route_q1_0) ? 0 :
            cuda_moe_split_fused_requested();
    if (split_hit_miss_requested && split_fused_requested) {
        fprintf(stderr,
                "ds4: split hit/miss and fused split are mutually exclusive\n");
        return 0;
    }
    if (!route_iq1_s && !route_q1_0 &&
        (!nested_layer_required || nested_gpu_cache_requested) &&
        !whole_in_window &&
        getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") == NULL) {
        if (!sparse_bake_layer &&
            (split_hit_miss_requested || split_fused_requested) &&
            getenv("DS4_CUDA_MOE_PROFILE") == NULL) {
            gpu_route_cache = cuda_moe_gpu_resident_routes_begin<G73, G132>(
                layer_index,
                gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes,
                expert_in_dim,
                selected, weights, n_expert, n_tokens,
                spex_queue, g133_epoch, route_io_deadline,
                out_dim, &gpu_route_sequence);
            use_split_fused = gpu_route_cache != NULL && split_fused_requested;
            use_split_hit_miss = gpu_route_cache != NULL && split_hit_miss_requested;
        } else {
            gpu_route_cache = cuda_moe_gpu_resident_routes_submit<G73, G132, DOV>(
                layer_index,
                gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes,
                expert_in_dim,
                selected, weights, n_expert, n_tokens,
                spex_queue, g133_epoch, route_io_deadline);
        }
    }
    if (!route_iq1_s && !route_q1_0 &&
        (!nested_layer_required || nested_gpu_cache_requested) &&
        !gpu_route_cache && !whole_in_window && n_tokens == 1u &&
        (nested_gpu_cache_requested ||
         cuda_moe_tiering_mode_requested() != CUDA_MOE_TIER_OFF)) {
        if (nested_gpu_cache_requested) {
            g_nested_residual.gpu_cache_failures++;
            g_nested_residual.hard_failure = 1;
        }
        if constexpr (!G73) {
            fprintf(stderr,
                    "ds4: %s decode route unavailable at layer=%u; refusing fallback\n",
                    nested_gpu_cache_requested ?
                        "nested residual GPU-cache" : "expert tiering",
                    layer_index);
            return 0;
        }
        fprintf(stderr,
                "ds4: [g73-open] exact transient route unavailable at layer=%u; "
                "falling back to exact selected-load\n",
                layer_index);
    }
    if (gpu_route_cache) {
        if constexpr (G73) {
            /* Split paths defer outcome consumption until the delayed
             * finish() has observed worker publication (route_ready); after
             * begin() alone the outcomes are not yet published and this
             * check would race the worker. */
            if (!use_split_fused && !use_split_hit_miss) {
                const uint32_t expected_outcome_sequence =
                    gpu_route_sequence != 0u
                        ? gpu_route_sequence
                        : gpu_route_cache->route_submitted_sequence.load(
                            std::memory_order_acquire);
                if (gpu_route_cache->route_g73_outcome_sequence !=
                        expected_outcome_sequence) {
                    return cuda_g73_contract_error(
                        layer_index, "route-outcome-publication");
                }
                g73_outcomes = gpu_route_cache->route_g73_outcomes;
                g73_outcomes_ready = 1;
            }
        }
        gate_w = gpu_route_cache->gate;
        up_w = gpu_route_cache->up;
        down_w = gpu_route_cache->down;
        use_mixed_route_ptrs = 1;
        mixed_route_ptrs = gpu_route_cache->device_route_ptrs;
        if (getenv("DS4_IQ1_MIXED_DEBUG") &&
            n_expert != CUDA_MOE_ROUTE_COUNT) {
            uint64_t route_ptrs[CUDA_MOE_ROUTE_COUNT * 3u] = {0};
            if (cuda_ok(cudaMemcpy(
                            route_ptrs, mixed_route_ptrs,
                            (size_t)n_expert * 3u * sizeof(uint64_t),
                            cudaMemcpyDeviceToHost),
                        "iq1 mixed route pointers D2H")) {
                for (uint32_t route = 0; route < n_expert; route++) {
                    const uint64_t gate_ptr = route_ptrs[route];
                    const uint64_t up_ptr = route_ptrs[n_expert + route];
                    const uint64_t down_ptr = route_ptrs[2u * n_expert + route];
                    const uint64_t gate_base =
                        (uint64_t)(uintptr_t)gpu_route_cache->gate;
                    const uint64_t up_base =
                        (uint64_t)(uintptr_t)gpu_route_cache->up;
                    const uint64_t down_base =
                        (uint64_t)(uintptr_t)gpu_route_cache->down;
                    fprintf(stderr,
                            "ds4: [iq1-mixed-debug] phase=route-ptrs route=%u "
                            "gate_slot=%llu gate_rem=%llu up_slot=%llu up_rem=%llu "
                            "down_slot=%llu down_rem=%llu\n",
                            route,
                            (unsigned long long)((gate_ptr - gate_base) /
                                gate_expert_bytes),
                            (unsigned long long)((gate_ptr - gate_base) %
                                gate_expert_bytes),
                            (unsigned long long)((up_ptr - up_base) /
                                gate_expert_bytes),
                            (unsigned long long)((up_ptr - up_base) %
                                gate_expert_bytes),
                            (unsigned long long)((down_ptr - down_base) /
                                down_expert_bytes),
                            (unsigned long long)((down_ptr - down_base) %
                                down_expert_bytes));
                }
            }
        }
        if constexpr (G132) {
            if (!use_split_fused && !use_split_hit_miss &&
                route_iq2_q2 && n_tokens == 1u &&
                gpu_route_cache->route_cpu_plan.cpu_count != 0u) {
                g132_general_candidate = 1;
            }
        }
    } else if (route_q1_0) {
        cuda_q1_0_mixed_profile_sample *mixed_profile_sample =
            g_q1_0_mixed_profile_current_sample;
        if (mixed_profile_sample) {
            const double selected_started = cuda_wall_sec();
            mixed_profile_sample->q1_entry_calls++;
            mixed_profile_sample->q1_entry_seconds +=
                selected_started - mixed_profile_sample->q1_call_started;
            mixed_profile_sample->q1_prepare_started = selected_started;
        }
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        cuda_g130_attribution_span attribution_previous =
            CUDA_G130_ATTRIB_NONE;
        if (attribution_state) {
            attribution_previous = cuda_g130_attribution_switch(
                attribution_state,
                CUDA_G130_ATTRIB_SELECTED_LOAD);
        }
#endif
        const int selected_loaded = cuda_moe_selected_load_q1_0(
            model_map, model_size, layer_index,
            gate_offset, up_offset, down_offset,
            gate_expert_bytes, down_expert_bytes,
            n_total_expert, n_expert, n_tokens, selected, selected_host);
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        if (attribution_state) {
            (void)cuda_g130_attribution_switch(
                attribution_state, attribution_previous);
        }
#endif
        if (mixed_profile_sample) {
            const double selected_finished = cuda_wall_sec();
            mixed_profile_sample->q1_selected_load_calls++;
            mixed_profile_sample->q1_selected_load_seconds +=
                selected_finished - mixed_profile_sample->q1_prepare_started;
            mixed_profile_sample->q1_prepare_started = selected_finished;
        }
        if (selected_loaded) {
            g_q1_0_selected_loads++;
            gate_w = g_moe_gather.q1_active_gate ?
                g_moe_gather.q1_active_gate : g_moe_gather.gate;
            up_w = g_moe_gather.q1_active_up ?
                g_moe_gather.q1_active_up : g_moe_gather.up;
            down_w = g_moe_gather.q1_active_down ?
                g_moe_gather.q1_active_down : g_moe_gather.down;
            selected = &g_moe_gather.slot_tensor;
        } else {
            g_q1_0_selected_load_failures++;
            ds4_gpu_spex_queue_cancel(spex_queue, spex_key);
            fprintf(stderr,
                    "ds4: Q1_0 sidecar selected load failed closed at layer=%u\n",
                    layer_index);
            return 0;
        }
    } else if (!whole_in_window && getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") == NULL) {
        const int selected_loaded =
            cuda_moe_selected_load(model_map, model_size, layer_index,
                                   gate_offset, up_offset, down_offset,
                                   gate_expert_bytes, down_expert_bytes,
                                    expert_in_dim,
                                    n_total_expert, n_expert, n_tokens,
                                    selected, weights, probs,
                                     spex_queue, spex_key, route_iq1_s,
                                     G73
                                         ? cuda_g73_io_deadline(
                                               g73_absolute_deadline)
                                         : 0.0);
        if (route_iq1_s) {
            if (selected_loaded) g_iq1_s_selected_loads++;
            else g_iq1_s_selected_load_failures++;
        }
        if (!selected_loaded && !G73 &&
            (g_moe_gather.wave_fail_closed || nested_layer_required ||
             g_nested_residual.hard_failure)) {
            ds4_gpu_spex_queue_cancel(spex_queue, spex_key);
            if (nested_layer_required) {
                fprintf(stderr,
                        "ds4: nested residual selected load failed closed "
                        "at layer=%u\n",
                        layer_index);
            }
            return 0;
        }
        if (selected_loaded) {
            if constexpr (G73) {
                if (!cuda_g73_classify_fallback(
                    layer_index, g_moe_gather.h_sel.data(), n_expert,
                    0, &g73_outcomes)) {
                    return 0;
                }
                g73_outcomes_ready = 1;
            }
            if (g_moe_gather.direct_cache_active) {
                gate_w = g_moe_expert_cache.gate;
                up_w = g_moe_expert_cache.up;
                down_w = g_moe_expert_cache.down;
            } else {
                if (g_moe_gather.wave_double_buffer) {
                    gate_w = g_moe_gather.wave_gate[0];
                    up_w = g_moe_gather.wave_up[0];
                    down_w = g_moe_gather.wave_down[0];
                } else {
                    if (route_iq1_s && n_expert == 1u &&
                        g_moe_gather.iq1_active_gate &&
                        g_moe_gather.iq1_active_up &&
                        g_moe_gather.iq1_active_down) {
                        gate_w = g_moe_gather.iq1_active_gate;
                        up_w = g_moe_gather.iq1_active_up;
                        down_w = g_moe_gather.iq1_active_down;
                    } else {
                        gate_w = g_moe_gather.gate;
                        up_w = g_moe_gather.up;
                        down_w = g_moe_gather.down;
                    }
                }
            }
            use_mixed_route_ptrs = g_moe_gather.mixed_direct_active;
            mixed_route_ptrs = use_mixed_route_ptrs ? g_moe_gather.route_ptrs : NULL;
            selected = &g_moe_gather.slot_tensor;   /* kernels index compact slots */
        } else {
            ds4_gpu_spex_queue_cancel(spex_queue, spex_key);
            if constexpr (G73) {
                fprintf(stderr,
                        "ds4: [g73-open] bounded selected-load unavailable "
                        "at layer=%u; using preallocated exact terminal\n",
                        layer_index);
                if (!g73_terminal_guard.lock(&g_cuda_g73_terminal)) {
                    return cuda_g73_contract_error(
                        layer_index, "terminal-mutex");
                }
                if (!cuda_g73_terminal_exact_load(
                    model_map, model_size, layer_index,
                    gate_offset, up_offset, down_offset,
                    gate_expert_bytes, down_expert_bytes,
                    n_total_expert, n_expert, selected, &g73_outcomes,
                    g73_absolute_deadline)) {
                    return 0;
                }
                g73_outcomes_ready = 1;
                assert(g73_terminal_guard.held_for(&g_cuda_g73_terminal));
                gate_w = g_cuda_g73_terminal.device_slots;
                up_w = gate_w + gate_expert_bytes;
                down_w = up_w + gate_expert_bytes;
                use_mixed_route_ptrs = 1;
                mixed_route_ptrs = g_cuda_g73_terminal.device_route_ptrs;
            } else {
            if (nested_layer_required) {
                g_nested_residual.failures++;
                g_nested_residual.hard_failure = 1;
                fprintf(stderr,
                        "ds4: nested residual refused source fallback "
                        "at layer=%u\n",
                        layer_index);
                return 0;
            }
            if (route_iq1_s) {
                fprintf(stderr,
                        "ds4: IQ1_S sidecar selected load failed closed at layer=%u\n",
                        layer_index);
                return 0;
            }
            if (sparse_bake_layer) {
                fprintf(stderr,
                        "ds4: sparse bake selected load failed closed at layer=%u\n",
                        layer_index);
                return 0;
            }
            gate_w = cuda_model_range_ptr(model_map, gate_offset, gate_bytes, "moe_gate");
            up_w = cuda_model_range_ptr(model_map, up_offset, gate_bytes, "moe_up");
            down_w = cuda_model_range_ptr(model_map, down_offset, down_bytes, "moe_down");
            }
        }
    } else {
        ds4_gpu_spex_queue_cancel(spex_queue, spex_key);
        if (nested_layer_required) {
            g_nested_residual.failures++;
            g_nested_residual.hard_failure = 1;
            fprintf(stderr,
                    "ds4: nested residual refused whole-tensor fallback "
                    "at layer=%u\n",
                    layer_index);
            return 0;
        }
        gate_w = cuda_model_range_ptr(model_map, gate_offset, gate_bytes, "moe_gate");
        up_w = cuda_model_range_ptr(model_map, up_offset, gate_bytes, "moe_up");
        down_w = cuda_model_range_ptr(model_map, down_offset, down_bytes, "moe_down");
    }
    if constexpr (G73) {
        if (!gate_w || !up_w || !down_w) {
            if (!g73_terminal_guard.lock(&g_cuda_g73_terminal)) {
                return cuda_g73_contract_error(layer_index, "terminal-mutex");
            }
            if (!cuda_g73_terminal_exact_load(
                model_map, model_size, layer_index,
                gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes,
                n_total_expert, n_expert, selected, &g73_outcomes,
                g73_absolute_deadline)) {
                return 0;
            }
            g73_outcomes_ready = 1;
            assert(g73_terminal_guard.held_for(&g_cuda_g73_terminal));
            gate_w = g_cuda_g73_terminal.device_slots;
            up_w = gate_w + gate_expert_bytes;
            down_w = up_w + gate_expert_bytes;
            use_mixed_route_ptrs = 1;
            mixed_route_ptrs = g_cuda_g73_terminal.device_route_ptrs;
        }
    }
    if (!gate_w || !up_w || !down_w) return 0;
    if constexpr (G73) {
        if (!g73_outcomes_ready) {
            int32_t selected_fixed[CUDA_MOE_ROUTE_COUNT] = {0};
            const int reused_host_selected =
                gpu_route_cache && gpu_route_sequence != 0u &&
                cuda_g73_copy_selected_from_route_mailbox(
                    gpu_route_cache, gpu_route_sequence, layer_index,
                    gate_offset, n_expert, g73_absolute_deadline,
                    selected_fixed);
            if (!reused_host_selected) {
                if (gpu_route_cache) {
                    gpu_route_cache->g73_classification_d2h++;
                }
                const uint64_t trace_d2h_started =
                    cuda_decode_trace_route_context(
                        layer_index, NULL)
                    ? cuda_decode_trace_qpc_now_raw() : 0u;
                const cudaError_t classification_error =
                    cudaMemcpy(selected_fixed, selected->ptr,
                               (size_t)n_expert * sizeof(int32_t),
                               cudaMemcpyDeviceToHost);
                cuda_decode_trace_note_d2h(
                    layer_index, trace_d2h_started, 1u,
                    (uint64_t)n_expert * sizeof(int32_t),
                    classification_error == cudaSuccess);
                if (classification_error != cudaSuccess) {
                    cuda_g73_device_error(
                        layer_index, "whole-map-classification-d2h",
                        classification_error);
                }
            }
            if (!cuda_g73_classify_fallback(
                    layer_index, selected_fixed, n_expert,
                    1, &g73_outcomes)) {
                if constexpr (G132) {
                    if (g132_general_candidate) {
                        cuda_g132_general_plan_release(
                            gpu_route_cache,
                            &gpu_route_cache->route_cpu_plan);
                    }
                }
                return 0;
            }
            g73_outcomes_ready = 1;
        }
        if (gate_w == g_cuda_g73_terminal.device_slots ||
            mixed_route_ptrs == g_cuda_g73_terminal.device_route_ptrs) {
            /* Terminal storage is consumed by the launches below. Ownership
             * must extend through their enqueue, not merely through loading. */
            assert(g73_terminal_guard.held_for(&g_cuda_g73_terminal));
        }
    }

    if constexpr (G132) {
        if (g132_general_candidate) {
            uint32_t cpu_mask = 0u;
            uint32_t gpu_count = 0u;
            if (!cuda_g132_cpu_lane_prepare_general(
                    gpu_route_cache, layer_index,
                    gate_expert_bytes, gate_row_bytes,
                    down_expert_bytes, down_row_bytes,
                    expert_in_dim, expert_mid_dim, out_dim, clamp,
                    &cpu_mask, &gpu_count)) {
                g_g132_cpu_lane.general_fallback_contract++;
                cuda_g132_general_plan_release(
                    gpu_route_cache,
                    &gpu_route_cache->route_cpu_plan);
                return 0;
            }
            moe_g132_compact_gpu_routes_kernel<<<1, 1>>>(
                g_g132_cpu_lane.device_general_route_ptrs,
                g_g132_cpu_lane.device_general_weights,
                gpu_route_cache->device_route_ptrs,
                (const float *)weights->ptr,
                original_n_expert, cpu_mask, gpu_count);
            if (!cuda_ok(cudaGetLastError(),
                         "G132 general route compaction")) {
                g_g132_cpu_lane.general_fallback_runtime++;
                cuda_g132_cpu_lane_cancel_dispatch();
                return 0;
            }
            g132_general_weights_tensor.ptr =
                g_g132_cpu_lane.device_general_weights;
            g132_general_weights_tensor.host_ptr = NULL;
            g132_general_weights_tensor.bytes =
                (uint64_t)gpu_count * sizeof(float);
            g132_general_weights_tensor.owner = 0;
            mixed_route_ptrs =
                g_g132_cpu_lane.device_general_route_ptrs;
            weights = &g132_general_weights_tensor;
            n_expert = gpu_count;
            g132_general_active = 1;
        }
        if (g132_general_active &&
            !cuda_g132_cpu_lane_begin_general(x)) {
            cuda_g132_cpu_lane_cancel_dispatch();
            return 0;
        }
    }
    int ok = 1;
    const uint32_t xq_blocks = expert_in_dim / CUDA_QK_K;
    const uint32_t midq_blocks = expert_mid_dim / CUDA_QK_K;
    const uint64_t xq_count = (uint64_t)n_tokens * xq_blocks;
    const uint64_t midq_count = (uint64_t)n_tokens * n_expert * midq_blocks;
    const uint64_t xq_bytes = xq_count * sizeof(cuda_block_q8_K);
    const uint64_t midq_bytes = midq_count * sizeof(cuda_block_q8_K);
    if (down->bytes >= xq_bytes && gate->bytes >= midq_bytes) {
        const uint32_t pair_count = n_tokens * n_expert;
        cuda_block_q8_K *xq = (cuda_block_q8_K *)down->ptr;
        uint32_t *wave_pairs_dev = NULL;
        if (g_moe_gather.wave_active) {
            if (xq_bytes > UINT64_MAX - 255ull) return 0;
            const uint64_t xq_scratch_bytes = (xq_bytes + 255ull) & ~255ull;
            const uint64_t wave_pairs_bytes =
                (uint64_t)pair_count * sizeof(uint32_t);
            if (wave_pairs_bytes > UINT64_MAX - xq_scratch_bytes) return 0;
            uint8_t *wave_scratch = (uint8_t *)cuda_tmp_alloc(
                xq_scratch_bytes + wave_pairs_bytes,
                "routed_moe wave xq and pairs");
            if (!wave_scratch) return 0;
            xq = (cuda_block_q8_K *)wave_scratch;
            wave_pairs_dev = (uint32_t *)(wave_scratch + xq_scratch_bytes);
        }
        cuda_block_q8_K *midq = (cuda_block_q8_K *)gate->ptr;
        const uint32_t legacy_profile_moe =
            getenv("DS4_CUDA_MOE_PROFILE") != NULL;
        const uint32_t q1_profile_moe =
            route_q1_0 && cuda_q1_0_profile_requested();
        const uint32_t profile_moe =
            legacy_profile_moe || q1_profile_moe;
        cudaEvent_t prof_ev[7] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL};
        if (profile_moe) {
            for (uint32_t i = 0; i < 7u; i++) {
                if (cudaEventCreate(&prof_ev[i]) != cudaSuccess) {
                    for (uint32_t j = 0; j < i; j++) (void)cudaEventDestroy(prof_ev[j]);
                    memset(prof_ev, 0, sizeof(prof_ev));
                    if (q1_profile_moe) {
                        g_q1_0_profile.timer_failures++;
                        if (g_q1_0_mixed_profile_current_sample) {
                            cuda_q1_0_mixed_profile_record_timer_failure();
                        }
                    }
                    break;
                }
            }
            if (prof_ev[0]) (void)cudaEventRecord(prof_ev[0], 0);
        }
        const uint32_t use_sorted_pairs = n_tokens > 1u;
        const uint32_t use_expert_tiles = use_sorted_pairs && getenv("DS4_CUDA_MOE_NO_EXPERT_TILES") == NULL;
        const uint32_t expert_tile_m = getenv("DS4_CUDA_MOE_TILE4") ? 4u : 8u;
        const uint32_t write_gate_up = getenv("DS4_CUDA_MOE_WRITE_GATE_UP") != NULL;
        const uint32_t use_p2_sorted = use_sorted_pairs && getenv("DS4_CUDA_MOE_NO_P2") == NULL;
        const uint32_t use_atomic_down = use_expert_tiles &&
            (getenv("DS4_CUDA_MOE_ATOMIC_DOWN") != NULL ||
             (n_tokens >= 128u && getenv("DS4_CUDA_MOE_NO_ATOMIC_DOWN") == NULL));
        const uint32_t use_gate_row2048 = use_expert_tiles && expert_tile_m == 8u &&
            (getenv("DS4_CUDA_MOE_GATE_ROW2048") != NULL ||
             getenv("DS4_CUDA_MOE_GATE_ROW256") != NULL ||
             getenv("DS4_CUDA_MOE_GATE_ROW128") != NULL ||
             (n_tokens >= 128u &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW2048") == NULL &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW256") == NULL &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW128") == NULL));
        const uint32_t use_down_tile16 = use_atomic_down && expert_tile_m == 8u &&
            n_tokens >= 128u && getenv("DS4_CUDA_MOE_NO_DOWN_TILE16") == NULL;
        const uint32_t use_down_block16 = use_down_tile16 && midq_blocks <= 8u &&
            getenv("DS4_CUDA_MOE_NO_DOWN_BLOCK16") == NULL;
        const uint32_t use_decode_lut_gate =
            n_tokens == 1u && xq_blocks <= 16u &&
            getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") == NULL;
        const uint32_t gate_row_span =
            getenv("DS4_CUDA_MOE_GATE_ROW512") != NULL ? 512u :
            getenv("DS4_CUDA_MOE_GATE_ROW2048") != NULL ? 2048u : 1024u;
        const uint32_t down_row_span =
            getenv("DS4_CUDA_MOE_DOWN_ROW512") != NULL ? 512u :
            getenv("DS4_CUDA_MOE_DOWN_ROW1024") != NULL ? 1024u : 2048u;
        const uint32_t use_down_row2048 = use_atomic_down && expert_tile_m == 8u &&
            (getenv("DS4_CUDA_MOE_DOWN_ROW2048") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW256") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW128") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW64") != NULL ||
             (use_down_tile16 &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW2048") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW256") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW128") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW64") == NULL));
        const uint32_t use_direct_down_sum6 =
            n_tokens == 1u && n_expert == 6u &&
            getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") == NULL;
        uint32_t *sorted_pairs = NULL;
        uint32_t *sorted_offsets = NULL;
        uint32_t *sorted_counts = NULL;
        uint32_t *tile_total = NULL;
        uint32_t *tile_experts = NULL;
        uint32_t *tile_starts = NULL;
        uint32_t *tile16_total = NULL;
        uint32_t *tile16_experts = NULL;
        uint32_t *tile16_starts = NULL;
        uint32_t tile_capacity = 0;
        uint32_t tile16_capacity = 0;
        dim3 xq_grid(xq_blocks, n_tokens, 1);
        if (g_q1_0_mixed_profile_current_sample) {
            cuda_q1_0_mixed_profile_sample *mixed_profile_sample =
                g_q1_0_mixed_profile_current_sample;
            const double kernel_started = cuda_wall_sec();
            mixed_profile_sample->q1_prepare_calls++;
            mixed_profile_sample->q1_prepare_seconds +=
                kernel_started - mixed_profile_sample->q1_prepare_started;
            mixed_profile_sample->q1_kernel_started = kernel_started;
        }
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        cuda_g130_attribution_span kernel_attribution_previous =
            CUDA_G130_ATTRIB_NONE;
        if (route_q1_0 && attribution_state) {
            kernel_attribution_previous = cuda_g130_attribution_switch(
                attribution_state,
                CUDA_G130_ATTRIB_KERNEL_LAUNCH_ENQUEUE);
        }
#endif
        q8_K_quantize_kernel<<<xq_grid, 256>>>(
            xq, (const float *)x->ptr, expert_in_dim, n_tokens,
            NULL, 0u, 0u);
        ok = cuda_ok(cudaGetLastError(), "routed_moe x quantize launch");
        if (prof_ev[1]) (void)cudaEventRecord(prof_ev[1], 0);
        if (route_q1_0) {
            if (g_moe_gather.wave_active) ok = 0;
            if (prof_ev[2]) (void)cudaEventRecord(prof_ev[2], 0);
            if (ok) {
                dim3 mgrid((expert_mid_dim + 7u) / 8u,
                           pair_count, 1);
                moe_gate_up_mid_q1_0_qwarp32_kernel<<<mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    NULL,
                    xq,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    pair_count,
                    clamp);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe Q1_0 gate/up launch");
            }
            if (prof_ev[3]) (void)cudaEventRecord(prof_ev[3], 0);
            if (ok) {
                dim3 midq_grid(midq_blocks, pair_count, 1);
                q8_K_quantize_kernel<<<midq_grid, 256>>>(
                    midq, (const float *)mid->ptr, expert_mid_dim,
                    pair_count, NULL, 0u, 0u);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe Q1_0 mid quantize launch");
            }
            if (prof_ev[4]) (void)cudaEventRecord(prof_ev[4], 0);
            if (ok) {
                dim3 dgrid((out_dim + 7u) / 8u, pair_count, 1);
                moe_down_q1_0_qwarp32_kernel<<<dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    NULL,
                    midq,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert,
                    pair_count);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe Q1_0 down launch");
            }
            if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
            if (ok) {
                const uint64_t n = (uint64_t)n_tokens * out_dim;
                const uint32_t blocks = (uint32_t)((n + 255u) / 256u);
                moe_sum_kernel<<<blocks, 256>>>(
                    (float *)out->ptr, (const float *)down->ptr,
                    out_dim, n_expert, n_tokens);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe Q1_0 sum launch");
            }
            if (prof_ev[6]) {
                const cudaError_t record_error = cudaEventRecord(prof_ev[6], 0);
                const cudaError_t synchronize_error =
                    record_error == cudaSuccess ?
                        cudaEventSynchronize(prof_ev[6]) : record_error;
                if (synchronize_error == cudaSuccess) {
                    float ms_xq = 0.0f, ms_gate = 0.0f;
                    float ms_midq = 0.0f, ms_down = 0.0f;
                    float ms_sum = 0.0f, ms_total = 0.0f;
                    (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                    (void)cudaEventElapsedTime(&ms_gate, prof_ev[2], prof_ev[3]);
                    (void)cudaEventElapsedTime(&ms_midq, prof_ev[3], prof_ev[4]);
                    (void)cudaEventElapsedTime(&ms_down, prof_ev[4], prof_ev[5]);
                    (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                    const cudaError_t elapsed_error = cudaEventElapsedTime(
                        &ms_total, prof_ev[0], prof_ev[6]);
                    if (g_q1_0_mixed_profile_current_sample) {
                        cuda_q1_0_mixed_profile_sample *mixed_profile_sample =
                            g_q1_0_mixed_profile_current_sample;
                        mixed_profile_sample->q1_kernel_fenced_calls++;
                        if (elapsed_error == cudaSuccess) {
                            mixed_profile_sample->q1_kernel_device_calls++;
                            mixed_profile_sample->q1_kernel_device_seconds +=
                                (double)ms_total / 1000.0;
                        }
                    }
                    if (q1_profile_moe) {
                        if (elapsed_error == cudaSuccess) {
                            g_q1_0_profile.q1_kernel_calls++;
                            g_q1_0_profile.q1_kernel_seconds +=
                                (double)ms_total / 1000.0;
                        } else {
                            g_q1_0_profile.timer_failures++;
                            if (g_q1_0_mixed_profile_current_sample) {
                                cuda_q1_0_mixed_profile_record_timer_failure();
                            }
                        }
                    }
                    if (legacy_profile_moe) {
                        fprintf(stderr,
                                "ds4: CUDA Q1_0 MoE profile tokens=%u pairs=%u xq=%.3f gateup=%.3f midq=%.3f down=%.3f sum=%.3f total=%.3f ms\n",
                                n_tokens, pair_count, ms_xq, ms_gate, ms_midq,
                                ms_down, ms_sum, ms_total);
                    }
                } else if (q1_profile_moe) {
                    g_q1_0_profile.timer_failures++;
                    if (g_q1_0_mixed_profile_current_sample) {
                        cuda_q1_0_mixed_profile_record_timer_failure();
                    }
                }
                for (uint32_t i = 0; i < 7u; i++) {
                    (void)cudaEventDestroy(prof_ev[i]);
                }
            }
            if (g_q1_0_mixed_profile_current_sample) {
                cuda_q1_0_mixed_profile_sample *mixed_profile_sample =
                    g_q1_0_mixed_profile_current_sample;
                mixed_profile_sample->q1_kernel_calls++;
                mixed_profile_sample->q1_kernel_seconds +=
                    cuda_wall_sec() - mixed_profile_sample->q1_kernel_started;
            }
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
            if (attribution_state) {
                (void)cuda_g130_attribution_switch(
                    attribution_state,
                    kernel_attribution_previous);
            }
#endif
            return ok;
        }
        if (route_iq1_s) {
            if (ok && g_moe_gather.wave_active) {
                if (!wave_pairs_dev) ok = 0;
                const int wave_double_buffer =
                    g_moe_gather.wave_double_buffer != 0;
                for (uint32_t wave = 0; ok && wave < g_moe_gather.wave_count; wave++) {
                    const uint32_t parity = wave & 1u;
                    int wave_work_enqueued = 0;
                    const char *wave_gate_w = gate_w;
                    const char *wave_up_w = up_w;
                    const char *wave_down_w = down_w;
                    const int32_t *wave_selected =
                        (const int32_t *)selected->ptr;
                    uint32_t *wave_pairs_current = wave_pairs_dev;
                    cudaEvent_t wave_upload_ready =
                        g_moe_gather.wave_upload_ready;
                    std::vector<uint32_t> *wave_pairs_host =
                        &g_moe_gather.h_wave_pairs;
                    uint32_t wave_pair_count =
                        g_moe_gather.wave_active_pairs;
                    if (wave_double_buffer) {
                        wave_gate_w = g_moe_gather.wave_gate[parity];
                        wave_up_w = g_moe_gather.wave_up[parity];
                        wave_down_w = g_moe_gather.wave_down[parity];
                        wave_selected = g_moe_gather.wave_slot[parity];
                        wave_pairs_current = g_moe_gather.wave_pair[parity];
                        wave_upload_ready =
                            g_moe_gather.wave_upload_ready_db[parity];
                        wave_pairs_host =
                            &g_moe_gather.h_wave_pairs_db[parity];
                        wave_pair_count =
                            g_moe_gather.wave_active_pairs_db[parity];
                    }
                    if (!wave_double_buffer && wave != 0u) {
                        ok = cuda_ok(cudaStreamSynchronize(0),
                                     "moe IQ1_S wave execution sync");
                    }
                    if (ok && !wave_double_buffer && wave != 0u) {
                        ok = cuda_moe_selected_stage_wave(
                            model_map, layer_index,
                            gate_offset, up_offset, down_offset,
                            gate_expert_bytes, down_expert_bytes,
                            n_total_expert, n_expert, n_tokens, wave);
                        wave_pair_count = g_moe_gather.wave_active_pairs;
                    }
                    if (ok) {
                        ok = cuda_ok(cudaStreamWaitEvent(
                                         0, wave_upload_ready, 0),
                                     "moe IQ1_S wave upload wait");
                    }
                    if (!ok) break;
                    if (wave_pair_count == 0 ||
                        wave_pair_count > pair_count ||
                        wave_pairs_host->size() != wave_pair_count) {
                        ok = 0;
                        break;
                    }
                    if (!wave_double_buffer) {
                        ok = cuda_ok(cudaMemcpyAsync(
                                         wave_pairs_dev,
                                         wave_pairs_host->data(),
                                         (size_t)wave_pair_count * sizeof(uint32_t),
                                         cudaMemcpyHostToDevice, 0),
                                     "routed_moe IQ1_S wave pairs upload");
                    }
                    if (!ok) break;

                    dim3 mgrid((expert_mid_dim + 7u) / 8u,
                               wave_pair_count, 1);
                    moe_gate_up_mid_iq1_s_sorted_qwarp32_kernel<<<mgrid, 256>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        wave_gate_w,
                        wave_up_w,
                        xq,
                        wave_pairs_current,
                        wave_selected,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        clamp);
                    ok = cuda_ok(cudaGetLastError(),
                                 "routed_moe IQ1_S wave gate/up launch");
                    if (!ok) break;
                    wave_work_enqueued = 1;

                    dim3 midq_grid(midq_blocks, pair_count, 1);
                    q8_K_quantize_kernel<<<midq_grid, 256>>>(
                        midq, (const float *)mid->ptr, expert_mid_dim,
                        pair_count, NULL, 0u, 0u);
                    ok = cuda_ok(cudaGetLastError(),
                                 "routed_moe IQ1_S wave mid quantize launch");
                    if (!ok) {
                        if (wave_double_buffer && wave_work_enqueued) {
                            (void)cuda_moe_wave_compute_seal(parity);
                        }
                        break;
                    }

                    dim3 dgrid((out_dim + 7u) / 8u, wave_pair_count, 1);
                    if (down_type == 19u) {
                        moe_down_iq1_s_sorted_qwarp32_kernel<<<dgrid, 256>>>(
                            (float *)down->ptr,
                            wave_down_w,
                            midq,
                            wave_pairs_current,
                            wave_selected,
                            down_expert_bytes,
                            down_row_bytes,
                            midq_blocks,
                            out_dim,
                            n_expert);
                    } else {
                        moe_down_q2_K_route_sorted_qwarp32_kernel<<<dgrid, 256>>>(
                            (float *)down->ptr,
                            wave_down_w,
                            midq,
                            wave_pairs_current,
                            wave_selected,
                            down_expert_bytes,
                            down_row_bytes,
                            midq_blocks,
                            out_dim,
                            n_expert);
                    }
                    ok = cuda_ok(cudaGetLastError(),
                                 "routed_moe IQ1_S wave down launch");
                    if (!ok) {
                        if (wave_double_buffer && wave_work_enqueued) {
                            (void)cuda_moe_wave_compute_seal(parity);
                        }
                        break;
                    }
                    if (wave_double_buffer) {
                        ok = cuda_moe_wave_compute_seal(parity);
                        if (!ok) break;
                    }
                    if (wave_double_buffer) {
                        const uint32_t next_wave = wave + 1u;
                        if (next_wave < g_moe_gather.wave_count) {
                            ok = cuda_moe_selected_stage_wave(
                                model_map, layer_index,
                                gate_offset, up_offset, down_offset,
                                gate_expert_bytes, down_expert_bytes,
                                n_total_expert, n_expert, n_tokens, next_wave);
                            if (!ok) break;
                        }
                    }
                }
                if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
                if (ok) {
                    const uint64_t n = (uint64_t)n_tokens * out_dim;
                    const uint32_t blocks = (uint32_t)((n + 255u) / 256u);
                    moe_sum_kernel<<<blocks, 256>>>(
                        (float *)out->ptr, (const float *)down->ptr,
                        out_dim, n_expert, n_tokens);
                    ok = cuda_ok(cudaGetLastError(),
                                 "routed_moe IQ1_S wave sum launch");
                }
                if (prof_ev[6]) {
                    (void)cudaEventRecord(prof_ev[6], 0);
                    if (cudaEventSynchronize(prof_ev[6]) == cudaSuccess) {
                        float ms_xq = 0.0f, ms_waves = 0.0f;
                        float ms_sum = 0.0f, ms_total = 0.0f;
                        (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                        (void)cudaEventElapsedTime(&ms_waves, prof_ev[1], prof_ev[5]);
                        (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                        (void)cudaEventElapsedTime(&ms_total, prof_ev[0], prof_ev[6]);
                        fprintf(stderr,
                                "ds4: CUDA IQ1_S MoE wave profile tokens=%u pairs=%u waves=%u max_wave=%u xq=%.3f waves_ms=%.3f sum=%.3f total=%.3f ms\n",
                                n_tokens, pair_count, g_moe_gather.wave_count,
                                g_moe_gather.wave_max_experts, ms_xq,
                                ms_waves, ms_sum, ms_total);
                    }
                    for (uint32_t i = 0; i < 7u; i++) {
                        (void)cudaEventDestroy(prof_ev[i]);
                    }
                }
                return ok;
            }
            if (prof_ev[2]) (void)cudaEventRecord(prof_ev[2], 0);
            if (ok) {
                dim3 mgrid((expert_mid_dim + 7u) / 8u,
                           pair_count, 1);
                moe_gate_up_mid_iq1_s_qwarp32_kernel<<<mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    use_mixed_route_ptrs ? mixed_route_ptrs : NULL,
                    xq,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    pair_count,
                    clamp);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe IQ1_S gate/up launch");
            }
            if (prof_ev[3]) (void)cudaEventRecord(prof_ev[3], 0);
            if (ok) {
                dim3 midq_grid(midq_blocks, pair_count, 1);
                q8_K_quantize_kernel<<<midq_grid, 256>>>(
                    midq, (const float *)mid->ptr, expert_mid_dim,
                    pair_count, NULL, 0u, 0u);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe IQ1_S mid quantize launch");
            }
            if (prof_ev[4]) (void)cudaEventRecord(prof_ev[4], 0);
            if (ok) {
                dim3 dgrid((out_dim + 7u) / 8u, pair_count, 1);
                if (down_type == 19u) {
                    moe_down_iq1_s_qwarp32_kernel<<<dgrid, 256>>>(
                        (float *)down->ptr,
                        down_w,
                        use_mixed_route_ptrs ? mixed_route_ptrs : NULL,
                        midq,
                        (const int32_t *)selected->ptr,
                        down_expert_bytes,
                        down_row_bytes,
                        midq_blocks,
                        out_dim,
                        n_expert,
                        pair_count);
                } else {
                    moe_down_q2_K_route_qwarp32_kernel<<<dgrid, 256>>>(
                        (float *)down->ptr,
                        down_w,
                        use_mixed_route_ptrs ? mixed_route_ptrs : NULL,
                        midq,
                        (const int32_t *)selected->ptr,
                        down_expert_bytes,
                        down_row_bytes,
                        midq_blocks,
                        out_dim,
                        n_expert,
                        pair_count);
                }
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe IQ1_S down launch");
            }
            if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
            if (ok) {
                const uint64_t n = (uint64_t)n_tokens * out_dim;
                const uint32_t blocks = (uint32_t)((n + 255u) / 256u);
                moe_sum_kernel<<<blocks, 256>>>(
                    (float *)out->ptr, (const float *)down->ptr,
                    out_dim, n_expert, n_tokens);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe IQ1_S sum launch");
            }
            if (prof_ev[6]) {
                (void)cudaEventRecord(prof_ev[6], 0);
                if (cudaEventSynchronize(prof_ev[6]) == cudaSuccess) {
                    float ms_xq = 0.0f, ms_gate = 0.0f;
                    float ms_midq = 0.0f, ms_down = 0.0f;
                    float ms_sum = 0.0f, ms_total = 0.0f;
                    (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                    (void)cudaEventElapsedTime(&ms_gate, prof_ev[2], prof_ev[3]);
                    (void)cudaEventElapsedTime(&ms_midq, prof_ev[3], prof_ev[4]);
                    (void)cudaEventElapsedTime(&ms_down, prof_ev[4], prof_ev[5]);
                    (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                    (void)cudaEventElapsedTime(&ms_total, prof_ev[0], prof_ev[6]);
                    fprintf(stderr,
                            "ds4: CUDA IQ1_S MoE profile tokens=%u pairs=%u xq=%.3f gateup=%.3f midq=%.3f down=%.3f sum=%.3f total=%.3f ms\n",
                            n_tokens, pair_count, ms_xq, ms_gate, ms_midq,
                            ms_down, ms_sum, ms_total);
                }
                for (uint32_t i = 0; i < 7u; i++) {
                    (void)cudaEventDestroy(prof_ev[i]);
                }
            }
            return ok;
        }
        if (ok && g_moe_gather.wave_active) {
            if (!wave_pairs_dev) ok = 0;
            const int wave_double_buffer =
                g_moe_gather.wave_double_buffer != 0;
            for (uint32_t wave = 0; ok && wave < g_moe_gather.wave_count; wave++) {
                const uint32_t parity = wave & 1u;
                int wave_work_enqueued = 0;
                const char *wave_gate_w = gate_w;
                const char *wave_up_w = up_w;
                const char *wave_down_w = down_w;
                const int32_t *wave_selected =
                    (const int32_t *)selected->ptr;
                uint32_t *wave_pairs_current = wave_pairs_dev;
                cudaEvent_t wave_upload_ready =
                    g_moe_gather.wave_upload_ready;
                std::vector<uint32_t> *wave_pairs_host =
                    &g_moe_gather.h_wave_pairs;
                uint32_t wave_pair_count =
                    g_moe_gather.wave_active_pairs;
                if (wave_double_buffer) {
                    wave_gate_w = g_moe_gather.wave_gate[parity];
                    wave_up_w = g_moe_gather.wave_up[parity];
                    wave_down_w = g_moe_gather.wave_down[parity];
                    wave_selected = g_moe_gather.wave_slot[parity];
                    wave_pairs_current = g_moe_gather.wave_pair[parity];
                    wave_upload_ready =
                        g_moe_gather.wave_upload_ready_db[parity];
                    wave_pairs_host =
                        &g_moe_gather.h_wave_pairs_db[parity];
                    wave_pair_count =
                        g_moe_gather.wave_active_pairs_db[parity];
                }
                if (!wave_double_buffer && wave != 0u) {
                    ok = cuda_ok(cudaStreamSynchronize(0),
                                 "moe wave execution sync");
                }
                if (ok && !wave_double_buffer && wave != 0u) {
                    ok = cuda_moe_selected_stage_wave(
                        model_map, layer_index,
                        gate_offset, up_offset, down_offset,
                        gate_expert_bytes, down_expert_bytes,
                        n_total_expert, n_expert, n_tokens, wave);
                    wave_pair_count = g_moe_gather.wave_active_pairs;
                }
                if (ok) {
                    ok = cuda_ok(cudaStreamWaitEvent(
                                     0, wave_upload_ready, 0),
                                 "moe wave upload wait");
                }
                if (!ok) break;
                g_prefill_wave_stats.upload_waits =
                    cuda_u64_saturating_add(g_prefill_wave_stats.upload_waits, 1);
                if (wave_pair_count == 0 ||
                    wave_pair_count > pair_count ||
                    wave_pairs_host->size() != wave_pair_count) {
                    ok = 0;
                    break;
                }
                if (!wave_double_buffer) {
                    ok = cuda_ok(cudaMemcpyAsync(
                                     wave_pairs_dev,
                                     wave_pairs_host->data(),
                                     (size_t)wave_pair_count * sizeof(uint32_t),
                                     cudaMemcpyHostToDevice, 0),
                                 "routed_moe wave pairs upload");
                }
                if (!ok) break;

                dim3 mgrid((expert_mid_dim + 31u) / 32u,
                           wave_pair_count, 1);
                moe_gate_up_mid_sorted_qwarp32_kernel<<<mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    wave_gate_w,
                    wave_up_w,
                    xq,
                    wave_pairs_current,
                    wave_selected,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    clamp);
                ok = cuda_ok(cudaGetLastError(), "routed_moe wave gate/up launch");
                if (!ok) break;
                wave_work_enqueued = 1;

                dim3 midq_grid(midq_blocks, n_tokens * n_expert, 1);
                q8_K_quantize_kernel<<<midq_grid, 256>>>(
                    midq, (const float *)mid->ptr, expert_mid_dim,
                    n_tokens * n_expert, NULL, 0u, 0u);
                ok = cuda_ok(cudaGetLastError(), "routed_moe wave mid quantize launch");
                if (!ok) {
                    if (wave_double_buffer && wave_work_enqueued) {
                        (void)cuda_moe_wave_compute_seal(parity);
                    }
                    break;
                }

                dim3 dgrid((out_dim + 31u) / 32u, wave_pair_count, 1);
                moe_down_sorted_qwarp32_kernel<<<dgrid, 256>>>(
                    (float *)down->ptr,
                    wave_down_w,
                    midq,
                    wave_pairs_current,
                    wave_selected,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
                ok = cuda_ok(cudaGetLastError(), "routed_moe wave down launch");
                if (!ok) {
                    if (wave_double_buffer && wave_work_enqueued) {
                        (void)cuda_moe_wave_compute_seal(parity);
                    }
                    break;
                }
                if (wave_double_buffer) {
                    ok = cuda_moe_wave_compute_seal(parity);
                    if (!ok) break;
                }

                g_prefill_wave_stats.waves =
                    cuda_u64_saturating_add(g_prefill_wave_stats.waves, 1);
                g_prefill_wave_stats.active_pairs =
                    cuda_u64_saturating_add(g_prefill_wave_stats.active_pairs,
                                            wave_pair_count);
                if (wave_double_buffer) {
                    g_prefill_wave_overlap_stats.waves =
                        cuda_u64_saturating_add(
                            g_prefill_wave_overlap_stats.waves, 1);
                    const uint32_t next_wave = wave + 1u;
                    if (next_wave < g_moe_gather.wave_count) {
                        ok = cuda_moe_selected_stage_wave(
                            model_map, layer_index,
                            gate_offset, up_offset, down_offset,
                            gate_expert_bytes, down_expert_bytes,
                            n_total_expert, n_expert, n_tokens, next_wave);
                        if (!ok) break;
                    }
                }
            }
            if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
            if (ok) {
                uint64_t n = (uint64_t)n_tokens * out_dim;
                moe_sum_kernel<<<(n + 255) / 256, 256>>>(
                    (float *)out->ptr,
                    (const float *)down->ptr,
                    out_dim,
                    n_expert,
                    n_tokens);
                ok = cuda_ok(cudaGetLastError(), "routed_moe wave sum launch");
            }
            if (ok) {
                g_prefill_wave_stats.layers = cuda_u64_saturating_add(
                    g_prefill_wave_stats.layers, 1);
                if (wave_double_buffer) {
                    g_prefill_wave_overlap_stats.layers =
                        cuda_u64_saturating_add(
                            g_prefill_wave_overlap_stats.layers, 1);
                }
                if (getenv("DS4_CUDA_PREFILL_UNION_STATS") != NULL) {
                    g_prefill_union_stats.calls = cuda_u64_saturating_add(
                        g_prefill_union_stats.calls, 1);
                    g_prefill_union_stats.tokens = cuda_u64_saturating_add(
                        g_prefill_union_stats.tokens, n_tokens);
                    g_prefill_union_stats.selected_slots = cuda_u64_saturating_add(
                        g_prefill_union_stats.selected_slots, pair_count);
                    g_prefill_union_stats.unique_experts = cuda_u64_saturating_add(
                        g_prefill_union_stats.unique_experts,
                        g_moe_gather.wave_unique_experts);
                    g_prefill_union_stats.arena_experts = cuda_u64_saturating_add(
                        g_prefill_union_stats.arena_experts,
                        g_moe_gather.wave_arena_experts);
                    g_prefill_union_stats.direct_experts = cuda_u64_saturating_add(
                        g_prefill_union_stats.direct_experts,
                        g_moe_gather.wave_direct_experts);
                    g_prefill_union_stats.nonresident_experts = cuda_u64_saturating_add(
                        g_prefill_union_stats.nonresident_experts,
                        g_moe_gather.wave_direct_experts);
                    g_prefill_union_stats.source_span_bytes = cuda_u64_saturating_add(
                        g_prefill_union_stats.source_span_bytes,
                        g_moe_gather.wave_source_span_bytes);
                    g_prefill_union_stats.arena_h2d_bytes = cuda_u64_saturating_add(
                        g_prefill_union_stats.arena_h2d_bytes,
                        g_moe_gather.wave_arena_h2d_bytes);
                    if (n_tokens > g_prefill_union_stats.max_tokens) {
                        g_prefill_union_stats.max_tokens = n_tokens;
                    }
                    if (g_moe_gather.wave_unique_experts >
                        g_prefill_union_stats.max_union) {
                        g_prefill_union_stats.max_union =
                            g_moe_gather.wave_unique_experts;
                    }
                }
            } else {
                g_prefill_wave_stats.failures = cuda_u64_saturating_add(
                    g_prefill_wave_stats.failures, 1);
                if (wave_double_buffer) {
                    g_prefill_wave_overlap_stats.failures =
                        cuda_u64_saturating_add(
                            g_prefill_wave_overlap_stats.failures, 1);
                }
            }
            if (prof_ev[6]) {
                (void)cudaEventRecord(prof_ev[6], 0);
                if (cudaEventSynchronize(prof_ev[6]) == cudaSuccess) {
                    float ms_xq = 0.0f, ms_waves = 0.0f, ms_sum = 0.0f, ms_total = 0.0f;
                    (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                    (void)cudaEventElapsedTime(&ms_waves, prof_ev[1], prof_ev[5]);
                    (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                    (void)cudaEventElapsedTime(&ms_total, prof_ev[0], prof_ev[6]);
                    fprintf(stderr,
                            "ds4: CUDA MoE wave profile tokens=%u pairs=%u waves=%u max_wave=%u xq=%.3f waves_ms=%.3f sum=%.3f total=%.3f ms\n",
                            n_tokens, pair_count, g_moe_gather.wave_count,
                            g_moe_gather.wave_max_experts, ms_xq, ms_waves,
                            ms_sum, ms_total);
                }
                for (uint32_t i = 0; i < 7u; i++) (void)cudaEventDestroy(prof_ev[i]);
            }
            return ok;
        }
        if (ok && (use_split_hit_miss || use_split_fused)) {
            dim3 qgrid((expert_mid_dim + 127u) / 128u, n_expert, 1);
            dim3 midq_grid(midq_blocks, n_expert, 1);
            dim3 dgrid((out_dim + 31u) / 32u, n_expert, 1);
            const uint32_t *hit_mask = gpu_route_cache->device_route_hit_mask;
            float *split_down = gpu_route_cache->device_route_split_down;
            int g73_split_replay = 0;
            (void)g73_split_replay;

            moe_gate_up_mid_decode_ptrs_lut_qwarp32_kernel<<<qgrid, 256>>>(
                (float *)gate->ptr,
                (float *)up->ptr,
                (float *)mid->ptr,
                mixed_route_ptrs,
                xq,
                (const float *)weights->ptr,
                gate_row_bytes,
                xq_blocks,
                expert_mid_dim,
                n_expert,
                write_gate_up,
                clamp,
                hit_mask,
                1u);
            ok = cuda_ok(cudaGetLastError(), "routed_moe split hit gate/up launch");
            if (ok) {
                q8_K_quantize_kernel<<<midq_grid, 256>>>(
                    midq, (const float *)mid->ptr, expert_mid_dim, n_expert,
                    hit_mask, n_expert, 1u);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split hit mid quantize launch");
            }
            if (ok) {
                moe_down_ptrs_masked_qwarp32_kernel<<<dgrid, 256>>>(
                    split_down,
                    mixed_route_ptrs + 2u * n_expert,
                    midq,
                    hit_mask,
                    1u,
                    down_row_bytes,
                    midq_blocks,
                    out_dim);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split hit down launch");
            }

            {
                cuda_moe_expert_cache *finished_cache =
                    cuda_moe_gpu_resident_routes_finish<G73, DOV>(
                        gpu_route_cache, gpu_route_sequence, layer_index,
                        use_split_fused ? 2 : 1, out_dim, route_io_deadline);
                if (finished_cache) {
                    if constexpr (G73) {
                        /* Deferred outcome consumption: the worker published
                         * outcomes before route_ready, which finish() just
                         * observed. */
                        const uint32_t expected_outcome_sequence =
                            gpu_route_sequence != 0u
                                ? gpu_route_sequence
                                : finished_cache->route_submitted_sequence.load(
                                    std::memory_order_acquire);
                        if (finished_cache->route_g73_outcome_sequence !=
                                expected_outcome_sequence) {
                            return cuda_g73_contract_error(
                                layer_index, "route-outcome-publication");
                        }
                        g73_outcomes = finished_cache->route_g73_outcomes;
                        g73_outcomes_ready = 1;
                    }
                    gpu_route_cache = finished_cache;
                } else if constexpr (G73) {
                    /* Late miss-transport failure after the hit kernels
                     * launched: nothing from the worker is authoritative.
                     * Replay the WHOLE layer through the exact terminal;
                     * the earlier hit launches only wrote gate/up/mid and
                     * split_down scratch, which the replay overwrites in
                     * stream order. Worker outcomes are never committed. */
                    fprintf(stderr,
                            "ds4: [g73-open] split miss transport failed at "
                            "layer=%u; replaying via exact terminal\n",
                            layer_index);
                    if (!g73_terminal_guard.lock(&g_cuda_g73_terminal)) {
                        return cuda_g73_contract_error(
                            layer_index, "terminal-mutex");
                    }
                    if (!cuda_g73_terminal_exact_load(
                        model_map, model_size, layer_index,
                        gate_offset, up_offset, down_offset,
                        gate_expert_bytes, down_expert_bytes,
                        n_total_expert, n_expert, selected, &g73_outcomes,
                        g73_absolute_deadline)) {
                        return 0;
                    }
                    g73_outcomes_ready = 1;
                    assert(g73_terminal_guard.held_for(&g_cuda_g73_terminal));
                    mixed_route_ptrs = g_cuda_g73_terminal.device_route_ptrs;
                    g73_split_replay = 1;
                } else {
                    ok = 0;
                }
            }

            if constexpr (G132) {
                /* The route worker may have claimed CPU routes for this
                 * request: their route_ptrs were deliberately left at zero
                 * and their hit-mask bits at zero.  The miss kernels below
                 * select exactly the zero-bit slots, so a non-empty plan
                 * must be either attached or released here -- never left
                 * orphaned.  An orphaned plan would (a) let the miss
                 * kernels dereference the zero pointers (illegal memory
                 * access poisoning the whole context) and (b) keep its
                 * arena readers/staging lease, fail-closing every later
                 * mailbox claim. */
                if (gpu_route_cache->route_cpu_plan.cpu_count != 0u) {
                    if (!ok || g73_split_replay) {
                        /* finish() failed (worker joined or idle after a
                         * published failure) or the exact replay recomputes
                         * every route on the GPU: the plan is dead weight.
                         * Skip the release only when the cache was
                         * safe-leaked -- a detached worker may still own
                         * the plan, and safe-leak semantics leak. */
                        if (!gpu_route_cache->route_worker_safe_leaked.load(
                                std::memory_order_acquire)) {
                            cuda_g132_general_plan_release(
                                gpu_route_cache,
                                &gpu_route_cache->route_cpu_plan);
                        }
                    } else {
                        uint32_t g132_split_cpu_mask = 0u;
                        uint32_t g132_split_gpu_count = 0u;
                        if (!cuda_g132_cpu_lane_prepare_general(
                                gpu_route_cache, layer_index,
                                gate_expert_bytes, gate_row_bytes,
                                down_expert_bytes, down_row_bytes,
                                expert_in_dim, expert_mid_dim, out_dim,
                                clamp, &g132_split_cpu_mask,
                                &g132_split_gpu_count)) {
                            /* The worker already skipped the H2D for the
                             * claimed routes, so the GPU alone cannot
                             * finish this layer: fail closed. */
                            g_g132_cpu_lane.general_fallback_contract++;
                            cuda_g132_general_plan_release(
                                gpu_route_cache,
                                &gpu_route_cache->route_cpu_plan);
                            return 0;
                        }
                        g132_general_active = 1;
                        if (!cuda_g132_cpu_lane_begin_general(x)) {
                            cuda_g132_cpu_lane_cancel_dispatch();
                            return 0;
                        }
                        const uint64_t g132_split_slots =
                            (uint64_t)n_expert * out_dim;
                        moe_g132_split_own_cpu_routes_kernel<<<
                                (uint32_t)((g132_split_slots + 255u) / 256u),
                                256>>>(
                            split_down,
                            gpu_route_cache->device_route_hit_mask,
                            g132_split_cpu_mask,
                            n_expert,
                            out_dim);
                        if (!cuda_ok(cudaGetLastError(),
                                     "G132 split CPU route ownership")) {
                            g_g132_cpu_lane.general_fallback_runtime++;
                            cuda_g132_cpu_lane_cancel_dispatch();
                            return 0;
                        }
                    }
                }
            }

            if constexpr (DOV) {
                /* DRAIN4 §3.2: il fence del ramo split sta QUI — dopo la
                 * passata hit (gia' accodata prima del finish) e dopo il
                 * kernel di ownership del fix Fable (scrive hit-mask e
                 * split_down, stato per-richiesta gia' in VRAM: non legge
                 * gli slot in volo e resta sotto le copie), e PRIMA della
                 * passata miss, i cui kernel dereferenziano route_ptrs e
                 * slot in volo.  Nel replay G73 non c'e' nulla di armato
                 * per questa generazione (il worker ha fallito o e' stato
                 * cancellato con quiesce): fence non necessario.  Su errore
                 * del waitEvent: lane cancellata se attiva, poi fail-closed
                 * come i watchdog (quiesce prima dell'invalidate). */
                if (ok && !g73_split_replay &&
                    !cuda_moe_drain_overlap4_consumer_fence(
                        gpu_route_cache, gpu_route_sequence,
                        "split-before-miss-pass")) {
                    if constexpr (G132) {
                        if (g132_general_active) {
                            cuda_g132_cpu_lane_cancel_dispatch();
                        }
                    }
                    if (cuda_moe_route_worker_cancel_and_join(
                            gpu_route_cache, gpu_route_sequence,
                            cuda_wall_sec())) {
                        cuda_moe_expert_cache_invalidate(
                            "consumer-dov4-wait-event-split");
                    }
                    return 0;
                }
            }

            if (ok && g73_split_replay) {
                /* Full exact replay over the terminal route pointers: every
                 * route recomputed from the terminal slots, then summed. */
                moe_gate_up_mid_decode_ptrs_lut_qwarp32_kernel<<<qgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    mixed_route_ptrs,
                    xq,
                    (const float *)weights->ptr,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    write_gate_up,
                    clamp,
                    NULL,
                    0u);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe split replay gate/up launch");
                if (ok) {
                    q8_K_quantize_kernel<<<midq_grid, 256>>>(
                        midq, (const float *)mid->ptr, expert_mid_dim,
                        n_expert, NULL, n_expert, 1u);
                    ok = cuda_ok(cudaGetLastError(),
                                 "routed_moe split replay mid quantize launch");
                }
                /* The masked down kernel dereferences its mask, so two
                 * passes (hits then misses) cover every slot regardless of
                 * the stale mask contents. */
                if (ok) {
                    moe_down_ptrs_masked_qwarp32_kernel<<<dgrid, 256>>>(
                        split_down,
                        mixed_route_ptrs + 2u * n_expert,
                        midq,
                        hit_mask,
                        1u,
                        down_row_bytes,
                        midq_blocks,
                        out_dim);
                    ok = cuda_ok(cudaGetLastError(),
                                 "routed_moe split replay down hit-pass launch");
                }
                if (ok) {
                    moe_down_ptrs_masked_qwarp32_kernel<<<dgrid, 256>>>(
                        split_down,
                        mixed_route_ptrs + 2u * n_expert,
                        midq,
                        hit_mask,
                        0u,
                        down_row_bytes,
                        midq_blocks,
                        out_dim);
                    ok = cuda_ok(cudaGetLastError(),
                                 "routed_moe split replay down miss-pass launch");
                }
                if (ok) {
                    moe_sum_kernel<<<(out_dim + 255u) / 256u, 256>>>(
                        (float *)out->ptr,
                        split_down,
                        out_dim,
                        n_expert,
                        1u);
                    ok = cuda_ok(cudaGetLastError(),
                                 "routed_moe split replay sum launch");
                }
            }
            if (ok && !g73_split_replay) {
                moe_gate_up_mid_decode_ptrs_lut_qwarp32_kernel<<<qgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    mixed_route_ptrs,
                    xq,
                    (const float *)weights->ptr,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    write_gate_up,
                    clamp,
                    hit_mask,
                    0u);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split miss gate/up launch");
            }
            if (ok && !g73_split_replay) {
                q8_K_quantize_kernel<<<midq_grid, 256>>>(
                    midq, (const float *)mid->ptr, expert_mid_dim, n_expert,
                    hit_mask, n_expert, 0u);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split miss mid quantize launch");
            }
            if (ok && !g73_split_replay && !use_split_fused) {
                moe_down_ptrs_masked_qwarp32_kernel<<<dgrid, 256>>>(
                    split_down,
                    mixed_route_ptrs + 2u * n_expert,
                    midq,
                    hit_mask,
                    0u,
                    down_row_bytes,
                    midq_blocks,
                    out_dim);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split miss down launch");
            }
            if (ok && !g73_split_replay && use_split_fused) {
                dim3 fgrid((out_dim + 31u) / 32u, 1, 1);
                moe_down_split_fused_finish_qwarp32_kernel<<<fgrid, 256>>>(
                    (float *)out->ptr,
                    split_down,
                    mixed_route_ptrs + 2u * n_expert,
                    midq,
                    hit_mask,
                    down_row_bytes,
                    midq_blocks,
                    n_expert,
                    out_dim);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe fused split finish launch");
            }
            if (ok && !g73_split_replay && !use_split_fused) {
                moe_sum_kernel<<<(out_dim + 255u) / 256u, 256>>>(
                    (float *)out->ptr,
                    split_down,
                    out_dim,
                    n_expert,
                    1u);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split sum launch");
            }
            if constexpr (G73) {
                if (!g73_outcomes_ready) {
                    if constexpr (G132) {
                        if (g132_general_active) {
                            cuda_g132_cpu_lane_cancel_dispatch();
                        }
                    }
                    return cuda_g73_contract_error(
                        layer_index, "missing-split-launch-outcomes");
                }
                if (!ok) {
                    cuda_g73_device_error(layer_index, "split-exact-launch");
                }
                /* Exactly one commit per MoE call: worker outcomes on split
                 * success, terminal outcomes on replay - never both. */
                if (!cuda_g73_commit_outcomes(layer_index, g73_outcomes)) {
                    if constexpr (G132) {
                        if (g132_general_active) {
                            cuda_g132_cpu_lane_cancel_dispatch();
                        }
                    }
                    return 0;
                }
            }
            if constexpr (G132) {
                if (g132_general_active) {
                    if (!ok || !cuda_g132_cpu_lane_end_general_gpu()) {
                        cuda_g132_cpu_lane_cancel_dispatch();
                        return 0;
                    }
                    /* lane_econ: asynchronous join.  The old blocking join
                     * cost the caller thread ~1,1 ms/layer of pure serial
                     * time (28/7: the whole measured lane loss); the
                     * bridge-stream chain now owns the join and the caller
                     * returns right after the enqueue. */
                    if (!cuda_g132_cpu_lane_enqueue_join_general(
                            out, layer_index)) {
                        return 0;
                    }
                }
            }
            return ok;
        }
        if (ok && use_sorted_pairs) {
            const uint64_t counts_bytes = 256ull * sizeof(uint32_t);
            const uint64_t offsets_bytes = 257ull * sizeof(uint32_t);
            const uint64_t cursors_bytes = 256ull * sizeof(uint32_t);
            const uint64_t sorted_bytes = (uint64_t)pair_count * sizeof(uint32_t);
            tile_capacity = (pair_count + expert_tile_m - 1u) / expert_tile_m + 256u;
            tile16_capacity = use_down_tile16 ? ((pair_count + 15u) / 16u + 256u) : 0u;
            const uint64_t tile_offsets_bytes = 257ull * sizeof(uint32_t);
            const uint64_t tile_total_bytes = sizeof(uint32_t);
            const uint64_t tile_experts_bytes = (uint64_t)tile_capacity * sizeof(uint32_t);
            const uint64_t tile_starts_bytes = (uint64_t)tile_capacity * sizeof(uint32_t);
            const uint64_t tile16_offsets_bytes = use_down_tile16 ? 257ull * sizeof(uint32_t) : 0u;
            const uint64_t tile16_total_bytes = use_down_tile16 ? sizeof(uint32_t) : 0u;
            const uint64_t tile16_experts_bytes = (uint64_t)tile16_capacity * sizeof(uint32_t);
            const uint64_t tile16_starts_bytes = (uint64_t)tile16_capacity * sizeof(uint32_t);
            const uint64_t tile_offsets_off = counts_bytes + offsets_bytes + cursors_bytes + sorted_bytes;
            const uint64_t tile_total_off = tile_offsets_off + tile_offsets_bytes;
            const uint64_t tile_experts_off = tile_total_off + tile_total_bytes;
            const uint64_t tile_starts_off = tile_experts_off + tile_experts_bytes;
            const uint64_t tile16_offsets_off = tile_starts_off + tile_starts_bytes;
            const uint64_t tile16_total_off = tile16_offsets_off + tile16_offsets_bytes;
            const uint64_t tile16_experts_off = tile16_total_off + tile16_total_bytes;
            const uint64_t tile16_starts_off = tile16_experts_off + tile16_experts_bytes;
            const uint64_t scratch_bytes = tile16_starts_off + tile16_starts_bytes;
            uint8_t *scratch = (uint8_t *)cuda_tmp_alloc(scratch_bytes,
                                                         "routed_moe sorted pairs");
            if (!scratch) {
                ok = 0;
            } else {
                uint32_t *counts = (uint32_t *)scratch;
                uint32_t *offsets = (uint32_t *)(scratch + counts_bytes);
                uint32_t *cursors = (uint32_t *)(scratch + counts_bytes + offsets_bytes);
                sorted_pairs = (uint32_t *)(scratch + counts_bytes + offsets_bytes + cursors_bytes);
                sorted_offsets = offsets;
                sorted_counts = counts;
                uint32_t *tile_offsets = (uint32_t *)(scratch + tile_offsets_off);
                tile_total = (uint32_t *)(scratch + tile_total_off);
                tile_experts = (uint32_t *)(scratch + tile_experts_off);
                tile_starts = (uint32_t *)(scratch + tile_starts_off);
                uint32_t *tile16_offsets = use_down_tile16 ? (uint32_t *)(scratch + tile16_offsets_off) : NULL;
                tile16_total = use_down_tile16 ? (uint32_t *)(scratch + tile16_total_off) : NULL;
                tile16_experts = use_down_tile16 ? (uint32_t *)(scratch + tile16_experts_off) : NULL;
                tile16_starts = use_down_tile16 ? (uint32_t *)(scratch + tile16_starts_off) : NULL;
                ok = cuda_ok(cudaMemset(counts, 0, counts_bytes), "routed_moe sorted counts clear");
                if (ok) {
                    moe_count_sorted_pairs_kernel<<<(pair_count + 255u) / 256u, 256>>>(
                        counts,
                        (const int32_t *)selected->ptr,
                        pair_count);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted count launch");
                }
                if (ok) {
                    moe_prefix_sorted_pairs_kernel<<<1, 1>>>(offsets, cursors, counts);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted prefix launch");
                }
                if (ok) {
                    moe_scatter_sorted_pairs_kernel<<<(pair_count + 255u) / 256u, 256>>>(
                        sorted_pairs,
                        cursors,
                        (const int32_t *)selected->ptr,
                        pair_count);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted scatter launch");
                }
                if (ok && use_expert_tiles) {
                    moe_build_expert_tile_offsets_kernel<<<1, 1>>>(tile_offsets, tile_total, counts, expert_tile_m);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile offsets launch");
                }
                if (ok && use_expert_tiles) {
                    moe_build_expert_tiles_kernel<<<1, 256>>>(tile_experts, tile_starts, tile_offsets, counts, expert_tile_m);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tiles launch");
                }
                if (ok && use_expert_tiles && use_down_tile16) {
                    moe_build_expert_tile_offsets_kernel<<<1, 1>>>(tile16_offsets, tile16_total, counts, 16u);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile16 offsets launch");
                }
                if (ok && use_expert_tiles && use_down_tile16) {
                    moe_build_expert_tiles_kernel<<<1, 256>>>(tile16_experts, tile16_starts, tile16_offsets, counts, 16u);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile16 launch");
                }
            }
        }
        if (prof_ev[2]) (void)cudaEventRecord(prof_ev[2], 0);
        if (ok) {
            dim3 mgrid((expert_mid_dim + 31u) / 32u, n_tokens * n_expert, 1);
            if (ok && sorted_pairs && use_expert_tiles && sorted_offsets && sorted_counts && tile_total && tile_experts && tile_starts) {
                if (use_gate_row2048) {
                    if (gate_row_span == 512u) {
                        dim3 tgrid((expert_mid_dim + 511u) / 512u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_rowspan_kernel<512><<<tgrid, 256>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    } else if (gate_row_span == 1024u) {
                        dim3 tgrid((expert_mid_dim + 1023u) / 1024u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_rowspan_kernel<1024><<<tgrid, 256>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    } else {
                        dim3 tgrid((expert_mid_dim + 2047u) / 2048u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_row2048_kernel<<<tgrid, 256>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    }
                } else if (expert_tile_m == 8u) {
                    dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                    moe_gate_up_mid_expert_tile8_row32_kernel<<<tgrid, 256>>>(
                        (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                        gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                        tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                        gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                        write_gate_up, clamp);
                } else {
                    dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                    moe_gate_up_mid_expert_tile4_row32_kernel<<<tgrid, 256>>>(
                        (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                        gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                        tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                        gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                        write_gate_up, clamp);
                }
            } else if (ok && sorted_pairs && use_p2_sorted) {
                dim3 p2_mgrid((expert_mid_dim + 15u) / 16u, (pair_count + 1u) / 2u, 1);
                moe_gate_up_mid_sorted_p2_qwarp32_kernel<<<p2_mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    xq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    pair_count,
                    clamp);
            } else if (ok && sorted_pairs) {
                moe_gate_up_mid_sorted_qwarp32_kernel<<<mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    xq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    clamp);
            } else if (ok) {
                dim3 qgrid((expert_mid_dim + 127u) / 128u, n_tokens * n_expert, 1);
                if (use_mixed_route_ptrs) {
                    moe_gate_up_mid_decode_ptrs_lut_qwarp32_kernel<<<qgrid, 256>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        mixed_route_ptrs,
                        xq,
                        (const float *)weights->ptr,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        write_gate_up,
                        clamp,
                        NULL,
                        0u);
                } else if (use_decode_lut_gate) {
                    moe_gate_up_mid_decode_lut_qwarp32_kernel<<<qgrid, 256>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        write_gate_up,
                        clamp);
                } else {
                    moe_gate_up_mid_qwarp32_kernel<<<qgrid, 256>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        clamp);
                }
            }
            ok = cuda_ok(cudaGetLastError(), "routed_moe gate/up launch");
            if (ok && getenv("DS4_IQ1_MIXED_DEBUG") &&
                use_mixed_route_ptrs && n_expert != CUDA_MOE_ROUTE_COUNT) {
                ds4_gpu_tensor debug_mid = {
                    mid->ptr,
                    NULL,
                    (uint64_t)n_expert * expert_mid_dim * sizeof(float),
                    0
                };
                ok = cuda_iq1_mixed_debug_output(
                    "hot-mid", &debug_mid, n_expert * expert_mid_dim);
            }
        }
        if (prof_ev[3]) (void)cudaEventRecord(prof_ev[3], 0);
        if (ok) {
            dim3 midq_grid(midq_blocks, n_tokens * n_expert, 1);
            q8_K_quantize_kernel<<<midq_grid, 256>>>(
                midq, (const float *)mid->ptr, expert_mid_dim,
                n_tokens * n_expert, NULL, 0u, 0u);
            ok = cuda_ok(cudaGetLastError(), "routed_moe mid quantize launch");
        }
        if (prof_ev[4]) (void)cudaEventRecord(prof_ev[4], 0);
        if (ok) {
            dim3 dgrid((out_dim + 31u) / 32u, n_tokens * n_expert, 1);
            uint32_t *down_tile_total = tile_total;
            uint32_t *down_tile_experts = tile_experts;
            uint32_t *down_tile_starts = tile_starts;
            uint32_t down_tile_capacity = tile_capacity;
            if (use_down_tile16 && tile16_total && tile16_experts && tile16_starts) {
                down_tile_total = tile16_total;
                down_tile_experts = tile16_experts;
                down_tile_starts = tile16_starts;
                down_tile_capacity = tile16_capacity;
            }
            if (use_mixed_route_ptrs) {
                dim3 sgrid((out_dim + 31u) / 32u, 1, 1);
                moe_down_sum_ptrs_qwarp32_kernel<<<sgrid, 256>>>(
                    (float *)out->ptr,
                    mixed_route_ptrs + 2u * n_expert,
                    midq,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
            } else if (use_direct_down_sum6) {
                dim3 sgrid((out_dim + 31u) / 32u, 1, 1);
                moe_down_sum6_qwarp32_kernel<<<sgrid, 256>>>(
                    (float *)out->ptr,
                    down_w,
                    midq,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim);
            } else if (use_atomic_down) {
                uint64_t n = (uint64_t)n_tokens * out_dim;
                zero_kernel<<<(n + 255u) / 256u, 256>>>((float *)out->ptr, n);
                ok = cuda_ok(cudaGetLastError(), "routed_moe atomic zero launch");
            }
            if (use_mixed_route_ptrs || use_direct_down_sum6) {
                /* The direct decode kernel writes the final token row. */
            } else if (sorted_pairs && use_expert_tiles && sorted_offsets && sorted_counts &&
                down_tile_total && down_tile_experts && down_tile_starts) {
                if (use_down_row2048) {
                    if (down_row_span == 512u) {
                        dim3 tgrid((out_dim + 511u) / 512u, down_tile_capacity, 1);
                        if (use_down_block16) {
                            moe_down_expert_tile16_rowspan_block16_kernel<512><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        } else {
                            moe_down_expert_tile16_rowspan_kernel<512><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        }
                    } else if (down_row_span == 1024u) {
                        dim3 tgrid((out_dim + 1023u) / 1024u, down_tile_capacity, 1);
                        if (use_down_block16) {
                            moe_down_expert_tile16_rowspan_block16_kernel<1024><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        } else {
                            moe_down_expert_tile16_rowspan_kernel<1024><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        }
                    } else {
                        dim3 tgrid((out_dim + 2047u) / 2048u, down_tile_capacity, 1);
                        if (use_down_block16) {
                            moe_down_expert_tile16_rowspan_block16_kernel<2048><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        } else {
                            moe_down_expert_tile16_row2048_kernel<<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        }
                    }
                } else if (use_down_tile16) {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile16_row32_kernel<<<tgrid, 256>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                } else if (expert_tile_m == 8u) {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile8_row32_kernel<<<tgrid, 256>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                } else {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile4_row32_kernel<<<tgrid, 256>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                }
            } else if (sorted_pairs && use_p2_sorted) {
                dim3 p2_dgrid((out_dim + 15u) / 16u, (pair_count + 1u) / 2u, 1);
                moe_down_sorted_p2_qwarp32_kernel<<<p2_dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert,
                    pair_count);
            } else if (sorted_pairs) {
                moe_down_sorted_qwarp32_kernel<<<dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
            } else {
                moe_down_qwarp32_kernel<<<dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
            }
            ok = cuda_ok(cudaGetLastError(), "routed_moe down launch");
        }
        if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
        if (ok && !use_atomic_down && !use_direct_down_sum6 &&
            !use_mixed_route_ptrs) {
            uint64_t n = (uint64_t)n_tokens * out_dim;
            moe_sum_kernel<<<(n + 255) / 256, 256>>>((float *)out->ptr, (const float *)down->ptr, out_dim, n_expert, n_tokens);
            ok = cuda_ok(cudaGetLastError(), "routed_moe sum launch");
        }
        if (prof_ev[6]) {
            (void)cudaEventRecord(prof_ev[6], 0);
            if (cudaEventSynchronize(prof_ev[6]) == cudaSuccess) {
                float ms_xq = 0.0f, ms_sort = 0.0f, ms_gate = 0.0f, ms_midq = 0.0f, ms_down = 0.0f, ms_sum = 0.0f, ms_total = 0.0f;
                (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                (void)cudaEventElapsedTime(&ms_sort, prof_ev[1], prof_ev[2]);
                (void)cudaEventElapsedTime(&ms_gate, prof_ev[2], prof_ev[3]);
                (void)cudaEventElapsedTime(&ms_midq, prof_ev[3], prof_ev[4]);
                (void)cudaEventElapsedTime(&ms_down, prof_ev[4], prof_ev[5]);
                (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                (void)cudaEventElapsedTime(&ms_total, prof_ev[0], prof_ev[6]);
                fprintf(stderr,
                        "ds4: CUDA MoE profile tokens=%u pairs=%u xq=%.3f sort=%.3f gateup=%.3f midq=%.3f down=%.3f sum=%.3f total=%.3f ms\n",
                        n_tokens, pair_count, ms_xq, ms_sort, ms_gate, ms_midq, ms_down, ms_sum, ms_total);
            }
            for (uint32_t i = 0; i < 7u; i++) (void)cudaEventDestroy(prof_ev[i]);
        }
        if constexpr (G73) {
            if (!g73_outcomes_ready) {
                if constexpr (G132) {
                    if (g132_general_active) {
                        cuda_g132_cpu_lane_cancel_dispatch();
                    }
                }
                return cuda_g73_contract_error(
                    layer_index, "missing-launch-outcomes");
            }
            if (!ok) {
                cuda_g73_device_error(layer_index, "exact-gemv-launch");
            }
            /* Exactly one outcome per out-of-mask route is committed only
             * after every exact GEMV launch for this MoE call was accepted. */
            if (!cuda_g73_commit_outcomes(layer_index, g73_outcomes)) {
                if constexpr (G132) {
                    if (g132_general_active) {
                        cuda_g132_cpu_lane_cancel_dispatch();
                    }
                }
                return 0;
            }
        }
        if constexpr (G132) {
            if (g132_general_active) {
                if (!ok || !cuda_g132_cpu_lane_end_general_gpu()) {
                    cuda_g132_cpu_lane_cancel_dispatch();
                    return 0;
                }
                /* lane_econ: asynchronous join, same contract as the split
                 * consumer above. */
                if (!cuda_g132_cpu_lane_enqueue_join_general(
                        out, layer_index)) {
                    return 0;
                }
            }
        }
        return ok;
    }

    if (g_moe_gather.wave_active) return 0;

    if (ok) {
        dim3 mgrid(expert_mid_dim, n_tokens * n_expert, 1);
        moe_gate_up_mid_f32_kernel<<<mgrid, 256>>>(
            (float *)gate->ptr,
            (float *)up->ptr,
            (float *)mid->ptr,
            gate_w,
            up_w,
            (const float *)x->ptr,
            (const int32_t *)selected->ptr,
            (const float *)weights->ptr,
            gate_expert_bytes,
            gate_row_bytes,
            expert_in_dim,
            expert_mid_dim,
            n_expert,
            clamp);
        ok = cuda_ok(cudaGetLastError(), "routed_moe gate/up launch");
    }
    if (ok) {
        dim3 dgrid(out_dim, n_tokens * n_expert, 1);
        moe_down_f32_kernel<<<dgrid, 256>>>(
            (float *)down->ptr,
            down_w,
            (const float *)mid->ptr,
            (const int32_t *)selected->ptr,
            down_expert_bytes,
            down_row_bytes,
            expert_mid_dim,
            out_dim,
            n_expert);
        ok = cuda_ok(cudaGetLastError(), "routed_moe down launch");
    }
    if (ok) {
        uint64_t n = (uint64_t)n_tokens * out_dim;
        moe_sum_kernel<<<(n + 255) / 256, 256>>>((float *)out->ptr, (const float *)down->ptr, out_dim, n_expert, n_tokens);
        ok = cuda_ok(cudaGetLastError(), "routed_moe sum launch");
    }
    return ok;
}

/* One init-time dispatch is the entire G73 hot-route seam. The OFF target is
 * the compile-time-false M1 specialization: it contains no G73 flag load or
 * runtime G73 branch. The two former split-policy indirect calls are direct
 * calls inside that specialization, so this adds no net hot-route indirection. */
static auto g_cuda_routed_moe_launch_dispatch =
    &routed_moe_launch_impl<false>;
static auto g_cuda_routed_moe_general_launch_dispatch =
    &routed_moe_launch_impl<false, false>;

static void cuda_g73_route_dispatch_init(void) {
    const char *lane = getenv("DS4_G132_CPU_LANE");
    const char *general = getenv("DS4_G132_CPU_LANE_GENERAL");
    const int general_enabled =
        lane && strcmp(lane, "1") == 0 &&
        general && strcmp(general, "1") == 0;
    /* INVALIDATE-SCOPED: stessa cucitura del dispatch G73/G132 — una getenv
     * a init, mai sul percorso caldo.  A flag spento le specializzazioni
     * selezionate sono le STESSE istanze di oggi (SCOPED=false di default):
     * il codice del rollback mirato non esiste nel compilato attivo. */
    const char *scoped_env = getenv("DS4_CUDA_SCOPED_INVALIDATE");
    const int scoped_enabled = scoped_env && strcmp(scoped_env, "1") == 0;
    /* DRAIN4: stessa cucitura — una getenv (cachata) a init, mai sul
     * percorso caldo.  A flag spento le specializzazioni selezionate sono
     * le STESSE istanze di oggi (DOV=false di default): il codice
     * dell'overlap non esiste nel compilato attivo.  Il dispatch MTP piu'
     * sotto resta cablato su <false> (DOV=false), e i percorsi Q1/IQ1 non
     * passano di qui: restano sulle istanze non-overlap (§3.3). */
    const int dov_enabled = cuda_moe_drain_overlap4_requested();
    if (dov_enabled) {
        fprintf(stderr,
                "ds4: [drain-overlap4] dispatch=armed g73=%d general=%d "
                "scoped=%d\n",
                g_cuda_g73_open_enabled ? 1 : 0, general_enabled,
                scoped_enabled);
    }
    if (g_cuda_g73_open_enabled && general_enabled) {
        g_cuda_routed_moe_launch_dispatch = dov_enabled
            ? &routed_moe_launch_impl<true, false, true>
            : &routed_moe_launch_impl<true, false>;
        g_cuda_routed_moe_general_launch_dispatch = dov_enabled
            ? &routed_moe_launch_impl<true, true, true>
            : &routed_moe_launch_impl<true, true>;
        g_cuda_moe_route_worker_dispatch = scoped_enabled
            ? (dov_enabled
                ? cuda_moe_route_worker<true, true, true, true>
                : cuda_moe_route_worker<true, true, true>)
            : (dov_enabled
                ? cuda_moe_route_worker<true, true, false, true>
                : cuda_moe_route_worker<true, true>);
    } else if (g_cuda_g73_open_enabled) {
        g_cuda_routed_moe_launch_dispatch = dov_enabled
            ? &routed_moe_launch_impl<true, false, true>
            : &routed_moe_launch_impl<true>;
        g_cuda_routed_moe_general_launch_dispatch = dov_enabled
            ? &routed_moe_launch_impl<true, false, true>
            : &routed_moe_launch_impl<true, false>;
        g_cuda_moe_route_worker_dispatch = scoped_enabled
            ? (dov_enabled
                ? cuda_moe_route_worker<true, false, true, true>
                : cuda_moe_route_worker<true, false, true>)
            : (dov_enabled
                ? cuda_moe_route_worker<true, false, false, true>
                : cuda_moe_route_worker<true, false>);
    } else if (general_enabled) {
        g_cuda_routed_moe_launch_dispatch = dov_enabled
            ? &routed_moe_launch_impl<false, false, true>
            : &routed_moe_launch_impl<false, false>;
        g_cuda_routed_moe_general_launch_dispatch = dov_enabled
            ? &routed_moe_launch_impl<false, true, true>
            : &routed_moe_launch_impl<false, true>;
        g_cuda_moe_route_worker_dispatch = scoped_enabled
            ? (dov_enabled
                ? cuda_moe_route_worker<false, true, true, true>
                : cuda_moe_route_worker<false, true, true>)
            : (dov_enabled
                ? cuda_moe_route_worker<false, true, false, true>
                : cuda_moe_route_worker<false, true>);
    } else {
        g_cuda_routed_moe_launch_dispatch = dov_enabled
            ? &routed_moe_launch_impl<false, false, true>
            : &routed_moe_launch_impl<false>;
        g_cuda_routed_moe_general_launch_dispatch = dov_enabled
            ? &routed_moe_launch_impl<false, false, true>
            : &routed_moe_launch_impl<false, false>;
        g_cuda_moe_route_worker_dispatch = scoped_enabled
            ? (dov_enabled
                ? cuda_moe_route_worker<false, false, true, true>
                : cuda_moe_route_worker<false, false, true>)
            : (dov_enabled
                ? cuda_moe_route_worker<false, false, false, true>
                : cuda_moe_route_worker<false, false>);
    }
}

extern "C" int ds4_gpu_routed_moe_one_tensor(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *down, const void *model_map, uint64_t model_size, uint32_t layer_index, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset, uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_expert, float clamp, const ds4_gpu_tensor *x, ds4_gpu_g133_epoch g133_epoch, ds4_gpu_spex_queue *spex_queue, const ds4_gpu_spex_key *spex_key) {
    /*
     * G73 is the backbone's exact selected-load contract. MTP has its complete
     * dense expert tensors in the independent mapped window, so route it
     * directly and never publish MTP offsets/outcomes into primary G73 state.
     */
    auto dispatch = model_map == g_mtp_model_host_base
        ? &routed_moe_launch_impl<false>
        : g_cuda_routed_moe_general_launch_dispatch;
    return dispatch(out, gate, up, mid, down, model_map, model_size,
                    layer_index,
                    gate_offset, up_offset, down_offset,
                    gate_type, down_type,
                    gate_expert_bytes, gate_row_bytes,
                    down_expert_bytes, down_row_bytes,
                    expert_in_dim, expert_mid_dim, out_dim,
                    selected, weights, NULL, n_expert, clamp, x, 1,
                    spex_queue, spex_key, NULL, g133_epoch);
}

static int cuda_iq1_mixed_scratch_ensure(uint64_t bytes) {
    if (bytes == 0) return 0;
    if (g_iq1_mixed_scratch && g_iq1_mixed_scratch_bytes >= bytes) return 1;
    if (g_iq1_mixed_scratch) {
        (void)cudaFree(g_iq1_mixed_scratch);
        g_iq1_mixed_scratch = NULL;
        g_iq1_mixed_scratch_bytes = 0;
    }
    cudaError_t err = cudaMalloc(&g_iq1_mixed_scratch, (size_t)bytes);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: CUDA IQ1 mixed scratch alloc failed (%.2f MiB): %s\n",
                (double)bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    g_iq1_mixed_scratch_bytes = bytes;
    return 1;
}

static int cuda_iq1_mixed_gpu_plan_prepare(void) {
    cuda_iq1_mixed_gpu_plan &plan = g_iq1_mixed_gpu_plan;
    if (plan.host_request && plan.device_request) return 1;
    cuda_iq1_mixed_gpu_plan_release();
    cudaError_t err = cudaHostAlloc(
        (void **)&plan.host_request, sizeof(*plan.host_request),
        cudaHostAllocMapped);
    if (err == cudaSuccess) {
        err = cudaHostGetDevicePointer(
            (void **)&plan.device_request, plan.host_request, 0);
    }
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: IQ1 mixed GPU planner allocation failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        cuda_iq1_mixed_gpu_plan_release();
        return 0;
    }
    memset(plan.host_request, 0, sizeof(*plan.host_request));
    fprintf(stderr,
            "ds4: [iq1-mixed-gpu-plan] result=ready "
            "mode=cold-one-upload-overlap\n");
    return 1;
}

static void cuda_iq1_mixed_gpu_plan_release(void) {
    cuda_iq1_mixed_gpu_plan &plan = g_iq1_mixed_gpu_plan;
    if (plan.host_request) (void)cudaFreeHost(plan.host_request);
    memset(&plan, 0, sizeof(plan));
}

static int cuda_iq1_mixed_debug_output(
        const char *phase,
        const ds4_gpu_tensor *tensor,
        uint32_t count) {
    if (!getenv("DS4_IQ1_MIXED_DEBUG")) return 1;
    if (!tensor || !tensor->ptr || tensor->bytes < (uint64_t)count * sizeof(float)) {
        fprintf(stderr, "ds4: [iq1-mixed-debug] phase=%s result=invalid-tensor\n",
                phase ? phase : "unknown");
        return 0;
    }
    if (!cuda_ok(cudaStreamSynchronize(0), "iq1 mixed debug sync")) return 0;
    std::vector<float> values(count);
    if (!cuda_ok(cudaMemcpy(values.data(), tensor->ptr,
                            (size_t)count * sizeof(float),
                            cudaMemcpyDeviceToHost),
                 "iq1 mixed debug D2H")) {
        return 0;
    }
    uint32_t nonfinite = 0;
    double sum_abs = 0.0;
    double sum_sq = 0.0;
    float min_value = INFINITY;
    float max_value = -INFINITY;
    for (float value : values) {
        if (!std::isfinite(value)) {
            nonfinite++;
            continue;
        }
        min_value = std::min(min_value, value);
        max_value = std::max(max_value, value);
        sum_abs += fabs((double)value);
        sum_sq += (double)value * (double)value;
    }
    const uint32_t finite = count - nonfinite;
    fprintf(stderr,
            "ds4: [iq1-mixed-debug] phase=%s count=%u nonfinite=%u "
            "min=%.9g max=%.9g mean_abs=%.9g rms=%.9g\n",
            phase ? phase : "unknown", count, nonfinite,
            finite ? min_value : 0.0f, finite ? max_value : 0.0f,
            finite ? sum_abs / (double)finite : 0.0,
            finite ? sqrt(sum_sq / (double)finite) : 0.0);
    return nonfinite == 0u;
}

static float cuda_g132_f16_to_f32(uint16_t h) {
    const uint32_t sign = (uint32_t)(h & 0x8000u) << 16;
    uint32_t exp = (h >> 10) & 0x1fu;
    uint32_t mant = h & 0x03ffu;
    uint32_t bits = 0;
    if (exp == 0u) {
        if (mant == 0u) {
            bits = sign;
        } else {
            exp = 1u;
            while ((mant & 0x0400u) == 0u) {
                mant <<= 1u;
                exp--;
            }
            mant &= 0x03ffu;
            bits = sign | ((exp + 127u - 15u) << 23u) | (mant << 13u);
        }
    } else if (exp == 31u) {
        bits = sign | 0x7f800000u | (mant << 13u);
    } else {
        bits = sign | ((exp + 127u - 15u) << 23u) | (mant << 13u);
    }
    float value = 0.0f;
    memcpy(&value, &bits, sizeof(value));
    return value;
}

static int32_t cuda_g132_dot_iq2_pair_16(
        const int8_t *grid0, const int8_t *grid1, const int8_t *q8) {
    int32_t sum = 0;
    for (uint32_t i = 0; i < 8u; i++) sum += (int32_t)grid0[i] * q8[i];
    for (uint32_t i = 0; i < 8u; i++) sum += (int32_t)grid1[i] * q8[8u + i];
    return sum;
}

static int32_t cuda_g132_dot_q2_16(
        const uint8_t *q2, const int8_t *q8, int shift) {
    int32_t sum = 0;
    for (uint32_t i = 0; i < 16u; i++) {
        sum += (int32_t)((q2[i] >> shift) & 3u) * q8[i];
    }
    return sum;
}

static int cuda_g132_quantize_row_q8_K(
        const float *x, cuda_block_q8_K *y, uint32_t count) {
    if (!x || !y || count == 0u || count % CUDA_QK_K != 0u) return 0;
    const uint32_t blocks = count / CUDA_QK_K;
    for (uint32_t b = 0; b < blocks; b++) {
        float signed_max = 0.0f;
        float abs_max = 0.0f;
        for (uint32_t j = 0; j < CUDA_QK_K; j++) {
            const float ax = fabsf(x[j]);
            if (ax > abs_max) {
                abs_max = ax;
                signed_max = x[j];
            }
        }
        if (abs_max == 0.0f) {
            y[b].d = 0.0f;
            memset(y[b].qs, 0, sizeof(y[b].qs));
            memset(y[b].bsums, 0, sizeof(y[b].bsums));
            x += CUDA_QK_K;
            continue;
        }
        const float inverse_scale = -127.0f / signed_max;
        for (uint32_t j = 0; j < CUDA_QK_K; j++) {
            int value = (int)lrintf(inverse_scale * x[j]);
            if (value > 127) value = 127;
            if (value < -128) value = -128;
            y[b].qs[j] = (int8_t)value;
        }
        for (uint32_t j = 0; j < CUDA_QK_K / 16u; j++) {
            int sum = 0;
            for (uint32_t i = 0; i < 16u; i++) {
                sum += y[b].qs[j * 16u + i];
            }
            y[b].bsums[j] = (int16_t)sum;
        }
        y[b].d = 1.0f / inverse_scale;
        x += CUDA_QK_K;
    }
    return 1;
}

static float cuda_g132_dot_iq2_xxs_q8_K(
        uint32_t count,
        const cuda_block_iq2_xxs *x,
        const cuda_block_q8_K *y) {
    const uint32_t blocks = count / CUDA_QK_K;
    float sumf = 0.0f;
    for (uint32_t i = 0; i < blocks; i++) {
        const float d = cuda_g132_f16_to_f32(x[i].d) * y[i].d;
        const uint16_t *q2 = x[i].qs;
        const int8_t *q8 = y[i].qs;
        int32_t block_sum = 0;
        for (uint32_t ib32 = 0; ib32 < CUDA_QK_K / 32u; ib32++) {
            uint32_t aux32[2];
            memcpy(aux32, q2, sizeof(aux32));
            const uint8_t *aux8 = (const uint8_t *)aux32;
            q2 += 4;
            const int32_t level_scale = (int32_t)(2u * (aux32[1] >> 28u) + 1u);
            int32_t sumi = 0;
            for (uint32_t l = 0; l < 4u; l += 2u) {
                const uint32_t sign0 = (aux32[1] >> (7u * l)) & 127u;
                const uint32_t sign1 = (aux32[1] >> (7u * (l + 1u))) & 127u;
                sumi += cuda_g132_dot_iq2_pair_16(
                    g_g132_iq2xxs_signed_grid[aux8[l]][sign0],
                    g_g132_iq2xxs_signed_grid[aux8[l + 1u]][sign1], q8);
                q8 += 16;
            }
            block_sum += sumi * level_scale;
        }
        sumf += d * (float)block_sum;
    }
    return 0.125f * sumf;
}

static float cuda_g132_dot_q2_K_q8_K(
        uint32_t count,
        const cuda_block_q2_K *x,
        const cuda_block_q8_K *y) {
    const uint32_t blocks = count / CUDA_QK_K;
    float sumf = 0.0f;
    for (uint32_t i = 0; i < blocks; i++) {
        const uint8_t *q2 = x[i].qs;
        const int8_t *q8 = y[i].qs;
        const uint8_t *scales = x[i].scales;
        int min_sum = 0;
        for (uint32_t j = 0; j < 16u; j++) {
            min_sum += y[i].bsums[j] * (scales[j] >> 4u);
        }
        const float dall = y[i].d * cuda_g132_f16_to_f32(x[i].d);
        const float dmin = y[i].d * cuda_g132_f16_to_f32(x[i].dmin);
        int isum = 0;
        uint32_t scale_index = 0;
        for (uint32_t k = 0; k < CUDA_QK_K / 128u; k++) {
            int shift = 0;
            for (uint32_t j = 0; j < 4u; j++) {
                int scale = scales[scale_index++] & 0x0f;
                isum += scale * cuda_g132_dot_q2_16(q2, q8, shift);
                scale = scales[scale_index++] & 0x0f;
                isum += scale * cuda_g132_dot_q2_16(q2 + 16u, q8 + 16u, shift);
                shift += 2;
                q8 += 32;
            }
            q2 += 32;
        }
        sumf += dall * (float)isum - dmin * (float)min_sum;
    }
    return sumf;
}

static int cuda_g132_cpu_lane_slot_reservation_valid(
        uint32_t slot_identity, uint64_t slot_generation,
        uint32_t layer, uint32_t expert) {
    if (slot_identity >= g_dynamic_arena.slots.size()) return 0;
    const cuda_dynamic_arena_slot &slot =
        g_dynamic_arena.slots[slot_identity];
    const uint32_t refs = cuda_dynamic_arena_slot_refs_load(
        &slot.cpu_lane_slot_refs);
    return (refs & CUDA_DYNAMIC_ARENA_SLOT_WRITER) == 0u &&
        (refs & CUDA_DYNAMIC_ARENA_SLOT_READERS) != 0u &&
        slot.host_ptr && slot.layer == layer && slot.expert == expert &&
        slot.content_generation == slot_generation &&
        (slot.state == DS4_GPU_ARENA_READY ||
         slot.state == DS4_GPU_ARENA_STAGED);
}

static void cuda_g132_cpu_lane_release_slot(uint32_t slot_identity) {
    if (slot_identity < g_dynamic_arena.slots.size()) {
        cuda_dynamic_arena_slot_reader_release(
            &g_dynamic_arena.slots[slot_identity]);
    }
}

static void cuda_g132_cpu_lane_release_reservations_locked(
        cuda_g132_cpu_lane *lane) {
    if (!lane) return;
    for (uint32_t job = 0; job < lane->job_count; job++) {
        cuda_g132_cpu_lane_release_slot(lane->slot_identities[job]);
        lane->slot_identities[job] = UINT32_MAX;
        lane->slot_generations[job] = 0u;
    }
    lane->job_count = 0u;
}

struct cuda_g132_cpu_lane_reservation_set {
    uint32_t slots[CUDA_G132_CPU_LANE_MAX_ROUTES];
    uint32_t count;
    cuda_g132_cpu_lane_reservation_set() : count(0u) {}
    ~cuda_g132_cpu_lane_reservation_set() { release_all(); }
    void add(uint32_t slot) {
        if (count < CUDA_G132_CPU_LANE_MAX_ROUTES) slots[count++] = slot;
    }
    void release_all() {
        for (uint32_t i = 0; i < count; i++) {
            cuda_g132_cpu_lane_release_slot(slots[i]);
        }
        count = 0u;
    }
    void transfer() { count = 0u; }
};

static int cuda_g132_cpu_lane_forward(
        cuda_g132_cpu_lane_worker *worker, uint32_t job) {
    cuda_g132_cpu_lane &lane = *worker->lane;
    if (job >= lane.job_count || !lane.host_input ||
        worker->output.size() != lane.out_dim ||
        worker->gate.size() != lane.expert_mid_dim ||
        worker->up.size() != lane.expert_mid_dim ||
        worker->mid.size() != lane.expert_mid_dim ||
        worker->xq.size() != lane.expert_in_dim / CUDA_QK_K) {
        return 0;
    }
    if (lane.backings[job] == CUDA_G132_CPU_LANE_BACKING_ARENA) {
        if (!cuda_g132_cpu_lane_slot_reservation_valid(
                lane.slot_identities[job], lane.slot_generations[job],
                lane.layer_index, (uint32_t)lane.expert_ids[job])) {
            return 0;
        }
    } else {
        const cuda_moe_expert_cache &cache = g_moe_expert_cache;
        const uint64_t gate_plane =
            (uint64_t)CUDA_MOE_ROUTE_COUNT * cache.gate_expert_bytes;
        const uint64_t down_plane =
            (uint64_t)CUDA_MOE_ROUTE_COUNT * cache.down_expert_bytes;
        const uintptr_t gate_ptr =
            (uintptr_t)lane.gate_ptrs[job];
        const uintptr_t up_ptr =
            (uintptr_t)lane.up_ptrs[job];
        const uintptr_t down_ptr =
            (uintptr_t)lane.down_ptrs[job];
        const uintptr_t gate_base =
            (uintptr_t)cache.route_host_gate;
        const uintptr_t up_base =
            (uintptr_t)cache.route_host_up;
        const uintptr_t down_base =
            (uintptr_t)cache.route_host_down;
        if (cache.route_cpu_staging_generation.load(
                std::memory_order_acquire) != lane.source_generation ||
            !cache.route_host_gate || !cache.route_host_up ||
            !cache.route_host_down ||
            gate_ptr < gate_base ||
            gate_ptr > gate_base + gate_plane - cache.gate_expert_bytes ||
            up_ptr < up_base ||
            up_ptr > up_base + gate_plane - cache.gate_expert_bytes ||
            down_ptr < down_base ||
            down_ptr > down_base + down_plane - cache.down_expert_bytes) {
            return 0;
        }
    }
    const char *gate_base = lane.gate_ptrs[job];
    const char *up_base = lane.up_ptrs[job];
    const char *down_base = lane.down_ptrs[job];
    if (!ds4_g132_matvec_iq2_xxs_expert_pair_prequant(
            worker->gate.data(), worker->up.data(),
            gate_base, up_base, worker->xq.data(),
            lane.expert_in_dim, lane.expert_mid_dim,
            lane.gate_row_bytes, lane.gate_row_bytes)) {
        return 0;
    }
    for (uint32_t row = 0; row < lane.expert_mid_dim; row++) {
        float gate_value = worker->gate[row];
        float up_value = worker->up[row];
        if (lane.clamp > 1.0e-6f) {
            if (gate_value > lane.clamp) gate_value = lane.clamp;
            if (up_value > lane.clamp) up_value = lane.clamp;
            if (up_value < -lane.clamp) up_value = -lane.clamp;
        }
        /* Identical ordering to the existing lane: clamp, SwiGLU, then
         * pre-down router weight for GENERAL. */
        worker->mid[row] =
            (gate_value / (1.0f + expf(-gate_value))) * up_value *
            (lane.general_active ? lane.route_weights[job] : 1.0f);
    }
    if (!ds4_g132_matvec_q2_k_expert(
            worker->output.data(), down_base, worker->mid.data(),
            lane.expert_mid_dim, lane.out_dim, lane.down_row_bytes)) {
        return 0;
    }
    /* The general lane applies the router weight before Q8_K quantization,
     * matching the GPU path.  The legacy mixed caller keeps its established
     * post-down weighting so GENERAL=0 is behaviorally neutral. */
    memcpy(lane.route_outputs.data() + (uint64_t)job * lane.out_dim,
           worker->output.data(), (size_t)lane.out_dim * sizeof(float));
    return 1;
}

static void *cuda_g132_cpu_lane_worker_main(void *arg) {
    cuda_g132_cpu_lane_worker *worker = (cuda_g132_cpu_lane_worker *)arg;
    cuda_g132_cpu_lane &lane = *worker->lane;
    (void)worker->index;
    for (;;) {
        os_mutex_lock(&lane.mutex);
        while (!lane.stop &&
               (!lane.job_active || !lane.input_ready ||
                lane.next_job >= lane.job_count)) {
            (void)os_cond_wait(&lane.work_cond, &lane.mutex);
        }
        if (lane.stop) {
            os_mutex_unlock(&lane.mutex);
            break;
        }
        /* This is the sole submitter to the private row pool.  Claim the
         * complete batch so experts cannot overlap each other. */
        lane.next_job = lane.job_count;
        /* lane_econ: general is stable for the whole dispatch (set by
         * prepare_general before input_ready, cleared only by the join
         * chain or a cancel), so a snapshot under the mutex is exact. */
        const int general = lane.general_active;
        os_mutex_unlock(&lane.mutex);

        const double dequeue_wall = cuda_wall_sec();
        int ok = ds4_g132_quantize_row_q8_K(
            lane.host_input, worker->xq.data(), lane.expert_in_dim);
        const double quant_finished_wall = cuda_wall_sec();
        double expert_seconds = 0.0;
        uint32_t expert_count = 0u;
        if (ok) {
            for (uint32_t job = 0; job < lane.job_count; job++) {
                const double started = cuda_wall_sec();
                ok = cuda_g132_cpu_lane_forward(worker, job);
                expert_seconds += cuda_wall_sec() - started;
                if (!ok) break;
                expert_count++;
            }
        }
        double reduce_seconds = 0.0;
        if (general) {
            /* lane_econ: the single orchestrator reduces its own partial,
             * so the join no longer needs the caller thread.  On failure
             * the partial is zeros: the H2D+add enqueued behind the gate
             * callback joins an exact zero and the gate callback latches
             * the fault fail-closed. */
            const double reduce_started = cuda_wall_sec();
            memset(lane.host_partial, 0,
                   (size_t)lane.out_dim * sizeof(float));
            if (ok) {
                for (uint32_t job = 0; job < lane.job_count; job++) {
                    const float *route = lane.route_outputs.data() +
                        (uint64_t)job * lane.out_dim;
                    for (uint32_t i = 0; i < lane.out_dim; i++) {
                        lane.host_partial[i] += route[i];
                    }
                }
            }
            reduce_seconds = cuda_wall_sec() - reduce_started;
        }

        os_mutex_lock(&lane.mutex);
        if (!ok) lane.job_failed = 1;
        lane.cpu_expert_seconds = expert_seconds;
        lane.cpu_expert_count = expert_count;
        lane.cpu_wake_seconds =
            lane.cpu_started > 0.0 && dequeue_wall >= lane.cpu_started
            ? dequeue_wall - lane.cpu_started : 0.0;
        lane.cpu_quant_seconds = quant_finished_wall - dequeue_wall;
        lane.cpu_reduce_seconds = reduce_seconds;
        lane.completed_jobs = lane.job_count;
        lane.cpu_finished = cuda_wall_sec();
        /* lane_econ: broadcast - the waiters can now be the join gate
         * callback, a cancel and a prepare at the same time. */
        os_cond_broadcast(&lane.done_cond);
        os_mutex_unlock(&lane.mutex);
    }
    return NULL;
}

static void CUDART_CB cuda_g132_cpu_lane_input_ready_callback(void *arg) {
    cuda_g132_cpu_lane *lane = (cuda_g132_cpu_lane *)arg;
    os_mutex_lock(&lane->mutex);
    if (lane->job_active) {
        lane->cpu_started = cuda_wall_sec();
        lane->input_ready = 1;
        os_cond_broadcast(&lane->work_cond);
    }
    os_mutex_unlock(&lane->mutex);
}

static int cuda_g132_cpu_lane_init(void) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    const char *env = getenv("DS4_G132_CPU_LANE");
    const char *general_env = getenv("DS4_G132_CPU_LANE_GENERAL");
    cudaError_t error = cudaSuccess;
    lane.requested = env && strcmp(env, "1") == 0;
    lane.general_requested =
        general_env && strcmp(general_env, "1") == 0;
    if (!lane.requested || lane.ready) return 1;
    lane.stop = 0;

    if (os_mutex_init(&lane.mutex) != 0) goto fail;
    lane.mutex_ready = 1;
    if (os_cond_init(&lane.work_cond) != 0) goto fail;
    lane.work_cond_ready = 1;
    if (os_cond_init(&lane.done_cond) != 0) goto fail;
    lane.done_cond_ready = 1;

    if (!ds4_g132_lane_parallel_init()) {
        fprintf(stderr, "ds4: [g132-cpu-lane] result=fail-open "
                        "reason=parallel-pool-init\n");
        goto fail;
    }
    error = cudaMemcpyFromSymbol(
        g_g132_iq2xxs_grid, cuda_iq2xxs_grid, sizeof(g_g132_iq2xxs_grid));
    if (error != cudaSuccess) goto cuda_fail;
    for (uint32_t grid = 0; grid < 256u; grid++) {
        const uint8_t *values = (const uint8_t *)&g_g132_iq2xxs_grid[grid];
        for (uint32_t sign_index = 0; sign_index < 128u; sign_index++) {
            uint8_t parity = 0;
            for (uint32_t bit = 0; bit < 7u; bit++) {
                parity ^= (uint8_t)((sign_index >> bit) & 1u);
            }
            const uint8_t signs = (uint8_t)(sign_index | (parity << 7u));
            for (uint32_t j = 0; j < 8u; j++) {
                const int value = values[j];
                g_g132_iq2xxs_signed_grid[grid][sign_index][j] =
                    (int8_t)((signs & (1u << j)) ? -value : value);
            }
        }
    }
    error = cudaStreamCreateWithFlags(&lane.bridge_stream, cudaStreamNonBlocking);
    if (error != cudaSuccess) goto cuda_fail;
    error = cudaEventCreateWithFlags(
        &lane.input_source_ready, cudaEventDisableTiming);
    if (error != cudaSuccess) goto cuda_fail;
    error = cudaEventCreateWithFlags(&lane.input_copy_done, cudaEventDisableTiming);
    if (error != cudaSuccess) goto cuda_fail;
    error = cudaEventCreateWithFlags(&lane.partial_copy_done, cudaEventDisableTiming);
    if (error != cudaSuccess) goto cuda_fail;
    error = cudaHostAlloc((void **)&lane.host_input,
                          4096u * sizeof(float), cudaHostAllocDefault);
    if (error != cudaSuccess) goto cuda_fail;
    error = cudaHostAlloc((void **)&lane.host_partial,
                          4096u * sizeof(float), cudaHostAllocDefault);
    if (error != cudaSuccess) goto cuda_fail;
    error = cudaMalloc((void **)&lane.device_partial, 4096u * sizeof(float));
    if (error != cudaSuccess) goto cuda_fail;
    if (lane.general_requested) {
        error = cudaMalloc((void **)&lane.device_general_route_ptrs,
                           CUDA_MOE_ROUTE_COUNT * 3u * sizeof(uint64_t));
        if (error != cudaSuccess) goto cuda_fail;
        error = cudaMalloc((void **)&lane.device_general_weights,
                           CUDA_MOE_ROUTE_COUNT * sizeof(float));
        if (error != cudaSuccess) goto cuda_fail;
    }

    {
        lane.worker_count = 1u;
        lane.max_experts_per_layer = 3u;
        const char *max_env = getenv("DS4_G132_CPU_LANE_MAX");
        if (max_env && max_env[0]) {
            char *end = NULL;
            errno = 0;
            const unsigned long parsed = strtoul(max_env, &end, 10);
            if (max_env[0] == '-' || end == max_env || !end || *end != '\0' ||
                errno != 0) {
                fprintf(stderr,
                        "ds4: [g132-cpu-lane] result=notice "
                        "reason=invalid-max value=%s fallback=3\n",
                        max_env);
            } else {
                lane.max_experts_per_layer = parsed > UINT32_MAX
                    ? UINT32_MAX : (uint32_t)parsed;
            }
        }
        const uint32_t max_cap =
            (uint32_t)CUDA_G132_CPU_LANE_MAX_ROUTES;
        if (lane.max_experts_per_layer > max_cap) {
            lane.max_experts_per_layer = max_cap;
        }
        for (uint32_t layer_index = 0;
             layer_index < CUDA_G132_CPU_LANE_LAYER_COUNT; layer_index++) {
            lane.layer_target_cpu[layer_index] =
                lane.max_experts_per_layer;
        }
    }
    for (uint32_t i = 0; i < lane.worker_count; i++) {
        lane.workers[i].lane = &lane;
        lane.workers[i].index = i;
        if (os_thread_create(&lane.threads[i],
                             cuda_g132_cpu_lane_worker_main,
                             &lane.workers[i]) != 0) {
            goto fail;
        }
        lane.threads_started++;
    }
    lane.ready = 1;
    fprintf(stderr,
            "ds4: [g132-cpu-lane] result=ready workers=%u queue_capacity=%u "
            "max_experts_per_layer=%u input_bytes=%u partial_bytes=%u "
            "source=primary_iq2_pinned_or_route_staging general=%u\n",
            lane.worker_count, CUDA_G132_CPU_LANE_MAX_ROUTES,
            lane.max_experts_per_layer,
            4096u * (unsigned)sizeof(float), 4096u * (unsigned)sizeof(float),
            lane.general_requested);
    return 1;

cuda_fail:
    fprintf(stderr, "ds4: [g132-cpu-lane] result=fail-open cuda_error=%s\n",
            cudaGetErrorString(error));
    (void)cudaGetLastError();
fail:
    lane.failures++;
    lane.failed_open = 1;
    cuda_g132_cpu_lane_release();
    lane.requested = 1;
    lane.failed_open = 1;
    return 1;
}

static void cuda_g132_cpu_lane_release(void) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    if (lane.mutex_ready) {
        os_mutex_lock(&lane.mutex);
        lane.stop = 1;
        /* lane_econ: revoke any pending async join so the gate callback
         * exits instead of waiting on workers that are being stopped;
         * otherwise destroying the bridge stream would hang on it. */
        lane.join_enqueued = 0;
        lane.stats_pending = 0;
        lane.job_active = 0;
        if (lane.work_cond_ready) os_cond_broadcast(&lane.work_cond);
        if (lane.done_cond_ready) os_cond_broadcast(&lane.done_cond);
        os_mutex_unlock(&lane.mutex);
    }
    for (uint32_t i = 0; i < lane.threads_started; i++) {
        os_thread_join(lane.threads[i]);
    }
    cuda_g132_cpu_lane_release_reservations_locked(&lane);
    g_moe_expert_cache.route_cpu_staging_generation.store(
        0u, std::memory_order_release);
    g_moe_expert_cache.route_cpu_plan = cuda_g132_general_plan{};
    if (lane.requested && lane.general_requested) {
        fprintf(stderr,
                "ds4: [g132-general-summary] calls=%llu route_cpu=%llu "
                "route_gpu=%llu bytes_non_attraversati=%llu "
                "cpu_wall_ms=%.6f gpu_wall_ms=%.6f "
                "expert_ms=%.6f "
                "gpu_wait_cpu_ms=%.6f cpu_wait_gpu_ms=%.6f "
                "eligible=%llu rejected_cap=%llu rejected_balance=%llu "
                "fallback_contract=%llu fallback_reservation=%llu "
                "fallback_wrap=%llu fallback_pipeline=%llu "
                "fallback_runtime=%llu "
                "staging_routes=%llu "
                "join_async=%llu prepare_waits=%llu prepare_wait_ms=%.6f "
                "stats_dropped=%llu wake_ms=%.6f quant_ms=%.6f "
                "reduce_ms=%.6f enqueue_ms=%.6f worker_window_ms=%.6f\n",
                (unsigned long long)lane.general_calls,
                (unsigned long long)lane.general_route_cpu,
                (unsigned long long)lane.general_route_gpu,
                (unsigned long long)lane.general_bytes_not_crossed,
                lane.general_cpu_seconds * 1000.0,
                lane.general_gpu_seconds * 1000.0,
                lane.general_route_cpu != 0u
                    ? lane.general_expert_seconds * 1000.0 /
                        (double)lane.general_route_cpu
                    : 0.0,
                lane.general_gpu_wait_cpu_seconds * 1000.0,
                lane.general_cpu_wait_gpu_seconds * 1000.0,
                (unsigned long long)lane.general_eligible,
                (unsigned long long)lane.general_rejected_cap,
                (unsigned long long)lane.general_rejected_balance,
                (unsigned long long)lane.general_fallback_contract,
                (unsigned long long)lane.general_fallback_reservation,
                (unsigned long long)lane.general_fallback_wrap,
                (unsigned long long)lane.general_fallback_pipeline,
                (unsigned long long)lane.general_fallback_runtime,
                (unsigned long long)lane.general_staging_routes,
                (unsigned long long)lane.general_join_async,
                (unsigned long long)lane.general_prepare_waits,
                lane.general_prepare_wait_seconds * 1000.0,
                (unsigned long long)lane.general_stats_dropped,
                lane.general_wake_seconds * 1000.0,
                lane.general_quant_seconds * 1000.0,
                lane.general_reduce_seconds * 1000.0,
                lane.general_enqueue_seconds * 1000.0,
                lane.general_worker_window_seconds * 1000.0);
        for (uint32_t layer_index = 0;
             layer_index < CUDA_G132_CPU_LANE_LAYER_COUNT; layer_index++) {
            if (lane.general_layer_calls[layer_index] == 0u) continue;
            fprintf(stderr,
                    "ds4: [g132-general-layer-summary] layer=%u calls=%llu "
                    "route_cpu=%llu route_gpu=%llu "
                    "bytes_non_attraversati=%llu cpu_wall_ms=%.6f "
                    "expert_ms=%.6f "
                    "gpu_wall_ms=%.6f gpu_wait_cpu_ms=%.6f "
                    "cpu_wait_gpu_ms=%.6f prepare_wait_charged_ms=%.6f\n",
                    layer_index,
                    (unsigned long long)
                        lane.general_layer_calls[layer_index],
                    (unsigned long long)lane.general_layer_cpu_routes[layer_index],
                    (unsigned long long)lane.layer_gpu_routes[layer_index],
                    (unsigned long long)
                        lane.layer_bytes_not_crossed[layer_index],
                    lane.general_layer_cpu_seconds[layer_index] * 1000.0,
                    lane.general_layer_cpu_routes[layer_index] != 0u
                        ? lane.general_layer_expert_seconds[layer_index] *
                            1000.0 /
                            (double)lane.general_layer_cpu_routes[layer_index]
                        : 0.0,
                    lane.layer_gpu_seconds[layer_index] * 1000.0,
                    lane.layer_gpu_wait_cpu_seconds[layer_index] * 1000.0,
                    lane.layer_cpu_wait_gpu_seconds[layer_index] * 1000.0,
                    lane.general_layer_prepare_wait_seconds[layer_index] *
                        1000.0);
        }
    }
    if (lane.requested && cuda_q1_0_profile_requested()) {
        fprintf(stderr,
            "ds4: [g132-cpu-lane] result=summary routes=%llu "
                "resident_hits=%llu skipped_cold=%llu cap_rejected=%llu "
                "not_pinned=%llu reservation_rejected=%llu "
                "promotion_hints_skipped=%llu "
                "max_experts_per_layer=%u input_d2h_bytes=%llu "
                "partial_h2d_bytes=%llu failures=%llu\n",
                (unsigned long long)lane.routes,
                (unsigned long long)lane.resident_hits,
                (unsigned long long)lane.skipped_cold,
                (unsigned long long)lane.cap_rejected,
                (unsigned long long)lane.not_pinned,
                (unsigned long long)lane.reservation_rejected,
                (unsigned long long)lane.promotion_hints_skipped,
                lane.max_experts_per_layer,
                (unsigned long long)lane.input_d2h_bytes,
                (unsigned long long)lane.partial_h2d_bytes,
                (unsigned long long)lane.failures);
        for (uint32_t layer = 0; layer < CUDA_G132_CPU_LANE_LAYER_COUNT; layer++) {
            if (lane.layer_calls[layer] == 0u) continue;
            fprintf(stderr,
                    "ds4: [g132-cpu-lane-layer] layer=%u calls=%llu routes=%llu "
                    "cpu_seconds=%.9f join_wait_seconds=%.9f\n",
                    layer,
                    (unsigned long long)lane.layer_calls[layer],
                    (unsigned long long)lane.layer_routes[layer],
                    lane.layer_cpu_seconds[layer],
                    lane.layer_join_wait_seconds[layer]);
        }
    }
    if (lane.device_general_weights) {
        (void)cudaFree(lane.device_general_weights);
    }
    if (lane.device_general_route_ptrs) {
        (void)cudaFree(lane.device_general_route_ptrs);
    }
    if (lane.device_partial) (void)cudaFree(lane.device_partial);
    if (lane.host_partial) (void)cudaFreeHost(lane.host_partial);
    if (lane.host_input) (void)cudaFreeHost(lane.host_input);
    if (lane.partial_copy_done) (void)cudaEventDestroy(lane.partial_copy_done);
    if (lane.input_copy_done) (void)cudaEventDestroy(lane.input_copy_done);
    if (lane.input_source_ready) (void)cudaEventDestroy(lane.input_source_ready);
    if (lane.bridge_stream) (void)cudaStreamDestroy(lane.bridge_stream);
    lane.device_partial = NULL;
    lane.device_general_weights = NULL;
    lane.device_general_route_ptrs = NULL;
    lane.host_partial = NULL;
    lane.host_input = NULL;
    lane.partial_copy_done = NULL;
    lane.input_copy_done = NULL;
    lane.input_source_ready = NULL;
    lane.bridge_stream = NULL;
    lane.route_outputs.clear();
    for (uint32_t i = 0; i < CUDA_G132_CPU_LANE_MAX_WORKERS; i++) {
        lane.workers[i].output.clear();
        lane.workers[i].gate.clear();
        lane.workers[i].up.clear();
        lane.workers[i].mid.clear();
        lane.workers[i].xq.clear();
    }
    ds4_g132_lane_parallel_shutdown();
    if (lane.done_cond_ready) os_cond_destroy(&lane.done_cond);
    if (lane.work_cond_ready) os_cond_destroy(&lane.work_cond);
    if (lane.mutex_ready) os_mutex_destroy(&lane.mutex);
    lane.ready = 0;
    lane.mutex_ready = 0;
    lane.work_cond_ready = 0;
    lane.done_cond_ready = 0;
    lane.threads_started = 0;
    lane.worker_count = 0;
}

static int cuda_g132_cpu_lane_requested(void) {
    return g_g132_cpu_lane.requested && g_g132_cpu_lane.ready &&
           !g_g132_cpu_lane.failed_open;
}

static int cuda_g132_cpu_lane_reserve_resident_iq2_ptrs(
        uint32_t layer, uint32_t expert,
        cuda_q1_0_mixed_representation representation,
        const char **gate, const char **up, const char **down,
        uint32_t *slot_identity, uint64_t *slot_generation,
        int *reservation_busy) {
    if (reservation_busy) *reservation_busy = 0;
    if (!gate || !up || !down || !slot_identity || !slot_generation ||
        layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        g_dynamic_arena.backing != CUDA_DYNAMIC_ARENA_BACKING_PRIMARY ||
        g_moe_tiering.entries.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u ||
        (representation != CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM &&
         representation != CUDA_Q1_0_MIXED_IQ2_TIER_RAM)) {
        return 0;
    }
    const cuda_moe_tier_entry &tier = g_moe_tiering.entries[
        cuda_moe_tiering_entry_index(layer, expert)];
    if (!tier.has_2bit_ram ||
        (tier.state != CUDA_MOE_TIER_RAM_PROBATION &&
         tier.state != CUDA_MOE_TIER_RAM_WARM)) {
        return 0;
    }

    char *resolved_gate = NULL;
    char *resolved_up = NULL;
    char *resolved_down = NULL;
    uint32_t resolved_slot = UINT32_MAX;
    uint64_t resolved_generation = 0;
    if (representation == CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM) {
        if (!cuda_moe_tiering_snapshot_ram_ptrs(
                layer, expert,
                &resolved_gate, &resolved_up, &resolved_down)) {
            return 0;
        }
        const uint32_t entry = layer * 256u + expert;
        if (entry >= g_dynamic_arena.active.size()) return 0;
        const cuda_dynamic_arena_binding &binding =
            g_dynamic_arena.active[entry];
        resolved_slot = binding.slot;
        resolved_generation = binding.slot_generation;
    } else {
        if (!cuda_moe_tiering_ram_ptrs(
                layer, expert,
                &resolved_gate, &resolved_up, &resolved_down)) {
            return 0;
        }
        resolved_slot = tier.ram_slot;
        resolved_generation = tier.ram_generation;
    }
    if (resolved_slot >= g_dynamic_arena.slots.size()) return 0;
    cuda_dynamic_arena_slot &slot =
        g_dynamic_arena.slots[resolved_slot];
    if (!cuda_dynamic_arena_slot_reader_acquire(&slot)) {
        if (reservation_busy) *reservation_busy = 1;
        return 0;
    }
    if (slot.pageable || !slot.host_ptr ||
        slot.layer != layer || slot.expert != expert ||
        slot.content_generation == 0u ||
        slot.content_generation != resolved_generation ||
        resolved_gate != slot.host_ptr ||
        resolved_up != slot.host_ptr + g_moe_expert_cache.gate_expert_bytes ||
        resolved_down != resolved_up + g_moe_expert_cache.gate_expert_bytes) {
        cuda_dynamic_arena_slot_reader_release(&slot);
        return 0;
    }
    *gate = resolved_gate;
    *up = resolved_up;
    *down = resolved_down;
    *slot_identity = resolved_slot;
    *slot_generation = resolved_generation;
    return 1;
}

static int cuda_g132_cpu_lane_reserved_iq2_ptrs(
        uint32_t layer, uint32_t expert,
        cuda_q1_0_mixed_representation representation,
        uint32_t slot_identity, uint64_t slot_generation,
        const char **gate, const char **up, const char **down) {
    if (!gate || !up || !down ||
        (representation != CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM &&
         representation != CUDA_Q1_0_MIXED_IQ2_TIER_RAM) ||
        !cuda_g132_cpu_lane_slot_reservation_valid(
            slot_identity, slot_generation, layer, expert)) {
        return 0;
    }
    const cuda_dynamic_arena_slot &slot =
        g_dynamic_arena.slots[slot_identity];
    if (slot.pageable) return 0;
    *gate = slot.host_ptr;
    *up = slot.host_ptr + g_moe_expert_cache.gate_expert_bytes;
    *down = *up + g_moe_expert_cache.gate_expert_bytes;
    return 1;
}

static int cuda_g132_cpu_lane_prepare_dispatch(
        uint32_t layer_index,
        uint64_t gate_expert_bytes, uint64_t gate_row_bytes,
        uint64_t down_expert_bytes, uint64_t down_row_bytes,
        uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim,
        const int32_t *experts, const float *weights,
        const cuda_q1_0_mixed_representation *representations,
        const uint32_t *slot_identities, const uint64_t *slot_generations,
        uint32_t count,
        float clamp) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    const uint64_t expected_gate_row =
        (uint64_t)(expert_in_dim / CUDA_QK_K) * sizeof(cuda_block_iq2_xxs);
    const uint64_t expected_down_row =
        (uint64_t)(expert_mid_dim / CUDA_QK_K) * sizeof(cuda_block_q2_K);
    if (!cuda_g132_cpu_lane_requested() || !experts || !weights ||
        !representations || !slot_identities || !slot_generations ||
        count == 0u || count > CUDA_G132_CPU_LANE_MAX_ROUTES ||
        layer_index >= CUDA_G132_CPU_LANE_LAYER_COUNT ||
        expert_in_dim != 4096u || out_dim != 4096u ||
        expert_mid_dim == 0u || expert_mid_dim % CUDA_QK_K != 0u ||
        gate_row_bytes != expected_gate_row ||
        down_row_bytes != expected_down_row ||
        gate_expert_bytes < gate_row_bytes * expert_mid_dim ||
        down_expert_bytes < down_row_bytes * out_dim ||
        gate_expert_bytes != g_moe_expert_cache.gate_expert_bytes ||
        down_expert_bytes != g_moe_expert_cache.down_expert_bytes) {
        return 0;
    }
    const char *gate_ptrs[CUDA_G132_CPU_LANE_MAX_ROUTES] = {};
    const char *up_ptrs[CUDA_G132_CPU_LANE_MAX_ROUTES] = {};
    const char *down_ptrs[CUDA_G132_CPU_LANE_MAX_ROUTES] = {};
    for (uint32_t job = 0; job < count; job++) {
        if (experts[job] < 0 || experts[job] >= 256 ||
            !std::isfinite(weights[job]) ||
            !cuda_g132_cpu_lane_reserved_iq2_ptrs(
                layer_index, (uint32_t)experts[job], representations[job],
                slot_identities[job], slot_generations[job],
                &gate_ptrs[job], &up_ptrs[job], &down_ptrs[job])) {
            return 0;
        }
    }
    os_mutex_lock(&lane.mutex);
    if (lane.job_active) {
        os_mutex_unlock(&lane.mutex);
        return 0;
    }
    try {
        lane.route_outputs.resize((uint64_t)count * out_dim);
        for (uint32_t i = 0; i < lane.worker_count; i++) {
            lane.workers[i].output.resize(out_dim);
            lane.workers[i].gate.resize(expert_mid_dim);
            lane.workers[i].up.resize(expert_mid_dim);
            lane.workers[i].mid.resize(expert_mid_dim);
            lane.workers[i].xq.resize(expert_in_dim / CUDA_QK_K);
        }
    } catch (...) {
        os_mutex_unlock(&lane.mutex);
        lane.failures++;
        return 0;
    }
    memcpy(lane.gate_ptrs, gate_ptrs, (size_t)count * sizeof(gate_ptrs[0]));
    memcpy(lane.up_ptrs, up_ptrs, (size_t)count * sizeof(up_ptrs[0]));
    memcpy(lane.down_ptrs, down_ptrs, (size_t)count * sizeof(down_ptrs[0]));
    memcpy(lane.slot_identities, slot_identities,
           (size_t)count * sizeof(slot_identities[0]));
    memcpy(lane.slot_generations, slot_generations,
           (size_t)count * sizeof(slot_generations[0]));
    memcpy(lane.expert_ids, experts, (size_t)count * sizeof(experts[0]));
    memcpy(lane.route_weights, weights, (size_t)count * sizeof(weights[0]));
    for (uint32_t job = 0; job < count; job++) {
        lane.backings[job] = CUDA_G132_CPU_LANE_BACKING_ARENA;
    }
    lane.gate_row_bytes = gate_row_bytes;
    lane.down_row_bytes = down_row_bytes;
    lane.expert_in_dim = expert_in_dim;
    lane.expert_mid_dim = expert_mid_dim;
    lane.out_dim = out_dim;
    lane.layer_index = layer_index;
    lane.job_count = count;
    lane.next_job = 0;
    lane.completed_jobs = 0;
    lane.clamp = clamp;
    lane.input_ready = 0;
    lane.job_failed = 0;
    lane.cpu_started = 0.0;
    lane.cpu_finished = 0.0;
    lane.cpu_expert_seconds = 0.0;
    lane.cpu_expert_count = 0u;
    lane.generation++;
    if (lane.generation == 0u) lane.generation++;
    lane.job_active = 1;
    os_mutex_unlock(&lane.mutex);
    return 1;
}

static int cuda_g132_cpu_lane_prepare_general(
        cuda_moe_expert_cache *cache,
        uint32_t layer_index,
        uint64_t gate_expert_bytes, uint64_t gate_row_bytes,
        uint64_t down_expert_bytes, uint64_t down_row_bytes,
        uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim,
        float clamp,
        uint32_t *cpu_mask,
        uint32_t *gpu_count) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    if (!cache || !cpu_mask || !gpu_count ||
        !cuda_g132_general_requested() ||
        !lane.device_general_route_ptrs ||
        !lane.device_general_weights) {
        return 0;
    }
    cuda_g132_general_plan &plan = cache->route_cpu_plan;
    const uint32_t sequence = cache->route_submitted_sequence.load(
        std::memory_order_acquire);
    const uint64_t generation = cache->route_submitted_generation.load(
        std::memory_order_acquire);
    const uint64_t expected_gate_row =
        (uint64_t)(expert_in_dim / CUDA_QK_K) * sizeof(cuda_block_iq2_xxs);
    const uint64_t expected_down_row =
        (uint64_t)(expert_mid_dim / CUDA_QK_K) * sizeof(cuda_block_q2_K);
    const uint64_t native_expert_bytes =
        gate_expert_bytes * 2ull + down_expert_bytes;
    if (plan.sequence != sequence || plan.generation != generation ||
        plan.layer_index != layer_index || plan.cpu_count == 0u ||
        plan.cpu_count >= plan.route_count ||
        plan.cpu_count > CUDA_G132_CPU_LANE_MAX_ROUTES ||
        layer_index >= CUDA_G132_CPU_LANE_LAYER_COUNT ||
        expert_in_dim != 4096u || out_dim != 4096u ||
        expert_mid_dim == 0u || expert_mid_dim % CUDA_QK_K != 0u ||
        gate_row_bytes != expected_gate_row ||
        down_row_bytes != expected_down_row ||
        native_expert_bytes != 7077888ull ||
        gate_expert_bytes != cache->gate_expert_bytes ||
        down_expert_bytes != cache->down_expert_bytes) {
        return 0;
    }
    for (uint32_t i = 0; i < plan.cpu_count; i++) {
        const cuda_g132_general_route &route = plan.routes[i];
        if (route.route >= plan.route_count || route.expert < 0 ||
            route.expert >= 256 || !std::isfinite(route.weight) ||
            !route.gate || !route.up || !route.down) {
            return 0;
        }
        if (route.backing == CUDA_G132_CPU_LANE_BACKING_ARENA &&
            !cuda_g132_cpu_lane_slot_reservation_valid(
                route.slot_identity, route.slot_generation,
                layer_index, (uint32_t)route.expert)) {
            return 0;
        }
    }

    os_mutex_lock(&lane.mutex);
    if (lane.async_fault) {
        os_mutex_unlock(&lane.mutex);
        return 0;
    }
    double prepare_waited = 0.0;
    if (lane.job_active || (lane.stats_pending && !lane.gpu_done)) {
        /* lane_econ: the async tail of the previous dispatch is still in
         * flight.  This bounded wait is the ONLY critical-path cost the
         * lane can still induce; it is measured here and charged by the
         * balancer to the layer that caused it. */
        const double wait_started = cuda_wall_sec();
        while ((lane.job_active ||
                (lane.stats_pending && !lane.gpu_done)) &&
               cuda_wall_sec() - wait_started < 0.100) {
            (void)os_cond_timedwait_ms(&lane.done_cond, &lane.mutex, 2u);
        }
        if (lane.job_active) {
            os_mutex_unlock(&lane.mutex);
            return 0;
        }
        prepare_waited = cuda_wall_sec() - wait_started;
        lane.general_prepare_wait_seconds += prepare_waited;
        lane.general_prepare_waits++;
        if (lane.prev_dispatch_layer < CUDA_G132_CPU_LANE_LAYER_COUNT) {
            lane.general_layer_prepare_wait_seconds
                [lane.prev_dispatch_layer] += prepare_waited;
        }
    }
    if (lane.stats_pending) {
        /* The previous dispatch never emitted (its GPU callback was outrun
         * past the deadline above): account it - with ITS own per-dispatch
         * fields still intact - before reusing them. */
        if (lane.gpu_done && lane.cpu_join_done) {
            cuda_g132_cpu_lane_emit_general_stats_locked(&lane);
        } else {
            lane.general_stats_dropped++;
            lane.stats_pending = 0;
        }
    }
    lane.cpu_join_done = 0;
    lane.dispatch_prepare_wait_seconds = prepare_waited;
    if (lane.prev_dispatch_valid &&
        lane.prev_dispatch_layer < CUDA_G132_CPU_LANE_LAYER_COUNT) {
        /* lane_econ balancer v2.  With the asynchronous join nobody waits
         * on the CPU/GPU walls anymore, so equalizing them minimizes the
         * wrong quantity.  The profit criterion is: maximize admitted
         * routes (transport quota removed from the serial relay) subject
         * to ZERO induced serialization, which is exactly the prepare wait
         * measured above.  No wait -> one more route; wait -> one less.
         * Streak/cooldown machinery and bounds unchanged. */
        const uint32_t prev = lane.prev_dispatch_layer;
        const double balance_hysteresis = 0.000150;
        const int32_t direction =
            lane.dispatch_prepare_wait_seconds > balance_hysteresis
            ? -1 : 1;
        lane.prev_dispatch_valid = 0;
        if (lane.layer_balance_cooldown[prev] != 0u) {
            lane.layer_balance_cooldown[prev]--;
            lane.layer_imbalance_streak[prev] = 0u;
        } else {
            if (lane.layer_imbalance_direction[prev] == direction) {
                lane.layer_imbalance_streak[prev]++;
            } else {
                lane.layer_imbalance_direction[prev] = direction;
                lane.layer_imbalance_streak[prev] = 1u;
            }
            if (lane.layer_imbalance_streak[prev] >= 3u) {
                uint32_t &target = lane.layer_target_cpu[prev];
                if (direction < 0 && target > 1u) {
                    target--;
                } else if (direction > 0 &&
                           target < lane.max_experts_per_layer) {
                    target++;
                }
                lane.layer_imbalance_streak[prev] = 0u;
                lane.layer_balance_cooldown[prev] = 4u;
            }
        }
    }
    try {
        lane.route_outputs.resize((uint64_t)plan.cpu_count * out_dim);
        for (uint32_t i = 0; i < lane.worker_count; i++) {
            lane.workers[i].output.resize(out_dim);
            lane.workers[i].gate.resize(expert_mid_dim);
            lane.workers[i].up.resize(expert_mid_dim);
            lane.workers[i].mid.resize(expert_mid_dim);
            lane.workers[i].xq.resize(expert_in_dim / CUDA_QK_K);
        }
    } catch (...) {
        os_mutex_unlock(&lane.mutex);
        lane.failures++;
        return 0;
    }
    for (uint32_t i = 0; i < plan.cpu_count; i++) {
        const cuda_g132_general_route &route = plan.routes[i];
        lane.gate_ptrs[i] = route.gate;
        lane.up_ptrs[i] = route.up;
        lane.down_ptrs[i] = route.down;
        lane.backings[i] = route.backing;
        lane.slot_identities[i] = route.slot_identity;
        lane.slot_generations[i] = route.slot_generation;
        lane.expert_ids[i] = route.expert;
        lane.route_weights[i] = route.weight;
    }
    lane.gate_row_bytes = gate_row_bytes;
    lane.down_row_bytes = down_row_bytes;
    lane.expert_in_dim = expert_in_dim;
    lane.expert_mid_dim = expert_mid_dim;
    lane.out_dim = out_dim;
    lane.layer_index = layer_index;
    lane.job_count = plan.cpu_count;
    lane.next_job = 0u;
    lane.completed_jobs = 0u;
    lane.clamp = clamp;
    lane.input_ready = 0;
    lane.job_failed = 0;
    lane.cpu_started = 0.0;
    lane.cpu_finished = 0.0;
    lane.cpu_expert_seconds = 0.0;
    lane.cpu_expert_count = 0u;
    lane.gpu_started = 0.0;
    lane.gpu_finished = 0.0;
    lane.gpu_done = 0;
    lane.general_active = 1;
    lane.source_sequence = sequence;
    lane.source_generation = generation;
    lane.general_gpu_routes = plan.route_count - plan.cpu_count;
    lane.general_current_eligible = plan.eligible;
    lane.general_current_rejected_cap = plan.rejected_cap;
    lane.general_current_rejected_balance = plan.rejected_balance;
    /* lane_econ: measured overlap budget of this dispatch - how much
     * worker-phase (resolver + staging + drain) ran between the request
     * begin and this attach.  An early-start lane could hide its whole
     * cpu_wall inside this window. */
    lane.dispatch_worker_window_seconds = lane.plan_begin_wall > 0.0
        ? cuda_wall_sec() - lane.plan_begin_wall : 0.0;
    lane.general_worker_window_seconds +=
        lane.dispatch_worker_window_seconds;
    lane.dispatch_enqueue_seconds = 0.0;
    lane.cpu_wake_seconds = 0.0;
    lane.cpu_quant_seconds = 0.0;
    lane.cpu_reduce_seconds = 0.0;
    lane.stats_pending = 1;
    lane.generation++;
    if (lane.generation == 0u) lane.generation++;
    lane.job_active = 1;
    *cpu_mask = plan.cpu_mask;
    *gpu_count = lane.general_gpu_routes;
    lane.general_eligible += plan.eligible;
    lane.general_rejected_cap += plan.rejected_cap;
    lane.general_rejected_balance += plan.rejected_balance;
    lane.general_staging_routes += plan.staging_count;
    /* Ownership moves to lane.slot_identities and the explicit staging lease.
     * Keep the non-owning plan metadata only until the compaction launch. */
    plan.cpu_count = 0u;
    plan.staging_count = 0u;
    os_mutex_unlock(&lane.mutex);
    return 1;
}

static void CUDART_CB cuda_g132_cpu_lane_gpu_started_callback(void *arg) {
    cuda_g132_cpu_lane *lane = (cuda_g132_cpu_lane *)arg;
    os_mutex_lock(&lane->mutex);
    /* lane_econ: same ownership token as the finished callback - with the
     * asynchronous join, job_active can be cleared before stream 0
     * executes this callback. */
    if (lane->stats_pending && lane->gpu_started == 0.0) {
        lane->gpu_started = cuda_wall_sec();
    }
    os_mutex_unlock(&lane->mutex);
}

static void CUDART_CB cuda_g132_cpu_lane_gpu_finished_callback(void *arg) {
    cuda_g132_cpu_lane *lane = (cuda_g132_cpu_lane *)arg;
    os_mutex_lock(&lane->mutex);
    /* lane_econ: stats_pending is the per-dispatch ownership token (the
     * idle callback may clear job_active before stream 0 executes this
     * callback); gpu_finished == 0 guards against a late callback of an
     * already-finalized dispatch stamping the next one. */
    if (lane->stats_pending && lane->gpu_finished == 0.0) {
        lane->gpu_finished = cuda_wall_sec();
        lane->gpu_done = 1;
        os_cond_broadcast(&lane->done_cond);
        /* Emit here when the CPU side already joined (the gate callback
         * saw gpu_done=0 and left the emission to whoever is last). */
        cuda_g132_cpu_lane_emit_general_stats_locked(lane);
    }
    os_mutex_unlock(&lane->mutex);
}

static int cuda_g132_cpu_lane_begin_general(const ds4_gpu_tensor *input) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    if (!lane.general_active ||
        !cuda_g132_cpu_lane_record_input_source() ||
        !cuda_g132_cpu_lane_enqueue_input(input) ||
        !cuda_ok(cudaLaunchHostFunc(
                     0, cuda_g132_cpu_lane_gpu_started_callback, &lane),
                 "G132 general GPU start callback")) {
        lane.general_fallback_runtime++;
        return 0;
    }
    return 1;
}

static int cuda_g132_cpu_lane_end_general_gpu(void) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    if (!lane.general_active ||
        !cuda_ok(cudaLaunchHostFunc(
                     0, cuda_g132_cpu_lane_gpu_finished_callback, &lane),
                 "G132 general GPU finish callback")) {
        lane.general_fallback_runtime++;
        return 0;
    }
    return 1;
}

static void cuda_g132_cpu_lane_cancel_dispatch(void) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    if (!lane.mutex_ready) return;
    os_mutex_lock(&lane.mutex);
    while (lane.job_active && lane.input_ready &&
           lane.completed_jobs < lane.job_count) {
        (void)os_cond_wait(&lane.done_cond, &lane.mutex);
    }
    if (lane.job_active) {
        const uint64_t source_generation = lane.source_generation;
        const int general_active = lane.general_active;
        lane.job_active = 0;
        lane.input_ready = 0;
        /* lane_econ: revoke a pending async join.  The gate/idle callbacks
         * check join_enqueued under this mutex and become no-ops; every
         * cleanup below is idempotent with theirs in any order. */
        lane.join_enqueued = 0;
        lane.stats_pending = 0;
        lane.cpu_join_done = 0;
        cuda_g132_cpu_lane_release_reservations_locked(&lane);
        lane.general_active = 0;
        if (general_active) {
            uint64_t expected = source_generation;
            (void)g_moe_expert_cache.route_cpu_staging_generation
                .compare_exchange_strong(
                    expected, 0u, std::memory_order_acq_rel,
                    std::memory_order_acquire);
            g_moe_expert_cache.route_cpu_plan =
                cuda_g132_general_plan{};
        }
        os_cond_broadcast(&lane.work_cond);
        os_cond_broadcast(&lane.done_cond);
    }
    os_mutex_unlock(&lane.mutex);
}

static int cuda_g132_cpu_lane_record_input_source(void) {
    /* Record before hot launch. The bridge stream waits on this point, so its
     * D2H overlaps hot work instead of waiting for hot completion. */
    return cuda_ok(cudaEventRecord(g_g132_cpu_lane.input_source_ready, 0),
                   "G132 CPU lane input source event");
}

static int cuda_g132_cpu_lane_enqueue_input(const ds4_gpu_tensor *input) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    const size_t bytes = (size_t)lane.expert_in_dim * sizeof(float);
    if (!input || !input->ptr || input->bytes < bytes ||
        !cuda_ok(cudaStreamWaitEvent(
                     lane.bridge_stream, lane.input_source_ready, 0),
                 "G132 CPU lane input wait") ||
        !cuda_ok(cudaMemcpyAsync(
                     lane.host_input, input->ptr, bytes,
                     cudaMemcpyDeviceToHost, lane.bridge_stream),
                 "G132 CPU lane input D2H") ||
        !cuda_ok(cudaEventRecord(lane.input_copy_done, lane.bridge_stream),
                 "G132 CPU lane input copy event") ||
        !cuda_ok(cudaLaunchHostFunc(
                     lane.bridge_stream,
                     cuda_g132_cpu_lane_input_ready_callback, &lane),
                 "G132 CPU lane input callback")) {
        (void)cudaStreamSynchronize(lane.bridge_stream);
        cuda_g132_cpu_lane_cancel_dispatch();
        lane.failures++;
        return 0;
    }
    lane.input_d2h_bytes += bytes;
    return 1;
}

static int cuda_g132_cpu_lane_wait_and_join(
        ds4_gpu_tensor *out, uint32_t layer_index,
        const float **captured_input) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    const double wait_started = cuda_wall_sec();
    os_mutex_lock(&lane.mutex);
    while (lane.job_active &&
           (lane.completed_jobs < lane.job_count ||
            (lane.general_active && !lane.gpu_done))) {
        (void)os_cond_wait(&lane.done_cond, &lane.mutex);
    }
    const double wait_finished = cuda_wall_sec();
    const uint32_t count = lane.job_count;
    const uint32_t gpu_routes = lane.general_gpu_routes;
    const uint32_t eligible = lane.general_current_eligible;
    const uint32_t rejected_cap = lane.general_current_rejected_cap;
    const uint32_t rejected_balance =
        lane.general_current_rejected_balance;
    const int general_active = lane.general_active;
    const uint64_t source_generation = lane.source_generation;
    const int failed = lane.job_failed || count == 0u;
    if (!failed) {
        memset(lane.host_partial, 0, (size_t)lane.out_dim * sizeof(float));
        for (uint32_t job = 0; job < count; job++) {
            const float *route = lane.route_outputs.data() +
                (uint64_t)job * lane.out_dim;
            const float post_weight =
                general_active ? 1.0f : lane.route_weights[job];
            for (uint32_t i = 0; i < lane.out_dim; i++) {
                lane.host_partial[i] += post_weight * route[i];
            }
        }
    }
    const double cpu_seconds = lane.cpu_finished >= lane.cpu_started
        ? lane.cpu_finished - lane.cpu_started : 0.0;
    const double expert_seconds = lane.cpu_expert_seconds;
    const uint32_t expert_count = lane.cpu_expert_count;
    const double expert_ms = expert_count != 0u
        ? expert_seconds * 1000.0 / (double)expert_count : 0.0;
    const double gpu_seconds =
        general_active && lane.gpu_finished >= lane.gpu_started
        ? lane.gpu_finished - lane.gpu_started : 0.0;
    const double gpu_wait_cpu_seconds =
        general_active && lane.cpu_finished > lane.gpu_finished
        ? lane.cpu_finished - lane.gpu_finished : 0.0;
    const double cpu_wait_gpu_seconds =
        general_active && lane.gpu_finished > lane.cpu_finished
        ? lane.gpu_finished - lane.cpu_finished : 0.0;
    lane.job_active = 0;
    lane.input_ready = 0;
    /* Workers are done and the host partial is fully reduced, so no CPU path
     * can touch resident expert bytes after this point. */
    cuda_g132_cpu_lane_release_reservations_locked(&lane);
    if (general_active) {
        uint64_t expected = source_generation;
        (void)g_moe_expert_cache.route_cpu_staging_generation
            .compare_exchange_strong(
                expected, 0u, std::memory_order_acq_rel,
                std::memory_order_acquire);
        g_moe_expert_cache.route_cpu_plan = cuda_g132_general_plan{};
        lane.general_active = 0;
    }
    os_cond_broadcast(&lane.work_cond);
    if (failed) {
        if (general_active) {
            lane.general_fallback_runtime++;
        }
        os_mutex_unlock(&lane.mutex);
        return 0;
    }

    if (general_active) {
        const uint64_t native_bytes =
            g_moe_expert_cache.gate_expert_bytes * 2ull +
            g_moe_expert_cache.down_expert_bytes;
        lane.general_calls++;
        lane.general_route_cpu += count;
        lane.general_route_gpu += gpu_routes;
        lane.general_bytes_not_crossed += (uint64_t)count * native_bytes;
        lane.general_expert_seconds += expert_seconds;
        lane.general_cpu_seconds += cpu_seconds;
        lane.general_gpu_seconds += gpu_seconds;
        lane.general_gpu_wait_cpu_seconds += gpu_wait_cpu_seconds;
        lane.general_cpu_wait_gpu_seconds += cpu_wait_gpu_seconds;
        lane.general_layer_calls[layer_index]++;
        lane.general_layer_cpu_routes[layer_index] += count;
        lane.general_layer_cpu_seconds[layer_index] += cpu_seconds;
        lane.general_layer_expert_seconds[layer_index] +=
            expert_seconds;
        lane.layer_gpu_routes[layer_index] += gpu_routes;
        lane.layer_bytes_not_crossed[layer_index] +=
            (uint64_t)count * native_bytes;
        lane.layer_gpu_seconds[layer_index] += gpu_seconds;
        lane.layer_gpu_wait_cpu_seconds[layer_index] +=
            gpu_wait_cpu_seconds;
        lane.layer_cpu_wait_gpu_seconds[layer_index] +=
            cpu_wait_gpu_seconds;

        const double hysteresis = std::max(
            0.000150, 0.10 * std::max(cpu_seconds, gpu_seconds));
        const double imbalance = cpu_seconds - gpu_seconds;
        const int32_t direction = imbalance > hysteresis ? -1 :
            (imbalance < -hysteresis ? 1 : 0);
        if (lane.layer_balance_cooldown[layer_index] != 0u) {
            lane.layer_balance_cooldown[layer_index]--;
            lane.layer_imbalance_streak[layer_index] = 0u;
        } else if (direction == 0) {
            lane.layer_imbalance_direction[layer_index] = 0;
            lane.layer_imbalance_streak[layer_index] = 0u;
        } else {
            if (lane.layer_imbalance_direction[layer_index] == direction) {
                lane.layer_imbalance_streak[layer_index]++;
            } else {
                lane.layer_imbalance_direction[layer_index] = direction;
                lane.layer_imbalance_streak[layer_index] = 1u;
            }
            if (lane.layer_imbalance_streak[layer_index] >= 3u) {
                uint32_t &target = lane.layer_target_cpu[layer_index];
                const uint32_t target_max = std::min(
                    lane.max_experts_per_layer,
                    count + gpu_routes - 1u);
                if (direction < 0 && target > 1u) {
                    target--;
                } else if (direction > 0 && target < target_max) {
                    target++;
                }
                lane.layer_imbalance_streak[layer_index] = 0u;
                lane.layer_balance_cooldown[layer_index] = 4u;
            }
        }
    }
    const uint32_t next_target =
        layer_index < CUDA_G132_CPU_LANE_LAYER_COUNT
        ? lane.layer_target_cpu[layer_index] : 0u;
    os_mutex_unlock(&lane.mutex);

    const size_t bytes = (size_t)lane.out_dim * sizeof(float);
    if (!cuda_ok(cudaMemcpyAsync(
                     lane.device_partial, lane.host_partial, bytes,
                     cudaMemcpyHostToDevice, lane.bridge_stream),
                 "G132 CPU lane partial H2D") ||
        !cuda_ok(cudaEventRecord(lane.partial_copy_done, lane.bridge_stream),
                 "G132 CPU lane partial event") ||
        !cuda_ok(cudaStreamWaitEvent(0, lane.partial_copy_done, 0),
                 "G132 CPU lane join wait")) {
        if (general_active) {
            lane.general_fallback_runtime++;
        }
        return 0;
    }
    /* Stream 0 already contains the hot (and any overflow-Q1) accumulation;
     * the event wait publishes the one CPU partial after those writes. */
    add_f32_u64_kernel<<<(lane.out_dim + 255u) / 256u, 256>>>(
        (float *)out->ptr, (const float *)out->ptr,
        lane.device_partial, lane.out_dim);
    if (!cuda_ok(cudaGetLastError(), "G132 CPU lane output join")) {
        if (general_active) {
            lane.general_fallback_runtime++;
        }
        return 0;
    }
    lane.routes += count;
    lane.partial_h2d_bytes += bytes;
    if (layer_index < CUDA_G132_CPU_LANE_LAYER_COUNT) {
        lane.layer_calls[layer_index]++;
        lane.layer_routes[layer_index] += count;
        lane.layer_cpu_seconds[layer_index] += cpu_seconds;
        lane.layer_join_wait_seconds[layer_index] +=
            wait_finished - wait_started;
    }
    if (general_active) {
        fprintf(stderr,
                "ds4: [g132-general-layer] layer=%u route_cpu=%u "
                "route_gpu=%u bytes_non_attraversati=%llu "
                "cpu_wall_ms=%.6f gpu_wall_ms=%.6f "
                "expert_ms=%.6f "
                "gpu_wait_cpu_ms=%.6f cpu_wait_gpu_ms=%.6f "
                "eligible=%u rejected_cap=%u rejected_balance=%u "
                "next_target_cpu=%u\n",
                layer_index, count, gpu_routes,
                (unsigned long long)((uint64_t)count *
                    (g_moe_expert_cache.gate_expert_bytes * 2ull +
                     g_moe_expert_cache.down_expert_bytes)),
                cpu_seconds * 1000.0, gpu_seconds * 1000.0,
                expert_ms, gpu_wait_cpu_seconds * 1000.0,
                cpu_wait_gpu_seconds * 1000.0,
                eligible, rejected_cap, rejected_balance, next_target);
    }
    if (cuda_q1_0_profile_requested()) {
        fprintf(stderr,
                "ds4: [g132-cpu-lane-layer] layer=%u routes=%u "
                "cpu_ms=%.6f join_wait_ms=%.6f\n",
                layer_index, count, cpu_seconds * 1000.0,
                (wait_finished - wait_started) * 1000.0);
    }
    if (captured_input) *captured_input = lane.host_input;
    return 1;
}

/* =======================================================================
 * lane_econ: asynchronous join for the GENERAL lane.
 *
 * Measured 28/7 (run 2250-2600 tok, ctx 150k, kernel row-parallel): the
 * blocking wait_and_join cost the caller thread ~1,1 ms per engaged layer
 * (gpu_wall ~0,2 + gpu_wait_cpu 0,89 + wake/reduce/enqueue) - within noise
 * of the WHOLE measured lane loss (47-50 ms/token / 43 layer).  The toll it
 * was supposed to buy back (one route's transport quota) is NOT on the
 * serial path in the demand-pipeline config: admission excludes staging
 * routes, and an arena route's H2D drains overlapped with the other
 * routes' SSD reads.  So the join must cost ~zero for the lane to have any
 * economy at all.
 *
 * New shape: the caller ENQUEUES the join and returns.
 *   bridge:  [gate hostfunc: wait CPU done, release reservations+lease,
 *             emit stats]  ->  [H2D partial]  ->  [event]  ->
 *            [idle hostfunc: dispatch reusable]
 *   stream0: [waitEvent]  ->  [add partial]
 * The CPU tail then hides under the NEXT layer's relay; the only residual
 * critical-path cost is the bounded wait in prepare_general when the tail
 * outlives that relay - measured and fed to the balancer.
 *
 * Failure semantics (job_failed after the chain is enqueued): the worker
 * zeroed host_partial, the add joins an exact zero, the gate callback
 * latches async_fault and the lane fails closed from the next engagement.
 * The old path aborted the whole request instead; the fault is unreachable
 * with the reservations/lease held (admit+prepare validated them) and is
 * counted in fallback_runtime plus a loud stderr line.
 * ======================================================================= */
static void cuda_g132_cpu_lane_emit_general_stats_locked(
        cuda_g132_cpu_lane *lane) {
    if (!lane->stats_pending || !lane->gpu_done || !lane->cpu_join_done) {
        return;
    }
    lane->stats_pending = 0;
    const uint32_t layer_index = lane->layer_index;
    const uint32_t count = lane->completed_jobs;
    const uint32_t gpu_routes = lane->general_gpu_routes;
    const uint32_t eligible = lane->general_current_eligible;
    const uint32_t rejected_cap = lane->general_current_rejected_cap;
    const uint32_t rejected_balance =
        lane->general_current_rejected_balance;
    const double cpu_seconds = lane->cpu_finished >= lane->cpu_started
        ? lane->cpu_finished - lane->cpu_started : 0.0;
    const double expert_seconds = lane->cpu_expert_seconds;
    const uint32_t expert_count = lane->cpu_expert_count;
    const double expert_ms = expert_count != 0u
        ? expert_seconds * 1000.0 / (double)expert_count : 0.0;
    const double gpu_seconds =
        lane->gpu_started > 0.0 && lane->gpu_finished >= lane->gpu_started
        ? lane->gpu_finished - lane->gpu_started : 0.0;
    const double gpu_wait_cpu_seconds =
        lane->gpu_finished > 0.0 && lane->cpu_finished > lane->gpu_finished
        ? lane->cpu_finished - lane->gpu_finished : 0.0;
    const double cpu_wait_gpu_seconds =
        lane->gpu_finished > lane->cpu_finished
        ? lane->gpu_finished - lane->cpu_finished : 0.0;
    const uint64_t native_bytes =
        g_moe_expert_cache.gate_expert_bytes * 2ull +
        g_moe_expert_cache.down_expert_bytes;
    lane->general_calls++;
    lane->general_join_async++;
    lane->general_route_cpu += count;
    lane->general_route_gpu += gpu_routes;
    lane->general_bytes_not_crossed += (uint64_t)count * native_bytes;
    lane->general_expert_seconds += expert_seconds;
    lane->general_cpu_seconds += cpu_seconds;
    lane->general_gpu_seconds += gpu_seconds;
    lane->general_gpu_wait_cpu_seconds += gpu_wait_cpu_seconds;
    lane->general_cpu_wait_gpu_seconds += cpu_wait_gpu_seconds;
    lane->general_wake_seconds += lane->cpu_wake_seconds;
    lane->general_quant_seconds += lane->cpu_quant_seconds;
    lane->general_reduce_seconds += lane->cpu_reduce_seconds;
    lane->general_enqueue_seconds += lane->dispatch_enqueue_seconds;
    lane->routes += count;
    lane->partial_h2d_bytes += (uint64_t)lane->out_dim * sizeof(float);
    if (layer_index < CUDA_G132_CPU_LANE_LAYER_COUNT) {
        lane->general_layer_calls[layer_index]++;
        lane->general_layer_cpu_routes[layer_index] += count;
        lane->general_layer_cpu_seconds[layer_index] += cpu_seconds;
        lane->general_layer_expert_seconds[layer_index] += expert_seconds;
        lane->layer_gpu_routes[layer_index] += gpu_routes;
        lane->layer_bytes_not_crossed[layer_index] +=
            (uint64_t)count * native_bytes;
        lane->layer_gpu_seconds[layer_index] += gpu_seconds;
        lane->layer_gpu_wait_cpu_seconds[layer_index] +=
            gpu_wait_cpu_seconds;
        lane->layer_cpu_wait_gpu_seconds[layer_index] +=
            cpu_wait_gpu_seconds;
        lane->layer_calls[layer_index]++;
        lane->layer_routes[layer_index] += count;
        lane->layer_cpu_seconds[layer_index] += cpu_seconds;
    }
    fprintf(stderr,
            "ds4: [g132-general-layer] layer=%u route_cpu=%u "
            "route_gpu=%u bytes_non_attraversati=%llu "
            "cpu_wall_ms=%.6f gpu_wall_ms=%.6f "
            "expert_ms=%.6f "
            "gpu_wait_cpu_ms=%.6f cpu_wait_gpu_ms=%.6f "
            "wake_ms=%.6f quant_ms=%.6f reduce_ms=%.6f enqueue_ms=%.6f "
            "worker_window_ms=%.6f prepare_wait_ms=%.6f join=async "
            "eligible=%u rejected_cap=%u rejected_balance=%u "
            "target_cpu=%u\n",
            layer_index, count, gpu_routes,
            (unsigned long long)((uint64_t)count * native_bytes),
            cpu_seconds * 1000.0, gpu_seconds * 1000.0,
            expert_ms, gpu_wait_cpu_seconds * 1000.0,
            cpu_wait_gpu_seconds * 1000.0,
            lane->cpu_wake_seconds * 1000.0,
            lane->cpu_quant_seconds * 1000.0,
            lane->cpu_reduce_seconds * 1000.0,
            lane->dispatch_enqueue_seconds * 1000.0,
            lane->dispatch_worker_window_seconds * 1000.0,
            lane->dispatch_prepare_wait_seconds * 1000.0,
            eligible, rejected_cap, rejected_balance,
            layer_index < CUDA_G132_CPU_LANE_LAYER_COUNT
                ? lane->layer_target_cpu[layer_index] : 0u);
}

static void CUDART_CB cuda_g132_cpu_lane_join_gate_callback(void *arg) {
    cuda_g132_cpu_lane *lane = (cuda_g132_cpu_lane *)arg;
    os_mutex_lock(&lane->mutex);
    while (lane->job_active && lane->join_enqueued &&
           lane->completed_jobs < lane->job_count) {
        (void)os_cond_wait(&lane->done_cond, &lane->mutex);
    }
    if (lane->job_active && lane->join_enqueued) {
        lane->cpu_join_done = 1;
        if (lane->job_failed) {
            /* The worker zeroed host_partial: the H2D+add behind this
             * callback joins an exact zero.  Latch the fault so the next
             * engagement fails closed instead of trusting the lane. */
            lane->async_fault = 1;
            lane->failures++;
            lane->general_fallback_runtime++;
            fprintf(stderr,
                    "ds4: [g132-general] result=async-fault layer=%u "
                    "jobs=%u; partial joined as zeros, lane fails closed "
                    "from the next engagement\n",
                    lane->layer_index, lane->completed_jobs);
        }
        /* Workers are done: no CPU path touches resident expert bytes
         * after this point, so the arena readers and the staging lease can
         * go now instead of at a caller-side join.  The cache plan is NOT
         * reset here: prepare_general already took ownership
         * (plan.cpu_count = 0) and the route worker of the NEXT request
         * may be writing the plan concurrently. */
        cuda_g132_cpu_lane_release_reservations_locked(lane);
        {
            uint64_t expected = lane->source_generation;
            (void)g_moe_expert_cache.route_cpu_staging_generation
                .compare_exchange_strong(
                    expected, 0u, std::memory_order_acq_rel,
                    std::memory_order_acquire);
        }
        cuda_g132_cpu_lane_emit_general_stats_locked(lane);
    }
    os_mutex_unlock(&lane->mutex);
}

static void CUDART_CB cuda_g132_cpu_lane_dispatch_idle_callback(void *arg) {
    cuda_g132_cpu_lane *lane = (cuda_g132_cpu_lane *)arg;
    os_mutex_lock(&lane->mutex);
    if (lane->join_enqueued) {
        /* The partial H2D ahead of this callback has completed: only now
         * may a new dispatch reuse host_partial and the job slots. */
        lane->join_enqueued = 0;
        lane->job_active = 0;
        lane->input_ready = 0;
        lane->general_active = 0;
        os_cond_broadcast(&lane->work_cond);
        os_cond_broadcast(&lane->done_cond);
    }
    os_mutex_unlock(&lane->mutex);
}

static int cuda_g132_cpu_lane_enqueue_join_general(
        ds4_gpu_tensor *out, uint32_t layer_index) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    if (!lane.general_active || !out || !out->ptr) return 0;
    const double enqueue_started = cuda_wall_sec();
    os_mutex_lock(&lane.mutex);
    lane.join_enqueued = 1;
    lane.prev_dispatch_layer = layer_index;
    lane.prev_dispatch_valid = 1;
    os_mutex_unlock(&lane.mutex);
    const size_t bytes = (size_t)lane.out_dim * sizeof(float);
    int chain_ok =
        cuda_ok(cudaLaunchHostFunc(
                    lane.bridge_stream,
                    cuda_g132_cpu_lane_join_gate_callback, &lane),
                "G132 general join gate") &&
        cuda_ok(cudaMemcpyAsync(
                    lane.device_partial, lane.host_partial, bytes,
                    cudaMemcpyHostToDevice, lane.bridge_stream),
                "G132 CPU lane partial H2D") &&
        cuda_ok(cudaEventRecord(lane.partial_copy_done, lane.bridge_stream),
                "G132 CPU lane partial event") &&
        cuda_ok(cudaLaunchHostFunc(
                    lane.bridge_stream,
                    cuda_g132_cpu_lane_dispatch_idle_callback, &lane),
                "G132 general dispatch idle") &&
        cuda_ok(cudaStreamWaitEvent(0, lane.partial_copy_done, 0),
                "G132 CPU lane join wait");
    if (chain_ok) {
        /* Stream 0 already contains the hit/miss accumulation; the event
         * wait publishes the one CPU partial after those writes, exactly
         * like the old synchronous tail. */
        add_f32_u64_kernel<<<(lane.out_dim + 255u) / 256u, 256>>>(
            (float *)out->ptr, (const float *)out->ptr,
            lane.device_partial, lane.out_dim);
        chain_ok = cuda_ok(cudaGetLastError(), "G132 CPU lane output join");
    }
    os_mutex_lock(&lane.mutex);
    lane.dispatch_enqueue_seconds = cuda_wall_sec() - enqueue_started;
    if (!chain_ok) {
        /* Revoke the join ownership: whatever part of the chain was
         * enqueued becomes inert (both callbacks check join_enqueued under
         * this mutex) and the synchronous cancel below cleans the
         * dispatch.  The caller fails the request, so the layer output the
         * add never reached is not consumed. */
        lane.join_enqueued = 0;
        os_cond_broadcast(&lane.done_cond);
    }
    os_mutex_unlock(&lane.mutex);
    if (!chain_ok) {
        lane.general_fallback_runtime++;
        cuda_g132_cpu_lane_cancel_dispatch();
        return 0;
    }
    return 1;
}

static void cuda_g132_cpu_lane_discard_dispatch(void) {
    cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
    if (!lane.mutex_ready) return;
    os_mutex_lock(&lane.mutex);
    while (lane.job_active && lane.input_ready &&
           lane.completed_jobs < lane.job_count) {
        (void)os_cond_wait(&lane.done_cond, &lane.mutex);
    }
    lane.job_active = 0;
    lane.input_ready = 0;
    /* lane_econ: same async-join revocation as cancel_dispatch. */
    lane.join_enqueued = 0;
    lane.stats_pending = 0;
    lane.cpu_join_done = 0;
    const uint64_t source_generation = lane.source_generation;
    const int general_active = lane.general_active;
    cuda_g132_cpu_lane_release_reservations_locked(&lane);
    lane.general_active = 0;
    if (general_active) {
        uint64_t expected = source_generation;
        (void)g_moe_expert_cache.route_cpu_staging_generation
            .compare_exchange_strong(
                expected, 0u, std::memory_order_acq_rel,
                std::memory_order_acquire);
        g_moe_expert_cache.route_cpu_plan = cuda_g132_general_plan{};
    }
    os_cond_broadcast(&lane.work_cond);
    os_cond_broadcast(&lane.done_cond);
    os_mutex_unlock(&lane.mutex);
}

static const char *cuda_q1_0_mixed_representation_name(
        cuda_q1_0_mixed_representation representation) {
    switch (representation) {
    case CUDA_Q1_0_MIXED_IQ2_VRAM: return "iq2_vram";
    case CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM: return "iq2_snapshot_ram";
    case CUDA_Q1_0_MIXED_IQ2_TIER_RAM: return "iq2_tier_ram";
    case CUDA_Q1_0_MIXED_Q1_RESIDENT: return "q1_resident";
    case CUDA_Q1_0_MIXED_IQ2_CPU_EXACT: return "iq2_cpu_exact";
    default: return "unknown";
    }
}

static int cuda_q1_0_mixed_trace_requested(void) {
    const char *value = getenv("DS4_Q1_0_MIXED_TRACE");
    return value && strcmp(value, "1") == 0;
}

static int cuda_q1_0_resident_ram_ptrs(
        uint32_t layer, uint32_t expert,
        char **gate, char **up, char **down) {
    cuda_dynamic_arena *arena_ptr = cuda_q1_0_route_arena(layer);
    if (!arena_ptr || expert >= 256u ||
        !gate || !up || !down || layer >= arena_ptr->n_layer ||
        expert >= arena_ptr->n_expert ||
        arena_ptr->layers.size() != arena_ptr->n_layer) {
        return 0;
    }
    cuda_dynamic_arena &arena = *arena_ptr;
    const uint32_t entry = layer * arena.n_expert + expert;
    if (entry >= arena.active.size()) return 0;
    const cuda_dynamic_arena_binding &binding = arena.active[entry];
    if (!cuda_dynamic_arena_binding_valid(
            arena, binding, layer, expert,
            arena.snapshot_generation, DS4_GPU_ARENA_READY)) {
        return 0;
    }
    const ds4_gpu_dynamic_arena_layer &geometry = arena.layers[layer];
    cuda_dynamic_arena_slot &slot = arena.slots[binding.slot];
    *gate = slot.host_ptr;
    *up = *gate + geometry.gate_expert_bytes;
    *down = *up + geometry.up_expert_bytes;
    return 1;
}

static int cuda_q1_0_dual_sparse_pair_contains(
        uint32_t layer, uint32_t expert) {
    cuda_dynamic_arena &primary = g_dynamic_arena;
    cuda_dynamic_arena &q1 = g_q1_0_dynamic_arena;
    if (!cuda_q1_0_dual_sparse_companion_requested() ||
        !g_q1_0_dual_sparse_snapshot.ready ||
        g_q1_0_dual_sparse_snapshot.staged ||
        primary.backing != CUDA_DYNAMIC_ARENA_BACKING_PRIMARY ||
        q1.backing != CUDA_DYNAMIC_ARENA_BACKING_Q1_0 ||
        primary.snapshot_generation == 0 ||
        q1.snapshot_generation != primary.snapshot_generation ||
        g_q1_0_dual_sparse_snapshot.primary_generation !=
            primary.snapshot_generation ||
        g_q1_0_dual_sparse_snapshot.q1_generation !=
            q1.snapshot_generation ||
        layer >= primary.n_layer || layer >= q1.n_layer ||
        expert >= primary.n_expert || expert >= q1.n_expert ||
        primary.n_layer != q1.n_layer ||
        primary.n_expert != q1.n_expert) {
        return 0;
    }
    const uint32_t entry = layer * primary.n_expert + expert;
    if (entry >= primary.active.size() || entry >= q1.active.size()) {
        return 0;
    }
    return cuda_dynamic_arena_binding_valid(
               primary, primary.active[entry], layer, expert,
               primary.snapshot_generation, DS4_GPU_ARENA_READY) &&
        cuda_dynamic_arena_binding_valid(
               q1, q1.active[entry], layer, expert,
               q1.snapshot_generation, DS4_GPU_ARENA_READY);
}

static cuda_q1_0_mixed_representation cuda_q1_0_mixed_resolve(
        uint32_t layer, uint32_t expert) {
    cuda_q1_0_mixed_capture_router_mode();
    if (cuda_q1_0_snapshot_backing_requested()) {
        /* The exclusive snapshot physically contains Q1_0 bytes. The only
         * exact IQ2 representation in this mode is the protected VRAM seed;
         * generic snapshot/tier RAM pointers would alias Q1_0 slots and must
         * never be interpreted as IQ2. */
        if (cuda_moe_tiering_has_exact_vram(layer, expert)) {
            return CUDA_Q1_0_MIXED_IQ2_VRAM;
        }
        char *gate = NULL;
        char *up = NULL;
        char *down = NULL;
        return cuda_q1_0_resident_ram_ptrs(
                    layer, expert, &gate, &up, &down)
            ? CUDA_Q1_0_MIXED_Q1_RESIDENT
            : CUDA_Q1_0_MIXED_UNKNOWN;
    }
    if (g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
        !g_moe_tiering.compose_prefill_mass_tiering ||
        !g_moe_tiering.compose_router_open ||
        layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        g_moe_tiering.entries.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u) {
        return CUDA_Q1_0_MIXED_UNKNOWN;
    }
    const cuda_moe_tier_entry &tier = g_moe_tiering.entries[
        cuda_moe_tiering_entry_index(layer, expert)];
    if (cuda_moe_tiering_has_exact_vram(layer, expert)) {
        return tier.state == CUDA_MOE_TIER_VRAM_PROTECTED
            ? CUDA_Q1_0_MIXED_IQ2_VRAM
            : CUDA_Q1_0_MIXED_UNKNOWN;
    }
    char *gate = NULL;
    char *up = NULL;
    char *down = NULL;
    if (cuda_moe_tiering_snapshot_ram_ptrs(
            layer, expert, &gate, &up, &down)) {
        return tier.state == CUDA_MOE_TIER_RAM_PROBATION ||
               tier.state == CUDA_MOE_TIER_RAM_WARM
            ? CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM
            : CUDA_Q1_0_MIXED_UNKNOWN;
    }
    if (cuda_moe_tiering_ram_ptrs(
            layer, expert, &gate, &up, &down)) {
        return tier.state == CUDA_MOE_TIER_RAM_PROBATION ||
               tier.state == CUDA_MOE_TIER_RAM_WARM
            ? CUDA_Q1_0_MIXED_IQ2_TIER_RAM
            : CUDA_Q1_0_MIXED_UNKNOWN;
    }
    if (tier.state != CUDA_MOE_TIER_SSD_COLD || tier.has_2bit_ram) {
        return CUDA_Q1_0_MIXED_UNKNOWN;
    }
    if (cuda_q1_0_resident_ram_ptrs(
            layer, expert, &gate, &up, &down)) {
        return CUDA_Q1_0_MIXED_Q1_RESIDENT;
    }
    return CUDA_Q1_0_MIXED_UNKNOWN;
}

extern "C" int ds4_gpu_routed_moe_mixed_q1_0_one_tensor(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *main_model_map,
        uint64_t main_model_size,
        uint32_t layer_index,
        uint64_t main_gate_offset,
        uint64_t main_up_offset,
        uint64_t main_down_offset,
        uint32_t main_gate_type,
        uint32_t main_down_type,
        uint64_t main_gate_expert_bytes,
        uint64_t main_gate_row_bytes,
        uint64_t main_down_expert_bytes,
        uint64_t main_down_row_bytes,
        const void *q1_model_map,
        uint64_t q1_model_size,
        uint64_t q1_gate_offset,
        uint64_t q1_up_offset,
        uint64_t q1_down_offset,
        uint64_t q1_gate_expert_bytes,
        uint64_t q1_gate_row_bytes,
        uint64_t q1_down_expert_bytes,
        uint64_t q1_down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x,
        ds4_gpu_g133_epoch g133_epoch) {
    g_q1_0_mixed_calls++;
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    cuda_g130_attribution_state *attribution_state =
        cuda_g130_attribution_token_state();
    const int attribution = attribution_state != NULL;
    cuda_g130_attribution_span attribution_previous = CUDA_G130_ATTRIB_NONE;
    if (attribution) {
        attribution_previous = cuda_g130_attribution_switch(
            attribution_state,
            CUDA_G130_ATTRIB_MIXED_Q1_CALL);
    }
    cuda_g130_attribution_restore_guard attribution_restore = {
        attribution_state, attribution_previous
    };
#endif
    const int mixed_profile = cuda_q1_0_profile_requested();
    cuda_q1_0_mixed_profile_sample mixed_profile_sample;
    const double mixed_profile_call_started =
        mixed_profile ? cuda_wall_sec() : 0.0;
    double mixed_profile_phase_started = mixed_profile_call_started;
    if (mixed_profile) {
        memset(&mixed_profile_sample, 0, sizeof(mixed_profile_sample));
        cuda_q1_0_mixed_profile_record_entered(n_expert);
    }
    if (!out || !gate || !up || !mid || !down || !main_model_map ||
        !q1_model_map || !selected || !weights || !x ||
        n_expert == 0u || n_expert > CUDA_MOE_ROUTE_COUNT ||
        main_gate_type != 16u || main_down_type != 10u ||
        main_model_map != g_model_host_base ||
        main_model_size != g_model_registered_size ||
        q1_model_map != g_q1_0_sidecar_host_base ||
        q1_model_size != g_q1_0_sidecar_size ||
        !cuda_q1_0_route_arena(layer_index) ||
        selected->bytes < (uint64_t)n_expert * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_expert * sizeof(float) ||
        out->bytes < (uint64_t)out_dim * sizeof(float)) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=entry-contract "
                "layer=%u routes=%u main_type=%u/%u main_map=%u "
                "main_size=%llu registered_size=%llu q1_map=%u "
                "q1_size=%llu sidecar_size=%llu q1_arena=%u "
                "tier_entries=%llu selected_bytes=%llu weights_bytes=%llu "
                "out_bytes=%llu required_out=%llu\n",
                layer_index, n_expert, main_gate_type, main_down_type,
                main_model_map == g_model_host_base,
                (unsigned long long)main_model_size,
                (unsigned long long)g_model_registered_size,
                q1_model_map == g_q1_0_sidecar_host_base,
                (unsigned long long)q1_model_size,
                (unsigned long long)g_q1_0_sidecar_size,
                cuda_q1_0_route_arena(layer_index) != NULL,
                (unsigned long long)g_moe_tiering.entries.size(),
                (unsigned long long)(selected ? selected->bytes : 0),
                (unsigned long long)(weights ? weights->bytes : 0),
                (unsigned long long)(out ? out->bytes : 0),
                (unsigned long long)out_dim * sizeof(float));
        g_q1_0_mixed_failures++;
        return 0;
    }
    if (cuda_g133_shared_policy_active() &&
        !cuda_moe_route_worker_drain_completed("q1-0-mixed-entry")) {
        g_q1_0_mixed_failures++;
        return 0;
    }
    cuda_dynamic_arena *q1_arena = cuda_q1_0_route_arena(layer_index);
    if (!q1_arena) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=q1-arena-null "
                "layer=%u\n", layer_index);
        g_q1_0_mixed_failures++;
        return 0;
    }
    const ds4_gpu_dynamic_arena_layer &q1_geometry =
        q1_arena->layers[layer_index];
    if (q1_geometry.gate_offset != q1_gate_offset ||
        q1_geometry.up_offset != q1_up_offset ||
        q1_geometry.down_offset != q1_down_offset ||
        q1_geometry.gate_expert_bytes != q1_gate_expert_bytes ||
        q1_geometry.up_expert_bytes != q1_gate_expert_bytes ||
        q1_geometry.down_expert_bytes != q1_down_expert_bytes) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=q1-geometry "
                "layer=%u gate_offset=%llu/%llu up_offset=%llu/%llu "
                "down_offset=%llu/%llu gate_bytes=%llu/%llu "
                "up_bytes=%llu/%llu down_bytes=%llu/%llu\n",
                layer_index,
                (unsigned long long)q1_geometry.gate_offset,
                (unsigned long long)q1_gate_offset,
                (unsigned long long)q1_geometry.up_offset,
                (unsigned long long)q1_up_offset,
                (unsigned long long)q1_geometry.down_offset,
                (unsigned long long)q1_down_offset,
                (unsigned long long)q1_geometry.gate_expert_bytes,
                (unsigned long long)q1_gate_expert_bytes,
                (unsigned long long)q1_geometry.up_expert_bytes,
                (unsigned long long)q1_gate_expert_bytes,
                (unsigned long long)q1_geometry.down_expert_bytes,
                (unsigned long long)q1_down_expert_bytes);
        g_q1_0_mixed_failures++;
        return 0;
    }
    if (!cuda_q1_0_ssd_wrap_poll()) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed "
                "reason=ssd-wrap-terminal layer=%u\n", layer_index);
        g_q1_0_mixed_failures++;
        return 0;
    }

    /* The Q1 fallback path still needs the exact-IQ2 resolver: it decides
     * whether each full/open route is already resident as IQ2 or must use Q1
     * for this token. Promotion only controls later RAM-probation mutation. */
    const int q1_0_dynamic_promotion =
        cuda_q1_0_dynamic_promotion_requested();
    const int q1_0_mixed_exact_iq2_resolver =
        cuda_q1_0_mixed_exact_iq2_resolver_requested();
    if (q1_0_mixed_exact_iq2_resolver &&
        cuda_moe_gpu_routes_requested()) {
        cuda_moe_expert_cache *cache = cuda_moe_expert_cache_prepare(
            main_gate_expert_bytes, main_down_expert_bytes);
        if (!cache || !cache->route_thread_started ||
            !cache->route_worker_ready.load(std::memory_order_acquire) ||
            cache->route_worker_failed.load(std::memory_order_acquire) ||
            cache->route_stop.load(std::memory_order_acquire)) {
            fprintf(stderr,
                    "ds4: [q1-0-mixed] result=failed "
                    "reason=iq2-vram-cache-not-ready layer=%u\n",
                    layer_index);
            g_q1_0_mixed_failures++;
            return 0;
        }
    }
    if (q1_0_mixed_exact_iq2_resolver &&
        !cuda_q1_0_snapshot_backing_requested() &&
        !cuda_q1_0_dual_sparse_companion_requested() &&
        g_moe_tiering.entries.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=entry-contract "
                "layer=%u routes=%u main_type=%u/%u main_map=%u "
                "main_size=%llu registered_size=%llu q1_map=%u "
                "q1_size=%llu sidecar_size=%llu q1_arena=%u "
                "tier_entries=%llu selected_bytes=%llu weights_bytes=%llu "
                "out_bytes=%llu required_out=%llu\n",
                layer_index, n_expert, main_gate_type, main_down_type,
                main_model_map == g_model_host_base,
                (unsigned long long)main_model_size,
                (unsigned long long)g_model_registered_size,
                q1_model_map == g_q1_0_sidecar_host_base,
                (unsigned long long)q1_model_size,
                (unsigned long long)g_q1_0_sidecar_size,
                cuda_q1_0_route_arena(layer_index) != NULL,
                (unsigned long long)g_moe_tiering.entries.size(),
                (unsigned long long)(selected ? selected->bytes : 0),
                (unsigned long long)(weights ? weights->bytes : 0),
                (unsigned long long)(out ? out->bytes : 0),
                (unsigned long long)out_dim * sizeof(float));
        g_q1_0_mixed_failures++;
        return 0;
    }
    if (q1_0_dynamic_promotion &&
        (cuda_q1_0_snapshot_backing_requested() ||
         !cuda_q1_0_dual_arena_layer_active(layer_index) ||
         g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
         !g_moe_tiering.compose_prefill_mass_tiering ||
         !g_moe_tiering.compose_router_open ||
         g_iq1_promotion.requested_slots == 0u)) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed "
                "reason=dynamic-promotion-contract layer=%u dual=%u "
                "snapshot=%u tier_mode=%u compose=%u open=%u slots=%u\n",
                layer_index,
                cuda_q1_0_dual_arena_layer_active(layer_index) ? 1u : 0u,
                cuda_q1_0_snapshot_backing_requested() ? 1u : 0u,
                (unsigned)g_moe_tiering.mode,
                g_moe_tiering.compose_prefill_mass_tiering ? 1u : 0u,
                g_moe_tiering.compose_router_open ? 1u : 0u,
                g_iq1_promotion.requested_slots);
        g_q1_0_mixed_failures++;
        return 0;
    }

    const int recovery_trace_layer =
        g_expert_recovery_trace.enabled &&
        layer_index == g_expert_recovery_trace.target_layer;
    const uint64_t recovery_trace_token_index =
        cuda_expert_recovery_trace_layer_call(layer_index);
    if (recovery_trace_layer && recovery_trace_token_index == UINT64_MAX) {
        g_q1_0_mixed_failures++;
        return 0;
    }

    int32_t selected_host[CUDA_MOE_ROUTE_COUNT] = {0};
    float weights_host[CUDA_MOE_ROUTE_COUNT] = {0};
    if (mixed_profile) {
        const double d2h_started = cuda_wall_sec();
        mixed_profile_sample.entry_contract_calls++;
        mixed_profile_sample.entry_contract_seconds +=
            d2h_started - mixed_profile_phase_started;
        mixed_profile_phase_started = d2h_started;
    }
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    if (attribution) {
        (void)cuda_g130_attribution_switch(
            attribution_state, CUDA_G130_ATTRIB_SELECTION_D2H);
    }
#endif
    const int mixed_selection_d2h_ok =
        cuda_ok(cudaMemcpy(selected_host, selected->ptr,
                           (size_t)n_expert * sizeof(int32_t),
                           cudaMemcpyDeviceToHost),
                "Q1_0 mixed selected D2H") &&
        cuda_ok(cudaMemcpy(weights_host, weights->ptr,
                           (size_t)n_expert * sizeof(float),
                           cudaMemcpyDeviceToHost),
                "Q1_0 mixed weights D2H");
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    if (attribution) {
        (void)cuda_g130_attribution_switch(
            attribution_state, CUDA_G130_ATTRIB_MIXED_Q1_CALL);
    }
#endif
    if (mixed_profile) {
        const double d2h_finished = cuda_wall_sec();
        mixed_profile_sample.selection_d2h_calls++;
        mixed_profile_sample.selection_d2h_seconds +=
            d2h_finished - mixed_profile_phase_started;
        mixed_profile_phase_started = d2h_finished;
    }
    if (!mixed_selection_d2h_ok) {
        g_q1_0_mixed_failures++;
        return 0;
    }

#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    if (attribution) {
        (void)cuda_g130_attribution_switch(
            attribution_state, CUDA_G130_ATTRIB_ROUTE_CLASSIFY);
    }
#endif
    int32_t hot_selected[CUDA_MOE_ROUTE_COUNT] = {0};
    float hot_weights[CUDA_MOE_ROUTE_COUNT] = {0};
    int32_t cold_selected[CUDA_MOE_ROUTE_COUNT] = {0};
    float cold_weights[CUDA_MOE_ROUTE_COUNT] = {0};
    int32_t cpu_selected[CUDA_G132_CPU_LANE_MAX_ROUTES] = {0};
    float cpu_weights[CUDA_G132_CPU_LANE_MAX_ROUTES] = {0};
    cuda_q1_0_mixed_representation
        cpu_representations[CUDA_G132_CPU_LANE_MAX_ROUTES] = {};
    uint32_t cpu_slot_identities[CUDA_G132_CPU_LANE_MAX_ROUTES] = {0};
    uint64_t cpu_slot_generations[CUDA_G132_CPU_LANE_MAX_ROUTES] = {0};
    cuda_q1_0_mixed_representation
        route_representations[CUDA_MOE_ROUTE_COUNT] = {};
    uint8_t route_cpu_admitted[CUDA_MOE_ROUTE_COUNT] = {0};
    uint32_t route_cpu_slot_identities[CUDA_MOE_ROUTE_COUNT] = {0};
    uint64_t route_cpu_slot_generations[CUDA_MOE_ROUTE_COUNT] = {0};
    cuda_g132_cpu_lane_reservation_set cpu_lane_reservations;
    uint32_t hot_count = 0;
    uint32_t cold_count = 0;
    uint32_t cpu_count = 0;
    uint32_t iq2_vram = 0;
    uint32_t iq2_snapshot_ram = 0;
    uint32_t iq2_tier_ram = 0;
    uint32_t tier_route_entries = 0;
    uint32_t recovery_trace_rank = UINT32_MAX;
    float recovery_trace_weight = 0.0f;
    const char *recovery_trace_representation = NULL;
    const int cold_one_requested =
        cuda_q1_0_mixed_cold_one_requested();
    uint32_t cold_slot = UINT32_MAX;
    if (cold_one_requested) {
        if (!cuda_q1_0_dual_sparse_companion_requested() ||
            n_expert != CUDA_MOE_ROUTE_COUNT ||
            !g_q1_0_dual_sparse_snapshot.ready) {
            fprintf(stderr,
                    "ds4: [q1-0-mixed] result=failed "
                    "reason=cold-one-contract layer=%u routes=%u\n",
                    layer_index, n_expert);
            g_q1_0_mixed_cold_one_invariant_failures++;
            g_q1_0_mixed_failures++;
            return 0;
        }
        cold_slot = 0u;
        for (uint32_t route = 1; route < n_expert; route++) {
            if (weights_host[route] < weights_host[cold_slot]) {
                cold_slot = route;
            }
        }
    }
    for (uint32_t route = 0; route < n_expert; route++) {
        const int32_t expert_i = selected_host[route];
        if (expert_i < 0 || expert_i >= 256) {
            fprintf(stderr,
                    "ds4: [q1-0-mixed] result=failed reason=expert-range "
                    "layer=%u route=%u expert=%d\n",
                    layer_index, route, (int)expert_i);
            g_q1_0_mixed_failures++;
            return 0;
        }
        cuda_q1_0_mixed_representation representation =
            CUDA_Q1_0_MIXED_UNKNOWN;
        if (cold_one_requested) {
            if (!cuda_q1_0_dual_sparse_pair_contains(
                    layer_index, (uint32_t)expert_i)) {
                fprintf(stderr,
                        "ds4: [q1-0-mixed] result=failed "
                        "reason=dual-sparse-parity layer=%u route=%u expert=%d\n",
                        layer_index, route, (int)expert_i);
                g_q1_0_mixed_cold_one_invariant_failures++;
                g_q1_0_mixed_failures++;
                return 0;
            }
            representation = route == cold_slot
                ? CUDA_Q1_0_MIXED_Q1_RESIDENT
                : (cuda_moe_tiering_has_exact_vram(
                        layer_index, (uint32_t)expert_i)
                    ? CUDA_Q1_0_MIXED_IQ2_VRAM
                    : CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM);
        } else {
            representation = cuda_q1_0_mixed_resolve(
                layer_index, (uint32_t)expert_i);
        }
        route_representations[route] = representation;
        const cuda_moe_tier_entry *tier =
            g_moe_tiering.entries.size() ==
                    (size_t)CUDA_MOE_LAYER_COUNT * 256u
                ? &g_moe_tiering.entries[cuda_moe_tiering_entry_index(
                    layer_index, (uint32_t)expert_i)]
                : NULL;
        if (tier) tier_route_entries++;
        iq2_vram += representation == CUDA_Q1_0_MIXED_IQ2_VRAM;
        iq2_snapshot_ram +=
            representation == CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM;
        iq2_tier_ram +=
            representation == CUDA_Q1_0_MIXED_IQ2_TIER_RAM;
    }

    if (cuda_g132_cpu_lane_requested()) {
        for (uint32_t route = 0; route < n_expert; route++) {
            if (route_representations[route] ==
                    CUDA_Q1_0_MIXED_Q1_RESIDENT) {
                g_g132_cpu_lane.skipped_cold++;
            }
            if (route_representations[route] !=
                    CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM &&
                route_representations[route] !=
                    CUDA_Q1_0_MIXED_IQ2_TIER_RAM) {
                continue;
            }
            const int32_t expert_i = selected_host[route];
            const cuda_moe_tier_entry *tier =
                g_moe_tiering.entries.size() ==
                        (size_t)CUDA_MOE_LAYER_COUNT * 256u
                    ? &g_moe_tiering.entries[cuda_moe_tiering_entry_index(
                        layer_index, (uint32_t)expert_i)]
                    : NULL;
            if (!tier ||
                (tier->state != CUDA_MOE_TIER_RAM_WARM &&
                 tier->state != CUDA_MOE_TIER_RAM_PROBATION)) {
                g_g132_cpu_lane.not_pinned++;
            }
        }
        const cuda_moe_tier_state admission_states[2] = {
            CUDA_MOE_TIER_RAM_WARM,
            CUDA_MOE_TIER_RAM_PROBATION,
        };
        uint32_t admitted = 0;
        for (uint32_t state_i = 0; state_i < 2u; state_i++) {
            for (uint32_t route = 0; route < n_expert; route++) {
                const cuda_q1_0_mixed_representation representation =
                    route_representations[route];
                if (representation != CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM &&
                    representation != CUDA_Q1_0_MIXED_IQ2_TIER_RAM) {
                    continue;
                }
                const int32_t expert_i = selected_host[route];
                const cuda_moe_tier_entry *tier =
                    g_moe_tiering.entries.size() ==
                            (size_t)CUDA_MOE_LAYER_COUNT * 256u
                        ? &g_moe_tiering.entries[cuda_moe_tiering_entry_index(
                            layer_index, (uint32_t)expert_i)]
                        : NULL;
                if (!tier || tier->state != admission_states[state_i]) {
                    continue;
                }
                const char *resident_gate = NULL;
                const char *resident_up = NULL;
                const char *resident_down = NULL;
                uint32_t slot_identity = UINT32_MAX;
                uint64_t slot_generation = 0;
                int reservation_busy = 0;
                if (!cuda_g132_cpu_lane_reserve_resident_iq2_ptrs(
                        layer_index, (uint32_t)expert_i, representation,
                        &resident_gate, &resident_up, &resident_down,
                        &slot_identity, &slot_generation,
                        &reservation_busy)) {
                    if (reservation_busy) {
                        g_g132_cpu_lane.reservation_rejected++;
                    } else {
                        g_g132_cpu_lane.not_pinned++;
                    }
                    continue;
                }
                if (admitted >= g_g132_cpu_lane.max_experts_per_layer) {
                    cuda_g132_cpu_lane_release_slot(slot_identity);
                    g_g132_cpu_lane.cap_rejected++;
                    continue;
                }
                cpu_lane_reservations.add(slot_identity);
                route_cpu_admitted[route] = 1u;
                route_cpu_slot_identities[route] = slot_identity;
                route_cpu_slot_generations[route] = slot_generation;
                admitted++;
                g_g132_cpu_lane.resident_hits++;
            }
        }
    }

    for (uint32_t route = 0; route < n_expert; route++) {
        const int32_t expert_i = selected_host[route];
        const cuda_q1_0_mixed_representation source_representation =
            route_representations[route];
        cuda_q1_0_mixed_representation representation =
            route_cpu_admitted[route]
                ? CUDA_Q1_0_MIXED_IQ2_CPU_EXACT
                : source_representation;
        const cuda_moe_tier_entry *tier =
            g_moe_tiering.entries.size() ==
                    (size_t)CUDA_MOE_LAYER_COUNT * 256u
                ? &g_moe_tiering.entries[cuda_moe_tiering_entry_index(
                    layer_index, (uint32_t)expert_i)]
                : NULL;
        if (cuda_expert_recovery_trace_target(
                layer_index, (uint32_t)expert_i)) {
            if (recovery_trace_rank != UINT32_MAX) {
                cuda_expert_recovery_trace_fail("duplicate_target_route");
                g_q1_0_mixed_failures++;
                return 0;
            }
            recovery_trace_rank = route;
            recovery_trace_weight = weights_host[route];
            recovery_trace_representation =
                cuda_q1_0_mixed_representation_name(representation);
        }
        if (cuda_q1_0_mixed_trace_requested()) {
            fprintf(stderr,
                    "ds4: [q1-0-mixed-route] layer=%u route=%u expert=%d "
                    "weight=%.9g representation=%s tier=%u has_2bit_ram=%u "
                    "source_representation=%s cpu_slot=%u "
                    "cpu_slot_generation=%llu cpu_pageable=%u "
                    "primary_snapshot=%llu q1_snapshot=%llu\n",
                    layer_index, route, (int)expert_i, weights_host[route],
                    cuda_q1_0_mixed_representation_name(representation),
                    tier ? (unsigned)tier->state : 0u,
                    tier ? (unsigned)tier->has_2bit_ram : 0u,
                    cuda_q1_0_mixed_representation_name(
                        source_representation),
                    route_cpu_admitted[route]
                        ? route_cpu_slot_identities[route] : UINT32_MAX,
                    (unsigned long long)(route_cpu_admitted[route]
                        ? route_cpu_slot_generations[route] : 0u),
                    route_cpu_admitted[route] ? 0u : UINT32_MAX,
                    (unsigned long long)g_moe_tiering.snapshot_generation,
                    (unsigned long long)
                        q1_arena->snapshot_generation);
            g_q1_0_mixed_trace_rows++;
        }
        if (representation == CUDA_Q1_0_MIXED_IQ2_VRAM ||
            representation == CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM ||
            representation == CUDA_Q1_0_MIXED_IQ2_TIER_RAM) {
            hot_selected[hot_count] = expert_i;
            hot_weights[hot_count] = weights_host[route];
            hot_count++;
        } else if (representation == CUDA_Q1_0_MIXED_IQ2_CPU_EXACT) {
            cpu_selected[cpu_count] = expert_i;
            cpu_weights[cpu_count] = weights_host[route];
            cpu_representations[cpu_count] = source_representation;
            cpu_slot_identities[cpu_count] =
                route_cpu_slot_identities[route];
            cpu_slot_generations[cpu_count] =
                route_cpu_slot_generations[route];
            cpu_count++;
        } else if (representation == CUDA_Q1_0_MIXED_Q1_RESIDENT) {
            cold_selected[cold_count] = expert_i;
            cold_weights[cold_count] = weights_host[route];
            cold_count++;
        } else {
            fprintf(stderr,
                    "ds4: [q1-0-mixed] result=failed reason=unresolved "
                    "layer=%u route=%u expert=%d router=unchanged\n",
                    layer_index, route, (int)expert_i);
            g_q1_0_mixed_failures++;
            return 0;
        }
    }
    if (q1_0_mixed_exact_iq2_resolver &&
        !cuda_q1_0_snapshot_backing_requested() &&
        !cuda_q1_0_dual_sparse_companion_requested() &&
        tier_route_entries != n_expert) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed "
                "reason=route-entry-contract layer=%u routes=%u "
                "tier_route_entries=%u tier_entries=%llu\n",
                layer_index, n_expert, tier_route_entries,
                (unsigned long long)g_moe_tiering.entries.size());
        g_q1_0_mixed_failures++;
        return 0;
    }
    g_q1_0_mixed_tier_route_entries += tier_route_entries;

    if (cold_one_requested) {
        if (hot_count + cpu_count != CUDA_MOE_ROUTE_COUNT - 1u ||
            cold_count != 1u) {
            fprintf(stderr,
                    "ds4: [q1-0-mixed] result=failed "
                    "reason=cold-one-count layer=%u hot=%u q1=%u cpu=%u\n",
                    layer_index, hot_count, cold_count, cpu_count);
            g_q1_0_mixed_cold_one_invariant_failures++;
            g_q1_0_mixed_failures++;
            return 0;
        }
        g_q1_0_mixed_cold_one_calls++;
        g_q1_0_mixed_cold_one_hot_routes += hot_count + cpu_count;
        g_q1_0_mixed_cold_one_q1_routes += cold_count;
    }

#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    if (attribution) {
        (void)cuda_g130_attribution_switch(
            attribution_state, CUDA_G130_ATTRIB_MIXED_Q1_CALL);
    }
#endif

    if (mixed_profile) {
        const double classify_finished = cuda_wall_sec();
        mixed_profile_sample.classify_map_calls++;
        mixed_profile_sample.classify_map_seconds +=
            classify_finished - mixed_profile_phase_started;
        mixed_profile_phase_started = classify_finished;
    }

    if (cold_count == 0u && cpu_count == 0u) {
        const double hot_branch_started = mixed_profile
            ? mixed_profile_phase_started : 0.0;
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        if (attribution) {
            (void)cuda_g130_attribution_switch(
                attribution_state, CUDA_G130_ATTRIB_HOT_ROUTE);
        }
#endif
        const int ok = g_cuda_routed_moe_launch_dispatch(
            out, gate, up, mid, down,
            main_model_map, main_model_size, layer_index,
            main_gate_offset, main_up_offset, main_down_offset,
            main_gate_type, main_down_type,
            main_gate_expert_bytes, main_gate_row_bytes,
            main_down_expert_bytes, main_down_row_bytes,
            expert_in_dim, expert_mid_dim, out_dim,
            selected, weights, NULL, n_expert, clamp, x, 1u, NULL, NULL,
            NULL, g133_epoch);
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        if (attribution) {
            (void)cuda_g130_attribution_switch(
                attribution_state,
                CUDA_G130_ATTRIB_MIXED_Q1_CALL);
        }
#endif
        if (mixed_profile) {
            const double hot_branch_finished = cuda_wall_sec();
            mixed_profile_sample.hot_branch_calls++;
            mixed_profile_sample.hot_branch_seconds +=
                hot_branch_finished - hot_branch_started;
            mixed_profile_phase_started = hot_branch_finished;
        }
        if (!ok) {
            g_q1_0_mixed_failures++;
            return 0;
        }
        g_q1_0_mixed_all_iq2++;
        g_q1_0_mixed_iq2_vram += iq2_vram;
        g_q1_0_mixed_iq2_snapshot_ram += iq2_snapshot_ram;
        g_q1_0_mixed_iq2_tier_ram += iq2_tier_ram;
        if (recovery_trace_rank != UINT32_MAX &&
            !cuda_expert_recovery_trace_capture(
                layer_index, g_expert_recovery_trace.target_expert,
                recovery_trace_rank, recovery_trace_weight,
                recovery_trace_representation, recovery_trace_token_index,
                g_moe_tiering.call_tick, x, expert_in_dim, NULL)) {
            g_q1_0_mixed_failures++;
            return 0;
        }
        if (mixed_profile) {
            const double publish_finished = cuda_wall_sec();
            mixed_profile_sample.join_publish_calls++;
            mixed_profile_sample.join_publish_seconds +=
                publish_finished - mixed_profile_phase_started;
            cuda_q1_0_mixed_profile_record_completed(
                mixed_profile_sample,
                publish_finished - mixed_profile_call_started,
                hot_count, cold_count, 0);
        }
        return 1;
    }

    const uint64_t iq2_ssd_bytes_before = g_moe_tiering.ssd_bytes;
    const uint64_t iq2_cold_to_ram_before = g_moe_tiering.cold_to_ram;

    int cpu_lane_active = 0;
    if (cpu_count != 0u) {
        const int cpu_lane_prepared = cuda_g132_cpu_lane_prepare_dispatch(
            layer_index,
            main_gate_expert_bytes, main_gate_row_bytes,
            main_down_expert_bytes, main_down_row_bytes,
            expert_in_dim, expert_mid_dim, out_dim,
            cpu_selected, cpu_weights, cpu_representations,
            cpu_slot_identities, cpu_slot_generations,
            cpu_count, clamp);
        if (cpu_lane_prepared) cpu_lane_reservations.transfer();
        cpu_lane_active = cpu_lane_prepared &&
            cuda_g132_cpu_lane_record_input_source();
        if (!cpu_lane_active) {
            cuda_g132_cpu_lane_cancel_dispatch();
            if (!cpu_lane_prepared) cpu_lane_reservations.release_all();
            g_g132_cpu_lane.failures++;
            fprintf(stderr,
                    "ds4: [g132-cpu-lane] result=fail-open layer=%u "
                    "routes=%u fallback=iq2-gpu\n",
                    layer_index, cpu_count);
            hot_count = 0;
            for (uint32_t route = 0; route < n_expert; route++) {
                if (route_representations[route] ==
                        CUDA_Q1_0_MIXED_Q1_RESIDENT) {
                    continue;
                }
                hot_selected[hot_count] = selected_host[route];
                hot_weights[hot_count] = weights_host[route];
                hot_count++;
            }
            if (recovery_trace_rank != UINT32_MAX) {
                recovery_trace_representation =
                    cuda_q1_0_mixed_representation_name(
                        route_representations[recovery_trace_rank]);
            }
            cpu_count = 0;
        }
    }
    const uint32_t fallback_route_count = cold_count + cpu_count;

    const uint64_t max_routes = CUDA_MOE_ROUTE_COUNT;
    const uint64_t out_bytes = (uint64_t)out_dim * sizeof(float);
    const uint64_t xq_blocks = expert_in_dim / CUDA_QK_K;
    const uint64_t xq_bytes = xq_blocks * sizeof(cuda_block_q8_K);
    const uint64_t off_hot_selected = 0;
    const uint64_t off_hot_weights = cuda_round_up(
        off_hot_selected + max_routes * sizeof(int32_t), 4u);
    const uint64_t off_cold_selected = cuda_round_up(
        off_hot_weights + max_routes * sizeof(float), 4u);
    const uint64_t off_cold_weights = cuda_round_up(
        off_cold_selected + max_routes * sizeof(int32_t), 4u);
    const uint64_t off_cold_out = cuda_round_up(
        off_cold_weights + max_routes * sizeof(float), 256u);
    const uint64_t cold_down_bytes = std::max(
        (uint64_t)fallback_route_count * out_bytes, xq_bytes);
    const uint64_t off_cold_down = cuda_round_up(
        off_cold_out + out_bytes, 256u);
    if (cold_down_bytes > UINT64_MAX - off_cold_down ||
        !cuda_iq1_mixed_scratch_ensure(off_cold_down + cold_down_bytes)) {
        if (cpu_lane_active) cuda_g132_cpu_lane_cancel_dispatch();
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=scratch "
                "layer=%u requested=%llu cold_down=%llu\n",
                layer_index,
                (unsigned long long)(off_cold_down + cold_down_bytes),
                (unsigned long long)cold_down_bytes);
        g_q1_0_mixed_failures++;
        return 0;
    }
    char *scratch = (char *)g_iq1_mixed_scratch;
    int32_t *device_hot_selected =
        (int32_t *)(scratch + off_hot_selected);
    float *device_hot_weights = (float *)(scratch + off_hot_weights);
    int32_t *device_cold_selected =
        (int32_t *)(scratch + off_cold_selected);
    float *device_cold_weights = (float *)(scratch + off_cold_weights);
    float *device_cold_out = (float *)(scratch + off_cold_out);
    float *device_cold_down = (float *)(scratch + off_cold_down);
    if (mixed_profile) {
        const double scratch_finished = cuda_wall_sec();
        mixed_profile_sample.scratch_prepare_calls++;
        mixed_profile_sample.scratch_prepare_seconds +=
            scratch_finished - mixed_profile_phase_started;
        mixed_profile_phase_started = scratch_finished;
    }
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    if (attribution) {
        (void)cuda_g130_attribution_switch(
            attribution_state, CUDA_G130_ATTRIB_H2D_ENQUEUE);
    }
#endif
    const int metadata_h2d_ok = !((hot_count != 0u &&
         (!cuda_ok(cudaMemcpy(device_hot_selected, hot_selected,
                              (size_t)hot_count * sizeof(int32_t),
                              cudaMemcpyHostToDevice),
                   "Q1_0 mixed hot selected H2D") ||
          !cuda_ok(cudaMemcpy(device_hot_weights, hot_weights,
                              (size_t)hot_count * sizeof(float),
                              cudaMemcpyHostToDevice),
                   "Q1_0 mixed hot weights H2D"))) ||
        !cuda_ok(cudaMemcpy(device_cold_selected, cold_selected,
                            (size_t)cold_count * sizeof(int32_t),
                            cudaMemcpyHostToDevice),
                 "Q1_0 mixed cold selected H2D") ||
        !cuda_ok(cudaMemcpy(device_cold_weights, cold_weights,
                            (size_t)cold_count * sizeof(float),
                            cudaMemcpyHostToDevice),
                 "Q1_0 mixed cold weights H2D"));
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    if (attribution) {
        (void)cuda_g130_attribution_switch(
            attribution_state, CUDA_G130_ATTRIB_MIXED_Q1_CALL);
    }
#endif
    if (!metadata_h2d_ok) {
        if (cpu_lane_active) cuda_g132_cpu_lane_cancel_dispatch();
        g_q1_0_mixed_failures++;
        return 0;
    }
    if (mixed_profile) {
        const double metadata_finished = cuda_wall_sec();
        mixed_profile_sample.metadata_h2d_calls++;
        mixed_profile_sample.metadata_h2d_seconds +=
            metadata_finished - mixed_profile_phase_started;
        mixed_profile_phase_started = metadata_finished;
    }

    int ok = 1;
    if (hot_count != 0u) {
        const ds4_gpu_tensor hot_selected_tensor = {
            device_hot_selected,
            NULL,
            (uint64_t)hot_count * sizeof(int32_t), 0
        };
        const ds4_gpu_tensor hot_weights_tensor = {
            device_hot_weights,
            NULL,
            (uint64_t)hot_count * sizeof(float), 0
        };
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        if (attribution) {
            (void)cuda_g130_attribution_switch(
                attribution_state, CUDA_G130_ATTRIB_HOT_ROUTE);
        }
#endif
        ok = g_cuda_routed_moe_launch_dispatch(
            out, gate, up, mid, down,
            main_model_map, main_model_size, layer_index,
            main_gate_offset, main_up_offset, main_down_offset,
            main_gate_type, main_down_type,
            main_gate_expert_bytes, main_gate_row_bytes,
            main_down_expert_bytes, main_down_row_bytes,
            expert_in_dim, expert_mid_dim, out_dim,
            &hot_selected_tensor, &hot_weights_tensor, NULL,
            hot_count, clamp, x, 1u, NULL, NULL, NULL, g133_epoch);
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        if (attribution) {
            (void)cuda_g130_attribution_switch(
                attribution_state,
                CUDA_G130_ATTRIB_MIXED_Q1_CALL);
        }
#endif
    } else {
        ok = cuda_ok(cudaMemsetAsync(out->ptr, 0, (size_t)out_bytes, 0),
                     "Q1_0 mixed empty IQ2 output");
    }
    if (!ok) {
        if (cpu_lane_active) {
            (void)cudaStreamSynchronize(g_g132_cpu_lane.bridge_stream);
            cuda_g132_cpu_lane_cancel_dispatch();
        }
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=iq2-hot-launch "
                "layer=%u hot=%u\n", layer_index, hot_count);
        g_q1_0_mixed_failures++;
        return 0;
    }
    if (cpu_lane_active && !cuda_g132_cpu_lane_enqueue_input(x)) {
        g_g132_cpu_lane.failed_open = 1;
        fprintf(stderr,
                "ds4: [g132-cpu-lane] result=fail-open layer=%u "
                "routes=%u reason=input-d2h fallback=iq2-gpu\n",
                layer_index, cpu_count);
        const uint32_t cpu_gpu_offset = cold_count;
        if (!cuda_ok(cudaMemcpy(device_cold_selected + cpu_gpu_offset,
                                cpu_selected,
                                (size_t)cpu_count * sizeof(int32_t),
                                cudaMemcpyHostToDevice),
                     "G132 fail-open IQ2 selected H2D") ||
            !cuda_ok(cudaMemcpy(device_cold_weights + cpu_gpu_offset,
                                cpu_weights,
                                (size_t)cpu_count * sizeof(float),
                                cudaMemcpyHostToDevice),
                     "G132 fail-open IQ2 weights H2D")) {
            g_q1_0_mixed_failures++;
            return 0;
        }
        const ds4_gpu_tensor cpu_gpu_selected_tensor = {
            device_cold_selected + cpu_gpu_offset,
            NULL,
            (uint64_t)cpu_count * sizeof(int32_t), 0
        };
        const ds4_gpu_tensor cpu_gpu_weights_tensor = {
            device_cold_weights + cpu_gpu_offset,
            NULL,
            (uint64_t)cpu_count * sizeof(float), 0
        };
        ds4_gpu_tensor cpu_gpu_out_tensor = {
            device_cold_out, NULL, out_bytes, 0
        };
        ds4_gpu_tensor cpu_gpu_down_tensor = {
            device_cold_down, NULL, cold_down_bytes, 0
        };
        int cpu_gpu_ok = g_cuda_routed_moe_launch_dispatch(
            &cpu_gpu_out_tensor, gate, up, mid, &cpu_gpu_down_tensor,
            main_model_map, main_model_size, layer_index,
            main_gate_offset, main_up_offset, main_down_offset,
            main_gate_type, main_down_type,
            main_gate_expert_bytes, main_gate_row_bytes,
            main_down_expert_bytes, main_down_row_bytes,
            expert_in_dim, expert_mid_dim, out_dim,
            &cpu_gpu_selected_tensor, &cpu_gpu_weights_tensor, NULL,
            cpu_count, clamp, x, 1u, NULL, NULL, NULL, g133_epoch);
        if (cpu_gpu_ok) {
            add_f32_u64_kernel<<<(out_dim + 255u) / 256u, 256>>>(
                (float *)out->ptr, (const float *)out->ptr,
                device_cold_out, out_dim);
            cpu_gpu_ok = cuda_ok(
                cudaGetLastError(), "G132 fail-open IQ2 output join");
        }
        if (!cpu_gpu_ok) {
            g_q1_0_mixed_failures++;
            return 0;
        }
        if (recovery_trace_rank != UINT32_MAX) {
            recovery_trace_representation =
                cuda_q1_0_mixed_representation_name(
                    route_representations[recovery_trace_rank]);
        }
        cpu_count = 0;
        cpu_lane_active = 0;
    }
    if (cuda_g133_shared_policy_active() &&
        !cuda_moe_route_worker_drain_completed("q1-0-mixed-policy")) {
        if (cpu_lane_active) cuda_g132_cpu_lane_discard_dispatch();
        g_q1_0_mixed_failures++;
        return 0;
    }
    const uint64_t iq2_ssd_bytes_after_hot = g_moe_tiering.ssd_bytes;
    const uint64_t iq2_cold_to_ram_after_hot = g_moe_tiering.cold_to_ram;
    if (iq2_ssd_bytes_after_hot != iq2_ssd_bytes_before ||
        iq2_cold_to_ram_after_hot != iq2_cold_to_ram_before) {
        if (cpu_lane_active) cuda_g132_cpu_lane_discard_dispatch();
        const uint64_t delta = iq2_ssd_bytes_after_hot >= iq2_ssd_bytes_before
            ? iq2_ssd_bytes_after_hot - iq2_ssd_bytes_before : 0;
        g_q1_0_mixed_iq2_ssd_bytes += delta;
        g_q1_0_mixed_iq2_ssd_violations++;
        g_q1_0_mixed_failures++;
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed "
                "reason=current-token-iq2-ssd layer=%u bytes=%llu "
                "cold_to_ram_delta=%llu\n",
                layer_index, (unsigned long long)delta,
                (unsigned long long)(
                    iq2_cold_to_ram_after_hot - iq2_cold_to_ram_before));
        return 0;
    }
    if (mixed_profile) {
        const double hot_branch_finished = cuda_wall_sec();
        mixed_profile_sample.hot_branch_calls++;
        mixed_profile_sample.hot_branch_seconds +=
            hot_branch_finished - mixed_profile_phase_started;
        mixed_profile_phase_started = hot_branch_finished;
    }

    /* The IQ2 route worker already observed the hot subset. Q1 routes bypass
     * that worker, so account for their router demand on the same logical
     * clock tick. This changes residency policy only for future tokens; the
     * current token remains Q1 and performs no IQ2 SSD read. */
    if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
        if (hot_count == 0u) {
            if (cuda_moe_tiering_advance_call_tick(
                    "q1-0-mixed-cold-only")) {
                g_moe_tiering.calls++;
            }
        }
        g_moe_tiering.selected += cold_count + cpu_count;
        for (uint32_t route = 0; route < cold_count; route++) {
            (void)cuda_moe_tiering_observe_route(
                layer_index, (uint32_t)cold_selected[route],
                cold_weights[route], g133_epoch);
        }
        for (uint32_t route = 0; route < cpu_count; route++) {
            (void)cuda_moe_tiering_observe_route(
                layer_index, (uint32_t)cpu_selected[route],
                cpu_weights[route], g133_epoch);
        }
    }
    if (mixed_profile) {
        const double tier_observe_finished = cuda_wall_sec();
        mixed_profile_sample.tier_observe_calls++;
        mixed_profile_sample.tier_observe_seconds +=
            tier_observe_finished - mixed_profile_phase_started;
        mixed_profile_phase_started = tier_observe_finished;
    }

    const ds4_gpu_tensor cold_selected_tensor = {
        device_cold_selected,
        NULL,
        (uint64_t)cold_count * sizeof(int32_t), 0
    };
    const ds4_gpu_tensor cold_weights_tensor = {
        device_cold_weights,
        NULL,
        (uint64_t)cold_count * sizeof(float), 0
    };
    ds4_gpu_tensor cold_out_tensor = {
        device_cold_out, NULL, out_bytes, 0
    };
    ds4_gpu_tensor cold_down_tensor = {
        device_cold_down, NULL, cold_down_bytes, 0
    };
    cuda_q1_0_mixed_profile_sample *previous_profile_sample = NULL;
    if (mixed_profile) {
        const double q1_call_started = cuda_wall_sec();
        mixed_profile_sample.q1_dispatch_prepare_calls++;
        mixed_profile_sample.q1_dispatch_prepare_seconds +=
            q1_call_started - mixed_profile_phase_started;
        mixed_profile_sample.q1_call_started = q1_call_started;
        previous_profile_sample = g_q1_0_mixed_profile_current_sample;
        g_q1_0_mixed_profile_current_sample = &mixed_profile_sample;
    }
    if (cold_count != 0u) {
        ok = g_cuda_routed_moe_launch_dispatch(
            &cold_out_tensor, gate, up, mid, &cold_down_tensor,
            q1_model_map, q1_model_size, layer_index,
            q1_gate_offset, q1_up_offset, q1_down_offset,
            41u, 41u,
            q1_gate_expert_bytes, q1_gate_row_bytes,
            q1_down_expert_bytes, q1_down_row_bytes,
            expert_in_dim, expert_mid_dim, out_dim,
            &cold_selected_tensor, &cold_weights_tensor, NULL,
            cold_count, clamp, x, 1u, NULL, NULL, cold_selected,
            g133_epoch);
    }
    if (mixed_profile) {
        g_q1_0_mixed_profile_current_sample = previous_profile_sample;
        mixed_profile_phase_started = cuda_wall_sec();
    }
    if (!ok) {
        if (cpu_lane_active) cuda_g132_cpu_lane_discard_dispatch();
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=q1-cold-launch "
                "layer=%u q1=%u\n", layer_index, cold_count);
        g_q1_0_mixed_failures++;
        return 0;
    }
    cudaEvent_t join_begin = NULL;
    cudaEvent_t join_end = NULL;
    if (cuda_q1_0_profile_requested()) {
        const cudaError_t begin_create = cudaEventCreate(&join_begin);
        const cudaError_t end_create = begin_create == cudaSuccess ?
            cudaEventCreate(&join_end) : begin_create;
        const cudaError_t begin_record = end_create == cudaSuccess ?
            cudaEventRecord(join_begin, 0) : end_create;
        if (begin_record != cudaSuccess) {
            if (join_begin) (void)cudaEventDestroy(join_begin);
            if (join_end) (void)cudaEventDestroy(join_end);
            join_begin = NULL;
            join_end = NULL;
            g_q1_0_profile.timer_failures++;
            cuda_q1_0_mixed_profile_record_timer_failure();
            (void)cudaGetLastError();
        }
    }
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    if (attribution) {
        (void)cuda_g130_attribution_switch(
            attribution_state, CUDA_G130_ATTRIB_MIXED_JOIN);
    }
#endif
    int mixed_join_ok = 1;
    if (cold_count != 0u) {
        add_f32_u64_kernel<<<(out_dim + 255u) / 256u, 256>>>(
            (float *)out->ptr, (const float *)out->ptr,
            device_cold_out, out_dim);
        mixed_join_ok =
            cuda_ok(cudaGetLastError(), "Q1_0 mixed output join");
    }
    const float *cpu_captured_input = NULL;
    if (mixed_join_ok && cpu_lane_active) {
        const double cpu_join_started = mixed_profile ? cuda_wall_sec() : 0.0;
        mixed_join_ok = cuda_g132_cpu_lane_wait_and_join(
            out, layer_index, &cpu_captured_input);
        if (!mixed_join_ok) {
            /* Fence the abandoned CPU partial, then recompute only the
             * CPU-owned exact-IQ2 routes through their existing GPU path. */
            cuda_g132_cpu_lane &lane = g_g132_cpu_lane;
            lane.failures++;
            lane.failed_open = 1;
            cuda_g132_cpu_lane_discard_dispatch();
            const cudaError_t bridge_fence =
                cudaStreamSynchronize(lane.bridge_stream);
            const cudaError_t output_fence = cudaStreamSynchronize(0);
            if (bridge_fence != cudaSuccess) {
                (void)cuda_ok(bridge_fence,
                              "G132 fail-open bridge fence");
            }
            if (output_fence != cudaSuccess) {
                (void)cuda_ok(output_fence,
                              "G132 fail-open output fence");
            }
            (void)cudaGetLastError();

            fprintf(stderr,
                    "ds4: [g132-cpu-lane] result=fail-open layer=%u "
                    "routes=%u reason=post-dispatch fallback=iq2-gpu\n",
                    layer_index, cpu_count);
            const uint32_t cpu_gpu_offset = cold_count;
            if (recovery_trace_rank != UINT32_MAX) {
                recovery_trace_representation =
                    cuda_q1_0_mixed_representation_name(
                        route_representations[recovery_trace_rank]);
            }
            if (!cuda_ok(cudaMemcpy(
                             device_cold_selected + cpu_gpu_offset,
                             cpu_selected,
                             (size_t)cpu_count * sizeof(int32_t),
                             cudaMemcpyHostToDevice),
                         "G132 post-dispatch IQ2 selected H2D") ||
                !cuda_ok(cudaMemcpy(
                             device_cold_weights + cpu_gpu_offset,
                             cpu_weights,
                             (size_t)cpu_count * sizeof(float),
                             cudaMemcpyHostToDevice),
                         "G132 post-dispatch IQ2 weights H2D")) {
                mixed_join_ok = 0;
            } else {
                const ds4_gpu_tensor cpu_gpu_selected_tensor = {
                    device_cold_selected + cpu_gpu_offset,
                    NULL,
                    (uint64_t)cpu_count * sizeof(int32_t), 0
                };
                const ds4_gpu_tensor cpu_gpu_weights_tensor = {
                    device_cold_weights + cpu_gpu_offset,
                    NULL,
                    (uint64_t)cpu_count * sizeof(float), 0
                };
                mixed_join_ok = g_cuda_routed_moe_launch_dispatch(
                    &cold_out_tensor, gate, up, mid, &cold_down_tensor,
                    main_model_map, main_model_size, layer_index,
                    main_gate_offset, main_up_offset, main_down_offset,
                    main_gate_type, main_down_type,
                    main_gate_expert_bytes, main_gate_row_bytes,
                    main_down_expert_bytes, main_down_row_bytes,
                    expert_in_dim, expert_mid_dim, out_dim,
                    &cpu_gpu_selected_tensor, &cpu_gpu_weights_tensor, NULL,
                    cpu_count, clamp, x, 1u, NULL, NULL, NULL,
                    g133_epoch);
                if (mixed_join_ok) {
                    add_f32_u64_kernel<<<
                        (out_dim + 255u) / 256u, 256>>>(
                        (float *)out->ptr, (const float *)out->ptr,
                        device_cold_out, out_dim);
                    mixed_join_ok = cuda_ok(
                        cudaGetLastError(),
                        "G132 post-dispatch IQ2 output join");
                }
            }
            cpu_count = 0;
            cpu_lane_active = 0;
        }
        if (mixed_profile && cold_count == 0u) {
            const double cpu_join_finished = cuda_wall_sec();
            mixed_profile_sample.q1_entry_calls++;
            mixed_profile_sample.q1_selected_load_calls++;
            mixed_profile_sample.q1_prepare_calls++;
            mixed_profile_sample.q1_kernel_calls++;
            mixed_profile_sample.q1_kernel_device_calls++;
            mixed_profile_sample.q1_kernel_fenced_calls++;
            mixed_profile_sample.q1_kernel_seconds +=
                cpu_join_finished - cpu_join_started;
            mixed_profile_phase_started = cpu_join_finished;
        }
    }
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
    if (attribution) {
        (void)cuda_g130_attribution_switch(
            attribution_state, CUDA_G130_ATTRIB_MIXED_Q1_CALL);
    }
#endif
    if (!mixed_join_ok) {
        if (cpu_lane_active) cuda_g132_cpu_lane_discard_dispatch();
        if (join_begin) (void)cudaEventDestroy(join_begin);
        if (join_end) (void)cudaEventDestroy(join_end);
        g_q1_0_mixed_failures++;
        return 0;
    }
    if (join_end) {
        float join_ms = 0.0f;
        const cudaError_t end_record = cudaEventRecord(join_end, 0);
        const cudaError_t end_sync = end_record == cudaSuccess ?
            cudaEventSynchronize(join_end) : end_record;
        const cudaError_t elapsed = end_sync == cudaSuccess ?
            cudaEventElapsedTime(&join_ms, join_begin, join_end) : end_sync;
        if (elapsed == cudaSuccess) {
            g_q1_0_profile.mixed_join_calls++;
            g_q1_0_profile.mixed_join_seconds +=
                (double)join_ms / 1000.0;
        } else {
            g_q1_0_profile.timer_failures++;
            cuda_q1_0_mixed_profile_record_timer_failure();
            (void)cudaGetLastError();
        }
        (void)cudaEventDestroy(join_begin);
        (void)cudaEventDestroy(join_end);
    }
    if (recovery_trace_rank != UINT32_MAX &&
        !cuda_expert_recovery_trace_capture(
            layer_index, g_expert_recovery_trace.target_expert,
            recovery_trace_rank, recovery_trace_weight,
            recovery_trace_representation, recovery_trace_token_index,
            g_moe_tiering.call_tick, x, expert_in_dim,
            cpu_captured_input)) {
        g_q1_0_mixed_failures++;
        return 0;
    }
    int promotion_is_nonblocking = 1;
    if (q1_0_dynamic_promotion && g_g132_cpu_lane.requested) {
        /* Lane A may offer cold routes only to the bounded SSD-wrap queue.
         * Never let its current-token path fall through to synchronous pread. */
        promotion_is_nonblocking = cuda_q1_0_ssd_wrap_requested() == 1;
        if (!promotion_is_nonblocking) {
            g_g132_cpu_lane.promotion_hints_skipped += cold_count;
        }
    }
    if (q1_0_dynamic_promotion && promotion_is_nonblocking) {
        /* The current result is already queued from resident Q1_0. Admission
         * below is future-token work: exact IQ2 first enters the disjoint RAM
         * probation arena and cannot become VRAM-eligible until a later call. */
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        if (attribution) {
            (void)cuda_g130_attribution_switch(
                attribution_state,
                CUDA_G130_ATTRIB_PROMOTION_STAGING);
        }
#endif
        for (uint32_t route = 0; route < cold_count; route++) {
            (void)cuda_moe_tiering_stage_observed_quant_cold_to_2bit_ram(
                layer_index, (uint32_t)cold_selected[route],
                cold_weights[route],
                main_gate_offset, main_up_offset, main_down_offset,
                main_gate_expert_bytes, main_down_expert_bytes, 1,
                q1_gate_offset, q1_up_offset, q1_down_offset,
                q1_gate_expert_bytes, q1_down_expert_bytes);
        }
#ifndef DS4_G130_ATTRIB_COMPILED_OUT
        if (attribution) {
            (void)cuda_g130_attribution_switch(
                attribution_state,
                CUDA_G130_ATTRIB_MIXED_Q1_CALL);
        }
#endif
    }
    if (cuda_q1_0_snapshot_backing_requested()) {
        g_moe_tiering.snapshot_backing_hits += cold_count;
    }
    g_q1_0_mixed_iq2_vram += iq2_vram;
    g_q1_0_mixed_iq2_snapshot_ram += iq2_snapshot_ram;
    g_q1_0_mixed_iq2_tier_ram += iq2_tier_ram;
    g_q1_0_mixed_q1_resident += cold_count;
    g_q1_0_mixed_joins++;
    if (mixed_profile) {
        const double publish_finished = cuda_wall_sec();
        mixed_profile_sample.join_publish_calls++;
        mixed_profile_sample.join_publish_seconds +=
            publish_finished - mixed_profile_phase_started;
        cuda_q1_0_mixed_profile_record_completed(
            mixed_profile_sample,
            publish_finished - mixed_profile_call_started,
            hot_count, fallback_route_count, 1);
    }
    return 1;
}

extern "C" int ds4_gpu_routed_moe_mixed_iq1_one_tensor(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *main_model_map,
        uint64_t main_model_size,
        uint32_t layer_index,
        uint64_t main_gate_offset,
        uint64_t main_up_offset,
        uint64_t main_down_offset,
        uint32_t main_gate_type,
        uint32_t main_down_type,
        uint64_t main_gate_expert_bytes,
        uint64_t main_gate_row_bytes,
        uint64_t main_down_expert_bytes,
        uint64_t main_down_row_bytes,
        const void *iq1_model_map,
        uint64_t iq1_model_size,
        uint64_t iq1_gate_offset,
        uint64_t iq1_up_offset,
        uint64_t iq1_down_offset,
        uint32_t iq1_down_type,
        uint64_t iq1_gate_expert_bytes,
        uint64_t iq1_gate_row_bytes,
        uint64_t iq1_down_expert_bytes,
        uint64_t iq1_down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x,
        ds4_gpu_g133_epoch g133_epoch,
        ds4_gpu_spex_queue *spex_queue,
        const ds4_gpu_spex_key *spex_key) {
    g_iq1_mixed_calls++;
    const int mixed_profile = getenv("DS4_IQ1_S_PROFILE") != NULL;
    const int no_main_sync = getenv("DS4_IQ1_MIXED_NO_MAIN_SYNC") != NULL;
    const int gpu_plan_requested =
        getenv("DS4_IQ1_MIXED_GPU_PLAN") != NULL;
    const double mixed_t0 = mixed_profile ? cuda_wall_sec() : 0.0;
    const uint32_t slot_count = 6u;
    int32_t h_selected[6];
    float h_weights[6];
    if (!out || !gate || !up || !mid || !down ||
        !main_model_map || !iq1_model_map || !selected || !weights || !x ||
        n_expert != slot_count || expert_in_dim == 0 || expert_mid_dim == 0 ||
        out_dim == 0 || main_gate_type != 16u || main_down_type != 10u ||
        (iq1_down_type != 19u && iq1_down_type != 10u) ||
        selected->bytes < slot_count * sizeof(int32_t) ||
        weights->bytes < slot_count * sizeof(float)) {
        g_iq1_mixed_failures++;
        return 0;
    }
    if (cuda_g133_shared_policy_active() &&
        !cuda_moe_route_worker_drain_completed("iq1-mixed-entry")) {
        g_iq1_mixed_failures++;
        return 0;
    }
    uint32_t cold_slot = 0;
    float cold_weight = 0.0f;
    int32_t cold_expert = -1;
    int32_t h_hot_selected[5];
    float h_hot_weights[5];
    uint32_t hot_i = 0;
    if (!gpu_plan_requested) {
        if (!cuda_ok(cudaMemcpy(h_selected, selected->ptr,
                                sizeof(h_selected), cudaMemcpyDeviceToHost),
                     "iq1 mixed selected D2H") ||
            !cuda_ok(cudaMemcpy(h_weights, weights->ptr,
                                sizeof(h_weights), cudaMemcpyDeviceToHost),
                     "iq1 mixed weights D2H")) {
            g_iq1_mixed_failures++;
            return 0;
        }
        cold_weight = h_weights[0];
        for (uint32_t i = 1; i < slot_count; i++) {
            if (h_weights[i] < cold_weight) {
                cold_weight = h_weights[i];
                cold_slot = i;
            }
        }
        cold_expert = h_selected[cold_slot];
        for (uint32_t i = 0; i < slot_count; i++) {
            if (i == cold_slot) continue;
            h_hot_selected[hot_i] = h_selected[i];
            h_hot_weights[hot_i] = h_weights[i];
            hot_i++;
        }
    } else if (!cuda_iq1_mixed_gpu_plan_prepare()) {
        g_iq1_mixed_gpu_plan.failures++;
        g_iq1_mixed_failures++;
        return 0;
    }
    const double mixed_router_t = mixed_profile ? cuda_wall_sec() : 0.0;

    const uint32_t hot_count = slot_count - 1u;
    if (!gpu_plan_requested &&
        (cold_expert < 0 || cold_expert >= 256 || hot_i != hot_count)) {
        g_iq1_mixed_failures++;
        return 0;
    }

    const uint32_t xq_blocks = expert_in_dim / CUDA_QK_K;
    const uint64_t out_bytes = (uint64_t)out_dim * sizeof(float);
    const uint64_t xq_bytes = (uint64_t)xq_blocks * sizeof(cuda_block_q8_K);
    const uint64_t cold_down_bytes = std::max(out_bytes, xq_bytes);
    const uint64_t off_hot_selected = 0;
    const uint64_t off_hot_weights =
        cuda_round_up(off_hot_selected + hot_count * sizeof(int32_t), 4u);
    const uint64_t off_cold_selected =
        cuda_round_up(off_hot_weights + hot_count * sizeof(float), 4u);
    const uint64_t off_cold_weight =
        cuda_round_up(off_cold_selected + sizeof(int32_t), 4u);
    const uint64_t off_cold_out =
        cuda_round_up(off_cold_weight + sizeof(float), 256u);
    const uint64_t off_cold_down = cuda_round_up(off_cold_out + out_bytes, 256u);
    if (out_bytes == 0 || cold_down_bytes > UINT64_MAX - off_cold_down) {
        g_iq1_mixed_failures++;
        return 0;
    }
    const uint64_t scratch_bytes = off_cold_down + cold_down_bytes;
    if (!cuda_iq1_mixed_scratch_ensure(scratch_bytes)) {
        g_iq1_mixed_failures++;
        return 0;
    }
    char *scratch = (char *)g_iq1_mixed_scratch;
    int32_t *d_hot_selected = (int32_t *)(scratch + off_hot_selected);
    float *d_hot_weights = (float *)(scratch + off_hot_weights);
    int32_t *d_cold_selected = (int32_t *)(scratch + off_cold_selected);
    float *d_cold_weight = (float *)(scratch + off_cold_weight);
    float *d_cold_out = (float *)(scratch + off_cold_out);
    float *d_cold_down = (float *)(scratch + off_cold_down);

    uint32_t gpu_plan_sequence = 0;
    if (gpu_plan_requested) {
        gpu_plan_sequence = ++g_iq1_mixed_gpu_plan.sequence;
        if (gpu_plan_sequence == 0u) {
            gpu_plan_sequence = ++g_iq1_mixed_gpu_plan.sequence;
        }
        iq1_mixed_cold_one_plan_kernel<<<1, 1>>>(
            d_hot_selected, d_hot_weights,
            d_cold_selected, d_cold_weight,
            g_iq1_mixed_gpu_plan.device_request,
            (const int32_t *)selected->ptr,
            (const float *)weights->ptr,
            layer_index, gpu_plan_sequence);
        if (!cuda_ok(cudaGetLastError(), "iq1 mixed GPU planner launch")) {
            g_iq1_mixed_gpu_plan.failures++;
            g_iq1_mixed_failures++;
            return 0;
        }
    } else {
        if (!cuda_ok(cudaMemcpy(d_hot_selected, h_hot_selected,
                                sizeof(h_hot_selected), cudaMemcpyHostToDevice),
                     "iq1 mixed hot selected H2D") ||
            !cuda_ok(cudaMemcpy(d_hot_weights, h_hot_weights,
                                sizeof(h_hot_weights), cudaMemcpyHostToDevice),
                     "iq1 mixed hot weights H2D") ||
            !cuda_ok(cudaMemcpy(d_cold_selected, &cold_expert,
                                sizeof(cold_expert), cudaMemcpyHostToDevice),
                     "iq1 mixed cold selected H2D") ||
            !cuda_ok(cudaMemcpy(d_cold_weight, &cold_weight,
                                sizeof(cold_weight), cudaMemcpyHostToDevice),
                     "iq1 mixed cold weight H2D")) {
            g_iq1_mixed_failures++;
            return 0;
        }
    }
    const double mixed_metadata_t = mixed_profile ? cuda_wall_sec() : 0.0;

    ds4_gpu_tensor hot_selected = { d_hot_selected, NULL, hot_count * sizeof(int32_t), 0 };
    ds4_gpu_tensor hot_weights = { d_hot_weights, NULL, hot_count * sizeof(float), 0 };
    int ok = g_cuda_routed_moe_launch_dispatch(out, gate, up, mid, down,
                               main_model_map, main_model_size, layer_index,
                               main_gate_offset, main_up_offset, main_down_offset,
                               main_gate_type, main_down_type,
                               main_gate_expert_bytes, main_gate_row_bytes,
                               main_down_expert_bytes, main_down_row_bytes,
                               expert_in_dim, expert_mid_dim, out_dim,
                               &hot_selected, &hot_weights, NULL, hot_count, clamp,
                               x, 1u, NULL, NULL, NULL, g133_epoch);
    if (!ok) {
        g_iq1_mixed_failures++;
        return 0;
    }
    const double mixed_main_submit_t = mixed_profile ? cuda_wall_sec() : 0.0;
    double gpu_plan_wait_seconds = 0.0;
    if (gpu_plan_requested) {
        const double wait_started = cuda_wall_sec();
        const double wait_deadline = wait_started + 5.0;
        while (*(volatile uint32_t *)&g_iq1_mixed_gpu_plan.host_request->sequence !=
               gpu_plan_sequence) {
            if (cuda_wall_sec() >= wait_deadline) {
                fprintf(stderr,
                        "ds4: IQ1 mixed GPU planner timed out seq=%u layer=%u\n",
                        gpu_plan_sequence, layer_index);
                g_iq1_mixed_gpu_plan.failures++;
                g_iq1_mixed_failures++;
                return 0;
            }
#ifdef _WIN32
            (void)SwitchToThread();
#else
            usleep(0);
#endif
        }
#ifdef _WIN32
        MemoryBarrier();
#else
        __sync_synchronize();
#endif
        gpu_plan_wait_seconds = cuda_wall_sec() - wait_started;
        g_iq1_mixed_gpu_plan.wait_seconds += gpu_plan_wait_seconds;
        const cuda_iq1_mixed_gpu_plan_request *request =
            g_iq1_mixed_gpu_plan.host_request;
        cold_slot = request->cold_slot;
        cold_expert = request->cold_expert;
        cold_weight = request->cold_weight;
        if (request->layer_index != layer_index || cold_slot >= slot_count ||
            cold_expert < 0 || cold_expert >= 256) {
            fprintf(stderr,
                    "ds4: IQ1 mixed GPU planner returned invalid route "
                    "seq=%u layer=%u request_layer=%u slot=%u expert=%d\n",
                    gpu_plan_sequence, layer_index, request->layer_index,
                    cold_slot, (int)cold_expert);
            g_iq1_mixed_gpu_plan.failures++;
            g_iq1_mixed_failures++;
            return 0;
        }
        g_iq1_mixed_gpu_plan.calls++;

        /* The hot kernels are already queued on stream 0. Publish the exact
         * host-selected cold id so selected-load can stage IQ1_S on the
         * nonblocking upload stream without repeating a router D2H. */
        g_iq1_mixed_host_selected.model_map = iq1_model_map;
        g_iq1_mixed_host_selected.selected_ptr = d_cold_selected;
        g_iq1_mixed_host_selected.gate_offset = iq1_gate_offset;
        g_iq1_mixed_host_selected.up_offset = iq1_up_offset;
        g_iq1_mixed_host_selected.down_offset = iq1_down_offset;
        g_iq1_mixed_host_selected.gate_expert_bytes =
            iq1_gate_expert_bytes;
        g_iq1_mixed_host_selected.down_expert_bytes =
            iq1_down_expert_bytes;
        g_iq1_mixed_host_selected.expert = cold_expert;
        g_iq1_mixed_host_selected.weight = cold_weight;
        g_iq1_mixed_host_selected.valid = 1;
    }
    g_iq1_mixed_last_layer = layer_index;
    g_iq1_mixed_last_slot = cold_slot;
    g_iq1_mixed_last_expert = cold_expert;
    if (!no_main_sync && !gpu_plan_requested &&
        !cuda_ok(cudaStreamSynchronize(0), "iq1 mixed main preserve sync")) {
        g_iq1_mixed_failures++;
        return 0;
    }
    const double mixed_main_sync_t = mixed_profile ? cuda_wall_sec() : 0.0;
    if (!cuda_iq1_mixed_debug_output("hot-main", out, out_dim)) {
        g_iq1_mixed_failures++;
        return 0;
    }

    ds4_gpu_tensor cold_selected = { d_cold_selected, NULL, sizeof(int32_t), 0 };
    ds4_gpu_tensor cold_weight_tensor = { d_cold_weight, NULL, sizeof(float), 0 };
    ds4_gpu_tensor cold_out = { d_cold_out, NULL, out_bytes, 0 };
    ds4_gpu_tensor cold_down = { d_cold_down, NULL, cold_down_bytes, 0 };
    ok = g_cuda_routed_moe_launch_dispatch(&cold_out, gate, up, mid, &cold_down,
                           iq1_model_map, iq1_model_size, layer_index,
                           iq1_gate_offset, iq1_up_offset, iq1_down_offset,
                           19u, iq1_down_type,
                           iq1_gate_expert_bytes, iq1_gate_row_bytes,
                           iq1_down_expert_bytes, iq1_down_row_bytes,
                           expert_in_dim, expert_mid_dim, out_dim,
                           &cold_selected, &cold_weight_tensor, NULL, 1u, clamp,
                           x, 1u, NULL, NULL, NULL, g133_epoch);
    if (!ok) {
        g_iq1_mixed_failures++;
        return 0;
    }
    const double mixed_cold_submit_t = mixed_profile ? cuda_wall_sec() : 0.0;

    add_f32_u64_kernel<<<(out_dim + 255u) / 256u, 256>>>(
        (float *)out->ptr, (const float *)out->ptr, d_cold_out, out_dim);
    if (!cuda_ok(cudaGetLastError(), "iq1 mixed cold add launch")) {
        g_iq1_mixed_failures++;
        return 0;
    }
    /* Promotion is speculative work for a future token. The current IQ1_S
     * result and join are already queued, so a staging failure must be
     * reported by promotion telemetry without turning a valid MoE result
     * into a partial failure that a caller could replay. */
    if (cuda_g133_shared_policy_active() &&
        !cuda_moe_route_worker_drain_completed("iq1-mixed-policy")) {
        g_iq1_mixed_failures++;
        return 0;
    }
    (void)cuda_moe_tiering_stage_iq1_cold_to_2bit_ram(
            layer_index, (uint32_t)cold_expert, cold_weight,
            main_gate_offset, main_up_offset, main_down_offset,
            main_gate_expert_bytes, main_down_expert_bytes, g133_epoch);
    const double mixed_join_t = mixed_profile ? cuda_wall_sec() : 0.0;
    if (!cuda_iq1_mixed_debug_output("joined", out, out_dim)) {
        g_iq1_mixed_failures++;
        return 0;
    }
    g_iq1_mixed_hot_main += hot_count;
    g_iq1_mixed_cold_iq1++;
    g_iq1_mixed_primary_cold_avoided++;
    g_iq1_mixed_joins++;
    if (mixed_profile) {
        g_iq1_mixed_profile_calls++;
        g_iq1_mixed_profile_router_d2h_seconds += mixed_router_t - mixed_t0;
        g_iq1_mixed_profile_metadata_h2d_seconds +=
            mixed_metadata_t - mixed_router_t;
        g_iq1_mixed_profile_main_submit_seconds +=
            mixed_main_submit_t - mixed_metadata_t;
        double main_sync_seconds =
            mixed_main_sync_t - mixed_main_submit_t - gpu_plan_wait_seconds;
        if (main_sync_seconds < 0.0) main_sync_seconds = 0.0;
        g_iq1_mixed_profile_main_sync_seconds += main_sync_seconds;
        g_iq1_mixed_profile_cold_submit_seconds +=
            mixed_cold_submit_t - mixed_main_sync_t;
        g_iq1_mixed_profile_join_submit_seconds +=
            mixed_join_t - mixed_cold_submit_t;
    }
    return 1;
}

extern "C" int ds4_gpu_routed_moe_batch_tensor(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *down, const void *model_map, uint64_t model_size, uint32_t layer_index, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset, uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, const ds4_gpu_tensor *probs, uint32_t n_expert, float clamp, const ds4_gpu_tensor *x, uint32_t n_tokens, bool *mid_is_f16) {
    if (mid_is_f16) *mid_is_f16 = false;
    return g_cuda_routed_moe_launch_dispatch(out, gate, up, mid, down, model_map, model_size,
                             layer_index,
                             gate_offset, up_offset, down_offset,
                             gate_type, down_type,
                             gate_expert_bytes, gate_row_bytes,
                             down_expert_bytes, down_row_bytes,
                             expert_in_dim, expert_mid_dim, out_dim,
                             selected, weights, probs, n_expert, clamp, x, n_tokens,
                             NULL, NULL, NULL, ds4_gpu_g133_epoch{});
}
extern "C" int ds4_gpu_hc_split_sinkhorn_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *mix, const void *model_map, uint64_t model_size, uint64_t scale_offset, uint64_t base_offset, uint32_t n_hc, uint32_t sinkhorn_iters, float eps) {
    if (!out || !mix || !model_map || n_hc != 4) return 0;
    const uint64_t mix_bytes = 24ull * sizeof(float);
    if (scale_offset > model_size || model_size - scale_offset < 3ull * sizeof(float) ||
        base_offset > model_size || model_size - base_offset < mix_bytes ||
        mix->bytes < mix_bytes || out->bytes < mix_bytes) return 0;
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, 3ull * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, mix_bytes, "hc_base");
    if (!scale || !base) return 0;
    uint32_t n_rows = (uint32_t)(mix->bytes / mix_bytes);
    if (out->bytes / mix_bytes < n_rows) n_rows = (uint32_t)(out->bytes / mix_bytes);
    hc_split_sinkhorn_kernel<<<(n_rows + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)mix->ptr,
        scale,
        base,
        n_rows, sinkhorn_iters, eps);
    return cuda_ok(cudaGetLastError(), "hc_split_sinkhorn launch");
}
extern "C" int ds4_gpu_hc_weighted_sum_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *weights, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !residual_hc || !weights || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out->bytes / ((uint64_t)n_embd * sizeof(float)));
    hc_weighted_sum_kernel<<<((uint64_t)n_embd * n_tokens + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)residual_hc->ptr, (const float *)weights->ptr,
        n_embd, n_hc, n_tokens, n_hc);
    return cuda_ok(cudaGetLastError(), "hc_weighted_sum launch");
}
extern "C" int ds4_gpu_hc_weighted_sum_split_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out->bytes / ((uint64_t)n_embd * sizeof(float)));
    uint32_t stride = (uint32_t)(2u * n_hc + n_hc * n_hc);
    hc_weighted_sum_kernel<<<((uint64_t)n_embd * n_tokens + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)residual_hc->ptr, (const float *)split->ptr,
        n_embd, n_hc, n_tokens, stride);
    return cuda_ok(cudaGetLastError(), "hc_weighted_sum_split launch");
}
extern "C" int ds4_gpu_hc_split_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!out || !split || !mix || !residual_hc || !model_map ||
        n_embd == 0 || n_hc != 4) {
        return 0;
    }
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    if (out->bytes < out_row_bytes || out->bytes % out_row_bytes != 0 ||
        scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
        base_offset > model_size || mix_bytes > model_size - base_offset) {
        return 0;
    }
    uint64_t n_rows = out->bytes / out_row_bytes;
    if (mix->bytes < n_rows * mix_bytes ||
        split->bytes < n_rows * mix_bytes ||
        residual_hc->bytes < n_rows * residual_row_bytes) {
        return 0;
    }
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, 3ull * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, mix_bytes, "hc_base");
    if (!scale || !base) return 0;
    hc_split_weighted_sum_fused_kernel<<<(uint32_t)n_rows, 256>>>(
            (float *)out->ptr,
            (float *)split->ptr,
            (const float *)mix->ptr,
            (const float *)residual_hc->ptr,
            scale,
            base,
            n_embd, n_hc, (uint32_t)n_rows, sinkhorn_iters, eps);
    return cuda_ok(cudaGetLastError(), "hc split weighted sum launch");
}
extern "C" int ds4_gpu_hc_split_weighted_sum_norm_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint64_t                norm_weight_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps,
        float                   norm_eps) {
    if (getenv("DS4_CUDA_DISABLE_HC_SPLIT_NORM_FUSED") == NULL) {
        if (!out || !norm_out || !split || !mix || !residual_hc || !model_map ||
            n_embd == 0 || n_hc != 4) {
            return 0;
        }
        const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
        const uint64_t mix_bytes = mix_hc * sizeof(float);
        const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
        if (out->bytes < out_row_bytes || out->bytes % out_row_bytes != 0 ||
            norm_out->bytes < out->bytes ||
            scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size ||
            (uint64_t)n_embd * sizeof(float) > model_size - norm_weight_offset) {
            return 0;
        }
        uint64_t n_rows = out->bytes / out_row_bytes;
        if (n_rows == 1) {
            if (mix->bytes < n_rows * mix_bytes ||
                split->bytes < n_rows * mix_bytes ||
                residual_hc->bytes < n_rows * residual_row_bytes) {
                return 0;
            }
            const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset,
                    3ull * sizeof(float), "hc_scale");
            const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset,
                    mix_bytes, "hc_base");
            const float *norm_w = (const float *)cuda_model_range_ptr(model_map, norm_weight_offset,
                    (uint64_t)n_embd * sizeof(float), "hc_norm_weight");
            if (!scale || !base || !norm_w) return 0;
            hc_split_weighted_sum_norm_fused_kernel<<<(uint32_t)n_rows, 256>>>(
                    (float *)out->ptr,
                    (float *)norm_out->ptr,
                    (float *)split->ptr,
                    (const float *)mix->ptr,
                    (const float *)residual_hc->ptr,
                    scale,
                    base,
                    norm_w,
                    n_embd, n_hc, (uint32_t)n_rows, sinkhorn_iters, eps, norm_eps);
            return cuda_ok(cudaGetLastError(), "hc split weighted sum norm launch");
        }
    }
    return ds4_gpu_hc_split_weighted_sum_tensor(out, split, mix, residual_hc,
                                                  model_map, model_size,
                                                  scale_offset, base_offset,
                                                  n_embd, n_hc,
                                                  sinkhorn_iters, eps) &&
           ds4_gpu_rms_norm_weight_tensor(norm_out, out, model_map, model_size,
                                            norm_weight_offset, n_embd, norm_eps);
}
extern "C" int ds4_gpu_output_hc_weights_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *pre,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_hc,
        float                   eps) {
    if (!out || !pre || !model_map || n_hc == 0) return 0;
    const uint64_t row_bytes = (uint64_t)n_hc * sizeof(float);
    if (row_bytes == 0 || out->bytes < row_bytes || out->bytes % row_bytes != 0 ||
        pre->bytes < out->bytes ||
        scale_offset > model_size || sizeof(float) > model_size - scale_offset ||
        base_offset > model_size || row_bytes > model_size - base_offset) {
        return 0;
    }
    const uint64_t n_tokens = out->bytes / row_bytes;
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, sizeof(float), "output_hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, row_bytes, "output_hc_base");
    if (!scale || !base) return 0;
    uint64_t n = n_tokens * n_hc;
    output_hc_weights_kernel<<<(n + 255) / 256, 256>>>(
            (float *)out->ptr,
            (const float *)pre->ptr,
            scale,
            base,
            n_hc,
            (uint32_t)n_tokens,
            eps);
    return cuda_ok(cudaGetLastError(), "output hc weights launch");
}
extern "C" int ds4_gpu_hc_expand_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *post, const ds4_gpu_tensor *comb, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !residual_hc || !post || !comb || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    (const float *)post->ptr,
                                                    (const float *)comb->ptr,
                                                    n_embd, n_hc, n_tokens,
                                                    n_hc, n_hc * n_hc, 0);
    return cuda_ok(cudaGetLastError(), "hc_expand launch");
}
extern "C" int ds4_gpu_hc_expand_split_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    base + n_hc,
                                                    base + 2u * n_hc,
                                                    n_embd, n_hc, n_tokens,
                                                    mix_hc, mix_hc, 0);
    return cuda_ok(cudaGetLastError(), "hc_expand_split launch");
}
extern "C" int ds4_gpu_hc_expand_add_split_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *block_add, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !block_add || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_add->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    base + n_hc,
                                                    base + 2u * n_hc,
                                                    n_embd, n_hc, n_tokens,
                                                    mix_hc, mix_hc, 1);
    return cuda_ok(cudaGetLastError(), "hc_expand_add_split launch");
}
extern "C" int ds4_gpu_shared_down_hc_expand_q8_0_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *shared_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *shared_mid,
        const ds4_gpu_tensor *routed_out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (getenv("DS4_CUDA_DISABLE_Q8_HC_EXPAND_FUSED") == NULL) {
        return cuda_matmul_q8_0_hc_expand_tensor_labeled(out_hc, shared_out,
                                                        model_map, model_size,
                                                        weight_offset,
                                                        in_dim, out_dim,
                                                        shared_mid,
                                                        routed_out,
                                                        residual_hc,
                                                        split,
                                                        n_embd, n_hc,
                                                        "shared_down_hc_expand");
    }
    return ds4_gpu_matmul_q8_0_tensor(shared_out, model_map, model_size,
                                        weight_offset, in_dim, out_dim,
                                        shared_mid, 1) &&
           ds4_gpu_hc_expand_add_split_tensor(out_hc, shared_out, routed_out,
                                                residual_hc, split, n_embd, n_hc);
}

extern "C" int ds4_gpu_matmul_q8_0_hc_expand_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *block_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
